-- 1.0.51：移除旧知识检索主链；AI 使用常驻/专项分段提示词。
AI_SEG_PREFIX = "seg_"
_AI_SEG_CACHE = {}

-- 1.0.55：常驻只有 seg_core；cmd/build/mcp 由 LOAD_SUB_PROMPT/真实工具标记触发并在当前任务中保持。
AI_SEG_IDS = {
    "core","cmd","build","mcp","review"
}

function ai_seg_filename(name)
    name=tostring(name or "")
    return AI_SEG_PREFIX .. name .. ".txt"
end
function ai_seg_path(name)
    local ok,d=pcall(game.dataDir)
    if not ok or type(d)~="string" or d=="" then return nil end
    return d .. "/" .. ai_seg_filename(name)
end
function ai_seg_id_from_load_name(name)
    local n=lower(trim(name or "")):gsub("%s+","")
    local aliases={
      ["cmd"]="cmd",["指令"]="cmd",["指令agent"]="cmd",["指令工具agent"]="cmd",["instruction"]="cmd",
      ["build"]="build",["建筑"]="build",["建筑agent"]="build",["建筑模式agent"]="build",
      ["mcp"]="mcp",["mcpagent"]="mcp",["mcp插件修改"]="mcp",["远程修改"]="mcp",
      ["review"]="review",["举报"]="review",["举报审查"]="review",["审查"]="review"
    }
    local id=aliases[n]
    if id then return id end
    for _,k in ipairs(AI_SEG_IDS) do
        if n==lower(k) then return k end
    end
    return nil
end
function ai_seg_canonical(name)
    return ai_seg_id_from_load_name(name) or ""
end
function ai_seg_load(name, force)
    local id=ai_seg_canonical(name)
    if id=="" then return "" end
    if (not force) and _AI_SEG_CACHE[id] ~= nil then return _AI_SEG_CACHE[id] end
    local p=ai_seg_path(id)
    local txt=""
    if p then
        local ok,v=pcall(util.read_file,p)
        if ok and type(v)=="string" then txt=v end
    end
    _AI_SEG_CACHE[id]=txt
    return txt
end
function ai_seg_status()
    local lines={}
    local d=""; pcall(function() d=tostring(game.dataDir() or "") end)
    lines[#lines+1]="数据目录 "..d.."/"
    for _,id in ipairs(AI_SEG_IDS) do
        local p=ai_seg_path(id); local ok=false; local n=0
        if p then local r,v=pcall(util.read_file,p); ok=r and type(v)=="string" and #v>10; n=ok and #v or 0 end
        lines[#lines+1]=ai_seg_filename(id).." → "..(ok and ("已存在("..n.."字)") or "缺失")
    end
    return table.concat(lines,"\n")
end

-- 仅核心提示词常驻；专项提示词必须通过 [LOAD_SUB_PROMPT] 或真实工具调用自动加入当前任务 context。
function build_ai_system(q,admin)
    local core=ai_seg_load("core",true)
    if trim(core)=="" then
        return "【严重错误】seg_core.txt 缺失，当前没有常驻 AI 核心提示词。", {"core"}
    end
    local extra="\n\n【多功能插件｜常驻执行规则】\n"..
        "1. 普通玩家：涉及‘白天/晚上/天气/下雨/停雨/晴天/雷暴’时，按原有规则自行走规定的时间/天气投票流程；不要因为请求简单就绕过投票。\n"..
        "2. 管理员：普通的‘调白天/改成晚上/切天气’属于直接执行意图，不要擅自发起投票；只有用户明确说‘发起投票/投票决定/让大家投票’时才使用 [VOTE]。若只说‘投票一下’之类而没有具体事项，先追问投什么。\n"..
        "3. 工具结果必须来自真实执行：查询在线玩家优先取实时服务器列表；查日志必须返回实际匹配到的多条记录（有多少返回多少，受安全上限限制），不得人为缩成一条；工具失败不得伪装成功。\n"..
        "4. 常驻核心属于本插件自己的‘多功能插件’规则，不在提示词中添加第三方品牌、版权或平台署名。"
    return "【多功能插件｜常驻核心提示词】\n"..core..extra, {"core"}
end


function _maybe_backup(q)
    local s = tostring(q or "")
    return s:find("备份", 1, true) ~= nil or s:find("打包", 1, true) ~= nil
end



_MODS = {}
_MOD_LOADER = (type(loadstring) == "function") and loadstring or ((type(load) == "function") and load or nil)

function mod_dir()
    if _MOD_DIR ~= nil then return _MOD_DIR end
    local ok, d = pcall(game.dataDir)
    _MOD_DIR = (ok and type(d) == "string" and d ~= "") and d or ""
    return _MOD_DIR
end

function mod_path(name)
    local d = mod_dir()
    if d == "" then return nil end
    return d .. "/mod_" .. tostring(name) .. ".lua"
end

function require_mod(name)
    name = tostring(name or "")
    if _MODS[name] ~= nil then return _MODS[name] or nil end
    if not _MOD_LOADER then _MODS[name] = false; return nil end
    local p = mod_path(name)
    if not p then _MODS[name] = false; return nil end
    local ok, src = pcall(util.read_file, p)
    if not ok or type(src) ~= "string" or #src < 10 then _MODS[name] = false; return nil end
    local f, cerr = _MOD_LOADER(src, "@mod_" .. name)
    if not f then _MODS[name] = false; return nil end
    _MODS[name] = {}
    local ok2, res = pcall(f)
    if ok2 and type(res) == "table" then _MODS[name] = res else _MODS[name] = false end
    return _MODS[name] or nil
end

function mod_missing_msg(name)
