function cmd_mod_status(name)
    local lines = {}
    lines[#lines + 1] = "加载器=" .. (_MOD_LOADER and "可用" or "★不可用（Lua 没有 load/loadstring）")
    lines[#lines + 1] = "模块目录=" .. tostring(mod_dir()) .. "/"
    local list = {{"backup", 14}, {"structure", 15}}
    for _, item in ipairs(list) do
        local mn = item[1]
        local p = mod_path(mn)
        local exists, sz = false, 0
        if p then
            local ok, s = pcall(util.read_file, p)
            if ok and type(s) == "string" then exists, sz = true, #s end
        end
        local st = (_MODS[mn] == nil) and "未加载" or (_MODS[mn] and ("已加载(" .. item[2] .. "个函数)") or "★加载失败")
        lines[#lines + 1] = string.format("mod_%-10s 文件=%s%s  状态=%s",
            mn, exists and "有" or "★缺", exists and ("(" .. sz .. "字节)") or "", st)
    end
    pcall(send, name, "§7[模块状态]\n" .. table.concat(lines, "\n"))
    return true
end

