-- 多功能插件｜自有常驻核心与专项按需加载。购买目录与出售目录保持独立。
BEIJING_OFFSET = 8 * 3600

function now_utc_ts()
    local ok, t = pcall(util.timestamp)
    if ok and tonumber(t) then return math.floor(tonumber(t)) end
    return os.time()
end

function beijing_fmt(utc_ts, fmt)
    local ts = tonumber(utc_ts)
    if ts == nil then return "-" end
    return os.date(fmt or "%Y-%m-%d %H:%M:%S", math.floor(ts) + BEIJING_OFFSET)
end

function beijing_fmt_short(utc_ts)
    return beijing_fmt(utc_ts, "%Y-%m-%d %H:%M")
end

function beijing_now()
    return beijing_fmt(now_utc_ts())
end

function current_real_time()
    -- util.timestamp() 返回的是 Unix 时间戳；统一按北京时间（UTC+8）展示。
    -- 不再优先直接返回 util.now()，避免把 UTC 时间原样显示出来而慢 8 小时。
    local ok, v = pcall(beijing_now)
    if ok and v and v ~= "-" and tostring(v) ~= "" then return tostring(v) end
    local ok0, v0 = pcall(util.now)
    if ok0 and v0 and tostring(v0) ~= "" then return tostring(v0) end
    return tostring(now_utc_ts())
end
