function get_info(name)
    local ok, info = pcall(player.get, name)
    if not ok or type(info) ~= "table" or not info.name then return nil end
    return info
end

function identity(name)
    local info = get_info(name) or {name = name, xuid = "", unique_id = ""}
    local xuid = trim(info.xuid)
    local uid = trim(info.unique_id)
    local nm = trim(name)
    local key = nm ~= "" and nm or (xuid ~= "" and xuid or uid)
    return key, info
end

function migrate_player_keys()
    local d = load_data()
    if type(d) ~= "table" or type(d.players) ~= "table" then return 0 end
    local moved = 0
    local by_name = {}
    for k, rec in pairs(d.players) do
        if type(rec) == "table" and rec.name and rec.name ~= "" then
            by_name[rec.name] = by_name[rec.name] or {}
            table.insert(by_name[rec.name], {k = k, rec = rec})
        end
    end
    for nm, list in pairs(by_name) do
        if #list > 1 then
            local base = d.players[nm]
            if type(base) ~= "table" then base = list[1].rec end
            base.waypoints = base.waypoints or {}
            for _, item in ipairs(list) do
                local r = item.rec
                if r ~= base and type(r.waypoints) == "table" then
                    for slot, w in pairs(r.waypoints) do
                        if type(w) == "table" then
                            local cur = base.waypoints[slot]
                            local cur_bad = (type(cur) ~= "table") or
                                            (tonumber(cur.x) == 0 and tonumber(cur.z) == 0)
                            if cur_bad and not (tonumber(w.x) == 0 and tonumber(w.z) == 0) then
                                base.waypoints[slot] = w
                            end
                        end
                    end
                end
                if r ~= base and type(r.death_history) == "table" then
                    base.death_history = base.death_history or {}
                    for _, h in ipairs(r.death_history) do
                        table.insert(base.death_history, h)
                    end
                    while #base.death_history > 10 do table.remove(base.death_history, 1) end
                end
                if r ~= base and type(r.death) == "table" then
                    local a = tonumber(base.death and base.death.saved_ts) or 0
                    local b = tonumber(r.death.saved_ts) or 0
                    if b > a then base.death = r.death end
                end
                local ca = tonumber(base.death_count) or 0
                local cb = tonumber(r.death_count) or 0
                if cb > ca then base.death_count = cb end
                if item.k ~= nm then
                    d.players[item.k] = nil
                    moved = moved + 1
                end
            end
            base.name = nm
            d.players[nm] = base
        end
    end
    if moved > 0 then
        save_data(d)
        log_event("MIGRATE", "玩家记录键合并：" .. tostring(moved) .. " 条")
    end
    return moved
end

is_admin = function(name)
    if name == SUPERUSER then return true end
    local ok, r = pcall(player.isOP, name)
    if ok and r ~= nil then return r == true end
    local info = get_info(name)
    if info and info.is_op ~= nil then return info.is_op == true end
    return false
end

function check_tag(name, tag)
    if name == "" or tag == "" then return false end
    local n = string.gsub(name, '"', '\\"')
    local t = string.gsub(tag, '"', '\\"')
    local ok, hit = pcall(game.isCmdSuccess, 'testfor @a[name="' .. n .. '",tag="' .. t .. '"]')
    return ok and hit == true
end


function init_scoreboard()
    local d=load_data()
    local cfg=file_load(SCOREBOARD_CONFIG_FILE,{})
    local board=trim(cfg.name or d.scoreboard_name or "")
    if board~="" then
        d.scoreboard_name=board; d.scoreboard_created=true; save_data(d)
        pcall(game.isCmdSuccess,"scoreboard objectives add "..board.." dummy")
    end
end

function normalize_dimension(value)
    local v = lower(trim(value))
    if v == "1" or string.find(v, "nether", 1, true) or v == "下界" or v == "地狱" then return "nether" end
    if v == "2" or string.find(v, "the_end", 1, true) or v == "end" or v == "末地" then return "the_end" end
    if v == "0" or string.find(v, "overworld", 1, true) or v == "主世界" or v == "主城" then return "overworld" end
    return nil
end

function dimension_display(value)
    local d = normalize_dimension(value)
    if d == "nether" then return "下界" end
    if d == "the_end" then return "末地" end
    return "主世界"
end

function integer_coord(value)
    local n = tonumber(value) or 0
    return tostring(math.floor(n))
end

function detect_dimension(name)
    local info = get_info(name)
    local tracked = info and normalize_dimension(info.dimension)
    if tracked then return tracked end
    return "overworld"
end


function context_for(name, question)
    local admin=is_admin(name)
    local s="当前提问者="..tostring(name).."\n当前权限="..(admin and "管理权限" or "普通玩家")
    return s,admin
end

function get_score(name, board)
    local ok, score = pcall(game.getScore, board, name)
    if ok then return name .. " 在记分板 " .. board .. " 的分数是 " .. tostring(score) end
    return "查询分数失败"
end

function _extract_player_names(v, out, seen)
    out, seen = out or {}, seen or {}
    if type(v)=="table" then
        local nm=v.name or v.Name or v.playerName or v.username
        if nm~=nil then
            nm=trim(tostring(nm))
            if nm~="" and not seen[nm] then seen[nm]=true; out[#out+1]=nm end
        end
        for _,x in pairs(v) do
            if type(x)=="table" then _extract_player_names(x,out,seen) end
        end
    elseif type(v)=="string" then
        local x=trim(v)
        if x~="" and not x:find("commands.players",1,true) and not x:find("success",1,true) and not seen[x] then
            out[#out+1]=x; seen[x]=true
        end
    end
    return out
end

function online_players()
    local names,seen={},{}
    -- 先用服务器实时 list 回执，避免 player.list() 缓存滞后。
    local ok_l, resp = pcall(game.sendCommandWithResp, "list", "ai", 10)
    if ok_l then
        local got=_extract_player_names(resp,names,seen)
        if #got>0 then return got end
    end
    -- 再用实时 selector；只接受带 name 字段的玩家对象，避免把其它返回字段当玩家名。
    local ok_t, target = pcall(game.getTarget, "@a")
    if ok_t and type(target)=="table" then
        names,seen={},{}
        for _,p in ipairs(target) do
            if type(p)=="table" then
                local nm=trim(tostring(p.name or p.Name or ""))
                if nm~="" and not seen[nm] then seen[nm]=true; names[#names+1]=nm end
            end
        end
        if #names>0 then return names end
    end
    local ok,list=pcall(player.list)
    if ok and type(list)=="table" then
        names,seen={},{}
        for _,p in ipairs(list) do
            local nm=type(p)=="table" and trim(tostring(p.name or "")) or ""
            if nm~="" and not seen[nm] then seen[nm]=true; names[#names+1]=nm end
        end
        if #names>0 then return names end
    end
    return {}
end

function online_names_from_list()
    local ok,list=pcall(player.list)
    if not ok or type(list)~='table' then return nil end
    local names={}
    for _,info in ipairs(list) do
        if info and info.name and tostring(info.name)~='' then table.insert(names,tostring(info.name)) end
    end
    return names
end

function list_players()
    local names = online_players()
    if not names then return "无法读取在线玩家列表" end
    return #names == 0 and "当前没有在线玩家" or "在线玩家(" .. #names .. "人)：" .. table.concat(names, ", ")
end

