    if type(d) ~= "table" then d = {} end
    d.players = type(d.players) == "table" and d.players or {}
    return d
end
function coord_soul_state_player(db, name, legacy_record)
    local k = tostring(name or "")
    local p = type(db.players[k]) == "table" and db.players[k] or {}
    db.players[k] = p
    if type(p.coordinate_tp) ~= "table" then
        p.coordinate_tp = (legacy_record and type(legacy_record.coordinate_tp) == "table") and legacy_record.coordinate_tp or {}
    end
    if type(p.signin) ~= "table" then
        p.signin = (legacy_record and type(legacy_record.signin) == "table") and legacy_record.signin or {available=false}
    end
    if p.playtime_seconds == nil then
        p.playtime_seconds = tonumber(legacy_record and legacy_record.playtime_seconds) or 0
    end
    if p.soul_cooldown_until == nil then
        p.soul_cooldown_until = tonumber(legacy_record and legacy_record.soul_cooldown_until) or 0
    end
    return p
end
function coord_soul_state_save(db)
    _small_json_save(COORD_SOUL_STATE_FILE, db or {players={}})
end
function coord_soul_state_migrate()
    local db = coord_soul_state_db()
    local data = load_data()
    local changed = false
    for _, rec in pairs(data.players or {}) do
        if type(rec) == "table" and tostring(rec.name or "") ~= "" then
            local name = tostring(rec.name)
            local existed = db.players[name] ~= nil
            local p = coord_soul_state_player(db, name, rec)
            if not existed then changed = true end
            if p.soul == nil and type(rec.soul) == "table" then
                p.soul = rec.soul
                changed = true
            end
        end
    end
    if changed or next(db.players) ~= nil then coord_soul_state_save(db) end
end

