function ai_usage_extract(data)
    local u = (type(data)=="table") and data.usage or nil
    if type(u)~="table" then return 0 end
    local t = tonumber(u.total_tokens)
    if not t then
        t = (tonumber(u.prompt_tokens) or 0) + (tonumber(u.completion_tokens) or 0)
    end
    return tonumber(t) or 0
end

function ai_usage_window_key(playerName, commandMode, windowKey)
    local w = trim(tostring(windowKey or ""))
    if w=="" then w = commandMode and "command" or "chat" end
    return tostring(w).."|"..tostring(playerName)
end

function ai_usage_window_add(playerName, commandMode, windowKey, amount)
    amount = tonumber(amount) or 0
    local d = ai_tokens_db()
    local k = ai_usage_window_key(playerName, commandMode, windowKey)
    local cur = (tonumber(d[k]) or 0) + amount
    d[k] = cur
    ai_tokens_save(d)
    return cur
end
function ai_usage_window_get(playerName, commandMode, windowKey)
    local d = ai_tokens_db()
    return tonumber(d[ai_usage_window_key(playerName, commandMode, windowKey)]) or 0
end
function ai_sse_usage_extract(raw)
    local best=0
    local function scan(v,depth)
        if type(v)~="table" or (depth or 0)>4 then return end
        local function consider(t)
            if type(t)~="table" then return end
            local total=tonumber(t.total_tokens or t.totalTokens)
            if total then if total>best then best=total end end
            local pt=tonumber(t.prompt_tokens or t.input_tokens or t.promptTokens)
            local ct=tonumber(t.completion_tokens or t.output_tokens or t.completionTokens)
            if pt or ct then
                local sum=(pt or 0)+(ct or 0)
                if sum>best then best=sum end
            end
        end
        consider(v)
        for _,k in ipairs({"usage","usage_metadata","token_usage","tokens","meta","data"}) do
            local x=v[k]
            if type(x)=="table" then scan(x,(depth or 0)+1) end
        end
    end
    for line in tostring(raw or ""):gmatch("[^\r\n]+") do
        local js=line:match("^data:%s*(.+)$")
        if js then
            local ok,d=pcall(http.json_decode,js)
            if ok and type(d)=="table" then scan(d,0) end
        end
    end
    if best==0 then
        local t=tonumber(tostring(raw or ""):match('"total_tokens"%s*:%s*(%d+)'))
        if t and t>best then best=t end
    end
    return math.floor(best)
end


call_ai = function(messages, timeout_override, model_override, max_tokens_override)
    local configured_model = ai_active_model()
    if model_override ~= nil and trim(tostring(model_override)) ~= "" then
        configured_model = trim(tostring(model_override))
    end
    local local_ok, local_text, local_model, local_tok = false, nil, nil, 0

    local api_url, configured_key, provider = ai_endpoint_for(configured_model)
    if configured_key == "" then
        error("AI连接失败：直连模型不可用，且插件直连密钥未配置。")
    end
    local use_thinking = ai_thinking_enabled()
    local max_try = math.max(1, tonumber(AI_RETRY_MAX) or 3)
    local last_err = "未知错误"

    for attempt = 1, max_try do
        local req = {
            model = configured_model,
            messages = messages,
            temperature = TEMPERATURE,
            max_tokens = tonumber(max_tokens_override) or MAX_REPLY,
        }
        if not use_thinking then req.thinking = { type = "disabled" } end
        local body = http.json_encode(req)
        local ok_post, r = pcall(http.post, api_url, body, {
            headers = {
                ['Content-Type'] = 'application/json',
                ['Authorization'] = 'Bearer ' .. configured_key
            },
            timeout = timeout_override or TIMEOUT
        })

        if not ok_post then
            last_err = "网络请求异常：" .. tostring(r)
        elseif not r or not r.ok then
            last_err = "网络请求失败：" .. tostring(r and (r.error or r.status) or "无响应")
        else
            local code = tonumber(r.status) or 0
            local rbody = tostring(r.body or "")
            if code == 429 then
                last_err = "接口限速（429）：" .. string.sub(rbody, 1, 200)
            elseif code >= 500 then
                last_err = "服务端错误（HTTP " .. tostring(code) .. "）：" .. string.sub(rbody, 1, 200)
            elseif code < 200 or code >= 300 then
                save_ai_trace({model=configured_model,status="http_error",status_code=code,reason=last_err,raw_body=rbody,request_body=body})
                error("HTTP " .. tostring(code) .. "：" .. string.sub(rbody, 1, 500))
            else
                local ok, data = pcall(http.json_decode, rbody)
                if not ok or type(data) ~= "table" then
                    last_err = "API 返回 JSON 解析失败"
                else
                    local _tok = ai_usage_extract(data)
                    AI_USAGE.last_call = _tok
                    AI_USAGE.task = (tonumber(AI_USAGE.task) or 0) + _tok
                    AI_USAGE.task_calls = (tonumber(AI_USAGE.task_calls) or 0) + 1
                    local choice = data.choices and data.choices[1]
                    local msg = choice and choice.message
                    local c = msg and msg.content
                    local reasoning_txt = msg and (msg.reasoning or msg.reasoning_content)
                    if (not c or trim(tostring(c)) == "") and type(reasoning_txt) == "string" and trim(reasoning_txt) ~= "" then
                        c = reasoning_txt
                    end
                    local has_content = (c and trim(tostring(c)) ~= "")
                    save_ai_trace({model=configured_model,
                        status=(has_content and "response_ok" or "empty_content"),
                        status_code=code,
                        reason=(has_content and "HTTP正常且AI返回了内容" or "HTTP正常，但AI内容为空"),
                        raw_body=rbody, assistant_output=c or "",
                        finish_reason=choice and choice.finish_reason or "未知",
                        request_body=body})
                    if has_content then return tostring(c) end
                    last_err = "AI没有返回内容(finish_reason=" .. tostring(choice and choice.finish_reason or "未知") .. ")"
                end
            end
        end

        if attempt < max_try then
            log_event("AI_RETRY","第"..tostring(attempt).."次失败："..last_err)
            ai_wait_seconds(AI_RETRY_WAIT)
        end
    end

    if string.find(last_err,"429",1,true) or string.find(last_err,"限速",1,true) then
        error("AI接口限速，请等几秒再试（"..last_err.."）")
    end
    error(last_err)
end

choose_signin_reward = function()
    local prompt=[[从下面6个安全签到奖励中选择一个最适合今天的，只返回一个字母，不要解释：
A 面包6
B 火把12
C 铁锭3
D 熟牛肉5
E 经验瓶2
F 金胡萝卜2
要求：奖励不能超标，不要创造其他物品。]]
    local ok,text=pcall(call_ai,{{role="system",content="你是服务器签到奖励选择器。"},{role="user",content=prompt}})
    if ok and type(text)=="string" then
        local letter=string.upper(trim(text)):match("[A-F]")
        if letter then return ({A=1,B=2,C=3,D=4,E=5,F=6})[letter] end
    end
    return (math.floor(util.timestamp())%#SIGNIN_REWARDS)+1
end



function utf8_truncate(s, max_chars)
    s=tostring(s or "")
    local limit=tonumber(max_chars) or NORMAL_REPLY_MAX_CHARS
    local count=0
    local i=1
    while i<=#s and count<limit do
        local b=string.byte(s,i)
        local n=1
        if b and b>=0xF0 then n=4 elseif b and b>=0xE0 then n=3 elseif b and b>=0xC0 then n=2 end
        if i+n-1>#s then break end
        i=i+n
        count=count+1
    end
    if i<=#s then return s:sub(1,i-1).."…" end
    return s
end

function compact_ai_reply(v)
    v=clean_ai_visible(v)
    v=v:gsub("[ \t\r\n]+"," ")
    v=trim(v)
    return utf8_truncate(v,NORMAL_REPLY_MAX_CHARS)
end

function clean_ai_visible(v)
    v=tostring(v or "")
    for _,tag in ipairs(AI_MARKER_TAGS) do
        v=v:gsub("%["..tag.."%](.-)%[/"..tag.."%]","")
    end
    v=v:gsub("%[CMD%]([^\n]*)", function(p)
        if marker_looks_like_cmd(p) then return "" end
        return "[CMD]"..p
    end)
    v=v:gsub("%[SHELL4%]([^\n]*)", function(p)
        if marker_looks_like_cmd(p) then return "" end
        return "[SHELL4]"..p
    end)
    v=v:gsub("SEARCH_WEB:%s*[^\n]+","")
    for _,tag in ipairs(AI_MARKER_TAGS) do
        v=v:gsub("%["..tag.."%]",""):gsub("%[/"..tag.."%]","")
    end
    return trim(v)
end
function task_has_recent_cmd_context(history)
    local questions=0
    for i=#(history or {}),1,-1 do
        local m=history[i]
        if type(m)=="table" then
            local c=tostring(m.content or "")
            if c:find("[CMD]",1,true) or c:find("SHELL4",1,true) or c:find("能力执行结果",1,true) then return true end
            if m.role=="user" and not c:find("能力执行",1,true) then
                questions=questions+1
                if questions>=2 then break end
            end
        end
    end
    return false
end

function task_prompt_append(messages,id)
    id=ai_seg_canonical(id)
    if id=="" then return false end
    local txt=ai_seg_load(id)
    if trim(txt)=="" then return false end
    local add="\n\n【当前任务专项提示词："..tostring(id).."】\n"..txt
    if messages[1] and messages[1].role=="system" then
        messages[1].content=tostring(messages[1].content or "")..add
    else
        table.insert(messages,1,{role="system",content=add})
    end
    return true
end

function auto_prompt_ids_from_tools(tool_text)
    local ids,seen={},{}
    local map={
        CMD="cmd", SHELL4="cmd", NBT="cmd",
        BUILD="build", BUILD_STOP="build", BUILD_OFF="build",
        MCP="mcp", MCP_EDIT="mcp"
    }
    local s=tostring(tool_text or "")
    for tag,id in pairs(map) do
        if s:find("["..tag.."]",1,true) then
            if id~="build" or is_admin(_CUR_AI_PLAYER) then
                if not seen[id] then seen[id]=true; ids[#ids+1]=id end
            end
        end
    end
    return ids
end

function task_prompt_load_set(messages,active,ids)
    local loaded={}
    for _,id in ipairs(ids or {}) do
        id=ai_seg_canonical(id)
        if id~="" and not active[id] then
            if task_prompt_append(messages,id) then
                active[id]=true
                loaded[#loaded+1]=id
            end
        end
    end
    return loaded
end

run_agent = function(question, playerName, commandMode, windowKey, privileged_override, opts)
    opts = (type(opts)=="table") and opts or {}
    AI_USAGE.task = 0
    AI_USAGE.task_calls = 0
    local started_at = util.timestamp()
    local ctx, admin = context_for(playerName, question)
    _CUR_AI_PLAYER = tostring(playerName or "")
    if privileged_override == true then admin = true end
    local _, player_rec = player_record(playerName,true)
    local build_state = ai_build_state_get(playerName)
    local effective_windowKey = windowKey
    local build_enabled = (build_state and build_state.active == true) or player_rec.ai_build_mode == true
    local build_mode = admin and build_enabled
    if build_mode and (not build_state or build_state.active ~= true) then
        ai_build_state_set(playerName,true,false,player_rec.ai_build_progress or "")
    end
    local agent_timeout = opts.timeout or (build_mode and BUILD_COMMAND_TIMEOUT or (commandMode and COMMAND_TIMEOUT or TIMEOUT)) or 60
    local max_rounds = opts.max_rounds or (build_mode and BUILD_MAX_ROUNDS or MAX_ROUNDS)
    local cmd_limit_per_round = opts.cmd_limit or nil
    local deadline = started_at + agent_timeout
    local global_rules = global_ai_rules_text()
    local _sys_base, _sys_intents = build_ai_system(question, admin)
    local system = tostring(_sys_base or "")
    if trim(ctx) ~= "" then system = system .. "\n\n【当前请求上下文】\n" .. ctx end
    if global_rules ~= "" then system = system .. "\n\n" .. global_rules end

    local history
    history = build_mode and get_build_history(playerName) or get_history(playerName, commandMode, effective_windowKey)
    local messages = {{role = "system", content = system}}
    local active_subprompts = {core=true}
    local initial_ids = {}
    -- 指令/建筑模式必须在当前任务真实注入完整专项，不能依赖“以前学过”的持久记忆。
    if commandMode then initial_ids[#initial_ids+1]="command" end
    if build_mode then initial_ids[#initial_ids+1]="build" end
    if task_has_recent_cmd_context(history) and not active_subprompts["command"] then
        initial_ids[#initial_ids+1]="command"
    end
    task_prompt_load_set(messages,active_subprompts,initial_ids)

    for _, msg in ipairs(history) do
        table.insert(messages, msg)
    end

    table.insert(messages, {role = "user", content = question})
    local function persist_history()
        if build_mode then save_build_history(playerName,messages) else save_history(playerName,messages,commandMode,effective_windowKey) end
    end
    local corrective_used = 0
    local CORRECTIVE_MAX = 2

    for round = 1, max_rounds do
        local _, live_rec=player_record(playerName,true)
        local stop_hit, stop_reason = ai_stop_check(playerName)
        if stop_hit then
            persist_history()
            return "AI 任务已停止（原因："..tostring(stop_reason or "手动停止").."）。"
        end
        local bstate_now = ai_build_state_get(playerName)
        if build_mode and bstate_now and bstate_now.stop_requested == true then
            ai_build_state_set(playerName,true,false,live_rec and live_rec.ai_build_progress or "")
            persist_history()
            return "建筑任务已停止；已经完成的部分不会删除。"
        end
        if build_mode and (live_rec and live_rec.ai_build_stop_requested==true) then
            if live_rec then live_rec.ai_build_stop_requested=false end
            ai_build_state_set(playerName,true,false,live_rec.ai_build_progress or "")
            local dd=load_data(); local key=identity(playerName);
            if dd.players and dd.players[key] then dd.players[key].ai_build_stop_requested=false end
            save_data(dd)
            persist_history()
            return "建筑任务已停止；已经完成的部分不会删除。"
        end
        local remain = deadline - util.timestamp()
        if remain <= 0 then persist_history(); error("AI思考超时；任务在第 "..tostring(round).." 轮中止") end
        local selected_model=choose_ai_model(question,commandMode)
        local reply_budget = (commandMode or build_mode) and MAX_REPLY or NORMAL_MAX_REPLY
        local api_ok, text_or_err = pcall(call_ai, messages, math.max(1, math.min(agent_timeout, remain)), selected_model, reply_budget)
        if not api_ok then
            local api_err=tostring(text_or_err)
            table.insert(messages,{role="assistant",content="[AI API调用失败] "..api_err})
            table.insert(messages,{role="user",content="本轮AI API调用失败，任务在这里中止。失败原因："..api_err.."。下次继续时必须记住这里没有成功执行后续步骤，不得假设成功。"})
            persist_history()
            error(api_err)
        end
        local text=tostring(text_or_err or "")
        table.insert(messages, {role = "assistant", content = text})

        -- task_mode 只由真实任务状态决定，不再根据用户文字猜意图。
        local task_mode = build_mode and "build" or "normal"
        local auto_ids = auto_prompt_ids_from_tools(text)
        local auto_loaded = task_prompt_load_set(messages,active_subprompts,auto_ids)
        if #auto_loaded>0 then
            table.insert(messages,{role="user",content="本轮工具已自动加载专项知识："..table.concat(auto_loaded,"、").."。保持同一任务上下文继续处理，不得清除或重置之前的对话与工具结果。"})
        end
        local results, used, load_requests, prompt_only = process_tools(text, playerName, admin, cmd_limit_per_round, active_subprompts, task_mode)
        if not admin and ai_ordinary_disallowed_tool(text, playerName) then
            persist_history()
            return AI_ORDINARY_DENIAL
        end
        if load_requests and #load_requests>0 then
            local loaded=task_prompt_load_set(messages,active_subprompts,load_requests)
            if #loaded>0 then
                table.insert(messages,{role="user",content="当前任务已加载专项提示词："..table.concat(loaded,"、").."。继续使用同一个任务上下文处理刚才的请求；已经加载的专项不要再次加载。"})
            end
        end

        if used and not prompt_only then
            local joined = table.concat(results, "\n")
            if string.find(joined,"已发起投票",1,true) then
                persist_history()
                return "投票已经发起，等待玩家投票。"
            end
            local failed = false
            for _, marker in ipairs({"失败", "错误", "拦截", "权限限制", "不存在", "无效"}) do
                if string.find(joined, marker, 1, true) then failed = true; break end
            end
            if failed then
                save_ai_trace({model=tostring(selected_model or "unknown"),status="tool_failed",status_code="",reason=joined,assistant_output=text,tool_result=joined})
                local failure_context = "能力执行真实返回（失败）：\n" .. joined .. "\n这是本次对话的一部分。请根据这个真实返回判断你刚才想完成什么、失败原因是什么；能换方式就重新调用合适能力，不能完成时再用正常简短语言向玩家说明事实。不要展示内部工具标记、调试字段或原始内部错误文本。"
                table.insert(messages, {role="user", content=failure_context})
            else
                table.insert(messages, {
                    role = "user",
                    content = "能力执行结果：\n" .. joined .. "\n请根据真实结果继续处理，不要假设成功。"
                })
            end
        elseif not prompt_only then
            if admin and round < max_rounds and corrective_used < CORRECTIVE_MAX and ai_reply_refused(text) then
                corrective_used = corrective_used + 1
                table.insert(messages, {role="user", content="【纠错】你刚才拒绝了服务器实际具备的工具能力。请根据当前已加载的专项提示词和真实工具结果重新处理；不要编造成功，也不要输出工具之外的执行承诺。"})
            elseif round < max_rounds and corrective_used < CORRECTIVE_MAX and ai_question_wants_action(question) and ai_reply_claims_done(text) then
                corrective_used = corrective_used + 1
                table.insert(messages, {role="user", content="【纠错】你声称已经完成，但本轮没有任何工具调用标记或真实工具结果。请只根据当前专项提示词重新输出实际工具调用；没有工具结果就不能声称完成。"})
            elseif commandMode and round < max_rounds then
                persist_history()
                return compact_ai_reply(text)
            else
                persist_history()
                return compact_ai_reply(text)
            end
        end
    end

    local last = messages[#messages]
    if last and last.role == "user" and string.find(last.content or "", "能力执行", 1, true) then
        local brief = tostring(last.content)
        brief = brief:gsub("能力执行结果：", ""):gsub("能力执行真实返回（失败）：", "")
        brief = brief:gsub("请根据真实结果继续处理，不要假设成功。", "")
        brief = brief:gsub("这是本次对话的一部分。.-不要展示内部工具标记、调试字段或原始内部错误文本。", "")
        brief = clean_ai_visible(brief)
        persist_history()
        return "执行结果：" .. trim(brief)
    end
    persist_history()
    for i=#messages,1,-1 do
        if messages[i].role=="assistant" and trim(messages[i].content or "")~="" then
            local out = compact_ai_reply(messages[i].content)
            if trim(out) ~= "" then return out end
        end
    end
    return "AI 未能完成这次请求，请换一种说法再试。"
end


function player_record(name, create)
    local d = load_data()
    local key, info = identity(name)
    local record = d.players[key]

    if not record then
        for old_key, candidate in pairs(d.players) do
            if type(candidate) == "table" and (
                candidate.name == name or
                (trim(info.xuid) ~= "" and trim(candidate.xuid) == trim(info.xuid)) or
                (trim(info.unique_id) ~= "" and trim(candidate.unique_id) == trim(info.unique_id))
            ) then
                record = candidate
                d.players[key] = record
                if old_key ~= key then d.players[old_key] = nil end
                break
            end
        end
    end

    record = record or {
        xuid = info.xuid or "",
        unique_id = info.unique_id or "",
        name = name,
        waypoints = {},
        death = nil
    }
    record.name = name
    record.xuid = trim(info.xuid) ~= "" and info.xuid or (record.xuid or "")
    record.unique_id = trim(info.unique_id) ~= "" and info.unique_id or (record.unique_id or "")
    record.waypoints = record.waypoints or {}
    d.players[key] = record

    local normalized = {}
    for i = 1, 10 do
        local wp = record.waypoints[i] or record.waypoints[tostring(i)]
        if type(wp) == "table" then normalized[tostring(i)] = wp end
    end
    record.waypoints = normalized
    d.players[key] = record
    return d, record, key
end

function wp_get(record, slot)
    record.waypoints = record.waypoints or {}
    return record.waypoints[tostring(slot)]
end

function wp_set(record, slot, value)
    record.waypoints = record.waypoints or {}
    record.waypoints[tostring(slot)] = value
end

function wp_delete(record, slot)
    record.waypoints = record.waypoints or {}
    record.waypoints[tostring(slot)] = nil
end

function detect_gamemode(name)
    local safe = string.gsub(name, '"', '\\"')
    local modes = {{id=0,name="survival"},{id=1,name="creative"},{id=2,name="adventure"},{id=3,name="spectator"}}
    for _,m in ipairs(modes) do
        local ok,hit=pcall(game.isCmdSuccess,'testfor @a[name="'..safe..'",m='..m.id..']')
        if ok and hit==true then return m.name end
    end
    return "survival"
end

function set_gamemode(name,mode)
    local safe=string.gsub(name,'"','\\"')
    local cmd='gamemode '..mode..' "'..safe..'"'
    local ok, result = pcall(game.isCmdSuccess, cmd)
    if ok and result == true then return true end
    local cmd2='gamemode '..mode..' @a[name="'..safe..'"]'
    local ok2, result2 = pcall(game.isCmdSuccess, cmd2)
    return ok2 and result2 == true
end

function mark_alive_state()
    pcall(game.sendCommand,'tag @a remove ds_alive')
    pcall(game.sendCommand,'tag @e[type=player] add ds_alive')
end

function is_alive_by_tag(name)
    local safe=string.gsub(name,'"','\\"')
    local ok,hit=pcall(game.isCmdSuccess,'testfor @a[name="'..safe..'",tag="ds_alive"]')
    return ok and hit==true
end
function is_alive_entity(name)
    local safe=string.gsub(name,'"','\\"')
    local ok,hit=pcall(game.isCmdSuccess,'testfor @e[type=player,name="'..safe..'"]')
    return ok and hit==true
end

function pos_looks_valid(x, y, z)
    x, y, z = tonumber(x), tonumber(y), tonumber(z)
    if not x or not y or not z then return false end
    if x == 0 and z == 0 then return false end
    if y < -64 or y > 320 then return false end
    if x ~= x or y ~= y or z ~= z then return false end
    if math.abs(x) > 30000000 or math.abs(z) > 30000000 then return false end
    return true
end

function player_position(name, fast)
    local cached = nil
    local okc, c = pcall(pos_cache_get, name)
    if okc and type(c) == "table" and pos_looks_valid(c.x, c.y, c.z) then
        cached = {x = tonumber(c.x), y = tonumber(c.y), z = tonumber(c.z),
                  dimension = normalize_dimension(c.dimension) or "overworld"}
    end

    local info = get_info(name)
    local fw = nil
    if info and pos_looks_valid(info.x, info.y, info.z) then
        fw = {x = tonumber(info.x), y = tonumber(info.y), z = tonumber(info.z)}
    end

    local gp = nil
    if not fast then
        local ok, pos = pcall(game.getPlayerPos, name)
        if ok and type(pos) == "table" and pos_looks_valid(pos.x, pos.y, pos.z) then
            gp = {x = tonumber(pos.x), y = tonumber(pos.y), z = tonumber(pos.z)}
        end
    end

    local pick = cached or gp or fw
    if not pick then return nil end
    pick.dimension = detect_dimension(name)
    return pick
end

function clone_saved_position(pos)
    if type(pos) ~= "table" then return nil end
    return {
        x = tonumber(pos.x), y = tonumber(pos.y), z = tonumber(pos.z),
        dimension = normalize_dimension(pos.dimension) or "overworld",
        saved_at = pos.saved_at or util.now()
    }
end

function precise_player_position(name)
    local ok, pos = pcall(game.getPlayerPos, name)
    if ok and type(pos) == "table" and pos_looks_valid(pos.x, pos.y, pos.z) then
        local x,y,z = tonumber(pos.x), tonumber(pos.y), tonumber(pos.z)
        local feet_y = math.floor(y)
        return {x=x, y=feet_y, z=z, dimension=detect_dimension(name), saved_at=util.now(), source="realtime"}
    end
    local fallback = player_position(name)
    if type(fallback) == "table" and pos_looks_valid(fallback.x, fallback.y, fallback.z) then
        fallback.source = fallback.source or "cache_fallback"
        fallback.saved_at = util.now()
        return fallback
    end
    return nil
end

function save_location(name)
    local pos = precise_player_position(name)
    if not pos then return nil, "无法读取当前位置" end

    local x, y, z = tonumber(pos.x), tonumber(pos.y), tonumber(pos.z)
    if not pos_looks_valid(x, y, z) then
        return nil, "读取到的坐标无效（" .. tostring(x) .. "," .. tostring(y) .. "," .. tostring(z) .. "），请稍后重试"
    end

    return {
        x = math.floor(x + 0.5),
        y = math.floor(y),
        z = math.floor(z + 0.5),
        dimension = detect_dimension(name),
        saved_at = util.now()
    }, nil
end

function dim_exec(dim)
    dim = lower(trim(dim))
    if dim == "nether" or dim == "the_nether" or dim == "1" then return "nether" end
    if dim == "the_end" or dim == "end" or dim == "2" then return "the_end" end
    return "overworld"
end

function tp_to(name, loc)
    if not loc then return false, "没有这个传送点" end
    local x, y, z = tonumber(loc.x), tonumber(loc.y), tonumber(loc.z)
    if not x or not y or not z then return false, "传送点坐标损坏" end
    if not pos_looks_valid(x, y, z) then
        return false, "该传送点坐标无效（" .. tostring(x) .. "," .. tostring(y) .. "," .. tostring(z) .. "），请重新保存"
    end


    local safeName = string.gsub(name, '"', '\\"')
    local cmd = string.format('execute as @a[name="%s"] at @s in %s run tp @s %.2f %.2f %.2f', safeName, dim_exec(loc.dimension), x, y, z)
    local ok, result = pcall(game.isCmdSuccess, cmd)
    if ok and result == true then return true, nil end
    return false, "传送指令执行失败"
end

function slot_menu(name, mode)
    local d, r = player_record(name, true)
    local title = mode == "save_slot" and "§b请选择要保存的传送点" or
                  (mode == "return_slot" and "§b请选择要返回的传送点" or "§b请选择要删除的传送点")

    local lines = {title, "§7输入 1~10 选择位置，输入 .stop / stop / 停止 退出"}
    for i = 1, 10 do
        local wp = wp_get(r,i)
        if wp and wp.name and wp.name ~= "" then
            table.insert(lines, string.format("§f%d. §a%s §7维度: §f%s", i, wp.name, tostring(wp.dimension)))
        else
            table.insert(lines, string.format("§f%d.", i))
        end
    end
    send(name, table.concat(lines, "\n"))

    r.menu = mode
    if not r.menu_expires then r.menu_expires = util.timestamp() + MENU_TIMEOUT end
    save_data(d)
end


function file_load(path, default)
    local ok,v=pcall(util.json_load,path)
    if ok and type(v)=="table" then return v end
    return default or {}
end
function file_save(path,v) pcall(util.json_write,path,v) end


function parse_cn_integer(text)
    text=trim(tostring(text or ""))
    local d={ ["零"]=0,["〇"]=0,["一"]=1,["两"]=2,["二"]=2,["三"]=3,["四"]=4,["五"]=5,["六"]=6,["七"]=7,["八"]=8,["九"]=9 }
    local n=tonumber(text)
    if n then return n end
    if d[text]~=nil then return d[text] end
    local b=text:find("百",1,true)
    if b then
        local left=text:sub(1,b-1); local right=text:sub(b+3)
        local a=parse_cn_integer(left) or 0; local c=(right~="" and parse_cn_integer(right) or 0)
        return a*100+c
    end
    local t=text:find("十",1,true)
    if t then
        local left=text:sub(1,t-1); local right=text:sub(t+3)
        local a=(left=="" and 1 or parse_cn_integer(left) or 0)
        local c=(right=="" and 0 or parse_cn_integer(right) or 0)
        return a*10+c
    end
    return nil
end
function parse_expiry(text)
    text=trim(text or "")
    local exp=text:match("有效期%s*(.-)%s*$") or text
    exp=trim(exp):gsub("[%s]+", "")
    exp=exp:gsub("天数$", "天"):gsub("日数$", "日"):gsub("个日$", "日"):gsub("个天$", "天")
    exp=exp:gsub("^约","")
    local units={{"天",86400,"天"},{"日",86400,"天"},{"小时",3600,"小时"},{"小時",3600,"小时"},{"时辰",3600,"小时"},{"时",3600,"小时"},{"分钟",60,"分钟"},{"分鐘",60,"分钟"},{"分",60,"分钟"},{"秒钟",1,"秒"},{"秒",1,"秒"},{"[Dd]",86400,"天"},{"[Hh]",3600,"小时"},{"[Mm]",60,"分钟"},{"[Ss]",1,"秒"}}
    for _,u in ipairs(units) do
        local nraw=exp:match("^(.-)%s*"..u[1].."%s*$")
        if nraw then
            nraw=trim(nraw)
            local n=parse_cn_integer(nraw)
            if n and n>0 then return n*u[2],tostring(n)..u[3],nraw end
        end
    end
    return nil,nil,nil
end

function generate_code(data)
    data=data or {}
    data.redeem_codes=data.redeem_codes or {}
    local letters="abcdefghijklmnopqrstuvwxyz"
    local digits="0123456789"
    local seed=(tonumber(util.timestamp()) or os.time()) + #tostring(data.redeem_codes)*97
    pcall(math.randomseed,seed)
    for _=1,100 do
        local ai=math.random(1,#letters); local bi=math.random(1,#letters)
        local a=letters:sub(ai,ai); local b=letters:sub(bi,bi)
        local n1=math.random(0,9); local n2=math.random(0,9); local n3=math.random(0,9)
        local code=string.format("%s%s%d%d%d",a,b,n1,n2,n3)
        if not data.redeem_codes[code] then return code end
    end
    return nil
end
function uuid_key(name)
    local ok,info=pcall(player.get,name)
    if ok and type(info)=="table" then
        local u=trim(info.unique_id or info.xuid or info.uid or "")
        if u~="" then return u end
    end
    local d,r,key=player_record(name,true)
    return trim(r.unique_id or r.xuid or key or name)
end

MARKET_STORAGE_AREA_NAME="ds_ai_market_storage"
function market_storage_db() return file_load(MARKET_STORAGE_FILE,{x=nil,y=nil,z=nil,dimension="overworld",area_name=MARKET_STORAGE_AREA_NAME,set_at=0,set_by=""}) end
function market_storage_save(v) file_save(MARKET_STORAGE_FILE,v) end
function market_storage_set(name,x,y,z)
    if not is_admin(name) then send(name,"§c只有管理权限可以设置玩家市场三维仓库。") return true end
    x,y,z=math.floor(tonumber(x) or 0),math.floor(tonumber(y) or 0),math.floor(tonumber(z) or 0)
    local dim=detect_dimension(name); local d={x=x,y=y,z=z,dimension=dim,area_name=MARKET_STORAGE_AREA_NAME,set_at=util.timestamp(),set_by=name}; market_storage_save(d)
    local cmd=string.format("tickingarea add %d %d %d %d %d %d %s",x,y,z,x+15,y,z+15,MARKET_STORAGE_AREA_NAME)
    local ok,res=pcall(game.isCmdSuccess,cmd)
    if ok and res==true then send(name,"§a✓ 玩家市场三维仓库已设置。\n§f初始坐标：§e"..x.." "..y.." "..z.."\n§7编号1从这里开始，16×16满后自动向上增加Y层；之后无需再次输入坐标。") else send(name,"§e仓库坐标已保存：§f"..x.." "..y.." "..z.."\n§c常加载区域命令未确认成功，请检查服务器中是否已有同名常加载区域。") end
    return true
end
function market_storage_coord(id)
    local st=market_storage_db(); if st.x==nil or st.y==nil or st.z==nil then return nil end
    local n=math.floor(tonumber(id) or 0)-1; if n<0 then return nil end
    local layer=math.floor(n/256); local rem=n%256; return {x=st.x+(rem%16),y=st.y+layer,z=st.z+math.floor(rem/16),dimension=st.dimension}
end
function market_clone_one(sx,sy,sz,tx,ty,tz)
    local cmd=string.format("clone %d %d %d %d %d %d %d %d %d replace",math.floor(sx),math.floor(sy),math.floor(sz),math.floor(sx),math.floor(sy),math.floor(sz),math.floor(tx),math.floor(ty),math.floor(tz)); local ok,res=pcall(game.isCmdSuccess,cmd); return ok and res==true,cmd
end
function market_clear_barrel_drop(name,x,y,z)
    return true
end

function server_sell_sessions_db(d)
    d.server_sell_sessions = d.server_sell_sessions or {}
    return d.server_sell_sessions
end

function server_sell_get_session(d,name)
    local sessions=server_sell_sessions_db(d)
    local s=sessions[tostring(name)]
    if type(s)=="table" then return s end
    local players=d.players or {}
    for _,record in pairs(players) do
        if type(record)=="table" and tostring(record.name or "")==tostring(name) and type(record.server_sell_session)=="table" then
            s=record.server_sell_session
            s.owner=tostring(name)
            sessions[tostring(name)]=s
            record.server_sell_session=nil
            return s
        end
    end
    return nil
end

function server_sell_set_session(d,name,s)
    local sessions=server_sell_sessions_db(d)
    if type(s)=="table" then s.owner=tostring(name); sessions[tostring(name)]=s
    else sessions[tostring(name)]=nil end
end

function server_sell_clear_session(d,name)
    local sessions=server_sell_sessions_db(d)
    sessions[tostring(name)]=nil
    local players=d.players or {}
    for _,record in pairs(players) do
        if type(record)=="table" and tostring(record.name or "")==tostring(name) then
            record.server_sell_session=nil
        end
    end
end

function server_sell_cleanup_drops(x,y,z)
    local cmd=string.format('kill @e[type=item,x=%d,y=%d,z=%d,r=3]',math.floor(x),math.floor(y),math.floor(z))
    pcall(game.isCmdSuccess,cmd)
end

SERVER_SELL_MISS_LIMIT = 3

function server_sell_block_exists(x,y,z)
    local ok,data=market_region_one_block(math.floor(x),math.floor(y),math.floor(z))
    if not ok or type(data)~="table" then return false end
    return lower(tostring(data.name or data.id or "")):find("barrel",1,true)~=nil
end

function server_sell_find_barrel(x, y, z)
    x, y, z = math.floor(x), math.floor(y), math.floor(z)
    local cands = { y, y - 1, y + 1, y - 2, y + 2 }
    local seen = {}
    for _, cy in ipairs(cands) do
        if not seen[cy] then
            seen[cy] = true
            local ok, data = market_region_one_block(x, cy, z)
            if ok and type(data) == "table" then
                local nm = lower(tostring(data.name or data.id or ""))
                if nm:find("barrel", 1, true) ~= nil then
                    return cy, data
                end
            end
        end
    end
    return nil, nil
end

function server_sell_validate_session(name,d)
    local s=server_sell_get_session(d,name)
    if type(s)~="table" then return nil,false end
    if tostring(s.owner or name)~=tostring(name) then return nil,false end
    local p=s.barrel_pos
    if type(p)~="table" then
        server_sell_clear_session(d,name)
        return nil,false
    end
    local x,y,z=math.floor(p.x),math.floor(p.y),math.floor(p.z)

    local hit_y = server_sell_find_barrel(x, y, z)
    if hit_y == nil then
        s.miss = (tonumber(s.miss) or 0) + 1
        if s.miss >= SERVER_SELL_MISS_LIMIT then
            server_sell_cleanup_drops(x, y - 1, z)
            server_sell_clear_session(d,name)
        else
            server_sell_set_session(d,name,s)   -- 保留会话，写回 miss 计数
        end
        return nil,false
    end
    s.miss = 0
    if tonumber(s.barrel_y) ~= hit_y then
        s.barrel_y = hit_y
        server_sell_set_session(d,name,s)
    end
    return s,true
end

function market_clone_storage_to_target(id,x,y,z)
    local c=market_storage_coord(id); if not c then return false,"管理权限尚未设置玩家市场仓库。" end
    local ok=market_clone_one(c.x,c.y,c.z,x,y,z); if not ok then return false,"仓库商品 clone 失败。" end; return true,c
end
function load_json_table_file(path,default) local ok,v=pcall(util.json_load,path); if ok and type(v)=="table" then return v end; return default or {} end
function ensure_reference_data_file(path, default_table)
    local ok,v=pcall(util.json_load,path)
    if ok and type(v)=="table" and next(v)~=nil then
        local changed=false
        for k,dv in pairs(default_table or {}) do
            if v[k]==nil then v[k]=dv; changed=true end
        end
        if changed then pcall(util.json_write,path,v) end
        return v
    end
    pcall(util.json_write,path,default_table)
    return default_table
end
local FULL_SHOP_CACHE, ITEM_NAME_CACHE, ITEM_DAMAGE_CACHE, SELL_PRICE_CACHE
function full_shop_data()
    if not FULL_SHOP_CACHE then
        FULL_SHOP_CACHE=ensure_reference_data_file(FULL_SHOP_FILE, default_full_shop_prices())
        local names=default_item_names()
        local sells=default_sell_prices()
        local changed=false
        local next_order=0
        for _,v in pairs(FULL_SHOP_CACHE or {}) do
            local o=tonumber(v and v.order) or 0
            if o>next_order then next_order=o end
        end
        for id,nm in pairs(names or {}) do
            id=lower(tostring(id)):gsub('^minecraft:','')
            if id~='' and FULL_SHOP_CACHE[id]==nil then
                local sv=sells[id]
                local base=tonumber(sv and (sv.price or sv)) or 1
                if base<1 then base=1 end
                next_order=next_order+1
                FULL_SHOP_CACHE[id]={price=math.floor(base),buy_price=math.floor(base*10),name=tostring(nm),damage=tonumber(sv and sv.damage or 0) or 0,order=next_order,category='全物品',admin_only=full_shop_admin_only and full_shop_admin_only(id,nm) or false}
                changed=true
            end
        end
        if changed then pcall(util.json_write,FULL_SHOP_FILE,FULL_SHOP_CACHE) end
    end
    return FULL_SHOP_CACHE
end
function item_name_data()
    if not ITEM_NAME_CACHE then ITEM_NAME_CACHE=ensure_reference_data_file(ITEM_NAMES_FILE,default_item_names()) end
