    local d,r=player_record(name,true)
    if r.market_sell_preview_pending and not (d.market_sessions and d.market_sessions[name]) then r.market_sell_preview_pending=nil end
    if d.market_sessions and d.market_sessions[name] and d.market_sessions[name].preview_entry==nil then d.market_sessions[name]=nil end
    r.market_sell_preview_pending=nil
    local st=r.market_sell_day or {day=math.floor(util.timestamp()/86400),count=0,last_at=0}; r.market_sell_day=st; local day=math.floor(util.timestamp()/86400); if st.day~=day then st.day=day; st.count=0 end
    if st.count>=5 then send(name,"§c你今天已经使用5次上架机会。明天再来。") return true end
    if util.timestamp()-(tonumber(st.last_at) or 0)<600 then send(name,"§c两次上架至少间隔10分钟。") return true end
    set_menu(d,r,"market_sell_price"); send(name,"§e请输入商品价格（使用当前积分版的分数作为金币）：") return true
end
function market_sell_preview_message(entry,id,name,price)
    local lines={"§b━━ 出售物品预览 ━━","§f商品ID：§b"..tostring(id),"§f出售名称：§e"..tostring(name),"§f出售价格：§6"..tostring(price).."积分","§f真实物品："}
    local pl,shown,total=market_item_preview_lines(entry.nbt,20)
    if #pl==0 then lines[#lines+1]="§c木桶内没有可预览的物品。" else for _,x in ipairs(pl) do lines[#lines+1]=x end end
