    local db=market_db(); db.listings[id]={id=id,name=s.name,price=s.price,seller=name,seller_uuid=uuid_key(name),storage_id=id,preview_nbt=entry.nbt,created_at=util.timestamp(),sold=false,sold_count=0,disabled=false,shop_banned=false,reports=0}; db.next_id=math.max(tonumber(db.next_id)or 1,tonumber(s.id)+1); market_save(db)
    r.market_sell_day.count=(tonumber(r.market_sell_day.count)or 0)+1; r.market_sell_day.last_at=util.timestamp(); d.market_sessions[name]=nil; r.market_sell_preview_pending=nil; clear_menu(d,r); save_data(d); set_market_busy(false); append_json_log(SHOP_LOG_FILE,{at=util.timestamp(),type="上架",seller=name,id=id,name=s.name,price=s.price,storage_id=id}); local first=(entry.nbt.Items and entry.nbt.Items[1]); local firstid=first and item_base_id(first) or "-"; send(name,"§a商品已上架！\n§f商品ID：§b"..id.."\n§f商品名：§e"..s.name.."\n§f首项真实ID/翻译：§b"..tostring(firstid).." §7/ §e"..tostring(first and translated_item_name(first) or s.name).."\n§f价格：§6"..s.price.."积分"); return true
end

function market_finish_sell(name)
    local d,r=player_record(name,true); local s=d.market_sessions and d.market_sessions[name]
    if r.market_sell_preview_pending and (not s or type(s.preview_entry)~="table") then r.market_sell_preview_pending=nil; if s then s.preview_entry=nil end; save_data(d) end
    if not s then send(name,"§c没有待确认商品。") return true end
    if r.market_sell_preview_pending and type(s.preview_entry)=="table" then send(name,"§e已有一个出售预览待确认，请输入1确认或0取消。") return true end
    local bx,by,bz=tonumber(s.barrel_pos.x),tonumber(s.barrel_pos.y),tonumber(s.barrel_pos.z)
    local bot=ai_bot_identity()
