function agent_all_options()
    local list={}
    local custom=agent_load_custom()
    for _,s in ipairs(AGENT_CUSTOM_SLOTS) do
        local c=custom[s.key] or {}
        if s.key=="workbuddy" and (tostring(c.base_url or "")=="" or tostring(c.api_key or "")=="") then
            list[#list+1]={kind="workbuddy",slot=s.key,label="WorkBuddy（外部AI）",base_url="",api_key="",model_id="",ready=true}
        else
            list[#list+1]={kind="custom",slot=s.key,label=s.label,base_url=tostring(c.base_url or ""),api_key=tostring(c.api_key or ""),model_id=tostring(c.model_id or ""),ready=(tostring(c.base_url or "")~="" and tostring(c.api_key or "")~="")}
        end
    end
    return list
end

function agent_resolve()
    local pick=agent_load_pick(); if type(pick)~="table" then return nil end
    if pick.kind=="workbuddy" then
        local c=agent_load_custom()["workbuddy"] or {}
        if tostring(c.base_url or "")~="" and tostring(c.api_key or "")~="" then
            return {kind="custom",slot="workbuddy",label=tostring(c.label or "WorkBuddy"),base_url=tostring(c.base_url),api_key=tostring(c.api_key),model_id=tostring(c.model_id or "")}
        end
        return {kind="workbuddy",slot="workbuddy",label="WorkBuddy（外部AI）",base_url="",api_key="",model_id=""}
    end
    if pick.kind=="custom" then
        local c=agent_load_custom()[tostring(pick.slot or "")] or {}
        if tostring(c.base_url or "")=="" or tostring(c.api_key or "")=="" then return nil end
        return {kind="custom",slot=pick.slot,label=tostring(c.label or pick.slot),base_url=tostring(c.base_url),api_key=tostring(c.api_key),model_id=tostring(c.model_id or "")}
    end
    return nil
end

function agent_api_url(base)
    base=trim(tostring(base or "")); if base=="" then return "" end
    local lowb=lower(base)
    if lowb:find("chat/completions",1,true) then return base end
    if lowb:sub(-3)=="/v1" then return base.."/chat/completions" end
    if lowb:sub(-1)=="/" then return base.."v1/chat/completions" end
    return base.."/v1/chat/completions"
end

function agent_parse_sse(raw)
    local out={}
    local ev=""
    for line in tostring(raw or ""):gmatch("[^\r\n]+") do
        local e = line:match("^event:%s*(.+)$")
        if e then
            ev = trim(e)
        else
            local js = line:match("^data:%s*(.+)$")
            if js and (ev=="" or ev=="ai_chunk" or ev=="ai_message" or ev=="ai_content") then
                local ok,d = pcall(http.json_decode, js)
                if ok and type(d)=="table" and type(d.text)=="string" then
                    out[#out+1]=d.text
                end
            end
        end
    end
    return table.concat(out,"")
end

function agent_call(p, prompt, name)
    if p.kind=="workbuddy" then
        local ok,err = ai_agent_forward(tostring(name or ""), tostring(prompt or ""))
        if not ok then return false,tostring(err) end
        return true,"__WORKBUDDY__"
    end
    local url=agent_api_url(p.base_url)
    if url=="" then return false,"这个选项还没配接口地址" end
    local payload=http.json_encode({
        model=tostring(p.model_id or ""),
        messages={{role="user",content=tostring(prompt or "")}},
        stream=false,
    })
    local ok,res = pcall(http.post, url, payload, {
        headers={["Content-Type"]="application/json",
                 ["Authorization"]="Bearer "..tostring(p.api_key or "")},
        timeout=90,
    })
    if not ok then return false,"请求失败："..tostring(res) end
    local status = type(res)=="table" and tonumber(res.status) or nil
    local body = type(res)=="table" and (res.body or res.text) or tostring(res)
    local ok2,d = pcall(http.json_decode, body)
    if not ok2 or type(d)~="table" then
        return false,(status and ("HTTP "..status.." ") or "").."返回不是 JSON："..tostring(body):sub(1,160)
    end
    if d.error then return false,"接口报错："..tostring(d.error.message or d.error) end
    local ch = d.choices and d.choices[1]
    local txt = ch and ((ch.message and ch.message.content) or ch.text) or nil
    if txt==nil or tostring(txt)=="" then
        return false,"模型没返回内容："..tostring(body):sub(1,160)
    end
    return true,tostring(txt)
end

function agent_send_long(name, text)
    text=tostring(text or "")
    local lines={}
    for l in tostring(text):gmatch("[^\r\n]+") do lines[#lines+1]=l end
    if #lines==0 then lines={text} end
    local buf=""; local sent=0
    local function flush()
        if buf~="" and sent<6 then send(name,buf); sent=sent+1; buf="" end
    end
    for _,l in ipairs(lines) do
        if #buf + #l + 1 > 180 then flush() end
        buf = (buf=="" and l) or (buf.."\n"..l)
    end
    flush()
    if sent>=6 then send(name,"§7（回复过长，已截断）") end
end

function ai_echo_file() return game.dataDir().."/ai_echo.json" end
function ai_echo_mode()
    local ok, d = pcall(util.json_load, ai_echo_file())
    if ok and type(d) == "table" and type(d.mode) == "string" and d.mode ~= "" then
        return d.mode
    end
    return "both"
end
function ai_echo_set(m) pcall(util.json_write, ai_echo_file(), {mode = tostring(m or "both")}) end

function agent_echo(name, text)
    local m = ai_echo_mode()
    if m == "public" then pcall(broadcast, tostring(text or "")); return end
    if m == "both" then
        pcall(send, name, tostring(text or ""))
        pcall(broadcast, tostring(text or ""))
        return
    end
    pcall(send, name, tostring(text or ""))
end

function agent_echo_long(name, text)
    text = tostring(text or "")
    local lines = {}
    for l in text:gmatch("[^\r\n]+") do lines[#lines + 1] = l end
    if #lines == 0 then lines = {text} end
    local buf = ""
    local sent = 0
    local function flush()
        if buf ~= "" and sent < 6 then agent_echo(name, buf); sent = sent + 1; buf = "" end
    end
    for _, l in ipairs(lines) do
        if #buf + #l + 1 > 180 then flush() end
        buf = (buf == "" and l) or (buf .. "\n" .. l)
    end
    flush()
    if sent >= 6 then agent_echo(name, "§7（回复过长，已截断）") end
end

function cmd_selfcheck(name)
    local ok, s = pcall(function()
        local r = {}
        local okj, jv = pcall(json_rawtext, "自检")
        r[#r + 1] = "json_rawtext=" .. tostring(jv) .. (okj and "" or "(pcall失败)")
        local function t(tag, cmd)
            local okk, v = pcall(game.isCmdSuccess, cmd)
            r[#r + 1] = tag .. "=" .. tostring(v) .. (okk and "" or "(pcall失败)")
        end
        t("tellraw全体", 'tellraw @a {"rawtext":[{"text":"自检A"}]}')
        t("tellraw本人", 'tellraw "' .. tostring(name) .. '" {"rawtext":[{"text":"自检B"}]}')
        t("execute本人", 'execute ' .. tostring(name) .. ' ~~~ say 自检C')
        t("say", 'say 自检D')
        t("tag本人", 'tag "' .. tostring(name) .. '" add 自检tag')
        t("testfor", 'testfor @a[name="' .. tostring(name) .. '"]')
        return table.concat(r, "｜")
    end)
    local msg = "[发送自检] " .. (ok and s or ("自检报错：" .. tostring(s)))
    pcall(send, name, msg)
    pcall(ai_agent_forward, name, msg, nil)
    return true
end

function agent_show_menu(name)
    local list=agent_all_options()
    local pick=agent_load_pick()
    if #list==0 then send(name,"§c一个可选的 AI 都没有。\n§7请先配置可用的 AI Agent 通道。"); return true end
    local lines={}
    for i,o in ipairs(list) do
        local mark=o.ready and "§a●" or "§7○"
        local cur=""
        if pick and ((o.kind=="workbuddy" and pick.kind=="workbuddy") or (o.kind=="custom" and pick.kind=="custom" and pick.slot==o.slot)) then cur=" §b←当前" end
        lines[#lines+1]=string.format("§f%d. %s §f%s%s",i,mark,o.label,cur)
    end
    send(name,"§b━━ AI Agent 选择 ━━\n"..table.concat(lines,"\n").."\n§e输入编号选择；§f.stop §7退出")
    return true
end

function agent_pick(name, idx)
    local list=agent_all_options()
    local o=list[tonumber(idx) or 0]
    if not o then send(name,"§c没有这个编号。用 §f.Agent 选择 §c重新看。"); return true end
    if not o.ready then send(name,"§e「"..tostring(o.label).."」还没配好。\n§7用法：§f.Agent 配置 "..idx.." <接口地址> <密钥> <模型名>"); return true end
    local rec=(o.kind=="workbuddy") and {kind="workbuddy",slot="workbuddy",label=o.label} or {kind="custom",slot=o.slot,label=o.label}
    agent_save_pick(rec)
    send(name,"§a已选择：§b"..tostring(o.label).."\n§7以后输入 §f.AI agent 要说的话 §7就用它。")
    return true
end

function agent_config(name, idx, base_url, api_key, model_id)
    local list=agent_all_options()
    local o=list[tonumber(idx) or 0]
    if not o then send(name,"§c没有这个编号。"); return true end
    if o.kind~="custom" and o.kind~="workbuddy" then send(name,"§c系统 AI 渠道请用 .AI渠道 管理。"); return true end
    if base_url=="" or api_key=="" then
        send(name,"§e用法：§f.Agent 配置 "..idx.." <接口地址> <密钥> <模型名>\n§7例：§f.Agent 配置 4 https://api.deepseek.com sk-xxx deepseek-chat")
        return true
    end
    local c=agent_load_custom()
    c[o.slot]={base_url=base_url, api_key=api_key, model_id=(model_id~="" and model_id or "gpt-4o-mini"), label=o.label}
    local ok,err=agent_save_custom(c)
    if not ok then send(name,"§c保存失败："..tostring(err)); return true end
    send(name,"§a已配置 §b"..tostring(o.label).."§a。\n§7用 §f.Agent 选择 §7再选一次就能用了。")
    return true
end

function agent_ask(name, text)
    if trim(tostring(text or ""))=="" then
        send(name,"§e用法：§f.AI agent 你想问的话\n§7先 §f.Agent 选择 §7挑一个模型；当前："..tostring((agent_load_pick() or {}).label or "未选择"))
        return true
    end
    local p=agent_resolve()
    if not p then
        pcall(agent_log_chat, name, "（解析失败）", text,
              "选中的模型解析不出来：agent_picked.json 记录的 model_id 在当前 /api/ai/models 里找不到")
        agent_echo(name,"§e之前选的模型现在用不了了（可能被删或改了配置）。\n§7输入 §f.Agent 选择 §7重新挑一个。")
        return true
    end
    agent_echo(name,"§7["..tostring(p.label).."] 思考中…")
    local ok,ans=agent_call(p,text,name)
    if not ok then
        pcall(agent_log_chat, name, tostring(p.label), text, "【调用失败】"..tostring(ans))
        agent_echo(name,"§c调用失败："..tostring(ans).."\n§7换个模型试试：§f.Agent 选择")
        return true
    end
    if ans=="__WORKBUDDY__" then
        agent_log_chat(name, p.label, text, "（已投递到 WorkBuddy，等待它回话）")
        agent_echo(name,"§a已发给 §bWorkBuddy§a：\n§f"..text.."\n§7它收到后会用指令/聊天把回答发回游戏。")
        return true
    end
    agent_log_chat(name, p.label, text, ans)
    agent_echo_long(name,"§b["..tostring(p.label).."]§f "..ans)
    return true
end

function agent_log_file() return game.dataDir().."/agent_chat_log.json" end
function agent_log_chat(name, label, ask, ans)
    local ok,arr = pcall(util.json_load, agent_log_file())
    if not ok or type(arr)~="table" then arr={} end
    arr[#arr+1] = {at=util.timestamp(), player=tostring(name or ""),
                   model=tostring(label or ""), q=tostring(ask or ""),
                   a=tostring(ans or ""):sub(1,4000)}
    while #arr > 30 do table.remove(arr,1) end
    pcall(util.json_write, agent_log_file(), arr)
end

function ai_agent_forward(name, text, agent_no)
    local key = ai_agent_bridge_key()
    if key == "" then return false, "未设置密钥（.AIAgent密钥 <平台密钥>）" end
    local n = tonumber(agent_no)
    local payload = http.json_encode({
        player = tostring(name),
        uuid = tostring(uuid_key(name) or ""),
        text = tostring(text or ""),
        agent_no = (n and n > 0) and n or nil,
        at = util.timestamp(),
    })
    local ok, res = pcall(http.post, AI_AGENT_BRIDGE_URL, payload, {
        headers = { ['Content-Type'] = 'application/json', ['X-Ds-Key'] = key },
        timeout = 10,
    })
    if not ok then return false, tostring(res) end
    if type(res)=="table" and tonumber(res.status) ~= nil and tonumber(res.status) >= 400 then
        return false, "HTTP "..tostring(res.status).." "..tostring(res.body or ""):sub(1,120)
    end
    return true
end


