function show_trigger_words(name,page)
    local all={
        ".help",".stop",".触发词",
        ".保存 / .保",".回 / .home / .传",".删除 / .删",".死亡日志（最近5次+序号传送）",".死亡点返回 [序号]",".dp where",".help 14 → 2 玩家收购",
        ".tp 维度 X Y Z","./tp 玩家",".传送机会",".撤回传送",
        ".soul",".退出",".签到",".背包",".撤销",".撤销举报",
        ".添加权限 玩家",".撤回权限 玩家",".解除封禁",
        ".玩家市场",".市场",".市场仓库 X Y Z",".查看商家 玩家名",".售卖物品",".售卖商品",".help 14 → 2 玩家收购",".出售物品",".购买物品",".购物",".购物系统",".购物日志",
        ".出售物品（管理设置特殊商品）",
        ".举报商品 编号",".商品举报 编号",".查验 编号",".日志",
        ".领地",".领地保护",".领地密码 6位数字",
        ".查结构 结构名",".结构 结构名",".一键查询",".种子 种子号",".种子账号 账号 密码",".种子状态",
        ".导出 名称 X1 Y1 Z1 X2 Y2 Z2",".导入 名称 X Y Z",".打包",".打包文件",".打包所有文件",
        ".备份",".备份文件",".备份所有文件",".完整备份",
        ".生成兑换码 内容 有效期",".兑换 兑换码",
        ".积分版 计分板名称",".scoreboard 计分板名称",".积分 玩家",
        "AI 内容（公开AI）","ai 内容（私聊AI）","指令 内容（指令Agent）","AI Agent 内容（转发外部AI）",
        ".Agent 选择","输入编号（选中 AI Agent）",".Agent 配置 编号 接口地址 密钥 模型名",
        ".AI回显 公开","看不到AI回答时用它（也可用 私聊 / 都发）",
        ".Agent 当前",".AI agent 内容（用选中的模型回答）",".aiagent 内容",
        ".AI模型 Flash/V4 Pro",".AI切换 Flash/V4 Pro",".ai模型当前",".ai状态",".ai诊断",
        ".AI设定 内容",".ai设定 清除",".AI 修改所有AI设定 内容",".全服AI设定",
        ".全服AI设定 删除 编号",".AI 删除所有AI设定 编号",".AI 移除所有AI设定 编号",
        ".AI 清空所有AI设定",".AI 清除所有AI设定",".AI停止",".AI停止全部 玩家",
        ".清除记忆",".记忆清除","AI 清除记忆","ai 清除记忆",
        ".NBT测试 X Y Z",".nbt测试 X Y Z",".解释 内容",
        ".停止建筑",".停止建造",".关闭建筑模式",".建筑模式关闭",
        "+ / - 翻页"
    }
    local total=#all
    local per_page=13
    local max_page=math.max(1,math.ceil(total/per_page))
    page=math.max(1,math.min(page or 1,max_page))
    local first=(page-1)*per_page+1
    local last=math.min(total,first+per_page-1)
    local lines={
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
        "§1◆ §r§b§lDs 触发词 §8┃ §7第 "..page.." / "..max_page.." 页",
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
    }
    for i=first,last do table.insert(lines,"§f"..(i-first+1)..". §e"..all[i]) end
    table.insert(lines,"§8§m━━━━━━━━━━━━━━━━━━━━━━━━")
    table.insert(lines,"§7➜ §b+ §7下一页  §8┃ §b- §7上一页  §8┃ §f.stop §7退出")
    local d,r=player_record(name,true)
    set_menu(d,r,"trigger_words",{trigger_page=page})
    send(name,table.concat(lines,"\n"))
    return true
end

