        "§f• 普通聊天、指令、投票、兑换码等使用独立的AI窗口，互不混淆。\n" ..
        (admin and
            "§a• 你是管理权限：AI可查询在线玩家信息，并可根据请求实际执行Minecraft指令。\n" ..
            "§a• 管理权限还可使用封禁、解封、传送机会、兑换码等管理功能。\n"
        or
            "§7• 你是普通玩家：AI可以正常聊天、查询与你有关的游戏信息，并执行插件允许的玩家级操作。\n" ..
            "§7• 普通玩家不能通过AI执行管理权限专属的封禁、解封、权限管理等操作。\n") ..
        "§e提示：§f不需要执行操作时，AI就是普通聊天；需要操作时会直接调用插件能力。"
    send(name,text)
end

set_menu = function(d, record, mode, extra, reset_ttl)
    record.menu = mode
    if reset_ttl then
        record.menu_expires = util.timestamp() + (tonumber(reset_ttl) or MENU_TIMEOUT)
    elseif not record.menu_expires then
        record.menu_expires = util.timestamp() + MENU_TIMEOUT
    end
    if extra then for key, value in pairs(extra) do record[key] = value end end
    save_data(d)
end

clear_menu = function(d, record)
    record.menu = nil
    record.menu_expires = nil
    record.pending_slot = nil
    record.pending_target = nil
    record.pending_amount = nil
    save_data(d)
end

function coordinate_tp_state(record)
    local name = tostring(record and record.name or "")
    if name == "" then
        record.coordinate_tp = record.coordinate_tp or {}
        return record.coordinate_tp
    end
    local db = coord_soul_state_db()
    local p = coord_soul_state_player(db, name, record)
    local st = p.coordinate_tp
    local now = util.timestamp()
    local changed = false
    if not st.first_join_at then
        st.first_join_at=now; st.first_grant_at=now+COORD_TP_FIRST_DELAY; st.available=false; st.granted_once=false
        changed = true
    end
    if not st.granted_once and now >= (st.first_grant_at or math.huge) then
        st.available=true; st.granted_once=true; st.next_refresh_at=now+COORD_TP_INTERVAL; st.notified_available=false; changed = true
    end
    if st.granted_once and not st.available and now >= (st.next_refresh_at or math.huge) then
        st.available=true; st.next_refresh_at=now+COORD_TP_INTERVAL; st.notified_available=false; changed = true
    end
    record.coordinate_tp = st
    if changed then coord_soul_state_save(db) end
    return st
end
function coordinate_tp_use(name, dimname, x,y,z)
    local d,r=player_record(name,true); local st=coordinate_tp_state(r); local admin=is_admin(name)
    local db=coord_soul_state_db(); local p=coord_soul_state_player(db,name,r); st=p.coordinate_tp
    if not admin and not st.available then
        local extra=tonumber(st.extra_uses) or 0
        if extra>0 then st.extra_uses=extra-1; st.using_extra=true else
            pcall(game.sendCommand,'playsound random.anvil_land "'..string.gsub(name,'"','\\"')..'"')
            send(name,st.granted_once and "§c你当前没有坐标传送次数。§e现实24小时后刷新一次。" or "§c你还没有坐标传送机会。§e累计在线2小时后获得第一次机会。")
            coord_soul_state_save(db); return true
        end
    end
    local dim=normalize_dimension(dimname); x=tonumber(x); y=tonumber(y); z=tonumber(z)
    if not dim or not x or not y or not z then send(name,"§c格式无效。请输入：主世界 114 100 114\n§7也支持：下界/地狱、末地。"); return true end
    local safe=string.gsub(name,'"','\\"')
    local cmd=string.format('execute as @a[name="%s"] at @s in %s run tp @s %.2f %.2f %.2f',safe,dim_exec(dim),x,y,z)
    local ok,result=pcall(game.isCmdSuccess,cmd)
    if not ok or result~=true then
        send(name,"§c坐标传送指令执行失败，请检查维度和坐标。")
        append_json_log(TELEPORT_LOG_FILE,{at=util.timestamp(),type="坐标传送失败",player=name,player_uuid=uuid_key(name),dimension=dim,x=x,y=y,z=z})
        return true
    end
    if not admin and not st.using_extra then st.available=false; st.next_refresh_at=util.timestamp()+COORD_TP_INTERVAL; st.notified_available=false end
    local used_extra=st.using_extra==true; st.using_extra=false
    r.coordinate_tp=st
    coord_soul_state_save(db)
    pcall(save_data,d)
    append_json_log(TELEPORT_LOG_FILE,{at=util.timestamp(),type="坐标传送",player=name,player_uuid=uuid_key(name),dimension=dim,x=x,y=y,z=z,admin=admin,used_extra=used_extra,remaining_extra=tonumber(st.extra_uses) or 0,next_refresh_at=st.next_refresh_at})
    send(name,admin and "§a✓ 坐标传送成功。§7管理权限次数无限。" or "§a✓ 坐标传送成功。§7下一次机会将在现实24小时后刷新。")
    return true
end
function soul_actionbar(name, text)
    text=tostring(text or "")
    local ok=pcall(game.sendActionbar, name, text)
    if ok then return true end
    local safe=string.gsub(tostring(name or ""), '"', '\\"')
    local payload=json_rawtext(text)
    if payload then pcall(game.sendCommand, 'titleraw "'..safe..'" actionbar '..payload) end
    return false
end

function start_soul(name)
    local d,r=player_record(name,true)
    local db=coord_soul_state_db(); local p=coord_soul_state_player(db,name,r)
    local now=util.timestamp()
    if type(p.soul)=="table" and p.soul.return_at then
        local remain=math.max(0,math.ceil((tonumber(p.soul.return_at) or now)-now))
        send(name,"§e你已经处于灵魂出窍状态，剩余约"..tostring(remain).."秒。")
        return true
    end
    local cd=tonumber(p.soul_cooldown_until) or 0
    if cd>now then
        send(name,"§e灵魂出窍还在冷却中，请等待 "..tostring(math.ceil(cd-now)).." 秒。")
        return true
    end
    local loc,err=save_location(name)
    if not loc then send(name,"§c灵魂出窍失败："..tostring(err)); return true end
    local original_mode=detect_gamemode(name)
    local mode_ok=set_gamemode(name,"spectator")
    if not mode_ok then
        send(name,"§c灵魂出窍失败：无法切换到旁观模式，本次没有启动倒计时。")
        return true
    end
    p.soul={location=clone_saved_position(loc),original_mode=original_mode,return_at=now+SOUL_DURATION}
    coord_soul_state_save(db)
    send(name,"§d✦ 灵魂出窍已启动！\n§f已进入旁观模式，"..tostring(SOUL_DURATION).."秒后自动返回。\n§e中途退出：聊天框输入 .退出\n§7原游戏模式："..original_mode)
    soul_actionbar(name,"§d灵魂出窍 §f剩余 §e"..tostring(SOUL_DURATION).." §f秒")
    return true
end
function tick_coordinate_and_soul()
    local db=coord_soul_state_db(); local now=util.timestamp(); local names=online_names_from_list()
    if type(names)~="table" then return end
    local changed=false
    local legacy=nil
    for _,name in ipairs(names) do
        if name and tostring(name)~="" then
            local n=tostring(name)
            if not db.players[n] then
                if not legacy then legacy=load_data() end
                local key=identity(n); local rec=legacy.players and legacy.players[key]
                coord_soul_state_player(db,n,rec)
                changed=true
            end
            local p=coord_soul_state_player(db,n,nil)
            local st=p.coordinate_tp
            if not st.first_join_at then
                st.first_join_at=now; st.first_grant_at=now+COORD_TP_FIRST_DELAY; st.available=false; st.granted_once=false; changed=true
            end
            if not st.granted_once and now >= (st.first_grant_at or math.huge) then
                st.available=true; st.granted_once=true; st.next_refresh_at=now+COORD_TP_INTERVAL; st.notified_available=false; changed=true
            elseif st.granted_once and not st.available and now >= (st.next_refresh_at or math.huge) then
                st.available=true; st.next_refresh_at=now+COORD_TP_INTERVAL; st.notified_available=false; changed=true
            end
            if st.available and not st.notified_available then
                send(n,[[§a✦ 你的坐标传送机会已刷新！§f输入 .tp 使用。
§7管理权限不受次数限制。]])
                st.notified_available=true; changed=true
            end
            local last=tonumber(p.last_tick)
            local delta=last and math.max(0,math.min(now-last,30)) or 0
            p.last_tick=now
            p.playtime_seconds=(tonumber(p.playtime_seconds) or 0)+delta
            changed=true
            p.signin=p.signin or {available=false}
            if not p.signin.first_ready_at and p.playtime_seconds>=7200 then
                p.signin.first_ready_at=now; p.signin.available=true; p.signin.next_at=now+DAILY_SIGNIN_INTERVAL
                send(n,"§6✦ 签到已解锁！§f输入 .签到 领取今日奖励。")
            elseif p.signin.first_ready_at and not p.signin.available and now >= (p.signin.next_at or math.huge) then
                p.signin.available=true; p.signin.next_at=now+DAILY_SIGNIN_INTERVAL
                send(n,"§6✦ 今日签到已刷新！§f输入 .签到 领取奖励。")
            end
            if type(p.soul)=="table" and p.soul.return_at then
                local remain=tonumber(p.soul.return_at)-now
                local shown=math.max(0,math.ceil(remain))
                if remain>0 then
                    soul_actionbar(n,string.format("§d灵魂出窍 §f剩余 §e%d §f秒",shown))
                    if shown==10 or shown<=5 then
                        send(n,string.format("§d灵魂出窍 §f剩余 §e%d §f秒",shown))
                    end
                else
                    local loc=clone_saved_position(p.soul.location); local original=p.soul.original_mode or "survival"
                    p.soul=nil
                    p.soul_cooldown_until=now+SOUL_COOLDOWN
                    soul_actionbar(n,"§a灵魂出窍结束 §7冷却30秒")
                    local ok2,err2=tp_to(n,loc); local mode_ok=set_gamemode(n,original)
                    if ok2 and mode_ok then send(n,"§a✓ 灵魂出窍结束，已自动返回原位置并恢复原模式。")
                    elseif ok2 then send(n,"§e✓ 已返回原位置，但恢复原游戏模式失败，请手动切换回："..original)
                    else send(n,"§c灵魂出窍返回失败："..tostring(err2).."；原游戏模式恢复："..(mode_ok and "成功" or "失败")) end
                    send(n,"§7灵魂出窍冷却已开始：30秒后可再次使用。")
                    changed=true
                end
            elseif (tonumber(p.soul_cooldown_until) or 0)>now then
                local cd=math.ceil((tonumber(p.soul_cooldown_until) or 0)-now)
                if cd<=5 or cd==30 then soul_actionbar(n,"§7灵魂出窍冷却 §e"..tostring(cd).." §7秒") end
            end
        end
    end
    if changed then coord_soul_state_save(db) end
end
function scoreboard_name()
    local cfg=file_load(SCOREBOARD_CONFIG_FILE,{})
    local board=trim(cfg.name or "")
    if board~="" then return board end
    local d=load_data(); return d.scoreboard_name
end

function valid_scoreboard_name(name)
    return type(name) == "string" and name:match("^[A-Za-z0-9_%-]+$") ~= nil and #name <= 32
end

function save_scoreboard_name(name,board)
    board=trim(board)
    local d=load_data(); d.scoreboard_name=board; d.scoreboard_set_by=name; d.scoreboard_set_at=util.now(); d.scoreboard_created=true; save_data(d)
    file_save(SCOREBOARD_CONFIG_FILE,{name=board,set_by=name,set_at=util.now()})
    pcall(game.isCmdSuccess,"scoreboard objectives add "..board.." dummy")
end

