        local target=r.pending_target
        clear_menu(d,r)
        local td,tr=player_record(target,true)
        local coord_db=coord_soul_state_db(); local tp_state=coord_soul_state_player(coord_db,target,tr).coordinate_tp
        tp_state.extra_uses=(tonumber(tp_state.extra_uses) or 0)+amount
