                send(name, "§c第 " .. n .. " 个传送点还没有创建。")
            else
                send(name, "§e正在传送到「" .. wp.name .. "」……")
                local ok, err = tp_to(name, wp)
                send(name, ok and "§a✓ 传送成功！" or "§c传送失败：" .. tostring(err))
            end
        else
            r.menu = nil
            save_data(d)
            if not wp or not wp.name then
                send(name, "§c第 " .. n .. " 个传送点为空，无法删除。")
            else
                local old = wp.name
                wp_delete(r,n)
                save_data(d)
                send(name, "§a✓ 已删除传送点「" .. old .. "」。")
            end
        end
        return true
    end

    return false
end


POS_SENTINELS = {
    ["0,0,0"] = true, ["0,-1,0"] = true, ["0,-2,0"] = true,
    ["0,-3,0"] = true, ["0,-64,0"] = true,
    ["1,72,5"] = true, ["1,71,5"] = true, ["9,67,17"] = true,
    ["1008,66,96"] = true, ["1008,67,96"] = true, ["1008,68,96"] = true,
}

local function pos_is_sentinel(x, y, z)
    local key = string.format("%d,%d,%d",
        math.floor(tonumber(x) or 0), math.floor(tonumber(y) or 0), math.floor(tonumber(z) or 0))
    return POS_SENTINELS[key] == true
end

local function death_position_valid_light(pos)
    if type(pos)~="table" then return false end
    local x,y,z=tonumber(pos.x),tonumber(pos.y),tonumber(pos.z)
    if x==nil or y==nil or z==nil then return false end
    if x==0 and y==0 and z==0 then return false end
    if pos_is_sentinel(x,y,z) then return false end   -- ★ 修复：拒绝哨兵值(0,-2,0 等)
    if y<-64 or y>320 then return false end           -- ★ 修复：Y 越界保护
    return true
end

DEATH_TRACK_FILE = game.dataDir() .. "/death_lastpos.json"

local function load_death_track()
    local ok, d = pcall(util.json_load, DEATH_TRACK_FILE)
    if not ok or type(d) ~= "table" then d = {} end
    d.pos = d.pos or {}        -- key(xuid 或玩家名) -> {x,y,z,dimension,name,at}
    d.pid2name = d.pid2name or {} -- pid(unique_id) -> 玩家名
    return d
end

local function save_death_track(d)
    pcall(util.json_write, DEATH_TRACK_FILE, d)
end

local function choose_death_pos(list)
    local best, best_at = nil, -1
    for _, p in ipairs(list) do
        if death_position_valid_light(p) then
            local at = tonumber(p.at) or 0
            if at >= best_at then best, best_at = p, at end
        end
    end
    return best
end

local DEATH_WRITE_ALLOWED = { pyrpc32 = true, entity_fallback = true }

local function save_death_point_light(name,loc,reason)
    reason = reason or "pyrpc32"
    if not DEATH_WRITE_ALLOWED[reason] then            -- ★ 修复：拒绝非权威来源
        log_event("DEATH", "拒绝非权威来源写入死亡点: reason=" .. tostring(reason) ..
                          " player=" .. tostring(name))
        return false
    end
    if not death_position_valid_light(loc) then return false end
    local d=load_data(); local key,info=identity(name); d.players=d.players or {}
    local r=d.players[key]
    if not r then
        r={xuid=info.xuid or "",unique_id=info.unique_id or "",name=name,waypoints={},death=nil}
        d.players[key]=r
    end
    r.name=name
    local dim=normalize_dimension(loc.dimension) or normalize_dimension((get_info(name) or {}).dimension) or "overworld"
    r.death={x=math.floor(tonumber(loc.x)),y=math.floor(tonumber(loc.y)),z=math.floor(tonumber(loc.z)),dimension=dim,saved_at=beijing_now(),saved_ts=now_utc_ts(),reason=reason or "pyrpc"}
    r.last_death_capture=util.timestamp()
    r.death_count=(tonumber(r.death_count) or 0)+1
    r.last_pos={x=r.death.x,y=r.death.y,z=r.death.z,dimension=dim,at=util.timestamp()}
    r.death_history=r.death_history or {}
    table.insert(r.death_history,{x=r.death.x,y=r.death.y,z=r.death.z,dimension=dim,saved_at=r.death.saved_at,saved_ts=now_utc_ts(),reason=r.death.reason})
    while #r.death_history>10 do table.remove(r.death_history,1) end
    d.death_capture_pending=d.death_capture_pending or {}
    d.death_capture_pending[name]=nil
    save_data(d)
    local ok_n, n_err = pcall(function()
        local cost = death_tp_cost()
        local sepline = "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
        local lines = {
            sepline,
            "§1◆ §r§b§l死亡点已记录 §8┃ §7这是第 §e§l" .. tostring(r.death_count) .. " §r§7次",
            string.format("§7坐标 §8▸ §f§l%d §7/ §f§l%d §7/ §f§l%d §8[§b%s§8]",
                r.death.x, r.death.y, r.death.z, dimension_display(dim)),
            sepline,
        }
        if cost > 0 then
            if bal ~= nil then
                lines[#lines + 1] = "§6§l⚑ §r§7传送费用 §8▸ §6§l" .. cost .. " §r§7积分 §8| §7当前 §a§l" .. bal ..
                    (tonumber(bal) and tonumber(bal) >= cost and " §a§l✔" or " §c§l✘ 不足" or "")
            else
                lines[#lines + 1] = "§6§l⚑ §r§7传送费用 §8▸ §6§l" .. cost .. " §r§7积分 §8（未设置积分板）"
            end
        else
            lines[#lines + 1] = "§6§l⚑ §r§7本次传送 §a§l免费"
        end
        lines[#lines + 1] = "§7查看记录 §8▸ §b§l.死亡日志 §r§8（再输入 §b1~5 §8传送）"
        lines[#lines + 1] = "§7直接回点 §8▸ §f.死亡点返回 §r§8（可带序号，如 §f.死亡点返回 2§8）"
        lines[#lines + 1] = "§a死亡点已保存，可稍后回来；回点费用 §e" .. tostring(cost) .. " §a积分。"
        lines[#lines + 1] = sepline
        send(name, table.concat(lines, "\n"))
    end)
    log_event("DEATH", string.format("%s 死亡 #%d %s reason=%s",
        name, tonumber(r.death_count) or 0, posdesc, tostring(reason or "v6")))
    if not ok_n then
        log_event("DEATH", "死亡提示渲染失败：" .. tostring(n_err))
        pcall(send, name, string.format(
            "§1◆ §r§b§l死亡点已记录 §8┃ §f%d %d %d §8[%s]\n§7输入 §b.死亡日志 §7查看并传送",
            tonumber(r.death_count) or 0, r.death.x, r.death.y, r.death.z, dimension_display(dim)))
    end
    local _tk = load_death_track()
    _tk.last_death_coord = _tk.last_death_coord or {}
    _tk.last_death_coord[name] = { at = util.timestamp(),
        coord = string.format("%d,%d,%d", r.death.x, r.death.y, r.death.z) }
    _tk.dead_at = _tk.dead_at or {}
    _tk.dead_at[name] = util.timestamp()
    save_death_track(_tk)
    return true
end

local PYRPC_CODE_DEATH = 22
local PYRPC_CODE_DEATH_ALT = {22, 23, 32}
local PYRPC_CODE_POS = 21
local PYRPC_CODE_POS_ALT = {21, 22, 23, 43}
local PYRPC_CODE_NOISE = 11
local EYE_HEIGHT = 1.62   -- 框架缓存的 y 是眼睛高度，脚部坐标 = y - 1.62


local PYRPC_MAX_DEPTH = 4

local function pyrpc_extract(inner, depth)
    if type(inner) ~= "table" then return nil, nil end
    depth = depth or 0
    local second = inner[2]
    if type(second) == "table" and second.die ~= nil then
        local real = tonumber(inner[1])
        return (real ~= nil and real or PYRPC_CODE_DEATH), second
    end
    if type(inner[1]) == "number" then
        return inner[1], second
    end
    if depth < PYRPC_MAX_DEPTH then
        for _, k in ipairs({ 2, "c", 1 }) do
            local nxt = inner[k]
            if type(nxt) == "table" then
                local c, p = pyrpc_extract(nxt, depth + 1)
                if c ~= nil then return c, p end
            end
        end
    end
    return nil, nil
end

local function pyrpc_inner(data)
    if type(data) ~= "table" then return nil, nil end
    local v = data.value
    if type(v) ~= "table" then
        if type(data.die) == "boolean" then return PYRPC_CODE_DEATH, data end
        return nil, nil
    end
    if v.die ~= nil then return PYRPC_CODE_DEATH, v end
    local c1, p1 = pyrpc_extract(v[2], 0)
    if c1 ~= nil then return c1, p1 end
    local c2, p2 = pyrpc_extract(v["c"], 0)
    if c2 ~= nil then return c2, p2 end
    return nil, nil
end

local function pyrpc_pid(payload)
    if type(payload) ~= "table" then return nil end
    local pid = payload.pid
    if pid == nil then pid = payload.id end
    if pid == nil then pid = payload.uuid end
    return pid
end

function pos_cache_key(name)
    local info = get_info(name)
    if info and type(info.xuid) == "string" and info.xuid ~= "" then return info.xuid end
    return name
end

POS_CACHE_WRITE_MIN_INTERVAL = 3.0
function pos_cache_set(name, pos, src, force)
    if not name or name == "" or type(pos) ~= "table" then return end
    local x, y, z = tonumber(pos.x), tonumber(pos.y), tonumber(pos.z)
    if x == nil or y == nil or z == nil then return end
    if x == 0 and z == 0 then return end              -- 拒绝世界原点占位
    if pos_is_sentinel(x, y, z) then return end        -- 拒绝哨兵值
    if y < -64 or y > 320 then return end              -- Y 越界保护

    src = src or pos.src or "fw"
    local entry = {
        x = x, y = math.floor(y), z = z,
        dimension = normalize_dimension(pos.dimension) or "overworld",
        name = name, at = util.timestamp(), src = src,
    }
    if type(RUNTIME) ~= "table" then RUNTIME = {} end
    RUNTIME.last_pos = RUNTIME.last_pos or {}
    RUNTIME.last_pos[name] = entry
    local tk = load_death_track()
    local field = (src == "fw") and "pos_fw" or "pos_pkt"
    tk[field] = tk[field] or {}
    local tbl = tk[field]
    local k = pos_cache_key(name)
    local old = tbl[k]
    if old then
        local age = (tonumber(entry.at) or 0) - (tonumber(old.at) or 0)
        local same = math.abs((tonumber(old.x) or 0)-x)<0.35
            and math.abs((tonumber(old.y) or 0)-math.floor(y))<1
            and math.abs((tonumber(old.z) or 0)-z)<0.35
        if not force and age < POS_CACHE_WRITE_MIN_INTERVAL then
            local moved = math.abs((tonumber(old.x) or 0)-x) + math.abs((tonumber(old.y) or 0)-math.floor(y)) + math.abs((tonumber(old.z) or 0)-z)
            if same or moved < 4 then return end
        end
    end
    tbl[k] = entry
    if k ~= name then tbl[name] = entry end
    save_death_track(tk)
end

function pos_cache_get(name, want_src)
    if not name or name == "" then return nil end
    local tk = load_death_track()
    local k = pos_cache_key(name)
    local order = { "pos_pkt", "pos_fw", "pos" }
    if want_src == "pkt" then order = { "pos_pkt", "pos" } end
    local e = nil
    local e_src = "disk_cache"
    for _, field in ipairs(order) do
        local t = tk[field]
        if type(t) == "table" then
            local cand = t[k] or t[name]
            if type(cand) == "table" then
                local cx, cy, cz = tonumber(cand.x), tonumber(cand.y), tonumber(cand.z)
                if cx and cy and cz and not pos_is_sentinel(cx, cy, cz) and cy >= -64 and cy <= 320 then
                    e = cand
                    e_src = (field == "pos_pkt") and "pkt" or ((field == "pos_fw") and "fw" or "disk_cache")
                    break
                end
            end
        end
    end
    if type(e) == "table" then
        local x, y, z = tonumber(e.x), tonumber(e.y), tonumber(e.z)
        if x and y and z and not pos_is_sentinel(x, y, z) and y >= -64 and y <= 320 then
            return { x = x, y = y, z = z,
                     dimension = e.dimension or "overworld",
                     at = tonumber(e.at) or 0, src = e_src }
        end
    end
    if type(RUNTIME) == "table" and type(RUNTIME.last_pos) == "table" then
        local m = RUNTIME.last_pos[name]
        if type(m) == "table" and death_position_valid_light(m) then
            m.src = "mem_cache"
            return m
        end
    end
    return nil
end

local function resolve_player_by_pid(pid)
    if pid == nil then return nil end
    local pid_str = tostring(pid)
    local track = load_death_track()
    local nm = (track.pid2name or {})[pid_str]
    if nm and nm ~= "" then return nm end
    for xuid, v in pairs(track.pos or {}) do
        if type(v) == "table" then
            if tostring(v.pid or "") == pid_str then return v.name end
            if tostring(v.unique_id or "") == pid_str then return v.name end
            if tostring(v.xuid or "") == pid_str then return v.name end
            if tostring(xuid) == pid_str then return v.name end
            if tostring(v.name or "") == pid_str then return v.name end
        end
    end
    local ok, list = pcall(player.list)
    if ok and type(list) == "table" then
        for _, p in ipairs(list) do
            if type(p) == "table" then
                if tostring(p.unique_id or "") == pid_str then return p.name end
                if tostring(p.xuid or "") == pid_str then return p.name end
                if tostring(p.name or "") == pid_str then return p.name end
            end
        end
    end
    return nil
end

local function note_player_pos(name, pid, x, y, z, dimension, feet_already)
    if not name or name == "" then return end
    x, y, z = tonumber(x), tonumber(y), tonumber(z)
    if not x or not y or not z then return end
    if x == 0 and y == 0 and z == 0 then return end
    if pos_is_sentinel(x, y, z) then return end        -- ★ 修复：哨兵值不落盘
    if not feet_already then y = math.floor(y - EYE_HEIGHT) end
    if pos_is_sentinel(x, y, z) then return end        -- ★ 换算是脚部坐标后再校验
    local track = load_death_track()
    track.pos = track.pos or {}
    track.pid2name = track.pid2name or {}
    local info = get_info(name)
    local xuid = (info and type(info.xuid) == "string" and info.xuid ~= "") and info.xuid or name
    local dim = normalize_dimension(dimension) or "overworld"
    local changed = false
    local now = util.timestamp()
    local old = track.pos[xuid]
    if old and (tonumber(old.at) or 0) > now then return end
    if (not old)
        or math.abs((tonumber(old.x) or 0) - x) >= 0.5
        or math.abs((tonumber(old.y) or 0) - y) >= 0.5
        or math.abs((tonumber(old.z) or 0) - z) >= 0.5
        or normalize_dimension(old.dimension) ~= dim then
        track.pos[xuid] = {x = x, y = y, z = z, dimension = dim, name = name, at = now,
                           xuid = xuid, pid = pid and tostring(pid) or nil}
        changed = true
    end
    if pid ~= nil and track.pid2name[tostring(pid)] ~= name then
        track.pid2name[tostring(pid)] = name
        changed = true
    end
    if changed then save_death_track(track) end
end


function on_pyrpc(data)
    if type(data) ~= "table" then return end
    local code, payload = pyrpc_inner(data)
    if code == PYRPC_CODE_NOISE then return end
    if type(payload) ~= "table" or payload.die == nil then
        local p=ds_pyrpc_die(f,0)
        if type(p)=="table" and p.die~=nil then payload=p else return end
    end
    local pid=pyrpc_pid(payload)
    local name=resolve_player_by_pid(pid)
    if not name or name=="" then return end
    if payload.die == true then
        ds_death_record(name,"pyrpc")
    else
        log_event("DEATH",name.." 重生")
    end
end

DEATH_DEDUP_SEC = 3
DEATH_DEDUP_FILE = game.dataDir() .. "/death_dedup.json"

function death_dedup_load()
    local ok, d = pcall(util.json_load, DEATH_DEDUP_FILE)
    if not ok or type(d) ~= "table" then d = {} end
    return d
end

function death_dedup_hit(name, window_sec)
    if not name or name == "" then return false end
    local d = death_dedup_load()
    local now = util.timestamp()
    local last = tonumber(d[name]) or 0
    if (now - last) < (window_sec or 3) then
        return true
    end
    d[name] = now
    for k, v in pairs(d) do
        if (now - (tonumber(v) or 0)) > 3600 then d[k] = nil end
    end
    pcall(util.json_write, DEATH_DEDUP_FILE, d)
    return false
end

DEATH_FALLBACK_INTERVAL = 3
function alive_state_get(name)
    local tk = load_death_track()
    local v = tk.alive and tk.alive[name]
    if v == nil then return nil end
    return v == true
end

function alive_state_set(name, alive)
    local tk = load_death_track()
    tk.alive = tk.alive or {}
    tk.alive[name] = alive and true or false
    save_death_track(tk)
end

function tick_death_fallback()
    if type(RUNTIME) ~= "table" then RUNTIME = {} end
    RUNTIME.last_pos = RUNTIME.last_pos or {}
    local track = load_death_track()
    local changed = false
    local ok_list, list = pcall(player.list)
    if ok_list and type(list) == "table" then
        for _, p in ipairs(list) do
            if type(p) == "table" and p.name and p.x ~= nil and p.y ~= nil and p.z ~= nil then
                local x, y, z = tonumber(p.x), tonumber(p.y), tonumber(p.z)
                if x and y and z and not (x == 0 and y == 0 and z == 0) then
                    local feet = math.floor(y - EYE_HEIGHT)
                    local dim = normalize_dimension(p.dimension) or "overworld"
                    pos_cache_set(p.name, {x = x, y = feet, z = z, dimension = dim}, "fw")
                    local key = (type(p.xuid) == "string" and p.xuid ~= "") and p.xuid or p.name
                    local old = track.pos[key]
                    if (not old)
                        or math.abs((tonumber(old.x) or 0) - x) >= 0.5
                        or (tonumber(old.y) == nil)
                        or math.floor(tonumber(old.y) or -99999) ~= feet
                        or math.abs((tonumber(old.z) or 0) - z) >= 0.5
                        or normalize_dimension(old.dimension) ~= dim then
                        track.pos[key] = {x = x, y = feet, z = z, dimension = dim, name = p.name, at = util.timestamp()}
                        changed = true
                    end
                    if p.unique_id ~= nil then
                        local pk = tostring(p.unique_id)
                        if track.pid2name[pk] ~= p.name then
                            track.pid2name[pk] = p.name
                            changed = true
                        end
                    end
                end
            end
        end
    end

    local now = util.timestamp()
    if (now - (tonumber(track.alive_check_at) or 0)) >= 3 then
        track.alive_check_at = now
        changed = true
        local names = online_names_from_list() or {}
        for _, name in ipairs(names) do
            if name then
                local alive = is_alive_entity(name)
                local prev = alive_state_get(name)   -- ★本次修改★ 落盘读取
                if prev == true and alive == false then
                    local pos = pos_cache_get(name)   -- ★本次修改★ 优先读落盘
                    if death_position_valid_light(pos) then
                        local d = load_data()
                        local r = d.players and d.players[identity(name)]
                        local recent = r and tonumber(r.last_death_capture) or 0
                        if (now - recent) > 8 then
                            save_death_point_light(name, pos, "entity_fallback")
                        end
                    end
                end
                alive_state_set(name, alive)   -- ★本次修改★ 落盘写入
            end
        end
    end

    if changed then save_death_track(track) end
end


function ai_stop_chat(name, msg)
    msg=trim(msg or "")
    local low=lower(msg)
    if low==".AI停止全部" or low==".ai停止全部" then
        if not is_admin(name) then send(name,"§c只有管理权限可以停止他人 AI 任务。"); return true end
        local target=trim(msg:match("^%.AI停止全部%s+(.+)$") or msg:match("^%.ai停止全部%s+(.+)$") or "")
        if target=="" then
            send(name,"§c用法：.AI停止全部 <玩家名>")
        else
            ai_stop_set(target,"管理权限强制停止")
            send(name,"§a已停止 "..target.." 的 AI 任务。")
            send(target,"§c管理权限已强制停止你的 AI 任务。")
        end
        return true
    end
    if low==".AI停止" or low==".ai停止" then
        ai_stop_set(name,"玩家手动停止")
        send(name,"§a已请求停止你的 AI 任务；当前任务将在下一轮或下一条指令前中止。")
        return true
    end
    return false
end

CHAT_RATE_FILE = game.dataDir() .. "/chat_rate.json"
_CHAT_RATE_CACHE = nil
_CHAT_RATE_DIRTY = 0
_CHAT_RATE_SIG   = nil

function chat_rate_db()
    if _CHAT_RATE_CACHE then return _CHAT_RATE_CACHE end
    local ok,d=pcall(util.json_load,CHAT_RATE_FILE)
    if ok and type(d)=="table" then
        d.rate=d.rate or {}; d.mutes=d.mutes or {}; d.state=d.state or {}
        _CHAT_RATE_CACHE=d
        return d
    end
    local old=load_data()
    local fresh={rate=old.chat_rate or {},mutes=old.chat_mutes or {},state=old.chat_mute_state or {}}
    pcall(util.json_write,CHAT_RATE_FILE,fresh)
    _CHAT_RATE_CACHE=fresh
    return fresh
end

function chat_rate_flush(force)
    if not _CHAT_RATE_CACHE then return end
    pcall(util.json_write, CHAT_RATE_FILE, _CHAT_RATE_CACHE)
    _CHAT_RATE_DIRTY = 0
end

local function _mute_sig(d)
    local n, s = 0, 0
    for _, v in pairs(d.mutes or {}) do
        n = n + 1
        s = s + (tonumber(v) or 0)
    end
    return n .. ":" .. tostring(s % 100000000)
end

function chat_rate_save(d)
    _CHAT_RATE_CACHE = d or _CHAT_RATE_CACHE
    _CHAT_RATE_DIRTY = (_CHAT_RATE_DIRTY or 0) + 1
    local sig = _mute_sig(_CHAT_RATE_CACHE or {})
    if sig ~= _CHAT_RATE_SIG then
        _CHAT_RATE_SIG = sig
        chat_rate_flush(true)      -- 禁言状态变了，立刻写
        return
    end
    if _CHAT_RATE_DIRTY >= 20 then chat_rate_flush(true) end   -- 频率计数攒够再写
end

function op_status(name)
    local ok, r = pcall(player.isOP, name)
    if ok and r ~= nil then return r == true end
    local ok2, info = pcall(get_info, name)
    if ok2 and type(info) == "table" and info.is_op ~= nil then return info.is_op == true end
    return nil
end

function mute_exempt_load()
    local t = {}
    local ok, d = pcall(util.json_load, MUTE_EXEMPT_FILE)
    if ok and type(d) == "table" then
        for k, v in pairs(d) do if v then t[tostring(k)] = true end end
    end
    local seeded = false
    for k in pairs(MUTE_EXEMPT_SEED or {}) do
        if not t[k] then t[k] = true; seeded = true end
    end
    MUTE_EXEMPT = t
    _MUTE_EXEMPT_READY = true
    if seeded then mute_exempt_save() end
    return t
end
function mute_exempt_save() pcall(util.json_write, MUTE_EXEMPT_FILE, MUTE_EXEMPT or {}) end
function mute_exempt_list()
    local out = {}
    for k in pairs(MUTE_EXEMPT or {}) do out[#out + 1] = tostring(k) end
    table.sort(out)
    return out
end
function mute_exempt_toggle(name, nm)
    if not (is_admin(name) or (MUTE_EXEMPT and MUTE_EXEMPT[name])) then
        send(name, "§c仅管理权限。"); return true
    end
    nm = trim(tostring(nm or ""))
    if nm == "" then
        send(name, "§e用法：§f.豁免 <玩家名> §7（再加一次=取消）\n§7当前名单：§f"
                   .. table.concat(mute_exempt_list(), "、"))
        return true
    end
    mute_exempt_load()
    if MUTE_EXEMPT[nm] then MUTE_EXEMPT[nm] = nil else MUTE_EXEMPT[nm] = true end
    mute_exempt_save()
    send(name, "§a豁免名单已更新：§f" .. table.concat(mute_exempt_list(), "、"))
    return true
end

MUTE_CFG = nil
function mute_cfg_file() return (game.dataDir() or "") .. "/mute_cfg.json" end
function mute_cfg()
    if MUTE_CFG then return MUTE_CFG end
    local t = {
        burst     = tonumber(CHAT_MUTE_BURST) or 20,
        throttle  = tonumber(CHAT_MUTE_BURST_THROTTLE) or 2,
        gthrottle = tonumber(CHAT_MUTE_GLOBAL_THROTTLE) or 2,
    }
    local ok, d = pcall(util.json_load, mute_cfg_file())
    if ok and type(d) == "table" then
        if tonumber(d.burst)     then t.burst = tonumber(d.burst) end
        if tonumber(d.throttle)  then t.throttle = tonumber(d.throttle) end
        if tonumber(d.gthrottle) then t.gthrottle = tonumber(d.gthrottle) end
    end
    MUTE_CFG = t
    return t
end
function mute_cfg_save() pcall(util.json_write, mute_cfg_file(), MUTE_CFG or {}) end

function muted_players()
    local out = {}
    local d = chat_rate_db()
    if type(d) ~= "table" then return out end
    local now = util.timestamp()
    for nm, v in pairs(d.mutes or {}) do
        local t = tonumber(v) or 0
        if t < 0 or t > now then out[#out + 1] = tostring(nm) end
    end
    return out
end

function mute_burst_all()
    do return 0 end -- 禁言系统已移除
    local list = muted_players()
    if #list == 0 then return 0 end
    if not _MUTE_EXEMPT_READY then mute_exempt_load() end
    local n = 0
    for _, nm in ipairs(list) do
        if not MUTE_EXEMPT[nm] then
            if mute_burst(nm) then n = n + 1 end
        end
    end
    return n
end

function blackbox_diag(name)
    local d = chat_rate_db()
    local now = util.timestamp()
    local muted = false
    for p, v in pairs(d.mutes or {}) do
        if tostring(p) == tostring(name) then
            local t = tonumber(v) or 0
            if t < 0 or t > now then muted = true end
        end
    end
    local safe = string.gsub(tostring(name or ""), '"', '\\"')
    pcall(game.sendCommand, 'titleraw "' .. safe .. '" clear')
    pcall(game.sendCommand, 'titleraw "' .. safe .. '" reset')
    pcall(game.sendCommand, 'scoreboard objectives setdisplay sidebar')
    pcall(game.sendCommand, 'scoreboard objectives setdisplay list')
    pcall(game.sendCommand, 'scoreboard objectives setdisplay belowname')
    local s = "黑框排查（" .. tostring(name) .. "）：你在禁言名单=" .. (muted and "是" or "否")
              .. "；已清 title 与三个计分板显示位。"
              .. "本插件没有常驻黑框能力（源码里没有 titleraw/bossbar/setdisplay 调用）。"
    send(name, "§b" .. s)
    pcall(ai_agent_forward, name, "[黑框排查] " .. s, nil)
    return true
end

function perm_selfcheck(name)
    local ok, s = pcall(function()
        local ok_op, r_op = pcall(player.isOP, name)
        local ok_gi, info = pcall(get_info, name)
        local ok_pm, pms = pcall(agent_all_options)
        local ok_pk, pick = pcall(agent_load_pick)
        return "权限自检｜" .. tostring(name)
            .. "｜is_admin=" .. tostring(is_admin(name))
            .. "｜player.isOP=" .. tostring(r_op) .. "(pcall=" .. tostring(ok_op) .. ")"
            .. "｜get_info.is_op=" .. tostring((ok_gi and type(info) == "table") and info.is_op or "nil")
            .. "｜SUPERUSER=" .. tostring(SUPERUSER)
            .. "｜AI Agent选项数=" .. tostring((ok_pm and type(pms) == "table") and #pms or "nil")
            .. "｜已选模型=" .. tostring((ok_pk and type(pick) == "table") and (pick.label or pick.model_id) or "无")
    end)
    local msg = "[权限自检] " .. (ok and s or ("自检本身报错：" .. tostring(s)))
    pcall(send, name, "§b" .. msg)
    local fok, ferr = pcall(ai_agent_forward, name, msg, nil)
    if not fok then pcall(send, name, "§c转发也失败：" .. tostring(ferr)) end
    return true
end

function chat_rate_record(playerName)
    do return false end -- 禁言系统已移除
    if is_admin(playerName) then return false end
    if not _MUTE_EXEMPT_READY then mute_exempt_load() end
    if MUTE_EXEMPT and MUTE_EXEMPT[playerName] then return false end
    local _ok_info, _info = pcall(get_info, playerName)
    if _ok_info and type(_info)=="table" and _info.is_op then return false end
    if op_status(playerName) == nil then return false end

    local d=chat_rate_db()
    local now=util.timestamp()

    local state=d.state[playerName]
    if type(state)~="table" or now-(tonumber(state.window_start) or 0)>=CHAT_MUTE_RESET then
        state={window_start=now, level=0}
        d.state[playerName]=state
    end

    local muted_until=tonumber(d.mutes[playerName] or 0) or 0
    if muted_until<0 or muted_until>now then
        chat_rate_save(d)
        mute_burst(playerName)
        return true
    end
    if muted_until>0 then d.mutes[playerName]=nil end

    local list=d.rate[playerName] or {}
    local kept={}
    for _,t in ipairs(list) do
        if now-t < CHAT_RATE_WINDOW then table.insert(kept,t) end
    end
    table.insert(kept,now)
    d.rate[playerName]=kept

    if #kept > CHAT_RATE_LIMIT then
        state.level=math.min((tonumber(state.level) or 0)+1, #MUTE_LEVELS+1)
        local seconds=MUTE_LEVELS[state.level] or 18000 -- 第6次起封顶5小时
        d.mutes[playerName]=now+seconds
        d.rate[playerName]={}
        chat_rate_save(d)
        pcall(game.sendCommand,'tag "'..string.gsub(playerName,'"','\\"')..'" add 禁言')
        local mins=math.floor(seconds/60)
        local label=mins<60 and (tostring(seconds).."秒") or (tostring(math.floor(mins/60)).."小时")
        send(playerName,"§c频率过快，已禁言 "..label.."。第"..tostring(state.level).."次违规；24小时后等级重置。")
        pcall(game.sendActionbar,playerName,"§c频率过快，已禁言 "..label)
        mute_burst(playerName)
        return true
    end
    chat_rate_save(d)
    return false
end

function tick_chat_mute()
    MUTE_DIAG.ticks2 = (MUTE_DIAG.ticks2 or 0) + 1
    local d=chat_rate_db()
    local now=util.timestamp()
    local changed=false

    for name,state in pairs(d.state) do
        if type(state)=="table" and now-(tonumber(state.window_start) or 0)>=CHAT_MUTE_RESET then
            d.state[name]=nil
            d.rate[name]=nil
            changed=true
        end
    end

    for name,until_at in pairs(d.mutes) do
        until_at=tonumber(until_at) or 0
        if until_at>=0 and until_at<=now then
            d.mutes[name]=nil
            d.rate[name]=nil
            pcall(game.sendCommand,'tag "'..string.gsub(name,'"','\\"')..'" remove 禁言')
            send(name,"§a禁言已解除，可以正常发言。")
            changed=true
        end
    end
    if changed then chat_rate_save(d) end
end

function muted_anyone()
    do return false end -- 禁言系统已移除
    local d = chat_rate_db()
    if type(d) ~= "table" then return true end -- 读不到就按老行为发包（fail-safe）
    local m = d.mutes
    if type(m)~="table" then return false end
    local now=util.timestamp()
    for _,v in pairs(m) do
        local t=tonumber(v) or 0
        if t<0 or t>now then return true end
    end
    return false
end

MUTE_DIAG = {ticks=0, cmds=0, t0=0}

function tick_chat_mute_fast()
    do return end -- 禁言系统已移除
    MUTE_DIAG.ticks = MUTE_DIAG.ticks + 1
    if MUTE_DIAG.t0 == 0 then MUTE_DIAG.t0 = util.timestamp() end
    if not muted_anyone() then return end
    local cmd='execute as @a[tag=禁言] run tellraw @s {"rawtext":[]}'
    local burst = tonumber(CHAT_MUTE_BURST) or 1
    if burst < 1 then burst = 1 end
    for _ = 1, burst do
        pcall(game.sendCommand, cmd)
        MUTE_DIAG.cmds = MUTE_DIAG.cmds + 1
    end
end

function admin_clear_mutes(name)
    if not (is_admin(name) or (MUTE_EXEMPT and MUTE_EXEMPT[name])) then
        send(name,"§c仅管理权限。"); return true
    end
    local d=chat_rate_db(); local cnt=0
    for p,_ in pairs(d.mutes or {}) do
        d.mutes[p]=nil; cnt=cnt+1
        pcall(game.sendCommand,'tag "'..string.gsub(tostring(p),'"','\\"')..'" remove 禁言')
    end
    d.rate={}; d.state={}
    chat_rate_save(d)
    send(name,"§a已清空 "..cnt.." 条禁言记录，并移除所有人的禁言标记。")
    pcall(ai_agent_forward, name, "[禁言] 已清空 "..cnt.." 条禁言记录（操作者 "..tostring(name).."）", nil)
    return true
end

function mute_burst(name)
    do return false end -- 禁言系统已移除
    local now = util.timestamp()
    MUTE_DIAG.last = MUTE_DIAG.last or {}
    local cfg = mute_cfg()
    MUTE_DIAG.glast = MUTE_DIAG.glast or 0
    if MUTE_DIAG.glast + (tonumber(cfg.gthrottle) or 0) > now then return false end
    MUTE_DIAG.glast = now
    if (MUTE_DIAG.last[name] or 0) + (tonumber(cfg.throttle) or 0) > now then return false end
    MUTE_DIAG.last[name] = now

    local burst = tonumber(cfg.burst) or 10
    if burst > 200 then burst = 200 end
    if burst <= 0 then return false end
    local safe = string.gsub(tostring(name or ""), '"', '\\"')
    local cmd = 'tellraw "' .. safe .. '" {"rawtext":[]}'
    for _ = 1, burst do
        pcall(game.sendCommand, cmd)
        MUTE_DIAG.cmds = MUTE_DIAG.cmds + 1
    end
    MUTE_DIAG.bursts = (MUTE_DIAG.bursts or 0) + 1
    return true
end

function mute_diag(name)
    local now = util.timestamp()
    local el = math.max(1, now - (MUTE_DIAG.t0 or now))
    local tick_hz = math.floor((MUTE_DIAG.ticks / el) * 100 + 0.5) / 100
    local cmd_hz = math.floor((MUTE_DIAG.cmds / el) * 100 + 0.5) / 100
    local target = (1 / (tonumber(CHAT_MUTE_TICK) or 0.05)) * (tonumber(CHAT_MUTE_BURST) or 1)
    local d = chat_rate_db()
    local nm = 0
    for _, v in pairs(d.mutes or {}) do
        local t = tonumber(v) or 0
        if t < 0 or t > now then nm = nm + 1 end
    end
    local s = string.format(
        "禁言诊断：1秒定时 %.2f/秒（累计 %d 次）；2秒定时累计 %d 次（两个都恒为 0 = util.schedule 没注册上）；"
        .."事件驱动已压制 %d 次 / 发包 %d 条（每轮 %s 条，全局节流 %s 秒）；当前被禁言 %d 人",
        tick_hz, MUTE_DIAG.ticks, MUTE_DIAG.ticks2 or 0, MUTE_DIAG.bursts or 0, MUTE_DIAG.cmds,
        tostring(mute_cfg().burst), tostring(mute_cfg().gthrottle), nm)
    send(name, "§b" .. s)
    pcall(ai_agent_forward, name, "[禁言诊断] " .. s, nil)
    return true
end

AI_HOURLY_LIMIT = 10
AI_HOURLY_WINDOW = 3600

function ai_hourly_quota_check(playerName)
    if is_admin(playerName) then return true end
    local d=ai_hourly_rate_db()
    local now=util.timestamp()
    local list=d[tostring(playerName)] or {}
    local kept={}
    for _,t in ipairs(list) do
        if now-(tonumber(t) or 0) < AI_HOURLY_WINDOW then kept[#kept+1]=tonumber(t) end
    end
    if #kept >= AI_HOURLY_LIMIT then
        d[tostring(playerName)]=kept
        ai_hourly_rate_save(d)
        local remain=AI_HOURLY_WINDOW-(now-(kept[1] or now))
        local mins=math.max(1,math.ceil(remain/60))
        send(playerName,"§c普通玩家每小时最多向AI发送10条消息。你本小时额度已用完，请约"..mins.."分钟后再试。")
        return false
    end
    kept[#kept+1]=now
    d[tostring(playerName)]=kept
    ai_hourly_rate_save(d)
    return true
end

function on_chat(playerName, msg)
    msg = trim(msg)
    local low = lower(msg)
    log_event("CHAT", playerName .. ": " .. msg)

    if low == ".help" or low == "help" then
        show_help(playerName)
        return
    end
    if low == ".触发词" then
        show_trigger_words(playerName, 1)
        return
    end
    local nbt_args=msg:match("^%.NBT测试%s+(.+)$") or msg:match("^%.nbt测试%s+(.+)$")
    if nbt_args then nbt_test_report(playerName,nbt_args); return end
    if low==".nbt测试" then send(playerName,"§e用法：.NBT测试 X Y Z，例如 .NBT测试 114 5 14"); return end

    local model_req = msg:match("^%.AI模型%s+(.+)$") or msg:match("^%.ai模型%s+(.+)$") or msg:match("^%.AI切换%s+(.+)$") or msg:match("^%.ai切换%s+(.+)$")
    if not model_req and (low=="ai切换模型到 deepseek-flash" or low=="ai切换到 deepseek-flash" or low=="ai切换模型到 flash") then model_req="deepseek-flash" end
    if low==".ai模型" or low==".ai模型当前" or low==".ai状态" then
        local current=get_ai_model_override() or tostring(game.getConfig("ai_model",AI_MODEL) or AI_MODEL)
        local _,_,prov=ai_endpoint_for(current)
        send(playerName,"§b当前 AI 模型：§e"..model_display(current)..
            "\n§7接口："..(prov=="deepseek" and "§aDeepSeek 官方" or "§7SenseNova 网关")..
            "\n§7思考模式："..(ai_thinking_enabled() and "§a开启（更慢更费token）" or "§7关闭（推荐）")..
            "\n§7可用模型："..available_model_list()..
            "\n§8deepseek-flash = DeepSeek 4.1 Flash（走 DeepSeek 官方接口）"..
            "\n§7切换：§f.AI模型 <模型ID或简称>，例如 §e.AI模型 4.1")
        return
    end
    if model_req then
        if not is_admin(playerName) then
            send(playerName,"§c只有管理权限可以切换 AI 模型。")
        else
            local ok,m=set_ai_model_override(model_req,playerName)
            if ok then
                local _,_,prov=ai_endpoint_for(m)
                send(playerName,"§aAI 模型已立即切换为：§e"..model_display(m).." §7("..m..")"..
                    "\n§7接口："..(prov=="deepseek" and "§aDeepSeek 官方" or "§7SenseNova 网关")..
                    "\n§7之后 AI 请求将优先使用这个模型，直到再次切换。")
            else send(playerName,"§c"..tostring(m)) end
        end
        return
    end

    if low == "停止建筑" or low == "停止建造" or low == "停止建筑模式" or low == ".停止建筑" or low == ".停止建造" then
        if not is_admin(playerName) then
            send(playerName,"§c只有管理权限可以停止建筑任务。")
        else
            RUNTIME.build_stop=RUNTIME.build_stop or {}; RUNTIME.build_stop[playerName]=true
            send(playerName,"§e已要求AI停止继续建筑；本次任务结束后停止信号会自动清除，已经完成的建筑不会删除。")
        end
        return
    end

    if low == ".建筑模式关闭" or low == ".关闭建筑模式" then
        if not is_admin(playerName) then
            send(playerName,"§c只有管理权限可以关闭建筑模式。")
        else
            local dd,rr=player_record(playerName,true)
            rr.ai_build_mode=false
            rr.ai_build_started_at=nil
            rr.ai_build_stop_requested=false
            save_data(dd)
            RUNTIME.build_stop=RUNTIME.build_stop or {}; RUNTIME.build_stop[playerName]=true
            send(playerName,"§e建筑模式已关闭；当前任务会停止，后续AI可正常使用，正常聊天记忆不会清除。")
        end
        return
    end

    if low == ".记忆清除" or low == ".清除记忆" then
        clear_ai_memory(playerName)
        send(playerName,"§b[Ds] §f已切换新窗口")
        return
    end

    if low == ".日志" then
        send(playerName, read_recent_logs(playerName))
        return
    end

    local redeem_args = msg:match("^%.生成兑换码%s+(.+)$") or msg:match("^%.兑换码生成%s+(.+)$")
    if redeem_args then
        if not is_admin(playerName) then
            send(playerName,"§c只有管理权限可以生成兑换码。")
            return
        end
        local seconds,label=parse_expiry(redeem_args)
        if not seconds or seconds<=0 then
            send(playerName,"§c请在末尾写一个有效期即可，例如：7天、7 日、七天、24小时、60分钟、1h、30m。")
            return
        end
        local expires_at=(tonumber(util.timestamp()) or 0)+seconds
        local body=trim(redeem_args)
        local ei=body:find("有效期",1,true)
        if ei then body=trim(body:sub(1,ei-1)) end

        local mode,name,x1,y1,z1,x2,y2,z2 = body:match("^(导出|导入)%s+(.+)%s+(-?%d+)%s+(-?%d+)%s+(-?%d+)%s+(-?%d+)%s+(-?%d+)%s+(-?%d+)%s*$")
        if mode then
            name=trim(name):gsub('^"(.*)"$','%1')
            if mode=="导出" then
                local ok,result=save_native_region(playerName,name,x1,y1,z1,x2,y2,z2)
                if not ok then send(playerName,"§c"..result); return end
            else
                local manifest,err=load_native_manifest(name)
                if not manifest then send(playerName,"§c"..err); return end
            end
            local code,err=create_redeem_code(playerName,"structure",{name=name},expires_at)
            send(playerName,code and ("§a区域 NBT 兑换码：§e"..code.."\n§f结构："..name.."\n§f有效期："..select(2,parse_expiry(redeem_args)).."\n§7兑换一次后永久失效。") or "§c"..err)
            return
        end

        local existing=body:match("^导入%s+(.+)$")
        if existing then
            existing=trim(existing):gsub('^"(.*)"$','%1')
            local manifest,err=load_native_manifest(existing)
            if not manifest then send(playerName,"§c"..err); return end
            local code,cerr=create_redeem_code(playerName,"structure",{name=existing},expires_at)
            send(playerName,code and ("§a区域 NBT 兑换码：§e"..code.."\n§f结构："..existing.."\n§7兑换后会加载到玩家当前位置；一次性使用。") or "§c"..cerr)
            return
        end

        if body=="" then
            send(playerName,"§c自然语言不能为空。示例：.生成兑换码 给我10个钻石 有效期24小时")
            return
        end
        local code,err=create_redeem_code(playerName,"ai",body,expires_at)
        send(playerName,code and ("§aAI兑换码：§e"..code.."\n§f内容："..body.."\n§7兑换时由AI根据内容执行；一次性使用。") or "§c"..err)
        return
    end

    local redeem_input=msg:match("^%.兑换%s+(.+)$")
    if redeem_input then
        local rawcode=trim(redeem_input)
        local dd0=load_data(); local ee0=(dd0.redeem_codes or {})[lower(rawcode)]
        if type(ee0)=="table" and ee0.kind=="ai" then
            send(playerName,"§b[Ds] §f正在兑换……")
        end
        local ok,result=redeem_code(playerName,redeem_input)
        send(playerName,ok and "§a"..result or "§c"..result)
        return
    end

    local in_name,ix1,iy1,iz1=msg:match("^%.导入%s+(.+)%s+(-?%d+)%s+(-?%d+)%s+(-?%d+)%s*$")
    if in_name then
        if not is_admin(playerName) then send(playerName,"§c只有管理权限可以导入区域。")
        else
            in_name=trim(in_name):gsub('^"(.*)"$','%1')
            local ok,result=place_native_region(playerName,in_name,ix1,iy1,iz1)
            send(playerName,tostring(result))
        end
        return
    end

    local out_name,ox1,oy1,oz1,ox2,oy2,oz2=msg:match("^%.导出%s+(.+)%s+(-?%d+)%s+(-?%d+)%s+(-?%d+)%s+(-?%d+)%s+(-?%d+)%s+(-?%d+)%s*$")
    if out_name then
        if not is_admin(playerName) then send(playerName,"§c只有管理权限可以导出区域。")
        else
            local ok,result=save_native_region(playerName,out_name,ox1,oy1,oz1,ox2,oy2,oz2)
            send(playerName,tostring(result))
        end
        return
    end
    if low == ".一键查询" then
        local seed = get_server_seed()
        local info = get_info(playerName)
        if not seed or not info then
            send(playerName, "§e请先设置种子（管理权限使用 .种子 <种子号>），并确保能读取当前位置。")
        else
            send(playerName, "§b[一键查询] §fSeed=" .. seed .. " 位置=" .. math.floor(info.x) .. "," .. math.floor(info.y) .. "," .. math.floor(info.z))
            send_long(playerName, query_seed_structure(playerName, "村庄", SEED_FINDER_DEFAULT_RADIUS), 650)
        end
        return
    end

    if enforce_blacklist(playerName) then return end


    do
        local menu_d, menu_r = player_record(playerName, true)
        if menu_r.menu == "gameplay_index" or menu_r.menu == "trigger_words" then
            if handle_menu(playerName, msg) then return end
        end
    end

    local is_ai_input =
        msg:sub(1, #COMMAND_WORD) == COMMAND_WORD or
        low:sub(1, #NORMAL_TRIGGER) == NORMAL_TRIGGER
    if is_ai_input then
    end

    if msg == ".撤销举报" or msg == ".撤销" then
        local removed = withdraw_report(playerName)
        send(playerName, removed > 0 and ("§a已撤销 " .. removed .. " 条举报。") or "§e你没有可撤销的举报。")
        return
    end

    local board_input = msg:match("^%.积分版%s+(.+)$") or msg:match("^%.积分%s+(.+)$") or msg:match("^%.scoreboard%s+(.+)$")
    if board_input then
        if not is_admin(playerName) then
            send(playerName, "§c只有管理权限可以设置积分计分板名称。")
        elseif not valid_scoreboard_name(trim(board_input)) then
            send(playerName, "§c名称无效，只能使用英文、数字、下划线或短横线，且不能有空格。")
        else
            save_scoreboard_name(playerName, trim(board_input))
            send(playerName, "§a积分计分板名称已保存并覆盖为：" .. trim(board_input))
        end
        return
    end

