    if low==".ai诊断" then
        local ok,t=pcall(util.json_load,AI_TRACE_FILE)
        if ok and type(t)=="table" then send(playerName,"§b━━ AI最近诊断 ━━\n§f模型："..tostring(t.model or "未知").."\n§f状态："..tostring(t.status or "未知").."\n§fHTTP："..tostring(t.status_code or "无").."\n§f原因："..tostring(t.reason or "无").."\n§f结束原因："..tostring(t.finish_reason or "无").."\n§fAI实际输出：\n§7"..(tostring(t.assistant_output or "")=="" and "<空>" or tostring(t.assistant_output)).."\n§f服务器工具结果：\n§7"..(tostring(t.tool_result or "")=="" and "<无>" or tostring(t.tool_result)).."\n§f原始HTTP返回：\n§7"..(tostring(t.raw_body or "")=="" and "<无>" or tostring(t.raw_body):sub(1,1200)).."\n§7不显示模型隐藏思维链，只显示真实API返回、工具结果和错误。") else send(playerName,"§e暂无AI诊断记录。") end
        return
    end

    do
        local k = msg:match("^%.AIAgent密钥%s*(.*)$") or msg:match("^%.aiagent密钥%s*(.*)$")
        if k then
            if not is_admin(playerName) then send(playerName,"§c只有管理权限可以设置 AI Agent 密钥。"); return end
            ai_agent_set_key(playerName, trim(k)); return
        end
    end
    if low==".aiagent状态" then ai_agent_bridge_status(playerName); return end
    if low==".豁免列表" then
        if not _MUTE_EXEMPT_READY then mute_exempt_load() end
        send(playerName,"§b禁言豁免名单：§f"..table.concat(mute_exempt_list(),"、"))
        return
    end
    do
        local nm = msg:match("^%.豁免%s*(.+)$")
        if nm then send(playerName,"§7禁言功能已移除，豁免名单不再需要。"); return end
    end
    if low==".黑框排查" then return blackbox_diag(playerName) end
    do
        local n = msg:match("^%.禁言强度%s+(%d+)$")
        if n then send(playerName,"§7禁言功能已按你的要求整体移除（2026-09-14）。"); return end
        if false then
            if not is_admin(playerName) then send(playerName, "§c仅管理权限。"); return end
            local c = mute_cfg()
            c.burst = math.max(1, math.min(200, tonumber(n) or 20))
            mute_cfg_save()
            send(playerName, "§a禁言强度已设为每轮 §f" .. tostring(c.burst)
                 .. " §a条（0=关闭压制；全局节流 " .. tostring(c.gthrottle) .. " 秒）")
            return
        end
    end
    do
        local em = msg:match("^%.[Aa][Ii]回显%s*(%S*)$")
        if em then
            em = trim(em or "")
            if em == "" then
                send(playerName, "§b当前 AI 回显：§f" .. ai_echo_mode()
                    .. "\n§7用法：§f.AI回显 公开 §7/ §f.AI回显 私聊 §7/ §f.AI回显 都发"
                    .. "\n§7看不到 AI 回答时，设成「公开」或「都发」。")
                return
            end
            local m
            if em == "公开" or em == "public" or em == "聊天框" then m = "public"
            elseif em == "私聊" or em == "private" or em == "私信" then m = "private"
            elseif em == "都发" or em == "both" or em == "两个" then m = "both"
            else send(playerName, "§c只能是：公开 / 私聊 / 都发"); return end
            ai_echo_set(m)
            send(playerName, "§aAI 回显已设为：§f" .. m
                .. "§7（私聊=只发给你，公开=只进聊天框，都发=两边都发）")
            return
        end
    end
    if low==".发送自检" then cmd_selfcheck(playerName); return end
    if low==".模块状态" then cmd_mod_status(playerName); return end
    if low==".分段状态" then cmd_seg_status(playerName); return end
    if low==".分段重载" then cmd_seg_reload(playerName); return end

    if low==".权限自检" then perm_selfcheck(playerName); return end
    if low==".禁言诊断" then send(playerName,"§7禁言功能已按你的要求整体移除（2026-09-14）。"); return end
    if low==".清空禁言" then send(playerName,"§7禁言功能已按你的要求整体移除（2026-09-14）。"); return end
    if low==".agent 选择" or low==".agent选择" or low==".agent 选" or low==".agent" then
        if not is_admin(playerName) then send(playerName,"§c只有管理权限可以选择 AI Agent。"); return end
        local pd,pr = player_record(playerName,true)
        set_menu(pd,pr,"agent_pick"); save_data(pd)
        return agent_show_menu(playerName)
    end
    if low==".agent 当前" or low==".agent当前" then
        local p=agent_resolve()
        if p then send(playerName,"§b当前 AI Agent：§f"..tostring(p.label).."\n§7接口："..tostring(agent_api_url(p.base_url)).."\n§7模型："..tostring(p.model_id))
        else send(playerName,"§e还没选，或之前选的已失效。输入 §f.Agent 选择") end
        return
    end
    do
        local idx,bu,ak,mi = msg:match("^%.[Aa]gent%s+配置%s+(%d+)%s+(%S+)%s+(%S+)%s*(.*)$")
        if idx then
            if not is_admin(playerName) then send(playerName,"§c只有管理权限可以配置 AI Agent。"); return end
            return agent_config(playerName, idx, tostring(bu or ""), tostring(ak or ""), trim(mi or ""))
        end
    end
    if low:sub(1,10)==".ai agent " or low==".ai agent" or low:sub(1,9)==".aiagent " or low==".aiagent" then
        local text
        if low:sub(1,10)==".ai agent " then text=trim(msg:sub(11))
        elseif low:sub(1,9)==".aiagent " then text=trim(msg:sub(10))
        else text="" end
        if not is_admin(playerName) then send(playerName,"§c只有管理权限可以使用 AI Agent。"); return end
        return agent_ask(playerName, text)
    end

    if low==".aiagent列表" or low==".aiagent名单" or low==".aiagents" then
        if not is_admin(playerName) then send(playerName,"§c只有管理权限可以查看 AI Agent 名单。"); return end
        local ok, list = ai_agent_roster(true)
        if not ok then
            send(playerName,"§c拉取名次失败："..tostring(list).."\n§7请在本实例工作区配置AI模型，内置MCP自动连接本机。"); return
        end
        if #list == 0 then
            send(playerName,"§e当前还没有任何 AI Agent 登记过。\n§7让 AI 在它的 MCP 网址后面加 §f&agent=<名字> §7再连一次，就会出现在这里。\n§7没有外部 AI 时，云端配好的模型（强大的GPT / DeepSeek 等）也会列出来供点名。"); return
        end
        local kind_cn = { mcp="外部AI", model="模型", pc="电脑CLI" }
        local lines = {}
        for _, a in ipairs(list) do
            local mark = a.online and "§a●" or "§7○"
            local kind = kind_cn[tostring(a.kind or "")] or tostring(a.kind or "?")
            table.insert(lines, "§f"..tostring(a.no)..". "..mark.." §f"..tostring(a.label or a.name)
                .."  §8["..kind.."]"..(a.online and "" or " §7离线"))
        end
        send(playerName,"§b━━ AI Agent 名单 ━━\n"..table.concat(lines,"\n")
            .."\n§e点名：§fAI Agent 编号 要说的话\n§e广播：§fAI Agent 要说的话\n§8（○ 离线：点了名也没人接）")
        return
    end


    if low:sub(1, 9) == "ai agent " or low == "ai agent" then
        local text = trim(msg:sub(10))
        if text == "" then
            send(playerName,"§b━━ AI Agent 通道 ━━\n§e用法：§fAI Agent 你想说的话 §7（广播给所有在线的）\n§e点名：§fAI Agent 2 你想说的话 §7（只发给 2 号）\n§e看名单：§f.AIAgent列表\n§f状态：§"..(ai_agent_bridge_ready() and "a已接通" or "c未设置密钥，请先 .AIAgent密钥 <平台密钥>"))
            return
        end
        if not is_admin(playerName) then send(playerName,"§c只有管理权限可以使用 AI Agent 通道。"); return end

        local no, rest = text:match("^(%d+)%s+(.+)$")
        local target_label = nil
        if no then
            no = tonumber(no); text = trim(rest)
        else
            local only = text:match("^(%d+)$")
            if only then
                no = tonumber(only); text = trim(msg:match("^AI%s+Agent%s+%d+%s*(.-)$") or "")
            end
        end
        if no and text == "" then
            send(playerName,"§e要点名就顺便把话说完：§fAI Agent "..no.." 你想让它做什么\n§7只查名单用：§f.AIAgent列表")
            return
        end
        if no then
            local rok, rlist = ai_agent_roster()
            if rok then
                local a = ai_agent_no_of(rlist, no)
                if not a then
                    send(playerName,"§c没有 "..no.." 号 AI Agent。用 §f.AIAgent列表 §c看当前有哪些。"); return
                end
                if a.online == false then
                    send(playerName,"§e"..no.." 号（"..tostring(a.label or a.name).."）现在不在线，消息可能没人接。\n§7仍要发送请改用不带编号的广播，或用 §f.AIAgent列表 §7挑一个在线的。"); return
                end
                target_label = tostring(a.label or a.name)
            end
        end

        local fok, ferr = ai_agent_forward(playerName, text, no)
        if fok then
            if no then
                send(playerName,"§a已转发给 §b"..no.." 号 "..tostring(target_label or "AI").."§a：\n§f"..text.."\n§7其它 AI 不会收到这条，等它回话。")
            else
                send(playerName,"§a已提交本机已配置的 AI 工作区：\n§f"..text.."\n§7完成后回复到当前玩家；想指定工作区用 §fAI Agent 编号 内容")
            end
        else
            send(playerName,"§c转发失败："..tostring(ferr).."\n§7请在本实例工作区配置AI模型，内置MCP自动连接本机。")
        end
        return
    end


    local question, commandMode, publicReply = nil, false, false

    if msg:sub(1, #COMMAND_WORD) == COMMAND_WORD then
        question = trim(msg:sub(#COMMAND_WORD + 1))
        commandMode = true
    elseif low:sub(1, 3) == "ai " then
        question = trim(msg:sub(4))
        publicReply = (msg:sub(1, 3) == "AI ")
    end

    if not question or question == "" then return end

    local memory_cmd = lower(trim(question))
    if memory_cmd == "清除记忆" or memory_cmd == "清空记忆" or memory_cmd == "清除聊天记忆" or memory_cmd == "忘记之前的聊天" then
        clear_ai_memory(playerName)
        if publicReply then broadcast("§b[Ds] §f已切换新窗口") else send(playerName,"§b[Ds] §f已切换新窗口") end
        return
    end

    local function ai_notice(text)
        if publicReply then broadcast(text) else send(playerName, text) end
    end
    local function ai_notice_long(text)
        text=tostring(text or "")
        if text=="" then return end
        local rest=text; local parts=0
        while rest~="" do
            local i=1; local count=0; local cut=#rest
            while i<=#rest and count<180 do
                local b=string.byte(rest,i) or 0; local n=(b>=0xF0 and 4) or (b>=0xE0 and 3) or (b>=0xC0 and 2) or 1
                if i+n-1>#rest then break end
                i=i+n; count=count+1
            end
            if i<=#rest then cut=i-1 else cut=#rest end
            local part=rest:sub(1,cut)
            rest=rest:sub(cut+1)
            ai_notice(part); parts=parts+1
            if parts>=24 then
                ai_notice("§7（回复达到聊天显示上限，后续内容已省略）")
                break
            end
        end
    end

    if not ai_hourly_quota_check(playerName) then return end

    local pre_build_state=ai_build_state_get(playerName)
    local ql=lower(question or "")
    local build_notice = is_admin(playerName) and ((pre_build_state and pre_build_state.active==true) or ql:find("建筑",1,true) or ql:find("建造",1,true) or ql:find("盖",1,true))
    if build_notice then ai_notice("§b[Ds] §f建筑任务处理中……") end
    local ok, reply = pcall(run_agent, question, playerName, commandMode, commandMode and "command" or "chat")

    local wkey = commandMode and "command" or "chat"
    local function ai_usage_notice()
        local this_task = tonumber(AI_USAGE.task) or 0
        local cum = 0
        if this_task > 0 then
            cum = ai_usage_window_add(playerName, commandMode, wkey, this_task)
        else
            cum = ai_usage_window_get(playerName, commandMode, wkey)
        end
        ai_notice(string.format("§8[Token] 本次 §b%d §8token §7| §8本窗口累计 §b%d §8token", this_task, cum))
    end

    if not ok then
        local err=tostring(reply)
        save_ai_trace({model=tostring(choose_ai_model(question,commandMode) or "unknown"),status="exception",status_code="",reason=err,assistant_output=""})
        if string.find(lower(err),"timeout",1,true) or string.find(lower(err),"timed out",1,true) or string.find(err,"超时",1,true) then
            ai_notice("§c[Ds] 思考超时 已断开")
        else
            ai_notice("§c[Ds] 本次请求暂时未完成，请稍后重试。")
        end
        ai_usage_notice()
        return
    end
    if not reply or trim(reply)=="" then
        ai_notice("§c[Ds] 本次请求没有得到有效结果，请换一种说法再试。")
    else
        ai_notice_long("§b[Ds] §f" .. reply)
    end
    ai_usage_notice()
end


function on_join(name)
    if enforce_blacklist(name) then return end
    log_event("PLAYER", tostring(name) .. " joined")
    local d,r=player_record(name,true); r.name=name; r.online_since=util.timestamp()
    coordinate_tp_state(r)
    market_settle_offline(name)
end
function on_leave(name)
    local d,r=player_record(name,true); local now=util.timestamp(); local since=tonumber(r.online_since)
    if since and now>=since then r.online_seconds=(tonumber(r.online_seconds) or 0)+(now-since) end
    r.online_since=nil; r.last_offline_at=now; save_data(d)
end

