    })
end

XOR8_TABLE = nil
function xor8_build()
    if XOR8_TABLE then return XOR8_TABLE end
    local t = {}
    for a = 0, 255 do
        local base = a * 256
        for b = 0, 255 do
            local x, y, r, bit = a, b, 0, 1
            for _ = 1, 8 do
                local xb = x % 2
                local yb = y % 2
                if xb ~= yb then r = r + bit end
                x = (x - xb) / 2
                y = (y - yb) / 2
                bit = bit * 2
            end
            t[base + b] = r
        end
    end
    XOR8_TABLE = t
    return t
end



function death_diag(name)
    local track = load_death_track()
    local d = load_data()
    local key, info = identity(name)
    local r = d.players and d.players[key]
    local lines = { "§b---- 死亡点诊断：" .. tostring(name) .. " ----" }
    lines[#lines+1] = string.format("§f身份键=§e%s §7xuid=§f%s §7uid=§f%s",
        tostring(key), tostring(info.xuid), tostring(info.unique_id))
    local okl, lst = pcall(player.list)
    lines[#lines+1] = string.format("§fplayer.list=§e%s 条",
        tostring((okl and type(lst) == "table") and #lst or "ERR"))
    if info and info.online ~= nil then
        lines[#lines+1] = string.format("§fplayer.get: §e%s,%s,%s §7online=§f%s §7dim=§f%s",
            tostring(info.x), tostring(info.y), tostring(info.z),
            tostring(info.online), tostring(info.dimension))
    end
    local p = track.pos[key] or track.pos[name]
    if p then
        lines[#lines+1] = string.format("§fpos表=§e%s,%s,%s §7@%s §7at=§f%s",
            tostring(p.x), tostring(p.y), tostring(p.z), tostring(p.dimension), tostring(p.at))
    else
        lines[#lines+1] = "§cpos 表无记录"
    end
    if r and r.death then
        lines[#lines+1] = string.format("§f当前死亡点=§e%s,%s,%s §7@%s §7reason=§f%s",
            tostring(r.death.x), tostring(r.death.y), tostring(r.death.z),
            tostring(r.death.dimension), tostring(r.death.reason))
    else
        lines[#lines+1] = "§c无死亡点记录"
    end
    lines[#lines+1] = string.format("§f死亡次数=§e%s", tostring(r and r.death_count or 0))

    local plain = {}
    for _, l in ipairs(lines) do
        plain[#plain+1] = l:gsub("§.", "")
    end
    plain[#plain+1] = ""
    plain[#plain+1] = "---- pos 表全量 ----"
    for k, v in pairs(track.pos or {}) do
        plain[#plain+1] = string.format("  %s  %s,%s,%s  @%s  at=%s",
            tostring(k), tostring(v.x), tostring(v.y), tostring(v.z),
            tostring(v.dimension), tostring(v.at))
    end
    plain[#plain+1] = "---- last_death_coord 表全量 ----"
    for k, v in pairs(track.last_death_coord or {}) do
        plain[#plain+1] = string.format("  %s -> %s (at=%s)",
            tostring(k), tostring(v.coord), tostring(v.at))
    end
    plain[#plain+1] = "---- pid2name 表全量 ----"
    for k, v in pairs(track.pid2name or {}) do
        plain[#plain+1] = string.format("  %s -> %s", tostring(k), tostring(v))
    end
    local f = io.open("/storage/emulated/0/ds_bridge/ds_death_diag.txt", "wb")
    if f then
        f:write(table.concat(plain, "\n"))
        f:close()
    end

    send(name, table.concat(lines, "\n"))
end

