function death_timer_mark_file() return game.dataDir() .. "/death_timer_ok" end

function death_timer_is_ok()
    local ok, s = pcall(util.read_file, death_timer_mark_file())
    return ok and type(s) == "string" and s:find("1") ~= nil
end

function death_timer_set_ok()
    pcall(util.write_file, death_timer_mark_file(), "1")
end

function death_timer_ensure()
    if death_timer_is_ok() then return true end
    local h = select(2, pcall(util.schedule, DEATH_FALLBACK_INTERVAL, "tick_death_fallback"))
    if type(h) == "number" and h > 0 then
        death_timer_set_ok()
        return true
    end
    return false
end
function death_timer_retry_tick()
    if death_timer_is_ok() then return end
    pcall(death_timer_ensure)
end

function register_periodic_tasks()
    local schedule = function(sec, handler)
        local ok, h = pcall(util.schedule, sec, handler)
        return ok and type(h)=="number" and h>0
    end
    schedule(6, "ds_death_sample_tick")
    schedule(VOTE_CHECK_INTERVAL, "on_vote_tick")
    schedule(10, "expire_system_state")
    schedule(3, "tick_territories")
    schedule(1, "tick_coordinate_and_soul")
    schedule(2, "tick_chat_mute")
    schedule(2, "flush_log_buffer")
    schedule(ANNOUNCEMENT_INTERVAL, "on_announcement_tick")
    pcall(util.write_file, death_timer_mark_file(), "")
    if not death_timer_ensure() then
        pcall(util.schedule, 2, "death_timer_retry_tick")
    end
end


function item_display_name(id, damage)
    local raw = tostring(id or "")
    local base = lower(raw:gsub("^minecraft:", ""))
    if base == "" then return "?" end
    local dmg = tonumber(damage) or 0
    local nm = nil
    local dm = item_damage_data()
    if type(dm) == "table" then nm = dm[base .. ":" .. tostring(dmg)] end
    if nm == nil then
        local names = item_name_data()
        if type(names) == "table" then nm = names[base] end
    end
    nm = tostring(nm or base:gsub("_", " "))
    local cn = nm:match("^(.-)%s*/%s*%a")
    if cn and trim(cn) ~= "" then nm = trim(cn) end
    return nm
end

function death_tp_cost()
    local c = tonumber(game.getConfig("death_tp_cost", 100)) or 100
    c = math.floor(c)
    if c < 0 then c = 0 end
    return c
end

function death_read_balance(name)
    local board = scoreboard_name()
    if not board or trim(board) == "" then return nil end
    local ok, v = pcall(game.getScore, board, name)
    if not ok then return nil end
    return math.floor(tonumber(v) or 0)
end

local SEP = "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"

function death_show_list(name)
    local d,r=player_record(name,true)
    local hist=r.death_history or {}
    local cost=death_tp_cost()
    local bal=death_read_balance(name)
    local recent={}
    local shown=0
    for i=#hist,1,-1 do
        shown=shown+1
        if shown>5 then break end
        local h=hist[i]
        local ts=tostring(h.saved_at or "")
        if #ts>=16 then ts=ts:sub(1,16) end
        recent[#recent+1]=string.format("§b%d §8┃ §f第§e%d§f次 §8▸ §f%d %d %d §8[§b%s§8] §7%s",
            shown, tonumber(h.n) or shown,
            math.floor(tonumber(h.x) or 0),math.floor(tonumber(h.y) or 0),math.floor(tonumber(h.z) or 0),
            dimension_display(h.dimension),ts)
    end
    local d2,r2=player_record(name,true)
    set_menu(d2,r2,"death_dir")
    if shown==0 then
        send(name,"§8§m━━━━━━━━━━━━━━━━━━━━━━━━\n§1◆ §r§b§l死 亡 日 志 §8┃ §7最近5次\n§8§m━━━━━━━━━━━━━━━━━━━━━━━━\n§7暂无死亡记录。下一次死亡后会自动记录。")
        send(name,"§7➜ §f.死亡日志 §7重新查看 · §f.stop §7退出")
        return
    end
    local head={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§1◆ §r§b§l死 亡 日 志 §8┃ §7最近5次","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    for i=1,math.min(3,#recent) do head[#head+1]=recent[i] end
    send(name,table.concat(head,"\n"))

    local tail={}
    for i=4,#recent do tail[#tail+1]=recent[i] end
