    tail[#tail+1]="§7➜ 输入 §b1~"..tostring(shown).." §7传送到对应记录点"
    tail[#tail+1]="§7➜ §f1 = 最近一次，数字越大越早"
    if cost>0 then
        tail[#tail+1]="§6⚑ §7回点费用 §6"..tostring(cost).." §7积分"..(bal~=nil and (" §8┃ §7余额 §b"..tostring(bal)) or "")
    else
        tail[#tail+1]="§6⚑ §7当前回点免费"
    end
    tail[#tail+1]="§7➜ §f.死亡点返回 [序号] §7可直接回点 · §f.stop §7退出"
    tail[#tail+1]="§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
    send(name,table.concat(tail,"\n"))
end
