function death_return_to(name, idx)
    local d, r = player_record(name, true)
    local hist = r.death_history or {}
    local n = #hist
    idx = math.floor(tonumber(idx) or 1)
    if idx < 1 then idx = 1 end
    local pt = nil
    if n == 0 then
        pt = r.death
    elseif idx <= n then
        pt = hist[n - idx + 1]
    else
        send(name, "§c没有第 " .. tostring(idx) .. " 条记录，你目前共 " .. tostring(n) .. " 条（1 = 最近）。")
        return false
    end
    if type(pt) ~= "table" then
        send(name, "§c你还没有坐标记录，无法回去。")
        return false
    end

    local cost = death_tp_cost()
    if cost > 0 then
        local board = scoreboard_name()
        if not board or trim(board) == "" then
            send(name, table.concat({
                SEP,
                "§c§l✘ §r§f§l无法回到记录点",
                "§7本服还没有设置积分计分板。",
                "§8请让管理权限先执行 §f.积分版 <名称>",
                SEP,
            }, "\n"))
            return false
        end
        local bal = death_read_balance(name)
        if bal == nil then
            send(name, "§c读取积分失败，传送已取消。")
            return false
        end
        if bal < cost then
            send(name, table.concat({
                SEP,
                "§c§l✘ §r§f§l积分不足，无法回到记录点",
                "§7需要 §6§l" .. cost .. " §r§7积分 §8| §7当前 §a§l" .. bal,
                "§7获得积分 §8▸ §f系统商店 §7→ §f2. 出售物品",
                "§7查看记录 §8▸ §f.死亡日志",
                SEP,
            }, "\n"))
            return false
        end
        local safe = string.gsub(name, '"', '\\"')
        local okc, res = pcall(game.isCmdSuccess, 'scoreboard players remove "' .. safe .. '" ' .. board .. ' ' .. cost)
        if not okc or res ~= true then
            send(name, "§c扣分失败，传送已取消。")
            return false
        end
    end

    r.menu = nil
    save_data(d)
    local ok, err = tp_to(name, pt)
    if ok then
        local coord = string.format("§7坐标 §8▸ §f§l%d §f%d §f%d §8[§f%s§8]",
            math.floor(tonumber(pt.x) or 0), math.floor(tonumber(pt.y) or 0), math.floor(tonumber(pt.z) or 0),
            dimension_display(pt.dimension))
        local tail
        if cost > 0 then
            local left = death_read_balance(name)
            tail = "§8已扣除 §6§l" .. cost .. " §r§8积分" .. (left and (" §8| §7余额 §a" .. left) or "")
        else
            tail = "§8本次回点不消耗积分"
        end
        send(name, table.concat({
            SEP,
            "§a§l✔ §r§f§l已回到记录点",
            coord,
            "§7这是第 §e" .. idx .. " §7近的一条记录",
            tail,
            SEP,
        }, "\n"))
    else
        local board = scoreboard_name()
        if cost > 0 and board and trim(board) ~= "" then
            local safe = string.gsub(name, '"', '\\"')
            pcall(game.isCmdSuccess, 'scoreboard players add "' .. safe .. '" ' .. board .. ' ' .. cost)
            send(name, "§c传送失败：" .. tostring(err) .. "\n§e已退回 " .. cost .. " 积分。")
            return false
        end
        send(name, "§c传送失败：" .. tostring(err))
    end
    return ok == true
end

function special_shop_clear_do(name, id)
    if not is_admin(name) then send(name, "§c只有管理权限可以清除特殊商店商品。"); return true end
    local db = fixed_shop_db()
    local v = (db.items or {})[tostring(id)]
    if not v then send(name, "§c编号 " .. tostring(id) .. " 不存在或已被清除。"); return true end
    local show_name = tostring(v.name or id)
    local show_price = tostring(v.price or 0)
    db.items[tostring(id)] = nil
    local ok, err = fixed_shop_save(db)
    local vok, vdb = pcall(util.json_load, FIXED_SHOP_FILE)
    local still = (vok and type(vdb) == "table" and type(vdb.items) == "table" and vdb.items[tostring(id)] ~= nil)
    if not ok or still then
        send(name, "§c清除失败：" .. tostring(err or "写入后回读仍然存在"))
        return true
    end
    pcall(append_json_log, SHOP_LOG_FILE, { at = util.timestamp(), type = "特殊商店清除商品",
        operator = name, id = tostring(id), name = show_name, price = v.price })
    send(name, table.concat({
        SEP,
        "§a§l✔ §r§f§l已真实清除商品",
        "§7商品 §8▸ §e" .. show_name .. " §8#§7" .. tostring(id),
        "§7单价 §8▸ §6" .. show_price .. " §r§7积分",
        "§8该商品已从特殊商店彻底移除（不可恢复）。",
        SEP,
    }, "\n"))
    return true
end

function zip_u16(n)
    n = math.floor(tonumber(n) or 0) % 65536
    return string.char(n % 256, math.floor(n / 256) % 256)
end
function zip_u32(n)
    n = math.floor(tonumber(n) or 0) % 4294967296
    return string.char(n % 256, math.floor(n / 256) % 256, math.floor(n / 65536) % 256, math.floor(n / 16777216) % 256)
end
XOR8_TABLE = nil
function xor8_build()
    if XOR8_TABLE then return XOR8_TABLE end
    local t = {}
    for a = 0, 255 do
        local base = a * 256
        for b = 0, 255 do
            local x, y, r, bit = a, b, 0, 1
            for _ = 1, 8 do
                local xb = x % 2
                local yb = y % 2
                if xb ~= yb then r = r + bit end
                x = (x - xb) / 2
                y = (y - yb) / 2
                bit = bit * 2
            end
            t[base + b] = r
        end
    end
    XOR8_TABLE = t
    return t
end
function zip_bxor(a, b)
    local X = xor8_build()
    a = math.floor(tonumber(a) or 0); b = math.floor(tonumber(b) or 0)
    local a0 = a % 256; local b0 = b % 256
    local a1 = ((a - a0) / 256) % 256; local b1 = ((b - b0) / 256) % 256
    local a2 = ((a - a0 - a1 * 256) / 65536) % 256; local b2 = ((b - b0 - b1 * 256) / 65536) % 256
    local a3 = math.floor(a / 16777216) % 256; local b3 = math.floor(b / 16777216) % 256
    return X[a0 * 256 + b0] + X[a1 * 256 + b1] * 256 + X[a2 * 256 + b2] * 65536 + X[a3 * 256 + b3] * 16777216
end
ZIP_CRC_TABLE = nil
function zip_crc32(s)
    if not ZIP_CRC_TABLE then
        local t = {}
        for i = 0, 255 do
            local c = i
            for _ = 1, 8 do
                if c % 2 == 1 then c = zip_bxor(3988292384, math.floor(c / 2)) else c = math.floor(c / 2) end
            end
            t[i] = c
        end
        ZIP_CRC_TABLE = t
    end
    local crc = 4294967295
    for i = 1, #s do
        local idx = zip_bxor(crc, s:byte(i)) % 256
        crc = zip_bxor(ZIP_CRC_TABLE[math.floor(idx)], math.floor(crc / 256))
    end
    return zip_bxor(crc, 4294967295)
end
function zip_build(files)
    local locals_parts, central_parts = {}, {}
    local offset = 0
    for _, f in ipairs(files) do
        local name = tostring(f.name or "")
        local data = tostring(f.data or "")
        local crc = zip_crc32(data)
        local size = #data
        local lh = string.char(80,75,3,4) .. zip_u16(20) .. zip_u16(2048) .. zip_u16(0) .. zip_u16(0) .. zip_u16(33)
            .. zip_u32(crc) .. zip_u32(size) .. zip_u32(size) .. zip_u16(#name) .. zip_u16(0) .. name
        locals_parts[#locals_parts + 1] = lh
        locals_parts[#locals_parts + 1] = data
        central_parts[#central_parts + 1] = string.char(80,75,1,2) .. zip_u16(20) .. zip_u16(20) .. zip_u16(2048) .. zip_u16(0) .. zip_u16(0) .. zip_u16(33)
            .. zip_u32(crc) .. zip_u32(size) .. zip_u32(size) .. zip_u16(#name) .. zip_u16(0) .. zip_u16(0) .. zip_u16(0) .. zip_u16(0) .. zip_u32(0) .. zip_u32(offset) .. name
        offset = offset + #lh + size
    end
    local cd = table.concat(central_parts)
    local eocd = string.char(80,75,5,6) .. zip_u16(0) .. zip_u16(0) .. zip_u16(#files) .. zip_u16(#files) .. zip_u32(#cd) .. zip_u32(offset) .. zip_u16(0)
    return table.concat(locals_parts) .. cd .. eocd
end
function pack_read_first(paths)
    for _, p in ipairs(paths or {}) do
        local ok, data = pcall(util.read_file, p)
        if ok and type(data) == "string" and data ~= "" then return data, p end
    end
    return nil, nil
end

function backup_write_candidates()
    local out = {}
    local first = trim(tostring(BACKUP_OUT_DIR or ""))
    if first == "" then first = "/storage/emulated/0/我的世界指令相关" end
    out[#out + 1] = first
    local dd = tostring(game.dataDir() or "")
    if dd ~= "" then out[#out + 1] = dd end
    return out
end
function backup_write_zip(fname, data)
    if type(data) ~= "string" or data == "" then return false, nil, "zip 数据为空" end
    fname = tostring(fname or "backup.zip")
    local last_err = "未知错误"
    for _, dir in ipairs(backup_write_candidates()) do
        local path = tostring(dir or "")
        if path ~= "" then
            path = path .. "/" .. fname
            local ok, err = pcall(util.write_file, path, data)
            if ok then
                local vok, vdata = pcall(util.read_file, path)
                if vok and type(vdata) == "string" and #vdata == #data then return true, path, nil end
                last_err = "回读不一致（" .. path .. "）"
            else
                last_err = tostring(err)
            end
        end
    end
    return false, nil, last_err
end

function backup_date_tag()
    local t = tostring(util.now() or "")
    local y, mo, d, h, mi = t:match("^(%d%d%d%d)%-(%d%d)%-(%d%d)%s+(%d%d):(%d%d)")
    if not y then return tostring(util.timestamp()) end
    return y .. "-" .. mo .. "-" .. d .. "_" .. h .. mi
end
function backup_file_name()
    return "ds_ai_agent_完整备份_" .. backup_date_tag() .. ".zip"
end
function backup_upload_config()
    return {
        url = trim(tostring(game.getConfig("backup_upload_url", "") or "")),
        token = trim(tostring(game.getConfig("backup_upload_token", "") or "")),
        mode = lower(trim(tostring(game.getConfig("backup_upload_mode", "raw") or "raw"))),
    }
end
function backup_upload_file(path, fname)
    local cfg = backup_upload_config()
    if cfg.url == "" then return false, "未配置上传地址（插件配置 backup_upload_url 为空）" end
    local ok, data = pcall(util.read_file, path)
    if not ok or type(data) ~= "string" or data == "" then return false, "读取本地备份文件失败" end
    local headers = { ["Content-Type"] = "application/zip", ["X-Filename"] = tostring(fname), ["X-Backup-Name"] = tostring(fname) }
    if cfg.token ~= "" then headers["Authorization"] = "Bearer " .. cfg.token end
    local body = data
    if cfg.mode == "base64" or cfg.mode == "json" or cfg.mode == "json_base64" then
        headers["Content-Type"] = "application/json"
        body = http.json_encode({ filename = tostring(fname), size = #data, data = base64_encode(data) })
    end
    local r = http.post(cfg.url, body, { headers = headers, timeout = 180 })
    if not r or not r.ok then
        log_event("BACKUP", "upload fail: " .. tostring(r and (r.error or r.status) or "无响应"))
        return false, "上传请求失败：" .. tostring(r and (r.error or r.status) or "无响应")
    end
    local code = tonumber(r.status) or 0
    if code < 200 or code >= 300 then
        return false, "上传失败（HTTP " .. tostring(code) .. "）：" .. tostring(r.body or ""):sub(1, 200)
    end
    log_event("BACKUP", "upload ok " .. tostring(fname) .. " -> " .. cfg.url)
    return true, tostring(r.body or ""):sub(1, 300)
end

function pack_full_backup_zip(out_name)
    -- 统一走当前实际插件 ID 与当前数据目录；禁止再引用旧版 ds_ai_agent_修复版_死亡检测_性能优化 路径。
    return pack_two_plugins_zip(out_name)
end

function pack_bundle_zip()
    local base = plugin_base_dir()
    local pdir = plugin_code_dir()
    local report = {}
    local lua_data, lua_path = pack_read_first({ pdir .. "/ds_ai_agent_修复版_死亡检测_性能优化.lua", pdir .. "/main.lua" })
    local man_data = pack_read_first({ pdir .. "/ds_ai_agent.manifest.json", pdir .. "/manifest.json" })
    local docs_data = pack_read_first({ pdir .. "/ds_ai_agent_修复版_死亡检测_性能优化.docs.md", pdir .. "/docs.md" })
    report[#report + 1] = "main.lua <- " .. tostring(lua_path or "未找到") .. " (" .. tostring(lua_data and #lua_data or 0) .. " 字节)"
    if not lua_data then return "打包失败：读不到插件源码（" .. pdir .. "）" end
    man_data = man_data or "{\n  \"id\": \"ds_ai_agent\",\n  \"name\": \"多功能插件 1.0.36\",\n  \"version\": \"1.0.36\",\n  \"type\": \"lua\",\n  \"author\": \"\",\n  \"description\": \"Ds 多功能插件\",\n  \"pre_plugins\": {}\n}\n"
    docs_data = docs_data or "# Ds 多功能插件\n\n详见插件说明。\n"
    local def_payload = {
        item_names = default_item_names(),
        item_damage_names = default_item_damage_names(),
        sell_prices = default_sell_prices(),
        full_shop_prices = default_full_shop_prices(),
    }
    local def_json = http.json_encode(def_payload)
    pcall(util.write_file, pdir .. "/defaults.json", def_json)
    report[#report + 1] = "defaults.json (" .. #def_json .. " 字节)"
    local z = zip_build({
        { name = "manifest.json", data = man_data },
        { name = "main.lua", data = lua_data },
        { name = "docs.md", data = docs_data },
        { name = "defaults.json", data = def_json },
    })
    local wok, wpath, werr = backup_write_zip("ds_ai_agent.zip", z)
    if wok then report[#report + 1] = "已写出 " .. wpath .. " (" .. #z .. " 字节)"
    else report[#report + 1] = "写 ds_ai_agent.zip 失败：" .. tostring(werr) end
    return table.concat(report, "\n")
end

function run_full_backup(playerName, why)
    local by = tostring(playerName or "控制台")
    local fname = backup_file_name()
    log_event("BACKUP", by .. " start " .. fname .. " (" .. tostring(why or "") .. ")")
    local ok, report = pcall(pack_full_backup_zip, fname)
    if not ok then
        log_event("BACKUP", "fail: " .. tostring(report))
        return "§c打包失败：" .. tostring(report)
    end
    local report_text = tostring(report or "")
    log_event("BACKUP", "done: " .. report_text:gsub("\n", " | "))
    local size, path = nil, nil
    for line in report_text:gmatch("[^\r\n]+") do
        local p = line:match("^打包%s+%d+%s+个文件，输出：(.+)$")
        if p then path = trim(p) end
        local s = line:match("^大小：(%d+)%s*字节")
        if s then size = s end
    end
    if not path then
        return "§c" .. report_text:gsub("\n", "\n§7")
    end
    local out = "§a§l✔ §r§a完整备份已生成\n§f文件：§e" .. fname ..
        "\n§f位置：§7" .. path ..
        (size and ("\n§f大小：§b" .. size .. " 字节") or "") ..
        "\n§7内容：插件文件 + 插件配置 + 全部数据文件。"
    local cfg = backup_upload_config()
    if cfg.url == "" then
        out = out .. "\n§7☁ 未配置上传地址（backup_upload_url），仅保存在手机上。"
    else
        local uok, uinfo = backup_upload_file(path, fname)
        if uok then out = out .. "\n§b☁ 已上传：§7" .. cfg.url
        else out = out .. "\n§c☁ 上传失败：§7" .. tostring(uinfo) end
    end
    return out
end


function plugin_id_now()
    local d = tostring(game.dataDir() or "")
    local seg = d:match("([^/]+)/?$")
    if seg and seg ~= "" then return seg end
    local ok, id = pcall(plugin.id)
    if ok and type(id) == "string" and id ~= "" then return id end
    return "ds_ai_agent"
end

function plugin_base_dir()
    local d = tostring(game.dataDir() or "")
    local base = d:gsub("/插件数据文件/[^/]*$", "")
    if base == d or base == "" then base = d end
    return base
end

function plugin_code_dir()
    return plugin_base_dir() .. "/插件文件/" .. plugin_id_now()
end

function defaults_json_paths()
    local out = {}
    local base = plugin_base_dir()
    local ok, cd = pcall(plugin_code_dir)
    if ok and type(cd) == "string" and cd ~= "" then out[#out + 1] = cd .. "/defaults.json" end
    local dd = tostring(game.dataDir() or "")
    if dd ~= "" then out[#out + 1] = dd .. "/defaults.json" end
    out[#out + 1] = base .. "/插件文件/ds_ai_agent/defaults.json"
    out[#out + 1] = base .. "/插件数据文件/ds_ai_agent/defaults.json"
    return out
end

function item_display_name(id, damage)
    local raw = tostring(id or "")
    local base = lower(raw:gsub("^minecraft:", ""))
    if base == "" then return "?" end
    local dmg = tonumber(damage) or 0
    local nm = nil
    local ok1, dm = pcall(item_damage_data)
    if ok1 and type(dm) == "table" then nm = dm[base .. ":" .. tostring(dmg)] end
    if nm == nil then
        local ok2, names = pcall(item_name_data)
        if ok2 and type(names) == "table" then nm = names[base] end
    end
    if nm == nil then
        local ok3, extra = pcall(extra_sell_prices)
        if ok3 and type(extra) == "table" then
            local e = extra[base]
            if type(e) == "table" and e.name then nm = e.name end
        end
    end
    if nm == nil then
        local ok4, prices = pcall(default_sell_prices)
        if ok4 and type(prices) == "table" then
            local e = prices[base]
            if type(e) == "table" and e.name then nm = e.name end
        end
    end
    nm = tostring(nm or base:gsub("_", " "))
    local cn = nm:match("^(.-)%s*/%s*%a")
    if cn and trim(cn) ~= "" then nm = trim(cn) end
    return nm
end

function restore_defaults_from_zip(src_path)
    local path = tostring(src_path or "")
    if path == "" then
        path = plugin_base_dir() .. "/插件文件/ds_ai_agent.zip"
    end
    local ok, data = pcall(util.read_file, path)
    if not ok or type(data) ~= "string" or #data < 100 then
        return false, "读不到插件包：" .. path
    end
    local pos, found, names = 1, nil, {}
    while true do
        local s = data:find("PK\003\004", pos, true)
        if not s then break end
        local method = string.byte(data, s + 8) + string.byte(data, s + 9) * 256
        local csize = 0
        for i = 0, 3 do csize = csize + string.byte(data, s + 18 + i) * (256 ^ i) end
        local nlen = string.byte(data, s + 26) + string.byte(data, s + 27) * 256
        local elen = string.byte(data, s + 28) + string.byte(data, s + 29) * 256
        local name = data:sub(s + 30, s + 30 + nlen - 1)
        local dstart = s + 30 + nlen + elen
        names[#names + 1] = name .. "(" .. method .. "," .. csize .. ")"
        if method == 0 and csize > 0 and name:find("defaults.json", 1, true) then
            found = data:sub(dstart, dstart + csize - 1)
        end
        pos = dstart + csize
    end
    if not found then
        return false, "包内没找到可解压的 defaults.json，条目：" .. table.concat(names, " / ")
    end
    local target = tostring(game.dataDir() or "") .. "/defaults.json"
    local wok, werr = pcall(util.write_file, target, found)
    if not wok then return false, "写入失败：" .. tostring(werr) end
    pcall(function()
        local cd = plugin_code_dir()
        util.write_file(cd .. "/defaults.json", found)
    end)
    _DEF_CACHE = {}
    _EXTRA_SELL_CACHE = nil
    return true, "已从 zip 还原 defaults.json（" .. #found .. " 字节）→ " .. target
end

function is_backup_intent(t)
    local s = lower(trim(tostring(t or "")))
    if s == "" then return false end
    local has_verb = s:find("打包", 1, true) or s:find("备份", 1, true) or s:find("压缩", 1, true) or s:find("backup", 1, true) or s:find("zip", 1, true)
    if not has_verb then return false end
    local has_obj = s:find("文件", 1, true) or s:find("所有", 1, true) or s:find("全部", 1, true) or s:find("整个", 1, true)
        or s:find("数据", 1, true) or s:find("插件", 1, true) or s:find("服务器", 1, true)
        or s:find("存档", 1, true) or s:find("本地", 1, true) or s:find("本机", 1, true) or s:find("上传", 1, true)
    return has_obj ~= nil
end




