        data_files={"BUILD_VERSION.txt","ds_data.json","chat_logs.json","runtime.log","runtime_pending.log","scoreboard_config.json","seg_core.txt","seg_cmd.txt","seg_build.txt","seg_mcp.txt","full_shop_items.json","item_names.json","item_damage_names.json","sell_prices.json","market.json","market_items_nbt.json","market_item_previews.json","market_storage.json","market_wallet.json","market_offline_notices.json","nbt_regions.json","purchase_logs.json","shop_logs.json","teleport_logs.json","territory_protection_logs.json","territories.json","server_seed.json","fixed_shop.json","ai_personas.json","ai_global_rules.json","ai_stop_flags.json","ai_last_trace.json","ai_tokens.json","ai_hourly_rate.json","ai_build_state.json","coordinate_soul_state.json","agent_picked.json","agent_providers.json","agent_chat_log.json","chat_rate.json","inv_request.json","death_lastpos.json","death_dedup.json","death_samples.json"}
    }}
end

function pack_two_plugins_zip(out_name)
    local files, report = {}, {}
    local function add(zipname, path)
        local ok, data = pcall(util.read_file, path)
        if ok and type(data) == "string" and data ~= "" then
            files[#files + 1] = { name = zipname, data = data }
            report[#report + 1] = zipname .. "  (" .. #data .. " 字节)"
        end
    end
    for _, p in ipairs(backup_plugin_list()) do
        local cd = p.code_dir
        add("插件文件/" .. p.id .. "/" .. p.id .. ".lua", cd .. "/" .. p.id .. ".lua")
        add("插件文件/" .. p.id .. "/" .. p.id .. ".manifest.json", cd .. "/" .. p.id .. ".manifest.json")
        add("插件文件/" .. p.id .. "/" .. p.id .. ".docs.md", cd .. "/" .. p.id .. ".docs.md")
        add("插件文件/" .. p.id .. "/defaults.json", cd .. "/defaults.json")
        add("插件文件/" .. p.id .. "/ds_ai_agent.manifest.json", cd .. "/ds_ai_agent.manifest.json")
        add("插件配置文件/" .. p.id .. "/" .. p.cfg_file, p.cfg_dir .. "/" .. p.cfg_file)
        for _, n in ipairs(p.data_files or {}) do
            add("插件数据文件/" .. p.id .. "/" .. n, p.data_dir .. "/" .. n)
        end
    end
    if #files == 0 then return "打包失败：没有读到任何文件。" end

    local z = zip_build(files)
    local fname = trim(tostring(out_name or ""))
    if fname == "" then fname = "MC两个插件完整备份.zip" end
    fname = fname:match("([^/%\\]+)$") or fname

    local wok, wpath, werr = backup_write_zip(fname, z)
    report[#report + 1] = "-----"
    if not wok then
        report[#report + 1] = "打包失败：写入失败（" .. tostring(werr) .. "）"
        return table.concat(report, "\n")
    end
    local vok, vdata = pcall(util.read_file, wpath)
    local vul = (vok and type(vdata) == "string" and #vdata == #z
                 and vdata:sub(1, 4) == string.char(80, 75, 3, 4))
    report[#report + 1] = "打包 " .. #files .. " 个文件"
    report[#report + 1] = "输出：" .. wpath
    report[#report + 1] = "大小：" .. #z .. " 字节；回读校验：" .. (vul and "通过" or "异常")
    return table.concat(report, "\n")
end

function pack_full_backup_zip(out_name)
    return pack_two_plugins_zip(out_name)
end

function ds_run_two_plugin_backup(playerName, why)
    local fname = "MC两个插件完整备份_" .. tostring(backup_date_tag()) .. ".zip"
    log_event("BACKUP", tostring(playerName or "?") .. " start " .. fname .. " (" .. tostring(why or "") .. ")")
    local ok, report = pcall(pack_two_plugins_zip, fname)
    if not ok then
        log_event("BACKUP", "fail: " .. tostring(report))
        return "§c打包失败：" .. tostring(report)
    end
    local txt = tostring(report or "")
    log_event("BACKUP", "done: " .. txt:gsub("\n", " | "))
    local path, size = nil, nil
    for line in txt:gmatch("[^\r\n]+") do
        local p = line:match("^输出：(.+)$")
        if p then path = trim(p) end
        local s = line:match("^大小：(%d+)%s*字节")
        if s then size = s end
    end
    if not path then
        return "§c" .. txt:gsub("\n", "\n§7")
    end
    return "§a§l✔ §r§a两个插件完整备份已生成"
        .. "\n§f文件：§e" .. fname
        .. "\n§f位置：§7" .. path
        .. (size and ("\n§f大小：§b" .. size .. " 字节") or "")
        .. "\n§7内容：多功能插件 + 死亡点（代码 + 配置 + 数据）"
end

function run_full_backup(playerName, why)
    return ds_run_two_plugin_backup(playerName, why)
end


DS_SAMPLE_FILE   = game.dataDir() .. "/death_samples.json"
DS_TRACK_FILE    = game.dataDir() .. "/death_lastpos.json"
DS_BOOT_FILE     = game.dataDir() .. "/v5_boot.json"
DS_SAMPLE_MAX_AGE = 15
DS_SAMPLE_MAX_PER_TICK = 6
DS_SAMPLE_KEEP   = 200
DS_DEATH_DEDUP_SEC = 8

DS_SENTINELS = {
    ["0,0,0"] = true, ["0,-1,0"] = true, ["0,-2,0"] = true,
    ["0,-3,0"] = true, ["0,-64,0"] = true,
    ["1,72,5"] = true, ["1,71,5"] = true, ["9,67,17"] = true,
    ["1008,66,96"] = true, ["1008,67,96"] = true, ["1008,68,96"] = true,
}
function ds_is_sentinel(x, y, z)
    local k = string.format("%d,%d,%d",
        math.floor(tonumber(x) or 0), math.floor(tonumber(y) or 0), math.floor(tonumber(z) or 0))
    return DS_SENTINELS[k] == true
end
function ds_pos_valid(x, y, z)
    x, y, z = tonumber(x), tonumber(y), tonumber(z)
    if x == nil or y == nil or z == nil then return false end
    if x == 0 and z == 0 then return false end
    if ds_is_sentinel(x, y, z) then return false end
    if y < -64 or y > 320 then return false end
    return true
end

