function ds_online_names()
    local names=online_players() or {}
    if #names>0 then return names end
    local seen={}
    for _,nm in ipairs(known_player_names()) do
        if not seen[nm] then
            local safe=string.gsub(nm,'"','\\"')
            local ok2,hit=pcall(game.isCmdSuccess,'testfor @a[name="'..safe..'"]')
            if ok2 and hit==true then seen[nm]=true; names[#names+1]=nm end
        end
    end
    return names
end

function ds_name_by_uid(uid)
    if uid == nil then return nil end
    local s = tostring(uid)
    if s == "" then return nil end
    local d = ds_samples_load()
    local nm = d.pid2name[s]
    if nm and nm ~= "" then return tostring(nm) end
    for k, v in pairs(d.samples or {}) do
        if type(v) == "table" and tostring(v.uid or "") == s then return tostring(k) end
    end
    local tk = ds_track_load()
    nm = (tk.pid2name or {})[s]
    if nm and nm ~= "" then return tostring(nm) end
    local ok, list = pcall(player.list)
    if ok and type(list) == "table" then
        for _, p in ipairs(list) do
            if type(p) == "table" then
                if tostring(p.unique_id or "") == s or tostring(p.xuid or "") == s then
                    return tostring(p.name or "")
                end
            end
        end
    end
    local ok2, data = pcall(load_data)
    if ok2 and type(data) == "table" and type(data.players) == "table" then
        for _, r in pairs(data.players) do
            if type(r) == "table" then
                if tostring(r.unique_id or "") == s or tostring(r.xuid or "") == s then
                    return tostring(r.name or "")
                end
            end
        end
    end
    return nil
end

function ds_death_sample_tick()
    local names = ds_online_names()
    local d = ds_samples_load()
    local now = util.timestamp()
    local total = #names
    if total > 0 then
        local budget = tonumber(DS_SAMPLE_MAX_PER_TICK) or 6
        if budget < 1 then budget = 1 end
        if budget > total then budget = total end
        local cursor = tonumber(d.cursor) or 0
        if cursor < 0 or cursor >= total then cursor = 0 end

        for i = 0, budget - 1 do
            local idx = (cursor + i) % total + 1
            local nm = names[idx]
            if nm then
                local ok, pos = pcall(game.getPlayerPos, nm)
                if ok and type(pos) == "table" then
                    local x, y, z = tonumber(pos.x), tonumber(pos.y), tonumber(pos.z)
                    if ds_pos_valid(x, y, z) then
                        local uid = ""
                        local okp, pinfo = pcall(player.get, nm)
                        if okp and type(pinfo) == "table" then uid = tostring(pinfo.unique_id or "") end
                        d.samples[nm] = {
                            x = x, y = math.floor(y), z = z,
                            dimension = normalize_dimension(pos.dimension) or "overworld",
                            ts = now, uid = uid,
                        }
                        if uid ~= "" then d.pid2name[uid] = nm end
                    end
                end
            end
        end
        d.cursor = (cursor + budget) % total
    end
    d.last_tick = now
    d.ticks = (tonumber(d.ticks) or 0) + 1

    local cnt = 0
    local arr = {}
    for k, v in pairs(d.samples) do
        cnt = cnt + 1
        arr[#arr + 1] = { k = k, ts = tonumber(type(v) == "table" and v.ts) or 0 }
    end
    for _, it in ipairs(arr) do
        if now - it.ts > 86400 then d.samples[it.k] = nil end
    end
    if cnt > DS_SAMPLE_KEEP then
        table.sort(arr, function(a, b) return a.ts < b.ts end)
        for i = 1, #arr - DS_SAMPLE_KEEP do d.samples[arr[i].k] = nil end
    end
    ds_samples_save(d)
end

DEATH_FRAME_FILE = game.dataDir() .. "/death_frame_pos.json"

local function death_frame_load()
    local ok, d = pcall(util.json_load, DEATH_FRAME_FILE)
    if not ok or type(d) ~= "table" then d = {} end
    d.by_name = d.by_name or {}
    d.by_rid = d.by_rid or {}
    d.name2rid = d.name2rid or {}
    return d
end

local function death_frame_save(d)
    pcall(util.json_write, DEATH_FRAME_FILE, d)
end

function death_frame_pos_set(name, rid, pos)
    if type(pos) ~= "table" then return end
    local x, y, z = tonumber(pos.x), tonumber(pos.y), tonumber(pos.z)
    if not x or not y or not z or not ds_pos_valid(x, y, z) then return end
    local now = util.timestamp()
    local d = death_frame_load()
    local e = {
        x = x, y = math.floor(y), z = z,
        dimension = normalize_dimension(pos.dimension) or "overworld",
        at = now,
    }
    if name and tostring(name) ~= "" then
        local nm = tostring(name)
        d.by_name[nm] = e
        if rid ~= nil then d.name2rid[nm] = tostring(rid) end
    end
    if rid ~= nil then
        d.by_rid[tostring(rid)] = e
    end
    death_frame_save(d)
end

function death_frame_pos_get(name, now)
    if not name or name == "" then return nil end
    now = now or util.timestamp()
    local d = death_frame_load()
    local e = d.by_name[name]
    if type(e) == "table" and (now - (tonumber(e.at) or 0)) <= 1.5 and ds_pos_valid(e.x,e.y,e.z) then
        return {x=tonumber(e.x), y=tonumber(e.y), z=tonumber(e.z),
                dimension=e.dimension or "overworld", at=tonumber(e.at) or 0, src="death-frame"}
    end
    local rid = d.name2rid[name]
    if not rid then
        local tk = load_death_track()
        for k, nm in pairs(tk.rid2name or {}) do
            if tostring(nm) == tostring(name) then rid = k; break end
        end
    end
    if rid then
        e = d.by_rid[tostring(rid)]
        if type(e) == "table" and (now - (tonumber(e.at) or 0)) <= 1.5 and ds_pos_valid(e.x,e.y,e.z) then
            return {x=tonumber(e.x), y=tonumber(e.y), z=tonumber(e.z),
                    dimension=e.dimension or "overworld", at=tonumber(e.at) or 0, src="death-frame"}
        end
    end
    return nil
end

function death_notify(name, lines)
    local nm = tostring(name or "")
    if nm == "" then return false end
    if type(lines) ~= "table" then lines = {tostring(lines or "")} end
    local safe = string.gsub(nm, '"', '\\"')
    local sent = false
    for _, line in ipairs(lines) do
        local payload = json_rawtext(tostring(line or ""))
        if payload then
            local ok = pcall(game.sendCommand, 'tellraw @a[name="' .. safe .. '"] ' .. payload)
            if ok then sent = true else
                local ok2 = pcall(game.sendTargeted, nm, tostring(line or ""))
                if ok2 then sent = true end
            end
        end
    end
    return sent
end

function ds_death_pos_for(name, now)
    now = now or util.timestamp()
    local frame = death_frame_pos_get(name, now)
    if type(frame) == "table" and ds_pos_valid(frame.x, frame.y, frame.z) then
        return frame, false
    end
    local sd = ds_samples_load()
    local sm = sd.samples and sd.samples[name] or nil
    if type(sm)=="table" and ds_pos_valid(sm.x,sm.y,sm.z) then
        local age = math.max(0, now - (tonumber(sm.ts) or 0))
        if age <= 5 then
            return {x=tonumber(sm.x), y=tonumber(sm.y), z=tonumber(sm.z), dimension=sm.dimension or "overworld", at=tonumber(sm.ts) or 0, src="query-3s"}, false
        end
    end
    local pkt = pos_cache_get(name, "pkt")
    if type(pkt)=="table" and ds_pos_valid(pkt.x,pkt.y,pkt.z) then
        local age = math.max(0, now - (tonumber(pkt.at) or 0))
        return pkt, age > 3
    end
    local tk=load_death_track()
    local info=get_info(name)
    local xuid=(info and info.xuid and tostring(info.xuid)~="") and tostring(info.xuid) or name
    for _,k in ipairs({xuid,name}) do
        local fw=type(tk.pos_fw)=="table" and tk.pos_fw[k] or nil
        if type(fw)=="table" and ds_pos_valid(fw.x,fw.y,fw.z) then
            local age=math.max(0, now-(tonumber(fw.at) or 0))
            return fw, age > 6
        end
    end
    return nil,false
end

function ds_is_player_name(nm)
    if not nm or nm == "" then return false end
    local ok, p = pcall(player.get, nm)
    if ok and type(p) == "table" and p.name ~= nil and tostring(p.name) ~= "" then return true end
    for _, x in ipairs(known_player_names()) do
        if x == nm then return true end
    end
    return false
end

function ds_death_record(name, reason)
    name = trim(tostring(name or ""))
    if name == "" then return false end
    if death_dedup_hit(name, DS_DEATH_DEDUP_SEC) then return false end

    local now = util.timestamp()
    local pos, stale = ds_death_pos_for(name, now)

    local d = load_data()
    local key = identity(name)
    d.players = d.players or {}
    local r = d.players[key]
    if type(r) ~= "table" then
        r = { name = name, waypoints = {} }
        d.players[key] = r
    end
    r.name = name
    r.death_count = (tonumber(r.death_count) or 0) + 1

    if pos then
        local dim = normalize_dimension(pos.dimension) or "overworld"
        local px = math.floor(tonumber(pos.x) or 0)
        local py = math.floor(tonumber(pos.y) or 0)
        local pz = math.floor(tonumber(pos.z) or 0)
        r.death = {
            x = px, y = py, z = pz, dimension = dim,
            saved_at = beijing_now(), saved_ts = now_utc_ts(),
            reason = tostring(reason or "v6"), stale = stale or nil,
            correction_until = now + 1.5,
        }
        r.last_death_capture = now
        r.last_pos = { x = px, y = py, z = pz, dimension = dim, at = now }
        r.death_history = r.death_history or {}
        table.insert(r.death_history, {
            x = px, y = py, z = pz, dimension = dim, n = r.death_count,
            saved_at = r.death.saved_at, saved_ts = now_utc_ts(),
            reason = r.death.reason, stale = r.death.stale,
        })
        while #r.death_history > 10 do table.remove(r.death_history, 1) end
    end
    save_data(d)

    local posdesc = "无坐标"
    if pos then
        posdesc = string.format("(%d,%d,%d @%s%s)",
            math.floor(tonumber(pos.x) or 0), math.floor(tonumber(pos.y) or 0),
            math.floor(tonumber(pos.z) or 0), tostring(pos.dimension or "?"),
            stale and " 不新鲜" or "")
    end
    local ok_n, n_err = pcall(function()
        local cost = death_tp_cost()
        local sepline = "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
        local lines = {
            sepline,
            "§1◆ §r§b§l死亡点已记录 §8┃ §7这是第 §e§l" .. tostring(r.death_count) .. " §r§7次",
        }
        if pos then
            lines[#lines + 1] = string.format("§7坐标 §8▸ §f§l%d §7/ §f§l%d §7/ §f§l%d §8[§b%s§8]",
                math.floor(tonumber(pos.x) or 0), math.floor(tonumber(pos.y) or 0),
                math.floor(tonumber(pos.z) or 0),
                dimension_display(normalize_dimension(pos.dimension) or "overworld"))
            if stale then lines[#lines + 1] = "§e⚠ 采集可能不新鲜，坐标仅供参考" end
        else
            lines[#lines + 1] = "§c未采集到坐标（机器人可能缺少 querytarget 权限）"
        end
        local _r20w_day,_r20w_phase=r20w_game_update()
        lines[#lines + 1] = "§7掉落规则 §8| ".._r20w_phase.rule_color.._r20w_phase.rule.." §7".._r20w_phase.name
        lines[#lines + 1] = sepline
        if cost > 0 then
            lines[#lines + 1] = "§6§l⚑ §r§7回点费用 §8▸ §6§l" .. cost .. " §r§7积分"
        else
            lines[#lines + 1] = "§6§l⚑ §r§7本次回点 §a§l免费"
        end
        lines[#lines + 1] = "§7查看记录 §8▸ §b§l.死亡日志 §r§8（再输入 §b1~5 §8传送）"
        lines[#lines + 1] = "§7直接回点 §8▸ §f.死亡点返回 §r§8（可带序号，如 §f.死亡点返回 2§8）"
        lines[#lines + 1] = sepline
        local ok_direct = death_notify(name, lines)
        if not ok_direct then error("death_notify failed") end
    end)
    if not ok_n then
        log_event("DEATH", "死亡提示渲染失败：" .. tostring(n_err))
        pcall(send, name, string.format("§c§l☠ §r§7第 %d 次倒下 §8| §f输入 §e.死亡日志 §7查看并传送",
            tonumber(r.death_count) or 0))
    end
    return true
end

function ds_death_correct_from_position(name, pos, src)
    name=trim(tostring(name or ""))
    if name=="" or type(pos)~="table" then return end
    local x,y,z=tonumber(pos.x),tonumber(pos.y),tonumber(pos.z)
    if not x or not y or not z or not ds_pos_valid(x,y,z) then return end
    local d=load_data(); local key=identity(name); local r=d.players and d.players[key]
    if type(r)~="table" or type(r.death)~="table" then return end
    local now=util.timestamp()
    if now > (tonumber(r.death.correction_until) or 0) then return end
    local oldsrc=tostring(r.death.reason or "")
    local oldx,oldy,oldz=tonumber(r.death.x),tonumber(r.death.y),tonumber(r.death.z)
    if oldx and math.abs(oldx-x)<0.75 and oldy and math.abs(oldy-y)<0.75 and oldz and math.abs(oldz-z)<0.75 then return end
    r.death.x=math.floor(x); r.death.y=math.floor(y); r.death.z=math.floor(z)
    r.death.dimension=normalize_dimension(pos.dimension) or r.death.dimension or "overworld"
    r.death.reason=oldsrc .. "+correct:" .. tostring(src or "pkt")
    r.death.corrected_at=beijing_now()
    if type(r.death_history)=="table" and #r.death_history>0 then
        local h=r.death_history[#r.death_history]
        if type(h)=="table" then
            h.x=r.death.x; h.y=r.death.y; h.z=r.death.z; h.dimension=r.death.dimension
            h.reason=r.death.reason; h.corrected_at=r.death.corrected_at
        end
    end
    save_data(d)
end

function _death_event_fields(data)
    if type(data) ~= "table" then return nil end
    if type(data.fields) == "table" then return data.fields end
    return data
end

function on_death_text(data)
    local f = _death_event_fields(data)
    if type(f) ~= "table" then return end
    local msg = tostring(f.message or "")
    if msg == "" then return end
    local victim = nil
    local params = f.parameters
    if msg:sub(1, 6) == "death." then
        if type(params) == "table" and params[1] ~= nil then victim = tostring(params[1]) end
        if victim == nil or victim == "" then victim = tostring(f.player or f.name or "") end
    else
        local tt = tonumber(f.text_type or f.type) or 0
        if tt == 2 or tt == 0 then
            local plain = util.strip_color(msg)
            victim = plain:match("^(%S+)死了") or plain:match("^(%S+)死亡")
                or plain:match("^(%S+) died") or plain:match("^(%S+) was slain")
                or plain:match("^(%S+) was killed") or plain:match("^(%S+) was shot")
                or plain:match("^(%S+) drowned") or plain:match("^(%S+) fell from")
                or plain:match("^(%S+) burned to death") or plain:match("^(%S+) was slain by")
                or plain:match("^(%S+) hit the ground") or plain:match("^(%S+) went up in flames")
                or plain:match("^(%S+) was impaled") or plain:match("^(%S+) was blown up")
                or plain:match("^(%S+) was stung") or plain:match("^(%S+) starved to death")
        end
    end
    victim = trim(util.strip_color(tostring(victim or "")))
    if victim == "" then return end
    log_event("DEATH", "收到Text死亡信号：" .. victim)
    ds_death_record(victim, "text")
end

function on_death_location(data)
    local f = _death_event_fields(data)
    if type(f) ~= "table" then return end
    if tonumber(f.type) ~= 1 then return end
    if f.entity_unique_id == nil then return end
    local nm = ds_name_by_uid(tostring(f.entity_unique_id))
    if nm and nm ~= "" then ds_death_record(nm, "location") end
end

function ds_pyrpc_die(data, depth)
    if type(data) ~= "table" then return nil end
    depth = depth or 0
    if data.die ~= nil then return data end
    local v = data.value
    if type(v) == "table" then
        if v.die ~= nil then return v end
        local p = ds_pyrpc_die(v, depth + 1)
        if p then return p end
        for _, k in ipairs({ "c", 2, 1 }) do
            local nxt = v[k]
            if type(nxt) == "table" then
                local p2 = ds_pyrpc_die(nxt, depth + 1)
                if p2 then return p2 end
            end
        end
    end
    if depth < 4 then
        for _, k in ipairs({ 2, "c", 1 }) do
            local nxt = data[k]
            if type(nxt) == "table" then
                local p3 = ds_pyrpc_die(nxt, depth + 1)
                if p3 then return p3 end
            end
        end
    end
    return nil
end

function on_pyrpc(data)
    local f = _death_event_fields(data)
    if type(f) ~= "table" then return end
    local code, payload = pyrpc_inner(f)
    if code == PYRPC_CODE_NOISE then return end
    if type(payload)=="table" and payload.die~=nil then
        local p=payload
        local pid=p.pid or p.id or p.uuid
        local nm=ds_name_by_uid(tostring(pid or ""))
        if nm and nm~="" then
            if p.die==true then ds_death_record(nm,"pyrpc") else log_event("DEATH",nm.." 重生") end
        end
        return
    end
    local death_code=false
    for _,c in ipairs(PYRPC_CODE_DEATH_ALT or {}) do if tonumber(code)==tonumber(c) then death_code=true; break end end
    if not death_code then return end
    local p=ds_pyrpc_die(data,0)
    if type(p)~="table" or p.die==nil then return end
    local pid=p.pid or p.id or p.uuid
    local nm=ds_name_by_uid(tostring(pid or ""))
    if not nm or nm=="" then return end
    if p.die==true then ds_death_record(nm,"pyrpc") else log_event("DEATH",nm.." 重生") end
end

function tick_death_fallback()
    pcall(ds_v5_bootstrap)
    local tk = ds_track_load()
    local changed = false
    local ok_list, list = pcall(player.list)
    if ok_list and type(list) == "table" then
        for _, p in ipairs(list) do
            if type(p) == "table" and p.name and p.x ~= nil and p.y ~= nil and p.z ~= nil then
                local x, y, z = tonumber(p.x), tonumber(p.y), tonumber(p.z)
                if x and y and z and not (x == 0 and y == 0 and z == 0) then
                    local feet = math.floor(y - 1.62)
                    if ds_pos_valid(x, feet, z) then
                        local dim = normalize_dimension(p.dimension) or "overworld"
                        local key = (type(p.xuid) == "string" and p.xuid ~= "") and p.xuid or p.name
                        local old = tk.pos_fw[key]
                        if (not old)
                            or math.abs((tonumber(old.x) or 0) - x) >= 0.5
                            or math.floor(tonumber(old.y) or -99999) ~= feet
                            or math.abs((tonumber(old.z) or 0) - z) >= 0.5
                            or normalize_dimension(old.dimension) ~= dim then
                            tk.pos_fw[key] = { x = x, y = feet, z = z, dimension = dim,
                                               name = p.name, at = util.timestamp(), src = "fw" }
                            changed = true
                        end
                        if p.unique_id ~= nil then
                            local pk = tostring(p.unique_id)
                            if tk.pid2name[pk] ~= p.name then
                                tk.pid2name[pk] = p.name
                                changed = true
                            end
                        end
                    end
                end
            end
        end
    end
    if changed then ds_track_save(tk) end
end

function ds_v5_bootstrap()
    return true
end

pcall(ds_v5_bootstrap)


local _v5_prev_on_chat = on_chat
function on_chat(playerName, msg)
    pcall(ds_v5_bootstrap)
    local raw = trim(tostring(msg or ""))
    local low = lower(raw)
    if low == ".备份两个插件" or low == ".打包两个插件" or low == ".完整备份两个插件"
        or low == ".备份全部插件" or low == ".打包全部插件" then
        if not is_admin(playerName) then
            send(playerName, "§c只有管理权限可以备份服务器文件。")
            return
        end
        send(playerName, "§b[备份] §f正在打包两个插件（代码 + 配置 + 数据），请稍候……")
        local result = ds_run_two_plugin_backup(playerName, "指令 " .. raw)
        send(playerName, result)
        return
    end
    if low == ".备份路径" or low == ".打包路径" then
        local b = ds_boot_load()
        send(playerName, "§b━━ 备份路径 ━━\n§f主目录：§e" .. tostring(BACKUP_OUT_DIR)
            .. "\n§f回退：§7" .. table.concat(BACKUP_FALLBACK_DIRS or {}, "、")
            .. "\n§f命令：§e.备份两个插件 §7/ §e.打包"
            .. "\n§8v5引导：text=" .. tostring(b.text_sub) .. " loc=" .. tostring(b.loc_sub)
            .. " sampler=" .. tostring(b.sampler))
        return
    end
    if low == ".死亡采样" then
        ds_death_sample_tick()
        local d = ds_samples_load()
        local lines = { "§b━━ 死亡采样表 ━━" }
        local n = 0
        local now = util.timestamp()
        for k, v in pairs(d.samples or {}) do
            n = n + 1
            if n <= 12 and type(v) == "table" then
                lines[#lines + 1] = string.format("§f%s §7▸ §e%d %d %d §8[%s] §8%d 秒前",
                    tostring(k), math.floor(tonumber(v.x) or 0), math.floor(tonumber(v.y) or 0),
                    math.floor(tonumber(v.z) or 0),
                    dimension_display(normalize_dimension(v.dimension) or "overworld"),
                    now - (tonumber(v.ts) or 0))
            end
        end
        if n == 0 then lines[#lines + 1] = "§c采样表为空（玩家可能都不在线）" end
        lines[#lines + 1] = "§7共 " .. n .. " 条；采样次数 " .. tostring(tonumber(d.ticks) or 0)
        send(playerName, table.concat(lines, "\n"))
        return
    end
    return _v5_prev_on_chat(playerName, msg)
end



