function final_death_name_by_uid(uid)
    uid=tostring(uid or "")
    if uid=="" then return nil end
    local d=final_death_load_samples()
    local nm=d.pid2name[uid]
    if nm and nm~="" then return tostring(nm) end
    for name,v in pairs(d.samples or {}) do
        if type(v)=="table" and tostring(v.uid or "")==uid then return tostring(name) end
    end
    local ok,list=pcall(player.list)
    if ok and type(list)=="table" then
        for _,p in ipairs(list) do
            if type(p)=="table" and (tostring(p.unique_id or "")==uid or tostring(p.xuid or "")==uid) then
                return tostring(p.name or "")
            end
        end
    end
    return ds_name_by_uid(uid)
end

