function final_death_location_handler(data)
    if type(data)~="table" then return end
    if tonumber(data.type)~=1 then return end
    local uid=data.entity_unique_id
    if uid==nil then uid=data.entity_uniqueId end
    local nm=final_death_name_by_uid(uid)
    if nm and nm~="" then
        ds_death_record(nm,"location-final")
    end
end

function final_death_find_payload(data, depth)
    if type(data)~="table" then return nil end
    depth=depth or 0
    if data.die~=nil then return data end
    if depth>5 then return nil end
    for _,k in ipairs({"value","c",1,2,3}) do
        local v=data[k]
        if type(v)=="table" then
            local f=final_death_find_payload(v,depth+1)
            if f then return f end
        end
    end
    return nil
end
function final_death_pyrpc_handler(data)
    local p=final_death_find_payload(data,0)
    if type(p)~="table" or p.die~=true then return end
    local pid=p.pid or p.id or p.uuid or p.entity_unique_id or p.entity_uniqueId
    local nm=final_death_name_by_uid(pid)
    if nm and nm~="" then ds_death_record(nm,"pyrpc-final") end
end


function final_death_actor_event_handler(data)
    local f=_death_event_fields(data)
    if type(f)~="table" or tonumber(f.event_type)~=3 then return end
    local rid=f.entity_runtime_id or f.runtime_entity_id
    local nm=rid_map_get(rid)
    if (not nm or nm=="") and rid~=nil then
        local on=online_players_by_testfor()
        if #on==1 then nm=on[1] end
    end
    if nm and nm~="" then ds_death_record(nm,"actor-event-3") end
end

function final_death_set_actor_data_handler(data)
    local f=_death_event_fields(data)
    if type(f)~="table" then return end
    local md=f.entity_metadata
    local pos=type(md)=="table" and (md["127"] or md[127]) or nil
    if type(pos)~="table" then return end
    local rid=f.entity_runtime_id or f.runtime_entity_id
    local nm=rid_map_get(rid)
    if not nm and rid~=nil then
        local on=online_players_by_testfor(); if #on==1 then nm=on[1] end
    end
    if not nm or nm=="" then return end
    local x,y,z=tonumber(pos[1]),tonumber(pos[2]),tonumber(pos[3])
    if not x or not y or not z or not pos_looks_valid(x,y,z) then return end
    local p={x=x,y=y,z=z,dimension=normalize_dimension((get_info(nm) or {}).dimension) or "overworld"}
    death_frame_pos_set(nm, rid, p)
    pos_cache_set(nm,p,"pkt",true)
    pcall(ds_death_correct_from_position,nm,p,"SetActorData[127]")
end

function final_death_health_handler(data)
    local f=_death_event_fields(data)
    if type(f)~="table" or type(f.attributes)~="table" then return end
    for _,a in ipairs(f.attributes) do
        local av=type(a)=="table" and a.attribute_value or nil
        if type(av)=="table" and tostring(av.name)=="minecraft:health" and tonumber(av.value or 1)<=0 then
            local rid=f.entity_runtime_id or f.runtime_entity_id
            local nm=rid_map_get(rid)
            if (not nm or nm=="") and rid~=nil then local on=online_players_by_testfor(); if #on==1 then nm=on[1] end end
            if nm and nm~="" then ds_death_record(nm,"health-0") end
            return
        end
    end
end

