function log_time_local(epoch)
    local t = tonumber(epoch) or now_utc_ts()
    local ok, v = pcall(beijing_fmt, t, "%Y-%m-%d %H:%M:%S")
    if ok and type(v) == "string" and v ~= "-" then return v end
    local ok2, v2 = pcall(util.time_fmt, t)
    if ok2 and v2 then return tostring(v2) end
    return tostring(t)
end

function save_ai_trace(t)
    t = t or {}
    t.at = beijing_now()
    local raw = tostring(t.raw_body or "")
    if #raw > 5000 then raw = raw:sub(1, 5000) .. "…" end
    t.raw_body = raw
    local out = tostring(t.assistant_output or "")
    if #out > 3000 then out = out:sub(1, 3000) .. "…" end
    t.assistant_output = out
    pcall(util.json_write, AI_TRACE_FILE, t)
end

function ai_sse_usage_extract(raw)
    local best = 0
    local function scan(v, depth)
        if type(v) ~= "table" or (depth or 0) > 4 then return end
        local function consider(t)
            if type(t) ~= "table" then return end
            local total = tonumber(t.total_tokens or t.totalTokens)
            if total and total > best then best = total end
            local pt = tonumber(t.prompt_tokens or t.input_tokens or t.promptTokens or t.input)
            local ct = tonumber(t.completion_tokens or t.output_tokens or t.completionTokens or t.output)
            if pt or ct then
                local sum = (pt or 0) + (ct or 0)
                if sum > best then best = sum end
            end
        end
        consider(v)
        for _, k in ipairs({"usage", "usage_metadata", "token_usage", "tokens", "meta", "data"}) do
            local x = v[k]
            if type(x) == "table" then scan(x, (depth or 0) + 1) end
        end
    end
    for line in tostring(raw or ""):gmatch("[^\r\n]+") do
        local js = line:match("^data:%s*(.+)$")
        if js then
            local ok, d = pcall(http.json_decode, js)
            if ok and type(d) == "table" then scan(d, 0) end
        end
    end
    if best == 0 then
        local mt = tostring(raw or ""):match('"total_tokens"%s*:%s*(%d+)')
        if mt then
            local t = tonumber(mt)
            if t and t > best then best = t end
        end
    end
    return math.floor(best)
end

