AI_CONTEXT_MAX_CHARS = 16000

function ai_context_max_chars()
    local v = tonumber(game.getConfig("ai_context_max_chars", AI_CONTEXT_MAX_CHARS))
    if not v or v < 2000 then v = AI_CONTEXT_MAX_CHARS end
    return math.floor(v)
end

function ai_trim_messages(messages)
    if type(messages) ~= "table" or #messages <= 2 then return messages end
    local budget = ai_context_max_chars()
    local total = 0
    for _, m in ipairs(messages) do
        if type(m) == "table" then total = total + #tostring(m.content or "") end
    end
    if total <= budget then return messages end
    local sys = messages[1]
    local out = {}
    if type(sys) == "table" and sys.role == "system" then
        out[#out + 1] = sys
        budget = budget - #tostring(sys.content or "")
    end
    if budget < 1000 then budget = 1000 end
    local tail, used = {}, 0
    for i = #messages, 2, -1 do
        local m = messages[i]
        if type(m) == "table" then
            local len = #tostring(m.content or "")
            if used + len > budget and #tail > 0 then break end
            used = used + len
            table.insert(tail, 1, m)
        end
    end
    for _, m in ipairs(tail) do out[#out + 1] = m end
    if #out <= 1 then return messages end
    return out
end

function ai_direct_messages(messages, preferred_model, timeout, max_tokens_override)
    if not ai_direct_enabled() then return false, nil, 0, nil, "直连已关闭(ai_direct=false)" end
    local arr = ai_direct_models()
    if type(arr) ~= "table" or #arr == 0 then return false, nil, 0, nil, "读不到 ai_models.json" end
    local per = tonumber(timeout) or TIMEOUT
    if per > 45 then per = 45 end
    if per < 5 then per = 5 end
    local pref = lower(trim(tostring(preferred_model or "")))
    local order, errs = {}, {}
    for _, cfg in ipairs(arr) do
        if type(cfg) == "table" then
            local nm = lower(tostring(cfg.name or ""))
            local mid = lower(tostring(cfg.model_id or ""))
            if pref ~= "" and (nm == pref or mid == pref) then order[#order + 1] = cfg end
        end
    end
    for _, cfg in ipairs(arr) do
        if type(cfg) == "table" then
            local nm = lower(tostring(cfg.name or ""))
            local mid = lower(tostring(cfg.model_id or ""))
            if not (pref ~= "" and (nm == pref or mid == pref)) then order[#order + 1] = cfg end
        end
    end
    local tries = 0
    for _, cfg in ipairs(order) do
        if tries >= 4 then break end
        local tag = tostring(cfg.name or cfg.model_id or "?")
        for attempt = 1, 2 do
            if tries >= 4 then break end
            tries = tries + 1
            local ok, txt, tok, model, err = ai_direct_once(cfg, messages, per, max_tokens_override)
            if ok then return true, txt, tok, model, nil end
            errs[#errs + 1] = tag .. (attempt > 1 and "(重试)" or "") .. "→" .. tostring(err)
        end
    end
    return false, nil, 0, nil, table.concat(errs, "；"):sub(1, 300)
end

