PERIODIC_BEAT_FILE = game.dataDir() .. "/periodic_beat.json"
PERIODIC_BEAT_FRESH = 8    -- 心跳多久算新鲜（秒）
PERIODIC_BEAT_GAP   = 3    -- 心跳最多几秒写一次盘

function periodic_beat_now()
    local ok, t = pcall(util.timestamp)
    if ok and tonumber(t) then return math.floor(tonumber(t)) end
    return os.time() or 0
end

function periodic_beat_write(tag, force)
    local now = periodic_beat_now()
    if not force then
        local ok, raw = pcall(util.read_file, PERIODIC_BEAT_FILE)
        if ok and type(raw) == "string" and raw ~= "" then
            local ok2, d = pcall(http.json_decode, raw)
            if ok2 and type(d) == "table" and (now - (tonumber(d.at) or 0)) < PERIODIC_BEAT_GAP then
                return false
            end
        end
    end
    pcall(util.write_file, PERIODIC_BEAT_FILE,
        http.json_encode({ at = now, tag = tostring(tag or "") }))
    return true
end

function periodic_beat_age()
    local ok, raw = pcall(util.read_file, PERIODIC_BEAT_FILE)
    if not ok or type(raw) ~= "string" or raw == "" then return 9999999 end
    local ok2, d = pcall(http.json_decode, raw)
    if not ok2 or type(d) ~= "table" then return 9999999 end
    return periodic_beat_now() - (tonumber(d.at) or 0)
end

PERIODIC_TASKS_SPEC = {
    {1,  "tick_coordinate_and_soul"},   -- 灵魂倒计时 / 坐标传送 / 签到（必须 1 秒）
    {3,  "flush_log_buffer"},
    {5,  "tick_chat_mute"},
    {5,  "tick_territories"},
    {5,  "tick_death_fallback"},
    {6,  "ds_death_sample_tick"},
    {10, "expire_system_state"},
    {VOTE_CHECK_INTERVAL,   "on_vote_tick"},
    {ANNOUNCEMENT_INTERVAL, "on_announcement_tick"},
}

function register_periodic_tasks()
    local n = 0
    for _, item in ipairs(PERIODIC_TASKS_SPEC) do
        local ok, h = pcall(util.schedule, item[1], item[2])
        if ok and type(h) == "number" and h > 0 then n = n + 1 end
    end
    return n
end

function ensure_periodic_tasks(force)
    if not force and periodic_beat_age() < PERIODIC_BEAT_FRESH then return false end
    return register_periodic_tasks() > 0
end

local _v9_prev_tick_soul = tick_coordinate_and_soul
function tick_coordinate_and_soul()
    periodic_beat_write("soul")
    if type(_v9_prev_tick_soul) == "function" then return _v9_prev_tick_soul() end
end

function soul_expire_check_all()
    local db = coord_soul_state_db()
    local now = periodic_beat_now()
    local n = 0
    for nm, p in pairs(db.players or {}) do
        if type(p) == "table" and type(p.soul) == "table"
            and now >= (tonumber(p.soul.return_at) or 0) then
            if soul_expire_check_player(nm) then n = n + 1 end
        end
    end
    return n
end

function soul_expire_check_all_online()
    local names = online_names_from_list() or {}
    local n = 0
    for _, nm in ipairs(names) do
        if soul_expire_check_player(nm) then n = n + 1 end
    end
    return n
end
function soul_expire_check_player(playerName)
    local n = tostring(playerName or "")
    if n == "" then return false end
    local db = coord_soul_state_db()
    local p = db.players and db.players[n]
    if type(p) ~= "table" or type(p.soul) ~= "table" then return false end
    local soul = p.soul
    local now = periodic_beat_now()
    if now < (tonumber(soul.return_at) or 0) then return false end
    local loc = clone_saved_position(soul.location)
    local original = soul.original_mode or "survival"
    p.soul = nil
    p.soul_cooldown_until = now + SOUL_COOLDOWN
    coord_soul_state_save(db)
    local ok2, err2 = tp_to(n, loc)
    local mode_ok = set_gamemode(n, original)
    soul_actionbar(n, "§a灵魂出窍结束 §7冷却30秒")
    if ok2 and mode_ok then
        send(n, "§a✓ 灵魂出窍结束，已自动返回原位置并恢复原模式。")
    elseif ok2 then
        send(n, "§e✓ 已返回原位置，但恢复原游戏模式失败，请手动切换回：" .. tostring(original))
    else
        send(n, "§c灵魂出窍返回失败：" .. tostring(err2))
    end
    send(n, "§7灵魂出窍冷却已开始：30秒后可再次使用。")
    return true
end


function soul_timeout_guard()
    pcall(soul_expire_check_all)
end

local _v9_prev_start_soul = start_soul
function start_soul(name)
    local r = _v9_prev_start_soul(name)
    pcall(util.setTimeout, SOUL_DURATION + 2, "soul_timeout_guard")
    return r
end


local _v9_prev_on_chat = on_chat
function on_chat(playerName, msg)
    pcall(ensure_periodic_tasks)
    local low = lower(trim(tostring(msg or "")))

    if low == ".ai通道" or low == ".ai费用" or low == ".token诊断" then
        local lines = { "§b━━ AI 通道 / Token 自检 ━━" }
        lines[#lines + 1] = "§f直连开关：§e" .. (ai_direct_enabled() and "§a开启" or "§c关闭")
        lines[#lines + 1] = "§f备用通道：§e§a已关闭"
        local arr = ai_direct_models()
        if type(arr) == "table" and #arr > 0 then
            lines[#lines + 1] = "§f可用直连模型：§e" .. #arr .. " §7个"
            for _, m in ipairs(arr) do
                if type(m) == "table" then
                    lines[#lines + 1] = "§7· §f" .. tostring(m.name or "?")
                        .. " §8(" .. tostring(m.model_id or "?") .. ")"
                end
            end
        else
            lines[#lines + 1] = "§c读不到 ai_models.json；请检查直连模型配置"
        end
        lines[#lines + 1] = "§f上下文上限：§e" .. tostring(ai_context_max_chars()) .. " §7字"
        local okt, t = pcall(util.json_load, AI_TRACE_FILE)
        if okt and type(t) == "table" then
            lines[#lines + 1] = "§8最近：" .. tostring(t.model or "?") .. " / " .. tostring(t.reason or "?")
            lines[#lines + 1] = "§8单次 token=§f" .. tostring(t.usage_tokens or 0) .. " §8时间=" .. tostring(t.at or "?")
        end
        send(playerName, table.concat(lines, "\n"))
        return
    end

    if low == ".定时器状态" or low == ".周期状态" then
        local age = periodic_beat_age()
        local lines = { "§b━━ 周期任务自检 ━━" }
        lines[#lines + 1] = string.format("§f心跳年龄：§e%.0f §7秒（< %d 秒 = 定时器在跑）", age, PERIODIC_BEAT_FRESH)
        lines[#lines + 1] = "§f状态：§e" .. (age < PERIODIC_BEAT_FRESH and "§a运行中" or "§c未运行（任意事件会自动补注册）")
        lines[#lines + 1] = "§7心跳文件：" .. tostring(PERIODIC_BEAT_FILE)
        lines[#lines + 1] = "§7共 " .. tostring(#PERIODIC_TASKS_SPEC) .. " 个周期任务"
        send(playerName, table.concat(lines, "\n"))
        return
    end

    if low == ".灵魂状态" then
        local db = coord_soul_state_db()
        local p = db.players and db.players[tostring(playerName)]
        if type(p) == "table" and type(p.soul) == "table" then
            local remain = math.max(0, (tonumber(p.soul.return_at) or 0) - periodic_beat_now())
            send(playerName, string.format("§b灵魂出窍中：剩余 §e%d §b秒；冷却至 §e%s",
                math.ceil(remain), tostring(p.soul_cooldown_until or 0)))
        else
            send(playerName, "§7你当前不在灵魂出窍状态。")
        end
        return
    end

    pcall(soul_expire_check_player, playerName)
    return _v9_prev_on_chat(playerName, msg)
end



PERIODIC_REG_GAP = 3   -- 几秒内重复注册视为重复调用
_PERIODIC_REG_AT = -999

local _v10_raw_register_periodic_tasks = register_periodic_tasks
function register_periodic_tasks()
    local now = periodic_beat_now()
    if now - (tonumber(_PERIODIC_REG_AT) or -999) < PERIODIC_REG_GAP then
        return 0   -- 刚注册过，忽略这次重复调用
    end
    _PERIODIC_REG_AT = now
    return _v10_raw_register_periodic_tasks()
end

