function on_init()
    local r = nil
    if type(_v10_prev_on_init) == "function" then r = _v10_prev_on_init() end
    pcall(ensure_periodic_tasks)
    return r
end



AI_DIRECT_MIN_MAXTOK = 2048
AI_DIRECT_RETRY_MAXTOK = 8192
AI_DIRECT_TIMEOUT_CAP = 90

function ai_direct_once(cfg, messages, timeout, max_tokens_override)
    local url = ai_direct_url(cfg.base_url)
    local key = trim(tostring(cfg.api_key or ""))
    if url == "" or key == "" then return false, nil, 0, nil, "无 base_url/api_key" end
    local model_tag = tostring(cfg.name or cfg.model_id or "")
    local mt0 = tonumber(max_tokens_override) or MAX_REPLY
    if mt0 > AI_DIRECT_RETRY_MAXTOK then mt0 = AI_DIRECT_RETRY_MAXTOK end
    if mt0 < AI_DIRECT_MIN_MAXTOK then mt0 = AI_DIRECT_MIN_MAXTOK end

    local function once(mt)
        local req = {
            model = tostring(cfg.model_id or ""),
            messages = messages,
            temperature = TEMPERATURE,
            max_tokens = mt,
            stream = false,
        }
        if not ai_thinking_enabled() then
            req.thinking = { type = "disabled" }
            req.reasoning_effort = "none"
        end
        local ok_post, r = pcall(http.post, url, http.json_encode(req), {
            headers = { ["Content-Type"] = "application/json", ["Authorization"] = "Bearer " .. key },
            timeout = timeout,
        })
        if not ok_post then return false, nil, 0, nil, "网络异常：" .. tostring(r) end
        if not r or not r.ok then return false, nil, 0, nil, "请求失败：" .. tostring(r and (r.error or r.status) or "无响应") end
        local code = tonumber(r.status) or 0
        local rbody = tostring(r.body or "")
        if code == 429 then return false, nil, 0, nil, "限速(429)：" .. rbody:sub(1, 120) end
        if code < 200 or code >= 300 then return false, nil, 0, nil, "HTTP " .. code .. "：" .. rbody:sub(1, 160) end
        local ok2, data = pcall(http.json_decode, rbody)
        if not ok2 or type(data) ~= "table" then return false, nil, 0, nil, "返回非 JSON" end
        local tok = ai_usage_extract(data)
        local ch = data.choices and data.choices[1]
        local msg = ch and ch.message
        local fin = tostring(ch and ch.finish_reason or "?")
        local c = msg and msg.content
        if (not c or trim(tostring(c)) == "") and msg then c = msg.reasoning_content or msg.reasoning end
        if not c or trim(tostring(c)) == "" then
            return false, nil, tok, fin, "模型无内容(finish=" .. fin .. ")"
        end
        return true, tostring(c), tok, fin, nil
    end

    local ok1, c1, t1, fin1, e1 = once(mt0)
    if ok1 then return true, c1, t1, model_tag, nil end
    if fin1 == "length" and mt0 < AI_DIRECT_RETRY_MAXTOK then
        local ok2, c2, t2, _f2, e2 = once(AI_DIRECT_RETRY_MAXTOK)
        if ok2 then return true, c2, t2, model_tag, nil end
        return false, nil, t2, nil, tostring(e2)
    end
    return false, nil, t1, nil, tostring(e1)
end

function ai_direct_messages(messages, preferred_model, timeout, max_tokens_override)
    if not ai_direct_enabled() then return false, nil, 0, nil, "直连已关闭(ai_direct=false)" end
    local arr = ai_direct_models()
    if type(arr) ~= "table" or #arr == 0 then return false, nil, 0, nil, "读不到 ai_models.json" end
    local per = tonumber(timeout) or TIMEOUT
    if per > AI_DIRECT_TIMEOUT_CAP then per = AI_DIRECT_TIMEOUT_CAP end
    if per < 5 then per = 5 end
    local pref = lower(trim(tostring(preferred_model or "")))
    local order, errs = {}, {}
    for _, cfg in ipairs(arr) do
        if type(cfg) == "table" then
            local nm = lower(tostring(cfg.name or ""))
            local mid = lower(tostring(cfg.model_id or ""))
            if pref ~= "" and (nm == pref or mid == pref) then order[#order + 1] = cfg end
        end
    end
    for _, cfg in ipairs(arr) do
        if type(cfg) == "table" then
            local nm = lower(tostring(cfg.name or ""))
            local mid = lower(tostring(cfg.model_id or ""))
            if not (pref ~= "" and (nm == pref or mid == pref)) then order[#order + 1] = cfg end
        end
    end
    local tries = 0
    for _, cfg in ipairs(order) do
        if tries >= 4 then break end
        local tag = tostring(cfg.name or cfg.model_id or "?")
        for attempt = 1, 2 do
            if tries >= 4 then break end
            tries = tries + 1
            local ok, txt, tok, model, err = ai_direct_once(cfg, messages, per, max_tokens_override)
            if ok then return true, txt, tok, model, nil end
            errs[#errs + 1] = tag .. (attempt > 1 and "(重试)" or "") .. "→" .. tostring(err)
        end
    end
    return false, nil, 0, nil, table.concat(errs, "；"):sub(1, 300)
end



AI_DIRECT_BUDGET_SEC = 45

function ai_direct_budget_sec()
    local v = tonumber(game.getConfig("ai_direct_budget_sec", AI_DIRECT_BUDGET_SEC))
    if not v or v < 10 then v = AI_DIRECT_BUDGET_SEC end
    if v > 110 then v = 110 end   -- 留出余量，绝不碰 2 分钟执行上限
    return math.floor(v)
end

function ai_direct_messages(messages, preferred_model, timeout, max_tokens_override, deadline)
    if not ai_direct_enabled() then return false, nil, 0, nil, "直连已关闭(ai_direct=false)" end
    local arr = ai_direct_models()
    if type(arr) ~= "table" or #arr == 0 then return false, nil, 0, nil, "读不到 ai_models.json" end
    local per = tonumber(timeout) or TIMEOUT
    if per > AI_DIRECT_TIMEOUT_CAP then per = AI_DIRECT_TIMEOUT_CAP end
    if per < 5 then per = 5 end
    local now0 = periodic_beat_now()
    local dl = tonumber(deadline) or (now0 + ai_direct_budget_sec())
    local pref = lower(trim(tostring(preferred_model or "")))
    local order, errs = {}, {}
    for _, cfg in ipairs(arr) do
        if type(cfg) == "table" then
            local nm = lower(tostring(cfg.name or ""))
            local mid = lower(tostring(cfg.model_id or ""))
            if pref ~= "" and (nm == pref or mid == pref) then order[#order + 1] = cfg end
        end
    end
    for _, cfg in ipairs(arr) do
        if type(cfg) == "table" then
            local nm = lower(tostring(cfg.name or ""))
            local mid = lower(tostring(cfg.model_id or ""))
            if not (pref ~= "" and (nm == pref or mid == pref)) then order[#order + 1] = cfg end
        end
    end
    local tries = 0
    for _, cfg in ipairs(order) do
        if tries >= 4 then break end
        local tag = tostring(cfg.name or cfg.model_id or "?")
        for attempt = 1, 2 do
            if tries >= 4 then break end
            local remain = dl - periodic_beat_now()
            if remain < 5 then
                errs[#errs + 1] = tag .. "→总预算不足，已停止重试"
                break
            end
            tries = tries + 1
            local use_to = math.min(per, remain)
            local ok, txt, tok, model, err = ai_direct_once(cfg, messages, use_to, max_tokens_override)
            if ok then return true, txt, tok, model, nil end
            errs[#errs + 1] = tag .. (attempt > 1 and "(重试)" or "") .. "→" .. tostring(err)
        end
    end
    return false, nil, 0, nil, table.concat(errs, "；"):sub(1, 300)
end

call_ai = function(messages, timeout_override, model_override, max_tokens_override)
    local configured_model = ai_active_model()
    if model_override ~= nil and trim(tostring(model_override)) ~= "" then
        configured_model = trim(tostring(model_override))
    end
    local tmo = timeout_override or TIMEOUT
    messages = ai_trim_messages(messages)
    local dl = periodic_beat_now() + ai_direct_budget_sec()

    local dok, dtext, dtok, dmodel, derr = ai_direct_messages(messages, configured_model, tmo, max_tokens_override, dl)
    if dok then
        local _t = tonumber(dtok) or 0
        AI_USAGE.last_call = _t
        AI_USAGE.task = (tonumber(AI_USAGE.task) or 0) + _t
        AI_USAGE.task_calls = (tonumber(AI_USAGE.task_calls) or 0) + 1
        save_ai_trace({ model = tostring(dmodel or configured_model), status = "response_ok_direct",
            status_code = 200, reason = "直连供应商（省 token）",
            assistant_output = tostring(dtext), usage_tokens = _t })
        return dtext
    end

    local api_url, configured_key = ai_endpoint_for(configured_model)
    if configured_key ~= "" then
        local req = {
            model = configured_model, messages = messages,
            temperature = TEMPERATURE, max_tokens = tonumber(max_tokens_override) or MAX_REPLY,
        }
        if not ai_thinking_enabled() then req.thinking = { type = "disabled" } end
        local ok_post, r = pcall(http.post, api_url, http.json_encode(req), {
            headers = { ['Content-Type'] = 'application/json', ['Authorization'] = 'Bearer ' .. configured_key },
            timeout = math.min(tmo, ai_direct_budget_sec()),
        })
        if ok_post and r and r.ok then
            local code = tonumber(r.status) or 0
            if code >= 200 and code < 300 then
                local ok2, data = pcall(http.json_decode, tostring(r.body or ""))
                if ok2 and type(data) == "table" then
                    local ch = data.choices and data.choices[1]
                    local msg = ch and ch.message
                    local c = msg and msg.content
                    if (not c or trim(tostring(c)) == "") and msg then c = msg.reasoning or msg.reasoning_content end
                    if c and trim(tostring(c)) ~= "" then
                        local _t = ai_usage_extract(data)
                        AI_USAGE.last_call = _t
                        AI_USAGE.task = (tonumber(AI_USAGE.task) or 0) + _t
                        AI_USAGE.task_calls = (tonumber(AI_USAGE.task_calls) or 0) + 1
                        save_ai_trace({ model = configured_model, status = "response_ok",
                            status_code = code, reason = "插件自配直连",
                            assistant_output = tostring(c), usage_tokens = _t })
                        return tostring(c)
                    end
                end
            end
        end
    end

    error("AI 调用失败｜直连：" .. tostring(derr))

end



