AI_THINK_TEXT = "§a正在思考中"

AI_THINK_FILE         = game.dataDir() .. "/ai_think_state.json"
AI_THINK_TIMEOUT_EXTRA = 30   -- 超过预估 + 30 秒视为异常，自动清理，避免 actionbar 卡住

function ai_think_db()
    local ok, d = pcall(util.json_load, AI_THINK_FILE)
