function ai_think_save(d) pcall(util.json_write, AI_THINK_FILE, d or {}) end

function ai_bot_identity()
    local ok, b = pcall(bot.current)
    if ok and type(b) == "table" and trim(tostring(b.name or "")) ~= "" then
        return trim(tostring(b.name))
    end
    local ok2, names = pcall(function() return online_players() end)
    if ok2 and type(names) == "table" and #names == 1 then
