AI_WAIT_RULES = {
    { id = "build",  sec = 60, kw = {
        "建筑","建造","盖房","盖个","造房","施工","房子","别墅","城堡","庄园","庭院",
        "小镇","豪宅","搭个","建个","建一","修个","造个","围墙","城墙","地基","楼层",
        "室内","继续施工","停止建筑","关闭建筑",
    } },
    { id = "backup", sec = 30, kw = { "备份","打包","压缩" } },
    { id = "redeem", sec = 25, kw = { "兑换" } },
    { id = "cmd",    sec = 18, kw = {
        "给我","give","传送","tp ","tpa","杀死","kill","gamemode","模式","附魔","enchant",
        "effect","setblock","fill","clone","summon","召唤","清除","执行","改成","换成",
        "刷","定位","locate","time set","weather","时间","天气","下雨","停雨","雷暴",
        "踢","禁言","封","解封","op ","搭建","放","挖","种",
    } },
    { id = "query",  sec = 6,  kw = {
        "查询","查看","我的","分数","记分板","标签","坐标","在线","多少人","信息",
        "状态","等级","有哪些","是什么","几点","背包",
    } },
}

function ai_predict_wait(question, commandMode)
    local q = lower(tostring(question or ""))
    local best = commandMode and 18 or 8
    local best_id = commandMode and "cmd" or "chat"
    for _, rule in ipairs(AI_WAIT_RULES) do
        for _, k in ipairs(rule.kw) do
            if q:find(lower(k), 1, true) then
                if tonumber(rule.sec) and tonumber(rule.sec) > best then
                    best = tonumber(rule.sec)
                    best_id = rule.id
                end
                break
            end
        end
    end
    return best, best_id
end

function ai_think_begin(playerName, question, commandMode, publicReply)
    local name = tostring(playerName or "")
    if name == "" then return 0, "chat" end
    local sec, kind = ai_predict_wait(question, commandMode)
    local d = ai_think_db()
    d[name] = {
        at       = periodic_beat_now(),
        expect   = sec,
        kind     = kind,
        public   = (publicReply == true),
        question = tostring(question or ""):sub(1, 120),
    }
    ai_think_save(d)

    local line = AI_TAG_BLUE .. " " .. AI_THINK_TEXT .. "§7……  §8预计约 §e"
        .. tostring(sec) .. " §8秒"
    if publicReply then pcall(broadcast, line) else pcall(send, name, line) end
    pcall(game.sendActionbar, name, AI_TAG_BLUE .. " " .. AI_THINK_TEXT .. "§7…")
    return sec, kind
end

function ai_think_end(playerName)
    local name = tostring(playerName or "")
    if name == "" then return end
    local d = ai_think_db()
    local st = d[name]
    if st ~= nil then
        d[name] = nil
        ai_think_save(d)
        if type(st) == "table" then
            local cost = periodic_beat_now() - (tonumber(st.at) or 0)
            pcall(log_event, "AI_WAIT", string.format("%s 实际 %d 秒 / 预估 %d 秒 (%s)",
                name, cost, tonumber(st.expect) or 0, tostring(st.kind or "?")))
        end
    end
    pcall(game.sendActionbar, name, "")
end

function ai_think_tick()
    local d = ai_think_db()
    local now = periodic_beat_now()
    local changed = false
    for nm, st in pairs(d) do
        if type(st) ~= "table" then
            d[nm] = nil
            changed = true
        else
            local at     = tonumber(st.at) or now
            local expect = tonumber(st.expect) or 8
            local elapsed = now - at
            if elapsed > expect + AI_THINK_TIMEOUT_EXTRA then
                d[nm] = nil
                changed = true
            else
                local remain = math.ceil(expect - elapsed)
                local text
                if remain > 0 then
                    text = AI_TAG_BLUE .. " " .. AI_THINK_TEXT .. "§7… §8预计还需 §e"
                        .. tostring(remain) .. " §8秒"
                else
                    text = AI_TAG_BLUE .. " " .. AI_THINK_TEXT .. "§7… §8马上就好"
                end
                pcall(game.sendActionbar, nm, text)
            end
        end
    end
    if changed then ai_think_save(d) end
end

