local _v13_prev_on_chat = on_chat
function on_chat(playerName, msg)
    local raw = trim(tostring(msg or ""))
    local low = lower(raw)

    local is_cmd_entry = (raw:sub(1, #COMMAND_WORD) == COMMAND_WORD)
    local is_ai_entry  = (low:sub(1, 3) == "ai ")
    local is_agent_entry = (low:sub(1, 9) == "ai agent " or low == "ai agent")

    local began = false
    if (is_cmd_entry or is_ai_entry) and not is_agent_entry then
        local question
        if is_cmd_entry then
            question = trim(raw:sub(#COMMAND_WORD + 1))
        else
            question = trim(raw:sub(4))
        end
        local publicReply = (not is_cmd_entry) and (raw:sub(1, 3) == "AI ")
        local m = lower(trim(question))
        local is_memory = (m == "清除记忆" or m == "清空记忆"
            or m == "清除聊天记忆" or m == "忘记之前的聊天")
        if question ~= "" and not is_memory then
            pcall(ai_think_begin, playerName, question, is_cmd_entry, publicReply)
            began = true
        end
    end

    local ok, r = pcall(_v13_prev_on_chat, playerName, msg)
    if began then pcall(ai_think_end, playerName) end
    if not ok then error(r) end
    return r
end

function ai_think_diag(playerName)
    local d = ai_think_db()
    local now = periodic_beat_now()
    local lines = { "§b━━ AI 思考状态 ━━" }
    local n = 0
    for nm, st in pairs(d) do
        n = n + 1
        if type(st) == "table" then
            lines[#lines + 1] = string.format("§f%s §7▸ 预估 §e%s§7 秒 §8| 已过 §e%d§7 秒 §8| %s",
                tostring(nm), tostring(st.expect or "?"), now - (tonumber(st.at) or now),
                tostring(st.kind or "?"))
        end
    end
    if n == 0 then lines[#lines + 1] = "§7当前没有正在思考的 AI 任务。" end
    lines[#lines + 1] = "§7执行者身份：§e" .. tostring(ai_bot_identity())
    lines[#lines + 1] = "§7预估规则：" .. tostring(#AI_WAIT_RULES) .. " 组关键词"
    send(playerName, table.concat(lines, "\n"))
    return true
end

local _v13_prev_on_chat_diag = on_chat
function on_chat(playerName, msg)
