function ai_vote_explicitly_requested(playerName)
    local d = ai_think_db()
    local st = d[tostring(playerName or "")]
    local q = (type(st) == "table") and tostring(st.question or "") or ""
    return q:find("投票", 1, true) ~= nil
end

_V14_CUR_PLAYER = nil
_V14_VOTE_AS_CMD = nil

local _v14_prev_extract = extract
function extract(text, tag)
    if tag == "LOAD_SUB_PROMPT" then
        _V14_VOTE_AS_CMD = nil          -- 每轮重新开始收集
    end

    if tag == "VOTE" then
        local arr = _v14_prev_extract(text, "VOTE")
        if #arr > 0 and _V14_CUR_PLAYER then
            local ok_admin = false
            pcall(function() ok_admin = (is_admin(_V14_CUR_PLAYER) == true) end)
            if ok_admin and not ai_vote_explicitly_requested(_V14_CUR_PLAYER) then
                _V14_VOTE_AS_CMD = _V14_VOTE_AS_CMD or {}
                for _, c in ipairs(arr) do
                    _V14_VOTE_AS_CMD[#_V14_VOTE_AS_CMD + 1] = c
                end
                return {}               -- 不交给 VOTE 分支
            end
        end
        return arr
    end

    if tag == "CMD" then
        local arr = _v14_prev_extract(text, "CMD")
        if _V14_VOTE_AS_CMD and #_V14_VOTE_AS_CMD > 0 then
            for _, c in ipairs(_V14_VOTE_AS_CMD) do arr[#arr + 1] = c end
            _V14_VOTE_AS_CMD = nil      -- 消费一次
        end
        return arr
    end

    return _v14_prev_extract(text, tag)
end

local _v14_prev_start_vote = start_vote
start_vote = function(playerName, cmd)
    local ok_admin = false
    pcall(function() ok_admin = (is_admin(playerName) == true) end)
    if ok_admin and not ai_vote_explicitly_requested(playerName) then
        local r = run_command(tostring(cmd or ""), playerName, true)
        pcall(send, playerName, "§a✓ 管理权限：已直接执行 §e" .. tostring(cmd or "")
            .. "§a。\n§7如需全服投票，请明确说「投票」两个字（例：§f投票 调白天§7）。")
        return r
    end
    return _v14_prev_start_vote(playerName, cmd)
end

PERIODIC_ID_FILE = game.dataDir() .. "/periodic_ids.json"

PERIODIC_TASKS_SPEC = {
    {1,  "tick_coordinate_and_soul"},   -- 灵魂倒计时 / 坐标传送 / 签到（必须 1 秒）
    {5,  "flush_log_buffer"},           -- 原 3 秒
    {15, "tick_chat_mute"},             -- 原 5 秒（禁言系统已移除，只剩到期清理）
    {8,  "tick_territories"},           -- 原 5 秒
    {15, "tick_death_fallback"},        -- 原 5 秒（内部实体存在性检查本来就 30 秒节流）
    {6,  "ds_death_sample_tick"},       -- 死亡点采样，保持
    {10, "expire_system_state"},
    {VOTE_CHECK_INTERVAL,   "on_vote_tick"},
    {ANNOUNCEMENT_INTERVAL, "on_announcement_tick"},
}

function periodic_cancel_old()
    local ok, d = pcall(util.json_load, PERIODIC_ID_FILE)
    if not ok or type(d) ~= "table" then return 0 end
    local n = 0
    for _, id in ipairs(d.ids or {}) do
        local v = tonumber(id)
        if v then pcall(util.cancel, v); n = n + 1 end
    end
    return n
end

function register_periodic_tasks()
    local cancelled = 0
    pcall(function() cancelled = periodic_cancel_old() end)
    local ids = {}
    for _, item in ipairs(PERIODIC_TASKS_SPEC) do
        local ok, h = pcall(util.schedule, item[1], item[2])
        if ok and type(h) == "number" and h > 0 then ids[#ids + 1] = h end
    end
    pcall(util.json_write, PERIODIC_ID_FILE, {
        ids = ids, cancelled = cancelled, at = periodic_beat_now(),
    })
    return #ids
end

function ai_think_tick()
    local d = ai_think_db()
    if type(d) ~= "table" or next(d) == nil then return end   -- 没人思考：零开销
    local now = periodic_beat_now()
    local changed = false
    for nm, st in pairs(d) do
        if type(st) ~= "table" then
            d[nm] = nil
            changed = true
        else
            local at = tonumber(st.at) or now
            local expect = tonumber(st.expect) or 8
            local elapsed = now - at
            if elapsed > expect + AI_THINK_TIMEOUT_EXTRA then
                d[nm] = nil
                changed = true
            elseif elapsed % 2 == 0 then
                local remain = math.ceil(expect - elapsed)
                local text
                if remain > 0 then
                    text = AI_TAG_BLUE .. " " .. AI_THINK_TEXT .. "§7… §8预计还需 §e"
                        .. tostring(remain) .. " §8秒"
                else
                    text = AI_TAG_BLUE .. " " .. AI_THINK_TEXT .. "§7… §8马上就好"
                end
                pcall(game.sendActionbar, nm, text)
            end
        end
    end
    if changed then ai_think_save(d) end
end


