function ai_thinking_set(v, by)
    pcall(util.json_write, AI_THINK_CFG_FILE, {
        enabled = (v == true), by = tostring(by or ""), at = periodic_beat_now(),
    })
end

function ai_thinking_enabled()
    local ov = ai_thinking_override()
    if ov ~= nil then return ov end
    local v = game.getConfig("ai_thinking", false)
    if v == true then return true end
    local s = lower(trim(tostring(v or "")))
    return (s == "true" or s == "1" or s == "on" or s == "yes")
end

