local _v14_prev_on_chat = on_chat
function on_chat(playerName, msg)
    _V14_CUR_PLAYER = playerName

    local raw = trim(tostring(msg or ""))
    local low = lower(raw)

    if low == ".ai思考" or low == ".思考" or low == ".ai思考状态" then
        pcall(send, playerName, ai_thinking_status_text())
        return
    end
    local arg = raw:match("^%.[Aa][Ii]思考%s*(.*)$")
    if arg == nil then arg = raw:match("^%.思考%s*(.*)$") end
    if arg ~= nil and trim(arg) ~= "" then
        if not is_admin(playerName) then
            pcall(send, playerName, "§c只有管理权限可以切换 AI 思考模式。")
            return
        end
        local a = lower(trim(arg))
        if a == "开" or a == "开启" or a == "on" or a == "true" or a == "1" then
            ai_thinking_set(true, playerName)
            pcall(send, playerName, "§a✓ AI 思考已开启。\n" .. ai_thinking_status_text())
        elseif a == "关" or a == "关闭" or a == "off" or a == "false" or a == "0" then
            ai_thinking_set(false, playerName)
            pcall(send, playerName, "§a✓ AI 思考已关闭。\n" .. ai_thinking_status_text())
        else
            pcall(send, playerName, "§e用法：§f.AI思考 开 §e/ §f.AI思考 关 §e/ §f.AI思考（查看）")
        end
        return
    end

    if low == ".性能" or low == ".性能诊断" or low == ".定时器" then
        return cmd_perf_diag(playerName)
    end

    return _v14_prev_on_chat(playerName, msg)
end


function register_periodic_tasks()
    local cancelled = 0
    pcall(function() cancelled = periodic_cancel_old() end)
    local ids, ok_n = {}, 0
    for _, item in ipairs(PERIODIC_TASKS_SPEC) do
        local ok, h = pcall(util.schedule, item[1], item[2])
        if ok then
            ok_n = ok_n + 1
            if type(h) == "number" and h > 0 then ids[#ids + 1] = h end
        end
    end
    pcall(util.json_write, PERIODIC_ID_FILE, {
        count = ok_n, ids = ids, cancelled = cancelled, at = periodic_beat_now(),
    })
    return ok_n
end







