PERIODIC_GEN_FILE = game.dataDir() .. "/periodic_gen.json"

function periodic_gen_read()
    local ok, d = pcall(util.json_load, PERIODIC_GEN_FILE)
    if ok and type(d) == "table" then return d end
    return {}
end
function periodic_gen_save(d) pcall(util.json_write, PERIODIC_GEN_FILE, d or {}) end

PERIODIC_TASKS_SPEC = {
    {1,  "tick_coordinate_and_soul"},   -- 灵魂倒计时 / 坐标传送 / 签到（必须 1 秒）
    {5,  "flush_log_buffer"},
    {15, "tick_chat_mute"},
    {8,  "tick_territories"},
    {15, "tick_death_fallback"},
    {6,  "ds_death_sample_tick"},
    {10, "expire_system_state"},
    {VOTE_CHECK_INTERVAL,   "on_vote_tick"},
    {ANNOUNCEMENT_INTERVAL, "on_announcement_tick"},
}

function register_periodic_tasks()
    local now = periodic_beat_now()
    local gd = periodic_gen_read()
    if gd.at and (now - (tonumber(gd.at) or 0)) < 3 then
        return tonumber(gd.count) or 0    -- 3 秒内重复调用：忽略，不重复注册
    end
    local cancelled = 0
    pcall(function() cancelled = periodic_cancel_old() end)
    local ids, ok_n = {}, 0
    for _, item in ipairs(PERIODIC_TASKS_SPEC) do
        local ok, h = pcall(util.schedule, item[1], item[2])
        if ok then
            ok_n = ok_n + 1
            if type(h) == "number" and h > 0 then ids[#ids + 1] = h end
        end
    end
    local gen = (tonumber(gd.gen) or 0) + 1
    periodic_gen_save({ gen = gen, at = now, count = ok_n, ids = ids, cancelled = cancelled })
    pcall(util.json_write, PERIODIC_ID_FILE, {
        count = ok_n, ids = ids, cancelled = cancelled, gen = gen, at = now,
    })
    return ok_n
end

function cmd_perf_diag(playerName)
    local lines = { "§b━━ 插件性能自检 ━━" }
    lines[#lines + 1] = string.format("§f心跳年龄：§e%.0f §7秒（< %d 秒 = 定时器在跑）",
        periodic_beat_age(), PERIODIC_BEAT_FRESH)
    local ok, d = pcall(util.json_load, PERIODIC_ID_FILE)
    local n, cancelled, gen = 0, 0, 0
    if ok and type(d) == "table" then
        n = tonumber(d.count) or 0
        cancelled = tonumber(d.cancelled) or 0
        gen = tonumber(d.gen) or 0
    end
    lines[#lines + 1] = "§f本代定时器：§e" .. n .. " §7个（第 §e" .. gen
        .. " §7代；登记时取消上一代 §e" .. cancelled .. " §7个）"
    local ok2, gd = pcall(util.json_load, PERIODIC_GEN_FILE)
    if ok2 and type(gd) == "table" then
        local g = tonumber(gd.gen) or 0
        lines[#lines + 1] = "§7· 累计加载代数：§e" .. g
            .. (g > 1 and " §8（重载过；已靠 3 秒时间窗去重，不会翻倍注册）" or " §8（首次加载）")
    end
    for _, item in ipairs(PERIODIC_TASKS_SPEC or {}) do
        lines[#lines + 1] = string.format("§7· §f%s §7每 §e%s§7 秒",
            tostring(item[2]), tostring(item[1]))
    end
    lines[#lines + 1] = "§fAI 思考：§e" .. (ai_thinking_enabled() and "开启" or "关闭")
    lines[#lines + 1] = "§8@s 现在会被替换成 @a[name=\"提问者\"]（合法选择器）。"
    send(playerName, table.concat(lines, "\n"))
    return true
end



function v16b_noop() end   -- 探测用空任务

function is_fresh_plugin_load()
    local ok, h = pcall(util.schedule, 86400, "v16b_noop")
    if ok and type(h) == "number" and h > 0 then
        pcall(util.cancel, h)     -- 立即取消探测定时器，不留下垃圾
        return true
    end
    return false
end

