    local ok, cnt = pcall(register_periodic_tasks)
    if ok then
        pcall(log_event, "PERIODIC", "v16b 顶层收口：登记 " .. tostring(cnt) .. " 个定时器")
    end
end

V17_EVENT_TICK_FILE = game.dataDir() .. "/v17_event_tick.json"

function v17_event_tick()
    local now = periodic_beat_now()
    local ok, d = pcall(util.json_load, V17_EVENT_TICK_FILE)
    if ok and type(d) == "table" and (now - (tonumber(d.at) or 0)) < 1 then
        return false   -- 本秒已跑过
    end
    pcall(util.json_write, V17_EVENT_TICK_FILE, { at = now, n = ((ok and type(d) == "table") and tonumber(d.n) or 0) + 1 })
    pcall(tick_coordinate_and_soul)
    if now % 6 == 0 then pcall(ds_death_sample_tick) end
    if now % 8 == 0 then pcall(tick_territories) end
    if now % 15 == 0 then pcall(tick_chat_mute) end
    if now % 15 == 0 then pcall(tick_death_fallback) end
    if now % 10 == 0 then pcall(expire_system_state) end
    if now % 5 == 0 then pcall(flush_log_buffer) end
    if VOTE_CHECK_INTERVAL > 0 and now % VOTE_CHECK_INTERVAL == 0 then pcall(on_vote_tick) end
    if ANNOUNCEMENT_INTERVAL > 0 and now % ANNOUNCEMENT_INTERVAL == 0 then pcall(on_announcement_tick) end
    return true
end

