function translated_item_name(item)
    local id, dmg
    if type(item) == "table" then
        id = item.Name or item.name or item.id
        dmg = item.Damage or item.damage or item.data or item.aux
    else
        id = item
        dmg = 0
    end
    id = tostring(id or "")
    if id == "" then return "未知物品" end
    local ok, nm = pcall(item_display_name, id, dmg)
    if ok and nm and trim(tostring(nm)) ~= "" then return tostring(nm) end
    return lower(id:gsub("^minecraft:", "")):gsub("_", " ")
end


function inv_target_kind(target, playerName)
    local t = lower(trim(tostring(target or "")))
    if t == "" or t == "self" or t == "me" or t == "自己" or t == "我" then
        return "self", tostring(playerName or "")
    end
    if t == "所有人" or t == "全部" or t == "all" or t == "@a" or t == "大家"
        or t == "所有人玩家" or t == "全部玩家" then
        return "all", ""
    end
    return "one", trim(tostring(target or ""))
end

function inv_request_any(playerName, target, tag, to_all)
    local kind, who = inv_target_kind(target, playerName)
    if kind == "all" then
        local names = online_players() or {}
        if #names == 0 then
            send(playerName, "§c当前没有在线玩家。")
            return
        end
        pcall(util.json_write, INV_REQ_FILE, {
            player = tostring(playerName), target = names[1], tag = tostring(tag or "chat"),
            to_all = (to_all == true), selector = inv_selector_of(names[1]),
            queue = names, queue_index = 1, at = util.timestamp(),
        })
        pcall(game.sendCommand, "codebuilder_actorinfo inventory " .. inv_selector_of(names[1]))
        pcall(util.setTimeout, 3, "inv_retry")
        return
    end
    local target_name = who
    if kind == "self" then target_name = tostring(playerName or "") end
    if target_name == "" then
        send(playerName, "§c没有指定玩家。")
        return
    end
    inv_request(playerName, target_name, tag, to_all)
end

local _v20_prev_on_command_output = on_command_output
function on_command_output(data)
    if type(data) ~= "table" then
        return _v20_prev_on_command_output(data)
    end
    local raw = data.data_set
    if type(raw) == "string" and raw ~= "" and string.find(raw, "inventory", 1, true) then
        _v20_prev_on_command_output(data)
        local ok, req = pcall(util.json_load, INV_REQ_FILE)
        if ok and type(req) == "table" and type(req.queue) == "table" then
            local idx = tonumber(req.queue_index) or 1
            local nxt = req.queue[idx + 1]
            if nxt then
                req.queue_index = idx + 1
                req.target = nxt
                req.selector = inv_selector_of(nxt)
                req.at = util.timestamp()
                pcall(util.json_write, INV_REQ_FILE, req)
                pcall(game.sendCommand, "codebuilder_actorinfo inventory " .. req.selector)
                pcall(util.setTimeout, 3, "inv_retry")
            end
        end
        return
    end
    return _v20_prev_on_command_output(data)
end


