function rebuild_item_names()
    local names = {}
    local ok0, cur = pcall(util.json_load, ITEM_NAMES_FILE)
    if ok0 and type(cur) == "table" then
        for k, v in pairs(cur) do
            if type(v) == "string" and v ~= "" then names[tostring(k)] = v end
        end
    end
    local prices = sell_price_data()
    for id, v in pairs(prices or {}) do
        if type(v) == "table" and type(v.name) == "string" and v.name ~= "" then
            if names[tostring(id)] == nil then names[tostring(id)] = v.name end
        end
    end
    for id, v in pairs(BUILTIN_SELL_FALLBACK or {}) do
        if type(v) == "table" and type(v.name) == "string" and v.name ~= "" then
            if names[tostring(id)] == nil then names[tostring(id)] = v.name end
        end
    end
    for id, v in pairs(ITEM_NAMES_EXTRA or {}) do
        if names[tostring(id)] == nil then names[tostring(id)] = v end
    end
    pcall(util.json_write, ITEM_NAMES_FILE, names)
    ITEM_NAME_CACHE = nil
    local n = 0; for _ in pairs(names) do n = n + 1 end
    return n
end

function ensure_item_names()
    local ok, cur = pcall(util.json_load, ITEM_NAMES_FILE)
    local n = 0
    if ok and type(cur) == "table" then for _ in pairs(cur) do n = n + 1 end end
    if n < 100 then
        local cnt = rebuild_item_names()
        pcall(log_event, "ITEM_NAMES", "物品名表重建：" .. tostring(cnt) .. " 项")
        return cnt
    end
    return n
end

local _v21_prev_on_chat = on_chat
function on_chat(playerName, msg)
    local low = lower(trim(tostring(msg or "")))
    if low == ".重建物品名" or low == ".修复翻译" then
        local cnt = rebuild_item_names()
        pcall(send, playerName, "§a✓ 物品名表已重建：§e" .. tostring(cnt) .. " §a项。\n§7现在背包/市场/收购都会显示中文名。")
        return
    end
    return _v21_prev_on_chat(playerName, msg)
end


if is_fresh_plugin_load() then
    pcall(ensure_item_names)
end


ADMIN_LIST_FILE = game.dataDir() .. "/admins.json"

function admin_list_load()
    local ok, d = pcall(util.json_load, ADMIN_LIST_FILE)
    if ok and type(d) == "table" then return d end
    return {}
end
function admin_list_save(d) pcall(util.json_write, ADMIN_LIST_FILE, d or {}) end

function admin_list_has(name)
    local nm = lower(trim(tostring(name or "")))
    if nm == "" then return false end
    local d = admin_list_load()
    for k, v in pairs(d) do
        if lower(trim(tostring(k))) == nm and v ~= false then return true end
    end
    return false
end

function admin_list_add(name, by)
    local nm = trim(tostring(name or ""))
    if nm == "" then return false, "玩家名不能为空" end
    local d = admin_list_load()
    d[nm] = { added_by = tostring(by or ""), added_at = util.timestamp() }
    admin_list_save(d)
    return true, nm
end
function admin_list_del(name)
    local nm = lower(trim(tostring(name or "")))
    local d = admin_list_load()
    local hit = nil
    for k in pairs(d) do
        if lower(trim(tostring(k))) == nm then hit = k; break end
    end
    if hit then d[hit] = nil; admin_list_save(d); return true, hit end
    return false, nil
end
function admin_list_text()
    local d = admin_list_load()
    local out = {}
    for k in pairs(d) do out[#out + 1] = tostring(k) end
    table.sort(out)
    return out
end

is_admin = function(name)
    local nm = trim(tostring(name or ""))
    if nm == "" then return false end

    if nm == SUPERUSER then return true end

    if admin_list_has(nm) then return true end

    local ok_rec, rec = pcall(function()
        local d = load_data()
        local key = identity(nm)
        return d.players and d.players[key] or nil
    end)
    if ok_rec and type(rec) == "table" and rec.is_admin == true then return true end

    local ok, r = pcall(player.isOP, nm)
    if ok and r == true then return true end

    local ok5, hit5 = pcall(check_tag, nm, "op")
    if ok5 and hit5 == true then return true end

    return false
end


function cmd_admin_list(playerName)
    local list = admin_list_text()
    local lines = { "§b━━ 管理员名单 ━━" }
    lines[#lines + 1] = "§f最高权限（硬编码）：§e" .. tostring(SUPERUSER)
    if #list == 0 then
        lines[#lines + 1] = "§7名单为空（可把玩家设为 op，或用 .添加管理 <玩家名>）"
    else
        for i, nm in ipairs(list) do
            lines[#lines + 1] = "§f" .. i .. ". §e" .. nm
        end
    end
    lines[#lines + 1] = "§7增：§f.添加管理 <玩家名> §7删：§f.移除管理 <玩家名>"
    lines[#lines + 1] = "§8名单存在数据目录 admins.json，插件重载不丢。"
    send(playerName, table.concat(lines, "\n"))
    return true
end

local _v22_prev_on_chat = on_chat
function on_chat(playerName, msg)
    local raw = trim(tostring(msg or ""))
    local low = lower(raw)

    if low == ".管理名单" or low == ".管理员名单" then
        return cmd_admin_list(playerName)
    end

    local add = raw:match("^%.添加管理%s+(.+)$") or raw:match("^%.加管理%s+(.+)$")
    if add then
        if not is_admin(playerName) then
            pcall(send, playerName, "§c只有管理权限可以添加管理员。")
            return
        end
        local ok, nm = admin_list_add(trim(add), playerName)
        if ok then
            pcall(send, playerName, "§a✓ 已把 §e" .. nm .. " §a加入管理员名单。\n§7他现在立即拥有管理权限（插件重载也不丢）。")
            pcall(send, nm, "§a✦ 你已被 " .. playerName .. " 设为管理员。")
        else
            pcall(send, playerName, "§c" .. tostring(nm))
        end
        return
    end

    local del = raw:match("^%.移除管理%s+(.+)$") or raw:match("^%.删管理%s+(.+)$")
    if del then
        if not is_admin(playerName) then
            pcall(send, playerName, "§c只有管理权限可以移除管理员。")
            return
        end
        local ok, nm = admin_list_del(trim(del))
        if ok then
            pcall(send, playerName, "§e✓ 已把 §f" .. nm .. " §e移出管理员名单。")
        else
            pcall(send, playerName, "§c名单里没有这个玩家。")
        end
        return
    end

    return _v22_prev_on_chat(playerName, msg)
end


function cmd_perm_diag(playerName)
    local lines = { "§b━━ 权限判定自检 ━━" }
    local target = tostring(playerName)
    lines[#lines + 1] = "§f当前玩家：§e" .. target
    lines[#lines + 1] = "§f最终 is_admin：§e" .. tostring(is_admin(target) == true)
    lines[#lines + 1] = "§8──────────"
    lines[#lines + 1] = "§f① 硬编码最高权限：§e" .. tostring(target == SUPERUSER)
    lines[#lines + 1] = "§f② 管理员名单：§e" .. tostring(admin_list_has(target))
    local ok_rec, rec = pcall(function()
        local d = load_data(); return d.players and d.players[identity(target)] or nil
    end)
    lines[#lines + 1] = "§f③ 玩家记录标记：§e"
        .. tostring(ok_rec and type(rec) == "table" and rec.is_admin == true)
    local ok4, r4 = pcall(player.isOP, target)
    lines[#lines + 1] = "§f④ 框架 isOP：§e" .. tostring(r4)
    local ok5, r5 = pcall(check_tag, target, "op")
    lines[#lines + 1] = "§f⑤ op 标签：§e" .. tostring(r5)
    lines[#lines + 1] = "§8──────────"
    lines[#lines + 1] = "§7名单人数：§e" .. tostring(#admin_list_text())
    lines[#lines + 1] = "§7增：§f.添加管理 <玩家名>"
    send(playerName, table.concat(lines, "\n"))
    return true
end

