local _v23_prev_show_permission_menu = show_permission_menu
show_permission_menu = function(name, mode)
    if name ~= SUPERUSER and not is_admin(name) then
        send(name, "§c只有最高权限账号可以使用权限管理。")
        return true
    end
    local names = online_players() or {}
    local filtered = {}
    for _, n in ipairs(names) do
        if mode == "grant" then
            if n ~= name and not is_admin(n) then table.insert(filtered, n) end
        else
            if is_admin(n) then table.insert(filtered, n) end
        end
    end
    if mode ~= "grant" then
        local seen = {}
        for _, n in ipairs(filtered) do seen[lower(n)] = true end
        for _, n in ipairs(admin_list_text()) do
            if not seen[lower(n)] and lower(n) ~= lower(name) then
                table.insert(filtered, n)
                seen[lower(n)] = true
            end
        end
    end
    local d, r = player_record(name, true)
    set_menu(d, r, mode == "grant" and "grant_target" or "revoke_target", { target_list = filtered })
    send(name, player_panel(
        mode == "grant" and "§a━━ 添加管理权限 ━━" or "§e━━ 撤回管理权限 ━━",
        filtered,
        "§7请输入编号选择玩家。\n§8（权限写入插件名单，不依赖服务器 OP）"))
    return true
end

local _v23_prev_on_chat = on_chat
function on_chat(playerName, msg)
    local d, r = player_record(playerName, true)
    local mode = r.menu
    if mode ~= "grant_target" and mode ~= "revoke_target" then
        return _v23_prev_on_chat(playerName, msg)
    end
    local index = tonumber(trim(tostring(msg or "")))
    local target = index and r.target_list and r.target_list[index]
    if not target then
        pcall(send, playerName, "§c编号无效，请重新输入。")
        return true
    end
    clear_menu(d, r)
    local safe = string.gsub(tostring(target), '"', '\\"')

    if mode == "grant_target" then
        admin_list_add(target, playerName)
        local td, tr = player_record(target, true)
        if type(tr) == "table" then tr.is_admin = true; save_data(td) end
        pcall(game.sendCommand, 'op "' .. safe .. '"')
        send(playerName, "§a✓ 已添加 " .. target .. " 的管理权限。\n§7已写入插件名单，立即生效。")
        send(target, "§a✦ 你已获得管理权限。")
    else
        admin_list_del(target)
        local td, tr = player_record(target, true)
        if type(tr) == "table" then tr.is_admin = nil; save_data(td) end
        pcall(game.sendCommand, 'deop "' .. safe .. '"')
        send(playerName, "§e✓ 已撤回 " .. target .. " 的管理权限。")
        send(target, "§e你的管理权限已被撤回。")
    end
    return true
end



function cmd_op_selfcheck(playerName)
    local bot = ai_bot_identity()
    if bot == "" then bot = "（读不到机器人名）" end
    local lines = { "§b━━ 机器人执行权限自检 ━━" }
    lines[#lines + 1] = "§f机器人账号：§e" .. tostring(bot)

    local tests = {
        { "give",   'give @a[name="' .. bot .. '"] stone 1' },
        { "fill",   "fill ~ ~ ~ ~1 ~1 ~1 stone" },
        { "summon", "summon tnt ~ ~3 ~" },
        { "gamerule", "gamerule keepInventory true" },
        { "time",   "time query daytime" },
        { "tag",    'tag @a[name="' .. bot .. '"] add ds_op_test' },
    }
    local ok_cnt, bad_cnt = 0, 0
    for _, t in ipairs(tests) do
        local ok, res = pcall(game.sendCommandWithResp, t[2], "ai", 5)
        local success = (ok and type(res) == "table" and res.success == true)
        local msg = ""
        if ok and type(res) == "table" and type(res.messages) == "table" and #res.messages > 0 then
            msg = tostring(res.messages[1].message or "")
        end
        if success then ok_cnt = ok_cnt + 1 else bad_cnt = bad_cnt + 1 end
        lines[#lines + 1] = string.format("§7· %-9s %s %s",
            t[1], success and "§a✔ 可用" or "§c✘ 无权限",
            (msg ~= "" and ("§8" .. msg) or ""))
    end
    lines[#lines + 1] = "§8──────────"
    if bad_cnt == 0 then
        lines[#lines + 1] = "§a机器人 OP 正常，全部指令可用。"
    else
        lines[#lines + 1] = "§c有 " .. tostring(bad_cnt) .. " 项失败 → §f机器人账号缺少 OP。"
        lines[#lines + 1] = "§e请在【网易租赁服后台/管理端】给账号 §f" .. tostring(bot) .. " §e开 OP。"
        lines[#lines + 1] = "§7插件无法自行恢复服务器 OP（op 命令本身也会失败）。"
    end
    pcall(game.sendCommand, 'tag @a[name="' .. bot .. '"] remove ds_op_test')
    send(playerName, table.concat(lines, "\n"))
    return true
end

