function known_player_names()
    local out, seen = {}, {}
    local function add(nm)
        nm = trim(tostring(nm or ""))
        if nm ~= "" and not seen[nm] then seen[nm] = true; out[#out + 1] = nm end
    end
    local ok, list = pcall(player.list)
    if ok and type(list) == "table" then
        for _, p in ipairs(list) do
            if type(p) == "table" then add(p.name) end
        end
    end
    local ok2, sd = pcall(ds_samples_load)
    if ok2 and type(sd) == "table" then
        for nm in pairs(sd.samples or {}) do add(nm) end
    end
    local ok3, d = pcall(load_data)
    if ok3 and type(d) == "table" and type(d.players) == "table" then
        for _, r in pairs(d.players) do
            if type(r) == "table" then add(r.name) end
        end
    end
    return out
end

function ds_online_names()
    local names, seen = {}, {}
    local function add(nm)
        nm = trim(tostring(nm or ""))
        if nm ~= "" and not seen[nm] then seen[nm] = true; names[#names + 1] = nm end
    end
    local ok, list = pcall(player.list)
    if ok and type(list) == "table" then
        for _, p in ipairs(list) do
            if type(p) == "table" then add(p.name) end
        end
    end
    local ok2, arr = pcall(game.getTarget, "@a")
    if ok2 and type(arr) == "table" then
        for _, nm in ipairs(arr) do add(nm) end
    end
    return names
end

DS_SAMPLE_FRESH_SEC = 15
DS_SAMPLE_MAX_PER_TICK = 2    -- ★ v30：每轮最多采样 2 人（原 12）。轮转覆盖，降低命令回包频率。
function inv_parse_targets(target, playerName)
    local t = trim(tostring(target or ""))
    local lt = lower(t)
    if t == "" or lt == "self" or lt == "me" or t == "自己" or t == "我" then
        return { tostring(playerName or "") }
    end
    if lt == "all" or lt == "@a" or t == "所有人" or t == "全部" or t == "大家"
        or t == "全部玩家" or t == "所有人玩家" then
        return online_players() or {}
    end
    t = t:gsub("，", ","):gsub("、", ","):gsub("；", ","):gsub(";", ",")
    local out, seen = {}, {}
    for nm in t:gmatch("[^,%s]+") do
        nm = trim(nm)
        if nm ~= "" and not seen[nm] then seen[nm] = true; out[#out + 1] = nm end
    end
    if #out == 0 then out = { tostring(playerName or "") } end
    return out
end

DS_SAMPLE_FRESH_SEC = 15

function ds_death_pos_for(name, now)
    now = now or util.timestamp()
    local frame = death_frame_pos_get(name, now)
    if type(frame) == "table" and ds_pos_valid(frame.x, frame.y, frame.z) then
        return frame, false
    end
    local sd = ds_samples_load()
    local sm = sd.samples and sd.samples[name]
    if type(sm) == "table" and ds_pos_valid(sm.x, sm.y, sm.z) then
        local age = math.max(0, now - (tonumber(sm.ts) or 0))
        if age <= DS_SAMPLE_FRESH_SEC then
            return { x = tonumber(sm.x), y = tonumber(sm.y), z = tonumber(sm.z),
                     dimension = sm.dimension or "overworld",
                     at = tonumber(sm.ts) or 0, src = "sample" }, age > 8
        end
    end
    local pkt = pos_cache_get(name, "pkt")
    if type(pkt) == "table" and ds_pos_valid(pkt.x, pkt.y, pkt.z) then
        local age = math.max(0, now - (tonumber(pkt.at) or 0))
        if age <= 30 then return pkt, age > 6 end
    end
    local tk = load_death_track()
    local info = get_info(name)
    local xuid = (info and info.xuid and tostring(info.xuid) ~= "") and tostring(info.xuid) or name
    for _, k in ipairs({ xuid, name }) do
        local fw = type(tk.pos_fw) == "table" and tk.pos_fw[k] or nil
        if type(fw) == "table" and ds_pos_valid(fw.x, fw.y, fw.z) then
            return fw, true
        end
    end
    return nil, false
end

V25_TIMERS_FILE = game.dataDir() .. "/v25_timers.json"

function v25_tick_all(now)
    now = now or periodic_beat_now()
    local ok, t = pcall(util.json_load, V25_TIMERS_FILE)
    if not ok or type(t) ~= "table" then t = {} end
    local dirty = false
    local function due(key, interval)
        if now - (tonumber(t[key]) or 0) >= interval then
            t[key] = now; dirty = true; return true
        end
        return false
    end
    if due("soul", 1) then pcall(tick_coordinate_and_soul) end
    if due("sample", 3) then pcall(ds_death_sample_tick) end   -- ★ R10：死亡采样固定 3 秒
    if due("fallback", 3) then pcall(tick_death_fallback) end
    if due("territory", 8) then pcall(tick_territories) end
    if due("expire", 10) then pcall(expire_system_state) end
    if due("mute", 15) then pcall(tick_chat_mute) end
    if due("log", 5) then pcall(flush_log_buffer) end
    if due("vote", VOTE_CHECK_INTERVAL) then pcall(on_vote_tick) end
    if due("ann", ANNOUNCEMENT_INTERVAL) then pcall(on_announcement_tick) end
    if dirty then pcall(util.json_write, V25_TIMERS_FILE, t) end
end

function v17_event_tick()
    local now = periodic_beat_now()
    local ok, d = pcall(util.json_load, V17_EVENT_TICK_FILE)
    if ok and type(d) == "table" and (now - (tonumber(d.at) or 0)) < 1 then
        return false
    end
    pcall(util.json_write, V17_EVENT_TICK_FILE, { at = now })
    pcall(v25_tick_all, now)
    return true
end

INV_QUEUE_FILE = game.dataDir() .. "/inv_queue.json"
INV_STEP_TIMEOUT = 5

function inv_queue_load()
    local ok, d = pcall(util.json_load, INV_QUEUE_FILE)
    if ok and type(d) == "table" then return d end
    return { active = false }
end
function inv_queue_save(d) pcall(util.json_write, INV_QUEUE_FILE, d or { active = false }) end


function inv_fire_current()
    local q = inv_queue_load()
    if not q.active then return end
    local nm = q.queue and q.queue[tonumber(q.index) or 1]
    if not nm then
        q.active = false; inv_queue_save(q); return
    end
    q.at = util.timestamp()
    inv_queue_save(q)
    pcall(game.sendCommand, "codebuilder_actorinfo inventory " .. inv_selector_of(nm))
    pcall(util.setTimeout, INV_STEP_TIMEOUT, "inv_step_timeout")
end
function inv_fire_delayed() pcall(inv_fire_current) end

function inv_step_timeout()
    local q = inv_queue_load()
    if not q.active then return end
    if util.timestamp() - (tonumber(q.at) or 0) < INV_STEP_TIMEOUT - 1 then return end
    q.index = (tonumber(q.index) or 1) + 1
    if not q.queue or q.index > #q.queue then
        q.active = false; inv_queue_save(q)
        pcall(send, q.player, "§7背包查询结束。")
        return
    end
    inv_queue_save(q)
    inv_fire_current()
end

function inv_next_player()
    local q = inv_queue_load()
    if not q.active then return end
    q.index = (tonumber(q.index) or 1) + 1
    if not q.queue or q.index > #q.queue then
        q.active = false; inv_queue_save(q); return
    end
    inv_queue_save(q)
    pcall(util.setTimeout, 1, "inv_fire_delayed")
end

function inv_request(playerName, target, tag, to_all)
    local targets = inv_parse_targets(target, playerName)
    local cleaned = {}
    for _, nm in ipairs(targets or {}) do
        nm = trim(tostring(nm or ""))
        if nm ~= "" then cleaned[#cleaned + 1] = nm end
    end
    if #cleaned == 0 then
        pcall(send, playerName, "§c没有可查询的玩家。")
        return
    end
    pcall(util.write_file, INV_REQ_FILE, "{}")   -- 清掉旧通道，避免两套逻辑打架
    inv_queue_save({
        active = true, player = tostring(playerName), tag = tostring(tag or "chat"),
        to_all = (to_all == true), queue = cleaned, index = 1, at = util.timestamp(),
    })
    inv_fire_current()
end

function inv_packet_raw(data)
    if type(data) ~= "table" then return nil end
    local raw = data.data_set
    if type(raw) ~= "string" then
        local f = data.fields
        if type(f) == "table" then raw = f.data_set end
    end
    if type(raw) ~= "string" then return nil end
    if not string.find(raw, "inventory", 1, true) then return nil end
    return raw
end
function inv_reply(target, text)
    local nm = tostring(target or "")
    if nm == "" then return end
    local payload = json_rawtext(text)
    if payload then
        local safe = string.gsub(nm, '"', '\\"')
        local ok = pcall(game.sendCommand, 'tellraw @a[name="' .. safe .. '"] ' .. payload)
        if ok then return end
    end
    pcall(game.sendTargeted, nm, text)
end

local _v25_prev_on_command_output = on_command_output
function on_command_output(data)
    local raw = inv_packet_raw(data)
    if raw then
        local q = inv_queue_load()
        if q.active then
            local items = inv_parse_slots(raw)
            if items then
                local nm = q.queue and q.queue[tonumber(q.index) or 1]
                local lines = { "§b━━ " .. tostring(nm) .. " 的背包 ━━" }
                if #items == 0 then
                    lines[#lines + 1] = "§7背包为空。"
                else
                    lines[#lines + 1] = "§7共 §e" .. #items .. " §7种物品"
                    for _, l in ipairs(inv_format_items(items, 3, 10)) do lines[#lines + 1] = l end
                end
                local text = table.concat(lines, "\n")
                if q.to_all == true then
                    pcall(broadcast, text)
                else
                    inv_reply(q.player, text)
                end
                pcall(log_event, "INVENTORY", tostring(q.player) .. " read " .. tostring(nm)
                    .. " items=" .. tostring(#items))
                inv_next_player()
            end
        end
    end
    if type(_v25_prev_on_command_output) == "function" then
        return _v25_prev_on_command_output(data)
    end
end

