    local payload = json_rawtext(t)
    if payload then
        local safe = string.gsub(nm, '"', '\\"')
        local ok2 = pcall(game.sendCommand, 'tellraw "' .. safe .. '" ' .. payload)
        if ok2 then return true end
    end
    pcall(game.sendTargeted, nm, t)
    return false
end

