function show_tpa_targets(name)
    local names = online_players() or {}
    local filtered = {}
    for _, target in ipairs(names) do if target ~= name then table.insert(filtered, target) end end
    local d, r = player_record(name, true)
    set_menu(d, r, "tpa_target", { target_list = filtered })
    local lines = {
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
        "§1◆ §r§b§l玩家互传 §8┃ §7选择目标",
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
    }
    if #filtered == 0 then
        lines[#lines + 1] = "§7当前没有其他在线玩家。"
    else
        for i, nm in ipairs(filtered) do
            lines[#lines + 1] = string.format("§b§l%02d §r§8┃ §f%s", i, tostring(nm))
        end
    end
    lines[#lines + 1] = "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
    lines[#lines + 1] = "§7➜ 输入 §b§l编号§r §7发送传送申请（对方 §b§l1§r §7同意 / §b§l0§r §7拒绝）"
    lines[#lines + 1] = "§7➜ 申请有效期 §e§l30§r §7秒 · §f§l.stop§r §7退出"
    send(name, table.concat(lines, "\n"))
end

