        "§f§l.积分 玩家§r §7查询积分",
        "§f§l.添加管理 玩家名§r §7添加管理员",
        "§f§l.移除管理 玩家名§r §7移除管理员",
        "§f§l.管理名单§r §7查看管理员名单",
        "§f§l.权限判定§r §7权限来源自检",
        "§f§l.op自检§r §7机器人执行权限实测",
        "§f§l.禁言 玩家 时长§r §7禁言（管理）",
        "§f§l.解除封禁§r §7打开解封菜单（管理）",
        "§f§l.翻译自检§r §7物品名翻译自检",
        "§f§l.重建物品名§r §7重建物品中文名表",
        "§f§l.性能§r §7查看定时器与心跳状态",
        "§f§l.停止建筑§r §7停止 AI 建筑任务",
        "§f§l.关闭建筑模式§r §7退出建筑模式",
        "§f§l+ / -§r §7翻页",
    }
    local total = #all
    local per_page = 10
    local max_page = math.max(1, math.ceil(total / per_page))
    page = math.max(1, math.min(page or 1, max_page))
    local first = (page - 1) * per_page + 1
    local last = math.min(total, first + per_page - 1)
    local lines = {
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
        "§1◆ §r§b§l指令入口 §8┃ §7第 " .. page .. " / " .. max_page .. " 页",
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
    }
    for i = first, last do
        lines[#lines + 1] = string.format("§b§l%02d §r§8┃ §7%s", i - first + 1, all[i])
    end
    lines[#lines + 1] = "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
    lines[#lines + 1] = "§7➜ §b§l+§r §7下一页 · §b§l-§r §7上一页 · §f§l.stop§r §7退出"
    local d, r = player_record(name, true)
    set_menu(d, r, "trigger_words", { trigger_page = page })
    send(name, table.concat(lines, "\n"))
    return true
end

function death_show_list(name)
    local d, r = player_record(name, true)
    local hist = r.death_history or {}
    local cost = death_tp_cost()
    local bal = death_read_balance(name)
    local recent = {}
    local shown = 0
    for i = #hist, 1, -1 do
        shown = shown + 1
        if shown > 5 then break end
        local h = hist[i]
        local ts = tostring(h.saved_at or "")
        if #ts >= 16 then ts = ts:sub(1, 16) end
        recent[#recent + 1] = string.format("§b§l%d §r§8┃ §7第 §e§l%d §r§7次 §8▸ §f§l%d %d %d §r§8[§b%s§8] §7%s",
            shown, tonumber(h.n) or shown,
            math.floor(tonumber(h.x) or 0), math.floor(tonumber(h.y) or 0), math.floor(tonumber(h.z) or 0),
            dimension_display(h.dimension), ts)
    end
    local d2, r2 = player_record(name, true)
    set_menu(d2, r2, "death_dir")
    if shown == 0 then
        send(name, table.concat({
            "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
            "§1◆ §r§b§l死 亡 日 志 §8┃ §7最近 5 次",
            "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
            "§7暂无死亡记录。下一次死亡后会自动记录。",
            "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
            "§7➜ §f§l.死亡日志§r §7重新查看 · §f§l.stop§r §7退出",
        }, "\n"))
        return
    end
    local head = {
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
        "§1◆ §r§b§l死 亡 日 志 §8┃ §7最近 5 次",
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
    }
    for i = 1, math.min(3, #recent) do head[#head + 1] = recent[i] end
    send(name, table.concat(head, "\n"))

    local tail = {}
    for i = 4, #recent do tail[#tail + 1] = recent[i] end
    tail[#tail + 1] = "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
    tail[#tail + 1] = "§7➜ 输入 §b§l1~" .. tostring(shown) .. "§r §7传送到对应记录点"
    tail[#tail + 1] = "§7➜ §b§l1§r §7= 最近一次，数字越大越早"
    if cost > 0 then
        tail[#tail + 1] = "§6⚑ §7回点费用 §6§l" .. tostring(cost) .. "§r §7积分"
            .. (bal ~= nil and (" §8┃ §7余额 §b" .. tostring(bal)) or "")
    else
        tail[#tail + 1] = "§6⚑ §7当前回点 §a§l免费"
    end
    tail[#tail + 1] = "§7➜ §f§l.死亡点返回 [序号]§r §7可直接回点 · §f§l.stop§r §7退出"
    send(name, table.concat(tail, "\n"))
end

