function ensure_item_names_more()
    local names = {}
    local ok0, cur = pcall(util.json_load, ITEM_NAMES_FILE)
    if ok0 and type(cur) == "table" then
        for k, v in pairs(cur) do
            if type(v) == "string" and v ~= "" then names[tostring(k)] = v end
        end
    end
    local added = 0
    for id, v in pairs(ITEM_NAMES_EXTRA_MORE or {}) do
        if names[tostring(id)] == nil then names[tostring(id)] = v; added = added + 1 end
    end
    for id, v in pairs(ITEM_NAMES_EXTRA or {}) do
        if names[tostring(id)] == nil then names[tostring(id)] = v; added = added + 1 end
    end
    if added > 0 then
        pcall(util.json_write, ITEM_NAMES_FILE, names)
        ITEM_NAME_CACHE = nil
    end
    local n = 0; for _ in pairs(names) do n = n + 1 end
    return n, added
end

if is_fresh_plugin_load() then
    pcall(function()
        local n, added = ensure_item_names_more()
        pcall(log_event, "ITEM_NAMES", "v27 补全物品名：共 " .. tostring(n) .. " 项，本次新增 " .. tostring(added))
    end)
end

local _v27_prev_on_chat = on_chat
function on_chat(playerName, msg)
    local low = lower(trim(tostring(msg or "")))
    if low == ".物品名补全" or low == ".补全翻译" then
        local n, added = ensure_item_names_more()
        pcall(send, playerName, "§a✓ 物品名表：共 §e" .. tostring(n) .. " §a项，本次新增 §e"
            .. tostring(added) .. " §a项。\n§7现在背包 / 市场 / 收购都会显示中文名。")
        return
    end
    return _v27_prev_on_chat(playerName, msg)
end




function valid_seed(s)
    s = trim(tostring(s or ""))
    if s == "" then return false end
    if not s:match("^%-?%d+$") then return false end
    local digits = s:gsub("^%-", "")
    if #digits < 1 or #digits > 19 then return false end
    if tonumber(s) == nil then return false end
    return true
end

function valid_structure_name(name)
    name = trim(tostring(name or ""))
    if name == "" then return false end
    if #name > 64 then return false end
    if string.find(name, "[\r\n]", 1) then return false end
    return true
end

function structure_hash(name)
    local s = tostring(name or "")
    local h = 5381
    for i = 1, #s do
        h = (h * 33 + string.byte(s, i)) % 2147483647
    end
    return h
end

function native_structure_id(name)
    name = trim(tostring(name or ""))
    if name == "" then return nil end
    if name:match("^[%w_]+$") and #name <= 40 then return name end
    return "ds_" .. tostring(structure_hash(name))
end


function get_server_seed()
    local ok, d = pcall(util.json_load, SEED_FILE)
    if ok and type(d) == "table" and d.seed ~= nil and tostring(d.seed) ~= "" then
        return tostring(d.seed)
    end
    local cfg = trim(tostring(game.getConfig("server_seed", "") or ""))
    if cfg ~= "" then return cfg end
    return nil
end

function set_server_seed(name, seed)
    seed = trim(tostring(seed or ""))
    if not valid_seed(seed) then return false end
    pcall(util.json_write, SEED_FILE, {
        seed = seed, set_by = tostring(name or ""), set_at = util.timestamp(),
    })
    return true
end


function seed_engine_base()
    local u = trim(tostring(game.getConfig("seed_engine_url", "") or ""))
    if u == "" then u = SEED_FINDER_URL end
    if u:find("mineseedfinder", 1, true) then u = SEED_FINDER_URL end
    return (u:gsub("/+$", ""))
end

function seed_engine_cred()
    local acct = trim(tostring(game.getConfig("seed_engine_account", "") or ""))
    local pwd  = trim(tostring(game.getConfig("seed_engine_password", "") or ""))
    if acct == "" then
        local ok, d = pcall(util.json_load, SEED_CRED_FILE)
        if ok and type(d) == "table" then
            acct = trim(tostring(d.account or ""))
            pwd  = trim(tostring(d.password or ""))
        end
    end
    return acct, pwd
end

function set_seed_engine_cred(acct, pwd)
    pcall(util.json_write, SEED_CRED_FILE, {
        account = tostring(acct or ""), password = tostring(pwd or ""),
        set_at = util.timestamp(),
    })
    return true
end

function seed_engine_token()
    local t = trim(tostring(game.getConfig("seed_engine_token", "") or ""))
    if t ~= "" then return t end
    local ok, d = pcall(util.json_load, SEED_TOKEN_FILE)
    if ok and type(d) == "table" then
        local tk = trim(tostring(d.token or ""))
        local exp = tonumber(d.expires_at) or 0
        if tk ~= "" and (exp == 0 or util.timestamp() < exp) then return tk end
    end
    return nil
end

function seed_engine_login()
    local acct, pwd = seed_engine_cred()
    if acct == "" or pwd == "" then
        return nil, "未配置查询器账号（管理权限可用 .种子账号 <账号> <密码> 设置）"
    end
    local url = seed_engine_base() .. "/auth/login"
    local ok, r = pcall(http.post, url,
        http.json_encode({ account = acct, password = pwd }),
        { headers = { ["Content-Type"] = "application/json" }, timeout = SEED_FINDER_TIMEOUT })
    if not ok then return nil, "登录请求异常：" .. tostring(r) end
    if not r or not r.ok then
        return nil, "登录请求失败：" .. tostring(r and (r.error or r.status) or "无响应")
    end
    local code = tonumber(r.status) or 0
    if code < 200 or code >= 300 then
        return nil, "登录失败 HTTP " .. code .. "：" .. tostring(r.body or ""):sub(1, 160)
    end
    local ok2, data = pcall(http.json_decode, tostring(r.body or ""))
    if not ok2 or type(data) ~= "table" then return nil, "登录返回无法解析" end
    local tk = trim(tostring(data.token or data.access_token or ""))
    if tk == "" then return nil, "登录成功但没有返回令牌" end
    pcall(util.json_write, SEED_TOKEN_FILE, {
        token = tk, account = acct,
        expires_at = util.timestamp() + (tonumber(data.expires_in) or 86400),
        at = util.timestamp(),
    })
    return tk
end

function query_seed_structure_engine(seed, structure, radius, x, z)
    local tk = seed_engine_token()
    if not tk then
        local nt, err = seed_engine_login()
        if not nt then return nil, "查询器未登录：" .. tostring(err) end
        tk = nt
    end
    local base = seed_engine_base()
    local q = http.querify({
        seed = tostring(seed or ""),
        structure = tostring(structure or ""),
        radius = tostring(radius or SEED_FINDER_DEFAULT_RADIUS),
        x = tostring(x or 0),
        z = tostring(z or 0),
    })
    local ok, r = pcall(http.get, base .. "/tools/seed/scan?" .. q, {
        headers = { ["Authorization"] = "Bearer " .. tk },
        timeout = SEED_FINDER_TIMEOUT,
    })
    if not ok then return nil, "查询请求异常：" .. tostring(r) end
    if not r or not r.ok then
        return nil, "查询请求失败：" .. tostring(r and (r.error or r.status) or "无响应")
    end
    local code = tonumber(r.status) or 0
    if code < 200 or code >= 300 then
        return nil, "查询失败 HTTP " .. code .. "：" .. tostring(r.body or ""):sub(1, 160)
    end
    local ok2, data = pcall(http.json_decode, tostring(r.body or ""))
    if not ok2 or type(data) ~= "table" then return nil, "查询返回无法解析" end
    local list = data.results or data.data or {}
    if type(list) ~= "table" then return nil, "查询返回结构异常" end
    return list
end


function bedrock_locate_id(name)
    local k = trim(tostring(name or ""))
    if k == "" then return nil end
    local v = BEDROCK_LOCATE_IDS[k]
    if v then return v end
    v = BEDROCK_LOCATE_IDS[lower(k)]
    if v then return v end
    return nil
end

function locate_structure_ingame(playerName, name)
    local sid = bedrock_locate_id(name)
    if not sid then return nil, "__notfound__" end
    local ok, res = pcall(game.sendCommandWithResp, "locate structure " .. sid, "ai", LOCATE_TIMEOUT)
    if not ok or type(res) ~= "table" then return nil, "__raw__" end
    for _, m in ipairs(res.messages or {}) do
        if type(m) == "table" then
            local msg = tostring(m.message or "")
            if msg == "commands.locate.structure.success" then
                local p = m.parameters or {}
                local x = tonumber(p[2])
                local z = tonumber(p[3])
                if x and z then
                    return { id = sid, x = math.floor(x), z = math.floor(z),
                             dist = tonumber(p[4]) or 0 }, nil
                end
            elseif msg == "commands.locate.structure.notFound"
                or msg == "commands.locate.structure.not_found" then
                return nil, "__notfound__"
            end
        end
    end
    return nil, "__notfound__"
end

function query_seed_structure(playerName, name, radius)
    name = trim(tostring(name or ""))
    if name == "" then
        return "§c请提供结构名称，例如：§f.结构 村庄"
    end
    local radius_n = tonumber(radius)
    if not radius_n or radius_n <= 0 then radius_n = SEED_FINDER_DEFAULT_RADIUS end

    local hit, err = locate_structure_ingame(playerName, name)
    if hit then
        local label = LOCATE_CN[hit.id] or name
        local lines = {
            "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
            "§1◆ §r§b§l结构定位 §8┃ §7" .. label,
            "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
        }
        lines[#lines + 1] = string.format("§f坐标 §8▸ §a§l%d §7/ §a§l%d", hit.x, hit.z)
        lines[#lines + 1] = "§f维度 §8▸ §b主世界"
        local pos = player_record_last_pos(playerName)
        if pos then
            local dx, dz = hit.x - tonumber(pos.x or 0), hit.z - tonumber(pos.z or 0)
            local d = math.sqrt(dx * dx + dz * dz)
            lines[#lines + 1] = string.format("§f距离 §8▸ §e§l%d §r§7格 §8| §f方向 §8▸ §e%s",
                math.floor(d + 0.5), compass8(dx, dz))
        end
        lines[#lines + 1] = "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
        lines[#lines + 1] = "§7传送 §8▸ §f.tp 主世界 " .. hit.x .. " 100 " .. hit.z
        return table.concat(lines, "\n")
    end

    local sid = bedrock_locate_id(name)
    local dimonly = sid and BEDROCK_DIMENSION_ONLY[sid]
    if dimonly then
        return "§c「" .. name .. "」只生成在 §e" .. dimonly .. "§c，无法在主世界定位。"
    end
    if sid == nil then
        return "§c不认识的结构名：§f" .. name
            .. "\n§7可用：村庄 / 要塞 / 海底神殿 / 林地府邸 / 废弃传送门 / 掠夺者前哨站"
            .. "\n§7远古城市 / 沼泽小屋 / 沙漠神殿 / 丛林神庙 / 沉船 / 埋藏的宝藏 / 废弃矿井"
            .. "\n§7试炼密室 / 古迹废墟 / 下界要塞 / 堡垒遗迹 / 末地城"
    end

    local seed = get_server_seed()
    if not seed then
        return "§c主世界没找到「" .. name .. "」。\n§7本服尚未设置世界种子（管理权限可用 §f.种子 <种子号>§7 设置），无法用种子精确查询。"
    end
    local pos = player_record_last_pos(playerName)
    local list, qerr = query_seed_structure_engine(seed, sid, radius_n,
        pos and pos.x or 0, pos and pos.z or 0)
    if not list then
        return "§c主世界没找到「" .. name .. "」。\n§7种子查询也失败：" .. tostring(qerr)
    end
    if #list == 0 then
        return "§c在半径 " .. radius_n .. " 区块内没有找到「" .. name .. "」。"
    end
    local lines = {
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
        "§1◆ §r§b§l结构定位（种子查询）§8┃ §7" .. (LOCATE_CN[sid] or name),
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
    }
    local n = 0
    for _, it in ipairs(list) do
        if type(it) == "table" then
            n = n + 1
            if n > SEED_FINDER_MAX_RESULTS then break end
            lines[#lines + 1] = string.format("§b§l%d §r§8┃ §f%d §7/ §f%d §8| §7距离 §e%s",
                n, math.floor(tonumber(it.x) or 0), math.floor(tonumber(it.z) or 0),
                tostring(it.distance or "?"))
        end
    end
    lines[#lines + 1] = "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
    lines[#lines + 1] = "§7传送 §8▸ §f.tp 主世界 X 100 Z"
    return table.concat(lines, "\n")
end

function save_native_region(playerName, name, x1, y1, z1, x2, y2, z2)
    if not valid_structure_name(name) then
        return false, "名称不能为空、不能换行，最长 64 字符。"
    end
    local ax, ay, az, bx, by, bz = normalize_region(x1, y1, z1, x2, y2, z2)
    if not ax then return false, "坐标格式无效，请用：.导出 名称 X1 Y1 Z1 X2 Y2 Z2" end
    local width, height, depth = bx - ax + 1, by - ay + 1, bz - az + 1
    if width > 256 or depth > 256 then
        return false, "区域 X/Z 方向最大 256 格（当前 " .. width .. "×" .. depth .. "）。"
    end
    if height > 384 then
        return false, "区域 Y 方向最大 384 格（当前 " .. height .. "）。"
    end

    local ok, data = pcall(game.getRegionBlockData, ax, ay, az, width, height, depth)
    if not ok or type(data) ~= "table" then
        return false, "区域读取失败：" .. tostring(data)
    end
    local total, solid = 0, 0
    for _, v in pairs(data) do
        if type(v) == "table" then
            total = total + 1
            local bn = lower(tostring(v.name or v.id or ""))
            if bn ~= "" and not bn:find("air", 1, true) then solid = solid + 1 end
        end
    end
    if total <= 0 then
        return false, "区域读取成功，但没有返回任何方块数据（请确认坐标在已加载区块内）。"
    end
    if solid <= 0 then
        return false, "这块区域全是空气，没有可导出的方块。"
    end

    local db = nbt_region_db()
    db.regions = db.regions or {}
    db.regions[tostring(name)] = {
        name = name,
        origin = { x = ax, y = ay, z = az },
        size = { x = width, y = height, z = depth },
        blocks = data,
        solid = solid,
        saved_by = playerName,
        saved_at = util.timestamp(),
    }
    local sok, serr = nbt_region_save(db)
    if not sok then return false, "区域保存失败：" .. tostring(serr) end

    local vok, verify = pcall(util.json_load, NBT_REGION_FILE)
    if not vok or type(verify) ~= "table" or type(verify.regions) ~= "table"
        or type(verify.regions[tostring(name)]) ~= "table" then
        return false, "区域写入后回读失败，请重试。"
    end

    log_event("NBT_REGION", tostring(playerName) .. " export region " .. tostring(name)
        .. " solid=" .. tostring(solid) .. " size=" .. width .. "x" .. height .. "x" .. depth)

    return true, table.concat({
        "§a✓ 区域已导出：§e" .. tostring(name),
        "§7范围 §8▸ §f" .. ax .. " " .. ay .. " " .. az .. " §7→ §f" .. bx .. " " .. by .. " " .. bz,
        "§7尺寸 §8▸ §f" .. width .. " × " .. height .. " × " .. depth,
        "§7方块 §8▸ §a" .. solid .. " §7个（含空气 " .. total .. " 格）",
        "§8导入 §▸ §f.导入 " .. tostring(name) .. " X Y Z",
        "§8兑换码 §▸ §f.生成兑换码 导入 " .. tostring(name) .. " 7天",
    }, "\n")
end



V29_BOOT_FILE = game.dataDir() .. "/v29_boot.json"
V29_INIT_FILE = game.dataDir() .. "/v29_init.json"

function v29_read_json(path)
    local ok, d = pcall(util.json_load, path)
    if ok and type(d) == "table" then return d end
    return {}
end

_V29_FRESH = nil
function v29_is_fresh_load()
    if _V29_FRESH ~= nil then return _V29_FRESH end
    _V29_FRESH = (is_fresh_plugin_load() == true)
    return _V29_FRESH
end

if v29_is_fresh_load() then
    pcall(util.json_write, V29_BOOT_FILE, {
        token = tostring(periodic_beat_now()) .. "_" .. tostring(math.random(100000, 999999)),
        at = periodic_beat_now(),
    })
end

function v29_boot_token()
    return tostring(v29_read_json(V29_BOOT_FILE).token or "")
end
function v29_init_done_token()
    return tostring(v29_read_json(V29_INIT_FILE).token or "")
end
function v29_init_mark(tk)
    pcall(util.json_write, V29_INIT_FILE, { token = tostring(tk or ""), at = periodic_beat_now() })
end

PERIODIC_TASKS_SPEC = {
    {1, "v17_event_tick"},
}

function register_periodic_tasks()
    if not v29_is_fresh_load() then
        return 0    -- ★ 重跑上下文（botReady / on_chat / 定时器回调）：绝不注册
    end
    local now = periodic_beat_now()
    local cancelled = 0
    pcall(function() cancelled = periodic_cancel_old() end)
    local ids, ok_n = {}, 0
    for _, item in ipairs(PERIODIC_TASKS_SPEC or {}) do
        local ok, h = pcall(util.schedule, item[1], item[2])
        if ok then
            ok_n = ok_n + 1
            if type(h) == "number" and h > 0 then ids[#ids + 1] = h end
        end
    end
    pcall(util.json_write, PERIODIC_ID_FILE, {
        count = ok_n, ids = ids, cancelled = cancelled, at = now,
        note = "v29：定时器已砍到 1 个主心跳，且仅真加载注册",
    })
    pcall(util.json_write, PERIODIC_GEN_FILE, {
        gen = 1, at = now, count = ok_n, ids = ids, cancelled = cancelled,
        note = "v29 已归零（此前累积到 666 代 = 卡顿根因）",
    })
    pcall(log_event, "PERIODIC",
        "v29 真加载注册 " .. tostring(ok_n) .. " 个定时器（已砍到 1 个主心跳）")
    return ok_n
end

local _v29_prev_on_init = on_init
function on_init()
    local tk = v29_boot_token()
    if tk == "" or tk == v29_init_done_token() then
        return
    end
    v29_init_mark(tk)
    if type(_v29_prev_on_init) == "function" then
        return _v29_prev_on_init()
    end
end

if v29_is_fresh_load() then
    pcall(register_periodic_tasks)
end

function cmd_v29_timer_diag(playerName)
    local lines = { "§b━━ 定时器泄漏自检（v29）━━" }
    local gd = v29_read_json(PERIODIC_GEN_FILE)
    local id = v29_read_json(PERIODIC_ID_FILE)
    lines[#lines + 1] = "§f注册代数 gen：§e" .. tostring(gd.gen or "?")
        .. " §8（v29 后每次真加载归零为 1；若持续增长说明又有路径在注册）"
    lines[#lines + 1] = "§f主心跳数量：§e" .. tostring(id.count or "?") .. " §7个（已从 10 砍到 1）"
    lines[#lines + 1] = "§f心跳年龄：§e" .. string.format("%.0f", periodic_beat_age()) .. " §7秒"
    lines[#lines + 1] = "§f真加载守卫：§e" .. tostring(v29_is_fresh_load())
        .. " §8（重跑上下文应为 false）"
    local bt, it = v29_boot_token(), v29_init_done_token()
    lines[#lines + 1] = "§fboot token：§7" .. (bt == "" and "空" or bt)
    lines[#lines + 1] = "§finit token：§7" .. (it == "" and "空" or it)
    lines[#lines + 1] = "§f本次加载 on_init 是否已执行：§e" .. tostring(bt ~= "" and bt == it)
    lines[#lines + 1] = "§8若 gen 仍在涨 → 重启工具箱彻底清掉累积的旧定时器。"
    send(playerName, table.concat(lines, "\n"))
    return true
end

local _v29_prev_on_chat = on_chat
function on_chat(playerName, msg)
    local low = lower(trim(tostring(msg or "")))
    if low == ".定时器诊断" or low == ".定时器泄漏" then
        return cmd_v29_timer_diag(playerName)
    end
    return _v29_prev_on_chat(playerName, msg)
end
