function ai_channel_load()
    local ok, d = pcall(util.json_load, AI_CHANNEL_FILE)
    if ok and type(d) == "table" then
        d.list = d.list or {}
        return d
    end
    return { list = {}, active = 0 }
end
function ai_channel_save(d) pcall(util.json_write, AI_CHANNEL_FILE, d or {}) end
function ai_channel_all() return ai_channel_load().list or {} end
function ai_channel_active()
    local d = ai_channel_load()
    local idx = tonumber(d.active) or 0
    if idx <= 0 then return nil end
    return d.list[idx]
end
function ai_channel_set_active(idx)
    local d = ai_channel_load()
    idx = tonumber(idx) or 0
    if idx < 0 or idx > #(d.list or {}) then return false, "编号不存在" end
    d.active = idx
    ai_channel_save(d)
    return true
end
function ai_channel_ready(c)
    return type(c) == "table" and trim(tostring(c.api_key or "")) ~= ""
        and trim(tostring(c.base_url or "")) ~= ""
        and trim(tostring(c.model_id or "")) ~= ""
end
function ai_channel_add(name, base_url, api_key, model_id)
    name = trim(tostring(name or "")); base_url = trim(tostring(base_url or ""))
    api_key = trim(tostring(api_key or "")); model_id = trim(tostring(model_id or ""))
    if base_url == "" or api_key == "" or model_id == "" then
        return false, "接口地址/密钥/模型名 都不能为空"
    end
    if name == "" then name = model_id end
    local d = ai_channel_load(); d.list = d.list or {}
    d.list[#d.list + 1] = { name = name, base_url = base_url, api_key = api_key,
        model_id = model_id, kind = "direct", added_at = util.timestamp() }
    ai_channel_save(d)
    return true, #d.list
end
function ai_channel_del(idx)
    local d = ai_channel_load(); idx = tonumber(idx) or 0
    if idx < 1 or idx > #(d.list or {}) then return false, "编号不存在" end
    local old = d.list[idx]
    table.remove(d.list, idx)
    if tonumber(d.active) == idx then d.active = 0
    elseif (tonumber(d.active) or 0) > idx then d.active = tonumber(d.active) - 1 end
    ai_channel_save(d)
    return true, old and old.name or "?"
end
function ai_channel_import_presets()
    local d = ai_channel_load(); d.list = d.list or {}
    local added = 0
    for _, p in ipairs(AI_CHANNEL_PRESETS) do
        local exists = false
        for _, c in ipairs(d.list) do
            if tostring(c.name) == tostring(p.name) then exists = true; break end
        end
        if not exists then
            d.list[#d.list + 1] = { name = p.name, base_url = p.base_url, api_key = "",
                model_id = p.model_id, kind = "direct", preset = true,
                note = p.note, added_at = util.timestamp() }
            added = added + 1
        end
    end
    ai_channel_save(d)
    return added, #d.list
end

function ai_channel_call_direct(c, messages, timeout, max_tokens_override)
    local url = ai_direct_url(c.base_url)
    local key = trim(tostring(c.api_key or ""))
    if url == "" or key == "" then return false, "渠道缺少接口地址或密钥" end
    local mt0 = tonumber(max_tokens_override) or MAX_REPLY
    if mt0 > 8192 then mt0 = 8192 end
    if mt0 < 512 then mt0 = 512 end

    local function once(mt)
        local req = { model = tostring(c.model_id or ""), messages = messages,
            temperature = TEMPERATURE, max_tokens = mt, stream = false }
        if not ai_thinking_enabled() then
            req.thinking = { type = "disabled" }
            req.reasoning_effort = "none"
        end
        local ok_post, r = pcall(http.post, url, http.json_encode(req), {
            headers = { ["Content-Type"] = "application/json", ["Authorization"] = "Bearer " .. key },
            timeout = timeout })
        if not ok_post then return false, nil, 0, nil, "网络异常：" .. tostring(r) end
        if not r or not r.ok then return false, nil, 0, nil, "请求失败：" .. tostring(r and (r.error or r.status) or "无响应") end
        local code = tonumber(r.status) or 0
        local rbody = tostring(r.body or "")
        if code == 401 or code == 403 then return false, nil, 0, nil, "密钥无效或无权（HTTP " .. code .. "）：" .. rbody:sub(1, 160) end
        if code == 404 then return false, nil, 0, nil, "接口地址或模型名不对（HTTP 404）：" .. rbody:sub(1, 160) end
        if code == 429 then return false, nil, 0, nil, "限速(429)：" .. rbody:sub(1, 160) end
        if code < 200 or code >= 300 then return false, nil, 0, nil, "HTTP " .. code .. "：" .. rbody:sub(1, 200) end
        local ok2, data = pcall(http.json_decode, rbody)
        if not ok2 or type(data) ~= "table" then return false, nil, 0, nil, "返回不是 JSON" end
        local tok = ai_usage_extract(data)
        local ch = data.choices and data.choices[1]
        local fin = tostring(ch and ch.finish_reason or "?")
        local msg = ch and ch.message
        local c2 = msg and msg.content
        if (not c2 or trim(tostring(c2)) == "") and msg then c2 = msg.reasoning_content or msg.reasoning end
        if not c2 or trim(tostring(c2)) == "" then
            return false, nil, tok, fin, "模型没返回内容（finish=" .. fin .. "）"
        end
        return true, tostring(c2), tok, fin, nil
    end

    local ok1, c1, t1, fin1, e1 = once(mt0)
    if ok1 then return true, c1, t1 end
    -- 推理模型可能把 token 全用在 reasoning 上导致 finish=length、content 空；放大上限重试一次
    if fin1 == "length" and mt0 < 8192 then
        local ok2, c2, t2, _f2, e2 = once(8192)
        if ok2 then return true, c2, (tonumber(t1) or 0)+(tonumber(t2) or 0) end
        return false, tostring(e2), (tonumber(t1) or 0)+(tonumber(t2) or 0)
    end
    return false, tostring(e1), t1
end

local _v31_prev_call_ai = call_ai
call_ai = function(messages, timeout_override, model_override, max_tokens_override)
    local c = ai_channel_active()
    if c then
        if not ai_channel_ready(c) then
            error("指定渠道「" .. tostring(c.name or "?") .. "」还没填密钥。\n§7用 §f.AI渠道 设置 <编号> <密钥>§7，或 §f.AI渠道 自动§7 恢复默认。")
        end
        messages = ai_trim_messages(messages)
        local ok, txt, tok = ai_channel_call_direct(c, messages, timeout_override or TIMEOUT, max_tokens_override)
        local _t = tonumber(tok) or 0
        AI_USAGE.last_call = _t
        AI_USAGE.task = (tonumber(AI_USAGE.task) or 0) + _t
        AI_USAGE.task_calls = (tonumber(AI_USAGE.task_calls) or 0) + 1
        if ok then
            save_ai_trace({ model = tostring(c.name or c.model_id), status = "response_ok_channel",
                status_code = 200, reason = "指定 AI 渠道（.AI渠道）",
                assistant_output = tostring(txt), usage_tokens = _t })
            return txt
        end
        error("指定渠道「" .. tostring(c.name or "?") .. "」调用失败：" .. tostring(txt)
            .. "\n§7可用 §f.AI渠道 列表§7 检查，或 §f.AI渠道 自动§7 恢复默认。")
    end
    return _v31_prev_call_ai(messages, timeout_override, model_override, max_tokens_override)
end

function cmd_ai_channel(name, raw)
    local body = trim(tostring(raw or ""))
    local low = lower(body)

    if low == "官网" or low == "预设" or low == "preset" then
        local added, total = ai_channel_import_presets()
        local lines = { "§b━━ 已导入官方渠道预设 ━━",
            "§7本次新增 §e" .. added .. " §7个，共 §e" .. total .. " §7个。",
            "§e给渠道补密钥：§f.AI渠道 设置 编号 你的密钥" }
        for i, p in ipairs(AI_CHANNEL_PRESETS) do
            lines[#lines + 1] = "§8· §f" .. p.name .. " §7" .. p.model_id .. " §8" .. p.base_url
        end
        lines[#lines + 1] = "§7例：§f.AI渠道 设置 1 sk-xxxxxxxx"
        send(name, table.concat(lines, "\n"))
        return true
    end

    if low == "自动" or low == "默认" or low == "关闭" or low == "取消" then
        ai_channel_set_active(0)
        send(name, "§a✓ 已关闭指定渠道，AI 恢复默认通道（直连模型）。")
        return true
    end

    local test_idx = low:match("^测%s*(%d+)$") or low:match("^测试%s*(%d+)$") or low:match("^检查%s*(%d+)$")
    if test_idx then
        local list = ai_channel_all()
        local c = list[tonumber(test_idx)]
        if not c then send(name, "§c编号不存在。"); return true end
        if not ai_channel_ready(c) then
            send(name, "§e「" .. tostring(c.name) .. "」还没填密钥。\n§f.AI渠道 设置 " .. test_idx .. " 你的密钥")
            return true
        end
        send(name, "§7正在测试「" .. tostring(c.name) .. "」……")
        local ok, txt = ai_channel_call_direct(c, { { role = "user", content = "只回复两个字：正常" } }, 30, 64)
        if ok then
            send(name, "§a✓ 渠道可用！\n§f模型：§e" .. tostring(c.model_id)
                .. "\n§f回复：§7" .. tostring(txt):sub(1, 80)
                .. "\n§7启用：§f.AI渠道 用 " .. test_idx)
        else
            send(name, "§c✘ 渠道不可用：" .. tostring(txt))
        end
        return true
    end

    local use_idx = low:match("^用%s*(%d+)$") or low:match("^启用%s*(%d+)$")
        or low:match("^选择%s*(%d+)$") or low:match("^切换%s*(%d+)$")
    if use_idx then
        local list = ai_channel_all()
        local c = list[tonumber(use_idx)]
        if not c then send(name, "§c编号不存在。用 §f.AI渠道 列表 §c查看。"); return true end
        if not ai_channel_ready(c) then
            send(name, "§e「" .. tostring(c.name) .. "」还没填密钥，不能启用。\n§f.AI渠道 设置 " .. use_idx .. " 你的密钥")
            return true
        end
        ai_channel_set_active(tonumber(use_idx))
        send(name, "§a✓ AI 已切换到：§e" .. tostring(c.name)
            .. "\n§f接口：§7" .. tostring(c.base_url)
            .. "\n§f模型：§e" .. tostring(c.model_id)
            .. "\n§7以后所有 AI 对话/指令都走这个渠道；恢复默认：§f.AI渠道 自动")
        return true
    end

    local del_idx = low:match("^删除%s*(%d+)$") or low:match("^移除%s*(%d+)$") or low:match("^删%s*(%d+)$")
    if del_idx then
        local ok, nm = ai_channel_del(del_idx)
        if ok then send(name, "§e✓ 已删除渠道「" .. tostring(nm) .. "」。")
        else send(name, "§c" .. tostring(nm)) end
        return true
    end

    local set_idx, key, url2, mid2 = body:match("^设置%s*(%d+)%s+(%S+)%s*(%S*)%s*(%S*)$")
    if set_idx then
        local d = ai_channel_load()
        local c = d.list[tonumber(set_idx)]
        if not c then send(name, "§c编号不存在。"); return true end
        c.api_key = trim(key)
        if url2 and trim(url2) ~= "" then c.base_url = trim(url2) end
        if mid2 and trim(mid2) ~= "" then c.model_id = trim(mid2) end
        ai_channel_save(d)
        send(name, "§a✓ 已更新「" .. tostring(c.name) .. "」\n§f接口：§7" .. tostring(c.base_url)
            .. "\n§f模型：§e" .. tostring(c.model_id)
            .. "\n§7建议先测试：§f.AI渠道 测 " .. set_idx)
        return true
    end

    local an, au, ak, am = body:match("^添加%s+(%S+)%s+(%S+)%s+(%S+)%s+(%S+)%s*$")
    if an then
        local ok, info = ai_channel_add(an, au, ak, am)
        if ok then
            send(name, "§a✓ 已添加渠道「" .. an .. "」编号 §e" .. info
                .. "\n§7测试：§f.AI渠道 测 " .. info .. " §7｜启用：§f.AI渠道 用 " .. info)
        else
            send(name, "§c" .. tostring(info))
        end
        return true
    end

    local d = ai_channel_load()
    local list = d.list or {}
    local lines = { "§8§m━━━━━━━━━━━━━━━━━━━━━━━━",
        "§b§lAI 渠道管理 §8┃ §7共 " .. #list .. " 个",
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━" }
    if #list == 0 then
        lines[#lines + 1] = "§7还没有任何渠道。"
        lines[#lines + 1] = "§e① 一键导入官方预设：§f.AI渠道 官网"
        lines[#lines + 1] = "§e② 或手动添加：§f.AI渠道 添加 名称 接口 密钥 模型"
        lines[#lines + 1] = "§7例：§f.AI渠道 添加 DeepSeek https://api.deepseek.com sk-xxx deepseek-chat"
    else
        for i, c in ipairs(list) do
            local ready = ai_channel_ready(c)
            local mark = ready and "§a●" or "§7○"
            local cur = ((tonumber(d.active) or 0) == i) and " §b←当前" or ""
            lines[#lines + 1] = string.format("§f%d. %s §f%s §8[§7%s§8]%s",
                i, mark, tostring(c.name), tostring(c.model_id or "?"), cur)
            if not ready then
                lines[#lines + 1] = "§8   └ 未填密钥：§f.AI渠道 设置 " .. i .. " 你的密钥"
            end
        end
    end
    lines[#lines + 1] = "§8§m━━━━━━━━━━━━━━━━━━━━━━━━"
    lines[#lines + 1] = "§7➜ §f.AI渠道 用 编号§7 切换 · §f.AI渠道 测 编号§7 测试"
    lines[#lines + 1] = "§7➜ §f.AI渠道 添加/设置/删除§7 · §f.AI渠道 官网§7 导入预设"
    lines[#lines + 1] = "§7➜ §f.AI渠道 自动§7 恢复默认（直连模型）"
    send(name, table.concat(lines, "\n"))
    return true
end

local _v31_prev_on_chat = on_chat
function on_chat(playerName, msg)
    local raw = trim(tostring(msg or ""))
    local body = raw:match("^%.[Aa][Ii]渠道%s*(.*)$") or raw:match("^%.渠道%s*(.*)$")
    if body ~= nil then
        if not is_admin(playerName) then
            pcall(send, playerName, "§c只有管理权限可以切换 AI 渠道。")
            return
        end
        return cmd_ai_channel(playerName, body)
    end
    return _v31_prev_on_chat(playerName, msg)
end


-- 1.0.36 · 最终提示词编排器
-- 历史版本曾存在多层 build_ai_system 包装器，导致身份/时间/执行者提示词即使不相关也被追加。
-- 1.0.36 已清理这些无效 prompt 包装器；以下函数是唯一运行时最终版本：仅核心常驻；专项只通过 LOAD_SUB_PROMPT 或复杂工具自动加载。
function ai_prompt_render(txt, playerName)
    txt=tostring(txt or "")
    local botname=ai_bot_identity(); if botname=="" then botname="本机器人账号" end
    txt=txt:gsub("%{BOT_NAME%}", tostring(botname))
    txt=txt:gsub("%{PLAYER_NAME%}", tostring(playerName or "当前玩家"))
    return txt
end

function ai_runtime_context(playerName,admin)
    local who=tostring(playerName or "当前玩家")
    local role=admin and "管理权限" or "普通玩家"
    local bot=ai_bot_identity(); if bot=="" then bot="服务器执行主体" end
    local continuity=ai_continuity_fact(who)
    local perm=admin and "管理权限可按插件代码使用管理工具。" or "普通玩家按代码权限使用基础查询与允许的游戏操作；权限不足由真实工具执行层返回，模型不要自行扩大或缩小权限。"
    return "【当前运行状态】提问者="..who.."；权限="..role.."；执行主体="..bot.."。权限与真实执行结果由插件代码决定。"..perm..(continuity~="" and ("\n\n"..continuity) or "")
end


-- v1.0.43 command observation wrapper
local _v43_prev_run_command = run_command
function run_command(cmd,playerName,admin)
    local task_id=ai_new_task_id(playerName); local ok,res=pcall(_v43_prev_run_command,cmd,playerName,admin)
    local raw=ok and tostring(res or "") or ("运行时异常："..tostring(res)); local status=(not ok or raw:find("失败",1,true) or raw:find("权限限制",1,true) or raw:find("拒绝",1,true)) and "failed" or "success"; local reason=ai_observation_reason(raw,status)
    ai_observation_write(task_id,playerName,"CMD",tostring(cmd or ""),status,raw,reason,"runtime.run_command"); ai_task_update(task_id,playerName,status,"CMD",tostring(cmd or ""),reason)
    if not ok then return raw end; return res
end

-- ============================================================================
-- v1.0.47：聊天日志持久化 + 普通玩家 AI 工具白名单
-- 目的：
-- 1. runtime.log 仍保留运行日志，但聊天记录另存 chat_logs.json，避免因为运行日志
--    滚动、缓冲或关键词过滤导致 AI 只能看到当前一句话。
-- 2. 普通玩家的 AI 能力改为代码级白名单：正常聊天、自己的信息/坐标/分数/标签、
--    自己的背包、自己施加药水效果、规定时间/天气投票。其它工具直接返回权限不足，
--    并且不把内部工具标记显示给玩家。
-- ============================================================================

AI_ORDINARY_DENIAL = "权限不足：普通玩家目前只能使用正常聊天、查询自己的信息/坐标/分数/标签/背包、给自己施加药水效果，以及发起规定的时间/天气投票。"

function ai_ordinary_question_allowed(question)
    local q=lower(tostring(question or ""))
    if q=="" then return false end
    local keys={"投票","药水","效果","背包","物品栏","库存","自己的信息","个人信息","我的信息","我的坐标","自己的坐标","当前位置","分数","积分","标签","uuid","xuid","坐标","位置","时间","天气","白天","晚上","下雨","停雨","晴天","雷暴"}
    for _,k in ipairs(keys) do if q:find(k,1,true) then return true end end
    return false
end

local function ai_ordinary_allowed_target(payload, playerName)
    local t=trim(tostring(payload or ""))
    if t=="" or lower(t)=="self" or lower(t)=="me" then return true end
    return lower(t)==lower(tostring(playerName or ""))
end

local function ai_ordinary_inventory_allowed(payload, playerName)
    local targets=inv_parse_targets(tostring(payload or ""), playerName)
    if type(targets)~="table" or #targets==0 then return false end
    for _,nm in ipairs(targets) do
        if lower(trim(tostring(nm or ""))) ~= lower(tostring(playerName or "")) then return false end
    end
    return true
end

function ai_ordinary_disallowed_tool(text, playerName)
    local s=tostring(text or "")

    -- 任意管理/外部能力都不允许普通玩家调用。
    local always_denied={
        "LOG","BUILD","BUILD_STOP","BUILD_OFF","NBT","MUTE","NET","SEARCH_WEB","LIST","LOCATE"
    }
    for _,tag in ipairs(always_denied) do
        if s:find("["..tag.."]",1,true) or s:find("["..tag.."]",1,true) then
            return true
        end
    end

    -- 自定义命令/壳工具：逐条检查，只允许自己的药水和白名单投票。
    for _,cmd in ipairs(extract(s,"CMD")) do
        local c=normalize_cmd(cmd)
        if c~="" then
            local head=command_head(c)
            if head=="effect" then
                local target=c:match("^effect%s+(%S+)") or ""
                if not ai_ordinary_allowed_target(target,playerName) then return true end
            elseif head=="time" or head=="weather" then
                if not is_vote_command(c) then return true end
            else
                return true
            end
        end
    end

    for _,payload in ipairs(extract(s,"SHELL3")) do
        local body=trim(payload)
        local op,target=body:match("^(%S+)%s*(.*)$")
        op=lower(op or "")
        if op=="self" then
            -- 自己的基础信息允许。
        elseif op=="info" and ai_ordinary_allowed_target(target,playerName) then
            -- 自己的信息允许。
        else
            return true
        end
    end

    for _,payload in ipairs(extract(s,"SHELL1")) do
        -- SHELL1 在普通玩家分支中只读取自己的位置/信息。
    end

    for _,payload in ipairs(extract(s,"SHELL2")) do
        local body=trim(payload)
        local kind,rest=body:match("^(%S+)%s*(.*)$")
        kind=lower(kind or "")
        if kind=="effect" then
            -- 插件会强制目标为当前玩家。
        elseif kind=="vote" and trim(rest)~="" and is_vote_command(normalize_cmd(rest)) then
            -- 规定投票允许。
        else
            return true
        end
    end

    for _,payload in ipairs(extract(s,"VOTE")) do
        if not is_vote_command(normalize_cmd(payload)) then return true end
    end

    for _,payload in ipairs(extract(s,"GETINFO")) do
        if not ai_ordinary_allowed_target(payload,playerName) then return true end
    end
    for _,payload in ipairs(extract(s,"GETSCORE")) do
        local target=trim(tostring(payload or "")):match("^(%S+)%s+")
        if target and lower(target)~=lower(tostring(playerName or "")) then return true end
    end
    for _,payload in ipairs(extract(s,"GETTAG")) do
        local target=trim(tostring(payload or "")):match("^(%S+)%s+")
        if target and lower(target)~=lower(tostring(playerName or "")) then return true end
    end
    for _,payload in ipairs(extract(s,"GETINVENTORY")) do
        if not ai_ordinary_inventory_allowed(payload,playerName) then return true end
    end

    -- 其它管理工具标记一律拒绝；提示词加载本身不算执行工具，不在这里拦截。
    local extra_denied={"PERSONA","TIME"}
    for _,tag in ipairs(extra_denied) do
        if s:find("["..tag.."]",1,true) then
            -- PERSONA/LOAD_SUB_PROMPT 属于内部提示词能力，不允许普通玩家直接要求 AI 注入。
            return true
        end
    end
    return false
end

-- 使用独立、稳定的聊天日志，不依赖 runtime.log 的 512 KB 滚动窗口。
function chat_log_query(playerName, query)
    local db=file_load(CHAT_LOG_FILE,{logs={}})
    local logs=type(db.logs)=="table" and db.logs or {}
    if #logs==0 then return "聊天日志：暂无记录。" end
    local q=trim(tostring(query or ""))
    local minutes=q:match("(%d+)%s*分钟前") or q:match("(%d+)%s*分钟")
    local now=tonumber(util.timestamp()) or os.time()
    local cutoff=minutes and (now-(tonumber(minutes) or 0)*60) or nil

    local generic=q
    local stop={"日志","聊天日志","聊天记录","最近","刚才","谁说了什么","说了什么","发言","消息","记录","查一下","查询一下","查询","查查","查","查看一下","查看","看看","看看日志","帮我","给我","一下"}
    for _,x in ipairs(stop) do generic=generic:gsub(x,"") end
    generic=generic:gsub("%d+%s*分钟前",""):gsub("%d+%s*分钟","")
    generic=trim(generic)

    local matched={}
    for _,item in ipairs(logs) do
        if type(item)=="table" then
            local at=tonumber(item.at) or 0
            if (not cutoff or at>=cutoff) then
                local who=tostring(item.player or "")
                local msg=tostring(item.message or "")
                local hay=lower(who.." "..msg)
                local need=lower(generic)
                if need=="" or hay:find(need,1,true) then
                    matched[#matched+1]=item
                end
            end
        end
    end

    local max_count=120
    local start=math.max(1,#matched-max_count+1)
    local lines={"聊天日志（最近最多120条）："}
    for i=start,#matched do
        local item=matched[i]
        lines[#lines+1]=string.format("[%s] [%s] %s",log_time_local(tonumber(item.at) or now),tostring(item.player or "?"),tostring(item.message or ""))
    end
    if #lines==1 then return "聊天日志：没有符合条件的记录。" end
    local out=table.concat(lines,"\n")
    if #out>20000 then out=out:sub(-20000) end
    return out
end

-- 重写管理日志查询：普通“查日志/最近聊天/谁说了什么”优先使用持久化聊天日志；
-- 运行异常/工具失败等仍从 runtime.log 查询。
local _v47_old_read_recent_logs=read_recent_logs
function read_recent_logs(playerName, query)
    if not is_admin(playerName) then return "权限限制：只有管理权限可以读取日志。" end
    local q=lower(trim(tostring(query or "")))
    local runtime_mode=(q:find("runtime.log",1,true) or q:find("运行日志",1,true) or q:find("运行错误",1,true) or q:find("报错",1,true) or q:find("异常",1,true))
    local chat_mode=(not runtime_mode) and (q=="" or q:find("日志",1,true) or q:find("聊天",1,true) or q:find("发言",1,true) or q:find("说了什么",1,true) or q:find("消息",1,true) or q:find("刚才",1,true) or q:find("最近",1,true) or q:find("记录",1,true))
    if chat_mode then return chat_log_query(playerName,query) end
    return _v47_old_read_recent_logs(playerName,query)
end

-- 记录每一条收到的原始聊天消息；只写消息元数据和正文，不依赖 runtime.log 缓冲。
local _v47_old_on_chat=on_chat
function on_chat(playerName,msg)
    local raw=trim(tostring(msg or ""))
    if raw~="" then
        pcall(append_json_log,CHAT_LOG_FILE,{at=tonumber(util.timestamp()) or os.time(),type="CHAT",player=tostring(playerName or ""),message=raw})
    end
    return _v47_old_on_chat(playerName,msg)
end

-- 普通玩家的工具调用最终拦截层：权限以代码为准，不允许模型通过提示词绕过。
local _v47_old_process_tools=process_tools
function process_tools(text,playerName,admin,cmd_limit,active_subprompts,task_mode)
    if not admin and ai_ordinary_disallowed_tool(text,playerName) then
        return {AI_ORDINARY_DENIAL}, true, {}, false
    end
    return _v47_old_process_tools(text,playerName,admin,cmd_limit,active_subprompts,task_mode)
end

-- 普通玩家不要走“AI拒答纠错后强行生成管理 CMD”的旧逻辑；允许范围内的投票/药水/自查仍由
-- 上面的代码级白名单执行，禁止范围直接返回权限不足。
local _v47_old_ai_reply_refused=ai_reply_refused
function ai_reply_refused(text)
    return _v47_old_ai_reply_refused(text)
end

-- 最后一层可见输出清理：任何工具标记、内部标识和 Minecraft 格式码都不直接显示给玩家。
local _v47_old_clean_ai_visible=clean_ai_visible
function clean_ai_visible(v)
    local out=_v47_old_clean_ai_visible(v)
    out=tostring(out or "")
    out=out:gsub("§.","")
    out=out:gsub("%s*%[/?[A-Z_]+%][^%[%]]*%s*", " ")
    return trim(out)
end




