function patch_prompt_candidates(id)
    local out = {}
    local seen = {}
    local function add(p)
        p = tostring(p or "")
        if p ~= "" and not seen[p] then seen[p] = true; out[#out+1] = p end
    end
    local fn = "seg_"..tostring(id)..".txt"
    local ok,dd=pcall(game.dataDir)
    if ok and type(dd)=="string" and dd~="" then
        add(dd.."/"..fn)
        add(dd.."/ai_prompts/"..fn)
    end
    local ok2,cd=pcall(plugin_code_dir)
    if ok2 and type(cd)=="string" and cd~="" then add(cd.."/"..fn); add(cd.."/ai_prompts/"..fn) end
    local ok3,bd=pcall(plugin_base_dir)
    if ok3 and type(bd)=="string" and bd~="" then
        add(bd.."/插件文件/"..tostring(plugin_id_now()).."/"..fn)
        add(bd.."/插件文件/"..tostring(plugin_id_now()).."/ai_prompts/"..fn)
    end
    return out
end

function ensure_patch_prompt_files()
    for id,txt in pairs(AI_PROMPT_BUILTIN or {}) do
        local found=false
        for _,p in ipairs(patch_prompt_candidates(id)) do
            local ok,v=pcall(util.read_file,p)
            if ok and type(v)=="string" and #v>10 then found=true; break end
        end
        if not found then
            local c=patch_prompt_candidates(id)[1]
            if c then pcall(util.write_file,c,txt:gsub("\\n","\n")) end
        end
    end
end

function ai_seg_load(name, force)
    local id=ai_seg_canonical(name)
    if id=="" then return "" end
    if (not force) and _AI_SEG_CACHE[id]~=nil and tostring(_AI_SEG_CACHE[id])~="" then return _AI_SEG_CACHE[id] end
    local txt=""
    for _,p in ipairs(patch_prompt_candidates(id)) do
        local ok,v=pcall(util.read_file,p)
        if ok and type(v)=="string" and trim(v)~="" then txt=v; break end
    end
    if trim(txt)=="" then txt=AI_PROMPT_BUILTIN[id] or "" end
    _AI_SEG_CACHE[id]=txt
    return txt
end

function ai_seg_status()
    ensure_patch_prompt_files()
    local lines={"AI TXT 状态（多路径联通版）："}
    for _,id in ipairs(AI_SEG_IDS or {}) do
        local txt=ai_seg_load(id,true)
        lines[#lines+1]=ai_seg_filename(id).." → "..(trim(txt)~="" and ("正常/"..#txt.."字") or "缺失")
    end
    return table.concat(lines,"\n")
end

