    return true
end

-- ---------- 导入/导出：保留原始偏移，不再用 minX/minY/minZ 二次归零 ----------
function place_native_region(playerName,name,tx,ty,tz)
    local m,err=load_native_manifest(name)
    if not m then return false,err end
    tx,ty,tz=math.floor(tonumber(tx) or 0),math.floor(tonumber(ty) or 0),math.floor(tonumber(tz) or 0)
    local origin=m.origin or {}
    local ox,oy,oz=tonumber(origin.x),tonumber(origin.y),tonumber(origin.z)
    if not ox or not oy or not oz then return false,"区域数据原点损坏。" end
    local list={}
    for key,v in pairs(m.blocks or {}) do
        local sx,sy,sz=tostring(key):match("^(-?%d+),(-?%d+),(-?%d+)$")
        if sx and type(v)=="table" then
            local bn=tostring(v.name or v.id or "")
            if bn~="" then
                local item={x=tonumber(sx)-ox,y=tonumber(sy)-oy,z=tonumber(sz)-oz,name=bn}
                if v.states~=nil then item.states=v.states end
                if type(v.nbt)=="table" then item.nbt=normalize_import_nbt(v.nbt) end
                list[#list+1]=item
            end
        end
    end
    if #list<=0 then return false,"区域数据为空。" end
    table.sort(list,function(a,b)
        if a.y~=b.y then return a.y<b.y end
        if a.z~=b.z then return a.z<b.z end
        return a.x<b.x
    end)
    local ok_call,run=pcall(game.importBlocks,list,{x=tx,y=ty,z=tz,dimension=dim_exec(detect_dimension(playerName)),speed=-1,region_mode=1,anti_loss=true})
    if not ok_call then return false,"导入失败："..tostring(run) end
    local ok_wait,finished=pcall(game.importWait,run)
    if not ok_wait then return false,"导入等待失败："..tostring(finished) end
    if finished==true then
        local size=m.size or {}
        log_event("NBT_REGION",tostring(playerName).." imported region "..tostring(name).." blocks="..tostring(#list).." preserve_offset=true")
        return true,"§a导入完成：§e"..tostring(name).." §f（"..tostring(#list).." 个方块）\n§7原始原点偏移已保留，没有再做二次归零。"
    end
    return false,"导入过程未正常完成。"
end

function nbt_region_self_check(name)
    local m,e=load_native_manifest(name)
    if not m then return false,e end
    local n=0; local sample={}
    for k,v in pairs(m.blocks or {}) do if type(v)=="table" then n=n+1; if #sample<5 then sample[#sample+1]=k end end end
    return true,"导出数据正常：原点="..tostring(m.origin and (m.origin.x..","..m.origin.y..","..m.origin.z) or "?").."，尺寸="..tostring(m.size and (m.size.x.."×"..m.size.y.."×"..m.size.z) or "?").."，记录="..n.."，样本="..table.concat(sample," | ")
end

-- ---------- 背包查询：多接口 + 选择器兼容，避免“空=读取失败” ----------
function patch_inventory_query_real(nm)
    local safe=string.gsub(tostring(nm),'"','\\"')
    local candidates={
        {fn=function() return game.queryInventory('@a[name="'..safe..'"]') end,src="game.queryInventory(selector)"},
        {fn=function() return game.queryInventory(tostring(nm)) end,src="game.queryInventory(name)"},
        {fn=function() return player.getInventory(tostring(nm)) end,src="player.getInventory(name)"},
    }
    for _,c in ipairs(candidates) do
        local ok,inv=pcall(c.fn)
        if ok and type(inv)=="table" and type(inv.items)=="table" then
            -- 明确允许真实空背包，但不把 nil/异常当空。
            return true,inv,c.src
        end
    end
    return false,nil,"所有背包读取接口均未返回合法 items 表"
end

function ai_inventory_sync(playerName,targetText,admin)
    local targets=inv_parse_targets(targetText,playerName)
    local allowed,denied={},{}
    for _,nm in ipairs(targets or {}) do
        nm=trim(tostring(nm or ""))
        if nm~="" then
            if admin or lower(nm)==lower(playerName) then allowed[#allowed+1]=nm else denied[#denied+1]=nm end
        end
    end
    if #denied>0 then return "权限限制：普通玩家只能查询自己的背包（已拒绝："..table.concat(denied,"、").."）。",false end
    if #allowed==0 then return "背包查询失败：没有有效玩家目标。",false end
    local ai_out={"背包真实查询结果："}; local screen_out={}
    for _,nm in ipairs(allowed) do
        local ok,inv,src=patch_inventory_query_real(nm)
        local block_ai={nm.."："}; local block_screen={"§b━━ "..nm.." 的背包 ━━"}
        if not ok then
            block_ai[#block_ai+1]="读取失败（没有真实背包返回，不能把失败当成空背包）。"
            block_screen[#block_screen+1]="§c读取失败：接口没有返回真实数据。"
        else
            local items=inv.items or {}
            if #items==0 then block_ai[#block_ai+1]="背包为空。"; block_screen[#block_screen+1]="§7背包为空。"
            else
                local arr={}
                for _,it in pairs(items) do
                    if type(it)=="table" then
                        local count=tonumber(it.count or it.Count or it.stackSize or 0) or 0
                        if count>0 then
                            local id=tostring(it.name or it.Name or it.id or "unknown")
                            local dmg=it.damage or it.Damage or it.aux or 0
                            arr[#arr+1]=short_item_name({name=id,damage=dmg}).." ×"..count.." ["..id.."]"
                        end
                    end
                end
                block_ai[#block_ai+1]=#arr>0 and table.concat(arr,"；") or "背包为空。"
                for _,line in ipairs(inv_format_items(items,3,10)) do block_screen[#block_screen+1]=line end
            end
            block_ai[#block_ai+1]="读取接口="..src
        end
        for _,x in ipairs(block_ai) do ai_out[#ai_out+1]=x end
        for _,x in ipairs(block_screen) do screen_out[#screen_out+1]=x end
    end
    pcall(send,playerName,table.concat(screen_out,"\n").."\n§7（以上是实时查询结果）")
    return table.concat(ai_out,"\n"),true
end

-- ---------- 金币排行榜（沿用现有积分/金币计分板） ----------
function coin_leaderboard(name, limit)
    limit=math.max(1,math.min(tonumber(limit) or 10,20))
    local board=scoreboard_name()
    if not board then send(name,"§c服务器尚未设置金币/积分计分板。"); return true end
    local names=online_players() or {}
    local rows={}
    local db=load_data()
    for _,rec in pairs(db.players or {}) do
        local nm=type(rec)=="table" and tostring(rec.name or "") or ""
        if nm~="" and not rec.deleted then names[#names+1]=nm end
    end
    local seen={}
    for _,nm in ipairs(names) do
        nm=tostring(nm); if nm~="" and not seen[lower(nm)] then
            seen[lower(nm)]=true
            local ok,score=pcall(game.getScore,board,nm)
            if ok then rows[#rows+1]={name=nm,score=tonumber(score) or 0} end
        end
    end
    table.sort(rows,function(a,b) if a.score~=b.score then return a.score>b.score end return lower(a.name)<lower(b.name) end)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§6✦ §e§l金币排行榜 §6✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    if #rows==0 then lines[#lines+1]="§7暂无可读取的玩家金币数据。" else
        for i=1,math.min(limit,#rows) do
            local r=rows[i]; local medal=({"§6①","§f②","§c③"})[i] or ("§7"..i..".")
            lines[#lines+1]=medal.." §f"..r.name.." §8▸ §6"..r.score.." 金币"
        end
    end
    send(name,table.concat(lines,"\n")); return true
end

-- ---------- 公告栏：TPS、服务器号、北京时间、实用入口 ----------
ANNOUNCE_CFG_FILE = game.dataDir().."/server_announcement.json"
ANNOUNCE_OBJ = "ds_notice"
ANNOUNCE_LINES_FILE = game.dataDir().."/server_announcement_lines.json"

local function_utc8 = nil
local function patch_beijing_parts(ts)
    ts=tonumber(ts) or os.time()
    local ok,t=pcall(os.date,"!*t",ts+8*3600)
    if ok and type(t)=="table" then return t end
    return os.date("*t",ts)
end
function patch_beijing_fmt(ts)
    local t=patch_beijing_parts(ts)
    return string.format("%04d-%02d-%02d %02d:%02d",t.year,t.month,t.day,t.hour,t.min)
end
function patch_announcement_cfg()
    local ok,d=pcall(util.json_load,ANNOUNCE_CFG_FILE)
    if ok and type(d)=="table" then return d end
    return {server_number="未设置",server_number_expire=0,updated_by=""}
end
function patch_save_announcement_cfg(d) pcall(util.json_write,ANNOUNCE_CFG_FILE,d or {}) end
function patch_try_tps()
    local fns={
        function() return game.getServerTPS() end,
        function() return game.getTPS() end,
        function() return game.serverTPS() end,
    }
    for _,fn in ipairs(fns) do
        local ok,v=pcall(fn)
        if ok and tonumber(v) then return tonumber(v),"API" end
    end
    return nil,"API不可用"
end
function patch_sidebar_update()
    local cfg=patch_announcement_cfg(); local tps,src=patch_try_tps();
    if not tps then tps=tonumber(RUNTIME.patch_tps_estimate) or 0 end
    local now=util.timestamp(); local exp=tonumber(cfg.server_number_expire) or 0
    local group=(exp>now and tostring(cfg.server_number or "未设置") or "已过期")
    local lines={
        "§b✦ 服务器公告 ✦",
        "§f服务器号：§e"..group,
        "§fTPS：§a"..(tps>0 and string.format("%.1f",tps) or "检测中").." §7["..src.."]",
        "§7刷新：§f"..patch_beijing_fmt(now),
        "§d✦ .help §7功能菜单",
        "§a✦ .签到 §7每日奖励",
        "§b✦ .公会 §7公会系统",
        "§6✦ .市场 §7玩家市场",
        "§5✦ .领地 §7领地保护",
    }
    pcall(game.isCmdSuccess,"scoreboard objectives add "..ANNOUNCE_OBJ.." dummy \"公告栏\"")
    local old={}; local ok,od=pcall(util.json_load,ANNOUNCE_LINES_FILE); if ok and type(od)=="table" and type(od.lines)=="table" then old=od.lines end
    for _,v in ipairs(old) do pcall(game.isCmdSuccess,'scoreboard players reset "'..string.gsub(tostring(v),'"','\\"')..'" '..ANNOUNCE_OBJ) end
    local new={}
    local score=#lines
    for _,text in ipairs(lines) do
        local uniq=text.." "..string.rep(" ",math.max(0,score))
        new[#new+1]=uniq
        pcall(game.isCmdSuccess,'scoreboard players set "'..string.gsub(uniq,'"','\\"')..'" '..ANNOUNCE_OBJ..' '..score)
        score=score-1
    end
    pcall(game.sendCommand,"scoreboard objectives setdisplay sidebar "..ANNOUNCE_OBJ)
    pcall(util.json_write,ANNOUNCE_LINES_FILE,{lines=new,updated_at=now})
end
function patch_server_number_set(name,num,days)
    if not is_admin(name) then send(name,"§c只有管理员可以设置服务器号。"); return true end
    num=trim(tostring(num or "")); if not num:match("^%d%d%d%d%d%d*$") then send(name,"§c服务器号只能是数字。"); return true end
    days=math.max(1,tonumber(days) or 30)
    local now=util.timestamp(); local d=patch_announcement_cfg(); d.server_number=num; d.server_number_expire=now+days*86400; d.updated_by=name; d.updated_at=now; patch_save_announcement_cfg(d)
    patch_sidebar_update(); send(name,"§a✓ 服务器号已设置：§e"..num.."\n§7北京时间到期：§f"..patch_beijing_fmt(d.server_number_expire).."\n§7有效期：§e"..days.."天")
    return true
end

-- ---------- TXT 命令容器：循环/连锁/脉冲 + 条件/无条件 ----------
CMD_CONTAINER_DB_FILE = game.dataDir().."/command_containers.json"
CMD_CONTAINER_TICK = 1
function cmd_container_db()
    local ok,d=pcall(util.json_load,CMD_CONTAINER_DB_FILE); if ok and type(d)=="table" then d.items=d.items or {}; return d end; return {items={},next_id=1}
end
function cmd_container_save(d) pcall(util.json_write,CMD_CONTAINER_DB_FILE,d or {items={}}) end
function parse_command_txt(text)
    local arr={}; local index=0
    for line in tostring(text or ""):gmatch("[^\r\n]+") do
        local s=trim(line)
        if s~="" and not s:match("^#") and not s:match("^//") then
            local typ,cond,cmd=s:match("^%[?([^%]]+)%]?%s*%[?([^%]]+)%]?%s*(.+)$")
            if not typ then typ="链式"; cond="无条件"; cmd=s end
            typ=lower(trim(typ)); cond=lower(trim(cond)); cmd=trim(cmd)
            local kind=(typ:find("循环",1,true) or typ=="repeating") and "repeating" or ((typ:find("脉冲",1,true) or typ=="impulse") and "impulse" or "chain")
            local conditional=(cond:find("有条件",1,true) or cond=="conditional" or cond=="条件")~=nil
            if cmd~="" then index=index+1; arr[#arr+1]={index=index,kind=kind,conditional=conditional,command=normalize_cmd(cmd),last_success=true} end
        end
    end
    return arr
end
function cmd_container_load_txt(name)
    local cands={}
    local ok,dd=pcall(game.dataDir); if ok and type(dd)=="string" then cands[#cands+1]=dd.."/command_txt/"..name; cands[#cands+1]=dd.."/command_txt/"..name..".txt" end
    local ok2,cd=pcall(plugin_code_dir); if ok2 and type(cd)=="string" then cands[#cands+1]=cd.."/command_txt/"..name; cands[#cands+1]=cd.."/command_txt/"..name..".txt" end
    for _,p in ipairs(cands) do local ok3,v=pcall(util.read_file,p); if ok3 and type(v)=="string" and trim(v)~="" then return parse_command_txt(v),p end end
    return nil,"读取不到TXT："..tostring(name)
end
function cmd_container_show(name)
    local d=cmd_container_db(); local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§b✦ §l命令容器 §b✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    lines[#lines+1]="§f① TXT导入  §7（自动识别 .txt）"
    lines[#lines+1]="§f② 容器列表"
    lines[#lines+1]="§f③ 启动/停止容器"
    lines[#lines+1]="§f④ 新建模拟命令链"
    local n=0; for id,v in pairs(d.items or {}) do n=n+1; if n<=8 then lines[#lines+1]="§7#"..id.." §e"..tostring(v.name).." §8| "..(v.enabled and "§a运行" or "§c停止") end end
    local pd,pr=player_record(name,true); set_menu(pd,pr,"cmd_container_main"); send(name,table.concat(lines,"\n")); return true
end
function cmd_container_tick()
    local d=cmd_container_db(); local changed=false
    for id,v in pairs(d.items or {}) do
        if type(v)=="table" and v.enabled==true and type(v.nodes)=="table" and #v.nodes>0 then
            if tostring(v.type)=="repeating" then
                local prev=true
                for _,node in ipairs(v.nodes) do
                    if node.conditional and prev~=true then break end
                    local ok,res=pcall(game.isCmdSuccess,normalize_cmd(node.command))
                    prev=(ok and res==true); node.last_success=prev; node.last_run=util.timestamp()
                    if node.kind=="impulse" and prev then break end
                end
                changed=true
            else
                local prev=true
                for _,node in ipairs(v.nodes) do
                    if node.conditional and prev~=true then break end
                    local ok,res=pcall(game.isCmdSuccess,normalize_cmd(node.command)); prev=(ok and res==true); node.last_success=prev; node.last_run=util.timestamp()
                    if node.kind=="impulse" then v.enabled=false; changed=true; break end
                end
            end
        end
    end
    if changed then cmd_container_save(d) end
end

-- ---------- 公会系统：独立目录 + 创建向导 + 领地/活跃/资金/任务/外交 ----------
GUILD_DIR = game.dataDir().."/guild"
GUILD_FILE = GUILD_DIR.."/guilds.json"
GUILD_PLAYER_FILE = GUILD_DIR.."/players.json"
GUILD_LOG_FILE = GUILD_DIR.."/logs.json"
GUILD_VOTE_FILE = GUILD_DIR.."/votes.json"
GUILD_TASK_FILE = GUILD_DIR.."/tasks.json"
GUILD_DIPLOMACY_FILE = GUILD_DIR.."/diplomacy.json"
GUILD_NOTICE_FILE = GUILD_DIR.."/notices.json"
GUILD_ACTIVITY_FILE = GUILD_DIR.."/activity.json"
GUILD_VERSION_FILE = GUILD_DIR.."/VERSION.txt"
function guild_load(path,def) local ok,d=pcall(util.json_load,path); if ok and type(d)=="table" then return d end return def end
function guild_save(path,d) pcall(util.json_write,path,d or {}) end
function guild_init_files()
    local d=guild_load(GUILD_FILE,{next_id=1,items={}}); d.items=d.items or {}; d.next_id=tonumber(d.next_id) or 1; guild_save(GUILD_FILE,d)
    for p,def in pairs({[GUILD_PLAYER_FILE]={players={}},[GUILD_LOG_FILE]={logs={}},[GUILD_VOTE_FILE]={votes={}},[GUILD_TASK_FILE]={guilds={}},[GUILD_DIPLOMACY_FILE]={relations={}},[GUILD_NOTICE_FILE]={guilds={}},[GUILD_ACTIVITY_FILE]={players={}}}) do local x=guild_load(p,def); guild_save(p,x) end
    pcall(util.write_file,GUILD_VERSION_FILE,PATCH_VERSION.."\n")
end
function guild_log(gid,typ,actor,detail)
    local d=guild_load(GUILD_LOG_FILE,{logs={}}); d.logs=d.logs or {}; d.logs[#d.logs+1]={at=util.timestamp(),guild_id=tostring(gid or ""),type=typ,actor=actor,detail=detail}; while #d.logs>5000 do table.remove(d.logs,1) end; guild_save(GUILD_LOG_FILE,d)
end
function guild_player_map() local d=guild_load(GUILD_PLAYER_FILE,{players={}}); d.players=d.players or {}; return d end
function guild_find_player(name)
    local d=guild_player_map(); local k=uuid_key(name); local gid=d.players[k]; if gid then local gd=guild_load(GUILD_FILE,{items={}}); local g=gd.items and gd.items[tostring(gid)]; if g and g.status~="dissolved" then return g end end
    local gd=guild_load(GUILD_FILE,{items={}})
    for _,g in pairs(gd.items or {}) do for _,m in pairs(g.members or {}) do if tostring(m.uuid or "")==k then return g end end end
    return nil
end
function guild_member_role(g,name)
    local u=uuid_key(name); for _,m in pairs(g.members or {}) do if tostring(m.uuid)==u then return tostring(m.role or "member") end end; return nil
end
function guild_online_count(g)
    local n=0; local on=online_players() or {}; local seen={}; for _,p in ipairs(on) do seen[uuid_key(p)]=true end
    for _,m in pairs(g.members or {}) do if seen[tostring(m.uuid)] then n=n+1 end end return n
end
function guild_level_title(lv)
    local a={"初启","新芽","成长","兴盛","璀璨","荣耀","圣辉","至尊","永恒","传奇"}; return a[math.max(1,math.min(10,tonumber(lv) or 1))] or "传奇"
end
function guild_max_members(lv) return math.min(50,10+math.max(0,(tonumber(lv) or 1)-1)*5) end
function guild_exp_need(lv) return 500*math.max(1,tonumber(lv) or 1) end
function guild_theme(code) local a={["冰霜"]="§b",["梦幻"]="§d",["黄金"]="§6",["暗影"]="§5",["自然"]="§a",["烈焰"]="§c",["深海"]="§3",["圣洁"]="§f"}; return a[tostring(code)] or "§b" end
function guild_create_menu(name)
    local d,r=player_record(name,true); set_menu(d,r,"guild_first"); local g=guild_find_player(name)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§d✦ §l公 会 殿 堂 §d✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    if g then lines[#lines+1]="§f你当前属于：§e"..tostring(g.name) end
    lines[#lines+1]="§f① 创建公会"; lines[#lines+1]="§f② 公会列表"; lines[#lines+1]="§f③ 搜索公会"; lines[#lines+1]="§f④ 搜索玩家"; lines[#lines+1]="§f⑤ 接受邀请码"; lines[#lines+1]="§f⑥ 我的申请"; lines[#lines+1]="§f⑦ 公会排行"; lines[#lines+1]="§f⑧ 活跃度排行"; send(name,table.concat(lines,"\n")); return true
end
function guild_main(name)
    local g=guild_find_player(name)
    if not g then return guild_create_menu(name) end
    local d,r=player_record(name,true); set_menu(d,r,"guild_main")
    local c=guild_theme(g.theme); local online=guild_online_count(g); local total=0; for _ in pairs(g.members or {}) do total=total+1 end
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━",""..c.."✦『"..tostring(g.name).."』✦§r","§7"..c.."◆ Lv."..tostring(g.level or 1).." · "..guild_level_title(g.level).."§r","§f会长：§e"..tostring(g.owner_name or "未知").."   §f成员：§b"..online.."/"..total,"§f贡献：§d"..tostring(g.total_contribution or 0).."   §f资金：§6"..tostring(g.funds or 0),"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§f① 公会信息  ② 成员列表  ③ 每日签到  ④ 公会任务","§f⑤ 公会排行  ⑥ 公会成就  ⑦ 公会公告  ⑧ 公会领地","§f⑨ 公会设施  ⑩ 公会外交  ⑪ 公会发展  ⑫ 公会管理"}
    send(name,table.concat(lines,"\n")); return true
end
function guild_create_abort(name,msg) local d,r=player_record(name,true); r.guild_create=nil; clear_menu(d,r); save_data(d); send(name,msg or "§e已取消公会创建。") end
function guild_creation_start(name)
    if guild_find_player(name) then send(name,"§c你已经加入公会，不能重复创建。"); return true end
    local board=scoreboard_name(); if not board then send(name,"§c服务器尚未设置金币计分板。"); return true end
    local ok,bal=pcall(game.getScore,board,name); bal=ok and tonumber(bal) or 0; if bal<3000 then send(name,"§c创建公会需要3000金币，你当前只有"..bal.."金币。"); return true end
    local d,r=player_record(name,true); r.guild_create={step="name",started_at=util.timestamp()}; set_menu(d,r,"guild_create_name"); send(name,"§d✦ 创建公会\n§f请输入你想创建的公会名称。\n§7创建费用：§e3000金币\n§7完成名称后再设置可选启动资金。\n§7.stop 取消")
    return true
end
function guild_create_finish(name)
    local d,r=player_record(name,true); local s=r.guild_create; if type(s)~="table" then return true end
    local board=scoreboard_name(); if not board then guild_create_abort(name,"§c金币计分板不存在，创建取消。"); return true end
    local ok,bal=pcall(game.getScore,board,name); bal=ok and tonumber(bal) or 0; local fee=3000; local startup=math.floor(tonumber(s.startup) or 0); local total=fee+startup
    if bal<total then send(name,"§c创建失败：当前金币不足以支付3000金币创建费和启动资金。"); return true end
    local safe=string.gsub(name,'"','\\"'); local rem_ok,rem_res=pcall(game.isCmdSuccess,'scoreboard players remove "'..safe..'" '..board..' '..total); if not rem_ok or rem_res~=true then guild_create_abort(name,"§c扣除创建费用失败，未创建公会。"); return true end
    local gd=guild_load(GUILD_FILE,{next_id=1,items={}}); local gid="G"..string.format("%04d",tonumber(gd.next_id) or 1); gd.next_id=(tonumber(gd.next_id) or 1)+1
    local g={id=gid,name=s.name,level=1,exp=0,title=guild_level_title(1),theme=s.theme or "冰霜",owner_uuid=uuid_key(name),owner_name=name,funds=startup,total_contribution=0,status="normal",created_at=util.timestamp(),members={{uuid=uuid_key(name),name=name,role="owner",joined_at=util.timestamp(),contribution=0,activity=0}},territory=s.territory,teleport_point=s.start_point,warehouse_point=nil,development="城建",notice="欢迎加入"}
    gd.items[gid]=g; guild_save(GUILD_FILE,gd)
    local pd=guild_player_map(); pd.players[uuid_key(name)]=gid; guild_save(GUILD_PLAYER_FILE,pd); guild_log(gid,"创建公会",name,"名称="..s.name.." 启动资金="..startup)
    r.guild_create=nil; clear_menu(d,r); save_data(d); send(name,"§a✦ 公会创建成功！\n§f公会：§e"..s.name.."\n§f称号：§dLv.1 · "..guild_level_title(1).."\n§f公会ID：§b"..gid.."\n§f公会资金：§6"..startup.."\n§7已自动设置公会传送点。"); guild_main(name); return true
end
function guild_overlap_with_existing(candidate)
    local db=territory_db(); for _,t in pairs(db.items or {}) do if type(t)=="table" and not t.deleted and territory_overlap(candidate,t) then return true,"普通领地 #"..tostring(t.id).."" end end
    local gd=guild_load(GUILD_FILE,{items={}}); for _,g in pairs(gd.items or {}) do local t=g.territory; if g.status~="dissolved" and type(t)=="table" and territory_overlap(candidate,t) then return true,"公会「"..tostring(g.name).."」" end end
    return false,nil
end
function guild_update_territory_index(g)
    local td=territory_db(); td.guild_index=td.guild_index or {}; td.guild_index[tostring(g.id)]={x1=g.territory.x1,x2=g.territory.x2,z1=g.territory.z1,z2=g.territory.z2,dimension=g.territory.dimension}; territory_save(td)
end
function guild_protect_tick()
    local gd=guild_load(GUILD_FILE,{items={}}); local names=online_players() or {}; local now=util.timestamp(); local pos_cache={}
    for _,name in ipairs(names) do local p=player_position(name,false); if p then pos_cache[name]=p end end
    for _,g in pairs(gd.items or {}) do
        if g.status~="dissolved" and type(g.territory)=="table" then
            for _,name in ipairs(names) do
                local pos=pos_cache[name]
                if pos and territory_inside(g.territory,pos) and dim_exec(g.territory.dimension)==dim_exec(pos.dimension) and guild_member_role(g,name)==nil then
                    local x1,x2=math.min(g.territory.x1,g.territory.x2),math.max(g.territory.x1,g.territory.x2)
                    local z1,z2=math.min(g.territory.z1,g.territory.z2),math.max(g.territory.z1,g.territory.z2)
                    local escape=RUNTIME.last_pos[name] and not territory_inside(g.territory,RUNTIME.last_pos[name]) and RUNTIME.last_pos[name] or nil
                    if not escape then
                        escape={x=x1-2,y=pos.y,z=math.min(math.max(pos.z,z1),z2),dimension=pos.dimension}
                        if pos.x-x1 > math.abs(pos.z-z1) and pos.x-x2 < 0 then escape.x=x2+2 end
                    end
                    local safe=string.gsub(name,'"','\\"')
                    local cmd=string.format('execute as @a[name="%s"] in %s run tp @s %.2f %.2f %.2f',safe,dim_exec(escape.dimension),tonumber(escape.x),tonumber(escape.y),tonumber(escape.z))
                    pcall(game.isCmdSuccess,cmd)
                    guild_log(g.id,"领地保护传送",name,"非成员进入公会领地")
                    send(name,"§c你不是「"..tostring(g.name).."」公会成员，已按领地保护规则传送离开。")
                end
            end
        end
    end
end
function guild_activity_tick()
    local now=util.timestamp(); local gm=guild_load(GUILD_FILE,{items={}}); local pd=guild_player_map(); pd.players=pd.players or {}
    for _,name in ipairs(online_players() or {}) do
        local g=guild_find_player(name); if g then
            local uuid=uuid_key(name); for _,m in ipairs(g.members or {}) do if tostring(m.uuid)==uuid then m.online_seconds=(tonumber(m.online_seconds) or 0)+60; m.activity=(tonumber(m.activity) or 0)+60; break end end
        end
    end
    for _,g in pairs(gm.items or {}) do
        if g.status~="dissolved" then
            local count=0; for _,m in pairs(g.members or {}) do count=count+tonumber(m.online_seconds or 0) end
            g.activity=math.floor(count/60); g.total_contribution=0; for _,m in pairs(g.members or {}) do g.total_contribution=g.total_contribution+(tonumber(m.contribution) or 0) end
        end
    end
    guild_save(GUILD_FILE,gm); guild_save(GUILD_PLAYER_FILE,pd); guild_save(GUILD_ACTIVITY_FILE,{updated_at=now})
end
function guild_signin(name)
    local g=guild_find_player(name); if not g then send(name,"§c你尚未加入公会。"); return true end
    g.signins=g.signins or {}; local uid=uuid_key(name); local today=os.date("%Y-%m-%d",util.timestamp()+8*3600); if g.signins[uid]==today then send(name,"§e你今天已经完成公会签到。"); return true end
    g.signins[uid]=today
    for _,m in pairs(g.members or {}) do if tostring(m.uuid)==uid then m.contribution=(tonumber(m.contribution) or 0)+20; break end end
    g.exp=(tonumber(g.exp) or 0)+10; guild_log(g.id,"公会签到",name,"贡献+20 经验+10"); local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    local reward_index=choose_signin_reward and choose_signin_reward() or 1; local rewards={{id="bread",count=6},{id="torch",count=12},{id="iron_ingot",count=3},{id="cooked_beef",count=5},{id="experience_bottle",count=2},{id="golden_carrot",count=2}}; local rw=rewards[math.max(1,math.min(#rewards,tonumber(reward_index) or 1))]
    local item=rw.id; if not item:find(":") then item="minecraft:"..item end; pcall(game.sendCommand,'give "'..string.gsub(name,'"','\\"')..'" '..item..' '..rw.count)
    send(name,"§a✦ 公会签到成功！\n§f今日奖励：§d"..rw.id.." ×"..rw.count.."\n§f个人贡献：§e+20\n§f公会经验：§b+10")
    return true
end
function guild_info(name)
    local g=guild_find_player(name); if not g then send(name,"§c你尚未加入公会。"); return true end
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§d✦『"..g.name.."』§r","§7Lv."..g.level.." · "..guild_level_title(g.level),"§f会长：§e"..g.owner_name,"§f成员：§b"..guild_online_count(g).."/"..#(g.members or {}),"§f资金：§6"..g.funds,"§f总贡献：§d"..g.total_contribution,"§f活跃度：§a"..(g.activity or 0),"§f发展路线：§b"..(g.development or "城建"),"§f公告：§e"..(g.notice or "暂无"),"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§7领地坐标、传送点和仓库坐标不会对普通成员显示。"}; send(name,table.concat(lines,"\n")); return true
end
function guild_list(name)
    local gd=guild_load(GUILD_FILE,{items={}}); local arr={}; for _,g in pairs(gd.items or {}) do if g.status~="dissolved" then arr[#arr+1]=g end end; table.sort(arr,function(a,b) return tostring(a.name)<tostring(b.name) end)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§b✦ 公会列表 §b✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}; for i=1,math.min(12,#arr) do local g=arr[i]; lines[#lines+1]=string.format("§f%d. §e%s §7Lv.%s §8| §b%s/%s §8| §d%s",i,g.name,g.level,guild_online_count(g),#(g.members or {}),guild_level_title(g.level)) end; if #arr==0 then lines[#lines+1]="§7暂无公会。" end; local d,r=player_record(name,true); set_menu(d,r,"guild_list",{guild_list=arr}); send(name,table.concat(lines,"\n")); return true
end
function guild_search_player(name,q)
    q=lower(trim(q or "")); local gd=guild_load(GUILD_FILE,{items={}}); local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§e✦ 玩家所属公会搜索 §e✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}; local count=0
    for _,g in pairs(gd.items or {}) do if g.status~="dissolved" then for _,m in pairs(g.members or {}) do if lower(tostring(m.name or "")):find(q,1,true) then count=count+1; lines[#lines+1]="§f"..m.name.." §8▸ §d"..g.name.." §7（"..tostring(m.role).."）" end end end end
    if count==0 then lines[#lines+1]="§7没有找到匹配玩家。" end; send(name,table.concat(lines,"\n")); return true
end
function guild_announcement(name)
    local g=guild_find_player(name); if not g then guild_list(name); return true end; local nd=guild_load(GUILD_NOTICE_FILE,{guilds={}}); local arr=nd.guilds[g.id] or {}; local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§e✦『"..g.name.."』公告栏 §e✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}; if #arr==0 then lines[#lines+1]="§7暂无公告。" else for i=math.max(1,#arr-9),#arr do local n=arr[i]; lines[#lines+1]="§f"..patch_beijing_fmt(n.at).." §8| §e"..n.by.."§7："..n.text end end; send(name,table.concat(lines,"\n")); return true
end
function guild_post_notice(name,text)
    local g=guild_find_player(name); if not g then return false end; local role=guild_member_role(g,name); if role~="owner" and role~="vice" and not is_admin(name) then send(name,"§c没有公告管理权限。"); return true end; local nd=guild_load(GUILD_NOTICE_FILE,{guilds={}}); nd.guilds[g.id]=nd.guilds[g.id] or {}; table.insert(nd.guilds[g.id],{at=util.timestamp(),by=name,text=tostring(text)}); while #nd.guilds[g.id]>30 do table.remove(nd.guilds[g.id],1) end; guild_save(GUILD_NOTICE_FILE,nd); guild_log(g.id,"发布公告",name,text); guild_announcement(name); return true
end
function guild_manage(name)
    local g=guild_find_player(name); if not g then return guild_create_menu(name) end; local role=guild_member_role(g,name); if role~="owner" and role~="vice" and not is_admin(name) then send(name,"§c普通成员没有公会管理权限。"); return true end
    local d,r=player_record(name,true); set_menu(d,r,"guild_manage"); send(name,"§8§m━━━━━━━━━━━━━━━━━━━━━━━━\n§c✦ 公会管理 §c✦\n§8§m━━━━━━━━━━━━━━━━━━━━━━━━\n§f① 设置公会传送点\n§f② 设置仓库传送点\n§f③ 发布公告\n§f④ 删除/更换公会领地\n§f⑤ 解散公会\n§f⑥ 外交关系\n§f⑦ 发展路线\n§f⑧ 管理投票"); return true
end
function guild_vote_start(name,subject,kind)
    local g=guild_find_player(name); if not g then return false end; local role=guild_member_role(g,name); if role~="owner" and role~="vice" and not is_admin(name) then send(name,"§c只有会长/副会长可以发起重大决策投票。"); return true end
    local vd=guild_load(GUILD_VOTE_FILE,{votes={}}); local id=tostring(#(vd.votes or {})+1); local v={id=id,guild_id=g.id,subject=subject,kind=kind,started_at=util.timestamp(),expire_at=util.timestamp()+300,yes={},no={},status="open"}; vd.votes[id]=v; guild_save(GUILD_VOTE_FILE,vd); guild_log(g.id,"发起投票",name,subject); send(name,"§a投票已发起："..subject.."\n§7管理层成员输入 1 支持、0 反对，5分钟截止。"); return true
end
function guild_vote_cast(name,vote,value)
    local vd=guild_load(GUILD_VOTE_FILE,{votes={}}); local v=vd.votes[tostring(vote)]; if not v or v.status~="open" or util.timestamp()>tonumber(v.expire_at) then send(name,"§c投票不存在或已结束。"); return true end; local g=guild_load(GUILD_FILE,{items={}}).items[v.guild_id]; if not g then return true end; local role=guild_member_role(g,name); if role~="owner" and role~="vice" then send(name,"§c只有会长/副会长可以投票。"); return true end; local u=uuid_key(name); v.yes[u]=nil; v.no[u]=nil; if value=="1" then v.yes[u]=true else v.no[u]=true end; guild_save(GUILD_VOTE_FILE,vd); send(name,"§a✓ 已记录你的投票。"); return true
end
function guild_dissolve(name)
    local gd=guild_load(GUILD_FILE,{items={}}); local g=guild_find_player(name); if not g then send(name,"§c公会不存在。"); return true end; local role=guild_member_role(g,name); if role~="owner" and not is_admin(name) then return guild_vote_start(name,"解散公会「"..g.name.."」","dissolve") end
    g.status="dissolved"; g.dissolved_at=util.timestamp(); local pd=guild_player_map(); for _,m in pairs(g.members or {}) do pd.players[tostring(m.uuid)]=nil end; guild_save(GUILD_PLAYER_FILE,pd); gd.items[g.id]=g; guild_save(GUILD_FILE,gd); guild_log(g.id,"解散公会",name,"管理员="..tostring(is_admin(name))); send(name,"§e公会已解散，原领地保护与传送点已停用。历史数据保留。"); return true
end
function guild_facility_set(name,kind)
    local g=guild_find_player(name); if not g then return true end; local role=guild_member_role(g,name); if role~="owner" and role~="vice" and not is_admin(name) then send(name,"§c只有会长/副会长可以设置公会设施。"); return true end
    local pos=player_position(name); if not pos then send(name,"§c无法读取当前位置。"); return true end; if not territory_inside(g.territory,pos) or dim_exec(g.territory.dimension)~=dim_exec(pos.dimension) then send(name,"§c设施位置必须位于本公会领地内部。"); return true end
    local obj={x=math.floor(pos.x),y=math.floor(pos.y),z=math.floor(pos.z),dimension=pos.dimension,at=util.timestamp(),by=name}; if kind=="tp" then g.teleport_point=obj else g.warehouse_point=obj end
    local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd); guild_log(g.id,"设置设施",name,kind); send(name,kind=="tp" and "§a公会传送点已设置。" or "§a公会仓库传送点已设置。"); return true
end
function guild_teleport(name,kind)
    local g=guild_find_player(name); if not g then send(name,"§c你尚未加入公会。"); return true end
    local p=(kind=="tp") and g.teleport_point or g.warehouse_point; if type(p)~="table" then send(name,"§e该公会尚未设置"..(kind=="tp" and "公会传送点" or "公会仓库点").."。"); return true end
    local safe=string.gsub(name,'"','\\"'); local cmd=string.format('execute as @a[name="%s"] in %s run tp @s %.2f %.2f %.2f',safe,dim_exec(p.dimension),p.x,p.y,p.z); local ok,res=pcall(game.isCmdSuccess,cmd); if ok and res==true then send(name,"§a✓ 已传送到"..(kind=="tp" and "公会区域" or "公会仓库").."。") else send(name,"§c传送失败，请检查设置的设施是否仍在本公会领地内。") end; return true
end
function guild_commands_menu(name)
    local g=guild_find_player(name); if not g then return guild_create_menu(name) end; guild_main(name); return true
end
function guild_handle_menu(name,msg)
    local d,r=player_record(name,true); local mode=r.menu; if not tostring(mode):find("^guild_") then return false end; local m=trim(msg or "")
    if m==".stop" or lower(m)=="stop" then clear_menu(d,r); save_data(d); send(name,"§e已退出公会操作。"); return true end
    if mode=="guild_first" then local n=tonumber(m); if n==1 then return guild_creation_start(name) elseif n==2 then return guild_list(name) elseif n==3 then set_menu(d,r,"guild_search_name"); send(name,"§e请输入公会名称关键词："); return true elseif n==4 then set_menu(d,r,"guild_search_player"); send(name,"§e请输入玩家名称关键词："); return true elseif n==5 then set_menu(d,r,"guild_invite_accept"); send(name,"§e请输入邀请码："); return true elseif n==6 then send(name,"§7当前基础版没有待处理申请。后续可接入完整申请列表。"); return true elseif n==7 then coin_leaderboard(name); return true elseif n==8 then coin_leaderboard(name); return true end; send(name,"§c请输入1~8。"); return true end
    if mode=="guild_create_name" then if #m<2 or #m>16 then send(name,"§c公会名称建议2~16字符。"); return true end; local gd=guild_load(GUILD_FILE,{items={}}); for _,g in pairs(gd.items or {}) do if g.status~="dissolved" and tostring(g.name)==m then send(name,"§c这个公会名称已经存在。"); return true end end; r.guild_create.name=m; r.guild_create.startup=0; r.guild_create.start_point=nil; set_menu(d,r,"guild_create_startup"); send(name,"§e是否投入启动资金？\n§f直接输入 0 表示不投入。\n§f输入正整数表示投入启动资金。\n§7启动资金将进入公会资金池。"); return true end
    if mode=="guild_create_startup" then local n=tonumber(m); if not n or n<0 or n%1~=0 then send(name,"§c请输入0或正整数。"); return true end; r.guild_create.startup=math.floor(n); set_menu(d,r,"guild_create_theme"); send(name,"§e选择公会主题颜色：\n§f1 冰霜  2 梦幻  3 黄金  4 暗影\n§f5 自然  6 烈焰  7 深海  8 圣洁"); return true end
    if mode=="guild_create_theme" then local map={ ["1"]="冰霜",["2"]="梦幻",["3"]="黄金",["4"]="暗影",["5"]="自然",["6"]="烈焰",["7"]="深海",["8"]="圣洁"}; if not map[m] then send(name,"§c请输入1~8。"); return true end; r.guild_create.theme=map[m]; set_menu(d,r,"guild_create_start_confirm"); send(name,"§d✦ 创建公会领地\n§f请先站到你希望作为§e起始坐标§f的位置。\n§f输入 §a1 §f确定，输入 §c0 §f取消。\n§7不会把坐标直接发到聊天框。"); return true end
    if mode=="guild_create_start_confirm" then if m=="0" then guild_create_abort(name,"§e已取消创建公会。"); return true end; if m~="1" then send(name,"§c请输入1或0。"); return true end; local p=player_position(name); if not p then send(name,"§c无法读取当前位置。"); return true end; r.guild_create.start_point={x=math.floor(p.x),y=math.floor(p.y),z=math.floor(p.z),dimension=p.dimension}; r.guild_create.step="end"; r.guild_create.end_deadline=util.timestamp()+180; set_menu(d,r,"guild_create_end_confirm"); save_data(d); send(name,"§a起始位置已确认。\n§e请在3分钟内前往终止坐标位置。\n§f输入1确定；输入0续3分钟；§f.stop取消。"); return true end
    if mode=="guild_create_end_confirm" then if m==".stop" then guild_create_abort(name,"§e已取消公会创建。"); return true end; local s=r.guild_create; if util.timestamp()>(tonumber(s.end_deadline) or 0) then if m=="0" then s.end_deadline=util.timestamp()+180; save_data(d); send(name,"§e已续3分钟，请继续前往终止位置。"); return true else guild_create_abort(name,"§c终止坐标阶段已超时，公会创建已取消。"); return true end end; if m=="0" then s.end_deadline=util.timestamp()+180; save_data(d); send(name,"§e已续3分钟。"); return true end; if m~="1" then send(name,"§c请输入1确定、0续时间。"); return true end; local p=player_position(name); if not p then send(name,"§c无法读取当前位置。"); return true end; local st=s.start_point; local en={x=math.floor(p.x),y=math.floor(p.y),z=math.floor(p.z),dimension=p.dimension}; if dim_exec(en.dimension)~=dim_exec(st.dimension) then send(name,"§c起始和终止坐标必须在同一维度。"); return true end; local candidate={x1=st.x,z1=st.z,x2=en.x,z2=en.z,dimension=st.dimension}; local w=math.abs(candidate.x2-candidate.x1)+1; local l=math.abs(candidate.z2-candidate.z1)+1; if w>128 or l>128 then send(name,"§c公会领地最大128×128；当前约为"..w.."×"..l.."。"); return true end; local hit,who=guild_overlap_with_existing(candidate); if hit then send(name,"§c创建失败：该区域与"..who.."重叠。"); return true end; s.territory={x1=candidate.x1,z1=candidate.z1,x2=candidate.x2,z2=candidate.z2,dimension=candidate.dimension}; return guild_create_finish(name) end
    if mode=="guild_main" then local n=tonumber(m); if n==1 then return guild_info(name) elseif n==2 then local g=guild_find_player(name); local lines={"§b✦ 公会成员 ✦"}; for i,m0 in ipairs(g.members or {}) do lines[#lines+1]=string.format("§f%d. %s §7[%s] §8| 贡献%s",i,m0.name,m0.role,m0.contribution or 0) end; send(name,table.concat(lines,"\n")); return true elseif n==3 then return guild_signin(name) elseif n==4 then send(name,"§b✦ 公会任务 ✦\n§7每日：成员签到、累计在线、活跃参与\n§7奖励：个人贡献、公会经验、公会资金\n§e任务模板基础版已启用。"); return true elseif n==5 then coin_leaderboard(name); return true elseif n==6 then send(name,"§d✦ 公会成就 ✦\n§7初建公会、成员达到10人、累计签到100次、累计在线100小时、公会达到Lv.5、完成100任务。"); return true elseif n==7 then return guild_announcement(name) elseif n==8 then local g=guild_find_player(name); send(name,"§b公会领地：§a已建立\n§7坐标对成员隐藏。\n§f.传送公会 / .传送工会"); return true elseif n==9 then send(name,"§b公会设施：\n§f.传送公会\n§f.传送工会仓库\n§7设置位置：会长/副会长，且必须位于本公会领地内。"); return true elseif n==10 then send(name,"§5✦ 外交 ✦\n§7中立 / 友好 / 同盟 / 敌对\n§7正式关系需要双方确认。"); return true elseif n==11 then send(name,"§6✦ 公会发展 ✦\n§f城建：领地/仓库/设施\n§f商业：资金/任务经济\n§f冒险：高级任务/活动\n§f荣耀：称号/排行/成就"); return true elseif n==12 then return guild_manage(name) end; send(name,"§c请输入1~12。"); return true end
    if mode=="guild_create_start_confirm" then return true end
    if mode=="guild_manage" then local n=tonumber(m); if n==1 then return guild_facility_set(name,"tp") elseif n==2 then return guild_facility_set(name,"warehouse") elseif n==3 then set_menu(d,r,"guild_notice_input"); send(name,"§e请输入公告内容："); return true elseif n==4 then guild_vote_start(name,"更换公会领地","relocate"); return true elseif n==5 then return guild_dissolve(name) elseif n==6 then send(name,"§5外交系统已开放关系展示；正式同盟/敌对需双方确认。"); return true elseif n==7 then send(name,"§6当前路线：城建。\n§7可发展的路线：城建 / 商业 / 冒险 / 荣耀。"); return true elseif n==8 then send(name,"§e当前基础版投票：输入 .公会投票 1 支持 / 0 反对（有进行中的投票时）。"); return true end; send(name,"§c请输入1~8。"); return true end
    if mode=="guild_notice_input" then return guild_post_notice(name,m) end
    if mode=="guild_search_player" then return guild_search_player(name,m) end
    if mode=="guild_search_name" then local gd=guild_load(GUILD_FILE,{items={}}); local lines={"§b✦ 公会搜索 ✦"}; local q=lower(m); local n=0; for _,g in pairs(gd.items or {}) do if g.status~="dissolved" and lower(tostring(g.name)):find(q,1,true) then n=n+1; lines[#lines+1]=g.name.." §7Lv."..g.level.." §8| 在线"..guild_online_count(g).."/"..#(g.members or {}) end end; if n==0 then lines[#lines+1]="§7没有找到匹配公会。" end; send(name,table.concat(lines,"\n")); return true end
    if mode=="guild_invite_accept" then send(name,"§e邀请码基础入口已接通。邀请码加入将在后续数据同步时完整开放。"); clear_menu(d,r); return true end
    return false
end

-- ---------- .help：16格主菜单 + 直接打开 ----------
function show_help(name)
    local d,r=player_record(name,true); r.menu="help"; r.menu_expires=util.timestamp()+MENU_TIMEOUT; save_data(d)
    send(name,table.concat({
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
        "§b§l      ✦ 功 能 主 菜 单 ✦",
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
        "§b01§r 基础功能    §b02§r 传送中心    §b03§r 领地系统    §b04§r 玩家信息",
        "§b05§r 经济系统    §b06§r 系统商店    §b07§r 玩家市场    §b08§r 兑换中心",
        "§b09§r AI智能      §b10§r 每日活动    §b11§r 任务中心    §b12§r 娱乐玩法",
