-- ---------- 新增菜单帮助直接分发 ----------
function patch_help_open(name,n)
    n=tonumber(n)
    if not n then show_help(name); return true end
    local d,r=player_record(name,true); clear_menu(d,r); save_data(d)
    if n==1 then slot_menu(name,"save_slot")
    elseif n==2 then slot_menu(name,"return_slot")
    elseif n==3 then set_menu(d,r,"death_dir"); death_show_list(name)
    elseif n==4 then slot_menu(name,"delete_slot")
    elseif n==5 then show_tpa_targets(name)
    elseif n==6 then show_transfer_targets(name)
    elseif n==7 then show_report_targets(name)
    elseif n==8 then local rr=player_record(name,true); local st=coordinate_tp_state(rr); if is_admin(name) or st.available or (tonumber(st.extra_uses) or 0)>0 then local dd,dr=player_record(name,true); set_menu(dd,dr,"coord_tp_input"); send(name,"§b━━ 选择坐标传送 ━━\n§f请输入：维度 X Y Z") else send(name,"§c你当前没有坐标传送次数。") end
    elseif n==9 then start_soul(name)
    elseif n==10 then show_ban_menu(name)
    elseif n==11 then show_unban_menu(name)
    elseif n==12 then show_player_market_main(name)
    elseif n==13 then show_territory(name)
    elseif n==14 then show_market_14(name)
    elseif n==15 then guild_commands_menu(name)
    elseif n==16 then show_gameplay_categories(name)
    else show_help(name) end
    return true
end

-- ---------- 定时更新：每分钟一次公告 + 公会活跃 + 轻量命令容器 ----------
local _patch_prev_v17 = v17_event_tick
PATCH_LAST_MINUTE = tonumber(PATCH_LAST_MINUTE) or 0
function v17_event_tick()
    local result=true
    if type(_patch_prev_v17)=="function" then local ok,r=pcall(_patch_prev_v17); if ok then result=r end end
    local now=util.timestamp()
    if now-PATCH_LAST_MINUTE>=60 then
        PATCH_LAST_MINUTE=now
        pcall(guild_activity_tick)
        pcall(guild_protect_tick)
        pcall(patch_sidebar_update)
    end
    if now%CMD_CONTAINER_TICK==0 then pcall(cmd_container_tick) end
    return result
end

-- ---------- 最终聊天入口补丁 ----------
local _patch_prev_on_chat = on_chat
function on_chat(playerName,msg)
    local raw=tostring(msg or "")
    local low=lower(trim(raw))

    -- 纯命令入口
    if low==".公会" or low=="公会" or low==".工会" or low=="工会" then return guild_commands_menu(playerName) end
    if low==".传送公会" or low=="传送公会" or low==".传送工会" or low=="传送工会" then return guild_teleport(playerName,"tp") end
    if low==".传送公会仓库" or low=="传送公会仓库" or low==".传送工会仓库" or low=="传送工会仓库" then return guild_teleport(playerName,"warehouse") end
    if low==".公会签到" or low=="公会签到" then return guild_signin(playerName) end
    if low==".公会公告" or low=="公会公告" then return guild_announcement(playerName) end
    local notice=raw:match("^%.公会公告%s+(.+)$")
    if notice then return guild_post_notice(playerName,trim(notice)) end
    local gsearch=raw:match("^%.公会搜索玩家%s+(.+)$")
    if gsearch then return guild_search_player(playerName,gsearch) end
    local ghelp=raw:match("^%.help%s+(%d+)%s*$")
    if ghelp then return patch_help_open(playerName,tonumber(ghelp)) end
    if low==".help" then show_help(playerName); return true end
    local glb=raw:match("^%.金币排行%s*(%d*)$") or raw:match("^%.金币排行榜%s*(%d*)$")
    if glb then return coin_leaderboard(playerName,tonumber(glb) or 10) end
    local grp=raw:match("^%.群号%s+(%d+)%s*(%d*)$")
    if grp then local n,days=raw:match("^%.群号%s+(%d+)%s*(%d*)$"); return patch_server_number_set(playerName,n,tonumber(days) or 30) end
    if low==".公告栏刷新" then if not is_admin(playerName) then send(playerName,"§c只有管理员可以刷新公告栏。"); return true end; patch_sidebar_update(); send(playerName,"§a公告栏已刷新。"); return true end
    if low==".命令容器" or low==".命令方块容器" then return cmd_container_show(playerName) end
    if low==".性能" or low==".tps" then local tps,src=patch_try_tps(); send(playerName,"§b━━ 服务器性能 ━━\n§fTPS：§e"..(tps and string.format("%.1f",tps) or "API不可用").."\n§f来源：§7"..src.."\n§f插件公告栏：§a每60秒刷新一次"); return true end
    -- 市场出售流程的菜单输入覆盖：修正“脚下一格木桶”而不传送机器人。
    local d,r=player_record(playerName,true); if r and r.menu=="market_sell_name" then local nm=trim(raw); if nm=="" then send(playerName,"§c名称不能为空。"); return true end; if #nm>80 then send(playerName,"§c名称太长。"); return true end; return patch_market_start_from_name(playerName,nm,d,r) end
    if r and r.menu and tostring(r.menu):find("^guild_") then
        local handled=guild_handle_menu(playerName,raw); if handled then return true end
    end
    return _patch_prev_on_chat(playerName,msg)
end

