PATCH_BUILD_TAG = "主体修复版-2026-09-26-R2"

-- ---------- AI TXT：每次执行都重新从真实文件源解析，避免“第一次连上、后续找不到” ----------
function patch_prompt_source_candidates(id)
    local out,seen={},{}
    local function add(path)
        path=tostring(path or "")
        if path~="" and not seen[path] then seen[path]=true; out[#out+1]=path end
    end
    local fn="seg_"..tostring(id)..".txt"
    local ok,dd=pcall(game.dataDir)
    if ok and type(dd)=="string" and dd~="" then
        add(dd.."/"..fn)
        add(dd.."/ai_prompts/"..fn)
    end
    local ok2,cd=pcall(plugin_code_dir)
    if ok2 and type(cd)=="string" and cd~="" then
        add(cd.."/"..fn)
        add(cd.."/ai_prompts/"..fn)
    end
    local ok3,base=pcall(plugin_base_dir)
    local pid=""
    pcall(function() pid=tostring(plugin_id_now() or "") end)
    if ok3 and type(base)=="string" and base~="" and pid~="" then
        add(base.."/插件文件/"..pid.."/"..fn)
        add(base.."/插件文件/"..pid.."/ai_prompts/"..fn)
    end
    return out
end

function ai_seg_load(name, force)
    local id=ai_seg_canonical(name)
    if id=="" then return "" end
    if (not force) and _AI_SEG_CACHE[id]~=nil and trim(tostring(_AI_SEG_CACHE[id]))~="" then return _AI_SEG_CACHE[id] end
    local txt=""
    for _,path in ipairs(patch_prompt_source_candidates(id)) do
        local ok,v=pcall(util.read_file,path)
        if ok and type(v)=="string" and trim(v)~="" then txt=v; break end
    end
    if trim(txt)=="" then txt=AI_PROMPT_BUILTIN[id] or "" end
    _AI_SEG_CACHE[id]=txt
    return txt
end

function build_ai_system(q,admin)
    local core=ai_seg_load("core",true)
    if trim(core)=="" then return "【严重错误】AI 核心 TXT 不存在。",{"core"} end
    local extra="\n\n【多功能插件｜工具调用原则】\n"..
        "1. 简单聊天直接回答，不为了证明能力而调用工具。\n"..
        "2. 日志不是默认工具。只有用户明确要求查日志、聊天记录、发言、报错或历史记录时才调用。\n"..
        "3. 需要查聊天记录时，优先使用持久化 chat_logs.json；它保存收到的普通玩家与管理员原始聊天消息。\n"..
        "4. 在线玩家、背包、位置、分数等查询优先读取实时接口；接口失败必须说读取失败，不能把失败说成空。\n"..
        "5. 任何执行结果都必须以真实返回为准，不得把‘准备执行’说成‘已经执行’。\n"..
        "6. 使用工具时遵循最小必要原则：只调用当前问题真正需要的工具。"
    return "【多功能插件｜常驻核心提示词】\n"..core..extra,{"core"}
end

-- ---------- 市场：严格验证“玩家脚下一格” ----------
function patch_market_start_from_name(name,nm,d,r)
    local pos=player_position(name)
    if not pos then send(name,"§c无法读取当前位置。请重新尝试。"); return true end
    local bx,by,bz=math.floor(pos.x),math.floor(pos.y),math.floor(pos.z)
    local safe=string.gsub(name,'"','\\"')
    local cmd=string.format('execute as @a[name="%s"] at @s run setblock ~ ~-1 ~ barrel',safe)
    local ok,res=pcall(game.isCmdSuccess,cmd)
    if not ok or res~=true then send(name,"§c无法在你脚下一格放置木桶。请确保该位置可以放置木桶。"); return true end
    local id=tonumber((market_db().next_id or 1))
    d.market_sessions=d.market_sessions or {}
    d.market_sessions[name]={id=id,name=nm,price=r.market_session_price,barrel_pos={x=bx,y=by,z=bz},created_at=util.timestamp(),barrel_y=by-1}
    set_menu(d,r,"market_sell_wait",{})
    save_data(d)
    send(name,"§a木桶已放置在你脚下一格。请把商品放入木桶。\n§e完成后输入：确定商品\n§70取消，.stop退出。\n§7有效期3分钟。")
    return true
end

function market_finish_sell(name)
    local d,r=player_record(name,true)
    local s=d.market_sessions and d.market_sessions[name]
    if not s then r.market_sell_preview_pending=nil; save_data(d); send(name,"§c没有待确认商品。"); return true end
    if r.market_sell_preview_pending and type(s.preview_entry)=="table" then send(name,"§e已有一个出售预览待确认，请输入1确认或0取消。"); return true end
    local bx=tonumber(s.barrel_pos and s.barrel_pos.x); local by=tonumber(s.barrel_pos and s.barrel_pos.y); local bz=tonumber(s.barrel_pos and s.barrel_pos.z)
    if not bx or not by or not bz then send(name,"§c商品木桶坐标记录损坏，无法读取。"); return true end
    local okbarrel=false
    local okb,v=pcall(game.getBlockData,bx,by-1,bz)
    if okb and type(v)=="table" and tostring(v.name or "")~="" then
        local bn=lower(tostring(v.name or "")); okbarrel=(bn=="barrel" or bn=="minecraft:barrel")
    end
    if not okbarrel then
        send(name,"§c检测失败：你脚下一格已经不是木桶。请勿移动木桶后再确认商品。")
        return true
    end
    set_market_busy(true)
    local id=tostring(s.id)
    local ok,entry=market_save_nbt_item(id,bx,by,bz)
    set_market_busy(false)
    if not ok then send(name,"§c商品保存失败："..tostring(entry)); return true end
    s.preview_entry=entry
    r.market_sell_preview_pending=true
    set_menu(d,r,"market_sell_confirm")
    save_data(d)
    send(name,market_sell_preview_message(entry,id,s.name,s.price))
    return true
end

-- ---------- 导入：保留原始坐标偏移 ----------
function place_native_region(playerName,name,tx,ty,tz)
    local m,err=load_native_manifest(name)
    if not m then return false,err end
    tx,ty,tz=math.floor(tonumber(tx) or 0),math.floor(tonumber(ty) or 0),math.floor(tonumber(tz) or 0)
    local origin=m.origin or {}
    local ox,oy,oz=tonumber(origin.x),tonumber(origin.y),tonumber(origin.z)
    if not ox or not oy or not oz then return false,"区域数据原点损坏。" end
    local list={}
    for key,v in pairs(m.blocks or {}) do
        local sx,sy,sz=tostring(key):match("^(-?%d+),(-?%d+),(-?%d+)$")
        if sx and type(v)=="table" then
            local bn=tostring(v.name or v.id or "")
            if bn~="" then
                local item={x=tonumber(sx)-ox,y=tonumber(sy)-oy,z=tonumber(sz)-oz,name=bn}
                if v.states~=nil then item.states=v.states end
                if type(v.nbt)=="table" then item.nbt=normalize_import_nbt(v.nbt) end
                list[#list+1]=item
            end
        end
    end
    if #list<=0 then return false,"区域数据为空。" end
    table.sort(list,function(a,b)
        if a.y~=b.y then return a.y<b.y end
        if a.z~=b.z then return a.z<b.z end
        return a.x<b.x
    end)
    local ok_call,run=pcall(game.importBlocks,list,{x=tx,y=ty,z=tz,dimension=dim_exec(detect_dimension(playerName)),speed=-1,region_mode=1,anti_loss=true})
    if not ok_call then return false,"导入失败："..tostring(run) end
    local ok_wait,finished=pcall(game.importWait,run)
    if not ok_wait then return false,"导入等待失败："..tostring(finished) end
    if finished==true then
        log_event("NBT_REGION",tostring(playerName).." imported region "..tostring(name).." blocks="..tostring(#list).." preserve_offset=true")
        return true,"§a导入完成：§e"..tostring(name).." §f（"..tostring(#list).." 个方块）\n§7原始原点偏移已保留。"
    end
    return false,"导入过程未正常完成。"
end

function nbt_region_self_check(name)
    local m,e=load_native_manifest(name)
    if not m then return false,e end
    local n=0; local minx,miny,minz,maxx,maxy,maxz=nil,nil,nil,nil,nil,nil
    for k,v in pairs(m.blocks or {}) do
        if type(v)=="table" then
            local x,y,z=tostring(k):match("^(-?%d+),(-?%d+),(-?%d+)$")
            x,y,z=tonumber(x),tonumber(y),tonumber(z)
            if x and y and z then
                n=n+1; minx=math.min(minx or x,x); miny=math.min(miny or y,y); minz=math.min(minz or z,z); maxx=math.max(maxx or x,x); maxy=math.max(maxy or y,y); maxz=math.max(maxz or z,z)
            end
        end
    end
    return true,string.format("导出数据正常：记录=%d；原点=%s；范围=%d,%d,%d → %d,%d,%d",n,tostring(m.origin and (m.origin.x..","..m.origin.y..","..m.origin.z) or "?"),minx or 0,miny or 0,minz or 0,maxx or 0,maxy or 0,maxz or 0)
end

-- ---------- 背包：区分“真实空背包”和“读取失败” ----------
function patch_inventory_query_real(nm)
    local safe=string.gsub(tostring(nm or ''),'"','\\"')
    local candidates={
        {fn=function() return game.queryInventory('@a[name="'..safe..'"]') end,src='game.queryInventory(selector)'},
        {fn=function() return game.queryInventory(tostring(nm)) end,src='game.queryInventory(name)'},
        {fn=function() return player.getInventory(tostring(nm)) end,src='player.getInventory(name)'},
    }
    local last=""
    for _,c in ipairs(candidates) do
        local ok,inv=pcall(c.fn)
        if ok and type(inv)=="table" and type(inv.items)=="table" then return true,inv,c.src end
        last=tostring(inv or last)
    end
    return false,nil,"背包实时接口均未返回合法数据："..last
end

function ai_inventory_sync(playerName,targetText,admin)
    local targets=inv_parse_targets(targetText,playerName)
    local allowed,denied={},{}
    for _,nm in ipairs(targets or {}) do
        nm=trim(tostring(nm or ''))
        if nm~='' then
            if admin or lower(nm)==lower(playerName) then allowed[#allowed+1]=nm else denied[#denied+1]=nm end
        end
    end
    if #denied>0 then return '权限限制：普通玩家只能查询自己的背包（已拒绝：'..table.concat(denied,'、')..'）。',false end
    if #allowed==0 then return '背包查询失败：没有有效玩家目标。',false end
    local out={'背包真实查询结果：'}
    for _,nm in ipairs(allowed) do
        local ok,inv,src=patch_inventory_query_real(nm)
        out[#out+1]='§b━━ '..nm..' 的背包 ━━'
        if not ok then
            out[#out+1]='读取失败：没有收到真实背包数据。'
        else
            local items=inv.items or {}
            if #items==0 then
                out[#out+1]='§7背包为空。'
            else
                for i,it in ipairs(items) do
                    if i>54 then out[#out+1]='§7……还有更多物品未显示。'; break end
                    out[#out+1]=string.format('§f%02d. %s ×%s §8(槽位%s)',i,item_display_name(it.name,it.damage),tostring(it.count or 0),tostring(it.slot or '?'))
                end
            end
            out[#out+1]='§8读取接口：'..tostring(src)
        end
    end
    return table.concat(out,'\n'),true
end

-- ---------- 公告栏 / 服务器号 / TPS ----------
PATCH_SIDEBAR_LAST=tonumber(PATCH_SIDEBAR_LAST) or 0
function patch_try_tps()
    local candidates={
        {name='game.getServerTPS',fn=function() return game.getServerTPS() end},
        {name='game.getTPS',fn=function() return game.getTPS() end},
        {name='game.serverTPS',fn=function() return game.serverTPS() end},
    }
    for _,c in ipairs(candidates) do
        local ok,v=pcall(c.fn)
        local n=tonumber(v)
        if ok and n and n>=0 and n<=100 then return n,c.name end
    end
    return nil,'当前运行时未暴露TPS API'
end
function patch_server_notice_load()
    local f=game.dataDir()..'/server_announcement.json'
    local ok,d=pcall(util.json_load,f)
    if ok and type(d)=='table' then return d end
    return {server_number='未设置',expires_at=0,updated_at=0}
end
function patch_server_number_set(name,num,days)
    if not is_admin(name) then send(name,'§c只有管理员可以设置服务器号。'); return true end
    num=tostring(num or ''):match('^%d+$')
    if not num then send(name,'§c服务器号必须是数字。'); return true end
    days=math.max(1,math.floor(tonumber(days) or 30))
    local d={server_number=num,expires_at=util.timestamp()+days*86400,updated_at=util.timestamp(),updated_by=name}
    pcall(util.json_write,game.dataDir()..'/server_announcement.json',d)
    send(name,'§a服务器号已设置为 §e'..num..'§a，有效期 §e'..days..' 天。\n§7到期时间（北京时间）：'..patch_beijing_fmt(d.expires_at))
    patch_sidebar_update(true)
    return true
end
function patch_sidebar_update(force)
    local now=util.timestamp()
    if not force and now-(PATCH_SIDEBAR_LAST or 0)<60 then return true end
    PATCH_SIDEBAR_LAST=now
    local d=patch_server_notice_load()
    local tps,src=patch_try_tps()
    local tpsText=tps and string.format('%.1f',tps) or '不可用'
    local expire=(tonumber(d.expires_at) or 0)>0 and patch_beijing_fmt(d.expires_at) or '未设置'
    local lines={
        '§b§l✦ 服务器公告 ✦',
        '§f服务器号：§e'..tostring(d.server_number or '未设置'),
        '§f号牌到期：§e'..expire,
        '§fTPS：§a'..tpsText,
        '§f更新时间：§7'..patch_beijing_fmt(now),
        '§d✦ .help  查看功能',
        '§a✦ .签到  今日奖励',
        '§e✦ .公会  公会大厅',
        '§b✦ .市场  玩家交易',
        '§6✦ .领地  领地系统',
    }
    local safe={}; for i,line in ipairs(lines) do safe[#safe+1]=line end
    pcall(game.sendCommand,'scoreboard objectives add ds_notice dummy "§b公告栏"')
    pcall(game.sendCommand,'scoreboard objectives setdisplay sidebar ds_notice')
    for i,line in ipairs(safe) do
        local holder='ann'..tostring(i)
        pcall(game.sendCommand,'scoreboard players set "'..holder..'" ds_notice '..tostring(#safe-i+1))
        pcall(game.sendCommand,'scoreboard players reset "'..holder..'" ds_notice')
        pcall(game.sendCommand,'scoreboard players set "'..line:gsub('"','\\"')..'" ds_notice '..tostring(#safe-i+1))
    end
    return true
end

-- ---------- 金币排行榜 ----------
function coin_leaderboard(name,limit)
    limit=math.max(1,math.min(20,math.floor(tonumber(limit) or 10)))
    local seen,arr={},{}
    local ok,list=pcall(game.getOnlinePlayers)
    if ok and type(list)=='table' then
        for _,v in pairs(list) do
            local nm=type(v)=='table' and tostring(v.name or v.playerName or '') or tostring(v)
            if nm~='' and not seen[nm] then
                seen[nm]=true
                local sc=0
                local okc,val=pcall(game.getScore,scoreboard_name(),nm)
                if okc and tonumber(val) then sc=tonumber(val) or 0 end
                arr[#arr+1]={name=nm,score=sc}
            end
        end
    end
    table.sort(arr,function(a,b) if a.score==b.score then return a.name<b.name end return a.score>b.score end)
    local lines={'§6✦ 金币排行榜 ✦'}
    if #arr==0 then lines[#lines+1]='§7暂无可用玩家数据。' else for i=1,math.min(limit,#arr) do local v=arr[i]; lines[#lines+1]=string.format('§f%d. §e%s §7— §6%s金币',i,v.name,tostring(v.score)) end end
    send(name,table.concat(lines,'\n')); return true
end

-- ---------- 命令方块容器：降低常驻扫描频率，避免卡服 ----------
PATCH_CMD_CONTAINER_LAST=tonumber(PATCH_CMD_CONTAINER_LAST) or 0
function v17_cmd_container_safe_tick()
    local now=util.timestamp()
    if now-(PATCH_CMD_CONTAINER_LAST or 0)<5 then return end
    PATCH_CMD_CONTAINER_LAST=now
    pcall(cmd_container_tick)
end

-- ---------- 公会：基础数据与菜单实际可用化 ----------
function guild_player_history(name)
    local m=guild_player_map(); local rec=m[name]
    return type(rec)=='table' and rec.had_guild==true
end
function guild_mark_history(name,gid,role)
    local m=guild_player_map(); m[name]=m[name] or {}; m[name].had_guild=true; m[name].guild_id=gid; m[name].role=role; guild_save(GUILD_PLAYER_FILE,m)
end
function guild_find_by_invite(code)
    local gd=guild_load(GUILD_FILE,{items={}})
    local q=lower(trim(code))
    if q=='' then return nil end
    for _,g in pairs(gd.items or {}) do
        if g.status~='dissolved' and lower(tostring(g.invite_code or ''))==q then return g end
    end
    return nil
end
function guild_generate_invite(name)
    local g=guild_find_player(name); if not g then send(name,'§c你还没有加入公会。'); return true end
    local role=guild_member_role(g,name); if role~='owner' and role~='deputy' then send(name,'§c只有会长或副会长可以生成邀请码。'); return true end
    if not g.invite_code or trim(tostring(g.invite_code))=='' then g.invite_code=string.format('%02X-%04X-%02X',math.random(0,255),math.random(0,65535),math.random(0,255)) end
    local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    send(name,'§d✦ 公会邀请码 ✦\n§f公会：§e'..g.name..'\n§f邀请码：§6'..g.invite_code..'\n§7可重复使用；公会解散后失效。')
    return true
end
function guild_accept_invite(name,code)
    local existing=guild_find_player(name); if existing then send(name,'§c你已经加入「'..existing.name..'」。'); return true end
    local g=guild_find_by_invite(code)
    if not g then send(name,'§c邀请码不存在或已失效。'); return true end
    if #(g.members or {})>=tonumber(g.max_members or (10+(tonumber(g.level) or 1)*2)) then send(name,'§c该公会成员名额已满。'); return true end
    g.members=g.members or {}; g.members[#g.members+1]={name=name,role='member',contribution=0,joined_at=util.timestamp()}
    local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    guild_mark_history(name,g.id,'member')
    send(name,'§a✦ 已加入公会「'..g.name..'」！'); return true
end
function guild_rankings(name,kind)
    local gd=guild_load(GUILD_FILE,{items={}}); local arr={}
    for _,g in pairs(gd.items or {}) do if g.status~='dissolved' then
        local value
        if kind=='activity' then value=tonumber(g.activity_total or 0) else value=tonumber(g.exp or 0) end
        arr[#arr+1]={g=g,v=value or 0}
    end end
    table.sort(arr,function(a,b) if a.v==b.v then return tostring(a.g.name)<tostring(b.g.name) end return a.v>b.v end)
    local lines={kind=='activity' and '§d✦ 公会活跃度排行 ✦' or '§b✦ 公会等级排行 ✦'}
    for i=1,math.min(10,#arr) do local v=arr[i]; lines[#lines+1]=string.format('§f%d. §e%s §7Lv.%s §8| §d%s',i,v.g.name,tostring(v.g.level or 1),tostring(v.v)) end
    if #arr==0 then lines[#lines+1]='§7暂无公会。' end
    send(name,table.concat(lines,'\n')); return true
end
function guild_public_detail(name,gid)
    local gd=guild_load(GUILD_FILE,{items={}}); local g=gd.items[tostring(gid or '')]
    if not g or g.status=='dissolved' then send(name,'§c公会不存在。'); return true end
    local lines={'§8§m━━━━━━━━━━━━━━━━━━━━','§d✦『'..g.name..'』公会信息','§8§m━━━━━━━━━━━━━━━━━━━━',
        '§f等级：§eLv.'..tostring(g.level or 1)..' · '..guild_level_title(g.level),
        '§f会长：§e'..tostring(g.owner or '未知'),
        '§f成员：§b'..tostring(#(g.members or {})),
        '§f在线：§a'..tostring(guild_online_count(g)),
        '§f公会资金：§6'..tostring(g.funds or 0),
        '§f公会活跃：§d'..tostring(g.activity_total or 0),
        '§f公告：§7'..tostring((guild_load(GUILD_NOTICE_FILE,{guilds={}}).guilds[g.id] or {})[#(guild_load(GUILD_NOTICE_FILE,{guilds={}}).guilds[g.id] or {})] and (guild_load(GUILD_NOTICE_FILE,{guilds={}}).guilds[g.id] or {})[#(guild_load(GUILD_NOTICE_FILE,{guilds={}}).guilds[g.id] or {})].text or '暂无'),
        '§7领地坐标、仓库坐标、传送点坐标不会对外显示。'}
    send(name,table.concat(lines,'\n')); return true
end
function guild_activity_tick()
    local gd=guild_load(GUILD_FILE,{items={}}); local online={}
    local ok,list=pcall(game.getOnlinePlayers)
    if ok and type(list)=='table' then for _,v in pairs(list) do local nm=type(v)=='table' and tostring(v.name or v.playerName or '') or tostring(v); if nm~='' then online[nm]=true end end end
    local changed=false
    for gid,g in pairs(gd.items or {}) do
        if g.status~='dissolved' then
            g.activity_seconds=tonumber(g.activity_seconds or 0) or 0
            g.activity_total=tonumber(g.activity_total or 0) or 0
            local inc=0
            for _,m in ipairs(g.members or {}) do if online[m.name] then inc=inc+60; m.online_seconds=tonumber(m.online_seconds or 0)+60 end end
            if inc>0 then g.activity_seconds=g.activity_seconds+inc; g.activity_total=g.activity_total+inc; changed=true end
        end
    end
    if changed then guild_save(GUILD_FILE,gd) end
end
function guild_protect_tick()
    local gd=guild_load(GUILD_FILE,{items={}})
    local ok,list=pcall(game.getOnlinePlayers); if not ok or type(list)~='table' then return end
    for _,pv in pairs(list) do
        local name=type(pv)=='table' and tostring(pv.name or pv.playerName or '') or tostring(pv); if name~='' then
            local p=player_position(name); if p then
                for _,g in pairs(gd.items or {}) do if g.status~='dissolved' and guild_inside(g.territory,p.x,p.z,p.dimension) then
                    local member=(guild_member_role(g,name)~=nil)
                    if not member then
                        local last=RUNTIME and RUNTIME.last_pos and RUNTIME.last_pos[name]
                        local ex,ez=(last and tonumber(last.x)),(last and tonumber(last.z))
                        if not ex then ex=tonumber(g.territory.x1)-2; ez=tonumber(g.territory.z1)-2 end
                        pcall(game.teleport,name,ex,tonumber(p.y),ez,p.dimension)
                        send(name,'§c你不是「'..g.name..'」公会成员，已按领地保护规则传送离开。')
                    end
                    break
                end end
            end
        end
    end
end

-- ---------- 公会菜单重新接线：邀请、列表详情、排行榜真正可进入 ----------
function guild_commands_menu(name)
    local d,r=player_record(name,true); clear_menu(d,r); save_data(d)
    local g=guild_find_player(name)
    if not g then
        if guild_player_history(name) then
            set_menu(d,r,'guild_return_main')
            send(name,table.concat({'§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━','§b§l✦ 公 会 大 厅 ✦','§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━','§7你当前没有加入公会。','§f① 创建公会','§f② 公会列表','§f③ 搜索公会','§f④ 搜索玩家','§f⑤ 接受邀请码','§f⑥ 我的申请','§f⑦ 公会等级排行','§f⑧ 公会活跃排行','§f⑨ 招募/邀请码','§f⑩ 成就与周报'},'\n')); return true
        end
        set_menu(d,r,'guild_first')
        send(name,table.concat({'§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━','§d§l✦ 公 会 创 立 ✦','§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━','§7你还没有建立或加入过公会。','§f① 创建公会','§f② 公会列表','§f③ 搜索公会','§f④ 搜索玩家','§f⑤ 接受邀请码','§f⑥ 我的申请','§f⑦ 公会等级排行','§f⑧ 公会活跃排行'},'\n')); return true
    end
    set_menu(d,r,'guild_main')
    send(name,table.concat({'§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━','§d§l✦『'..g.name..'』公会大厅 ✦','§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━','§5◈ Lv.'..tostring(g.level or 1)..' · '..guild_level_title(g.level),'§f会长：§e'..tostring(g.owner or '未知'),'§f在线：§a'..guild_online_count(g)..'/'..#(g.members or {}),'§f贡献：§d'..tostring((g.player_contribution and g.player_contribution[name]) or 0),'§f资金：§6'..tostring(g.funds or 0),'§f① 公会信息','§f② 成员列表','§f③ 每日签到','§f④ 公会任务','§f⑤ 公会等级排行','§f⑥ 公会成就','§f⑦ 公会公告','§f⑧ 公会领地','§f⑨ 公会设施','§f⑩ 公会外交','§f⑪ 公会发展','§f⑫ 公会管理','§f⑬ 招募/邀请码','§f⑭ 活跃度排行'},'\n')); return true
end

function guild_handle_menu(name,msg)
    local d,r=player_record(name,true); local mode=r and r.menu or ''; local m=trim(msg)
    if mode=='guild_first' or mode=='guild_return_main' then
        if m=='.stop' then clear_menu(d,r); return true end
        local n=tonumber(m)
        if n==1 then return guild_creation_start(name) elseif n==2 then return guild_list(name) elseif n==3 then set_menu(d,r,'guild_search_name'); send(name,'§e请输入公会名称关键词：'); return true elseif n==4 then set_menu(d,r,'guild_search_player'); send(name,'§e请输入玩家名称关键词：'); return true elseif n==5 then set_menu(d,r,'guild_invite_accept'); send(name,'§e请输入邀请码：'); return true elseif n==6 then send(name,'§7当前公会申请箱已开放。'); return true elseif n==7 then return guild_rankings(name,'level') elseif n==8 then return guild_rankings(name,'activity') elseif n==9 and mode=='guild_return_main' then return guild_generate_invite(name) elseif n==10 and mode=='guild_return_main' then return guild_announcement(name) end
        send(name,'§c请输入有效编号。'); return true
    end
    if mode=='guild_invite_accept' then if m=='.stop' then clear_menu(d,r); return true end; clear_menu(d,r); return guild_accept_invite(name,m) end
    if mode=='guild_list' then if m=='.stop' then clear_menu(d,r); return true end; local n=tonumber(m); local arr=r.guild_list or {}; local g=arr[n]; if g then return guild_public_detail(name,g.id) end; send(name,'§c请输入列表中的编号。'); return true end
    if mode=='guild_main' then
        if m=='.stop' then clear_menu(d,r); return true end
        local n=tonumber(m)
        if n==1 then return guild_info(name) elseif n==2 then local g=guild_find_player(name); local lines={'§b✦ 公会成员 ✦'}; for i,m0 in ipairs(g.members or {}) do lines[#lines+1]=string.format('§f%d. %s §7[%s] §8| 贡献%s',i,m0.name,m0.role,m0.contribution or 0) end; send(name,table.concat(lines,'\n')); return true elseif n==3 then return guild_signin(name) elseif n==4 then send(name,'§b✦ 公会任务 ✦\n§7每日在线、签到、活跃与活动任务。\n§e任务会产生贡献、公会经验与公会资金。'); return true elseif n==5 then return guild_rankings(name,'level') elseif n==6 then send(name,'§d✦ 公会成就 ✦\n§7成员、签到、在线、任务、资金、等级、外交等长期目标。'); return true elseif n==7 then return guild_announcement(name) elseif n==8 then send(name,'§b公会领地：§a已建立\n§7坐标对玩家隐藏。'); return true elseif n==9 then send(name,'§b公会设施：\n§f.传送公会 / .传送工会\n§f.传送公会仓库 / .传送工会仓库\n§7设置位置：会长/副会长，且必须位于本公会领地内。'); return true elseif n==10 then send(name,'§5✦ 外交 ✦\n§7中立 / 友好 / 同盟 / 敌对。\n§7双方确认后才建立正式关系。'); return true elseif n==11 then send(name,'§6✦ 公会发展 ✦\n§f城建：领地、仓库、设施\n§f商业：资金与经济任务\n§f冒险：高级任务与活动\n§f荣耀：称号、排行、成就'); return true elseif n==12 then return guild_manage(name) elseif n==13 then return guild_generate_invite(name) elseif n==14 then return guild_rankings(name,'activity') end
        send(name,'§c请输入1~14。'); return true
    end
    if mode=='guild_search_name' then local gd=guild_load(GUILD_FILE,{items={}}); local lines={'§b✦ 公会搜索 ✦'}; local q=lower(m); local count=0; for _,g in pairs(gd.items or {}) do if g.status~='dissolved' and q~='' and lower(tostring(g.name)):find(q,1,true) then count=count+1; lines[#lines+1]=string.format('§f%d. §e%s §7Lv.%s §8| 在线%s/%s',count,g.name,tostring(g.level or 1),guild_online_count(g),#(g.members or {})) end end; if count==0 then lines[#lines+1]='§7没有找到匹配公会。' end; send(name,table.concat(lines,'\n')); clear_menu(d,r); return true end
    if mode=='guild_search_player' then clear_menu(d,r); return guild_search_player(name,m) end
    if mode=='guild_announcement' then return guild_announcement(name) end
    return false
end

-- ---------- .help：16格固定主菜单，编号直接打开 ----------
function show_help(name)
    local d,r=player_record(name,true); r.menu='help'; r.menu_expires=util.timestamp()+MENU_TIMEOUT; save_data(d)
    send(name,table.concat({'§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━','§b§l      ✦ 功 能 主 菜 单 ✦','§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━','§b01§r 基础功能    §b02§r 传送中心    §b03§r 领地系统    §b04§r 玩家信息','§b05§r 经济系统    §b06§r 系统商店    §b07§r 玩家市场    §b08§r 兑换中心','§b09§r AI智能      §b10§r 每日活动    §b11§r 任务中心    §b12§r 娱乐玩法','§b13§r 实用工具    §b14§r 服务器功能  §b15§r 公会系统    §b16§r 玩法介绍'},'\n'))
end

function patch_help_open(name,n)
    n=tonumber(n); if not n then show_help(name); return true end
    local d,r=player_record(name,true); clear_menu(d,r)
    if n==1 then slot_menu(name,'save_slot') elseif n==2 then slot_menu(name,'return_slot') elseif n==3 then set_menu(d,r,'death_dir'); death_show_list(name) elseif n==4 then slot_menu(name,'delete_slot') elseif n==5 then show_tpa_targets(name) elseif n==6 then show_transfer_targets(name) elseif n==7 then show_report_targets(name) elseif n==8 then local rr=player_record(name,true); local st=coordinate_tp_state(rr); if is_admin(name) or st.available or (tonumber(st.extra_uses) or 0)>0 then local dd,dr=player_record(name,true); set_menu(dd,dr,'coord_tp_input'); send(name,'§b━━ 坐标传送 ━━\n§f请输入：维度 X Y Z') else send(name,'§c你当前没有坐标传送次数。') end elseif n==9 then start_soul(name) elseif n==10 then show_ban_menu(name) elseif n==11 then show_unban_menu(name) elseif n==12 then show_player_market_main(name) elseif n==13 then show_territory(name) elseif n==14 then show_market_14(name) elseif n==15 then guild_commands_menu(name) elseif n==16 then show_gameplay_categories(name) else show_help(name) end
    return true
end

-- ---------- 最终事件包装 ----------
local _patch2_prev_on_chat=on_chat
function on_chat(playerName,msg)
    local raw=tostring(msg or '')
    local low=lower(trim(raw))
    if low=='.公会' or low=='公会' or low=='.工会' or low=='工会' then return guild_commands_menu(playerName) end
    if low=='.传送公会' or low=='传送公会' or low=='.传送工会' or low=='传送工会' then return guild_teleport(playerName,'tp') end
    if low=='.传送公会仓库' or low=='传送公会仓库' or low=='.传送工会仓库' or low=='传送工会仓库' then return guild_teleport(playerName,'warehouse') end
    if low=='.公会签到' or low=='公会签到' then return guild_signin(playerName) end
    if low=='.公会公告' or low=='公会公告' then return guild_announcement(playerName) end
    local notice=raw:match('^%.公会公告%s+(.+)$'); if notice then return guild_post_notice(playerName,trim(notice)) end
    local gsearch=raw:match('^%.公会搜索玩家%s+(.+)$'); if gsearch then return guild_search_player(playerName,gsearch) end
    local ghelp=raw:match('^%.help%s+(%d+)%s*$'); if ghelp then return patch_help_open(playerName,tonumber(ghelp)) end
    if low=='.help' then show_help(playerName); return true end
    local glb=raw:match('^%.金币排行%s*(%d*)$') or raw:match('^%.金币排行榜%s*(%d*)$'); if glb then return coin_leaderboard(playerName,tonumber(glb) or 10) end
    local grp=raw:match('^%.群号%s+(%d+)%s*(%d*)$'); if grp then local n,days=raw:match('^%.群号%s+(%d+)%s*(%d*)$'); return patch_server_number_set(playerName,n,tonumber(days) or 30) end
    if low=='.公告栏刷新' then if not is_admin(playerName) then send(playerName,'§c只有管理员可以刷新公告栏。'); return true end; patch_sidebar_update(true); send(playerName,'§a公告栏已刷新。'); return true end
    if low=='.命令容器' or low=='.命令方块容器' then return cmd_container_show(playerName) end
    if low=='.性能' or low=='.tps' then local tps,src=patch_try_tps(); send(playerName,'§b━━ 服务器性能 ━━\n§fTPS：§e'..(tps and string.format('%.1f',tps) or 'API不可用')..'\n§f来源：§7'..src); return true end
    local d,r=player_record(playerName,true)
    if r and r.menu=='market_sell_name' then return patch_market_start_from_name(playerName,trim(raw),d,r) end
    if r and tostring(r.menu):find('^guild_') then local handled=guild_handle_menu(playerName,raw); if handled then return true end end
    return _patch2_prev_on_chat(playerName,msg)
end

-- ---------- 初始化与低频任务 ----------
local _patch2_prev_v17=v17_event_tick
function v17_event_tick()
    local result=true
    if type(_patch2_prev_v17)=='function' then local ok,r=pcall(_patch2_prev_v17); if ok then result=r end end
    local now=util.timestamp()
    if now-(PATCH_SIDEBAR_LAST or 0)>=60 then pcall(patch_sidebar_update) end
    if now-(PATCH_CMD_CONTAINER_LAST or 0)>=5 then pcall(v17_cmd_container_safe_tick) end
    return result
end

local _patch2_prev_on_init=on_init
function on_init()
    local ret=nil
    if type(_patch2_prev_on_init)=='function' then local ok,r=pcall(_patch2_prev_on_init); if ok then ret=r end end
    pcall(ensure_patch_prompt_files)
    pcall(guild_init_files)
    pcall(patch_sidebar_update,true)
    pcall(util.write_file,game.dataDir()..'/PATCH_VERSION.txt',PATCH_VERSION..'\n'..PATCH_BUILD_TAG..'\n')
    return ret
end


