PATCH_BUILD_TAG = "主体修复版-2026-09-26-R3"

-- ---------- 公会历史记录兼容 UUID 映射 ----------
function guild_player_history(name)
    local m=guild_player_map()
    local k=uuid_key(name)
    if m.players and m.players[k] then return true end
    if m[tostring(name)] and type(m[tostring(name)])=='table' and m[tostring(name)].had_guild then return true end
    return false
end
function guild_mark_history(name,gid,role)
    local m=guild_player_map(); m.players=m.players or {}
    local k=uuid_key(name)
    m.players[k]=gid
    m.history=m.history or {}
    m.history[k]={had_guild=true,last_guild_id=gid,last_role=role,updated_at=util.timestamp()}
    guild_save(GUILD_PLAYER_FILE,m)
end

-- ---------- 公会等级/贡献/资金成长闭环 ----------
function guild_upgrade_cost(lv)
    return 1000*math.max(1,tonumber(lv) or 1)
end
function guild_progress(g,name,exp,contrib,funds)
    exp=math.max(0,math.floor(tonumber(exp) or 0)); contrib=math.max(0,math.floor(tonumber(contrib) or 0)); funds=math.max(0,math.floor(tonumber(funds) or 0))
    g.exp=tonumber(g.exp or 0)+exp
    g.funds=tonumber(g.funds or 0)+funds
    g.total_contribution=tonumber(g.total_contribution or 0)+contrib
    for _,m in ipairs(g.members or {}) do if uuid_key(m.name)==uuid_key(name) then m.contribution=tonumber(m.contribution or 0)+contrib; break end end
    while (tonumber(g.level) or 1)<10 do
        local lv=tonumber(g.level) or 1; local need=guild_exp_need(lv); local cost=guild_upgrade_cost(lv)
        if (tonumber(g.exp) or 0)<need or (tonumber(g.funds) or 0)<cost then break end
        if #(g.members or {}) < guild_max_members(lv+1) then break end
        g.exp=g.exp-need; g.funds=g.funds-cost; g.level=lv+1; g.title=guild_level_title(g.level); g.max_members=guild_max_members(g.level); g.level_up_at=util.timestamp()
        guild_log(g.id,'公会升级','系统','Lv.'..lv..' → Lv.'..g.level..'，消耗资金'..cost)
    end
end

function guild_signin(name)
    local g=guild_find_player(name)
    if not g then send(name,'§c你还没有加入公会。'); return true end
    local today=os.date('!%Y-%m-%d',util.timestamp()+8*3600)
    g.signins=g.signins or {}
    local u=uuid_key(name)
    g.signins[u]=g.signins[u] or {}
    if g.signins[u].day==today then send(name,'§e你今天已经签到过了。'); return true end
    local reward='签到奖励待生成'
    local ok,rr=pcall(choose_signin_reward,name)
    if ok and type(rr)=='string' and trim(rr)~='' then reward=rr end
    g.signins[u].day=today; g.signins[u].count=tonumber(g.signins[u].count or 0)+1
    guild_progress(g,name,10,20,20)
    local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    send(name,'§d✦ 公会每日签到成功 ✦\n§f奖励：'..reward..'\n§e贡献 +20  §b公会经验 +10  §6公会资金 +20')
    return true
end

-- ---------- 公会领地：删除、换址、设施位置硬校验 ----------
function guild_delete_territory(name,force)
    local g=guild_find_player(name)
    if not g then send(name,'§c你还没有加入公会。'); return true end
    local role=guild_member_role(g,name); if role~='owner' and not (force and is_admin(name)) and not is_admin(name) then send(name,'§c只有会长或管理员可以删除公会领地。'); return true end
    if type(g.territory)~='table' then send(name,'§7当前公会没有公会领地。'); return true end
    local old=g.territory
    g.territory=nil; g.teleport_point=nil; g.warehouse_point=nil
    local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    guild_log(g.id,'删除公会领地',name,(force and '管理员强制删除' or '会长主动删除')..'；原区域='..tostring(old.x1)..','..tostring(old.z1)..'~'..tostring(old.x2)..','..tostring(old.z2))
    send(name,'§a公会领地保护已经解除。\n§7现在可以重新选择新的领地。')
    return true
end
function guild_relocate_start(name)
    local g=guild_find_player(name); if not g then send(name,'§c你还没有加入公会。'); return true end
    if guild_member_role(g,name)~='owner' and not is_admin(name) then send(name,'§c只有会长或管理员可以更换公会领地。'); return true end
    local d,r=player_record(name,true); r.guild_relocate={guild_id=g.id,step='start',started_at=util.timestamp()}; set_menu(d,r,'guild_relocate_start_confirm'); save_data(d)
    send(name,'§d✦ 更换公会领地 ✦\n请先站到新的§e起始位置§f。\n输入1确定，0取消。\n§7不会显示你的坐标。')
    return true
end
function guild_finish_relocate(name)
    local d,r=player_record(name,true); local s=r.guild_relocate; if type(s)~='table' then return true end
    local g=guild_find_player(name); if not g or tostring(g.id)~=tostring(s.guild_id) then guild_create_abort(name,'§c公会状态已经变化，本次换址已取消。'); return true end
    local p=player_position(name); if not p then send(name,'§c无法读取当前位置。'); return true end
    local st=s.start_point; local en={x=math.floor(p.x),y=math.floor(p.y),z=math.floor(p.z),dimension=p.dimension}
    if dim_exec(en.dimension)~=dim_exec(st.dimension) then send(name,'§c起始与终止位置必须在同一维度。'); return true end
    local cand={x1=st.x,z1=st.z,x2=en.x,z2=en.z,dimension=st.dimension}
    local w=math.abs(cand.x2-cand.x1)+1; local l=math.abs(cand.z2-cand.z1)+1
    if w>128 or l>128 then send(name,'§c新的公会领地不能超过128×128。'); return true end
    local tdb=territory_db()
    for _,t in pairs(tdb.items or {}) do if type(t)=='table' and not t.deleted and territory_overlap(cand,t) then send(name,'§c新领地与普通领地重叠，换址失败。'); return true end end
    local gd=guild_load(GUILD_FILE,{items={}})
    for gid,other in pairs(gd.items or {}) do if tostring(gid)~=tostring(g.id) and other.status~='dissolved' and type(other.territory)=='table' and territory_overlap(cand,other.territory) then send(name,'§c新领地与其他公会领地重叠，换址失败。'); return true end end
    g.territory=cand; g.teleport_point=s.start_point; g.warehouse_point=nil; gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    local pp=player_record(name,true); pp.guild_relocate=nil; clear_menu(d,pp); save_data(d)
    guild_log(g.id,'更换公会领地',name,'新区域='..cand.x1..','..cand.z1..'~'..cand.x2..','..cand.z2)
    send(name,'§a✦ 公会领地更换完成！\n§7旧领地保护已自动失效。\n§f新的公会传送点已更新。\n§f旧仓库点已清空，需要重新设置仓库位置。')
    return true
end
function guild_facility_set(kind,name)
    local g=guild_find_player(name); if not g then send(name,'§c你还没有加入公会。'); return true end
    local role=guild_member_role(g,name); if role~='owner' and role~='deputy' and not is_admin(name) then send(name,'§c只有会长、副会长或管理员可以设置。'); return true end
    local p=player_position(name); if not p then send(name,'§c无法读取当前位置。'); return true end
    if type(g.territory)~='table' or not guild_inside(g.territory,p.x,p.z,p.dimension) then send(name,'§c设施位置必须位于本公会领地内部。'); return true end
    if kind=='tp' then g.teleport_point={x=math.floor(p.x),y=math.floor(p.y),z=math.floor(p.z),dimension=p.dimension} else g.warehouse_point={x=math.floor(p.x),y=math.floor(p.y),z=math.floor(p.z),dimension=p.dimension} end
    local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    guild_log(g.id,kind=='tp' and '设置公会传送点' or '设置公会仓库点',name,'位置保密')
    send(name,'§a设置完成。坐标已保存，普通公会信息不会显示。'); return true
end

