-- ---------- 最终公会菜单/管理菜单 ----------
local _r3_old_guild_handle=guild_handle_menu
function guild_handle_menu(name,msg)
    local d,r=player_record(name,true); local mode=r and r.menu or ''; local m=trim(msg)
    if mode=='guild_relocate_start_confirm' then if m=='.stop' or m=='0' then r.guild_relocate=nil; clear_menu(d,r); save_data(d); send(name,'§e已取消换址。'); return true end; if m~='1' then send(name,'§c请输入1确定或0取消。'); return true end; local p=player_position(name); if not p then send(name,'§c无法读取当前位置。'); return true end; r.guild_relocate.start_point={x=math.floor(p.x),y=math.floor(p.y),z=math.floor(p.z),dimension=p.dimension}; r.guild_relocate.step='end'; r.guild_relocate.end_deadline=util.timestamp()+180; set_menu(d,r,'guild_relocate_end_confirm'); save_data(d); send(name,'§a起始位置已记录。\n§e请在3分钟内前往终止位置。\n§f输入1确定，0续3分钟，.stop取消。'); return true end
    if mode=='guild_relocate_end_confirm' then if m=='.stop' then r.guild_relocate=nil; clear_menu(d,r); save_data(d); send(name,'§e已取消换址。'); return true end; local s=r.guild_relocate; if util.timestamp()>(tonumber(s.end_deadline) or 0) then if m=='0' then s.end_deadline=util.timestamp()+180; save_data(d); send(name,'§e已续3分钟。'); return true else r.guild_relocate=nil; clear_menu(d,r); save_data(d); send(name,'§c换址流程超时。'); return true end end; if m=='0' then s.end_deadline=util.timestamp()+180; save_data(d); send(name,'§e已续3分钟。'); return true end; if m~='1' then send(name,'§c请输入1确定或0续时间。'); return true end; return guild_finish_relocate(name) end
    if mode=='guild_manage' then
        local n=tonumber(m); if n==1 then return guild_facility_set('tp',name) elseif n==2 then return guild_facility_set('warehouse',name) elseif n==3 then set_menu(d,r,'guild_notice_input'); send(name,'§e请输入公告内容：'); return true elseif n==4 then return guild_relocate_start(name) elseif n==5 then return guild_delete_territory(name,false) elseif n==6 then return guild_dissolve(name) elseif n==7 then send(name,'§5外交：中立 / 友好 / 同盟 / 敌对。正式关系需双方确认。'); return true elseif n==8 then send(name,'§e重大事项投票：会长与副会长可参与；输入 .公会投票 1 / 0。'); return true elseif n==9 then return guild_generate_invite(name) elseif n==10 then return guild_admin_menu(name) end; send(name,'§c请输入1~10。'); return true end
    if mode=='guild_admin' then
        local n=tonumber(m); if n==1 then return guild_list(name) elseif n==2 then set_menu(d,r,'guild_admin_dissolve'); send(name,'§e请输入公会ID，例如 G0001：'); return true elseif n==3 then set_menu(d,r,'guild_admin_delete_territory'); send(name,'§e请输入公会ID：'); return true elseif n==4 then local lg=guild_load(GUILD_LOG_FILE,{logs={}}); local lines={'§c✦ 最近公会管理日志 ✦'}; for i=math.max(1,#lg.logs-20),#lg.logs do local v=lg.logs[i]; lines[#lines+1]=string.format('§7%s §f[%s] %s §8%s',patch_beijing_fmt(v.at),v.type,v.actor or '',v.detail or '') end; send(name,table.concat(lines,'\n')); return true elseif n==5 then return guild_commands_menu(name) end; send(name,'§c请输入1~5。'); return true end
    if mode=='guild_admin_dissolve' then if m=='.stop' then clear_menu(d,r); return true end; clear_menu(d,r); return guild_admin_force_dissolve(name,m) end
    if mode=='guild_admin_delete_territory' then if m=='.stop' then clear_menu(d,r); return true end; local gd=guild_load(GUILD_FILE,{items={}}); local g=gd.items[m]; if not g then send(name,'§c公会不存在。'); return true end; g.territory=nil; g.teleport_point=nil; g.warehouse_point=nil; gd.items[m]=g; guild_save(GUILD_FILE,gd); guild_log(m,'管理员强制删除领地',name,'公会领地已解除'); clear_menu(d,r); send(name,'§a已删除公会「'..g.name..'」的领地保护，已恢复重新选址资格。'); return true end
    if mode=='guild_notice_input' and m~='' then return guild_post_notice(name,m) end
    return _r3_old_guild_handle(name,msg)
end

-- ---------- R3 聊天入口：邀请码、领地换址、管理员 ----------
local _r3_old_on_chat=on_chat
function on_chat(playerName,msg)
    local raw=tostring(msg or ''); local low=lower(trim(raw))
    if low=='.公会后台' or low=='.工会后台' then return guild_admin_menu(playerName) end
    if low=='.公会邀请码' or low=='.工会邀请码' then return guild_generate_invite(playerName) end
    if low=='.金币排行' or low=='.金币排行榜' then return coin_leaderboard(playerName,10) end
    if low=='.聊天日志状态' then if not is_admin(playerName) then send(playerName,'§c仅管理员。'); return true end; return patch_chat_log_status(playerName) end
    return _r3_old_on_chat(playerName,msg)
end

