    local ret=nil
    if type(_r3_old_init)=='function' then local ok,r=pcall(_r3_old_init); if ok then ret=r end end
    pcall(guild_init_files)
    pcall(ensure_patch_prompt_files)
    pcall(patch_sidebar_update,true)
    return ret
end


