PATCH_BUILD_TAG = "主体修复版-2026-09-26-R4"
CMD_CONTAINER_TICK=999999

-- ---------- TXT 命令容器：真正接通导入流程 ----------
function cmd_container_import(name,file_name)
    file_name=trim(tostring(file_name or ''))
    file_name=file_name:gsub('^%.+','')
    if file_name=='' then send(name,'§e用法：.命令容器导入 文件名.txt'); return true end
    local nodes,path=cmd_container_load_txt(name,file_name)
    if not nodes then send(name,'§c'..tostring(path)); return true end
    local d=cmd_container_db(); local id=tonumber(d.next_id or 1); d.next_id=id+1
    d.items[tostring(id)]={id=id,name=file_name,type=(nodes[1] and nodes[1].kind) or 'chain',enabled=false,nodes=nodes,source=path,created_at=util.timestamp()}
    cmd_container_save(d)
    send(name,'§a✦ TXT 已导入命令容器 #'..tostring(id)..'\n§f节点：§e'..tostring(#nodes)..'\n§7来源：'..tostring(path)..'\n§7当前状态：停止，可从 .命令容器 菜单启动。')
    return true
end
function cmd_container_toggle(name,id,on)
    if not is_admin(name) then send(name,'§c只有管理员可以启动/停止命令容器。'); return true end
    local d=cmd_container_db(); local v=d.items[tostring(id)]
    if not v then send(name,'§c容器不存在。'); return true end
    v.enabled=(on==nil) and not v.enabled or on
    cmd_container_save(d); send(name,'§a容器 #'..tostring(id)..' 已'..(v.enabled and '启动' or '停止')..'。'); return true
end
function cmd_container_show(name)
    local d=cmd_container_db(); local lines={'§8§m━━━━━━━━━━━━━━━━━━━━━━━━','§b✦ §l命令容器 §b✦','§8§m━━━━━━━━━━━━━━━━━━━━━━━━','§f① TXT导入','§f② 容器列表','§f③ 启动/停止容器','§7格式示例：[循环][无条件] say 你好'}
    local n=0; for id,v in pairs(d.items or {}) do n=n+1; if n<=8 then lines[#lines+1]='§7#'..id..' §e'..tostring(v.name)..' §8| '..(v.enabled and '§a运行' or '§c停止')..' §8| 节点'..tostring(#(v.nodes or {})) end end
    local pd,pr=player_record(name,true); set_menu(pd,pr,'cmd_container_main'); send(name,table.concat(lines,'\n')); return true
end

-- ---------- 公告/日志 ----------
function guild_post_notice(name,text)
    local g=guild_find_player(name); if not g then send(name,'§c你还没有加入公会。'); return true end
    local role=guild_member_role(g,name); if role~='owner' and role~='deputy' and not is_admin(name) then send(name,'§c只有会长、副会长或管理员可以发布公告。'); return true end
    local nd=guild_load(GUILD_NOTICE_FILE,{guilds={}}); nd.guilds[g.id]=nd.guilds[g.id] or {}; table.insert(nd.guilds[g.id],{at=util.timestamp(),by=name,text=tostring(text or '')}); while #nd.guilds[g.id]>30 do table.remove(nd.guilds[g.id],1) end; guild_save(GUILD_NOTICE_FILE,nd); guild_log(g.id,'发布公告',name,text); guild_announcement(name); return true
end

-- ---------- 公会投票：会长/副会长真正可投，解散也纳入重大决策 ----------
function guild_vote_start(name,subject,kind)
    local g=guild_find_player(name); if not g then send(name,'§c公会不存在。'); return true end
    local role=guild_member_role(g,name); if role~='owner' and role~='deputy' and not is_admin(name) then send(name,'§c只有会长或副会长可以发起重大决策投票。'); return true end
    if is_admin(name) then return guild_admin_force_dissolve(name,g.id) end
    local vd=guild_load(GUILD_VOTE_FILE,{votes={}}); vd.votes=vd.votes or {}
    local id=tostring(#vd.votes+1); vd.votes[id]={id=id,guild_id=g.id,subject=subject,kind=kind,started_at=util.timestamp(),expire_at=util.timestamp()+300,yes={},no={},status='open'}; guild_save(GUILD_VOTE_FILE,vd); guild_log(g.id,'发起投票',name,subject); send(name,'§a投票已发起：'..subject..'\n§7管理层成员输入 1 支持、0 反对。5分钟截止。'); return true
end
function guild_vote_cast(name,value)
    local vd=guild_load(GUILD_VOTE_FILE,{votes={}}); local target=nil
    for i=#(vd.votes or {}),1,-1 do local v=vd.votes[i]; if v.status=='open' then target=v; break end end
    if not target or util.timestamp()>tonumber(target.expire_at or 0) then send(name,'§c当前没有进行中的公会投票。'); return true end
    local g=guild_load(GUILD_FILE,{items={}}).items[target.guild_id]; if not g then return true end
    local role=guild_member_role(g,name); if role~='owner' and role~='deputy' then send(name,'§c只有会长和副会长可以投票。'); return true end
    local u=uuid_key(name); target.yes[u]=nil; target.no[u]=nil; if tostring(value)=='1' then target.yes[u]=true else target.no[u]=true end
    local eligible=0; for _,m in ipairs(g.members or {}) do if m.role=='owner' or m.role=='deputy' then eligible=eligible+1 end end
    local cast=0; for _ in pairs(target.yes or {}) do cast=cast+1 end; for _ in pairs(target.no or {}) do cast=cast+1 end
    if cast>=eligible and eligible>0 then
        local y,nc=0,0; for _ in pairs(target.yes or {}) do y=y+1 end; for _ in pairs(target.no or {}) do nc=nc+1 end
        target.status=(y>nc) and 'passed' or 'rejected'; target.finished_at=util.timestamp(); guild_save(GUILD_VOTE_FILE,vd)
        if target.status=='passed' and target.kind=='dissolve' then guild_admin_force_dissolve(name,g.id) else guild_log(g.id,'投票结束',name,'结果='..target.status..'；支持='..y..'；反对='..nc) end
        send(name,'§a投票已结算：'..(target.status=='passed' and '通过' or '未通过'))
    else
        guild_save(GUILD_VOTE_FILE,vd); send(name,'§a✓ 已记录投票：'..(tostring(value)=='1' and '支持' or '反对'))
    end
    return true
end

function guild_dissolve(name)
    local g=guild_find_player(name); if not g then send(name,'§c公会不存在。'); return true end
    if is_admin(name) then return guild_admin_force_dissolve(name,g.id) end
    if guild_member_role(g,name)~='owner' then return guild_vote_start(name,'解散公会「'..g.name..'」','dissolve') end
    return guild_vote_start(name,'解散公会「'..g.name..'」','dissolve')
end

-- ---------- 管理员菜单 bug 修正 ----------
function guild_admin_menu(name)
    if not is_admin(name) then send(name,'§c只有管理员可以打开公会管理后台。'); return true end
    local d,r=player_record(name,true); set_menu(d,r,'guild_admin'); save_data(d)
    send(name,table.concat({'§c§l✦ 公 会 管 理 后 台 ✦','§f① 公会列表','§f② 强制解散公会','§f③ 强制删除公会领地','§f④ 查看日志','§f⑤ 返回公会大厅'},'\n')); return true
end

-- ---------- 命令容器菜单/直接指令 ----------
local _r4_old_on_chat=on_chat
function on_chat(playerName,msg)
    local raw=tostring(msg or ''); local low=lower(trim(raw))
    local import_name=raw:match('^%.命令容器导入%s+(.+)$') or raw:match('^%.命令方块容器导入%s+(.+)$')
    if import_name then return cmd_container_import(playerName,trim(import_name)) end
    local toggle_id,toggle_val=raw:match('^%.命令容器%s+(%d+)%s+(开|关)$')
    if toggle_id then return cmd_container_toggle(playerName,tonumber(toggle_id),toggle_val=='开') end
    local vote=raw:match('^%.公会投票%s*([01])$'); if vote then return guild_vote_cast(playerName,vote) end
    local stop=low=='.stop'
    local d,r=player_record(playerName,true)
    if r and r.menu=='cmd_container_main' and not stop then
        local n=tonumber(trim(raw)); if n==1 then set_menu(d,r,'cmd_container_import'); send(playerName,'§e请输入TXT文件名：例如 示例_循环链式.txt'); return true end
        if n==2 then cmd_container_show(playerName); return true end
        if n==3 then set_menu(d,r,'cmd_container_toggle'); send(playerName,'§e请输入：编号 开 / 编号 关'); return true end
        if n==4 then send(playerName,'§e使用 .命令容器导入 文件名.txt 创建容器。'); return true end
    elseif r and r.menu=='cmd_container_import' then if stop then clear_menu(d,r); return true end; return cmd_container_import(playerName,trim(raw))
    elseif r and r.menu=='cmd_container_toggle' then if stop then clear_menu(d,r); return true end; local id,v=raw:match('^(%d+)%s+(开|关)$'); if id then return cmd_container_toggle(playerName,tonumber(id),v=='开') end; send(playerName,'§c格式：编号 开 或 编号 关'); return true end
    return _r4_old_on_chat(playerName,msg)
end

-- ---------- 最终性能调度：领地保护8秒、活跃/TPS60秒、命令容器5秒 ----------
local _r4_old_v17=v17_event_tick
function v17_event_tick()
    local result=true
    if type(_r4_old_v17)=='function' then local ok,r=pcall(_r4_old_v17); if ok then result=r end end
    local now=util.timestamp()
    PATCH_GUILD_PROTECT_LAST=tonumber(PATCH_GUILD_PROTECT_LAST) or 0
    PATCH_GUILD_ACTIVITY_LAST=tonumber(PATCH_GUILD_ACTIVITY_LAST) or 0
    if now-PATCH_GUILD_PROTECT_LAST>=8 then PATCH_GUILD_PROTECT_LAST=now; pcall(guild_protect_tick) end
    if now-PATCH_GUILD_ACTIVITY_LAST>=60 then PATCH_GUILD_ACTIVITY_LAST=now; pcall(guild_activity_tick) end
    if now-(PATCH_SIDEBAR_LAST or 0)>=60 then pcall(patch_sidebar_update) end
    if now-(PATCH_CMD_CONTAINER_LAST or 0)>=5 then pcall(v17_cmd_container_safe_tick) end
    return result
end

-- ---------- .help 15 / 公会搜索关键词 / 邀请入口 ----------
local _r4_old_help_open=patch_help_open
function patch_help_open(name,n)
    if tonumber(n)==15 then return guild_commands_menu(name) end
    return _r4_old_help_open(name,n)
end

-- ---------- 初始化 ----------
local _r4_old_init=on_init
function on_init()
    local ret=nil
    if type(_r4_old_init)=='function' then local ok,r=pcall(_r4_old_init); if ok then ret=r end end
    CMD_CONTAINER_TICK=999999
    pcall(guild_init_files); pcall(ensure_patch_prompt_files); pcall(patch_sidebar_update,true)
    return ret
end


