function guild_public_detail(name,gid)
    local gd=guild_load(GUILD_FILE,{items={}}); local g=gd.items[tostring(gid or '')]
    if not g or g.status=='dissolved' then send(name,'§c公会不存在。'); return true end
    local nd=guild_load(GUILD_NOTICE_FILE,{guilds={}}); local arr=nd.guilds[g.id] or {}; local latest=arr[#arr]
    local lines={'§8§m━━━━━━━━━━━━━━━━━━━━','§d✦『'..g.name..'』公会信息','§8§m━━━━━━━━━━━━━━━━━━━━','§f等级：§eLv.'..tostring(g.level or 1)..' · '..guild_level_title(g.level),'§f会长：§e'..tostring(g.owner_name or g.owner or '未知'),'§f成员：§b'..tostring(#(g.members or {}))..'/'..tostring(guild_max_members(g.level)),'§f在线：§a'..tostring(guild_online_count(g)),'§f公会资金：§6'..tostring(g.funds or 0),'§f公会活跃：§d'..tostring(g.activity_total or 0),'§f公告：§7'..tostring(latest and latest.text or '暂无公告'),'§7领地、仓库、传送点坐标不会对外显示。'}
    send(name,table.concat(lines,'\n')); return true
end

function guild_accept_invite(name,code)
    local existing=guild_find_player(name); if existing then send(name,'§c你已经加入「'..existing.name..'」。'); return true end
    local g=guild_find_by_invite(code)
    if not g then send(name,'§c邀请码不存在或已失效。'); return true end
    if #(g.members or {})>=guild_max_members(g.level) then send(name,'§c该公会成员名额已满。'); return true end
    g.members=g.members or {}; g.members[#g.members+1]={uuid=uuid_key(name),name=name,role='member',contribution=0,joined_at=util.timestamp(),activity=0}
    local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    guild_mark_history(name,g.id,'member'); guild_log(g.id,'加入公会',name,'邀请码='..tostring(code))
    send(name,'§a✦ 已加入公会「'..g.name..'」！'); guild_commands_menu(name); return true
end

function guild_search_player(name,q)
    q=lower(trim(q or '')); local gd=guild_load(GUILD_FILE,{items={}}); local results={}; local lines={'§8§m━━━━━━━━━━━━━━━━━━━━━━━━','§e✦ 玩家所属公会搜索 ✦','§8§m━━━━━━━━━━━━━━━━━━━━━━━━'}
    if q=='' then send(name,'§c关键词不能为空。'); return true end
    for _,g in pairs(gd.items or {}) do if g.status~='dissolved' then for _,m in pairs(g.members or {}) do if lower(tostring(m.name or '')):find(q,1,true) then results[#results+1]={name=m.name,gid=g.id,role=m.role}; end end end end
    table.sort(results,function(a,b) return tostring(a.name)<tostring(b.name) end)
    for i,v in ipairs(results) do if i>20 then break end; lines[#lines+1]=string.format('§f%d. §e%s §8▸ §d%s §7（%s）',i,v.name,tostring((gd.items[v.gid] or {}).name or '?'),tostring(v.role)) end
    if #results==0 then lines[#lines+1]='§7没有找到匹配玩家。' else lines[#lines+1]='§7输入编号可查看对应公会信息。' end
    local d,r=player_record(name,true); r.guild_search_players=results; set_menu(d,r,'guild_search_player_results'); send(name,table.concat(lines,'\n')); return true
end

-- ---------- 公会任务：最小可用日常 ----------
function guild_task_today(g)
    local day=os.date('!%Y-%m-%d',util.timestamp()+8*3600); local td=guild_load(GUILD_TASK_FILE,{guilds={}}); td.guilds=td.guilds or {}; local t=td.guilds[g.id]
    if type(t)~='table' or t.day~=day then t={day=day,signins=0,online_minutes=0,claimed=false}; td.guilds[g.id]=t; guild_save(GUILD_TASK_FILE,td) end
    return t,td
end
function guild_task_menu(name)
    local g=guild_find_player(name); if not g then send(name,'§c你还没有加入公会。'); return true end
    local t=guild_task_today(g); local needSign=5; local needOnline=60; local eligible=(tonumber(t.signins or 0)>=needSign and tonumber(t.online_minutes or 0)>=needOnline)
    send(name,'§b✦ 今日公会任务 ✦\n§f签到人数：§e'..tostring(t.signins or 0)..'/'..needSign..'\n§f在线分钟：§e'..tostring(t.online_minutes or 0)..'/'..needOnline..'\n§f状态：'..(t.claimed and '§7已领取' or (eligible and '§a可领取' or '§7进行中'))..'\n§7完成后输入1领取奖励。')
    local d,r=player_record(name,true); set_menu(d,r,'guild_task_claim'); return true
end
function guild_task_claim(name,msg)
    local g=guild_find_player(name); if not g then return true end; local t,td=guild_task_today(g); if tostring(msg)~='1' then send(name,'§e输入1领取完成任务奖励，.stop退出。'); return true end; if t.claimed then send(name,'§7今日任务已经领取。'); return true end
    if tonumber(t.signins or 0)<5 or tonumber(t.online_minutes or 0)<60 then send(name,'§c任务尚未完成。'); return true end
    t.claimed=true; td.guilds[g.id]=t; guild_save(GUILD_TASK_FILE,td); guild_progress(g,name,100,50,200); local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd); send(name,'§a✦ 公会任务完成！\n§e贡献 +50\n§b公会经验 +100\n§6公会资金 +200'); return true
end

-- 更新活动统计时同时推进当天公会在线任务和签到计数。
local _r5_old_activity_tick=guild_activity_tick
function guild_activity_tick()
    if type(_r5_old_activity_tick)=='function' then pcall(_r5_old_activity_tick) end
    local gd=guild_load(GUILD_FILE,{items={}}); local ok,list=pcall(game.getOnlinePlayers); local online={}
    if ok and type(list)=='table' then for _,v in pairs(list) do local nm=type(v)=='table' and tostring(v.name or v.playerName or '') or tostring(v); if nm~='' then online[uuid_key(nm)]=true end end end
    for _,g in pairs(gd.items or {}) do if g.status~='dissolved' then local t,td=guild_task_today(g); local min=0; for _,m in ipairs(g.members or {}) do if online[tostring(m.uuid)] then min=min+1 end end; t.online_minutes=tonumber(t.online_minutes or 0)+min; local count=0; for _,m in ipairs(g.members or {}) do local u=tostring(m.uuid); local sg=g.signins and g.signins[u]; if sg and sg.day==t.day then count=count+1 end end; t.signins=count; td.guilds[g.id]=t; guild_save(GUILD_TASK_FILE,td) end end
end

-- ---------- 菜单最终接线：修正搜索/任务/管理 ----------
local _r5_old_guild_handle=guild_handle_menu
function guild_handle_menu(name,msg)
    local d,r=player_record(name,true); local mode=r and r.menu or ''; local m=trim(msg)
    if mode=='guild_task_claim' then if m=='.stop' then clear_menu(d,r); return true end; return guild_task_claim(name,m) end
    if mode=='guild_search_player_results' then if m=='.stop' then clear_menu(d,r); return true end; local n=tonumber(m); local v=r.guild_search_players and r.guild_search_players[n]; if v then clear_menu(d,r); return guild_public_detail(name,v.gid) end; send(name,'§c请输入搜索结果编号。'); return true end
    if mode=='guild_first' or mode=='guild_return_main' then
        if m=='.stop' then clear_menu(d,r); return true end
        local n=tonumber(m)
        if n==1 then return guild_creation_start(name) elseif n==2 then return guild_list(name) elseif n==3 then set_menu(d,r,'guild_search_name'); send(name,'§e请输入公会名称关键词：'); return true elseif n==4 then set_menu(d,r,'guild_search_player'); send(name,'§e请输入玩家名称关键词：'); return true elseif n==5 then set_menu(d,r,'guild_invite_accept'); send(name,'§e请输入邀请码：'); return true elseif n==6 then return guild_list(name) elseif n==7 then return guild_rankings(name,'level') elseif n==8 then return guild_rankings(name,'activity') elseif n==9 and mode=='guild_return_main' then guild_generate_invite(name); return true end
        send(name,'§c请输入有效编号。'); return true
    end
    if mode=='guild_main' then
        local n=tonumber(m); if n==4 then clear_menu(d,r); return guild_task_menu(name) end
    end
    if mode=='guild_search_name' then local gd=guild_load(GUILD_FILE,{items={}}); local results={}; local q=lower(m); local lines={'§b✦ 公会搜索 ✦'}; for _,g in pairs(gd.items or {}) do if g.status~='dissolved' and q~='' and lower(tostring(g.name)):find(q,1,true) then results[#results+1]=g end end; table.sort(results,function(a,b) return tostring(a.name)<tostring(b.name) end); for i,g in ipairs(results) do if i>20 then break end; lines[#lines+1]=string.format('§f%d. §e%s §7Lv.%s §8| 在线%s/%s',i,g.name,tostring(g.level or 1),guild_online_count(g),guild_max_members(g.level)) end; if #results==0 then lines[#lines+1]='§7没有找到匹配公会。' end; r.guild_search_guilds=results; set_menu(d,r,'guild_search_guild_results'); send(name,table.concat(lines,'\n')); return true end
    if mode=='guild_search_guild_results' then local n=tonumber(m); local g=r.guild_search_guilds and r.guild_search_guilds[n]; if g then clear_menu(d,r); return guild_public_detail(name,g.id) end; send(name,'§c请输入搜索结果编号。'); return true end
    if mode=='guild_task_claim' then return guild_task_claim(name,m) end
    if mode=='guild_main' and m=='.stop' then clear_menu(d,r); return true end
    return _r5_old_guild_handle(name,msg)
end

