PATCH_BUILD_TAG = "主体修复版-2026-09-26-R7"

-- ---------- 背包：统一真实回执链，兼容数组/对象型 items ----------
function patch_inventory_items_normalize(inv)
    if type(inv)~="table" then return nil end
    local raw=inv.items
    if type(raw)~="table" then return nil end
    local out={}
    for k,v in pairs(raw) do
        if type(v)=="table" then
            local cnt=tonumber(v.count or v.Count or v.stackSize or v.quantity or v.amount or 0) or 0
            local nm=v.name or v.Name or v.id or v.Identifier
            if nm and tostring(nm)~="" and cnt>0 then
                out[#out+1]={slot=v.slot or v.Slot or tonumber(k) or #out,name=tostring(nm),count=cnt,damage=tonumber(v.damage or v.Damage or v.aux or 0) or 0,enchantments=v.enchantments}
            end
        end
    end
    table.sort(out,function(a,b) return (tonumber(a.slot) or 0)<(tonumber(b.slot) or 0) end)
    return out
end

function patch_inventory_query_real(nm)
    local safe=string.gsub(tostring(nm or ""),'"','\\"')
    local candidates={
        {fn=function() return player.getInventory(tostring(nm)) end,src="player.getInventory(name)"},
        {fn=function() return game.queryInventory('@a[name="'..safe..'"]') end,src="game.queryInventory(selector)"},
        {fn=function() return game.queryInventory(tostring(nm)) end,src="game.queryInventory(name)"},
    }
    local last=""
    for _,c in ipairs(candidates) do
        local ok,inv=pcall(c.fn)
        if ok then
            local items=patch_inventory_items_normalize(inv)
            if items~=nil then return true,{items=items},c.src end
        end
        last=tostring(inv or last)
    end
    return false,nil,"背包实时接口均未返回合法数据："..last
end

function ai_inventory_sync(playerName,targetText,admin)
    local targets=inv_parse_targets(targetText,playerName)
    local allowed,denied={},{}
    for _,nm in ipairs(targets or {}) do
        nm=trim(tostring(nm or ""))
        if nm~="" then
            if admin or lower(nm)==lower(playerName) then allowed[#allowed+1]=nm else denied[#denied+1]=nm end
        end
    end
    if #denied>0 then return "权限限制：普通玩家只能查询自己的背包（已拒绝："..table.concat(denied,"、").."）。",false end
    if #allowed==0 then return "背包查询失败：没有有效玩家目标。",false end
    local out={"§b━━ 背包真实查询 ━━"}
    for _,nm in ipairs(allowed) do
        local ok,inv,src=patch_inventory_query_real(nm)
        out[#out+1]="§f玩家：§e"..nm
        if not ok then
            out[#out+1]="§c读取失败：没有收到真实背包数据。"
        else
            local items=inv.items or {}
            if #items==0 then
                out[#out+1]="§7背包为空。"
            else
                out[#out+1]="§7共 §e"..#items.." §7种物品"
                for i,it in ipairs(items) do
                    if i>54 then out[#out+1]="§7……还有更多物品未显示。"; break end
                    out[#out+1]=string.format("§f%02d. %s ×%s §8(槽位%s)",i,item_display_name(it.name,it.damage),tostring(it.count or 0),tostring(it.slot or "?"))
                end
            end
            out[#out+1]="§8读取接口："..tostring(src)
        end
    end
    return table.concat(out,"\n"),true
end

