end

function market_public_list_v2(page)
    local db=market_db(); local a={}
    for _,v in pairs(db.listings or {}) do if not v.disabled and not v.shop_banned and not v.sold then a[#a+1]=v end end
    table.sort(a,function(x,y)return (tonumber(x.id)or 0)<(tonumber(y.id)or 0)end)
    local per=13; local maxp=math.max(1,math.ceil(#a/per)); page=math.max(1,math.min(tonumber(page)or 1,maxp)); local first=(page-1)*per+1; local last=math.min(#a,first+per-1)
    local out={"§b━━ 玩家商品 ━━","§7第 "..page.." / "..maxp.." 页"}; local shown={}
    for i=first,last do local v=a[i]; shown[#shown+1]=v; local rc=(db.reports and db.reports[tostring(v.id)] and tonumber(db.reports[tostring(v.id)].count))or 0; out[#out+1]=string.format("§f%d. §e%s",i,tostring(v.name)); out[#out+1]=string.format("§7  价格：§6%s积分 §7| 商家等级：§a%s",tostring(v.price),shop_level(v.sold_count)); out[#out+1]=string.format("§7  商家：§b%s%s",tostring(v.seller),rc>0 and " §c⚠"..rc or "") end
    if #a==0 then out[#out+1]="§e当前没有玩家商品。" end
    out[#out+1]="§7输入商品编号查看真实物品；+ 下一页；- 上一页；.stop 退出。"
    return out,shown,page,maxp
end

-- ---------- 公会等级：按成员数量设置升级门槛，避免Lv.2死锁 ----------
function guild_required_members(lv)
    local n=tonumber(lv) or 1
    local req={[1]=1,[2]=3,[3]=5,[4]=8,[5]=12,[6]=16,[7]=20,[8]=25,[9]=30,[10]=35}
    return req[math.max(1,math.min(10,n))] or 35
end
function guild_progress(g,name,exp,contrib,funds)
    exp=math.max(0,math.floor(tonumber(exp) or 0)); contrib=math.max(0,math.floor(tonumber(contrib) or 0)); funds=math.max(0,math.floor(tonumber(funds) or 0))
    g.exp=tonumber(g.exp or 0)+exp; g.funds=tonumber(g.funds or 0)+funds; g.total_contribution=tonumber(g.total_contribution or 0)+contrib
    for _,m in ipairs(g.members or {}) do if uuid_key(m.name)==uuid_key(name) then m.contribution=tonumber(m.contribution or 0)+contrib; break end end
    while (tonumber(g.level) or 1)<10 do
        local lv=tonumber(g.level) or 1; local need=guild_exp_need(lv); local cost=guild_upgrade_cost(lv)
        if (tonumber(g.exp) or 0)<need or (tonumber(g.funds) or 0)<cost then break end
        if #(g.members or {}) < guild_required_members(lv+1) then break end
        g.exp=g.exp-need; g.funds=g.funds-cost; g.level=lv+1; g.title=guild_level_title(g.level); g.max_members=guild_max_members(g.level); g.level_up_at=util.timestamp(); g.level_unlocks=g.level_unlocks or {}
        guild_log(g.id,"公会升级","系统","Lv."..lv.." → Lv."..g.level.."，消耗资金"..cost.."，成员门槛"..guild_required_members(g.level))
    end
end

-- ---------- 公会发展路线：真正可切换、以功能解锁为主 ----------
function guild_development_menu(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    send(name,table.concat({"§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━","§6§l✦ 公 会 发 展 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━","§f当前路线：§e"..tostring(g.development or "城建"),"§f切换路线需要：§6"..guild_upgrade_cost(g.level or 1).." 公会资金","§b① 城建 §7— 领地/仓库/设施","§6② 商业 §7— 资金获取/经济任务","§a③ 冒险 §7— 高级任务/活动","§d④ 荣耀 §7— 称号/排行/成就","§7路线可以重复调整，但每次都会消耗公会资金。","§7.stop 退出"},"\n")); local d,r=player_record(name,true); set_menu(d,r,"guild_development"); return true
end
function guild_set_development(name,n)
    local g=guild_find_player(name); if not g then return true end
    local role=guild_member_role(g,name); if role~="owner" and role~="deputy" and not is_admin(name) then send(name,"§c只有会长/副会长可以调整发展路线。"); return true end
    local map={["1"]="城建",["2"]="商业",["3"]="冒险",["4"]="荣耀"}; local route=map[tostring(n)]
    if not route then send(name,"§c请输入1~4。"); return true end
    local cost=math.max(0,guild_upgrade_cost(g.level or 1)); if not is_admin(name) and (tonumber(g.funds)or 0)<cost then send(name,"§c公会资金不足，需要 "..cost.."。 "); return true end
    if not is_admin(name) then g.funds=(tonumber(g.funds)or 0)-cost end; g.development=route
    local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd); guild_log(g.id,"切换发展路线",name,route.."；消耗="..(is_admin(name) and 0 or cost)); clear_menu(player_record(name,true)); send(name,"§a✦ 公会发展路线已切换为：§e"..route); return true
end

-- ---------- 公会投票：只有解散由管理员直接处理，其他事项真正发起投票 ----------
function guild_vote_start(name,subject,kind)
    local g=guild_find_player(name); if not g then send(name,"§c公会不存在。"); return true end
    local role=guild_member_role(g,name)
    if is_admin(name) and kind=="dissolve" then return guild_admin_force_dissolve(name,g.id) end
    if not is_admin(name) and role~="owner" and role~="deputy" then send(name,"§c只有会长/副会长可以发起重大决策投票。"); return true end
    local vd=guild_load(GUILD_VOTE_FILE,{votes={}}); vd.votes=vd.votes or {}
    local id=tostring(#vd.votes+1); vd.votes[id]={id=id,guild_id=g.id,subject=subject,kind=kind,initiator=name,started_at=util.timestamp(),expire_at=util.timestamp()+300,yes={},no={},status="open"}; guild_save(GUILD_VOTE_FILE,vd); guild_log(g.id,"发起投票",name,subject); send(name,"§a投票已发起："..subject.."\n§7会长/副会长输入 1 支持、0 反对，5分钟截止。"); return true
end
function guild_vote_cast(name,value)
    local vd=guild_load(GUILD_VOTE_FILE,{votes={}}); local target=nil
    for i=#(vd.votes or {}),1,-1 do local v=vd.votes[i]; if v.status=="open" then target=v; break end end
    if not target or util.timestamp()>tonumber(target.expire_at or 0) then send(name,"§c当前没有进行中的公会投票。"); return true end
    local g=guild_load(GUILD_FILE,{items={}}).items[target.guild_id]; if not g then return true end
    local role=guild_member_role(g,name); if role~="owner" and role~="deputy" then send(name,"§c只有会长和副会长可以投票。"); return true end
    local u=uuid_key(name); target.yes[u]=nil; target.no[u]=nil; if tostring(value)=="1" then target.yes[u]=true else target.no[u]=true end
    local eligible=0; for _,m in ipairs(g.members or {}) do if m.role=="owner" or m.role=="deputy" then eligible=eligible+1 end end
    local cast=0; for _ in pairs(target.yes or {}) do cast=cast+1 end; for _ in pairs(target.no or {}) do cast=cast+1 end
    if cast>=eligible and eligible>0 then
        local y,nc=0,0; for _ in pairs(target.yes or {}) do y=y+1 end; for _ in pairs(target.no or {}) do nc=nc+1 end
        target.status=(y>nc) and "passed" or "rejected"; target.finished_at=util.timestamp(); guild_save(GUILD_VOTE_FILE,vd)
        if target.status=="passed" and target.kind=="dissolve" then guild_apply_dissolve(g,name,"重大决策投票通过")
        elseif target.status=="passed" and target.kind=="relocate" then guild_relocate_start(target.initiator or name)
        else guild_log(g.id,"投票结束",name,"结果="..target.status.."；支持="..y.."；反对="..nc) end
        send(name,"§a投票已结算："..(target.status=="passed" and "通过" or "未通过"))
    else guild_save(GUILD_VOTE_FILE,vd); send(name,"§a✓ 已记录投票："..(tostring(value)=="1" and "支持" or "反对")) end
    return true
end

