-- ---------- 公会菜单最终处理 ----------
local _r7_prev_guild_handle=guild_handle_menu
function guild_handle_menu(name,msg)
    local d,r=player_record(name,true); local mode=r and r.menu or ""; local m=trim(msg)
    if mode=="guild_development" then if m==".stop" then clear_menu(d,r); return true end; return guild_set_development(name,m) end
    if mode=="guild_main" and m=="10" then return send(name,"§5✦ 外交大厅 ✦\n§7中立 / 友好 / 同盟 / 敌对\n§f使用 .公会外交 查看或设置关系。") or true end
    if mode=="guild_manage" then
        if m==".stop" then clear_menu(d,r); return true end
        local n=tonumber(m)
        if n==1 then return guild_facility_set("tp",name) end
        if n==2 then return guild_facility_set("warehouse",name) end
        if n==3 then set_menu(d,r,"guild_notice_input"); send(name,"§e请输入公告内容："); return true end
        if n==4 then return guild_relocate_start(name) end
        if n==5 then return guild_delete_territory(name,false) end
        if n==6 then return guild_dissolve(name) end
        if n==7 then send(name,"§5✦ 外交大厅 ✦\n§7中立 / 友好 / 同盟 / 敌对\n§f.公会外交 查看\n§f.公会外交 G0001 同盟"); return true end
        if n==8 then send(name,"§e重大事项投票：\n§f.公会投票 1 支持\n§f.公会投票 0 反对"); return true end
        if n==9 then return guild_generate_invite(name) end
        if n==10 then return guild_development_menu(name) end
        if n==11 and is_admin(name) then return guild_admin_menu(name) end
        send(name,"§c请输入有效编号。"); return true
    end
    return _r7_prev_guild_handle(name,msg)
end

-- ---------- 公会外交：真正保存双方关系 ----------
function guild_diplomacy_handle(name,target_id,relation)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    local role=guild_member_role(g,name); if role~="owner" and role~="deputy" and not is_admin(name) then send(name,"§c只有会长/副会长可以管理外交关系。"); return true end
    local gd=guild_load(GUILD_FILE,{items={}}); local target=gd.items[tostring(target_id or "")]; if not target or target.status=="dissolved" then send(name,"§c目标公会不存在。"); return true end
    if tostring(target.id)==tostring(g.id) then send(name,"§c不能与自己公会建立外交关系。"); return true end
    local rels={["中立"]=true,["友好"]=true,["同盟"]=true,["敌对"]=true}; if not rels[tostring(relation)] then send(name,"§c关系只能是：中立 / 友好 / 同盟 / 敌对"); return true end
    local dd=guild_load(GUILD_DIPLOMACY_FILE,{relations={}}); dd.relations=dd.relations or {}; dd.relations[g.id]=dd.relations[g.id] or {}; dd.relations[target.id]=dd.relations[target.id] or {}
    dd.relations[g.id][target.id]={relation=relation,by=name,at=util.timestamp(),status="pending"}; dd.relations[target.id][g.id]={relation=relation,by=name,at=util.timestamp(),status="pending"}; guild_save(GUILD_DIPLOMACY_FILE,dd)
    send(name,"§a外交请求已发出：§e"..target.name.." §7→ §d"..relation.."。\n§7对方会长/副会长确认后正式生效。"); return true
end
function guild_diplomacy_accept(name,target_id)
    local g=guild_find_player(name); if not g then return true end
    local role=guild_member_role(g,name); if role~="owner" and role~="deputy" then send(name,"§c只有会长/副会长可以确认外交关系。"); return true end
    local dd=guild_load(GUILD_DIPLOMACY_FILE,{relations={}}); local mine=dd.relations and dd.relations[g.id] or {}; local rec=mine[tostring(target_id or "")]; if type(rec)~="table" or rec.status~="pending" then send(name,"§c没有找到该公会的待确认外交请求。"); return true end
    rec.status="active"; mine[tostring(target_id)]=rec; dd.relations[g.id]=mine; local other=dd.relations[tostring(target_id)] or {}; other[g.id]=rec; dd.relations[tostring(target_id)]=other; guild_save(GUILD_DIPLOMACY_FILE,dd); send(name,"§a外交关系已确认：§e"..tostring(target_id).." §7→ §d"..tostring(rec.relation)); return true
end
function guild_diplomacy_menu(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    local dd=guild_load(GUILD_DIPLOMACY_FILE,{relations={}}); local rel=dd.relations and dd.relations[g.id] or {}; local lines={"§5✦ 外交大厅 ✦"}; local n=0
    for gid,r in pairs(rel or {}) do n=n+1; local gd=guild_load(GUILD_FILE,{items={}}); local tg=gd.items[gid]; lines[#lines+1]=string.format("§f%s §8→ §d%s §7(%s)",tostring(tg and tg.name or gid),tostring(r.relation),tostring(r.status)) end
    if n==0 then lines[#lines+1]="§7暂无外交关系。" end
    lines[#lines+1]="§7用法：.公会外交 G0001 同盟 / .公会外交确认 G0001"; send(name,table.concat(lines,"\n")); return true
end

-- ---------- 普通签到/公会签到：AI奖励都走同一安全奖励池 ----------
function final_ai_signin_reward()
    local rewards={{id="bread",count=6,text="面包 ×6"},{id="torch",count=12,text="火把 ×12"},{id="iron_ingot",count=3,text="铁锭 ×3"},{id="cooked_beef",count=5,text="熟牛肉 ×5"},{id="experience_bottle",count=2,text="经验瓶 ×2"},{id="golden_carrot",count=2,text="金胡萝卜 ×2"}}
    local idx=tonumber(choose_signin_reward and choose_signin_reward() or 1) or 1; idx=math.max(1,math.min(#rewards,idx)); return rewards[idx]
end
function guild_signin(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    local today=os.date("!%Y-%m-%d",util.timestamp()+8*3600); g.signins=g.signins or {}; local u=uuid_key(name); g.signins[u]=g.signins[u] or {}
    if g.signins[u].day==today then send(name,"§e你今天已经签到过了。"); return true end
    local reward=final_ai_signin_reward(); g.signins[u].day=today; g.signins[u].count=tonumber(g.signins[u].count or 0)+1
    guild_progress(g,name,10,20,20); local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    pcall(game.sendCommand,'give "'..string.gsub(name,'"','\\"')..'" minecraft:'..reward.id..' '..reward.count)
    send(name,"§d✦ 公会每日签到成功 ✦\n§fAI今日奖励：§e"..reward.text.."\n§e贡献 +20  §b公会经验 +10  §6公会资金 +20"); return true
end

-- ---------- 自备份：只允许恢复我们自己产生的快照，不使用云端旧备份 ----------
BACKUP_INDEX_FILE=game.dataDir().."/SELF_BACKUPS.txt"
function self_backup_now(name)
    if not is_admin(name) then send(name,"§c只有管理员可以创建插件快照。"); return true end
    local stamp=os.date("!%Y%m%d_%H%M%S",util.timestamp()+8*3600); local dd=game.dataDir(); local code=plugin_code_dir(); local base=plugin_base_dir(); local prefix=dd.."/self_backup_"..stamp.."_"
    local files={
        {src=code.."/main.lua",dst=prefix.."main.lua"},{src=code.."/manifest.json",dst=prefix.."manifest.json"},{src=code.."/docs.md",dst=prefix.."docs.md"},
        {src=code.."/seg_core.txt",dst=prefix.."seg_core.txt"},{src=code.."/seg_cmd.txt",dst=prefix.."seg_cmd.txt"},{src=code.."/seg_build.txt",dst=prefix.."seg_build.txt"},{src=code.."/seg_mcp.txt",dst=prefix.."seg_mcp.txt"},{src=code.."/seg_review.txt",dst=prefix.."seg_review.txt"},
        {src=base.."/插件配置文件/ds_ai_agent/ds_ai_agent.json",dst=prefix.."config.json"},
    }
    local data_files={"ds_data.json","market.json","market_items_nbt.json","market_item_previews.json","market_storage.json","market_wallet.json","market_offline_notices.json","nbt_regions.json","territories.json","purchase_logs.json","shop_logs.json","chat_logs.json","server_announcement.json","server_announcement_lines.json","command_containers.json","ai_global_rules.json","ai_last_trace.json","ai_personas.json","agent_providers.json","inv_request.json","death_lastpos.json","death_dedup.json","death_samples.json"}
    for _,f in ipairs(data_files) do files[#files+1]={src=dd.."/"..f,dst=prefix.."data_"..f:gsub("/","_")} end
    for _,f in ipairs({"guild/guilds.json","guild/players.json","guild/logs.json","guild/votes.json","guild/tasks.json","guild/diplomacy.json","guild/notices.json","guild/activity.json","guild/VERSION.txt","command_txt/示例_循环链式.txt"}) do files[#files+1]={src=dd.."/"..f,dst=prefix.."data_"..f:gsub("/","_")} end
    local okc=0
    for _,f in ipairs(files) do local ok,v=pcall(util.read_file,f.src); if ok and type(v)=="string" then if pcall(util.write_file,f.dst,v) then okc=okc+1 end end end
    local line=stamp.." | "..okc.." files | plugin="..tostring(plugin_id_now()).."\n"; local old=pcall(util.read_file,BACKUP_INDEX_FILE) and util.read_file(BACKUP_INDEX_FILE) or ""; pcall(util.write_file,BACKUP_INDEX_FILE,tostring(old)..line)
    send(name,"§a✦ 已创建自己的完整文本快照：§e"..stamp.."\n§7文件数：§f"..okc.."\n§7后续回滚只允许使用本插件自己生成的快照。")
    return true
end

-- ---------- `.备份` / `.公会外交` / 市场最终入口 ----------
local _r7_prev_on_chat=on_chat
function on_chat(playerName,msg)
    local raw=tostring(msg or ""); local low=lower(trim(raw)); local d,r=player_record(playerName,true)
    if low==".备份" or low=="备份" then return self_backup_now(playerName) end
    if low==".公会外交" or low==".工会外交" then return guild_diplomacy_menu(playerName) end
    local did,rel=raw:match("^%.公会外交%s+(G%d+)%s+(%S+)$") or raw:match("^%.工会外交%s+(G%d+)%s+(%S+)$"); if did then return guild_diplomacy_handle(playerName,did,rel) end
    local dac=raw:match("^%.公会外交确认%s+(G%d+)$") or raw:match("^%.工会外交确认%s+(G%d+)$"); if dac then return guild_diplomacy_accept(playerName,dac) end
    if low==".市场" or low==".玩家市场" then return show_player_market_main(playerName) end
    if r and r.menu=="market_main" then
        local n=tonumber(trim(raw))
        if n==1 then return market_sell_begin(playerName) end
        if n==2 or n==3 then show_market(playerName,1); local dd,rr=player_record(playerName,true); set_menu(dd,rr,n==2 and "market_buy" or "market_report",{market_page=1,market_list=rr.market_list}); return true end
        if n==4 then if not is_admin(playerName) then send(playerName,"§c该功能仅管理员可见。"); return true end; return _r7_prev_on_chat(playerName,msg) end
        if n==5 then return show_shop_logs(playerName) end
        if n==6 then return show_shop_management(playerName) end
        if n==7 then return show_sellers(playerName,1) end
        send(playerName,"§c请输入有效编号。"); return true
    end
    if r and r.menu=="market_buy" then
        if raw=="+" or raw=="-" then show_market(playerName,(r.market_page or 1)+(raw=="+" and 1 or -1)); return true end
        local n=tonumber(raw); local first=((r.market_page or 1)-1)*13+1; local idx=n and (n-first+1); local v=idx and r.market_list and r.market_list[idx]; if not v then send(playerName,"§c编号无效，请输入当前页显示的商品编号。"); return true end; return market_show_preview(playerName,v.id)
    end
    if r and r.menu=="market_report" then
        if raw=="+" or raw=="-" then show_market(playerName,(r.market_page or 1)+(raw=="+" and 1 or -1)); local dd,rr=player_record(playerName,true); set_menu(dd,rr,"market_report",{market_page=rr.market_page or 1,market_list=rr.market_list}); return true end
    end
    return _r7_prev_on_chat(playerName,msg)
end

-- ---------- 初始化：确保第一次加载就落一个自备份索引 ----------
local _r7_prev_init=on_init
function on_init()
    local ret=nil; if type(_r7_prev_init)=="function" then local ok,r=pcall(_r7_prev_init); if ok then ret=r end end
    pcall(ensure_patch_prompt_files); pcall(guild_init_files); pcall(patch_sidebar_update,true)
    pcall(cleanup_corrupt_player_keys)
    return ret
end

