-- ---------- R11 数据键清理：只删除确认为空壳的乱码玩家记录 ----------
function cleanup_corrupt_player_keys()
    local d=load_data(); if type(d)~="table" or type(d.players)~="table" then return 0 end
    local removed=0
    for k,r in pairs(d.players) do
        if type(k)=="string" and k:find(string.char(239,191,189),1,true) and type(r)=="table" then
            local xuid=trim(tostring(r.xuid or "")); local uid=trim(tostring(r.unique_id or ""))
            local has_death=type(r.death)=="table" or (type(r.death_history)=="table" and #r.death_history>0)
            local wp=type(r.waypoints)=="table" and next(r.waypoints)~=nil
            if xuid=="" and uid=="" and not has_death and not wp then
                d.players[k]=nil; removed=removed+1
            end
        end
    end
    if removed>0 then save_data(d); pcall(log_event,"MIGRATE","清理乱码玩家空壳记录："..tostring(removed).." 条") end
    return removed
end

