-- 市场主菜单重新编号：普通玩家与管理员都连续编号，不出现 1/2/3/5 的跳号。
function show_player_market_main(name)
    local d,r=player_record(name,true)
    local actions={
        {key="sell",text="上架商品"},
        {key="buy",text="浏览商品"},
        {key="report",text="举报商品"},
    }
    if is_admin(name) then actions[#actions+1]={key="admin",text="商铺处理（管理员）"} end
    actions[#actions+1]={key="logs",text="商铺日志"}
    actions[#actions+1]={key="manage",text="店铺管理"}
    actions[#actions+1]={key="sellers",text="商家列表"}
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━","§b§l✦ 玩 家 市 场 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━"}
    for i,a in ipairs(actions) do lines[#lines+1]="§f"..i..". "..a.text end
    lines[#lines+1]="§7真实物品数据由木桶 NBT 读取；卖家下线后商品仍保留。"
    lines[#lines+1]="§8.stop 退出"
    r.market_main_actions=actions
    set_menu(d,r,"market_main")
    send(name,table.concat(lines,"\n"))
end

-- 发展路线修复：正确清理菜单状态。
function guild_set_development(name,n)
    local g=guild_find_player(name); if not g then return true end
    local role=guild_member_role(g,name)
    if role~="owner" and role~="deputy" and not is_admin(name) then
        send(name,"§c只有会长/副会长可以调整发展路线。"); return true
    end
    local map={["1"]="城建",["2"]="商业",["3"]="冒险",["4"]="荣耀"}
    local route=map[tostring(n)]
    if not route then send(name,"§c请输入1~4。"); return true end
    local cost=math.max(0,guild_upgrade_cost(g.level or 1))
    if not is_admin(name) and (tonumber(g.funds) or 0)<cost then
        send(name,"§c公会资金不足，需要 "..cost.."。"); return true
    end
    if not is_admin(name) then g.funds=(tonumber(g.funds) or 0)-cost end
    g.development=route
    local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    guild_log(g.id,"切换发展路线",name,route.."；消耗="..(is_admin(name) and 0 or cost))
    local dd,rr=player_record(name,true); clear_menu(dd,rr)
    send(name,"§a✦ 公会发展路线已切换为：§e"..route)
    return true
end

-- 管理菜单设施设置参数顺序修复 + 领地删除权限统一。
local _r8_prev_guild_handle = guild_handle_menu
function guild_handle_menu(name,msg)
    local d,r=player_record(name,true)
    local mode=r and r.menu or ""
    local m=trim(msg or "")
    if mode=="guild_manage" then
        if m==".stop" or lower(m)=="stop" then clear_menu(d,r); return true end
        local n=tonumber(m)
        if n==1 then return guild_facility_set(name,"tp") end
        if n==2 then return guild_facility_set(name,"warehouse") end
        if n==3 then set_menu(d,r,"guild_notice_input"); send(name,"§e请输入公告内容："); return true end
        if n==4 then return guild_relocate_start(name) end
        if n==5 then return guild_delete_territory(name,false) end
        if n==6 then return guild_dissolve(name) end
        if n==7 then return guild_diplomacy_menu(name) end
        if n==8 then send(name,"§e重大事项投票：\n§f1 = 支持\n§f0 = 反对\n§7如需发起：请由会长/副会长进入对应重大事项流程。"); return true end
        if n==9 then return guild_generate_invite(name) end
        if n==10 then return guild_development_menu(name) end
        if n==11 and is_admin(name) then return guild_admin_menu(name) end
        send(name,"§c请输入有效编号。"); return true
    end
    if mode=="guild_main" then
        if m==".stop" then clear_menu(d,r); return true end
        local n=tonumber(m)
        if n==3 then return guild_signin(name) end
        if n==4 then return guild_task_menu(name) end
        if n==7 then return guild_announcement(name) end
        if n==9 then send(name,"§b公会设施：\n§f.传送公会 / .传送工会\n§f.传送公会仓库 / .传送工会仓库\n§7设置点位必须位于本公会领地内。"); return true end
        if n==10 then return guild_diplomacy_menu(name) end
        if n==11 then return guild_development_menu(name) end
        if n==12 then return guild_manage(name) end
        if n==13 then return guild_generate_invite(name) end
        if n==14 then return guild_rankings(name,"activity") end
    end
    return _r8_prev_guild_handle(name,msg)
end

