function patch_help_open(name,n)
    n=tonumber(n)
    if not n then return show_help(name) end
    local d,r=player_record(name,true); clear_menu(d,r)
    if n==1 then r8_basic_menu(name)
    elseif n==2 then r8_teleport_menu(name)
    elseif n==3 then show_territory(name)
    elseif n==4 then r8_player_info_menu(name)
    elseif n==5 then r8_economy_menu(name)
    elseif n==6 then show_market_14(name)
    elseif n==7 then show_player_market_main(name)
    elseif n==8 then r8_redeem_menu(name)
    elseif n==9 then r8_ai_menu(name)
    elseif n==10 then r8_daily_menu(name)
    elseif n==11 then r8_task_menu(name)
    elseif n==12 then r8_fun_menu(name)
    elseif n==13 then r8_utilities_menu(name)
    elseif n==14 then r8_server_menu(name)
    elseif n==15 then guild_commands_menu(name)
    elseif n==16 then show_gameplay_categories(name)
    else return show_help(name) end
    return true
end

-- ---------- R8 菜单输入 ----------
local _r8_prev_on_chat=on_chat
function on_chat(playerName,msg)
    local raw=tostring(msg or ""); local low=lower(trim(raw)); local d,r=player_record(playerName,true)
    if r and r.menu=="market_main" then
        local n=tonumber(trim(raw)); local acts=r.market_main_actions or {}
        local a=n and acts[n]
        if not a then send(playerName,"§c请输入当前菜单中的有效编号。"); return true end
        if a.key=="sell" then return market_sell_begin(playerName)
        elseif a.key=="buy" then show_market(playerName,1); local dd,rr=player_record(playerName,true); set_menu(dd,rr,"market_buy",{market_page=1,market_list=rr.market_list}); return true
        elseif a.key=="report" then show_market(playerName,1); local dd,rr=player_record(playerName,true); set_menu(dd,rr,"market_report",{market_page=1,market_list=rr.market_list}); return true
        elseif a.key=="admin" then return _r8_prev_on_chat(playerName,msg)
        elseif a.key=="logs" then return show_shop_logs(playerName)
        elseif a.key=="manage" then return show_shop_management(playerName)
        elseif a.key=="sellers" then return show_sellers(playerName,1) end
    end
    if r and r.menu=="r8_basic" then
        local n=tonumber(raw)
        if n==1 then return signin(playerName) end
        if n==2 then return get_self_basic_info(playerName) end
        if n==3 then show_trigger_words(playerName,1); return true end
        if n==4 then death_show_list(playerName); return true end
        if n==5 then slot_menu(playerName,"save_slot"); return true end
        if n==6 then show_tpa_targets(playerName); return true end
        send(playerName,"§c请输入1~6。"); return true
    end
    if r and r.menu=="r8_tp" then
        local n=tonumber(raw)
        if n==1 then show_tpa_targets(playerName); return true end
        if n==2 then show_transfer_chances(playerName); return true end
        if n==3 then
            local dd,rr=player_record(playerName,true); set_menu(dd,rr,"coord_tp_input"); send(playerName,"§b请输入：维度 X Y Z"); return true
        end
        if n==4 then death_show_list(playerName); return true end
        if n==5 then return start_soul(playerName) end
        send(playerName,"§c请输入1~5。"); return true
    end
    if r and r.menu=="r8_player_info" then
        local n=tonumber(raw)
        if n==1 then return get_self_basic_info(playerName) end
        if n==2 then send(playerName,"§b在线玩家：\n§f"..table.concat(online_players() or {},"\n§f")); return true end
        if n==3 then
            local out,ok=ai_inventory_sync(playerName,playerName,is_admin(playerName)); send(playerName,out); return true
        end
        if n==4 then
            local board=scoreboard_name(); local ok,v=pcall(game.getMultiScore,playerName); send(playerName,ok and ("§b━━ 我的分数 ━━\n§f"..tostring(http.json_encode(v))) or "§c分数读取失败。"); return true
        end
        send(playerName,"§c请输入1~4。"); return true
    end
    if r and r.menu=="r8_economy" then
        local n=tonumber(raw)
        if n==1 then return coin_leaderboard(playerName) end
        if n==2 then return show_market_14(playerName) end
        if n==3 then return show_player_market_main(playerName) end
        if n==4 then return signin(playerName) end
        if n==5 then return guild_main(playerName) end
        send(playerName,"§c请输入1~5。"); return true
    end
    if r and r.menu=="r8_redeem" then
        if raw==".stop" then clear_menu(d,r); return true end
        if tonumber(raw)==1 then clear_menu(d,r); send(playerName,"§e请输入兑换码，例如：XX123"); set_menu(d,r,"r8_redeem_input"); return true end
        if tonumber(raw)==2 then send(playerName,"§7兑换码为一次性奖励码；使用后按服务器规则标记已兑换。"); return true end
        send(playerName,"§c请输入1或2。"); return true
    end
    if r and r.menu=="r8_redeem_input" then
        if raw==".stop" then clear_menu(d,r); return true end
        local ok,res=pcall(redeem_code,playerName,trim(raw)); if not ok then send(playerName,"§c兑换失败："..tostring(res)) elseif res==false or res==nil then send(playerName,"§c兑换码无效或已使用。") end
        clear_menu(d,r); return true
    end
    if r and r.menu=="r8_ai" then
        local n=tonumber(raw)
        if n==1 then local cur=get_ai_model_override() or tostring(game.getConfig("ai_model",AI_MODEL) or AI_MODEL); send(playerName,"§b当前模型：§e"..model_display(cur).."\n"..ai_thinking_status_text()); return true end
        if n==2 then send(playerName,ai_thinking_status_text()); return true end
        if n==3 then send(playerName,ai_seg_status()); return true end
        if n==4 then clear_ai_memory(playerName); send(playerName,"§aAI记忆已清除，已切换到新的会话窗口。"); return true end
        if n==5 then show_trigger_words(playerName,1); return true end
        send(playerName,"§c请输入1~5。"); return true
    end
    if r and r.menu=="r8_daily" then
        local n=tonumber(raw)
        if n==1 then return signin(playerName) end
        if n==2 then return guild_signin(playerName) end
        if n==3 then return guild_task_menu(playerName) end
        if n==4 then return guild_rankings(playerName,"activity") end
        send(playerName,"§c请输入1~4。"); return true
    end
    if r and r.menu=="r8_task" then
        local n=tonumber(raw)
        if n==1 then return guild_task_menu(playerName) end
        if n==2 then
            send(playerName,"§d✦ 公会成就 ✦\n§7初建、成员、签到、在线、任务、资金、等级、外交成就。")
            return true
        end
        if n==3 then return guild_rankings(playerName,"activity") end
        if n==4 then return guild_rankings(playerName,"level") end
        send(playerName,"§c请输入1~4。"); return true
    end
    if r and r.menu=="r8_fun" then
        local n=tonumber(raw)
        if n==1 then return start_soul(playerName) end
        if n==2 then return show_player_market_main(playerName) end
        if n==3 then return guild_diplomacy_menu(playerName) end
        if n==4 then send(playerName,"§d✦ 公会活动 ✦\n§7参与签到、任务、在线和外交活动即可获得贡献/经验/资金。"); return true end
        send(playerName,"§c请输入1~4。"); return true
    end
    if r and r.menu=="r8_utils" then
        local n=tonumber(raw)
        if n==1 then show_trigger_words(playerName,1); return true end
        if n==2 then send(playerName,"§e用法：.NBT测试 X Y Z"); return true end
        if n==3 then return cmd_container_show(playerName) end
        if n==4 then local t,s=patch_try_tps(); send(playerName,"§bTPS：§e"..(t and string.format("%.1f",t) or "不可用").."\n§7来源："..tostring(s)); return true end
        if n==5 then return self_backup_now(playerName) end
        send(playerName,"§c请输入1~5。"); return true
    end
    if r and r.menu=="r8_server" then
        local n=tonumber(raw)
        if n==1 then patch_sidebar_update(true); send(playerName,"§a公告栏已刷新。\n§7TPS会在下一次60秒周期自动更新。"); return true end
        if n==2 then
            if not is_admin(playerName) then send(playerName,"§c只有管理员可以设置服务器号。"); return true end
            set_menu(d,r,"r8_group_number"); send(playerName,"§e请输入服务器号，可写：数字 或 数字 天数"); return true
        end
        if n==3 then return cmd_container_show(playerName) end
        if n==4 then local t,s=patch_try_tps(); send(playerName,"§b服务器TPS：§e"..(t and string.format("%.1f",t) or "不可用").."\n§7来源："..tostring(s)); return true end
        if n==5 then send(playerName,"§b在线玩家：\n"..table.concat(online_players() or {},"\n")); return true end
        send(playerName,"§c请输入1~5。"); return true
    end
    if r and r.menu=="r8_group_number" then
        if raw==".stop" then clear_menu(d,r); return true end
        local n,days=raw:match("^(%d+)%s*(%d*)$")
        if not n then send(playerName,"§c请输入：服务器号 [有效天数]"); return true end
        return patch_server_number_set(playerName,n,tonumber(days) or 30)
    end
    return _r8_prev_on_chat(playerName,msg)
end

local _r8_prev_init=on_init
function on_init()
    local ret=nil
    if type(_r8_prev_init)=="function" then local ok,r=pcall(_r8_prev_init); if ok then ret=r end end
    pcall(ensure_patch_prompt_files)
    pcall(guild_init_files)
    pcall(patch_sidebar_update,true)
    return ret
end-- ============================================================
-- R12 最终补齐：公会申请/审核、公开状态、商店最终价格
-- ============================================================
GUILD_APPLICATION_FILE = GUILD_DIR.."/applications.json"

local _r12_old_guild_init = guild_init_files
function guild_init_files()
    local ret = _r12_old_guild_init()
    local d = guild_load(GUILD_APPLICATION_FILE,{next_id=1,items={}})
    d.next_id = tonumber(d.next_id) or 1; d.items = d.items or {}; guild_save(GUILD_APPLICATION_FILE,d)
    return ret
end
function guild_app_db()
    local d=guild_load(GUILD_APPLICATION_FILE,{next_id=1,items={}}); d.next_id=tonumber(d.next_id) or 1; d.items=d.items or {}; return d
end
function guild_is_manager(g,name)
    local role=guild_member_role(g,name); return role=="owner" or role=="deputy" or is_admin(name)
end
function guild_apply_join(name,gid)
    if guild_find_player(name) then send(name,"§c你已经加入公会，不能重复申请。"); return true end
    local gd=guild_load(GUILD_FILE,{items={}}); local g=gd.items and gd.items[tostring(gid or "")]
    if not g or g.status=="dissolved" then send(name,"§c目标公会不存在。"); return true end
    if g.public==false then send(name,"§c该公会当前关闭公开申请，请联系会长获取邀请码。"); return true end
    if #(g.members or {})>=guild_max_members(g.level) then send(name,"§c该公会成员名额已满。"); return true end
    local db=guild_app_db(); local u=uuid_key(name); local now=util.timestamp()
    for _,a in pairs(db.items) do if type(a)=="table" and a.status=="pending" and tostring(a.guild_id)==tostring(g.id) and tostring(a.applicant_uuid)==u then send(name,"§e你已经向「"..g.name.."」提交过待处理申请。\n§7申请编号："..tostring(a.id)); return true end end
    local id="A"..string.format("%05d",db.next_id); db.next_id=db.next_id+1
    db.items[id]={id=id,guild_id=g.id,guild_name=g.name,applicant_uuid=u,applicant_name=name,status="pending",created_at=now,updated_at=now}
    guild_save(GUILD_APPLICATION_FILE,db); guild_log(g.id,"提交入会申请",name,"申请="..id)
    send(name,"§a✦ 入会申请已提交\n§f公会：§e"..g.name.."\n§f申请编号：§b"..id.."\n§7请等待会长/副会长审核。")
    return true
end
function guild_my_applications(name)
    local db=guild_app_db(); local u=uuid_key(name); local arr={}; for _,a in pairs(db.items) do if type(a)=="table" and tostring(a.applicant_uuid)==u then arr[#arr+1]=a end end
    table.sort(arr,function(a,b) return (tonumber(a.created_at) or 0)>(tonumber(b.created_at) or 0) end)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§d✦ 我的入会申请 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    for i=1,math.min(10,#arr) do local a=arr[i]; local st=({pending="§e待审核",accepted="§a已通过",rejected="§c已拒绝",cancelled="§7已撤销"})[a.status] or tostring(a.status); lines[#lines+1]=string.format("§f%s §8| §e%s §8| %s",tostring(a.id),tostring(a.guild_name),st) end
    if #arr==0 then lines[#lines+1]="§7暂无申请。" end; lines[#lines+1]="§7输入 .stop 退出"
    local d,r=player_record(name,true); set_menu(d,r,"guild_my_applications"); send(name,table.concat(lines,"\n")); return true
end
function guild_pending_applications(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    if not guild_is_manager(g,name) then send(name,"§c只有会长/副会长可以审核入会申请。"); return true end
    local db=guild_app_db(); local arr={}; for _,a in pairs(db.items) do if type(a)=="table" and a.status=="pending" and tostring(a.guild_id)==tostring(g.id) then arr[#arr+1]=a end end
    table.sort(arr,function(a,b) return (tonumber(a.created_at) or 0)<(tonumber(b.created_at) or 0) end)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§d✦ 入会申请审核 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    for i=1,math.min(20,#arr) do local a=arr[i]; lines[#lines+1]=string.format("§f%d. §e%s §8| 编号 §b%s",i,tostring(a.applicant_name),tostring(a.id)) end
    if #arr==0 then lines[#lines+1]="§7当前没有待审核申请。" end; lines[#lines+1]="§7输入编号后，再输入 1=通过 / 0=拒绝；.stop退出"
    local d,r=player_record(name,true); r.guild_pending_apps=arr; set_menu(d,r,"guild_app_list"); send(name,table.concat(lines,"\n")); return true
end
function guild_application_decide(name,app_id,agree)
    local g=guild_find_player(name); if not g or not guild_is_manager(g,name) then send(name,"§c没有审核权限。"); return true end
    local db=guild_app_db(); local a=db.items[tostring(app_id or "")]
    if type(a)~="table" or a.status~="pending" or tostring(a.guild_id)~=tostring(g.id) then send(name,"§c申请不存在、已处理或不属于本公会。"); return true end
    if tostring(agree)~="1" and tostring(agree)~="0" then send(name,"§c请输入1=通过，0=拒绝。"); return true end
    if tostring(agree)=="1" then
        if guild_find_player(a.applicant_name) then a.status="rejected"; a.reject_reason="申请人已经加入其他公会"; a.updated_at=util.timestamp(); db.items[a.id]=a; guild_save(GUILD_APPLICATION_FILE,db); send(name,"§c申请人已经加入其他公会，申请自动失效。"); return true end
        if #(g.members or {})>=guild_max_members(g.level) then send(name,"§c公会已满，暂时无法通过申请。"); return true end
        g.members=g.members or {}; g.members[#g.members+1]={uuid=tostring(a.applicant_uuid),name=tostring(a.applicant_name),role="member",contribution=0,joined_at=util.timestamp(),activity=0}
        local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd); guild_mark_history(a.applicant_name,g.id,"member"); guild_log(g.id,"通过入会申请",name,"申请="..a.id.."；玩家="..a.applicant_name)
        a.status="accepted"; a.updated_at=util.timestamp(); a.reviewed_by=name; db.items[a.id]=a; guild_save(GUILD_APPLICATION_FILE,db)
        send(name,"§a已通过申请：§e"..a.applicant_name); pcall(game.sendTargeted,a.applicant_name,"§a✦ 你的公会申请已通过！\n§f公会：§e"..g.name)
    else
        a.status="rejected"; a.updated_at=util.timestamp(); a.reviewed_by=name; db.items[a.id]=a; guild_save(GUILD_APPLICATION_FILE,db); guild_log(g.id,"拒绝入会申请",name,"申请="..a.id.."；玩家="..a.applicant_name); send(name,"§e已拒绝申请：§f"..a.applicant_name); pcall(game.sendTargeted,a.applicant_name,"§c你的公会申请已被拒绝。\n§f公会：§e"..g.name)
    end
    clear_menu(player_record(name,true)); return true
end
function guild_set_public(name,value)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    if not guild_is_manager(g,name) then send(name,"§c只有会长/副会长可以修改公会公开状态。"); return true end
    g.public=value==true; local gd=guild_load(GUILD_FILE,{items={}}); gd.items[g.id]=g; guild_save(GUILD_FILE,gd); guild_log(g.id,g.public and "开启公开申请" or "关闭公开申请",name,"")
    send(name,g.public and "§a✦ 公会已开启公开入会申请。" or "§e✦ 公会已关闭公开入会申请。\n§7玩家仍可通过邀请码加入。"); return true
end
local _r12_old_full_shop_catalog=full_shop_catalog
function full_shop_catalog(playerName)
    local arr=_r12_old_full_shop_catalog(playerName); for _,v in ipairs(arr or {}) do if tostring(v.id)=="diamond" then v.price=160 end; if tostring(v.id)=="netherite_block" then v.price=1800 end end; return arr
end
local _r12_old_sell_price_data=sell_price_data
function sell_price_data()
    local t=_r12_old_sell_price_data(); t=t or {}; t.diamond=t.diamond or {price=160,name="钻石",damage=0,order=93}; t.diamond.price=160; t.netherite_block=t.netherite_block or {price=1800,name="下界合金块",damage=0,order=185}; t.netherite_block.price=1800; return t
end
local _r12_old_guild_public_detail=guild_public_detail
function guild_public_detail(name,gid)
    local ret=_r12_old_guild_public_detail(name,gid); local gd=guild_load(GUILD_FILE,{items={}}); local g=gd.items and gd.items[tostring(gid or "")]
    if g and g.status~="dissolved" and not guild_find_player(name) then local d,r=player_record(name,true); r.guild_detail_id=tostring(g.id); set_menu(d,r,"guild_public_detail"); send(name,"§e输入 1 申请加入本公会\n§7输入 0 返回；.stop 退出。\n§7当前公开申请："..(g.public==false and "§c关闭" or "§a开启")) end
    return ret
end
function guild_manage(name)
    local g=guild_find_player(name); if not g then return guild_create_menu(name) end; if not guild_is_manager(g,name) then send(name,"§c普通成员没有公会管理权限。"); return true end
    local d,r=player_record(name,true); set_menu(d,r,"guild_manage"); send(name,table.concat({"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§c✦ 公会管理 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§f① 设置公会传送点","§f② 设置仓库传送点","§f③ 发布公告","§f④ 删除/更换公会领地","§f⑤ 解散公会","§f⑥ 外交关系","§f⑦ 投票/重大事项","§f⑧ 发展路线","§f⑨ 邀请码","§f⑩ 入会公开状态","§f⑪ 入会申请审核","§f⑫ 管理员后台（仅管理员）","§7.stop 退出"},"\n")); return true
end
local _r12_prev_on_chat=on_chat
function on_chat(playerName,msg)
    local raw=tostring(msg or ""); local low=lower(trim(raw)); local d,r=player_record(playerName,true)
    local aid,adec=raw:match("^%.公会申请处理%s+(A%d+)%s+([01])$"); if aid then return guild_application_decide(playerName,aid,adec) end
    local gid=raw:match("^%.申请公会%s+(G%d+)$") or raw:match("^%.公会申请%s+(G%d+)$"); if gid then return guild_apply_join(playerName,gid) end
    if low==".公会申请" or low==".我的公会申请" then return guild_my_applications(playerName) end
    local pub=raw:match("^%.公会公开%s+([01])$") or raw:match("^%.工会公开%s+([01])$"); if pub then return guild_set_public(playerName,pub=="1") end
    if r and r.menu=="guild_first" then local n=tonumber(raw); if n==6 then return guild_my_applications(playerName) end end
    if r and r.menu=="guild_public_detail" then if raw==".stop" or raw=="0" then clear_menu(d,r); return true end; if raw=="1" then local target=r.guild_detail_id; clear_menu(d,r); return guild_apply_join(playerName,target) end; send(playerName,"§c请输入1申请加入，0返回。; .stop退出。"); return true end
    if r and r.menu=="guild_my_applications" then if raw==".stop" or raw=="0" then clear_menu(d,r); return true end; send(playerName,"§7申请状态已保存；用 .公会申请 查看最新状态。 "); return true end
    if r and r.menu=="guild_manage" then
        local n=tonumber(raw)
        if n==10 then set_menu(d,r,"guild_public_toggle"); local gg=guild_find_player(playerName); send(playerName,"§e输入1开启公开申请；0关闭。当前："..((gg and gg.public==false) and "§c关闭" or "§a开启")); return true end
        if n==11 then return guild_pending_applications(playerName) end
        if n==12 then if not is_admin(playerName) then send(playerName,"§c只有管理员可进入后台。"); return true end; return guild_admin_menu(playerName) end
        if n==9 then return guild_generate_invite(playerName) end; if n==8 then return guild_development_menu(playerName) end; if n==7 then send(playerName,"§e重大事项投票：输入 .公会投票 <1支持/0反对>。 "); return true end; if n==6 then return guild_diplomacy_menu(playerName) end
        if n==3 then set_menu(d,r,"guild_notice_input"); send(playerName,"§e请输入公告内容："); return true end; if n==1 then return guild_facility_set(playerName,"tp") end; if n==2 then return guild_facility_set(playerName,"warehouse") end; if n==4 then return guild_relocate_start(playerName) end; if n==5 then return guild_dissolve(playerName) end
    end
    if r and r.menu=="guild_public_toggle" then if raw==".stop" then clear_menu(d,r); return true end; if raw=="1" then clear_menu(d,r); return guild_set_public(playerName,true) end; if raw=="0" then clear_menu(d,r); return guild_set_public(playerName,false) end; send(playerName,"§c请输入1或0。"); return true end
    if r and r.menu=="guild_app_list" then if raw==".stop" then clear_menu(d,r); return true end; local n=tonumber(raw); local a=r.guild_pending_apps and r.guild_pending_apps[n]; if not a then send(playerName,"§c请输入申请列表中的编号。"); return true end; r.guild_app_review_id=a.id; set_menu(d,r,"guild_app_decide"); send(playerName,"§e申请：§f"..a.id.."\n§e玩家：§f"..a.applicant_name.."\n§a1 通过\n§c0 拒绝\n§7.stop 退出"); return true end
    if r and r.menu=="guild_app_decide" then if raw==".stop" then clear_menu(d,r); return true end; if raw=="1" or raw=="0" then return guild_application_decide(playerName,r.guild_app_review_id,raw) end; send(playerName,"§c请输入1=通过，0=拒绝。"); return true end
    return _r12_prev_on_chat(playerName,msg)
end
local _r12_prev_init=on_init
function on_init()
    local ret=nil; if type(_r12_prev_init)=="function" then local ok,v=pcall(_r12_prev_init); if ok then ret=v end end; pcall(guild_init_files); pcall(function() local gd=guild_load(GUILD_FILE,{items={}}); for _,g in pairs(gd.items or {}) do if g.status~="dissolved" and g.public==nil then g.public=true end end; guild_save(GUILD_FILE,gd) end); return ret
end


