FINAL_PATCH_VERSION = "1.0.65-R13"
FINAL_PATCH_TAG = "公会完整系统_主体恢复修复版"

-- -----------------------------------------------------------------
-- 0) 通用安全辅助
-- -----------------------------------------------------------------
function r13_safe_name(name)
    return string.gsub(tostring(name or ""),'"','\\"')
end

function r13_beijing_time(ts,with_date)
    ts=tonumber(ts) or util.timestamp()
    local ok,t=pcall(os.date,"!*t",ts+8*3600)
    if not ok or type(t)~="table" then return "--:--" end
    if with_date then return string.format("%04d-%02d-%02d %02d:%02d",t.year,t.month,t.day,t.hour,t.min) end
    return string.format("%02d:%02d",t.hour,t.min)
end

function r13_guild_role(role)
    role=lower(trim(tostring(role or "member")))
    if role=="owner" or role=="leader" or role=="会长" then return "owner" end
    if role=="vice" or role=="deputy" or role=="副会长" then return "deputy" end
    return "member"
end

function r13_guild_contains(g,pos)
    if type(g)~="table" or type(g.territory)~="table" or type(pos)~="table" then return false end
    local t=g.territory
    if dim_exec(t.dimension)~=dim_exec(pos.dimension) then return false end
    local x1,x2=math.min(tonumber(t.x1) or 0,tonumber(t.x2) or 0),math.max(tonumber(t.x1) or 0,tonumber(t.x2) or 0)
    local z1,z2=math.min(tonumber(t.z1) or 0,tonumber(t.z2) or 0),math.max(tonumber(t.z1) or 0,tonumber(t.z2) or 0)
    local x,z=tonumber(pos.x),tonumber(pos.z)
    return x~=nil and z~=nil and x>=x1 and x<=x2 and z>=z1 and z<=z2
end

function r13_rect_overlap(a,b)
    if type(a)~="table" or type(b)~="table" then return false end
    if dim_exec(a.dimension)~=dim_exec(b.dimension) then return false end
    local ax1,ax2=math.min(tonumber(a.x1) or 0,tonumber(a.x2) or 0),math.max(tonumber(a.x1) or 0,tonumber(a.x2) or 0)
    local az1,az2=math.min(tonumber(a.z1) or 0,tonumber(a.z2) or 0),math.max(tonumber(a.z1) or 0,tonumber(a.z2) or 0)
    local bx1,bx2=math.min(tonumber(b.x1) or 0,tonumber(b.x2) or 0),math.max(tonumber(b.x1) or 0,tonumber(b.x2) or 0)
    local bz1,bz2=math.min(tonumber(b.z1) or 0,tonumber(b.z2) or 0),math.max(tonumber(b.z1) or 0,tonumber(b.z2) or 0)
    return not (ax2<bx1 or bx2<ax1 or az2<bz1 or bz2<az1)
end

-- -----------------------------------------------------------------
-- 1) AI TXT：真实文件优先、常驻 core、日志降权，不再“默认先查日志”
-- -----------------------------------------------------------------
R13_PROMPT_FALLBACK = R13_PROMPT_FALLBACK or {
    core=[[
你是 Minecraft 基岩版服务器的游戏内 AI 助手，必须使用中文回答。
【真实数据原则】在线玩家、背包、位置、计分板、日志、世界状态必须优先读取真实工具结果；读取失败要明确说明失败，不能把失败说成“空”。
【日志原则】日志工具是按需工具，不是默认步骤。只有玩家明确要求“查日志、聊天记录、发言、报错、历史记录”时才调用日志；普通聊天、普通指令、普通问答禁止为了流程完整而主动查日志。
【基岩版原则】使用 Bedrock/网易租赁服真实可用语法，禁止自动套用 Java Edition NBT 语法。
【执行原则】需要执行命令时必须真实执行并以回执为准；不能把“准备执行”说成“已经完成”。
【工具最小化】只调用当前问题需要的工具，不做无关查询。
]],
    cmd=[[指令专项：只输出并执行当前基岩版/网易服可用的真实命令。执行前核验权限与参数，执行后依据真实回执汇报。]],
    build=[[建筑专项：小步执行、真实回执、失败修正。导入/导出必须保留真实相对坐标与 NBT，不得把空气当成成功结果。]],
    mcp=[[远程维护专项：修改前读取真实文件；修改后验证；只有自己创建过完整备份时才允许回滚，禁止直接使用云手机里的不明旧包覆盖当前版本。]],
    review=[[审查专项：只根据真实日志、聊天记录和服务器数据判断，不把猜测当事实。]]
}

function r13_prompt_candidates(id)
    local fn="seg_"..tostring(id)..".txt"
    local out,seen={},{}
    local function add(p)
        p=tostring(p or "")
        if p~="" and not seen[p] then seen[p]=true; out[#out+1]=p end
    end
    local ok,dd=pcall(game.dataDir)
    if ok and type(dd)=="string" then add(dd.."/"..fn); add(dd.."/ai_prompts/"..fn) end
    local ok2,cd=pcall(plugin_code_dir)
    if ok2 and type(cd)=="string" then add(cd.."/"..fn); add(cd.."/ai_prompts/"..fn) end
    local ok3,base=pcall(plugin_base_dir)
    local pid=""; pcall(function() pid=tostring(plugin_id_now() or "") end)
    if ok3 and type(base)=="string" and pid~="" then
        add(base.."/插件文件/"..pid.."/"..fn)
        add(base.."/插件文件/"..pid.."/ai_prompts/"..fn)
    end
    return out
end

function ai_seg_load(name,force)
    local id=ai_seg_canonical(name)
    if id=="" then return "" end
    if not force and _AI_SEG_CACHE[id] and trim(tostring(_AI_SEG_CACHE[id]))~="" then return _AI_SEG_CACHE[id] end
    local value=""
    for _,p in ipairs(r13_prompt_candidates(id)) do
        local ok,v=pcall(util.read_file,p)
        if ok and type(v)=="string" and trim(v)~="" then value=v; break end
    end
    if trim(value)=="" then value=R13_PROMPT_FALLBACK[id] or AI_PROMPT_BUILTIN[id] or "" end
    _AI_SEG_CACHE[id]=value
    return value
end

function ensure_patch_prompt_files()
    for id,text in pairs(R13_PROMPT_FALLBACK) do
        local found=false
        for _,p in ipairs(r13_prompt_candidates(id)) do
            local ok,v=pcall(util.read_file,p)
            if ok and type(v)=="string" and trim(v)~="" then found=true; break end
        end
        if not found then
            local list=r13_prompt_candidates(id)
            if list[1] then pcall(util.write_file,list[1],text) end
        end
    end
end

function build_ai_system(q,admin)
    local core=ai_seg_load("core",true)
    if trim(core)=="" then return "【严重错误】seg_core.txt 与内置 core 均不可用。",{"core"} end
    local extra="\n\n【当前插件工具策略】\n"..
        "- 简单聊天直接回答；不默认查日志。\n"..
        "- 查普通玩家发言时使用持久化 chat_logs.json；普通玩家真实聊天与管理员聊天在同一日志中。\n"..
        "- 背包查询必须区分‘真实空背包’与‘接口读取失败’。\n"..
        "- 玩家市场、领地、公会、金币与死亡点必须使用服务器实时数据，不得猜测。\n"..
        "- 工具失败时明确失败原因，不允许伪装成功。"
    return "【常驻核心提示词】\n"..core..extra,{"core"}
end

-- -----------------------------------------------------------------
-- 2) 玩家市场：每个玩家独立木桶坐标，直接远程读真实木桶，不再脚下一格
-- -----------------------------------------------------------------
function r13_is_air_block(data)
    if type(data)~="table" then return false end
    local n=lower(tostring(data.name or data.id or ""))
    return n=="air" or n=="minecraft:air" or n=="cave_air" or n=="minecraft:cave_air"
end

function r13_read_block(x,y,z)
    local ok,d,e=market_region_one_block(math.floor(x),math.floor(y),math.floor(z))
    if ok and type(d)=="table" then return d end
    return nil,e
end

function r13_find_market_barrel_spot(name)
    local p=player_position(name,false)
    if not p then return nil,"无法读取玩家当前位置。" end
    local x,y,z=math.floor(p.x),math.floor(p.y),math.floor(p.z)
    local candidates={{1,0},{-1,0},{0,1},{0,-1},{2,0},{-2,0},{0,2},{0,-2}}
    for _,o in ipairs(candidates) do
        local bx,bz=x+o[1],z+o[2]
        local d=r13_read_block(bx,y,bz)
        if d and r13_is_air_block(d) then return {x=bx,y=y,z=bz,dimension=p.dimension} end
    end
    return nil,"附近没有找到可安全放置木桶的空气位置。"
end

function r13_market_session(name)
    local d,r=player_record(name,true)
    d.market_sessions=d.market_sessions or {}
    return d,r,d.market_sessions[name]
end

function patch_market_start_from_name(name,nm,d,r)
    nm=trim(tostring(nm or ""))
    if nm=="" then send(name,"§c商品名称不能为空。"); return true end
    local spot,why=r13_find_market_barrel_spot(name)
    if not spot then send(name,"§c无法创建上架木桶："..tostring(why)); return true end
    local cmd=string.format("setblock %d %d %d barrel",spot.x,spot.y,spot.z)
    local ok,res=pcall(game.isCmdSuccess,cmd)
    if not ok or res~=true then send(name,"§c木桶放置失败，请换一个位置重试。"); return true end
    local id=tonumber((market_db().next_id or 1)) or 1
    local token=tostring(uuid_key(name))..":"..tostring(util.timestamp())..":"..tostring(id)
    d.market_sessions=d.market_sessions or {}
    d.market_sessions[name]={
        id=id,name=nm,price=tonumber(r.market_session_price) or 0,
        barrel_pos={x=spot.x,y=spot.y,z=spot.z,dimension=spot.dimension},
        owner=tostring(name),owner_uuid=uuid_key(name),session_token=token,
        created_at=util.timestamp(),expires_at=util.timestamp()+180,status="waiting"
    }
    r.market_sell_preview_pending=nil
    set_menu(d,r,"market_sell_wait",{})
    r.menu_expires=util.timestamp()+180
    save_data(d)
    send(name,"§a✦ 上架木桶已放在你附近。\n§f把商品放入木桶后输入：§e确定商品\n§7每个玩家的木桶坐标独立保存，不会串单；3分钟超时自动结束。")
    return true
end

function market_save_nbt_item(id,x,y,z)
    x,y,z=math.floor(tonumber(x) or 0),math.floor(tonumber(y) or 0),math.floor(tonumber(z) or 0)
    local ok,data,err=market_region_one_block(x,y,z)
    if not ok or type(data)~="table" then return false,"读取木桶失败："..tostring(err) end
    local bn=lower(tostring(data.name or data.id or ""))
    if not bn:find("barrel",1,true) then return false,"记录的商品位置已经不是木桶。" end
    local nbt=data.nbt or data.NBT or data.blockEntityNbt or data.block_entity_nbt
    if not market_nbt_has_items({nbt=nbt}) then return false,"商品木桶为空，或木桶 Items 未被真实读取。" end
    local entry={id=tostring(id),block_name=tostring(data.name or data.id or "minecraft:barrel"),states=data.states or {},nbt=market_copy_table(nbt),saved_at=util.timestamp(),x=x,y=y,z=z}
    local db=market_nbt_db(); db.items=db.items or {}; db.items[tostring(id)]=entry
    local oks,serr=market_nbt_save(db)
    if not oks then return false,"商品 NBT 保存失败："..tostring(serr) end
    market_save_preview(id,entry)
    return true,entry
end

function market_finish_sell(name)
    local d,r,s=r13_market_session(name)
    if not s then send(name,"§c没有待确认的上架木桶。"); return true end
    if tostring(s.owner_uuid or "")~=tostring(uuid_key(name)) then
        d.market_sessions[name]=nil; save_data(d); send(name,"§c上架会话归属校验失败，已取消，防止串单。"); return true
    end
    if util.timestamp()>tonumber(s.expires_at or 0) then
        local p=s.barrel_pos or {}; pcall(game.isCmdSuccess,string.format("setblock %d %d %d air replace",tonumber(p.x) or 0,tonumber(p.y) or 0,tonumber(p.z) or 0))
        d.market_sessions[name]=nil; r.market_sell_preview_pending=nil; clear_menu(d,r); save_data(d); send(name,"§e上架流程已超过3分钟，已取消。"); return true
    end
    if r.market_sell_preview_pending and type(s.preview_entry)=="table" then send(name,"§e预览已经生成，请输入1确认上架或0取消。"); return true end
    local p=s.barrel_pos or {}
    local id=tostring(s.id)
    local ok,entry=market_save_nbt_item(id,p.x,p.y,p.z)
    if not ok then send(name,"§c商品读取失败："..tostring(entry)); return true end
    s.preview_entry=entry; s.status="preview"
    r.market_sell_preview_pending=true
    set_menu(d,r,"market_sell_confirm")
    save_data(d)
    send(name,market_sell_preview_message(entry,id,s.name,s.price))
    return true
end

function market_finalize_sell(name)
    local d,r,s=r13_market_session(name)
    if not s then send(name,"§c没有待确认商品。"); return true end
    if tostring(s.owner_uuid or "")~=tostring(uuid_key(name)) then send(name,"§c上架会话归属不一致，已拒绝。"); return true end
    if market_storage_db().x==nil then send(name,"§c管理员尚未设置玩家市场三维仓库：.市场仓库 X Y Z"); return true end
    local p=s.barrel_pos or {}
    local id=tostring(s.id)
    local entry=s.preview_entry
    if type(entry)~="table" or type(entry.nbt)~="table" then
        local ok,e=market_save_nbt_item(id,p.x,p.y,p.z)
        if not ok then send(name,"§c商品保存失败："..tostring(e)); return true end
        entry=e; s.preview_entry=e
    end
    local c=market_storage_coord(id)
    if not c then send(name,"§c玩家市场三维仓库配置无效。"); return true end
    local cloned=market_clone_one(p.x,p.y,p.z,c.x,c.y,c.z)
    if not cloned then send(name,"§c商品 clone 到市场仓库失败，原木桶未删除。"); return true end
    pcall(game.isCmdSuccess,string.format("setblock %d %d %d air replace",math.floor(p.x),math.floor(p.y),math.floor(p.z)))
    local db=market_db()
    db.listings[id]={id=id,name=s.name,price=tonumber(s.price) or 0,seller=name,seller_uuid=uuid_key(name),storage_id=id,preview_nbt=entry.nbt,created_at=util.timestamp(),sold=false,sold_count=0,disabled=false,shop_banned=false,reports=0}
    db.next_id=math.max(tonumber(db.next_id) or 1,(tonumber(s.id) or 0)+1)
    market_save(db)
    r.market_sell_day=r.market_sell_day or {day=math.floor(util.timestamp()/86400),count=0,last_at=0}
    r.market_sell_day.count=(tonumber(r.market_sell_day.count) or 0)+1
    r.market_sell_day.last_at=util.timestamp()
    d.market_sessions[name]=nil; r.market_sell_preview_pending=nil; clear_menu(d,r); save_data(d)
    append_json_log(SHOP_LOG_FILE,{at=util.timestamp(),type="上架",seller=name,seller_uuid=uuid_key(name),id=id,name=s.name,price=s.price,storage_id=id})
    send(name,"§a✦ 商品已真实上架。\n§f编号：§b"..id.."  §f名称：§e"..tostring(s.name).."  §f价格：§6"..tostring(s.price).."金币")
    return true
end

-- 服务器收购物品也改成独立真实坐标；不使用“脚下一格”
function r13_server_sell_allocate(name)
    local spot,why=r13_find_market_barrel_spot(name)
    if not spot then return nil,why end
    local ok,res=pcall(game.isCmdSuccess,string.format("setblock %d %d %d barrel",spot.x,spot.y,spot.z))
    if not ok or res~=true then return nil,"木桶放置失败" end
    return spot
end

function server_sell_validate_session(name,d)
    local s=server_sell_get_session(d,name)
    if type(s)~="table" or type(s.barrel_pos)~="table" then return nil,false end
    if tostring(s.owner_uuid or uuid_key(name))~=tostring(uuid_key(name)) then return nil,false end
    local p=s.barrel_pos
    local ok,b=market_region_one_block(math.floor(p.x),math.floor(p.y),math.floor(p.z))
    if not ok or type(b)~="table" or not lower(tostring(b.name or b.id or "")):find("barrel",1,true) then return s,false end
    return s,true
end

function server_sell_begin(name)
    if not market_scoreboard_ready() then send(name,"§c服务器尚未设置积分版。"); return true end
    local d,r=player_record(name,true)
    if server_sell_session_expired(name,d,r) then d,r=player_record(name,true) end
    local old,valid=server_sell_validate_session(name,d)
    if valid then set_menu(d,r,"server_sell_wait"); send(name,"§e你已经有一个待出售木桶。§f输入1结算，0取消。"); return true end
    server_sell_clear_session(d,name)
    local spot,why=r13_server_sell_allocate(name)
    if not spot then send(name,"§c无法创建出售木桶："..tostring(why)); return true end
    local now=util.timestamp()
    server_sell_set_session(d,name,{barrel_pos={x=spot.x,y=spot.y,z=spot.z,dimension=spot.dimension},owner=tostring(name),owner_uuid=uuid_key(name),session_token=tostring(uuid_key(name))..":"..now,created_at=now,expires_at=now+180,status="waiting"})
    set_menu(d,r,"server_sell_wait"); r.menu_expires=now+180; save_data(d)
    send(name,"§a✦ 出售木桶已放在附近。\n§f放入物品后输入 §e1 §f结算；输入 §70 §f取消。\n§7木桶坐标按玩家独立保存，不会串到别人会话。")
    return true
end

function cancel_server_sell_state(name,reason)
    local d,r=player_record(name,true)
    local s=server_sell_get_session(d,name)
    if type(s)=="table" and type(s.barrel_pos)=="table" then
        local p=s.barrel_pos
        pcall(game.isCmdSuccess,string.format("setblock %d %d %d air replace",math.floor(p.x),math.floor(p.y),math.floor(p.z)))
        server_sell_cleanup_drops(math.floor(p.x),math.floor(p.y),math.floor(p.z))
    end
    server_sell_clear_session(d,name); d.server_sell_pending=nil
    if r.menu=="server_sell_list" or r.menu=="server_sell_wait" then r.menu=nil; r.menu_expires=nil end
    save_data(d); if reason and reason~="" then send(name,reason) end; return true
end

function market_finish_server_sell(name)
    local d,r=player_record(name,true)
    if server_sell_session_expired(name,d,r) then return true end
    d,r=player_record(name,true)
    local s,valid=server_sell_validate_session(name,d)
    if not valid then send(name,"§c出售失败：你的独立出售木桶已经不存在。"); return true end
    if s.status=="processing" or s.status=="completed" then send(name,"§c这笔出售已经处理过。"); return true end
    s.status="processing"
    local p=s.barrel_pos
    local ok,data,err=market_region_one_block(math.floor(p.x),math.floor(p.y),math.floor(p.z))
    if not ok or type(data)~="table" then s.status="waiting"; save_data(d); send(name,"§c读取木桶失败："..tostring(err)); return true end
    local nbt=data.nbt or data.NBT or data.blockEntityNbt or data.block_entity_nbt
    local items=type(nbt)=="table" and nbt.Items or nil
    if type(items)~="table" then s.status="waiting"; save_data(d); send(name,"§c木桶内没有可读取物品。"); return true end
    local total,detail,bad=0,{},{ }
    for _,item in pairs(items) do
        local count=tonumber(item.Count or item.count or 0) or 0
        if count>0 then
            local unit,why=sell_table_lookup(item)
            if not unit then bad[#bad+1]=why else total=total+unit*count; detail[#detail+1]=translated_item_name(item).." ×"..count.." = "..(unit*count).."金币" end
        end
    end
    if #bad>0 then s.status="waiting"; save_data(d); send(name,"§c出售失败：\n§7"..table.concat(bad,"\n§7")); return true end
    if total<=0 then s.status="waiting"; save_data(d); send(name,"§c木桶内没有支持出售的物品。"); return true end
    local board=market_scoreboard_ready(); if not board then s.status="waiting"; save_data(d); send(name,"§c积分版不存在。"); return true end
    local okc,res=pcall(game.isCmdSuccess,'scoreboard players add "'..r13_safe_name(name)..'" '..board..' '..math.floor(total))
    if not okc or res~=true then s.status="waiting"; save_data(d); send(name,"§c金币发放失败，木桶未清空。"); return true end
    pcall(game.isCmdSuccess,string.format("setblock %d %d %d air replace",math.floor(p.x),math.floor(p.y),math.floor(p.z)))
    server_sell_cleanup_drops(math.floor(p.x),math.floor(p.y),math.floor(p.z))
    append_json_log(PURCHASE_LOG_FILE,{at=util.timestamp(),type="服务器收购",seller=name,seller_uuid=uuid_key(name),total=total,items=detail})
    server_sell_clear_session(d,name); clear_menu(d,r); save_data(d)
    send(name,"§a出售成功！\n§f"..table.concat(detail,"\n§f").."\n§6共获得 "..math.floor(total).." 金币。")
    return true
end

-- -----------------------------------------------------------------
-- 3) 导入/导出：保持原点相对坐标；拒绝“空气假成功”
-- -----------------------------------------------------------------
function place_native_region(playerName,name,tx,ty,tz)
    local m,err=load_native_manifest(name)
    if not m then return false,err end
    tx,ty,tz=math.floor(tonumber(tx) or 0),math.floor(tonumber(ty) or 0),math.floor(tonumber(tz) or 0)
    local origin=m.origin or {}
    local ox,oy,oz=tonumber(origin.x),tonumber(origin.y),tonumber(origin.z)
    if not ox or not oy or not oz then return false,"区域文件缺少原始 origin。" end
    local list,solid={},0
    for key,v in pairs(m.blocks or {}) do
        local sx,sy,sz=tostring(key):match("^(-?%d+),(-?%d+),(-?%d+)$")
        if sx and type(v)=="table" then
            local bn=tostring(v.name or v.id or "")
            if bn~="" then
                local item={x=tonumber(sx)-ox,y=tonumber(sy)-oy,z=tonumber(sz)-oz,name=bn}
                if v.states~=nil then item.states=v.states end
                if type(v.nbt)=="table" then item.nbt=normalize_import_nbt(v.nbt) end
                list[#list+1]=item
                if not lower(bn):find("air",1,true) then solid=solid+1 end
            end
        end
    end
    if #list==0 then return false,"导出文件没有方块记录。" end
    if solid==0 then return false,"导出文件只包含空气，已拒绝导入，防止把空数据当成功。" end
    table.sort(list,function(a,b) if a.y~=b.y then return a.y<b.y end; if a.z~=b.z then return a.z<b.z end; return a.x<b.x end)
    local ok,job=pcall(game.importBlocks,list,{x=tx,y=ty,z=tz,dimension=dim_exec(detect_dimension(playerName)),speed=-1,region_mode=1,anti_loss=true})
    if not ok then return false,"importBlocks 调用失败："..tostring(job) end
    local okw,finished=pcall(game.importWait,job)
    if not okw or finished~=true then return false,"导入任务没有返回完成状态："..tostring(finished) end
    log_event("NBT_REGION",tostring(playerName).." imported "..tostring(name).." blocks="..#list.." solid="..solid.." preserve_origin=true")
    return true,"§a导入完成：§e"..tostring(name).." §f共"..#list.."格，其中非空气"..solid.."格。\n§7已按原始 origin 保留坐标偏移。"
end

