R13_NOTICE_LINES_FILE = game.dataDir().."/server_announcement_lines.json"
R13_DEFAULT_GROUP = "1121432132"
R13_SERVER_NAME = "疣螈的SMP服务器"

function r13_notice_load()
    local ok,d=pcall(util.json_load,R13_NOTICE_FILE)
    if not ok or type(d)~="table" then d={} end
    if trim(tostring(d.qq_group or ""))=="" then d.qq_group=R13_DEFAULT_GROUP end
    if trim(tostring(d.server_name or ""))=="" then d.server_name=R13_SERVER_NAME end
    return d
