function patch_server_number_set(name,num,days)
    if not is_admin(name) then send(name,"§c只有管理员可以设置群号。"); return true end
    num=trim(tostring(num or ""))
    if not num:match("^%d+$") then send(name,"§c群号只能填写数字。"); return true end
    local d=r13_notice_load(); d.qq_group=num; d.updated_by=name; pcall(util.json_write,R13_NOTICE_FILE,d)
    patch_sidebar_update(true)
    send(name,"§aQQ群已更新为：§e"..num)
    return true
end

function patch_try_tps()
    local cands={
        {"game.getServerTPS",function() return game.getServerTPS() end},
        {"game.getTPS",function() return game.getTPS() end},
        {"game.serverTPS",function() return game.serverTPS() end},
    }
    for _,c in ipairs(cands) do
        local ok,v=pcall(c[2]); local n=tonumber(v)
        if ok and n and n>=0 and n<=40 then return n,c[1] end
    end
    return nil,"Prism当前公开API未提供TPS"
end

function r13_online_count()
    local ok,list=pcall(game.getOnlinePlayers)
    if ok and type(list)=="table" then local n=0; for _ in pairs(list) do n=n+1 end; return n end
    local t=online_players() or {}; return #t
end

function patch_sidebar_update(force)
    local now=util.timestamp()
    PATCH_SIDEBAR_LAST=tonumber(PATCH_SIDEBAR_LAST) or 0
    if not force and now-PATCH_SIDEBAR_LAST<60 then return true end
    PATCH_SIDEBAR_LAST=now
    local cfg=r13_notice_load(); local tps=patch_try_tps()
    local lines={
        "§b§l✦ 服务器公告 ✦",
        "§f"..tostring(cfg.server_name),
        "§fTPS："..(tps and ("§a"..string.format("%.1f",tps)) or "§7--"),
        "§f在线：§a"..tostring(r13_online_count()),
        "§f北京时间：§e"..r13_beijing_time(now,false),
        "§fQQ群：§b"..tostring(cfg.qq_group),
        "§6金币榜 §f.金币排行",
        "§d公会榜 §f.公会排行",
        "§b帮助 §f.help",
    }
    pcall(game.sendCommand,'scoreboard objectives add ds_notice dummy "§b公告栏"')
    pcall(game.sendCommand,"scoreboard objectives setdisplay sidebar ds_notice")
    local old={}; local ok,od=pcall(util.json_load,R13_NOTICE_LINES_FILE); if ok and type(od)=="table" and type(od.lines)=="table" then old=od.lines end
    for _,line in ipairs(old) do pcall(game.sendCommand,'scoreboard players reset "'..r13_safe_name(line)..'" ds_notice') end
    local saved={}; local score=#lines
    for _,line in ipairs(lines) do
        saved[#saved+1]=line
        pcall(game.sendCommand,'scoreboard players set "'..r13_safe_name(line)..'" ds_notice '..score)
        score=score-1
    end
    pcall(util.json_write,R13_NOTICE_LINES_FILE,{lines=saved})
    return true
end

