-- -----------------------------------------------------------------
-- 6) 命令容器：固定语法 + 条件/无条件 + 脉冲/循环/连锁 + TXT
-- -----------------------------------------------------------------
function parse_command_txt(text)
    local arr={}; local idx=0
    for line in tostring(text or ""):gmatch("[^\r\n]+") do
        local s=trim(line)
        if s~="" and not s:match("^#") and not s:match("^//") then
            local typ,cond,cmd=s:match("^%[([^%]]+)%]%s*%[([^%]]+)%]%s*(.+)$")
            if not typ then
                local p1,p2,rest=s:match("^([RCPrcp循环连锁脉冲]+)%s+([01OCoc有无条件]+)%s+(.+)$")
                typ,cond,cmd=p1,p2,rest
            end
            if not typ then typ="连锁"; cond="无条件"; cmd=s end
            local t=lower(trim(typ)); local c=lower(trim(cond)); cmd=trim(cmd)
            local kind="chain"
            if t=="r" or t=="循环" or t=="repeating" then kind="repeating"
            elseif t=="p" or t=="脉冲" or t=="impulse" then kind="impulse"
            elseif t=="c" or t=="连锁" or t=="chain" then kind="chain" end
            local conditional=(c=="1" or c=="c" or c=="有条件" or c=="条件" or c=="conditional")
            if cmd~="" then idx=idx+1; arr[#arr+1]={index=idx,kind=kind,conditional=conditional,command=normalize_cmd(cmd),last_success=false} end
        end
    end
    return arr
end

function cmd_container_import(name,file_name)
    if not is_admin(name) then send(name,"§c只有管理员可以导入命令容器TXT。"); return true end
    file_name=trim(tostring(file_name or "")); file_name=file_name:match("([^/\\]+)$") or file_name
    if file_name=="" then send(name,"§e用法：.命令容器导入 文件名.txt"); return true end
    local nodes,path=cmd_container_load_txt(name,file_name)
    if not nodes then send(name,"§c"..tostring(path)); return true end
    if #nodes==0 then send(name,"§cTXT中没有有效命令节点。"); return true end
    local d=cmd_container_db(); local id=tonumber(d.next_id or 1); d.next_id=id+1
    d.items[tostring(id)]={id=id,name=file_name,enabled=false,nodes=nodes,source=path,created_by=name,created_at=util.timestamp(),run_count=0}
    cmd_container_save(d)
    send(name,"§a✦ 命令容器导入成功 #"..id.."\n§f节点：§e"..#nodes.."\n§7支持：[循环/连锁/脉冲][有条件/无条件] 命令")
    return true
end

function cmd_container_tick()
    local d=cmd_container_db(); local dirty=false
    for _,box in pairs(d.items or {}) do
        if type(box)=="table" and box.enabled==true and type(box.nodes)=="table" and #box.nodes>0 then
            local prev=true
            local first=true
            for _,node in ipairs(box.nodes) do
                local execute=true
                if node.conditional and prev~=true then execute=false end
                if execute then
                    if node.kind=="impulse" and node.fired==true then
                        prev=node.last_success==true
                    else
                        local ok,res=pcall(game.isCmdSuccess,normalize_cmd(node.command))
                        prev=(ok and res==true); node.last_success=prev; node.last_run=util.timestamp()
                        if node.kind=="impulse" then node.fired=true end
                        dirty=true
                    end
                else prev=false end
                first=false
            end
            box.run_count=(tonumber(box.run_count) or 0)+1
            -- 没有循环节点的容器执行一次后自动停，模拟脉冲起点+连锁
            local has_repeat=false; for _,n in ipairs(box.nodes) do if n.kind=="repeating" then has_repeat=true; break end end
            if not has_repeat then box.enabled=false; dirty=true end
        end
    end
    if dirty then cmd_container_save(d) end
end

function cmd_container_show(name)
    local d=cmd_container_db(); local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§b§l✦ 命 令 容 器 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§f① TXT导入   ② 容器列表   ③ 启动/停止","§7TXT格式：§f[循环][无条件] say 你好","§7也支持：§f[连锁][有条件] ...  /  [脉冲][无条件] ..."}
    local arr={}; for id,v in pairs(d.items or {}) do arr[#arr+1]={id=id,v=v} end; table.sort(arr,function(a,b) return tonumber(a.id)<tonumber(b.id) end)
    for i=1,math.min(#arr,8) do local x=arr[i]; lines[#lines+1]="§f#"..x.id.." §e"..tostring(x.v.name).." §8│ "..(x.v.enabled and "§a运行" or "§c停止").." §8│ §7"..#(x.v.nodes or {}).."节点" end
    local d0,r0=player_record(name,true); set_menu(d0,r0,"cmd_container_main"); send(name,table.concat(lines,"\n")); return true
end

-- -----------------------------------------------------------------
-- 7) 公会系统：数据迁移/等级/活跃/贡献/资金/生命周期
-- -----------------------------------------------------------------
GUILD_APPLICATION_FILE = GUILD_APPLICATION_FILE or (GUILD_DIR.."/applications.json")
GUILD_ACHIEVEMENT_FILE = GUILD_ACHIEVEMENT_FILE or (GUILD_DIR.."/achievements.json")
GUILD_WEEKLY_FILE = GUILD_WEEKLY_FILE or (GUILD_DIR.."/weekly.json")

function guild_init_files()
    local d=guild_load(GUILD_FILE,{next_id=1,items={}}); d.items=d.items or {}; d.next_id=tonumber(d.next_id) or 1
    for _,g in pairs(d.items) do
        if type(g)=="table" then
            g.level=math.max(1,math.min(10,tonumber(g.level) or 1)); g.exp=tonumber(g.exp) or 0; g.funds=tonumber(g.funds) or 0
            g.theme=g.theme or "冰霜"; g.development=g.development or "城建"; g.status=g.status or "normal"; g.public=(g.public~=false)
            g.members=g.members or {}; g.created_at=tonumber(g.created_at) or util.timestamp(); g.last_activity_at=tonumber(g.last_activity_at) or g.created_at
            for _,m in ipairs(g.members) do m.role=r13_guild_role(m.role); m.contribution=tonumber(m.contribution) or 0; m.online_seconds=tonumber(m.online_seconds) or 0; m.activity=tonumber(m.activity) or 0 end
        end
    end
    guild_save(GUILD_FILE,d)
    local defs={
        [GUILD_PLAYER_FILE]={players={},history={}},[GUILD_LOG_FILE]={logs={}},[GUILD_VOTE_FILE]={votes={}},[GUILD_TASK_FILE]={guilds={}},
        [GUILD_DIPLOMACY_FILE]={relations={}},[GUILD_NOTICE_FILE]={guilds={}},[GUILD_ACTIVITY_FILE]={players={}},[GUILD_APPLICATION_FILE]={next_id=1,items={}},
        [GUILD_ACHIEVEMENT_FILE]={guilds={}},[GUILD_WEEKLY_FILE]={guilds={}},
    }
    for p,def in pairs(defs) do local x=guild_load(p,def); guild_save(p,x) end
    pcall(util.write_file,GUILD_VERSION_FILE,FINAL_PATCH_VERSION.."\n")
end

function guild_member_role(g,name)
    local u=uuid_key(name)
    for _,m in ipairs((g and g.members) or {}) do if tostring(m.uuid or "")==tostring(u) then return r13_guild_role(m.role) end end
    return nil
end

function guild_is_manager(g,name)
    local r=guild_member_role(g,name)
    return r=="owner" or r=="deputy" or is_admin(name)
end

function guild_max_members(lv)
    lv=math.max(1,math.min(10,tonumber(lv) or 1)); return 10+(lv-1)*5
end

function guild_level_title(lv)
    local a={"初启","新芽","成长","兴盛","璀璨","荣耀","圣辉","至尊","永恒","传奇"}
    return a[math.max(1,math.min(10,tonumber(lv) or 1))]
end

function guild_exp_need(lv) return 500*math.max(1,tonumber(lv) or 1) end
function guild_upgrade_cost(lv) return 1000*math.max(1,tonumber(lv) or 1) end
function guild_min_members_for_level(lv) return math.max(1,math.ceil((tonumber(lv) or 1)/2)) end

function guild_route_bonus(g,kind)
    local r=tostring(g.development or "城建")
    if r=="商业" and kind=="funds" then return 1.20 end
    if r=="冒险" and kind=="exp" then return 1.20 end
    if r=="荣耀" and kind=="activity" then return 1.10 end
    if r=="城建" and kind=="upgrade_cost" then return 0.90 end
    return 1.0
end

function r13_guild_save_one(g)
    local gd=guild_load(GUILD_FILE,{next_id=1,items={}}); gd.items=gd.items or {}; gd.items[tostring(g.id)]=g; guild_save(GUILD_FILE,gd)
end

function guild_progress(g,name,exp,contrib,funds)
    exp=math.max(0,math.floor((tonumber(exp) or 0)*guild_route_bonus(g,"exp")))
    contrib=math.max(0,math.floor(tonumber(contrib) or 0))
    funds=math.max(0,math.floor((tonumber(funds) or 0)*guild_route_bonus(g,"funds")))
    g.exp=(tonumber(g.exp) or 0)+exp; g.funds=(tonumber(g.funds) or 0)+funds; g.total_contribution=(tonumber(g.total_contribution) or 0)+contrib; g.last_activity_at=util.timestamp(); g.status="normal"
    local u=uuid_key(name)
    for _,m in ipairs(g.members or {}) do if tostring(m.uuid)==tostring(u) then m.contribution=(tonumber(m.contribution) or 0)+contrib; break end end
    return exp,contrib,funds
end

function guild_try_upgrade(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    if not guild_is_manager(g,name) then send(name,"§c只有会长/副会长可以升级公会。"); return true end
    local lv=tonumber(g.level) or 1; if lv>=10 then send(name,"§d✦ 当前已经是最高等级：传奇公会。"); return true end
    local need=guild_exp_need(lv); local cost=math.floor(guild_upgrade_cost(lv)*guild_route_bonus(g,"upgrade_cost")); local minm=guild_min_members_for_level(lv+1)
    if (tonumber(g.exp) or 0)<need then send(name,"§c公会经验不足："..g.exp.."/"..need); return true end
    if (tonumber(g.funds) or 0)<cost then send(name,"§c公会资金不足："..g.funds.."/"..cost); return true end
    if #(g.members or {})<minm then send(name,"§c成员数量不足：至少需要"..minm.."人。"); return true end
    g.exp=g.exp-need; g.funds=g.funds-cost; g.level=lv+1; g.title=guild_level_title(g.level); g.max_members=guild_max_members(g.level); g.level_up_at=util.timestamp()
    r13_guild_save_one(g); guild_log(g.id,"公会升级",name,"Lv."..lv.." → Lv."..g.level.."；资金-"..cost)
    send(name,"§a✦ 公会升级成功！\n§f当前：§dLv."..g.level.." · "..guild_level_title(g.level).."\n§f成员上限：§b"..guild_max_members(g.level).."\n§7等级越高，成员容量与任务收益逐步提高。")
    return true
end

function guild_activity_tick()
    local gd=guild_load(GUILD_FILE,{next_id=1,items={}}); local now=util.timestamp(); local on=online_players() or {}; local online={}
    for _,n in ipairs(on) do online[tostring(uuid_key(n))]=n end
    local taskdb=guild_load(GUILD_TASK_FILE,{guilds={}}); taskdb.guilds=taskdb.guilds or {}
    local day=os.date("!%Y-%m-%d",now+8*3600)
    for _,g in pairs(gd.items or {}) do
        if g.status~="dissolved" then
            local inc=0
            for _,m in ipairs(g.members or {}) do
                if online[tostring(m.uuid)] then m.online_seconds=(tonumber(m.online_seconds) or 0)+60; m.activity=(tonumber(m.activity) or 0)+60; inc=inc+60 end
            end
            if inc>0 then g.online_seconds=(tonumber(g.online_seconds) or 0)+inc; g.last_activity_at=now; g.status="normal" end
            local age=now-(tonumber(g.last_activity_at) or now)
            if age>=30*86400 then g.status="dormant" elseif age>=7*86400 then g.status="low_activity" else g.status="normal" end
            local t=taskdb.guilds[g.id]
            if type(t)~="table" or t.day~=day then t={day=day,signins=0,online_minutes=0,claimed=false}; taskdb.guilds[g.id]=t end
            t.online_minutes=(tonumber(t.online_minutes) or 0)+math.floor(inc/60)
            local sign=0; for _,m in ipairs(g.members or {}) do local sg=g.signins and g.signins[tostring(m.uuid)]; if type(sg)=="table" and sg.day==day then sign=sign+1 elseif sg==day then sign=sign+1 end end; t.signins=sign
        end
    end
    guild_save(GUILD_FILE,gd); guild_save(GUILD_TASK_FILE,taskdb)
end

function guild_activity_score(g)
    local online_minutes=math.floor((tonumber(g.online_seconds) or 0)/60)
    local signup=0; if type(g.signins)=="table" then for _ in pairs(g.signins) do signup=signup+1 end end
    return math.floor((online_minutes + signup*5)*guild_route_bonus(g,"activity"))
end

function guild_rankings(name,kind)
    kind=kind or "level"; local gd=guild_load(GUILD_FILE,{items={}}); local arr={}
    for _,g in pairs(gd.items or {}) do
        if g.status~="dissolved" then
            local v=0
            if kind=="activity" then v=guild_activity_score(g)
            elseif kind=="funds" then v=tonumber(g.funds) or 0
            elseif kind=="contribution" then v=tonumber(g.total_contribution) or 0
            else v=(tonumber(g.level) or 1)*100000+(tonumber(g.exp) or 0) end
            arr[#arr+1]={g=g,v=v}
        end
    end
    table.sort(arr,function(a,b) if a.v==b.v then return tostring(a.g.name)<tostring(b.g.name) end return a.v>b.v end)
    local title=kind=="activity" and "公会活跃榜" or (kind=="funds" and "公会资金榜" or (kind=="contribution" and "公会贡献榜" or "公会等级榜"))
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§d✦ "..title.." ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    for i=1,math.min(10,#arr) do local g=arr[i].g; lines[#lines+1]=string.format("§f%d. §e%s §7Lv.%s §8│ §b%s/%s §8│ §d%s",i,tostring(g.name),tostring(g.level),guild_online_count(g),#(g.members or {}),tostring(arr[i].v)) end
    if #arr==0 then lines[#lines+1]="§7暂无公会。" end
    send(name,table.concat(lines,"\n")); return true
end

-- -----------------------------------------------------------------
-- 8) 公会领地：创建/重叠/换址/删除/设施/保护
-- -----------------------------------------------------------------
function guild_overlap_with_existing(candidate,ignore_gid)
    local td=territory_db()
    for _,t in pairs(td.items or {}) do
        if type(t)=="table" and not t.deleted and r13_rect_overlap(candidate,t) then return true,"普通领地 #"..tostring(t.id) end
    end
    local gd=guild_load(GUILD_FILE,{items={}})
    for gid,g in pairs(gd.items or {}) do
        if tostring(gid)~=tostring(ignore_gid or "") and g.status~="dissolved" and type(g.territory)=="table" and r13_rect_overlap(candidate,g.territory) then return true,"公会「"..tostring(g.name).."」" end
    end
    return false,nil
end

function guild_facility_set(name,kind)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    if not guild_is_manager(g,name) then send(name,"§c只有会长、副会长或管理员可以设置公会设施。"); return true end
    local p=player_position(name,false); if not p then send(name,"§c无法读取当前位置。"); return true end
    if not r13_guild_contains(g,p) then send(name,"§c公会传送点和仓库点必须设置在本公会领地内部。"); return true end
    local v={x=math.floor(p.x),y=math.floor(p.y),z=math.floor(p.z),dimension=p.dimension,by=name,at=util.timestamp()}
    if kind=="tp" then g.teleport_point=v else g.warehouse_point=v end
    r13_guild_save_one(g); guild_log(g.id,kind=="tp" and "设置公会传送点" or "设置公会仓库点",name,"坐标保密")
    send(name,kind=="tp" and "§a公会传送点已设置。" or "§a公会仓库传送点已设置。")
    return true
end

function guild_teleport(name,kind)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    local p=kind=="warehouse" and g.warehouse_point or g.teleport_point
    if type(p)~="table" then send(name,kind=="warehouse" and "§e公会尚未设置仓库传送点。" or "§e公会尚未设置传送点。"); return true end
    if not r13_guild_contains(g,p) then send(name,"§c该传送点已经不在当前公会领地内，请会长/副会长重新设置。"); return true end
    local cmd=string.format('execute as @a[name="%s"] in %s run tp @s %.2f %.2f %.2f',r13_safe_name(name),dim_exec(p.dimension),tonumber(p.x),tonumber(p.y),tonumber(p.z))
    local ok,res=pcall(game.isCmdSuccess,cmd)
    send(name,(ok and res==true) and (kind=="warehouse" and "§a已传送到公会仓库。" or "§a已传送到公会区域。") or "§c传送失败，请检查目标区块与维度。")
    return true
end

function guild_delete_territory(name,force)
    local g=guild_find_player(name); if not g then send(name,"§c公会不存在。"); return true end
    local role=guild_member_role(g,name)
    if role~="owner" and not (force and is_admin(name)) and not is_admin(name) then send(name,"§c只有会长或管理员可以删除公会领地。"); return true end
    if type(g.territory)~="table" then send(name,"§7当前公会没有领地。"); return true end
    g.territory=nil; g.teleport_point=nil; g.warehouse_point=nil; g.territory_deleted_at=util.timestamp(); r13_guild_save_one(g)
    guild_log(g.id,"删除公会领地",name,force and "管理员强制" or "会长主动")
    send(name,"§a公会领地已删除，重新获得一次创建公会领地的资格。\n§7旧传送点与旧仓库点已同时失效。")
    return true
end

function guild_relocate_start(name)
    local g=guild_find_player(name); if not g then send(name,"§c公会不存在。"); return true end
    if guild_member_role(g,name)~="owner" and not is_admin(name) then send(name,"§c只有会长或管理员可以更换公会领地。"); return true end
    local d,r=player_record(name,true); r.guild_relocate={guild_id=g.id,step="start",started_at=util.timestamp()}; set_menu(d,r,"guild_relocate_start_confirm"); save_data(d)
    send(name,"§d✦ 更换公会领地 ✦\n§f请先站到新的§e起始坐标§f位置。\n§a1 确定  §c0 取消\n§7不会在聊天框公开坐标。")
    return true
end

function guild_protect_tick()
    local gd=guild_load(GUILD_FILE,{items={}}); local names=online_players() or {}; local positions={}
    for _,name in ipairs(names) do local p=player_position(name,true) or player_position(name,false); if p then positions[name]=p end end
    for _,g in pairs(gd.items or {}) do
        if g.status~="dissolved" and type(g.territory)=="table" then
            for _,name in ipairs(names) do
                local p=positions[name]
                if p and r13_guild_contains(g,p) and guild_member_role(g,name)==nil and not is_admin(name) then
                    local last=RUNTIME and RUNTIME.last_pos and RUNTIME.last_pos[name] or nil
                    local dest=nil
                    if type(last)=="table" and not r13_guild_contains(g,last) then dest=last end
                    if not dest then
                        local t=g.territory; local x1=math.min(t.x1,t.x2); local z1=math.min(t.z1,t.z2); dest={x=x1-2,y=p.y,z=z1-2,dimension=p.dimension}
                    end
                    local cmd=string.format('execute as @a[name="%s"] in %s run tp @s %.2f %.2f %.2f',r13_safe_name(name),dim_exec(dest.dimension),dest.x,dest.y,dest.z)
                    pcall(game.isCmdSuccess,cmd); send(name,"§c这里是「"..tostring(g.name).."」公会领地，只有本公会成员可以进入。")
                end
            end
        end
    end
end

-- -----------------------------------------------------------------
-- 9) 公会签到/任务/公告/邀请码/公开申请/搜索/排行/周报
-- -----------------------------------------------------------------
function guild_signin(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    local day=os.date("!%Y-%m-%d",util.timestamp()+8*3600); local u=uuid_key(name); g.signins=g.signins or {}; local old=g.signins[u]
    if (type(old)=="table" and old.day==day) or old==day then send(name,"§e你今天已经完成公会签到。"); return true end
    local reward=final_ai_signin_reward and final_ai_signin_reward() or {id="bread",count=6,text="面包 ×6"}
    g.signins[u]={day=day,count=(type(old)=="table" and tonumber(old.count) or 0)+1}
    local exp,con,fund=guild_progress(g,name,10,20,20); r13_guild_save_one(g); guild_log(g.id,"公会签到",name,"贡献+"..con.." 经验+"..exp.." 资金+"..fund)
    pcall(game.sendCommand,'give "'..r13_safe_name(name)..'" minecraft:'..reward.id..' '..reward.count)
    send(name,"§d✦ 公会签到成功 ✦\n§fAI每日奖励：§e"..reward.text.."\n§f贡献：§d+"..con.."  §f公会经验：§b+"..exp.."  §f公会资金：§6+"..fund)
    return true
end

function guild_task_today(g)
    local day=os.date("!%Y-%m-%d",util.timestamp()+8*3600); local db=guild_load(GUILD_TASK_FILE,{guilds={}}); db.guilds=db.guilds or {}; local t=db.guilds[g.id]
    if type(t)~="table" or t.day~=day then t={day=day,signins=0,online_minutes=0,claimed=false}; db.guilds[g.id]=t; guild_save(GUILD_TASK_FILE,db) end
    return t,db
end

function guild_task_menu(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    local t=guild_task_today(g); local need_sign=math.min(5,math.max(1,#(g.members or {}))); local need_online=60
    local done=(tonumber(t.signins) or 0)>=need_sign and (tonumber(t.online_minutes) or 0)>=need_online
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§b✦ 今 日 公 会 任 务 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§f成员签到：§e"..tostring(t.signins or 0).."/"..need_sign,"§f累计在线：§e"..tostring(t.online_minutes or 0).."/"..need_online.."分钟","§f状态："..(t.claimed and "§7已领取" or (done and "§a可领取" or "§e进行中")),"§7完成后输入1领取；.stop退出。"}
    local d,r=player_record(name,true); set_menu(d,r,"guild_task_claim"); send(name,table.concat(lines,"\n")); return true
end

function guild_task_claim(name,msg)
    local g=guild_find_player(name); if not g then return true end
    local t,db=guild_task_today(g); local need_sign=math.min(5,math.max(1,#(g.members or {})))
    if tostring(msg)~="1" then send(name,"§e输入1领取；.stop退出。"); return true end
    if t.claimed then send(name,"§7今天已经领取过公会任务奖励。"); return true end
    if (tonumber(t.signins) or 0)<need_sign or (tonumber(t.online_minutes) or 0)<60 then send(name,"§c任务尚未完成。"); return true end
    t.claimed=true; db.guilds[g.id]=t; guild_save(GUILD_TASK_FILE,db)
    local exp,con,fund=guild_progress(g,name,100,50,200); r13_guild_save_one(g)
    send(name,"§a✦ 公会任务奖励已领取 ✦\n§d贡献 +"..con.."  §b经验 +"..exp.."  §6资金 +"..fund); return true
end

function guild_generate_invite(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    if not guild_is_manager(g,name) then send(name,"§c只有会长/副会长可以生成邀请码。"); return true end
    if trim(tostring(g.invite_code or ""))=="" then
        g.invite_code=string.format("%02X%02X-%04X",math.random(0,255),math.random(0,255),math.random(0,65535))
        g.invite_created_at=util.timestamp(); r13_guild_save_one(g)
    end
    send(name,"§d✦ 公会邀请码 ✦\n§f公会：§e"..g.name.."\n§f邀请码：§6"..g.invite_code.."\n§7邀请码可重复使用；公会解散后自动失效。")
    return true
end

function guild_accept_invite(name,code)
    if guild_find_player(name) then send(name,"§c你已经加入公会。"); return true end
    local g=guild_find_by_invite(code); if not g or g.status=="dissolved" then send(name,"§c邀请码不存在或已失效。"); return true end
    if #(g.members or {})>=guild_max_members(g.level) then send(name,"§c该公会成员已满。"); return true end
    local u=uuid_key(name); g.members[#g.members+1]={uuid=u,name=name,role="member",joined_at=util.timestamp(),contribution=0,activity=0,online_seconds=0}; g.last_activity_at=util.timestamp(); r13_guild_save_one(g)
    guild_mark_history(name,g.id,"member"); guild_log(g.id,"邀请码加入",name,"邀请码="..tostring(code)); send(name,"§a✦ 已加入公会「"..g.name.."」！"); return guild_commands_menu(name)
end

function guild_post_notice(name,text)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    if not guild_is_manager(g,name) then send(name,"§c只有会长/副会长可以发布公告。"); return true end
    text=trim(tostring(text or "")); if text=="" then send(name,"§c公告不能为空。"); return true end; if #text>240 then send(name,"§c公告过长，请控制在240字符以内。"); return true end
    local db=guild_load(GUILD_NOTICE_FILE,{guilds={}}); db.guilds=db.guilds or {}; db.guilds[g.id]=db.guilds[g.id] or {}; table.insert(db.guilds[g.id],{at=util.timestamp(),by=name,text=text}); while #db.guilds[g.id]>30 do table.remove(db.guilds[g.id],1) end; guild_save(GUILD_NOTICE_FILE,db); g.notice=text; r13_guild_save_one(g); guild_log(g.id,"发布公告",name,text); return guild_announcement(name)
end

function guild_announcement(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    local db=guild_load(GUILD_NOTICE_FILE,{guilds={}}); local arr=db.guilds and db.guilds[g.id] or {}; local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§e✦『"..g.name.."』公告栏 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    if #arr==0 then lines[#lines+1]="§7暂无公告。" else for i=math.max(1,#arr-9),#arr do local n=arr[i]; lines[#lines+1]="§f"..r13_beijing_time(n.at,true).." §8│ §e"..tostring(n.by).."§7："..tostring(n.text) end end
    send(name,table.concat(lines,"\n")); return true
end

function guild_weekly_report(name)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    local total_hours=math.floor((tonumber(g.online_seconds) or 0)/3600); local active=guild_activity_score(g); local top={}
    for _,m in ipairs(g.members or {}) do top[#top+1]=m end; table.sort(top,function(a,b) return (tonumber(a.online_seconds) or 0)>(tonumber(b.online_seconds) or 0) end)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§b✦ 公 会 周 报 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§f累计在线：§a"..total_hours.."小时","§f公会活跃：§d"..active,"§f公会资金：§6"..tostring(g.funds or 0),"§f等级进度：§b"..tostring(g.exp or 0).."/"..guild_exp_need(g.level)}
    for i=1,math.min(3,#top) do lines[#lines+1]="§f"..i..". §e"..tostring(top[i].name).." §7在线"..math.floor((tonumber(top[i].online_seconds) or 0)/3600).."小时 §8│ 贡献"..tostring(top[i].contribution or 0) end
    send(name,table.concat(lines,"\n")); return true
end

-- -----------------------------------------------------------------
-- 10) 公会详情与菜单：未加入/曾加入/已加入分别显示，坐标永不公开
-- -----------------------------------------------------------------
function guild_player_history(name)
    local d=guild_player_map(); local k=uuid_key(name)
    return (type(d.history)=="table" and d.history[k]~=nil) or d.players[k]~=nil
end

function guild_mark_history(name,gid,role)
    local d=guild_player_map(); local k=uuid_key(name); d.players=d.players or {}; d.history=d.history or {}; d.players[k]=gid; d.history[k]={had_guild=true,last_guild_id=gid,last_role=r13_guild_role(role),updated_at=util.timestamp()}; guild_save(GUILD_PLAYER_FILE,d)
end

function guild_public_detail(name,gid)
    local gd=guild_load(GUILD_FILE,{items={}}); local g=gd.items and gd.items[tostring(gid or "")]
    if not g or g.status=="dissolved" then send(name,"§c公会不存在。"); return true end
    local nd=guild_load(GUILD_NOTICE_FILE,{guilds={}}); local arr=nd.guilds and nd.guilds[g.id] or {}; local last=arr[#arr]
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§d✦『"..tostring(g.name).."』公会 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§fID：§b"..tostring(g.id).."  §f等级：§dLv."..tostring(g.level or 1).." · "..guild_level_title(g.level),"§f会长：§e"..tostring(g.owner_name or "未知"),"§f成员：§b"..guild_online_count(g).."/"..#(g.members or {}).." §8（在线/总人数）","§f资金：§6"..tostring(g.funds or 0).."  §f活跃：§a"..guild_activity_score(g),"§f发展：§b"..tostring(g.development or "城建"),"§f状态：§7"..tostring(g.status or "normal"),"§f公告：§e"..tostring(last and last.text or g.notice or "暂无"),"§7领地坐标、传送点与仓库坐标不会公开。"}
    send(name,table.concat(lines,"\n"))
    if not guild_find_player(name) then local d,r=player_record(name,true); r.guild_detail_id=g.id; set_menu(d,r,"guild_public_detail"); send(name,"§a1 申请加入   §70 返回   §8│ .stop 退出") end
    return true
end

function guild_list(name)
    local gd=guild_load(GUILD_FILE,{items={}}); local arr={}
    for _,g in pairs(gd.items or {}) do if g.status~="dissolved" then arr[#arr+1]=g end end
    table.sort(arr,function(a,b) if (tonumber(a.level) or 1)==(tonumber(b.level) or 1) then return tostring(a.name)<tostring(b.name) end return (tonumber(a.level) or 1)>(tonumber(b.level) or 1) end)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§b✦ 公 会 列 表 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    for i=1,math.min(15,#arr) do local g=arr[i]; lines[#lines+1]=string.format("§f%02d §8│ §e%s §8│ §dLv.%s §8│ §b%s/%s",i,tostring(g.name),tostring(g.level),guild_online_count(g),#(g.members or {})) end
    if #arr==0 then lines[#lines+1]="§7暂无公会。" end
    lines[#lines+1]="§7输入编号查看公开信息；不会显示坐标。"
    local d,r=player_record(name,true); r.guild_list=arr; set_menu(d,r,"guild_list"); send(name,table.concat(lines,"\n")); return true
end

function guild_search_player(name,q)
    q=lower(trim(tostring(q or ""))); if q=="" then send(name,"§c请输入玩家名字关键词。"); return true end
    local gd=guild_load(GUILD_FILE,{items={}}); local res={}
    for _,g in pairs(gd.items or {}) do if g.status~="dissolved" then for _,m in ipairs(g.members or {}) do if lower(tostring(m.name or "")):find(q,1,true) then res[#res+1]={name=m.name,gid=g.id,gname=g.name,role=r13_guild_role(m.role)} end end end end
    table.sort(res,function(a,b) return tostring(a.name)<tostring(b.name) end)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§e✦ 玩家所属公会搜索 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}
    for i=1,math.min(20,#res) do local v=res[i]; lines[#lines+1]=string.format("§f%02d §8│ §e%s §8→ §d%s §7[%s]",i,tostring(v.name),tostring(v.gname),tostring(v.role)) end
    if #res==0 then lines[#lines+1]="§7没有找到匹配玩家。" else lines[#lines+1]="§7输入编号查看该玩家所在公会。" end
    local d,r=player_record(name,true); r.guild_search_players=res; set_menu(d,r,"guild_search_player_results"); send(name,table.concat(lines,"\n")); return true
end

function guild_commands_menu(name)
    local d,r=player_record(name,true); clear_menu(d,r); save_data(d)
    local g=guild_find_player(name)
    if not g then
        local old=guild_player_history(name); set_menu(d,r,old and "guild_return_main" or "guild_first")
        local title=old and "§b§l✦ 公 会 大 厅 ✦" or "§d§l✦ 公 会 创 立 ✦"
        local sub=old and "§7你当前没有加入公会。" or "§7你还没有创建或加入过公会。"
        send(name,table.concat({"§8§m━━━━━━━━━━━━━━━━━━━━━━━━",title,"§8§m━━━━━━━━━━━━━━━━━━━━━━━━",sub,"§f① 创建公会   ② 公会列表","§f③ 搜索公会   ④ 搜索玩家","§f⑤ 接受邀请码 ⑥ 我的申请","§f⑦ 公会等级榜 ⑧ 活跃度榜","§f⑨ 公会资金榜 ⑩ 公会玩法说明","§7.stop 退出"},"\n")); return true
    end
    set_menu(d,r,"guild_main")
    local c=guild_theme(g.theme); local role=guild_member_role(g,name) or "member"
    send(name,table.concat({"§8§m━━━━━━━━━━━━━━━━━━━━━━━━",c.."§l✦『"..tostring(g.name).."』公会 ✦§r","§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§dLv."..tostring(g.level).." · "..guild_level_title(g.level).."  §8│ §f身份：§e"..role,"§f在线：§a"..guild_online_count(g).."/"..#(g.members or {}).."  §8│ §f资金：§6"..tostring(g.funds or 0),"§f活跃：§d"..guild_activity_score(g).."  §8│ §f贡献：§b"..tostring(g.total_contribution or 0),"§f① 公会信息   ② 成员列表   ③ 每日签到   ④ 公会任务","§f⑤ 公会排行   ⑥ 公会成就   ⑦ 公会公告   ⑧ 公会领地","§f⑨ 公会设施   ⑩ 公会外交   ⑪ 公会发展   ⑫ 公会管理","§f⑬ 招募/邀请码 ⑭ 活跃排行   ⑮ 公会周报   ⑯ 公会升级","§7.stop 退出"},"\n")); return true
end

function guild_manage(name)
    local g=guild_find_player(name); if not g then return guild_commands_menu(name) end
    if not guild_is_manager(g,name) then send(name,"§c普通成员没有公会管理权限。"); return true end
    local d,r=player_record(name,true); set_menu(d,r,"guild_manage")
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§6§l✦ 公 会 管 理 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§f① 设置公会传送点   ② 设置仓库点","§f③ 发布公告         ④ 更换公会领地","§f⑤ 删除公会领地     ⑥ 解散公会","§f⑦ 外交关系         ⑧ 重大事项投票","§f⑨ 邀请码           ⑩ 公开申请开关","§f⑪ 入会申请审核     ⑫ 发展路线"}
    if is_admin(name) then lines[#lines+1]="§c⑬ 管理员后台" end; lines[#lines+1]="§7.stop 退出"; send(name,table.concat(lines,"\n")); return true
end

-- -----------------------------------------------------------------
-- 11) 公会创建流程：名字→启动资金→颜色→站到起始点1确认→3分钟终止点
-- -----------------------------------------------------------------
function guild_creation_start(name)
    if guild_find_player(name) then send(name,"§c你已经加入公会，不能重复创建。"); return true end
    local board=scoreboard_name(); if not board then send(name,"§c服务器尚未设置金币计分板。"); return true end
    local ok,b=pcall(game.getScore,board,name); local bal=ok and tonumber(b) or 0
    if bal<3000 then send(name,"§c创建公会需要3000金币；当前："..bal); return true end
    local d,r=player_record(name,true); r.guild_create={started_at=util.timestamp(),step="name"}; set_menu(d,r,"guild_create_name"); save_data(d)
    send(name,"§d✦ 创建公会 · 1/4 ✦\n§f请输入公会名称（2~16字符）。\n§7创建费：§63000金币  §8│ §f.stop §7取消")
    return true
end

function guild_create_finish(name)
    local d,r=player_record(name,true); local s=r.guild_create; if type(s)~="table" or type(s.territory)~="table" then send(name,"§c创建状态不完整。"); return true end
    local board=scoreboard_name(); if not board then return guild_create_abort(name,"§c金币计分板不存在，创建取消。") end
    local startup=math.max(0,math.floor(tonumber(s.startup) or 0)); local need=3000+startup; local ok,b=pcall(game.getScore,board,name); local bal=ok and tonumber(b) or 0
    if bal<need then send(name,"§c金币不足：需要"..need.."，当前"..bal.."。"); return true end
    local okc,res=pcall(game.isCmdSuccess,'scoreboard players remove "'..r13_safe_name(name)..'" '..board..' '..need)
    if not okc or res~=true then send(name,"§c扣除创建费用失败，公会未创建。"); return true end
    local gd=guild_load(GUILD_FILE,{next_id=1,items={}}); gd.items=gd.items or {}; local id="G"..string.format("%04d",tonumber(gd.next_id) or 1); gd.next_id=(tonumber(gd.next_id) or 1)+1; local u=uuid_key(name)
    local g={id=id,name=s.name,level=1,exp=0,title=guild_level_title(1),theme=s.theme or "冰霜",owner_uuid=u,owner_name=name,funds=startup,total_contribution=0,status="normal",public=true,created_at=util.timestamp(),last_activity_at=util.timestamp(),members={{uuid=u,name=name,role="owner",joined_at=util.timestamp(),contribution=0,activity=0,online_seconds=0}},territory=s.territory,teleport_point=s.start_point,warehouse_point=nil,development="城建",notice="欢迎加入"}
    gd.items[id]=g; guild_save(GUILD_FILE,gd); guild_mark_history(name,id,"owner"); guild_log(id,"创建公会",name,"创建费=3000；启动资金="..startup)
    r.guild_create=nil; clear_menu(d,r); save_data(d)
    send(name,"§a✦ 公会创建成功！\n§f名称：§e"..s.name.."  §8│ §fID：§b"..id.."\n§f等级：§dLv.1 · 初启  §8│ §f资金：§6"..startup.."\n§7公会传送点已自动设为创建领地时的起始位置。")
    return guild_commands_menu(name)
end

-- -----------------------------------------------------------------
-- 12) 公会投票/解散：管理员可强制；管理层重大事项投票
-- -----------------------------------------------------------------
function r13_active_vote(gid)
    local db=guild_load(GUILD_VOTE_FILE,{votes={}}); db.votes=db.votes or {}
    for id,v in pairs(db.votes) do if type(v)=="table" and tostring(v.guild_id)==tostring(gid) and v.status=="open" and util.timestamp()<tonumber(v.expire_at or 0) then return id,v,db end end
    return nil,nil,db
end

function guild_vote_start(name,subject,kind)
    local g=guild_find_player(name); if not g then send(name,"§c公会不存在。"); return true end
    if not guild_is_manager(g,name) then send(name,"§c只有会长/副会长可以发起重大投票。"); return true end
    local old=r13_active_vote(g.id); if old then send(name,"§e当前已有一个进行中的投票。"); return true end
    local db=guild_load(GUILD_VOTE_FILE,{votes={}}); db.votes=db.votes or {}; local id=tostring(util.timestamp()); db.votes[id]={id=id,guild_id=g.id,subject=tostring(subject),kind=tostring(kind),started_by=name,started_at=util.timestamp(),expire_at=util.timestamp()+300,yes={},no={},status="open"}; guild_save(GUILD_VOTE_FILE,db); guild_log(g.id,"发起投票",name,subject); send(name,"§e✦ 投票已发起："..tostring(subject).."\n§a1 支持  §c0 反对  §7（5分钟）"); return true
end

function guild_vote_cast(name,value)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    local role=guild_member_role(g,name); if role~="owner" and role~="deputy" then send(name,"§c只有会长/副会长参与管理层投票。"); return true end
    local id,v,db=r13_active_vote(g.id); if not v then send(name,"§7当前没有进行中的投票。"); return true end
    local u=uuid_key(name); v.yes[u]=nil; v.no[u]=nil; if tostring(value)=="1" then v.yes[u]=true else v.no[u]=true end
    local eligible=0; for _,m in ipairs(g.members or {}) do local rr=r13_guild_role(m.role); if rr=="owner" or rr=="deputy" then eligible=eligible+1 end end
    local yes,no=0,0; for _ in pairs(v.yes) do yes=yes+1 end; for _ in pairs(v.no) do no=no+1 end
    if yes+no>=eligible and eligible>0 then
        v.status=yes>no and "passed" or "rejected"; v.finished_at=util.timestamp(); guild_save(GUILD_VOTE_FILE,db); guild_log(g.id,"投票结束",name,"议题="..v.subject.."；结果="..v.status.."；"..yes..":"..no)
        if v.status=="passed" and v.kind=="dissolve" then
            g.status="dissolved"; g.dissolved_at=util.timestamp(); g.territory=nil; g.teleport_point=nil; g.warehouse_point=nil; r13_guild_save_one(g)
            local pm=guild_player_map(); pm.players=pm.players or {}; pm.history=pm.history or {}; for _,m in ipairs(g.members or {}) do pm.players[tostring(m.uuid)]=nil; pm.history[tostring(m.uuid)]={had_guild=true,last_guild_id=g.id,last_role=r13_guild_role(m.role),updated_at=util.timestamp(),dissolved=true} end; guild_save(GUILD_PLAYER_FILE,pm)
        end
        send(name,"§f投票结束："..(v.status=="passed" and "§a通过" or "§c未通过"))
    else guild_save(GUILD_VOTE_FILE,db); send(name,"§a已记录投票。当前：支持"..yes.." / 反对"..no) end
    return true
end

function guild_dissolve(name)
    local g=guild_find_player(name); if not g then send(name,"§c公会不存在。"); return true end
    if is_admin(name) then
        g.status="dissolved"; g.dissolved_at=util.timestamp(); g.territory=nil; g.teleport_point=nil; g.warehouse_point=nil; r13_guild_save_one(g); guild_log(g.id,"管理员强制解散",name,""); send(name,"§a已强制解散公会并解除领地保护。"); return true
    end
    if guild_member_role(g,name)~="owner" then send(name,"§c只有会长可以发起解散。"); return true end
    return guild_vote_start(name,"解散公会「"..g.name.."」","dissolve")
end

-- -----------------------------------------------------------------
-- 13) 公会菜单路由，防止和主菜单串状态
-- -----------------------------------------------------------------
local _r13_prev_guild_handle = guild_handle_menu
function guild_handle_menu(name,msg)
    local d,r=player_record(name,true); local mode=tostring(r and r.menu or ""); local raw=trim(tostring(msg or ""))
    if raw==".stop" or raw=="退出" or lower(raw)=="stop" then clear_menu(d,r); save_data(d); send(name,"§e已退出公会菜单。"); return true end

    if mode=="guild_first" or mode=="guild_return_main" then
        local n=tonumber(raw)
        if n==1 then return guild_creation_start(name)
        elseif n==2 then return guild_list(name)
        elseif n==3 then set_menu(d,r,"guild_search_name"); send(name,"§e请输入公会名称关键词："); return true
        elseif n==4 then set_menu(d,r,"guild_search_player"); send(name,"§e请输入玩家名称关键词："); return true
        elseif n==5 then set_menu(d,r,"guild_invite_accept"); send(name,"§e请输入邀请码："); return true
        elseif n==6 then return guild_my_applications(name)
        elseif n==7 then return guild_rankings(name,"level")
        elseif n==8 then return guild_rankings(name,"activity")
        elseif n==9 then return guild_rankings(name,"funds")
        elseif n==10 then send(name,R13_GAMEPLAY[15][2]); return true end
        send(name,"§c请输入1~10。"); return true
    end

    if mode=="guild_create_name" then
        if #raw<2 or #raw>16 then send(name,"§c公会名称需要2~16字符。"); return true end
        local gd=guild_load(GUILD_FILE,{items={}}); for _,g in pairs(gd.items or {}) do if g.status~="dissolved" and lower(tostring(g.name))==lower(raw) then send(name,"§c公会名称已存在。"); return true end end
        r.guild_create.name=raw; set_menu(d,r,"guild_create_startup"); save_data(d); send(name,"§d✦ 创建公会 · 2/4 ✦\n§f输入启动资金；输入§e0§f表示不额外投入。\n§7创建费3000金币不计入启动资金。"); return true
    end
    if mode=="guild_create_startup" then
        local n=tonumber(raw); if not n or n<0 or n%1~=0 then send(name,"§c请输入0或正整数。"); return true end
        r.guild_create.startup=math.floor(n); set_menu(d,r,"guild_create_theme"); save_data(d); send(name,"§d✦ 创建公会 · 3/4 ✦\n§f1 冰霜  2 梦幻  3 黄金  4 暗影\n§f5 自然  6 烈焰  7 深海  8 圣洁"); return true
    end
    if mode=="guild_create_theme" then
        local map={[1]="冰霜",[2]="梦幻",[3]="黄金",[4]="暗影",[5]="自然",[6]="烈焰",[7]="深海",[8]="圣洁"}; local theme=map[tonumber(raw)]
        if not theme then send(name,"§c请输入1~8。"); return true end
        r.guild_create.theme=theme; set_menu(d,r,"guild_create_start_confirm"); save_data(d); send(name,"§d✦ 创建公会 · 4/4 ✦\n§f请先站到公会领地的§e起始坐标§f。\n§a1 确定  §c0 取消\n§7不会把坐标发到聊天框。"); return true
    end
    if mode=="guild_create_start_confirm" then
        if raw=="0" then return guild_create_abort(name,"§e已取消公会创建。") end
        if raw~="1" then send(name,"§c请输入1确定或0取消。"); return true end
        local p=player_position(name,false); if not p then send(name,"§c无法读取当前位置。"); return true end
        r.guild_create.start_point={x=math.floor(p.x),y=math.floor(p.y),z=math.floor(p.z),dimension=p.dimension}; r.guild_create.end_deadline=util.timestamp()+180; set_menu(d,r,"guild_create_end_confirm"); save_data(d)
        send(name,"§a起始坐标已记录。\n§e请在3分钟内走到终止坐标。\n§a1 确定终止坐标  §e0 续3分钟  §f.stop 取消"); return true
    end
    if mode=="guild_create_end_confirm" then
        local s=r.guild_create
        if raw=="0" then s.end_deadline=util.timestamp()+180; save_data(d); send(name,"§e已续3分钟。"); return true end
        if raw~="1" then send(name,"§c输入1确认终止坐标，0续时间。"); return true end
        if util.timestamp()>tonumber(s.end_deadline or 0) then send(name,"§c已经超时；输入0续3分钟或.stop取消。"); return true end
        local p=player_position(name,false); if not p then send(name,"§c无法读取当前位置。"); return true end
        local a=s.start_point; if dim_exec(a.dimension)~=dim_exec(p.dimension) then send(name,"§c起始坐标与终止坐标必须在同一维度。"); return true end
        local candidate={x1=math.floor(a.x),z1=math.floor(a.z),x2=math.floor(p.x),z2=math.floor(p.z),dimension=a.dimension}
        local w=math.abs(candidate.x2-candidate.x1)+1; local l=math.abs(candidate.z2-candidate.z1)+1
        if w>128 or l>128 then send(name,"§c公会领地最大128×128；当前"..w.."×"..l.."。"); return true end
        local hit,who=guild_overlap_with_existing(candidate,nil); if hit then send(name,"§c领地创建失败：与"..tostring(who).."重叠。"); return true end
        s.territory=candidate; save_data(d); return guild_create_finish(name)
    end

    if mode=="guild_main" then
        local n=tonumber(raw); local g=guild_find_player(name)
        if n==1 then return guild_public_detail(name,g.id)
        elseif n==2 then local lines={"§b✦ 公会成员 ✦"}; for i,m in ipairs(g.members or {}) do lines[#lines+1]=string.format("§f%02d §8│ §e%s §7[%s] §8│ 贡献%s",i,tostring(m.name),r13_guild_role(m.role),tostring(m.contribution or 0)) end; send(name,table.concat(lines,"\n")); return true
        elseif n==3 then return guild_signin(name)
        elseif n==4 then return guild_task_menu(name)
        elseif n==5 then return guild_rankings(name,"level")
        elseif n==6 then send(name,"§d✦ 公会成就 ✦\n§7初建、成员、签到、在线、资金、等级、外交等长期成就会持续累计。"); return true
        elseif n==7 then return guild_announcement(name)
        elseif n==8 then send(name,"§b✦ 公会领地 ✦\n§f范围上限：§e128×128\n§7坐标对普通玩家隐藏；与普通领地/其他公会领地不能重叠。"); return true
        elseif n==9 then send(name,"§b✦ 公会设施 ✦\n§f.传送公会 / .传送工会\n§f.传送公会仓库 / .传送工会仓库\n§7传送点与仓库点必须在本公会领地内部。"); return true
        elseif n==10 then return guild_diplomacy_menu(name)
        elseif n==11 then return guild_development_menu(name)
        elseif n==12 then return guild_manage(name)
        elseif n==13 then return guild_generate_invite(name)
        elseif n==14 then return guild_rankings(name,"activity")
        elseif n==15 then return guild_weekly_report(name)
        elseif n==16 then return guild_try_upgrade(name) end
        send(name,"§c请输入1~16。"); return true
    end

    if mode=="guild_manage" then
        local n=tonumber(raw)
        if n==1 then return guild_facility_set(name,"tp")
        elseif n==2 then return guild_facility_set(name,"warehouse")
        elseif n==3 then set_menu(d,r,"guild_notice_input"); send(name,"§e请输入公告内容："); return true
        elseif n==4 then return guild_relocate_start(name)
        elseif n==5 then return guild_delete_territory(name,false)
        elseif n==6 then return guild_dissolve(name)
        elseif n==7 then return guild_diplomacy_menu(name)
        elseif n==8 then local g=guild_find_player(name); return guild_vote_start(name,"重大事项表决","general")
        elseif n==9 then return guild_generate_invite(name)
        elseif n==10 then local g=guild_find_player(name); return guild_set_public(name,g.public==false)
        elseif n==11 then return guild_pending_applications(name)
        elseif n==12 then return guild_development_menu(name)
        elseif n==13 and is_admin(name) then return guild_admin_menu(name) end
        send(name,"§c请输入有效编号。"); return true
    end

    if mode=="guild_notice_input" then clear_menu(d,r); return guild_post_notice(name,raw) end
    if mode=="guild_invite_accept" then clear_menu(d,r); return guild_accept_invite(name,raw) end
    if mode=="guild_list" then local n=tonumber(raw); local g=n and r.guild_list and r.guild_list[n]; if g then return guild_public_detail(name,g.id) end; send(name,"§c请输入列表编号。"); return true end
    if mode=="guild_search_name" then
        local gd=guild_load(GUILD_FILE,{items={}}); local q=lower(raw); local arr={}; for _,g in pairs(gd.items or {}) do if g.status~="dissolved" and lower(tostring(g.name)):find(q,1,true) then arr[#arr+1]=g end end; table.sort(arr,function(a,b) return tostring(a.name)<tostring(b.name) end)
        local lines={"§b✦ 公会搜索 ✦"}; for i=1,math.min(20,#arr) do lines[#lines+1]=string.format("§f%02d §8│ §e%s §7Lv.%s §8│ §b%s/%s",i,arr[i].name,arr[i].level,guild_online_count(arr[i]),#(arr[i].members or {})) end; if #arr==0 then lines[#lines+1]="§7没有找到匹配公会。" end; r.guild_search_guilds=arr; set_menu(d,r,"guild_search_guild_results"); send(name,table.concat(lines,"\n")); return true
    end
    if mode=="guild_search_guild_results" then local n=tonumber(raw); local g=n and r.guild_search_guilds and r.guild_search_guilds[n]; if g then return guild_public_detail(name,g.id) end; send(name,"§c请输入搜索结果编号。"); return true end
    if mode=="guild_search_player" then return guild_search_player(name,raw) end
    if mode=="guild_search_player_results" then local n=tonumber(raw); local v=n and r.guild_search_players and r.guild_search_players[n]; if v then return guild_public_detail(name,v.gid) end; send(name,"§c请输入搜索结果编号。"); return true end
    if mode=="guild_task_claim" then return guild_task_claim(name,raw) end
    if mode=="guild_public_detail" then if raw=="0" then clear_menu(d,r); return guild_commands_menu(name) end; if raw=="1" then local gid=r.guild_detail_id; clear_menu(d,r); return guild_apply_join(name,gid) end; send(name,"§c输入1申请加入，0返回。"); return true end

    if type(_r13_prev_guild_handle)=="function" then return _r13_prev_guild_handle(name,msg) end
    return false
end

