local _r13_prev_trigger_words = show_trigger_words
function show_trigger_words(name,page)
    local all={
        ".help",".stop / 退出",".触发词","AI 内容 / ai 内容","指令 内容",
        ".保存 / .保",".回 / .home / .传",".删除 / .删",".死亡日志",".死亡点返回 [序号]",
        ".签到",".背包",".金币排行",".玩家市场 / .市场",".领地 / .领地保护",".命令容器",
        ".公会 / .工会",".传送公会 / .传送工会",".传送公会仓库 / .传送工会仓库",".公会签到",".公会公告",".公会邀请码",".公会排行",".公会外交",
        ".群号 数字（管理员）",".公告栏刷新（管理员）",".备份（管理员）"
    }
    local per=12; local maxp=math.max(1,math.ceil(#all/per)); page=math.max(1,math.min(tonumber(page) or 1,maxp)); local first=(page-1)*per+1; local last=math.min(#all,first+per-1)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§b✦ 触 发 词 ✦ §7"..page.."/"..maxp,"§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}; for i=first,last do lines[#lines+1]="§f"..all[i] end; lines[#lines+1]="§7+ 下一页   - 上一页   .stop 退出"
    local d,r=player_record(name,true); r.trigger_page=page; set_menu(d,r,"trigger_words"); send(name,table.concat(lines,"\n")); return true
end

