QQ_BRIDGE_FILE = game.dataDir().."/qq_bridge.json"
function qq_bridge_load()
    local ok,d=pcall(util.json_load,QQ_BRIDGE_FILE); if not ok or type(d)~="table" then d={} end
    d.group_id=d.group_id or R13_DEFAULT_GROUP; d.enabled=(d.enabled==true); d.app_id=d.app_id or ""; d.app_secret=d.app_secret or ""; d.bridge_url=d.bridge_url or ""; return d
end
function qq_bridge_status(name)
    local d=qq_bridge_load(); local secret=(trim(tostring(d.app_secret))~="") and "已配置" or "未配置"
    send(name,"§b✦ QQ群服互通 ✦\n§f群号：§e"..tostring(d.group_id).."\n§f状态："..(d.enabled and "§a启用" or "§7未启用").."\n§fAppID："..(trim(tostring(d.app_id))~="" and "§a已配置" or "§7未配置").."\n§fAppSecret：§7"..secret.."\n§7凭证只从数据文件读取，不在聊天框显示。")
    return true
end

-- -----------------------------------------------------------------
-- 17) 最终聊天路由：优先拦截新系统，避免子菜单串到旧主菜单
-- -----------------------------------------------------------------
local _r13_prev_on_chat = on_chat
function on_chat(playerName,msg)
    local raw=trim(tostring(msg or "")); local low=lower(raw); local d,r=player_record(playerName,true)

    -- help 必须先于旧 handle_menu，避免旧 1~15 逻辑吃掉 16
    if low==".help" or low=="help" then return show_help(playerName) end
    local hn=raw:match("^%.help%s+(%d+)%s*$"); if hn then return r13_help_open(playerName,tonumber(hn)) end
    if r and r.menu=="help" then if raw==".stop" or raw=="退出" then clear_menu(d,r); save_data(d); send(playerName,"§e已退出主菜单。"); return true end; local n=tonumber(raw); if n and n>=1 and n<=16 then return r13_help_open(playerName,n) end; send(playerName,"§c请输入1~16。"); return true end
    if r and r.menu=="gameplay_index" then if raw==".stop" or raw=="退出" then clear_menu(d,r); return true end; local n=tonumber(raw); if n and n>=1 and n<=16 then return show_gameplay_category(playerName,n) end; send(playerName,"§c请输入1~16。"); return true end

    -- 公会直接入口/别名
    if low==".公会" or low=="公会" or low==".工会" or low=="工会" then return guild_commands_menu(playerName) end
    if low==".传送公会" or low=="传送公会" or low==".传送工会" or low=="传送工会" then return guild_teleport(playerName,"tp") end
    if low==".传送公会仓库" or low=="传送公会仓库" or low==".传送工会仓库" or low=="传送工会仓库" then return guild_teleport(playerName,"warehouse") end
    if low==".公会签到" or low==".工会签到" then return guild_signin(playerName) end
    if low==".公会公告" or low==".工会公告" then return guild_announcement(playerName) end
    if low==".公会邀请码" or low==".工会邀请码" then return guild_generate_invite(playerName) end
    if low==".公会排行" or low==".工会排行" then return r13_guild_rank_menu(playerName) end
    if low==".公会周报" or low==".工会周报" then return guild_weekly_report(playerName) end
    if low==".公会升级" or low==".工会升级" then return guild_try_upgrade(playerName) end
    local notice=raw:match("^%.公会公告%s+(.+)$") or raw:match("^%.工会公告%s+(.+)$"); if notice then return guild_post_notice(playerName,notice) end
    local searchp=raw:match("^%.公会搜索玩家%s+(.+)$") or raw:match("^%.工会搜索玩家%s+(.+)$"); if searchp then return guild_search_player(playerName,searchp) end
    local vote=raw:match("^%.公会投票%s+([01])$") or raw:match("^%.工会投票%s+([01])$"); if vote then return guild_vote_cast(playerName,vote) end

    -- 排行/公告/命令容器
    if low==".金币排行" or low==".金币排行榜" then return coin_leaderboard(playerName,10) end
    if low==".公告栏刷新" then if not is_admin(playerName) then send(playerName,"§c只有管理员可以刷新公告栏。"); return true end; patch_sidebar_update(true); send(playerName,"§a公告栏已刷新。"); return true end
    local grp=raw:match("^%.群号%s+(%d+)$"); if grp then return patch_server_number_set(playerName,grp) end
    if low==".qq群服" or low==".qq群" then return qq_bridge_status(playerName) end
    if low==".命令容器" or low==".命令方块容器" then return cmd_container_show(playerName) end
    local cf=raw:match("^%.命令容器导入%s+(.+)$") or raw:match("^%.命令方块容器导入%s+(.+)$"); if cf then return cmd_container_import(playerName,cf) end
    local cid,sw=raw:match("^%.命令容器%s+(%d+)%s+(开|关)$"); if cid then return cmd_container_toggle(playerName,tonumber(cid),sw=="开") end

    -- 子菜单必须优先在自己的命名空间处理
    if r and tostring(r.menu or ""):find("^guild_") then local ok=guild_handle_menu(playerName,raw); if ok then return true end end
    if r and r.menu=="guild_rank_menu" then local n=tonumber(raw); if n==1 then return guild_rankings(playerName,"level") elseif n==2 then return guild_rankings(playerName,"activity") elseif n==3 then return guild_rankings(playerName,"funds") elseif n==4 then return guild_rankings(playerName,"contribution") end; send(playerName,"§c请输入1~4。"); return true end
    if r and r.menu=="cmd_container_main" then
        if raw==".stop" then clear_menu(d,r); return true end
        local n=tonumber(raw); if n==1 then set_menu(d,r,"cmd_container_import"); send(playerName,"§e请输入TXT文件名："); return true elseif n==2 then return cmd_container_show(playerName) elseif n==3 then set_menu(d,r,"cmd_container_toggle"); send(playerName,"§e请输入：编号 开  或  编号 关"); return true end; send(playerName,"§c请输入1~3。"); return true
    end
    if r and r.menu=="cmd_container_import" then if raw==".stop" then clear_menu(d,r); return true end; return cmd_container_import(playerName,raw) end
    if r and r.menu=="cmd_container_toggle" then if raw==".stop" then clear_menu(d,r); return true end; local id,v=raw:match("^(%d+)%s+(开|关)$"); if id then return cmd_container_toggle(playerName,tonumber(id),v=="开") end; send(playerName,"§c格式：编号 开 / 编号 关"); return true end

    return _r13_prev_on_chat(playerName,msg)
end

-- -----------------------------------------------------------------
-- 18) 周期任务：公会保护2秒；活跃60秒；公告60秒；命令容器5秒
-- -----------------------------------------------------------------
R13_LAST_GUILD_PROTECT=tonumber(R13_LAST_GUILD_PROTECT) or 0
R13_LAST_GUILD_ACTIVITY=tonumber(R13_LAST_GUILD_ACTIVITY) or 0
R13_LAST_CMD=tonumber(R13_LAST_CMD) or 0
local _r13_prev_v17 = v17_event_tick
function v17_event_tick()
    local ret=true
    if type(_r13_prev_v17)=="function" then local ok,v=pcall(_r13_prev_v17); if ok then ret=v end end
    local now=util.timestamp()
    if now-R13_LAST_GUILD_PROTECT>=2 then R13_LAST_GUILD_PROTECT=now; pcall(guild_protect_tick) end
    if now-R13_LAST_GUILD_ACTIVITY>=60 then R13_LAST_GUILD_ACTIVITY=now; pcall(guild_activity_tick) end
    if now-(tonumber(PATCH_SIDEBAR_LAST) or 0)>=60 then pcall(patch_sidebar_update,false) end
    if now-R13_LAST_CMD>=5 then R13_LAST_CMD=now; pcall(cmd_container_tick) end
    return ret
end

-- -----------------------------------------------------------------
-- 19) 初始化：只迁移当前数据，不删除旧数据；写入版本标记
-- -----------------------------------------------------------------
local _r13_prev_init = on_init
function on_init()
    local ret=nil
    if type(_r13_prev_init)=="function" then local ok,v=pcall(_r13_prev_init); if ok then ret=v end end
    pcall(ensure_patch_prompt_files); pcall(guild_init_files)
    local cfg=r13_notice_load(); pcall(util.json_write,R13_NOTICE_FILE,cfg)
    pcall(patch_sidebar_update,true)
    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    return ret
end

-- ============================================================
-- R13B：成员管理、资金、普通领地互斥、发展路线与细节修正
-- ============================================================
FINAL_PATCH_TAG = "公会完整系统_主体恢复修复版_R13B"

function guild_create_abort(name,msg)
    local d,r=player_record(name,true); r.guild_create=nil; r.guild_relocate=nil; clear_menu(d,r); save_data(d); if msg and msg~="" then send(name,msg) end; return true
end

function guild_find_player(name)
    local map=guild_player_map(); local u=uuid_key(name); local gid=map.players and map.players[u]
    local gd=guild_load(GUILD_FILE,{items={}})
    if gid then local g=gd.items and gd.items[tostring(gid)]; if g and g.status~="dissolved" then return g end end
    for _,g in pairs(gd.items or {}) do
        if g.status~="dissolved" then
            for _,m in ipairs(g.members or {}) do
                if tostring(m.uuid or "")==tostring(u) or lower(tostring(m.name or ""))==lower(tostring(name)) then return g end
            end
        end
    end
    return nil
end

function guild_member_role(g,name)
    local u=uuid_key(name); local lname=lower(tostring(name))
    for _,m in ipairs((g and g.members) or {}) do
        if tostring(m.uuid or "")==tostring(u) or lower(tostring(m.name or ""))==lname then return r13_guild_role(m.role) end
    end
    return nil
end

function guild_online_count(g)
    local on=online_players() or {}; local set={}; for _,n in ipairs(on) do set[tostring(uuid_key(n))]=true; set[lower(tostring(n))]=true end
    local c=0; for _,m in ipairs((g and g.members) or {}) do if set[tostring(m.uuid or "")] or set[lower(tostring(m.name or ""))] then c=c+1 end end; return c
end

function r13_remove_guild_mapping(name,uuid,gid,role)
    local d=guild_player_map(); d.players=d.players or {}; d.history=d.history or {}; local u=tostring(uuid or uuid_key(name)); d.players[u]=nil; d.history[u]={had_guild=true,last_guild_id=gid,last_role=r13_guild_role(role),updated_at=util.timestamp()}; guild_save(GUILD_PLAYER_FILE,d)
end

function guild_leave(name)
    local g=guild_find_player(name); if not g then send(name,"§c你当前没有公会。"); return true end
    local role=guild_member_role(g,name); if role=="owner" then send(name,"§c会长不能直接退出。请先转让会长或解散公会。"); return true end
    local u=uuid_key(name); local keep={}; local removed=nil
    for _,m in ipairs(g.members or {}) do if tostring(m.uuid)==tostring(u) or lower(tostring(m.name))==lower(name) then removed=m else keep[#keep+1]=m end end
    if not removed then send(name,"§c成员数据不一致，未执行退出。"); return true end
    g.members=keep; r13_guild_save_one(g); r13_remove_guild_mapping(name,u,g.id,role); guild_log(g.id,"成员退出",name,""); send(name,"§e你已退出公会「"..g.name.."」。"); return true
end

function guild_find_member(g,text)
    local q=lower(trim(tostring(text or ""))); if q=="" then return nil end
    local exact=nil; local hits={}
    for _,m in ipairs(g.members or {}) do local n=lower(tostring(m.name or "")); if n==q then exact=m end; if n:find(q,1,true) then hits[#hits+1]=m end end
    if exact then return exact end; if #hits==1 then return hits[1] end; return nil
end

function guild_kick_member(actor,target)
    local g=guild_find_player(actor); if not g then return true end
    local ar=guild_member_role(g,actor); if ar~="owner" and ar~="deputy" and not is_admin(actor) then send(actor,"§c没有成员管理权限。"); return true end
    local m=guild_find_member(g,target); if not m then send(actor,"§c没有找到唯一匹配成员。"); return true end
    local tr=r13_guild_role(m.role); if tr=="owner" then send(actor,"§c不能踢出会长。"); return true end
    if ar=="deputy" and tr=="deputy" and not is_admin(actor) then send(actor,"§c副会长不能踢出另一位副会长。"); return true end
    local keep={}; for _,x in ipairs(g.members or {}) do if x~=m then keep[#keep+1]=x end end; g.members=keep; r13_guild_save_one(g); r13_remove_guild_mapping(m.name,m.uuid,g.id,m.role); guild_log(g.id,"踢出成员",actor,m.name); send(actor,"§a已将 §e"..m.name.." §a移出公会。"); pcall(game.sendTargeted,m.name,"§c你已被移出公会「"..g.name.."」。"); return true
end

function guild_set_deputy(actor,target,enabled)
    local g=guild_find_player(actor); if not g then return true end
    if guild_member_role(g,actor)~="owner" and not is_admin(actor) then send(actor,"§c只有会长或管理员可以任免副会长。"); return true end
    local m=guild_find_member(g,target); if not m then send(actor,"§c没有找到唯一匹配成员。"); return true end
    if r13_guild_role(m.role)=="owner" then send(actor,"§c会长身份不能改为副会长。"); return true end
    m.role=enabled and "deputy" or "member"; r13_guild_save_one(g); guild_log(g.id,enabled and "任命副会长" or "取消副会长",actor,m.name); send(actor,enabled and ("§a已任命 §e"..m.name.." §a为副会长。") or ("§e已取消 "..m.name.." 的副会长身份。")); return true
end

function guild_transfer_owner(actor,target)
    local g=guild_find_player(actor); if not g then return true end
    if guild_member_role(g,actor)~="owner" and not is_admin(actor) then send(actor,"§c只有会长可以转让会长。"); return true end
    local m=guild_find_member(g,target); if not m then send(actor,"§c没有找到唯一匹配成员。"); return true end
    if lower(tostring(m.name))==lower(tostring(actor)) then send(actor,"§c不能转让给自己。"); return true end
    local au=uuid_key(actor)
    for _,x in ipairs(g.members or {}) do if tostring(x.uuid)==tostring(au) or lower(tostring(x.name))==lower(actor) then x.role="member" end end
    m.role="owner"; g.owner_uuid=m.uuid; g.owner_name=m.name; r13_guild_save_one(g); guild_log(g.id,"转让会长",actor,"新会长="..m.name); send(actor,"§a会长已转让给：§e"..m.name); pcall(game.sendTargeted,m.name,"§d✦ 你已成为公会「"..g.name.."」的新会长！"); return true
end

function guild_donate(name,amount)
    local g=guild_find_player(name); if not g then send(name,"§c你还没有加入公会。"); return true end
    amount=math.floor(tonumber(amount) or 0); if amount<=0 then send(name,"§c捐献金额必须是正整数。"); return true end
    local board=scoreboard_name(); if not board then send(name,"§c金币计分板不存在。"); return true end
    local ok,b=pcall(game.getScore,board,name); local bal=ok and tonumber(b) or 0; if bal<amount then send(name,"§c金币不足，当前："..bal); return true end
    local okc,res=pcall(game.isCmdSuccess,'scoreboard players remove "'..r13_safe_name(name)..'" '..board..' '..amount); if not okc or res~=true then send(name,"§c扣除金币失败，未捐献。"); return true end
    local contribution=math.max(1,math.floor(amount/100)); g.funds=(tonumber(g.funds) or 0)+amount; g.total_contribution=(tonumber(g.total_contribution) or 0)+contribution; for _,m in ipairs(g.members or {}) do if tostring(m.uuid)==tostring(uuid_key(name)) then m.contribution=(tonumber(m.contribution) or 0)+contribution end end; r13_guild_save_one(g); guild_log(g.id,"公会捐献",name,"金币+"..amount.."；贡献+"..contribution); send(name,"§a捐献成功：§6"..amount.."金币 §8│ §d贡献+"..contribution); return true
end

function guild_member_manage_menu(name)
    local g=guild_find_player(name); if not g then return true end; if not guild_is_manager(g,name) then send(name,"§c没有成员管理权限。"); return true end
    local d,r=player_record(name,true); set_menu(d,r,"guild_member_manage"); send(name,"§8§m━━━━━━━━━━━━━━━━━━━━━━━━\n§b✦ 成 员 管 理 ✦\n§8§m━━━━━━━━━━━━━━━━━━━━━━━━\n§f① 踢出成员\n§f② 任命副会长\n§f③ 取消副会长\n§f④ 转让会长\n§7选择后输入玩家名；.stop退出"); return true
end

function guild_development_menu(name)
    local g=guild_find_player(name); if not g then return true end
    local d,r=player_record(name,true); set_menu(d,r,"guild_development")
    local lv=tonumber(g.level) or 1; local cost=math.floor(guild_upgrade_cost(lv)*guild_route_bonus(g,"upgrade_cost"))
    send(name,table.concat({"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§6✦ 公 会 发 展 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§f路线：§e"..tostring(g.development or "城建").."  §8│ §f资金：§6"..tostring(g.funds or 0),"§f升级：§b经验"..tostring(g.exp or 0).."/"..guild_exp_need(lv).." §8│ §6资金"..cost,"§f① 城建   ② 商业   ③ 冒险   ④ 荣耀","§f⑤ 公会升级","§f⑥ 公会捐献","§f⑦ 更换主题颜色","§7城建：升级资金成本-10%  §8│ §7商业：任务资金+20%","§7冒险：任务经验+20%      §8│ §7荣耀：活跃排行+10%","§7.stop 退出"},"\n")); return true
end

function guild_set_development(name,choice)
    local g=guild_find_player(name); if not g then return true end
    if not guild_is_manager(g,name) then send(name,"§c只有会长/副会长可以调整发展路线。"); return true end
    local map={[1]="城建",[2]="商业",[3]="冒险",[4]="荣耀"}; local route=map[tonumber(choice)]; if not route then send(name,"§c请输入1~4。"); return true end
    if tostring(g.development)==route then send(name,"§7当前已经是「"..route.."」路线。"); return true end
    local cost=500; if (tonumber(g.funds) or 0)<cost then send(name,"§c切换发展路线需要500公会资金。"); return true end
    g.funds=g.funds-cost; g.development=route; r13_guild_save_one(g); guild_log(g.id,"切换发展路线",name,route.."；资金-500"); send(name,"§a发展路线已切换为：§e"..route.." §7（消耗500公会资金）"); return true
end

function guild_theme_menu(name)
    local g=guild_find_player(name); if not g then return true end; if not guild_is_manager(g,name) then send(name,"§c只有会长/副会长可以修改主题。"); return true end
    local d,r=player_record(name,true); set_menu(d,r,"guild_theme_pick"); send(name,"§d✦ 公会主题颜色 ✦\n§f1 冰霜  2 梦幻  3 黄金  4 暗影\n§f5 自然  6 烈焰  7 深海  8 圣洁\n§7主题只影响显示，不允许玩家直接注入§控制码。"); return true
end

function guild_set_theme(name,n)
    local g=guild_find_player(name); if not g then return true end; if not guild_is_manager(g,name) then return true end
    local map={[1]="冰霜",[2]="梦幻",[3]="黄金",[4]="暗影",[5]="自然",[6]="烈焰",[7]="深海",[8]="圣洁"}; local v=map[tonumber(n)]; if not v then send(name,"§c请输入1~8。"); return true end
    g.theme=v; r13_guild_save_one(g); guild_log(g.id,"修改公会主题",name,v); send(name,"§a公会主题已改为："..guild_theme(v)..v); return true
end

-- 普通领地创建时也必须检查公会领地；二者本质上都是保护区域
function territory_create_finish(name)
    local d,r=player_record(name,true); local s=r.territory_create; if not s then return true end
    local db=territory_db(); local isadm=is_admin(name); local max=isadm and 512 or 128; local w=math.abs(s.x2-s.x1)+1; local l=math.abs(s.z2-s.z1)+1
    if w>max or l>max then send(name,"§c创建失败：范围过大。最大 "..max.."×"..max.."，Y轴不限。"); r.territory_create=nil; clear_menu(d,r); return true end
    local uid=uuid_key(name); local count=0; for _,t in pairs(db.items or {}) do if t.owner_uuid==uid and not t.deleted then count=count+1 end end
    if not isadm and count>=1 then local extra=tonumber(r.territory_extra) or 0; if extra>0 then r.territory_extra=extra-1 else send(name,"§c普通玩家只能拥有1块领地。"); r.territory_create=nil; clear_menu(d,r); return true end end
    local pc,pv=password_ascii_digit_count(s.password); if pc~=6 or #pv~=6 then send(name,"§c创建失败：领地密码必须是6位数字。"); return true end; s.password=pv
    local c={x1=s.x1,z1=s.z1,x2=s.x2,z2=s.z2,dimension=s.dimension,owner_uuid=uid,owner=name,name=s.name,password=pv,password_digits=pv,public=false,created_at=util.timestamp(),deleted=false}
    for _,t in pairs(db.items or {}) do if not t.deleted and r13_rect_overlap(c,t) then send(name,"§c创建失败：该区域与已有普通领地重叠。"); r.territory_create=nil; clear_menu(d,r); return true elseif not t.deleted and territory_too_close(c,t,20) then send(name,"§c创建失败：领地之间至少需要间隔20米。"); r.territory_create=nil; clear_menu(d,r); return true end end
    local gd=guild_load(GUILD_FILE,{items={}}); for _,g in pairs(gd.items or {}) do if g.status~="dissolved" and type(g.territory)=="table" and r13_rect_overlap(c,g.territory) then send(name,"§c创建失败：该区域与公会「"..tostring(g.name).."」领地重叠。"); r.territory_create=nil; clear_menu(d,r); return true end end
    local id=tostring(db.next_id or 1); db.next_id=(tonumber(db.next_id) or 1)+1; c.id=id; db.items[id]=c; territory_save(db); territory_protection_log({at=util.timestamp(),type="领地创建",player=name,player_uuid=uid,territory_id=id,territory_name=s.name,dimension=s.dimension,x1=s.x1,z1=s.z1,x2=s.x2,z2=s.z2,public=false}); r.territory_create=nil; clear_menu(d,r); save_data(d); send(name,"§a领地创建成功！编号："..id.."\n§7已同时检查普通领地与公会领地冲突。"); return true
end

function cmd_container_toggle(name,id,on)
    if not is_admin(name) then send(name,"§c只有管理员可以启动/停止命令容器。"); return true end
    local d=cmd_container_db(); local b=d.items[tostring(id)]; if not b then send(name,"§c容器不存在。"); return true end
    b.enabled=on==true
    if b.enabled then for _,n in ipairs(b.nodes or {}) do n.fired=false; n.last_success=false end end
    cmd_container_save(d); send(name,"§a容器 #"..tostring(id).." 已"..(b.enabled and "启动" or "停止").."。"); return true
end

-- 管理员强制解散要彻底解除成员映射，但保留历史
function guild_admin_force_dissolve(name,gid)
    if not is_admin(name) then send(name,"§c仅管理员。"); return true end
    local gd=guild_load(GUILD_FILE,{items={}}); local g=gd.items and gd.items[tostring(gid)]; if not g then send(name,"§c公会不存在。"); return true end
    g.status="dissolved"; g.dissolved_at=util.timestamp(); g.territory=nil; g.teleport_point=nil; g.warehouse_point=nil; gd.items[g.id]=g; guild_save(GUILD_FILE,gd)
    local pm=guild_player_map(); pm.players=pm.players or {}; pm.history=pm.history or {}; for _,m in ipairs(g.members or {}) do pm.players[tostring(m.uuid)]=nil; pm.history[tostring(m.uuid)]={had_guild=true,last_guild_id=g.id,last_role=r13_guild_role(m.role),updated_at=util.timestamp(),dissolved=true} end; guild_save(GUILD_PLAYER_FILE,pm); guild_log(g.id,"管理员强制解散",name,""); send(name,"§a已强制解散「"..tostring(g.name).."」，领地、传送点、仓库点已失效，历史日志保留。"); return true
end

-- 公会管理菜单增加成员管理和资金入口
function guild_manage(name)
    local g=guild_find_player(name); if not g then return guild_commands_menu(name) end; if not guild_is_manager(g,name) then send(name,"§c普通成员没有公会管理权限。"); return true end
    local d,r=player_record(name,true); set_menu(d,r,"guild_manage")
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§6§l✦ 公 会 管 理 ✦","§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§f01 传送点    02 仓库点    03 发布公告","§f04 更换领地  05 删除领地  06 解散公会","§f07 外交关系  08 重大投票  09 邀请码","§f10 公开申请  11 申请审核  12 发展路线","§f13 成员管理  14 公会资金"}
    if is_admin(name) then lines[#lines+1]="§c15 管理员后台" end; lines[#lines+1]="§7.stop 退出"; send(name,table.concat(lines,"\n")); return true
end

local _r13b_prev_guild_handle=guild_handle_menu
function guild_handle_menu(name,msg)
    local d,r=player_record(name,true); local mode=tostring(r.menu or ""); local raw=trim(tostring(msg or ""))
    if mode=="guild_manage" then
        if raw==".stop" or raw=="退出" then clear_menu(d,r); return true end
        local n=tonumber(raw)
        if n==1 then return guild_facility_set(name,"tp") elseif n==2 then return guild_facility_set(name,"warehouse") elseif n==3 then set_menu(d,r,"guild_notice_input"); send(name,"§e请输入公告内容："); return true elseif n==4 then return guild_relocate_start(name) elseif n==5 then set_menu(d,r,"guild_delete_confirm"); send(name,"§c确认删除公会领地？\n§f1 确认删除   0 取消\n§7删除后恢复重新创建资格，旧传送点/仓库点同时失效。"); return true elseif n==6 then return guild_dissolve(name) elseif n==7 then return guild_diplomacy_menu(name) elseif n==8 then return guild_vote_start(name,"重大事项表决","general") elseif n==9 then return guild_generate_invite(name) elseif n==10 then local g=guild_find_player(name); return guild_set_public(name,g.public==false) elseif n==11 then return guild_pending_applications(name) elseif n==12 then return guild_development_menu(name) elseif n==13 then return guild_member_manage_menu(name) elseif n==14 then local g=guild_find_player(name); send(name,"§6✦ 公会资金 ✦\n§f当前：§e"..tostring(g.funds or 0).."\n§7所有成员可输入：.公会捐献 金额\n§7公会升级、路线切换等会真实消耗公会资金。"); return true elseif n==15 and is_admin(name) then return guild_admin_menu(name) end
        send(name,"§c请输入有效编号。"); return true
    end
    if mode=="guild_delete_confirm" then if raw=="1" then clear_menu(d,r); return guild_delete_territory(name,false) elseif raw=="0" then clear_menu(d,r); return guild_manage(name) end; send(name,"§c请输入1或0。"); return true end
    if mode=="guild_member_manage" then local n=tonumber(raw); if n and n>=1 and n<=4 then r.guild_member_action=n; set_menu(d,r,"guild_member_target"); send(name,"§e请输入目标玩家名称："); return true end; send(name,"§c请输入1~4。"); return true end
    if mode=="guild_member_target" then local a=tonumber(r.guild_member_action); local target=raw; clear_menu(d,r); if a==1 then return guild_kick_member(name,target) elseif a==2 then return guild_set_deputy(name,target,true) elseif a==3 then return guild_set_deputy(name,target,false) elseif a==4 then return guild_transfer_owner(name,target) end; return true end
    if mode=="guild_development" then
        local n=tonumber(raw); if n and n>=1 and n<=4 then return guild_set_development(name,n) elseif n==5 then clear_menu(d,r); return guild_try_upgrade(name) elseif n==6 then set_menu(d,r,"guild_donate_input"); send(name,"§e请输入要捐献的金币数量："); return true elseif n==7 then return guild_theme_menu(name) end; send(name,"§c请输入1~7。"); return true
    end
    if mode=="guild_donate_input" then clear_menu(d,r); return guild_donate(name,raw) end
    if mode=="guild_theme_pick" then clear_menu(d,r); return guild_set_theme(name,raw) end
    return _r13b_prev_guild_handle(name,msg)
end

local _r13b_prev_on_chat=on_chat
function on_chat(playerName,msg)
    local raw=trim(tostring(msg or "")); local low=lower(raw)
    if low==".退出公会" or low==".离开公会" or low==".退出工会" then return guild_leave(playerName) end
    local don=raw:match("^%.公会捐献%s+(%d+)$") or raw:match("^%.工会捐献%s+(%d+)$"); if don then return guild_donate(playerName,tonumber(don)) end
    local kick=raw:match("^%.公会踢出%s+(.+)$"); if kick then return guild_kick_member(playerName,kick) end
    local dep=raw:match("^%.公会副会长%s+(.+)$"); if dep then return guild_set_deputy(playerName,dep,true) end
    local undep=raw:match("^%.公会取消副会长%s+(.+)$"); if undep then return guild_set_deputy(playerName,undep,false) end
    local trans=raw:match("^%.公会转让%s+(.+)$"); if trans then return guild_transfer_owner(playerName,trans) end
    return _r13b_prev_on_chat(playerName,msg)
end

local _r13b_prev_init=on_init
function on_init()
    local ret=nil; if type(_r13b_prev_init)=="function" then local ok,v=pcall(_r13b_prev_init); if ok then ret=v end end
    pcall(guild_init_files); pcall(ensure_patch_prompt_files); pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n"); return ret
end

