FINAL_PATCH_VERSION = "1.0.65-R13C"
FINAL_PATCH_TAG = "完整修复_公会系统_预部署版"

-- 主菜单：保留原功能顺序，四列×四行，并分两段发送避免聊天框吞行。
function show_help(name)
    local d,r=player_record(name,true); set_menu(d,r,"help"); r.menu_expires=util.timestamp()+MENU_TIMEOUT; save_data(d)
    send(name,table.concat({
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
        "§b§l          ✦ 多 功 能 主 菜 单 ✦",
        "§8§m━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
        "§b01§r 保存传送点 §8│ §b02§r 返回传送点 §8│ §b03§r 返回死亡点 §8│ §b04§r 删除存档点",
        "§b05§r 玩家互传   §8│ §b06§r 玩家转账   §8│ §b07§r 反馈审核   §8│ §b08§r 坐标传送",
    },"\n"))
    send(name,table.concat({
