-- 公会排行菜单专门处理，必须在通用 guild_* 菜单前拦截，防止串到旧公会菜单。
function r13c_handle_rank_menu(name,raw)
    local d,r=player_record(name,true)
    if not r or r.menu~="guild_rank_menu" then return false end
    raw=trim(tostring(raw or ""))
    if raw==".stop" or raw=="退出" then clear_menu(d,r); save_data(d); send(name,"§e已退出公会排行。") return true end
    local n=tonumber(raw)
    if n==1 then return guild_rankings(name,"level")
    elseif n==2 then return guild_rankings(name,"activity")
    elseif n==3 then return guild_rankings(name,"funds")
    elseif n==4 then return guild_rankings(name,"contribution") end
    send(name,"§c请输入1~4。"); return true
end

