-- `.备份` 自快照也覆盖新公会文件；只复制当前插件真实文件，不读取云端旧备份。
function self_backup_now(name)
    if not is_admin(name) then send(name,"§c只有管理员可以创建插件快照。") return true end
    local stamp=os.date("!%Y%m%d_%H%M%S",util.timestamp()+8*3600)
    local dd=game.dataDir(); local code=plugin_code_dir(); local base=plugin_base_dir(); local prefix=dd.."/self_backup_"..stamp.."_"
    local files={
        {src=code.."/main.lua",dst=prefix.."main.lua"},{src=code.."/manifest.json",dst=prefix.."manifest.json"},{src=code.."/docs.md",dst=prefix.."docs.md"},
        {src=code.."/seg_core.txt",dst=prefix.."seg_core.txt"},{src=code.."/seg_cmd.txt",dst=prefix.."seg_cmd.txt"},{src=code.."/seg_build.txt",dst=prefix.."seg_build.txt"},{src=code.."/seg_mcp.txt",dst=prefix.."seg_mcp.txt"},{src=code.."/seg_review.txt",dst=prefix.."seg_review.txt"},
        {src=base.."/插件配置文件/ds_ai_agent/ds_ai_agent.json",dst=prefix.."config.json"},
    }
    local data_files={
        "ds_data.json","chat_logs.json","market.json","market_items_nbt.json","market_item_previews.json","market_storage.json","market_wallet.json","market_offline_notices.json",
        "nbt_regions.json","territories.json","purchase_logs.json","shop_logs.json","teleport_logs.json","territory_protection_logs.json","server_announcement.json","server_announcement_lines.json",
        "command_containers.json","qq_bridge.json","ai_global_rules.json","ai_last_trace.json","ai_personas.json","agent_providers.json","inv_request.json","death_lastpos.json","death_dedup.json","death_samples.json",
        "guild/guilds.json","guild/players.json","guild/logs.json","guild/votes.json","guild/tasks.json","guild/diplomacy.json","guild/notices.json","guild/activity.json",
        "guild/applications.json","guild/achievements.json","guild/weekly.json","guild/VERSION.txt","command_txt/示例_循环链式.txt","command_txt/示例_命令容器.txt"
    }
    for _,f in ipairs(data_files) do files[#files+1]={src=dd.."/"..f,dst=prefix.."data_"..f:gsub("/","_")} end
    local okc=0
    for _,f in ipairs(files) do
        local ok,v=pcall(util.read_file,f.src)
        if ok and type(v)=="string" then local okw=pcall(util.write_file,f.dst,v); if okw then okc=okc+1 end end
    end
    local old=""; local oko,v=pcall(util.read_file,BACKUP_INDEX_FILE); if oko and type(v)=="string" then old=v end
    pcall(util.write_file,BACKUP_INDEX_FILE,old..stamp.." | "..okc.." files | version="..FINAL_PATCH_VERSION.."\n")
    send(name,"§a✦ 已创建本插件自己的回滚快照：§e"..stamp.."\n§7成功保存：§f"..okc.." §7个文件。\n§7后续回滚只使用本插件自己生成的快照。")
    return true
end

