-- 普通签到同样由 AI 在安全白名单中选每日奖励，并明确发给签到玩家本人。
function signin(name)
    local d,r=player_record(name,true)
    local db=coord_soul_state_db(); local p=coord_soul_state_player(db,name,r); p.signin=p.signin or {available=false}
    if not p.signin.available then send(name,"§e今天还不能签到。§7累计在线满120分钟后解锁；之后每现实24小时刷新一次。") return true end
    local idx=tonumber(choose_signin_reward and choose_signin_reward() or 1) or 1
    idx=math.max(1,math.min(#SIGNIN_REWARDS,idx)); local reward=SIGNIN_REWARDS[idx]
    local target='@a[name="'..r13_safe_name(name)..'"]'
    local cmd=tostring(reward.cmd or ""):gsub("@s",target,1)
    local ok,res=pcall(game.isCmdSuccess,cmd)
    if not ok or res~=true then send(name,"§c签到奖励发放失败，本次签到没有消耗，请稍后重试。") return true end
    p.signin.available=false; p.signin.last_claim_at=util.timestamp(); p.signin.next_at=util.timestamp()+DAILY_SIGNIN_INTERVAL
    coord_soul_state_save(db); r.signin=p.signin; pcall(save_data,d)
    send(name,"§6✦ 今日签到成功！\n§fAI今日奖励：§e"..tostring(reward.text).."\n§7"..tostring(reward.flavor or "").."\n§7下一次签到：现实24小时后。")
    return true
end

