end

-- ============================================================
-- 1.0.66 R14：FUNCTION TXT 原生命令链模拟系统
-- ============================================================
FINAL_PATCH_VERSION = "1.0.66-R14"
FINAL_PATCH_TAG = "FUNCTION命令链_完整管理版"

FUNCTION_DIR = game.dataDir().."/command_txt"
FUNCTION_REGISTRY_FILE = game.dataDir().."/function_registry.json"
FUNCTION_TIMER_FILE = game.dataDir().."/function_timer_ids.json"
FUNCTION_LOCK_FILE = game.dataDir().."/function_edit_locks.json"
FUNCTION_DEBUG_FILE = game.dataDir().."/function_debug.json"
FUNCTION_ENGINE_VERSION = "ROUND_FAST_V5_REAL_TXT_LOAD"
FUNCTION_MAX_FILES = 999
FUNCTION_MAX_VIEW = 60
FUNCTION_PAGE_SIZE = 20
FUNCTION_CHAT_CHUNK = 200
FUNCTION_MIN_DELAY = 0.001
FUNCTION_MAX_DELAY = 100000
FUNCTION_DEFAULT_DELAY = 0.05 -- 20Hz
FUNCTION_DEFAULT_STATE = {kind=1, conditional=0, redstone=0}

function function_copy_state(st)
    st=st or FUNCTION_DEFAULT_STATE
    local hz=tonumber(st.hz)
    if hz and (hz<=0 or hz>20) then hz=nil end
    return {kind=tonumber(st.kind) or 1,conditional=tonumber(st.conditional) or 0,redstone=tonumber(st.redstone) or 0,hz=hz}
end

function function_state_equal(a,b)
    return tonumber(a and a.kind)==tonumber(b and b.kind)
        and tonumber(a and a.conditional)==tonumber(b and b.conditional)
        and tonumber(a and a.redstone)==tonumber(b and b.redstone)
        and tonumber(a and a.hz)==tonumber(b and b.hz)
end

function function_state_text(st)
    st=st or FUNCTION_DEFAULT_STATE
    local k=tonumber(st.kind) or 1
    local kind=(k==0 and "连锁" or (k==2 and "循环" or "脉冲"))
    local cond=(tonumber(st.conditional)==1) and "有条件" or "无条件"
    local red=(tonumber(st.redstone)==1) and "红石激活" or "保持开启"
    return kind.."/"..cond.."/"..red
end

function function_safe_filename(name)
    name=trim(tostring(name or ""))
    name=name:match("([^/\\]+)$") or name
    if name=="" then return nil,"文件名不能为空" end
    if not lower(name):match("%.txt$") then name=name..".txt" end
    if name:find("..",1,true) or name:find("/") or name:find("\\") then return nil,"文件名不合法" end
    if #name>120 then return nil,"文件名过长" end
    return name
end

function function_file_path(name)
    local n,e=function_safe_filename(name)
    if not n then return nil,e end
    return FUNCTION_DIR.."/"..n,n
end

FUNCTION_BUNDLED_TXT = {
    ["雪球菜单_综合功能.txt"] = "snowball_menu_integrated.txt",
    ["FUNCTION_链级频率示例.txt"] = "function_rate_example.txt",
}

function function_read_text(name)
    local path,n=function_file_path(name)
    if not path then return nil,n end
    local ok,v=pcall(util.read_file,path)
    if ok and type(v)=="string" and trim(v)~="" then return v,path end
    local bundled=FUNCTION_BUNDLED_TXT[tostring(n or "")]
    if bundled then
        local cd=""; pcall(function() cd=tostring(plugin_code_dir() or "") end)
        if cd~="" then
            local rp=cd.."/command_txt/"..bundled
            local ok2,v2=pcall(util.read_file,rp)
            if ok2 and type(v2)=="string" and trim(v2)~="" then
                -- Best effort: materialize into real data command_txt. Even if the write is unavailable,
                -- the bundled bytes are still returned so registration/compile can load them.
                pcall(util.write_file,path,v2)
                return v2,rp
            end
        end
    end
    return nil,"读取不到TXT："..tostring(n)
end

function function_write_text(name,text)
    local path,n=function_file_path(name)
    if not path then return false,n end
    local ok,err=pcall(util.write_file,path,tostring(text or ""))
    if not ok then return false,"写入失败："..tostring(err) end
    return true,path
end

function function_shell_quote(s)
    s=tostring(s or "")
    s=s:gsub("\\","\\\\"):gsub('"','\\"'):gsub("%$","\\$"):gsub("`","\\`")
    return '"'..s..'"'
end

function function_registry_load()
    local ok,d=pcall(util.json_load,FUNCTION_REGISTRY_FILE)
    if not ok or type(d)~="table" then d={next_id=1,items={}} end
    d.items=d.items or {}; d.next_id=math.max(1,tonumber(d.next_id) or 1)
    for id,it in pairs(d.items) do
        if type(it)=="table" then
            it.id=tonumber(it.id) or tonumber(id)
            it.enabled=(it.enabled==true); it.loaded=(it.loaded~=false)
            it.delay_sec=math.max(FUNCTION_MIN_DELAY,math.min(FUNCTION_MAX_DELAY,tonumber(it.delay_sec) or FUNCTION_DEFAULT_DELAY))
            it.powered=(it.powered==true)
            it.missing=(it.missing==true); it.timer_registered=(it.timer_registered==true); it.needs_reload=(it.needs_reload==true)
        end
    end
    return d
end

function function_registry_save(d)
    return pcall(util.json_write,FUNCTION_REGISTRY_FILE,d or {next_id=1,items={}})
end

function function_registry_sorted(d,include_missing)
    d=d or function_registry_load(); local arr={}
    for id,it in pairs(d.items or {}) do
        if type(it)=="table" and (include_missing or not it.missing) then arr[#arr+1]={id=tonumber(id) or tonumber(it.id) or 0,item=it} end
    end
    table.sort(arr,function(a,b) return a.id<b.id end)
    return arr
end

function function_registry_get(id,d)
    d=d or function_registry_load(); return d.items[tostring(tonumber(id) or -1)],d
end

function function_scan_shell_names()
    local names={}; local seen={}; local available=false
    local okst,st=pcall(system.shizukuStatus)
    if not okst or type(st)~="table" or st.available~=true or st.granted~=true then
        return names,false
    end
    local cmd='for f in '..function_shell_quote(FUNCTION_DIR)..'/*.txt; do [ -f "$f" ] && basename "$f"; done'
    local ok,res=pcall(system.shell,cmd)
    if ok and type(res)=="table" and res.ok==true then
        available=true
        local src=tostring(res.stdout or "")
        local pos=1
        if src:sub(-1)~="\n" then src=src.."\n" end
        while pos<=#src do
            local nl=src:find("\n",pos,true); if not nl then break end
            local n=trim(src:sub(pos,nl-1)):gsub("\r$","")
            pos=nl+1
            if n~="" and lower(n):match("%.txt$") and not seen[n] then seen[n]=true; names[#names+1]=n end
        end
    end
    return names,available
end

function function_scan_files(silent)
    local d=function_registry_load(); local names,scanned=function_scan_shell_names(); local seen={}
    -- 没有Shizuku目录扫描时，至少保留已登记且真实可读的TXT。
    if not scanned then
        for _,x in ipairs(function_registry_sorted(d,true)) do
            local n=tostring(x.item.name or "")
            if n~="" then local v=function_read_text(n); if v then names[#names+1]=n end end
        end
        for _,n in ipairs({"示例_FUNCTION.txt","示例_命令容器.txt","示例_循环链式.txt"}) do
            local v=function_read_text(n); if v then names[#names+1]=n end
        end
    end
    -- R20H：包内 FUNCTION 资源始终参与扫描。即使 shell 只能看到数据目录，
    -- 内置 TXT 仍可通过 plugin_code_dir()/command_txt 真实读取，不会被误标为缺失。
    for n,_ in pairs(FUNCTION_BUNDLED_TXT or {}) do
        local v=function_read_text(n)
        if v then names[#names+1]=n end
    end
    table.sort(names)
    local byname={}
    for id,it in pairs(d.items) do if type(it)=="table" and tostring(it.name or "")~="" then byname[tostring(it.name)]=tostring(id) end end
    for _,name in ipairs(names) do
        if not seen[name] then
            seen[name]=true
            local id=byname[name]
            if not id then
                local nextid=d.next_id
                while d.items[tostring(nextid)] and nextid<=FUNCTION_MAX_FILES do nextid=nextid+1 end
                if nextid<=FUNCTION_MAX_FILES then
                    id=tostring(nextid); d.next_id=nextid+1
                    d.items[id]={id=nextid,name=name,enabled=false,loaded=true,delay_sec=FUNCTION_DEFAULT_DELAY,powered=false,missing=false,created_at=util.timestamp(),timer_registered=false,needs_reload=false}
                end
            else
                d.items[id].missing=false
            end
        end
    end
    for id,it in pairs(d.items) do if type(it)=="table" then it.missing=not seen[tostring(it.name or "")] end end
    function_registry_save(d)
    if not silent then
        local count=0; for _,x in ipairs(function_registry_sorted(d,false)) do count=count+1 end
        return true,"扫描完成，共找到 "..count.." 个 TXT"..(scanned and "。" or "；当前无目录扫描权限，只能识别已登记文件。")
    end
    return true,d,scanned
end

function function_register_filename(name)
    local n,e=function_safe_filename(name); if not n then return false,e end
    local txt=function_read_text(n); if not txt then return false,"找不到 "..n.."，请先放入 command_txt 目录。" end
    local d=function_registry_load()
    for id,it in pairs(d.items) do if tostring(it.name)==n then it.missing=false; function_registry_save(d); return true,tonumber(id) end end
    local id=d.next_id
    while d.items[tostring(id)] and id<=FUNCTION_MAX_FILES do id=id+1 end
    if id>FUNCTION_MAX_FILES then return false,"文件编号已达到上限" end
    d.next_id=id+1; d.items[tostring(id)]={id=id,name=n,enabled=false,loaded=true,delay_sec=FUNCTION_DEFAULT_DELAY,powered=false,missing=false,created_at=util.timestamp(),timer_registered=false,needs_reload=false}
    function_registry_save(d); return true,id
end

function function_parse_state_line(s,current)
    s=trim(tostring(s or ""))
    local a,b,c,rate=s:match("^([012])%s*,%s*([01])%s*,%s*([01])%s+(.+)$")
    if a then
        local hz=tonumber(trim(rate or ""))
        if not hz or hz<=0 or hz>20 then return current,false end
        local n=function_copy_state(current); n.kind=tonumber(a); n.conditional=tonumber(b); n.redstone=tonumber(c); n.hz=hz
        return n,true
    end
    a,b,c=s:match("^([012])%s*,%s*([01])%s*,%s*([01])$")
    if a then local n=function_copy_state(current); n.kind=tonumber(a); n.conditional=tonumber(b); n.redstone=tonumber(c); return n,true end
    a,b=s:match("^([012])%s*,%s*([01])$")
    if a then local n=function_copy_state(current); n.kind=tonumber(a); n.conditional=tonumber(b); return n,true end
    a=s:match("^([012])$")
    if a then local n=function_copy_state(current); n.kind=tonumber(a); return n,true end
    return current,false
end

function function_parse_document(text,opts)
    opts=opts or {}
    local nodes,errors,warnings={},{},{}
    local current=function_copy_state(opts.initial_state or FUNCTION_DEFAULT_STATE)
    local chain=1; local ended=false; local cmd_index=0; local physical=0; local after_end=false
    local src=tostring(text or ""):gsub("\r\n","\n"):gsub("\r","\n")
    if src:sub(-1)~="\n" then src=src.."\n" end
    local pos=1
    while pos<=#src do
        local nl=src:find("\n",pos,true); if not nl then break end
        local raw=src:sub(pos,nl-1); pos=nl+1; physical=physical+1
        local line=trim(raw)
        if line~="" and not line:match("^#") and not line:match("^%-%-") then
            if after_end then errors[#errors+1]="第"..physical.."行：! 后面不能再有内容"; break end
            if line=="!" then
                ended=true; after_end=true
            elseif line=="." then
                chain=chain+1; current=function_copy_state(FUNCTION_DEFAULT_STATE)
            else
                local state_line=line
                if state_line:sub(1,1)=="$" then state_line=trim(state_line:sub(2)) end
                local newst,isstate=function_parse_state_line(state_line,current)
                if isstate then
                    current=newst
                elseif state_line:match("^[012]%s*,") then
                    errors[#errors+1]="第"..physical.."行：状态/频率语法无效（频率必须 >0 且 <=20Hz）"
                else
                    local cmd=line
                    if cmd:sub(1,1)=="/" then cmd=trim(cmd:sub(2)) end
                    if cmd=="" then
                        errors[#errors+1]="第"..physical.."行：空指令"
                    else
                        cmd_index=cmd_index+1
                        nodes[#nodes+1]={index=cmd_index,chain_id=chain,state=function_copy_state(current),command="/"..cmd,physical_line=physical}
                    end
                end
            end
        end
    end
    if opts.require_end~=false and not ended then errors[#errors+1]="文件末尾缺少 !" end
    if #nodes==0 then warnings[#warnings+1]="没有有效指令" end
    return {nodes=nodes,errors=errors,warnings=warnings,ended=ended,commands=#nodes,chains=chain}
end

function function_serialize_nodes(nodes)
    local lines={}; local prev_chain=nil; local prev_state=nil
    for _,node in ipairs(nodes or {}) do
        if prev_chain~=nil and tostring(node.chain_id)~=tostring(prev_chain) then lines[#lines+1]="."; prev_state=nil end
        local st=node.state or FUNCTION_DEFAULT_STATE
        if not prev_state or not function_state_equal(st,prev_state) then
            if tonumber(st.hz) then
                lines[#lines+1]=string.format("%d,%d,%d %.8g",tonumber(st.kind) or 1,tonumber(st.conditional) or 0,tonumber(st.redstone) or 0,tonumber(st.hz))
            else
                lines[#lines+1]=string.format("%d,%d,%d",tonumber(st.kind) or 1,tonumber(st.conditional) or 0,tonumber(st.redstone) or 0)
            end
            prev_state=function_copy_state(st)
        end
        local cmd=tostring(node.command or "")
        if cmd:sub(1,1)~="/" then cmd="/"..cmd end
        lines[#lines+1]=cmd; prev_chain=node.chain_id
    end
    lines[#lines+1]="!"
    return table.concat(lines,"\n").."\n"
end

function function_parse_buffer(lines,initial_state)
    local text=table.concat(lines or {},"\n").."\n!\n"
    return function_parse_document(text,{initial_state=initial_state,require_end=true})
end

function function_count_chains(nodes)
    local set={}; local n=0
    for _,v in ipairs(nodes or {}) do local k=tostring(v.chain_id); if not set[k] then set[k]=true; n=n+1 end end
    return n
end

function function_send_chunked(name,text,maxchars)
    maxchars=tonumber(maxchars) or FUNCTION_CHAT_CHUNK
    local buf=""
    local function flush() if buf~="" then send(name,buf); buf="" end end
    local src=tostring(text or "")
    if src:sub(-1)~="\n" then src=src.."\n" end
    local pos=1
    while pos<=#src do
        local nl=src:find("\n",pos,true); if not nl then break end
        local line=src:sub(pos,nl-1); pos=nl+1
        if #line>maxchars then
            flush(); local p=1
            while p<=#line do send(name,line:sub(p,p+maxchars-1)); p=p+maxchars end
        elseif buf=="" then buf=line
        elseif #buf+1+#line<=maxchars then buf=buf.."\n"..line
        else flush(); buf=line end
    end
    flush()
end

function function_document_for_id(id)
    local item,d=function_registry_get(id)
    if not item then return nil,nil,nil,"文件编号不存在" end
    if item.missing then return nil,item,d,"TXT文件已不存在" end
    local text,err=function_read_text(item.name)
    if not text then return nil,item,d,err end
    local doc=function_parse_document(text,{require_end=true})
    return doc,item,d,nil,text
end

function function_view_range(name,id,a,b)
    local doc,item,_,err=function_document_for_id(id); if err then send(name,"§c"..err); return true end
    if #doc.errors>0 then send(name,"§c语法错误："..table.concat(doc.errors,"；")); return true end
    a=math.max(1,tonumber(a) or 1); b=tonumber(b) or a
    if b<a then a,b=b,a end; if b-a+1>FUNCTION_MAX_VIEW then b=a+FUNCTION_MAX_VIEW-1 end
    b=math.min(b,#doc.nodes)
    if a>#doc.nodes then send(name,"§c第"..a.."条不存在；当前只有"..#doc.nodes.."条指令。"); return true end
    local lines={"§8━━━━━━━━━━━━━━━━━━━━","§b✦ #"..id.." "..tostring(item.name).." §7["..a.."~"..b.."]","§8━━━━━━━━━━━━━━━━━━━━"}
    for i=a,b do local n=doc.nodes[i]; lines[#lines+1]="§f"..id.."."..i.." §7"..tostring(n.command) end
    if b<#doc.nodes then lines[#lines+1]="§8还有"..(#doc.nodes-b).."条；可继续输入 §f"..id.."."..(b+1)..".."..math.min(#doc.nodes,b+FUNCTION_PAGE_SIZE) end
    function_send_chunked(name,table.concat(lines,"\n"),FUNCTION_CHAT_CHUNK); return true
end

function function_lock_load()
    local ok,d=pcall(util.json_load,FUNCTION_LOCK_FILE); if not ok or type(d)~="table" then d={locks={}} end; d.locks=d.locks or {}; return d
end
function function_lock_acquire(id,name)
    local d=function_lock_load(); local k=tostring(id); local now=util.timestamp(); local l=d.locks[k]
    if type(l)=="table" and tonumber(l.expires_at or 0)>now and tostring(l.player or "")~=tostring(name) then return false,"该TXT正在被 "..tostring(l.player).." 编辑" end
    d.locks[k]={player=name,expires_at=now+300}; pcall(util.json_write,FUNCTION_LOCK_FILE,d); return true
end
function function_lock_touch(id,name)
    local d=function_lock_load(); local l=d.locks[tostring(id)]; if type(l)=="table" and tostring(l.player)==tostring(name) then l.expires_at=util.timestamp()+300; pcall(util.json_write,FUNCTION_LOCK_FILE,d) end
end
function function_lock_release(id,name)
    local d=function_lock_load(); local l=d.locks[tostring(id)]; if not l or tostring(l.player)==tostring(name) or is_admin(name) then d.locks[tostring(id)]=nil; pcall(util.json_write,FUNCTION_LOCK_FILE,d) end
end

function function_edit_begin(name,id,mode,a,b)
    if not is_admin(name) then send(name,"§cFUNCTION系统仅管理员可编辑。") return true end
    local doc,item,_,err=function_document_for_id(id); if err then send(name,"§c"..err); return true end
    if #doc.errors>0 then send(name,"§c当前TXT有语法错误，请先使用语法检查："..table.concat(doc.errors,"；")); return true end
    local ok,e=function_lock_acquire(id,name); if not ok then send(name,"§c"..e); return true end
    a=tonumber(a); b=tonumber(b) or a
    local d,r=player_record(name,true)
    local base=function_copy_state(FUNCTION_DEFAULT_STATE)
    if a and doc.nodes[a] then base=function_copy_state(doc.nodes[a].state)
    elseif #doc.nodes>0 then base=function_copy_state(doc.nodes[#doc.nodes].state) end
    r.function_active=true; r.function_file_id=tonumber(id); r.function_edit={id=tonumber(id),mode=mode,a=a,b=b,buffer={},base_state=base,started_at=util.timestamp()}; set_menu(d,r,"function_edit"); save_data(d)
    if mode=="replace_single" then
        send(name,"§e已选择 §f"..id.."."..a.."§e。\n§7输入：§f./ 新指令 §7即可替换；系统会自动以 / 写入TXT。\n§7.stop 取消。")
    elseif mode=="replace_range" then
        send(name,"§e已进入范围替换：§f"..id.."."..a..".."..b.."/\n§7逐行输入：§f./ 指令 §7；状态行可直接输入 §f1,0,0§7；§f. §7分隔新链；输入 §f! §7提交。\n§7.stop 取消。")
    else
        local pos=(a and (tostring(a)..(b and b~=a and ".."..b or "")) or "末尾")
        send(name,"§a已进入新增模式：§f#"..id.." §7位置="..pos.."\n§7逐行输入 §f./ 指令§7；可输入状态行或 §f.§7 分链；输入 §f! §7提交。\n§7.stop 取消。")
    end
    return true
end

function function_new_chain_id(nodes)
    local m=0; for _,n in ipairs(nodes or {}) do local v=tonumber(n.chain_id); if v and v>m then m=v end end; return m+1
end

function function_apply_edit(name,edit)
    local doc,item,_,err=function_document_for_id(edit.id); if err then return false,err end
    if #doc.errors>0 then return false,"原TXT语法错误："..table.concat(doc.errors,"；") end
    local nodes=doc.nodes; local mode=edit.mode; local a=tonumber(edit.a); local b=tonumber(edit.b) or a
    local buf=function_parse_buffer(edit.buffer or {},edit.base_state)
    if #buf.errors>0 then return false,"新增内容语法错误："..table.concat(buf.errors,"；") end
    if #buf.nodes==0 then return false,"没有输入任何有效指令" end
    local insert_at=#nodes
    if mode=="replace_single" or mode=="replace_range" then
        if not a or a<1 or a>#nodes then return false,"目标指令不存在" end
        b=math.max(a,math.min(b or a,#nodes)); insert_at=a-1
    elseif mode=="add_after" then
        if a then if a<1 or a>#nodes then return false,"目标指令不存在" end; insert_at=a else insert_at=#nodes end
    elseif mode=="add_range" then
        if not a or not b then return false,"范围无效" end
        a=math.max(1,math.min(a,#nodes)); b=math.max(a,math.min(b,#nodes)); insert_at=math.max(0,b-1) -- 11..15 => 插在原第15条之前
    end
    local anchor_chain=nil
    if insert_at>0 and nodes[insert_at] then anchor_chain=nodes[insert_at].chain_id
    elseif nodes[1] then anchor_chain=nodes[1].chain_id else anchor_chain=1 end
    local next_chain=function_new_chain_id(nodes); local chain_map={}; local first_buf_chain=nil
    for _,n in ipairs(buf.nodes) do if first_buf_chain==nil then first_buf_chain=n.chain_id end end
    for _,n in ipairs(buf.nodes) do
        if not chain_map[n.chain_id] then
            if n.chain_id==first_buf_chain then chain_map[n.chain_id]=anchor_chain else chain_map[n.chain_id]=next_chain; next_chain=next_chain+1 end
        end
        n.chain_id=chain_map[n.chain_id]
    end
    local out={}
    for i,n in ipairs(nodes) do
        if mode=="replace_single" or mode=="replace_range" then
            if i<a or i>b then out[#out+1]=n end
        else out[#out+1]=n end
    end
    if mode=="replace_single" or mode=="replace_range" then
        local result={}; local inserted=false; local old_index=0
        for i,n in ipairs(nodes) do
            if i==a and not inserted then for _,bn in ipairs(buf.nodes) do result[#result+1]=bn end; inserted=true end
            if i<a or i>b then result[#result+1]=n end
        end
        if not inserted then for _,bn in ipairs(buf.nodes) do result[#result+1]=bn end end
        out=result
    else
        local result={}
        for i=1,#nodes do
            result[#result+1]=nodes[i]
            if i==insert_at then for _,bn in ipairs(buf.nodes) do result[#result+1]=bn end end
        end
        if insert_at==0 then local pref={}; for _,bn in ipairs(buf.nodes) do pref[#pref+1]=bn end; for _,n in ipairs(result) do pref[#pref+1]=n end; result=pref
        elseif insert_at>=#nodes then if #nodes==0 then result={}; for _,bn in ipairs(buf.nodes) do result[#result+1]=bn end end end
        out=result
    end
    local ok,w=function_write_text(item.name,function_serialize_nodes(out)); if not ok then return false,w end
    pcall(function_compile_item,edit.id)
    return true,"已保存 "..item.name.."；当前共 "..#out.." 条指令。"
end

function function_delete_commands(name,id,a,b)
    if not is_admin(name) then send(name,"§c仅管理员。") return true end
    local ok,e=function_lock_acquire(id,name); if not ok then send(name,"§c"..e); return true end
    local doc,item,_,err=function_document_for_id(id); if err then function_lock_release(id,name); send(name,"§c"..err); return true end
    if #doc.errors>0 then function_lock_release(id,name); send(name,"§cTXT语法错误，不能安全删除。") return true end
    local nodes=doc.nodes; a=tonumber(a); b=tonumber(b) or a
    if not a then a=#nodes; b=a end
    if not a or a<1 or a>#nodes then function_lock_release(id,name); send(name,"§c目标指令不存在。") return true end
    b=math.max(a,math.min(b,#nodes)); local out={}
    for i,n in ipairs(nodes) do if i<a or i>b then out[#out+1]=n end end
    local okw,ew=function_write_text(item.name,function_serialize_nodes(out)); function_lock_release(id,name)
    if not okw then send(name,"§c"..tostring(ew)); return true end
    pcall(function_compile_item,id)
    send(name,"§a已删除 §f"..id.."."..a..(b~=a and (".."..b) or "").."§a；剩余 "..#out.." 条指令。")
    return true
end

function function_set_delay(name,id,delay)
    if not is_admin(name) then send(name,"§c仅管理员。") return true end
    delay=tonumber(delay)
    if not delay or delay<FUNCTION_MIN_DELAY or delay>FUNCTION_MAX_DELAY then send(name,"§c延迟范围：0.001 ～ 100000 秒。") return true end
    local item,d=function_registry_get(id); if not item then send(name,"§c文件编号不存在。") return true end
    item.delay_sec=delay; item.needs_reload=false
    function_registry_save(d)
    if item.enabled and type(function_schedule_one)=="function" then pcall(function_schedule_one,id) end
    local hz=1/delay
    send(name,string.format("§a执行频率已立即生效：§e%.8g 秒 §7≈ §b%.8g Hz",delay,hz))
    return true
end

function function_set_hz(name,id,hz)
    hz=tonumber(hz); if not hz or hz<0.00001 or hz>1000 then send(name,"§cHz范围：0.00001 ～ 1000。") return true end
    return function_set_delay(name,id,1/hz)
end

function function_toggle(name,id)
    if not is_admin(name) then send(name,"§cFUNCTION系统仅管理员可管理。") return true end
    local item,d=function_registry_get(id); if not item then send(name,"§c文件编号不存在。") return true end
    local turning_on=(item.enabled~=true)
    if turning_on then
        local okc,ec=function_compile_item(id)
        if not okc then send(name,"§c无法开启，TXT语法/读取失败："..tostring(ec)); return true end
        item,d=function_registry_get(id)
        item.enabled=true; item.loaded=true
        item.activation_seq=(tonumber(item.activation_seq) or 0)+1
        item.pulse_marks={}
        item.runtime_last_powered=item.powered==true
        if item.powered==true then item.redstone_seq=(tonumber(item.redstone_seq) or 0)+1 end
    else
        item.enabled=false; item.loaded=true
    end
    function_registry_save(d)
    if type(function_schedule_one)=="function" then pcall(function_schedule_one,id) end
    send(name,"§a#"..id.." "..tostring(item.name).." 已"..(item.enabled and "开启" or "停止").."。"..(item.enabled and "§7 已按当前频率立即注册。" or ""))
    return true
end

function function_debug_load()
    local ok,d=pcall(util.json_load,FUNCTION_DEBUG_FILE); if not ok or type(d)~="table" then d={files={}} end; d.files=d.files or {}; return d
end
function function_debug_save(d) pcall(util.json_write,FUNCTION_DEBUG_FILE,d or {files={}}) end

-- TXT只在开启/重新加载/编辑后编译一次；高频tick直接执行已编译节点。
function function_compile_item(id)
    local item,d=function_registry_get(id)
    if not item or item.missing then return false,"文件不存在" end
    local text,err=function_read_text(item.name); if not text then return false,err end
    local doc=function_parse_document(text,{require_end=true})
    if #doc.errors>0 then
        item.compiled_nodes=nil; item.compiled_at=nil; item.last_error=table.concat(doc.errors,"；"); item.error_at=util.timestamp(); item.enabled=false
        function_registry_save(d)
        return false,item.last_error
    end
    item.compiled_nodes=doc.nodes
    item.compiled_chains=function_count_chains(doc.nodes)
    item.compiled_at=util.timestamp()
    item.last_error=nil
    if item.enabled==true then
        item.activation_seq=(tonumber(item.activation_seq) or 0)+1
        item.pulse_marks={}
        item.runtime_last_powered=item.powered==true
        if item.powered==true then item.redstone_seq=(tonumber(item.redstone_seq) or 0)+1 end
    end
    function_registry_save(d)
    return true,#doc.nodes
end

-- R20F：普通节点走原生 game.sendCommand 无等待直发；只有真正需要 SuccessCount 的前驱才同步确认。
-- 不经过 MCP，不经过 batch/stream，不给普通命令加逐条回包。
function function_round_dispatch(cmd,need_result)
    local c=normalize_cmd(tostring(cmd or ""))
    if c=="" then return false,false,"empty","空指令" end
    if need_result then
        local ok,res=pcall(game.isCmdSuccess,c)
        if ok then return true,res==true,"confirmed",res==true and "" or "SuccessCount=0" end
        local ok2,err2=pcall(game.sendCommand,c)
        return ok2,false,"fallback-send",ok2 and "同步接口异常，已直发；结果未知" or tostring(err2 or res)
    end
    local ok,err=pcall(game.sendCommand,c)
    return ok,nil,"sendCommand",ok and "" or tostring(err)
end

function function_nodes_have_inline_rate(nodes)
    for _,node in ipairs(nodes or {}) do if tonumber(node and node.state and node.state.hz) then return true end end
    return false
end

function function_chain_rates(nodes)
    local out={}
    for _,node in ipairs(nodes or {}) do
        local k=tostring(node.chain_id or 1)
        local hz=tonumber(node.state and node.state.hz)
        if out[k]==nil and hz and hz>0 then out[k]=math.max(0.00001,math.min(20,hz)) end
    end
    return out
end

function function_effective_delay(item)
    if type(item)=="table" and function_nodes_have_inline_rate(item.compiled_nodes) then return 0.05 end
    return math.max(FUNCTION_MIN_DELAY,math.min(FUNCTION_MAX_DELAY,tonumber(item and item.delay_sec) or FUNCTION_DEFAULT_DELAY))
end

function function_gate_name(file_id,chain_id)
    return "F"..tostring(tonumber(file_id) or 0).."C"..tostring(tonumber(chain_id) or 1)
end

function function_gate_wrap(cmd,gate)
    local c=normalize_cmd(tostring(cmd or ""))
    if not gate or not gate.period or gate.period<=1 then return c end
    return 'execute if score "'..gate.name..'" ds_fnclock matches '..tostring(gate.period)..'.. run '..c
end

function function_execute_doc(id,item,doc,debug_mode)
    local debug={at=util.timestamp(),file_id=id,name=item.name,engine=FUNCTION_ENGINE_VERSION,results={},failed=0,total=0,submitted=0,confirmed=0,chains=function_count_chains(doc.nodes)}
    local prev_chain=nil; local prev_success=nil; local prev_activated=false; local changed=false; local gate=nil
    local inline=function_nodes_have_inline_rate(doc.nodes); local rates=function_chain_rates(doc.nodes)
    item.pulse_marks=type(item.pulse_marks)=="table" and item.pulse_marks or {}
    item.activation_seq=tonumber(item.activation_seq) or 1; item.redstone_seq=tonumber(item.redstone_seq) or 0

    if not debug_mode then
        local powered=item.powered==true
        if item.runtime_last_powered==nil then item.runtime_last_powered=powered; changed=true
        elseif item.runtime_last_powered~=powered then if powered then item.redstone_seq=item.redstone_seq+1 end; item.runtime_last_powered=powered; changed=true end
    end

    for i,node in ipairs(doc.nodes) do
        local same_chain=(prev_chain~=nil and tostring(prev_chain)==tostring(node.chain_id))
        local chain_entry=not same_chain
        if chain_entry then
            prev_success=nil; prev_activated=true; gate=nil
            local first_kind=tonumber((node.state or FUNCTION_DEFAULT_STATE).kind) or 1
            if inline and not debug_mode and first_kind~=1 then
                local hz=tonumber(rates[tostring(node.chain_id)]) or 20
                hz=math.max(0.00001,math.min(20,hz))
                local period=math.max(1,math.floor((20/hz)+0.5))
                if period>1 then
                    gate={name=function_gate_name(id,node.chain_id),period=period,hz=hz}
                    pcall(game.sendCommand,'scoreboard players add "'..gate.name..'" ds_fnclock 1')
                end
            end
        end

        local st=node.state or FUNCTION_DEFAULT_STATE
        local kind=tonumber(st.kind) or 1; local conditional=tonumber(st.conditional) or 0; local needs_redstone=(tonumber(st.redstone) or 0)==1
        local execute=true; local why=""
        if kind==0 and not chain_entry and prev_activated~=true then execute=false; why="连锁前驱未激活" end
        if execute and needs_redstone and item.powered~=true then execute=false; why="等待红石" end
        if execute and kind==1 then
            local token=needs_redstone and ("r:"..tostring(item.redstone_seq)) or ("a:"..tostring(item.activation_seq))
            local key=tostring(node.chain_id)..":"..tostring(node.index or i)
            if not debug_mode and tostring(item.pulse_marks[key] or "")==token then execute=false; why="脉冲本次激活已执行"
            elseif not debug_mode then item.pulse_marks[key]=token; changed=true end
        end
        if execute and conditional==1 and prev_success~=true then execute=false; why="前一条SuccessCount=0/未知" end

        if execute then
            local nextnode=doc.nodes[i+1]
            local next_same=nextnode and tostring(nextnode.chain_id)==tostring(node.chain_id)
            local next_cond=next_same and tonumber((nextnode.state or FUNCTION_DEFAULT_STATE).conditional)==1
            local need_result=(debug_mode==true) or (next_cond==true)
            local actual=(not debug_mode) and function_gate_wrap(node.command,gate) or node.command
            local dispatched,success,mode,err=function_round_dispatch(actual,need_result)
            prev_activated=(dispatched==true); prev_success=need_result and (success==true) or nil
            debug.total=debug.total+1; if dispatched then debug.submitted=debug.submitted+1 end; if need_result then debug.confirmed=debug.confirmed+1 end
            if (not dispatched) or (need_result and success~=true) then debug.failed=debug.failed+1 end
            if debug_mode then debug.results[#debug.results+1]={index=i,command=node.command,success=success,dispatched=dispatched,mode=mode,state=function_state_text(st),error=err or ""} end
        else
            prev_activated=false; prev_success=false
            if debug_mode then debug.results[#debug.results+1]={index=i,command=node.command,success=false,skipped=true,state=function_state_text(st),error=why} end
        end

        local nextnode=doc.nodes[i+1]
        local chain_end=(not nextnode) or tostring(nextnode.chain_id)~=tostring(node.chain_id)
        if chain_end and gate and not debug_mode then
            pcall(game.sendCommand,'execute if score "'..gate.name..'" ds_fnclock matches '..tostring(gate.period)..'.. run scoreboard players set "'..gate.name..'" ds_fnclock 0')
            gate=nil
        end
        prev_chain=node.chain_id
    end
    return debug,changed
end

function function_execute_file_id(id,debug_mode)
    local item,d=function_registry_get(id)
    if not item or item.missing or item.loaded==false or (not debug_mode and item.enabled~=true) then return false,"未运行" end
    local doc=nil
    if debug_mode==true then
        local text,err=function_read_text(item.name); if not text then return false,err end
        doc=function_parse_document(text,{require_end=true})
        if #doc.errors>0 then return false,table.concat(doc.errors,"；") end
    else
        if type(item.compiled_nodes)~="table" then
            local okc,ec=function_compile_item(id); if not okc then pcall(function_schedule_one,id); return false,ec end
            item,d=function_registry_get(id)
        end
        doc={nodes=item.compiled_nodes or {},errors={},warnings={},commands=#(item.compiled_nodes or {}),chains=tonumber(item.compiled_chains) or 1}
    end
    local dbg,changed=function_execute_doc(tonumber(id),item,doc,debug_mode==true)
    if changed and not debug_mode then function_registry_save(d) end
    if debug_mode then local dd=function_debug_load(); dd.files[tostring(id)]=dbg; function_debug_save(dd) end
    return true,dbg
end

-- 旧命令容器停用，FUNCTION统一使用同步顺序执行核。
function cmd_container_tick() return true end

FUNCTION_TIMER_STATE_FILE = game.dataDir().."/function_timer_state.json"
function function_timer_state_load()
    local ok,d=pcall(util.json_load,FUNCTION_TIMER_STATE_FILE)
    if not ok or type(d)~="table" then d={items={}} end
    d.items=d.items or {}
    return d
end
function function_timer_state_save(d) pcall(util.json_write,FUNCTION_TIMER_STATE_FILE,d or {items={}}) end

function function_timer_dispatch(id)
    return function_execute_file_id(id,false)
end

-- R20G：不再在每次 main.lua 加载时创建 999 个闭包。
-- 只给真实启用的 TXT 建回调；旧运行环境即使重载源码，也会从注册表恢复这些回调。
function function_ensure_callback(id)
    id=tonumber(id)
    if not id or id<1 or id>FUNCTION_MAX_FILES then return false end
    local key="function_file_tick_"..tostring(id)
    if type(_G[key])~="function" then
        local fixed=id
        _G[key]=function() return function_timer_dispatch(fixed) end
    end
    return true
end
do
    local __rg=function_registry_load()
    for __id,__it in pairs(__rg.items or {}) do
        if type(__it)=="table" and __it.enabled==true and __it.loaded~=false and __it.missing~=true then function_ensure_callback(__id) end
    end
end

function function_schedule_one(id)
    id=tonumber(id); if not id then return false,"编号无效" end
    local ts=function_timer_state_load(); local key=tostring(id)
    local old=tonumber(ts.items[key]); if old then pcall(util.cancel,old); ts.items[key]=nil end
    local item,d=function_registry_get(id)
    if not item then function_timer_state_save(ts); return false,"文件编号不存在" end
    item.timer_registered=false; item.timer_id=nil
    if not item.enabled or item.loaded==false or item.missing then
        function_registry_save(d); function_timer_state_save(ts); return true,"已停止"
    end
    local delay=function_effective_delay(item)
    function_ensure_callback(id)
    local ok,h=pcall(util.schedule,delay,"function_file_tick_"..id)
    if ok and type(h)=="number" and h>0 then
        ts.items[key]=h; item.timer_registered=true; item.timer_id=h; item.registered_delay=delay; item.needs_reload=false
        function_registry_save(d); function_timer_state_save(ts); return true,h
    end
    item.needs_reload=true; item.last_error="计时器注册失败："..tostring(h); function_registry_save(d); function_timer_state_save(ts)
    return false,item.last_error
end

function function_cancel_old_timers()
    local ts=function_timer_state_load(); local n=0
    for _,h in pairs(ts.items or {}) do if tonumber(h) then pcall(util.cancel,tonumber(h)); n=n+1 end end
    local ok,legacy=pcall(util.json_load,FUNCTION_TIMER_FILE)
    if ok and type(legacy)=="table" then for _,h in ipairs(legacy.ids or {}) do if tonumber(h) then pcall(util.cancel,tonumber(h)); n=n+1 end end end
    function_timer_state_save({items={}}); pcall(util.json_write,FUNCTION_TIMER_FILE,{ids={},count=0,at=util.timestamp(),version=FINAL_PATCH_VERSION})
    return n
end

function function_register_timers()
    pcall(function_cancel_old_timers); pcall(function_scan_files,true)
    local base=function_registry_load(); local ts={items={}}; local ids={}; local n=0
    for _,x in ipairs(function_registry_sorted(base,false)) do
        local id=x.id
        local item=function_registry_get(id)
        if item and item.enabled and item.loaded~=false and not item.missing then
            local okc,ec=function_compile_item(id)
            local it,rd=function_registry_get(id)
            if okc and it then
                local delay=function_effective_delay(it)
                function_ensure_callback(id)
                local ok,h=pcall(util.schedule,delay,"function_file_tick_"..id)
                if ok and type(h)=="number" and h>0 then
                    ts.items[tostring(id)]=h; ids[#ids+1]=h; n=n+1
                    it.timer_registered=true; it.timer_id=h; it.registered_delay=delay; it.needs_reload=false
                else
                    it.timer_registered=false; it.timer_id=nil; it.needs_reload=true; it.last_error="计时器注册失败："..tostring(h)
                end
                function_registry_save(rd)
            elseif it then
                it.timer_registered=false; it.timer_id=nil; it.needs_reload=true; it.last_error=tostring(ec or "编译失败")
                function_registry_save(rd)
            end
        elseif item then
            local _,rd=function_registry_get(id); item.timer_registered=false; item.timer_id=nil; function_registry_save(rd)
        end
    end
    function_timer_state_save(ts)
    pcall(util.json_write,FUNCTION_TIMER_FILE,{ids=ids,count=n,at=util.timestamp(),version=FINAL_PATCH_VERSION,engine=FUNCTION_ENGINE_VERSION})
    return n
end

-- 不再用1秒fallback偷偷改变用户设定的频率；注册失败就明确显示失败。
function function_fallback_tick() return true end

function function_file_status_label(it)
    if it.missing then return "§8[缺失]" end
    if it.loaded==false then return "§7[卸载]" end
    if it.enabled then return it.timer_registered and "§a[运行]" or "§e[计时器异常]" end
    return "§c[停止]"
end

function function_show_main(name)
    if not is_admin(name) then send(name,"§cFUNCTION命令链系统仅管理员可使用。") return true end
    local ok,msg=function_scan_files(false); local d=function_registry_load(); local arr=function_registry_sorted(d,false); local run=0
    for _,x in ipairs(arr) do if x.item.enabled then run=run+1 end end
    local lines={"§8━━━━━━━━━━━━━━━━━━━━━━━━","§b§l      ✦ FUNCTION 管理 ✦","§8━━━━━━━━━━━━━━━━━━━━━━━━","§fTXT文件：§e"..#arr.."  §f运行：§a"..run.."  §f停止：§c"..(#arr-run)}
    for _,x in ipairs(arr) do
        local hz=1/(tonumber(x.item.delay_sec) or FUNCTION_DEFAULT_DELAY)
        lines[#lines+1]=string.format("§f%d. §e%s §8│ %s §8│ §7%.5gHz",x.id,tostring(x.item.name),function_file_status_label(x.item),hz)
    end
    if #arr==0 then lines[#lines+1]="§7暂无TXT。请放入：§f插件数据文件/ds_ai_agent/command_txt/" end
    local d0,r=player_record(name,true); r.function_active=true; set_menu(d0,r,"function_main"); save_data(d0)
    function_send_chunked(name,table.concat(lines,"\n"),FUNCTION_CHAT_CHUNK)
    if not ok and msg then send(name,"§7"..tostring(msg)) end
    return true
end

