        "§f1. 开启 / 停止","§f2. 查看 / 搜索 / 编辑","§f3. 调节执行频率","§f4. 调试与运行状态","§f5. 文件管理","§7输入0返回  §8│ §f.stop §7退出"
    },"\n")); return true
end

function function_show_view_page(name,id,page)
    local doc,item,_,err=function_document_for_id(id); if err then send(name,"§c"..err); return true end
    if #doc.errors>0 then send(name,"§cTXT语法错误："..table.concat(doc.errors,"；")); return true end
    page=math.max(1,tonumber(page) or 1); local start=(page-1)*FUNCTION_PAGE_SIZE+1
    if start>#doc.nodes and #doc.nodes>0 then page=math.max(1,math.ceil(#doc.nodes/FUNCTION_PAGE_SIZE)); start=(page-1)*FUNCTION_PAGE_SIZE+1 end
    local finish=math.min(#doc.nodes,start+FUNCTION_PAGE_SIZE-1)
    local d,r=player_record(name,true); r.function_active=true; r.function_file_id=tonumber(id); r.function_page=page; set_menu(d,r,"function_view"); save_data(d)
    local lines={"§8━━━━━━━━━━━━━━━━━━━━","§b✦ #"..id.." "..item.name.." §7第"..page.."页","§8━━━━━━━━━━━━━━━━━━━━"}
    for i=start,finish do lines[#lines+1]="§f"..id.."."..i.." §7"..doc.nodes[i].command end
    lines[#lines+1]="§7+ 下一页  - 上一页  §8│ §7输入编号选择编辑"
    lines[#lines+1]="§7范围查看：§f11..20  §8│ §7编辑：§f11/ §7或 §f11..15/"
    function_send_chunked(name,table.concat(lines,"\n"),FUNCTION_CHAT_CHUNK); return true
end

