function function_syntax_check(name,id)
    local doc,item,_,err=function_document_for_id(id); if err then send(name,"§c"..err); return true end
    local lines={"§b✦ 语法检查 #"..id.." "..item.name,"§f指令：§e"..#doc.nodes.."  §f链条：§e"..function_count_chains(doc.nodes)}
    if #doc.errors==0 then lines[#lines+1]="§a✓ 语法通过；末尾 !、链分隔与状态行均可解析。" else for _,e in ipairs(doc.errors) do lines[#lines+1]="§c✗ "..e end end
    for _,w in ipairs(doc.warnings or {}) do lines[#lines+1]="§e! "..w end
    function_send_chunked(name,table.concat(lines,"\n"),FUNCTION_CHAT_CHUNK); return true
end

function function_debug_result(name,id,failed_only)
    local d=function_debug_load(); local x=d.files[tostring(id)]
    if type(x)~="table" then send(name,"§7还没有调试记录，请先执行单周期真实测试。") return true end
    local lines={"§d✦ 最近测试 #"..id.." §7"..patch_beijing_fmt(x.at),"§f总执行：§e"..tostring(x.total or 0).."  §f失败：§c"..tostring(x.failed or 0)}
    for _,r in ipairs(x.results or {}) do
        if not failed_only or r.success~=true then lines[#lines+1]=string.format("§f%d. %s §8│ %s §8│ %s",tonumber(r.index) or 0,r.success and "§a成功" or (r.skipped and "§7跳过" or "§c失败"),tostring(r.command),tostring(r.error or "")) end
    end
    function_send_chunked(name,table.concat(lines,"\n"),FUNCTION_CHAT_CHUNK); return true
end

function function_file_info(name,id)
    local doc,item,_,err=function_document_for_id(id); if err then send(name,"§c"..err); return true end
    send(name,string.format("§b✦ 文件信息 #%-d\n§f名称：§e%s\n§f指令：§e%d\n§f链条：§e%d\n§f延迟：§e%.8g秒\n§f频率：§b%.8gHz\n§f运行：%s\n§f计时器：%s\n§f计时器异常：%s",id,item.name,#doc.nodes,function_count_chains(doc.nodes),item.delay_sec,1/item.delay_sec,item.enabled and "§a开启" or "§c停止",item.timer_registered and "§a已注册" or "§7未注册",item.needs_reload and "§e是" or "§a否")); return true
end

function function_shell_delete(path)
    local ok,res=pcall(system.shell,"rm -f -- "..function_shell_quote(path))
    return ok and type(res)=="table" and res.ok==true and tonumber(res.exit or 1)==0,res
end

function function_rename_file(name,id,newname)
    local item,d=function_registry_get(id); if not item then send(name,"§c文件不存在。") return true end
    local n,e=function_safe_filename(newname); if not n then send(name,"§c"..e); return true end
    local oldtxt=function_read_text(item.name); if not oldtxt then send(name,"§c原文件读取失败。") return true end
    local existing=function_read_text(n); if existing then send(name,"§c目标文件已存在。") return true end
    local oldpath=function_file_path(item.name); local oksh,res=pcall(system.shizukuStatus)
    if not oksh or type(res)~="table" or res.granted~=true then send(name,"§c重命名需要Shizuku文件删除权限；当前未授权。复制功能仍可使用。") return true end
    local okw,ew=function_write_text(n,oldtxt); if not okw then send(name,"§c"..ew); return true end
    local del=function_shell_delete(oldpath); if not del then send(name,"§c新文件已写入，但旧文件删除失败。为避免编号混乱，请手动处理后执行 .function 刷新。") return true end
    item.name=n; item.missing=false; item.needs_reload=false; function_registry_save(d); pcall(function_compile_item,id); send(name,"§a已重命名为：§e"..n.."§7，文件编号 #"..id.." 保持不变。") return true
end

function function_copy_file(name,id,newname)
    local item=function_registry_get(id); if not item then return true end
    local n,e=function_safe_filename(newname); if not n then send(name,"§c"..e); return true end
    if function_read_text(n) then send(name,"§c目标文件已存在。") return true end
    local txt,er=function_read_text(item.name); if not txt then send(name,"§c"..er); return true end
    local ok,w=function_write_text(n,txt); if not ok then send(name,"§c"..w); return true end
    local okr,newid=function_register_filename(n); send(name,okr and ("§a复制成功：§e"..n.." §7编号 #"..tostring(newid).."。首次运行直接开启即可。") or ("§c"..tostring(newid))); return true
end

function function_delete_file(name,id)
    local item,d=function_registry_get(id); if not item then send(name,"§c文件不存在。") return true end
    local path=function_file_path(item.name); local oksh,res=pcall(system.shizukuStatus)
    if not oksh or type(res)~="table" or res.granted~=true then send(name,"§c删除TXT需要Shizuku权限，当前无法安全删除真实文件。") return true end
    local ok=function_shell_delete(path); if not ok then send(name,"§c删除文件失败。") return true end
    item.enabled=false; item.loaded=false; item.missing=true; item.deleted_at=util.timestamp(); item.timer_registered=false; function_registry_save(d); pcall(function_schedule_one,id); function_lock_release(id,name)
    send(name,"§aTXT已删除；固定编号 #"..id.." 保留在历史登记中，不会被其他文件抢占。") return true
end

-- 管理员编辑会话输入。命令在聊天里统一使用 ./ 开头，保存到TXT时自动变成 /。
function function_handle_edit_input(name,raw,d,r)
    local e=r.function_edit; if type(e)~="table" then clear_menu(d,r); return true end
    if raw==".stop" or raw=="退出" then function_lock_release(e.id,name); r.function_edit=nil; set_menu(d,r,"function_file"); save_data(d); send(name,"§e已取消编辑，没有修改TXT。") return true end
    function_lock_touch(e.id,name)
    if e.mode=="replace_single" then
        if raw:sub(1,2)~="./" then send(name,"§e单条修改请输入：§f./ 新指令 §7（前面的 ./ 是编辑标记）。") return true end
        local cmd=trim(raw:sub(3)); if cmd=="" then send(name,"§c新指令不能为空。") return true end
        e.buffer={"/"..cmd}; local ok,msg=function_apply_edit(name,e); function_lock_release(e.id,name); r.function_edit=nil; set_menu(d,r,"function_file"); save_data(d); send(name,ok and ("§a"..msg) or ("§c"..msg)); return true
    end
    if raw=="!" then
        local ok,msg=function_apply_edit(name,e); if ok then function_lock_release(e.id,name); r.function_edit=nil; set_menu(d,r,"function_file"); save_data(d); send(name,"§a"..msg) else send(name,"§c"..msg) end; return true
    end
    local _,isstate=function_parse_state_line(raw,FUNCTION_DEFAULT_STATE)
    if raw=="." or isstate then e.buffer[#e.buffer+1]=raw; save_data(d); send(name,"§7已加入编辑缓冲：§f"..raw); return true end
    if raw:sub(1,2)=="./" then local cmd=trim(raw:sub(3)); if cmd=="" then send(name,"§c指令不能为空。") return true end; e.buffer[#e.buffer+1]="/"..cmd; save_data(d); send(name,"§7已加入：§f/"..cmd); return true end
    send(name,"§e编辑模式只接受：§f./ 指令§e、状态行 §f1,0,0§e、链分隔 §f.§e、提交 §f!§e、取消 §f.stop")
    return true
end

function function_handle_direct_ref(name,raw,r)
    if not is_admin(name) or not (r and r.function_active) then return false end
    local fid,a,b,edit
    fid,a,b=raw:match("^(%d+)%.(%d+)%.%.(%d+)(/?)$")
    if fid then edit=(b and raw:sub(-1)=="/"); if edit then return function_edit_begin(name,tonumber(fid),"replace_range",tonumber(a),tonumber(b)) else return function_view_range(name,tonumber(fid),tonumber(a),tonumber(b)) end end
    fid,a,edit=raw:match("^(%d+)%.(%d+)(/?)$")
    if fid then if raw:sub(-1)=="/" then return function_edit_begin(name,tonumber(fid),"replace_single",tonumber(a),tonumber(a)) else return function_view_range(name,tonumber(fid),tonumber(a),tonumber(a)) end end
    return false
end

function function_handle_add_delete(name,raw)
    if not is_admin(name) then return false end
    local spec=raw:match("^%./%+%s*(.+)$")
    if spec then
        local fid,a,b=spec:match("^(%d+)%.(%d+)%.%.(%d+)/?$")
        if fid then return function_edit_begin(name,tonumber(fid),"add_range",tonumber(a),tonumber(b)) end
        fid,a=spec:match("^(%d+)%.(%d+)/?$")
        if fid then return function_edit_begin(name,tonumber(fid),"add_after",tonumber(a),tonumber(a)) end
        fid=spec:match("^(%d+)/?$")
        if fid then return function_edit_begin(name,tonumber(fid),"add_after",nil,nil) end
        send(name,"§c格式：./+ 7  或  ./+ 7.11  或  ./+ 7.11..15"); return true
    end
    spec=raw:match("^%./%-%s*(.+)$")
    if spec then
        local fid,a,b=spec:match("^(%d+)%.(%d+)%.%.(%d+)/?$"); if fid then return function_delete_commands(name,tonumber(fid),tonumber(a),tonumber(b)) end
        fid,a=spec:match("^(%d+)%.(%d+)/?$"); if fid then return function_delete_commands(name,tonumber(fid),tonumber(a),tonumber(a)) end
        fid=spec:match("^(%d+)/?$"); if fid then return function_delete_commands(name,tonumber(fid),nil,nil) end
        send(name,"§c格式：./- 7  或  ./- 7.11  或  ./- 7.11..15"); return true
    end
    return false
end

-- R14最终聊天路由。
local _r14_prev_on_chat=on_chat
function on_chat(playerName,msg)
    local raw=trim(tostring(msg or "")); local low=lower(raw); local d,r=player_record(playerName,true)
    if low==".function" or low=="function" or low==".函数" then return function_show_main(playerName) end
    if low==".function 刷新" or low==".function reload" then
        if not is_admin(playerName) then send(playerName,"§c仅管理员。") return true end
        local ok,text=function_scan_files(false); send(playerName,ok and ("§a"..tostring(text).."\n§7新加入的TXT如需精确独立计时器，请重载插件一次。") or ("§c"..tostring(text))); return true
    end
    local reg=raw:match("^%.function%s+注册%s+(.+)$"); if reg then if not is_admin(playerName) then send(playerName,"§c仅管理员。") return true end; local ok,v=function_register_filename(reg); send(playerName,ok and ("§a已登记TXT，固定编号 #"..tostring(v).."。") or ("§c"..tostring(v))); return true end
    if function_handle_add_delete(playerName,raw) then return true end
    if r and r.menu=="function_edit" then return function_handle_edit_input(playerName,raw,d,r) end
    if function_handle_direct_ref(playerName,raw,r) then return true end

    if r and tostring(r.menu or ""):find("^function_") then
        if not is_admin(playerName) then clear_menu(d,r); r.function_active=nil; save_data(d); send(playerName,"§cFUNCTION系统仅管理员可使用。") return true end
        if raw==".stop" or raw=="退出" then if r.function_edit then function_lock_release(r.function_edit.id,playerName) end; r.function_edit=nil; r.function_active=nil; clear_menu(d,r); save_data(d); send(playerName,"§e已退出FUNCTION系统。") return true end
        local id=tonumber(r.function_file_id)
        if r.menu=="function_main" then local n=tonumber(raw); if n then return function_show_file_menu(playerName,n) end; send(playerName,"§c请输入TXT固定编号。") return true end
        if r.menu=="function_file" then
            local n=tonumber(raw); if n==0 then return function_show_main(playerName) elseif n==1 then return function_toggle(playerName,id) elseif n==2 then return function_show_view_page(playerName,id,1) elseif n==3 then return function_show_freq_menu(playerName,id) elseif n==4 then return function_show_debug_menu(playerName,id) elseif n==5 then return function_show_manage_menu(playerName,id) end; send(playerName,"§c请输入0~5。") return true
        end
        if r.menu=="function_view" then
            if raw=="+" then return function_show_view_page(playerName,id,(tonumber(r.function_page) or 1)+1) elseif raw=="-" then return function_show_view_page(playerName,id,math.max(1,(tonumber(r.function_page) or 1)-1)) elseif raw=="0" then return function_show_file_menu(playerName,id) end
            local a,b=raw:match("^(%d+)%.%.(%d+)(/?)$"); if a then if raw:sub(-1)=="/" then return function_edit_begin(playerName,id,"replace_range",tonumber(a),tonumber(b)) else return function_view_range(playerName,id,tonumber(a),tonumber(b)) end end
            local a2=raw:match("^(%d+)/$"); if a2 then return function_edit_begin(playerName,id,"replace_single",tonumber(a2),tonumber(a2)) end
            local n=tonumber(raw); if n then return function_edit_begin(playerName,id,"replace_single",n,n) end
            send(playerName,"§c输入编号、范围11..20、11/、11..15/、+、-或0。") return true
        end
        if r.menu=="function_freq" then
            local n=tonumber(raw); if n==0 then return function_show_file_menu(playerName,id) elseif n==1 then set_menu(d,r,"function_freq_hz"); save_data(d); send(playerName,"§e请输入Hz：0.00001 ～ 1000"); return true elseif n==2 then set_menu(d,r,"function_freq_delay"); save_data(d); send(playerName,"§e请输入延迟秒数：0.001 ～ 100000"); return true elseif n==3 then send(playerName,"§f预设：§e0.001秒=1000Hz  0.05秒=20Hz  1秒=1Hz  10秒=0.1Hz  100秒=0.01Hz  100000秒=0.00001Hz"); return true elseif n==4 then return function_set_delay(playerName,id,0.05) end; send(playerName,"§c请输入0~4。") return true
        end
        if r.menu=="function_freq_hz" then local v=tonumber(raw); if not v then send(playerName,"§c请输入数字Hz。") return true end; local ret=function_set_hz(playerName,id,v); function_show_freq_menu(playerName,id); return ret end
        if r.menu=="function_freq_delay" then local v=tonumber(raw); if not v then send(playerName,"§c请输入数字秒数。") return true end; local ret=function_set_delay(playerName,id,v); function_show_freq_menu(playerName,id); return ret end
        if r.menu=="function_debug" then
            local n=tonumber(raw); if n==0 then return function_show_file_menu(playerName,id) elseif n==1 then local ok,res=function_execute_file_id(id,true); send(playerName,ok and ("§a单周期测试完成：执行"..tostring(res.total).."，失败"..tostring(res.failed).."。") or ("§c测试失败："..tostring(res))); return true elseif n==2 then return function_debug_result(playerName,id,false) elseif n==3 then return function_debug_result(playerName,id,true) elseif n==4 then local it=function_registry_get(id); if it then send(playerName,string.format("§b计时器状态\n§f目标延迟：§e%.8g秒\n§f目标Hz：§e%.8g\n§f已注册延迟：§e%s\n§f专属计时器：%s\n§f计时器异常：%s",it.delay_sec,1/it.delay_sec,tostring(it.registered_delay or "--"),it.timer_registered and "§a是" or "§7否",it.needs_reload and "§e是" or "§a否")) end; return true elseif n==5 then local doc,it,_,er=function_document_for_id(id); if er then send(playerName,"§c"..er) else send(playerName,"§f链条：§e"..function_count_chains(doc.nodes).."  §f节点：§e"..#doc.nodes.."  §f红石："..(it.powered and "§aON" or "§7OFF")) end; return true elseif n==6 then local dd=function_debug_load(); dd.files[tostring(id)]=nil; function_debug_save(dd); send(playerName,"§a调试记录已清空。") return true elseif n==7 then local it,rd=function_registry_get(id); if it then it.powered=not it.powered; function_registry_save(rd); send(playerName,"§a模拟红石已切换为："..(it.powered and "§aON" or "§7OFF")) end; return true end; send(playerName,"§c请输入0~7。") return true
        end
        if r.menu=="function_manage" then
            local n=tonumber(raw); if n==0 then return function_show_file_menu(playerName,id) elseif n==1 then local ok,msg=function_scan_files(false); local it,rd=function_registry_get(id); if it then it.loaded=true; function_registry_save(rd) end; local okc,ec=function_compile_item(id); if it and it.enabled then pcall(function_schedule_one,id) end; send(playerName,(ok and okc) and ("§a"..tostring(msg).."；TXT已重新编译并生效。") or ("§c"..tostring(ec or msg))); return true elseif n==2 then return function_syntax_check(playerName,id) elseif n==3 then set_menu(d,r,"function_rename"); save_data(d); send(playerName,"§e请输入新TXT文件名："); return true elseif n==4 then set_menu(d,r,"function_copy"); save_data(d); send(playerName,"§e请输入复制后的TXT文件名："); return true elseif n==5 then local it,rd=function_registry_get(id); if it then it.enabled=false; it.loaded=false; function_registry_save(rd); send(playerName,"§a已停止并卸载 #"..id.."；TXT文件本身没有删除。") end; return true elseif n==6 then return function_file_info(playerName,id) elseif n==7 then set_menu(d,r,"function_delete_confirm"); save_data(d); send(playerName,"§c确认删除真实TXT文件？输入 §fDELETE §c确认，其他内容取消。"); return true end; send(playerName,"§c请输入0~7。") return true
        end
        if r.menu=="function_rename" then local v=raw; set_menu(d,r,"function_manage"); save_data(d); return function_rename_file(playerName,id,v) end
        if r.menu=="function_copy" then local v=raw; set_menu(d,r,"function_manage"); save_data(d); return function_copy_file(playerName,id,v) end
        if r.menu=="function_delete_confirm" then set_menu(d,r,"function_manage"); save_data(d); if raw=="DELETE" then return function_delete_file(playerName,id) end; send(playerName,"§e已取消删除。") return true end
    end
    return _r14_prev_on_chat(playerName,msg)
end

-- R14自备份：补入FUNCTION注册表、调试数据、计时器清单及所有可扫描TXT。
local _r14_prev_backup_plugin_list=backup_plugin_list
function backup_plugin_list()
    local list={}; if type(_r14_prev_backup_plugin_list)=="function" then local ok,v=pcall(_r14_prev_backup_plugin_list); if ok and type(v)=="table" then list=v end end
