-- 1.0.66 R14A：语义收口（链激活、帮助/触发词、旧命令容器别名）
-- ============================================================
FINAL_PATCH_VERSION = "1.0.66-R14A"
FINAL_PATCH_TAG = "FUNCTION命令链_完整管理版_R14A"

-- R20C：执行语义已在上方统一为 main(17) 同步顺序内核，这里不再二次覆盖。

-- 修正范围替换锚点：替换时继承被替换首条所在链，不会错误并入上一条独立链。
local _r14a_old_apply_edit=function_apply_edit
function function_apply_edit(name,edit)
    local doc,item,_,err=function_document_for_id(edit.id); if err then return false,err end
    if #doc.errors>0 then return false,"原TXT语法错误："..table.concat(doc.errors,"；") end
    local nodes=doc.nodes; local mode=edit.mode; local a=tonumber(edit.a); local b=tonumber(edit.b) or a
    local buf=function_parse_buffer(edit.buffer or {},edit.base_state)
    if #buf.errors>0 then return false,"新增内容语法错误："..table.concat(buf.errors,"；") end
    if #buf.nodes==0 then return false,"没有输入任何有效指令" end
    local insert_at=#nodes; local anchor_chain=nil
    if mode=="replace_single" or mode=="replace_range" then
        if not a or a<1 or a>#nodes then return false,"目标指令不存在" end
        b=math.max(a,math.min(b or a,#nodes)); insert_at=a-1; anchor_chain=nodes[a] and nodes[a].chain_id or 1
    elseif mode=="add_after" then
        if a then if a<1 or a>#nodes then return false,"目标指令不存在" end; insert_at=a else insert_at=#nodes end
        anchor_chain=(insert_at>0 and nodes[insert_at] and nodes[insert_at].chain_id) or (nodes[1] and nodes[1].chain_id) or 1
    elseif mode=="add_range" then
        if not a or not b then return false,"范围无效" end
        a=math.max(1,math.min(a,#nodes)); b=math.max(a,math.min(b,#nodes)); insert_at=math.max(0,b-1)
        anchor_chain=(insert_at>0 and nodes[insert_at] and nodes[insert_at].chain_id) or (nodes[a] and nodes[a].chain_id) or 1
    else return false,"未知编辑模式" end
    local next_chain=function_new_chain_id(nodes); local chain_map={}; local first_buf_chain=buf.nodes[1] and buf.nodes[1].chain_id or 1
    for _,n in ipairs(buf.nodes) do
        if not chain_map[n.chain_id] then if n.chain_id==first_buf_chain then chain_map[n.chain_id]=anchor_chain else chain_map[n.chain_id]=next_chain; next_chain=next_chain+1 end end
        n.chain_id=chain_map[n.chain_id]
    end
    local result={}
    if mode=="replace_single" or mode=="replace_range" then
        local inserted=false
        for i,n in ipairs(nodes) do
            if i==a and not inserted then for _,bn in ipairs(buf.nodes) do result[#result+1]=bn end; inserted=true end
            if i<a or i>b then result[#result+1]=n end
        end
        if not inserted then for _,bn in ipairs(buf.nodes) do result[#result+1]=bn end end
    else
        if insert_at==0 then for _,bn in ipairs(buf.nodes) do result[#result+1]=bn end end
        for i,n in ipairs(nodes) do result[#result+1]=n; if i==insert_at then for _,bn in ipairs(buf.nodes) do result[#result+1]=bn end end end
        if #nodes==0 and insert_at~=0 then for _,bn in ipairs(buf.nodes) do result[#result+1]=bn end end
    end
    local ok,w=function_write_text(item.name,function_serialize_nodes(result)); if not ok then return false,w end
    pcall(function_compile_item,edit.id)
    return true,"已保存 "..item.name.."；当前共 "..#result.." 条指令。"
end

-- 触发词中加入新的FUNCTION入口；旧“.命令容器”只作为兼容别名，不再打开旧系统。
function show_trigger_words(name,page)
    local all={
        ".help",".stop / 退出",".触发词","AI 内容 / ai 内容","指令 内容",
        ".保存 / .保",".回 / .home / .传",".删除 / .删",".死亡日志",".死亡点返回 [序号]",
        ".签到",".背包",".金币排行",".玩家市场 / .市场",".领地 / .领地保护",
        ".function（管理员）","./+ 文件[.行]（管理员）","./- 文件[.行]（管理员）",
        ".公会 / .工会",".传送公会 / .传送工会",".传送公会仓库 / .传送工会仓库",".公会签到",".公会公告",".公会邀请码",".公会排行",".公会外交",
        ".群号 数字（管理员）",".公告栏刷新（管理员）",".备份（管理员）"
    }
    local per=12; local maxp=math.max(1,math.ceil(#all/per)); page=math.max(1,math.min(tonumber(page) or 1,maxp)); local first=(page-1)*per+1; local last=math.min(#all,first+per-1)
    local lines={"§8§m━━━━━━━━━━━━━━━━━━━━━━━━","§b✦ 触 发 词 ✦ §7"..page.."/"..maxp,"§8§m━━━━━━━━━━━━━━━━━━━━━━━━"}; for i=first,last do lines[#lines+1]="§f"..all[i] end; lines[#lines+1]="§7+ 下一页   - 上一页   .stop 退出"
    local d,r=player_record(name,true); r.trigger_page=page; set_menu(d,r,"trigger_words"); send(name,table.concat(lines,"\n")); return true
end

local _r14a_prev_chat=on_chat
function on_chat(playerName,msg)
    local raw=trim(tostring(msg or "")); local low=lower(raw)
    if low==".命令容器" or low==".命令方块容器" then return function_show_main(playerName) end
    local oldimp=raw:match("^%.命令容器导入%s+(.+)$") or raw:match("^%.命令方块容器导入%s+(.+)$")
    if oldimp then
        if not is_admin(playerName) then send(playerName,"§c仅管理员。") return true end
        local ok,id=function_register_filename(oldimp); send(playerName,ok and ("§a已登记为FUNCTION文件 #"..tostring(id).."。请使用 .function 管理。") or ("§c"..tostring(id))); return true
    end
    return _r14a_prev_chat(playerName,msg)
end

