R15_AI_SKILL_IDS={"command","player","inventory","scoreboard","tag","log","web","nbt","build","review"}
R15_AI_SKILL_SET={}
for _,id in ipairs(R15_AI_SKILL_IDS) do R15_AI_SKILL_SET[id]=true end

function r15_prompt_candidates(kind,id)
    local out,seen={},{}
    local function add(p) p=tostring(p or ""); if p~="" and not seen[p] then seen[p]=true; out[#out+1]=p end end
    local dd=""; pcall(function() dd=tostring(game.dataDir() or "") end)
    local cd=""; pcall(function() cd=tostring(plugin_code_dir() or "") end)
    local base=""; pcall(function() base=tostring(plugin_base_dir() or "") end)
    local pid=""; pcall(function() pid=tostring(plugin_id_now() or "ds_ai_agent") end)
    if kind=="core" or kind=="capabilities" then
        local fn=(kind=="core") and "core.txt" or "capabilities.txt"
        add(dd.."/ai_prompts/"..fn); add(dd.."/"..fn)
        add(cd.."/ai_prompts/"..fn); add(cd.."/"..fn)
        if base~="" and pid~="" then add(base.."/插件文件/"..pid.."/ai_prompts/"..fn); add(base.."/插件文件/"..pid.."/"..fn) end
    elseif kind=="skill" then
        local fn=tostring(id)..".txt"
        add(dd.."/ai_prompts/skills/"..fn); add(dd.."/ai_skills/"..fn)
        add(cd.."/ai_prompts/skills/"..fn); add(cd.."/ai_skills/"..fn)
        if base~="" and pid~="" then add(base.."/插件文件/"..pid.."/ai_prompts/skills/"..fn); add(base.."/插件文件/"..pid.."/ai_skills/"..fn) end
    end
    return out
end

function r15_prompt_valid(kind,id,txt)
    txt=tostring(txt or "")
    if kind=="core" then return #txt>=180 and txt:find("LOAD_SUB_PROMPT",1,true)~=nil end
    if kind=="capabilities" then return #txt>=220 and txt:find("LOAD_SUB_PROMPT",1,true)~=nil and txt:find("command",1,true)~=nil end
    if kind=="skill" then
        if #txt<100 then return false end
        local must={command="[CMD]",player="[GETINFO]",inventory="[GETINVENTORY]",scoreboard="[GETSCORE]",tag="[GETTAG]",log="[LOG]",web="[SEARCH_WEB]",nbt="[NBT]",build="[BUILD]",review="真实"}
        local token=must[id]
        return token==nil or txt:find(token,1,true)~=nil
    end
    return false
end

function r15_read_prompt(kind,id)
    local fallback=(kind=="core" and R15_AI_DEFAULT_CORE) or (kind=="capabilities" and R15_AI_DEFAULT_CAPABILITIES) or (kind=="skill" and R15_AI_DEFAULT_SKILLS[id]) or ""
    for _,p in ipairs(r15_prompt_candidates(kind,id)) do
        local ok,v=pcall(util.read_file,p)
        if ok and type(v)=="string" and r15_prompt_valid(kind,id,v) then return v,p,false end
    end
    return tostring(fallback or ""),"builtin",true
end

function r15_write_default_if_missing(kind,id,txt)
    local list=r15_prompt_candidates(kind,id)
    local target=list[1]
    if not target or target=="" then return false end
    local ok,v=pcall(util.read_file,target)
    if ok and type(v)=="string" and r15_prompt_valid(kind,id,v) then return true end
    return pcall(util.write_file,target,tostring(txt or ""))
end

function r15_ensure_prompt_files()
    r15_write_default_if_missing("core",nil,R15_AI_DEFAULT_CORE)
    r15_write_default_if_missing("capabilities",nil,R15_AI_DEFAULT_CAPABILITIES)
    for _,id in ipairs(R15_AI_SKILL_IDS) do r15_write_default_if_missing("skill",id,R15_AI_DEFAULT_SKILLS[id]) end
    return true
end

function r15_skill_signature(id)
    local txt=r15_read_prompt("skill",id)
    local acc=0
    for i=1,#txt do acc=(acc + string.byte(txt,i)*((i%97)+1)) % 2147483647 end
    return tostring(#txt)..":"..tostring(acc)
end

function r15_skill_memory_load()
    local ok,d=pcall(util.json_load,R15_AI_SKILL_MEMORY_FILE)
    if ok and type(d)=="table" then d.schema=R15_AI_SCHEMA; d.players=d.players or {}; return d end
    return {schema=R15_AI_SCHEMA,players={}}
end
function r15_skill_memory_save(d) return pcall(util.json_write,R15_AI_SKILL_MEMORY_FILE,d or {schema=R15_AI_SCHEMA,players={}}) end
function r15_skill_player_key(name) return lower(trim(tostring(name or "unknown"))) end
function r15_skill_memory_record(name,id)
    if not R15_AI_SKILL_SET[id] then return false end
    local d=r15_skill_memory_load(); local key=r15_skill_player_key(name); d.players[key]=d.players[key] or {}
    d.players[key][id]={signature=r15_skill_signature(id),loaded_at=util.timestamp(),summary=R15_AI_SKILL_SUMMARY[id] or id}
    r15_skill_memory_save(d); return true
end
function r15_skill_memory_valid(name,id)
    if not R15_AI_SKILL_SET[id] then return false end
    local d=r15_skill_memory_load(); local p=d.players[r15_skill_player_key(name)] or {}; local rec=p[id]
    return type(rec)=="table" and tostring(rec.signature or "")==r15_skill_signature(id)
end
function r15_skill_memory_summary(name)
    local d=r15_skill_memory_load(); local p=d.players[r15_skill_player_key(name)] or {}; local out={}
    for _,id in ipairs(R15_AI_SKILL_IDS) do
        local rec=p[id]
        if type(rec)=="table" and tostring(rec.signature or "")~="" then out[#out+1]="- "..tostring(rec.summary or R15_AI_SKILL_SUMMARY[id] or id) end
    end
    return table.concat(out,"\n")
end

local _r15_prev_seg_alias=ai_seg_id_from_load_name
function ai_seg_id_from_load_name(name)
    local n=lower(trim(tostring(name or ""))):gsub("%s+","")
    local aliases={
        command="command",cmd="command",["指令"]="command",["命令"]="command",
        player="player",["玩家"]="player",info="player",
        inventory="inventory",bag="inventory",["背包"]="inventory",
        scoreboard="scoreboard",score="scoreboard",["记分板"]="scoreboard",["分数"]="scoreboard",
        tag="tag",["标签"]="tag",log="log",["日志"]="log",web="web",net="web",["联网"]="web",
        nbt="nbt",build="build",["建筑"]="build",review="review",["审查"]="review",["举报"]="review"
    }
    if aliases[n] then return aliases[n] end
    if type(_r15_prev_seg_alias)=="function" then return _r15_prev_seg_alias(name) end
    return nil
end
function ai_seg_canonical(name) return ai_seg_id_from_load_name(name) or "" end

local _r15_prev_seg_load=ai_seg_load
function ai_seg_load(name,force)
    local id=ai_seg_canonical(name)
    if R15_AI_SKILL_SET[id] then local txt=r15_read_prompt("skill",id); return txt end
    if type(_r15_prev_seg_load)=="function" then return _r15_prev_seg_load(name,force) end
    return ""
end

function build_ai_system(q,admin)
    local core,core_src,core_fallback=r15_read_prompt("core")
    local caps,caps_src,caps_fallback=r15_read_prompt("capabilities")
    local learned=r15_skill_memory_summary(_CUR_AI_PLAYER)
    local extra="\n\n【运行时说明】\n- 当前插件："..FINAL_PATCH_VERSION.."。\n- 具体游戏/协议版本不硬编码，以真实服务器能力为准。\n- 提示词文件若意外被截断或缺少关键调用标记，会自动使用内置完整兜底，避免 AI 因残缺 TXT 失去执行器说明。"
    if learned~="" then extra=extra.."\n\n【已掌握技能摘要｜无需重复加载全文】\n"..learned end
    return "【常驻核心】\n"..core.."\n\n"..caps..extra,{"core","capabilities"}
end

function auto_prompt_ids_from_tools(tool_text)
    local s=tostring(tool_text or ""); local ids,seen={},{}
    local map={CMD="command",SHELL4="command",LIST="player",GETINFO="player",SHELL3="player",GETINVENTORY="inventory",GETSCORE="scoreboard",GETTAG="tag",LOG="log",NET="web",SEARCH_WEB="web",NBT="nbt",BUILD="build",BUILD_STOP="build",BUILD_OFF="build"}
    for tag,id in pairs(map) do
        if s:find("["..tag.."]",1,true) and not seen[id] then
            if id~="build" or is_admin(_CUR_AI_PLAYER) then seen[id]=true; ids[#ids+1]=id end
        end
    end
    return ids
end

function task_prompt_load_set(messages,active,ids)
    local loaded={}
    active=active or {}
    for _,rawid in ipairs(ids or {}) do
        local id=ai_seg_canonical(rawid)
        if id~="" and not active[id] then
            if R15_AI_SKILL_SET[id] and r15_skill_memory_valid(_CUR_AI_PLAYER,id) then
                active[id]=true
                loaded[#loaded+1]=id.."(已记忆)"
            elseif task_prompt_append(messages,id) then
                active[id]=true
                if R15_AI_SKILL_SET[id] then r15_skill_memory_record(_CUR_AI_PLAYER,id) end
                loaded[#loaded+1]=id
            end
        end
    end
    return loaded
end

function ai_skill_status(name)
    local lines={"AI技能状态："}
    for _,id in ipairs(R15_AI_SKILL_IDS) do
        local txt,src,fb=r15_read_prompt("skill",id)
        lines[#lines+1]=string.format("%s → %s / %d字 / %s",id,r15_skill_memory_valid(name,id) and "已记忆" or "未记忆",#txt,fb and "内置兜底" or src)
    end
    return table.concat(lines,"\n")
end

local _r15_prev_chat=on_chat
function on_chat(playerName,msg)
    local raw=trim(tostring(msg or "")); local low=lower(raw)
    if low==".ai技能" or low==".ai技能状态" then
        if not is_admin(playerName) then send(playerName,"§c仅管理员可查看AI技能状态。") return true end
        send(playerName,ai_skill_status(playerName)); return true
    end
    return _r15_prev_chat(playerName,msg)
end

local _r15_prev_backup=self_backup_now
function self_backup_now(name)
    local ret=true
    if type(_r15_prev_backup)=="function" then ret=_r15_prev_backup(name) end
    if not is_admin(name) then return ret end
    local dd=game.dataDir(); local code=plugin_code_dir(); local stamp=os.date("!%Y%m%d_%H%M%S",util.timestamp()+8*3600); local prefix=dd.."/self_backup_"..stamp.."_r15_"
    local files={{src=dd.."/ai_skill_memory.json",dst=prefix.."ai_skill_memory.json"},{src=dd.."/ai_prompts/core.txt",dst=prefix.."core.txt"},{src=dd.."/ai_prompts/capabilities.txt",dst=prefix.."capabilities.txt"}}
    for _,id in ipairs(R15_AI_SKILL_IDS) do files[#files+1]={src=dd.."/ai_prompts/skills/"..id..".txt",dst=prefix.."skill_"..id..".txt"} end
    for _,f in ipairs(files) do local ok,v=pcall(util.read_file,f.src); if ok and type(v)=="string" then pcall(util.write_file,f.dst,v) end end
    return ret
end

local _r15_prev_init=on_init
function on_init()
    local ret=nil
    if type(_r15_prev_init)=="function" then local ok,v=pcall(_r15_prev_init); if ok then ret=v end end
    pcall(r15_ensure_prompt_files)
    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    return ret
end



