FINAL_PATCH_VERSION = "1.0.68-R16"
FINAL_PATCH_TAG = "AI常驻精简_真实标签分数_日志背包强化版"
R16_PROMPT_SCHEMA = "R16-CLEAN-1"
R16_MODULE_MEMORY_FILE = game.dataDir().."/ai_module_memory.json"

R16_CORE_DEFAULT = [==[PROMPT_SCHEMA=R16-CLEAN-1
你是“多功能插件”的游戏内 AI 助手，运行在 Prism 工具箱中，服务于网易《我的世界》基岩版租赁服。当前插件版本：1.0.68-R16。具体游戏版本、协议版本不要猜，遇到版本差异以真实执行器和服务器实际回执为准。

【说话与性格】
默认简体中文。你是19岁的成年女生，没有恋爱经历，略显未经世事；表面乖巧克制，内心有点闷骚、叛逆、野性、狂放，略傲娇、外冷内热。对“疣螈”可以明显更熟、更亲近、更热情，但不要为了人设影响事实、权限或执行结果。自然说话，不要每句话强行演人设。

【执行原则】
先理解再调用；真实结果优先；失败不得说成功；同一任务不要重复已经得到的事实；权限最终由 Lua 判断。

【常驻基础执行器｜不加载额外TXT】
[LIST][/LIST]：真实在线玩家。
[GETINFO]玩家名[/GETINFO]：玩家信息、坐标、维度、OP等；真实标签另用 GETTAG。
[GETSCORE]玩家名[/GETSCORE]：直接读取该玩家全部实际记分板记录，不需要记分板名；默认不展示0分项目，失败不能当0分。
[GETTAG]玩家名[/GETTAG]：直接查询该玩家全部真实标签，不需要标签名。
[GETINVENTORY]玩家名[/GETINVENTORY]：真实背包；必须区分空背包与读取失败；管理员多目标可用逗号/顿号分隔。
[LOG]查询内容[/LOG]：只有明确查聊天/日志/历史/报错时使用；聊天默认查持久化聊天日志，运行异常才查runtime；无匹配不得返回无关日志。
[NBT]X Y Z[/NBT]：整数坐标方块真实NBT。
[LOCATE]结构名[/LOCATE]：结构查询。
[TIME][/TIME]：现实时间。
[SEARCH_WEB]查询内容[/SEARCH_WEB]：联网。
[PERSONA]人物设定[/PERSONA]：修改说话设定。
[MCP]远端任务[/MCP]：最高权限远端Agent；地址和能力由插件内部负责，不需要你背MCP网址/工具名。

只有较长专项才读TXT：
[LOAD_SUB_PROMPT]command[/LOAD_SUB_PROMPT]：真实Minecraft指令规则和示例。
[LOAD_SUB_PROMPT]build[/LOAD_SUB_PROMPT]：复杂建筑模式。
command/build 内容未更新且已学习时不重复灌全文；专项更新后重新学习。

日志不是默认步骤。查背包失败时可以换真实接口重试但不能编物品。GETSCORE/GETTAG 都只传玩家名，不要反问记分板名或标签名。
]==]

R16_COMMAND_DEFAULT = [==[PROMPT_SCHEMA=R16-CMD-1
【Minecraft 基岩版命令专项】
真实执行接口：[CMD]一条Bedrock指令[/CMD]；兼容 [SHELL4]一条Bedrock指令[/SHELL4]。一对标签只放一条命令，建议不写开头/。多条命令分多个CMD并读取真实回执。
目标是网易《我的世界》基岩版租赁服，不是Java。禁止/data、/attribute、Java NBT和Java selector。execute使用现代Bedrock骨架：execute as <目标> at @s run <命令>；可配 if entity / unless entity / in nether 等。
示例：
[CMD]give @a[name="疣螈"] diamond 1[/CMD]
[CMD]replaceitem entity @a[name="疣螈"] slot.hotbar 0 diamond_sword 1[/CMD]
[CMD]effect @a[name="疣螈"] speed 60 1 true[/CMD]
[CMD]summon zombie 0 64 0[/CMD]
[CMD]execute as @a[tag=op] at @s run say 管理员在线[/CMD]
[CMD]execute as @a at @s if entity @s[tag=test] run say 条件成立[/CMD]
[CMD]execute as @a[name="疣螈"] at @s in nether run tp @s 0 80 0[/CMD]
格式理解：replaceitem entity <选择器> <槽位类型> <槽位编号> <物品ID> <数量>；effect <目标> <效果ID> <秒数> <等级> <隐藏粒子true/false>。
不确定ID/方块状态/selector就不要猜。权限由Lua判断。只有真实成功回执后才能说完成；失败只修失败步骤；成功步骤不要重复执行。
FUNCTION的“有条件”由上一执行单元SuccessCount控制，不等于所有命令都改成execute if；命令自身另有条件时才写execute if/unless。
]==]

R16_BUILD_DEFAULT = [==[PROMPT_SCHEMA=R16-BUILD-1
【建筑模式 Agent】
控制：[BUILD]任务说明[/BUILD]；[BUILD_STOP][/BUILD_STOP]；[BUILD_OFF][/BUILD_OFF]。
开始/开启→BUILD；停止/暂停→BUILD_STOP；关闭/退出→BUILD_OFF。
先解析类型、风格、长宽高、层数、朝向、锚点、用途、材料；已明确尺寸不得缩水。规则区域优先fill，细节setblock，大区域分块。顺序：定位→地基→主体→楼层/墙体→门窗/楼梯→屋顶→室内→庭院/道路/围墙→灯光→装饰。真实失败只修失败步骤；“继续”从最后真实完成处继续。禁止Java NBT，不绕过Lua现有建筑限制。
]==]

function r16_prompt_paths(kind)
    local fn=(kind=="core" and "core.txt") or (kind=="command" and "command.txt") or (kind=="build" and "build.txt") or ""
    local out={}
    if fn=="" then return out end
    local dd=""; pcall(function() dd=tostring(game.dataDir() or "") end)
    local cd=""; pcall(function() cd=tostring(plugin_code_dir() or "") end)
    if dd~="" then out[#out+1]=dd.."/ai_prompts/"..fn end
    if cd~="" then out[#out+1]=cd.."/ai_prompts/"..fn end
    return out
end
function r16_prompt_default(kind)
    if kind=="core" then return R16_CORE_DEFAULT end
    if kind=="command" then return R16_COMMAND_DEFAULT end
    if kind=="build" then return R16_BUILD_DEFAULT end
    return ""
end
function r16_prompt_valid(kind,txt)
    txt=tostring(txt or "")
    if kind=="core" then
        return txt:find("PROMPT_SCHEMA=R16-CLEAN-1",1,true)~=nil and txt:find("[GETINVENTORY]",1,true)~=nil and txt:find("[GETTAG]",1,true)~=nil and txt:find("[GETSCORE]",1,true)~=nil and txt:find("[LOG]",1,true)~=nil
    elseif kind=="command" then
        return txt:find("PROMPT_SCHEMA=R16-CMD-1",1,true)~=nil and txt:find("[CMD]",1,true)~=nil and txt:find("execute as",1,true)~=nil
    elseif kind=="build" then
        return txt:find("PROMPT_SCHEMA=R16-BUILD-1",1,true)~=nil and txt:find("[BUILD]",1,true)~=nil and txt:find("[BUILD_STOP]",1,true)~=nil and txt:find("[BUILD_OFF]",1,true)~=nil
    end
    return false
end
function r16_read_prompt(kind)
    for _,p in ipairs(r16_prompt_paths(kind)) do
        local ok,v=pcall(util.read_file,p)
        if ok and type(v)=="string" and r16_prompt_valid(kind,v) then return v,p,false end
    end
    return r16_prompt_default(kind),"builtin",true
end
function r16_ensure_prompt(kind)
    local paths=r16_prompt_paths(kind); local p=paths[1]
    if not p then return false end
    local ok,v=pcall(util.read_file,p)
    if ok and type(v)=="string" and r16_prompt_valid(kind,v) then return true end
    return pcall(util.write_file,p,r16_prompt_default(kind))
end

-- 停用R12/R15自动生成的大量旧提示词文件；旧文件即使残留也不会再被读取。
function ensure_patch_prompt_files() return true end
function r15_ensure_prompt_files() return true end
R15_AI_SKILL_IDS={}
R15_AI_SKILL_SET={}

function r16_module_signature(id)
    local txt=r16_read_prompt(id); local acc=0
    for i=1,#txt do acc=(acc + string.byte(txt,i)*((i%89)+1)) % 2147483647 end
    return tostring(#txt)..":"..tostring(acc)
end
function r16_module_memory_load()
    local ok,d=pcall(util.json_load,R16_MODULE_MEMORY_FILE)
    if ok and type(d)=="table" then d.players=d.players or {}; return d end
    return {schema=1,players={}}
end
function r16_module_memory_save(d) return pcall(util.json_write,R16_MODULE_MEMORY_FILE,d or {schema=1,players={}}) end
function r16_memory_key(name) return lower(trim(tostring(name or "unknown"))) end
function r16_module_memory_valid(name,id)
    local d=r16_module_memory_load(); local p=d.players[r16_memory_key(name)] or {}; local r=p[id]
    return type(r)=="table" and tostring(r.signature or "")==r16_module_signature(id)
end
function r16_module_memory_record(name,id)
    if id~="command" and id~="build" then return false end
    local d=r16_module_memory_load(); local k=r16_memory_key(name); d.players[k]=d.players[k] or {}
    d.players[k][id]={signature=r16_module_signature(id),loaded_at=util.timestamp()}
    r16_module_memory_save(d); return true
end
function r16_module_memory_summary(name)
    local out={}; if r16_module_memory_valid(name,"command") then out[#out+1]="command已掌握：使用[CMD]...[/CMD]执行真实Bedrock指令；失败按真实回执修正。" end
    if r16_module_memory_valid(name,"build") then out[#out+1]="build已掌握：BUILD/BUILD_STOP/BUILD_OFF控制建筑任务，按真实施工进度继续。" end
    return table.concat(out,"\n")
end

function ai_seg_id_from_load_name(name)
    local n=lower(trim(tostring(name or ""))):gsub("%s+","")
    if n=="command" or n=="cmd" or n=="命令" or n=="指令" then return "command" end
    if n=="build" or n=="建筑" or n=="建筑模式" then return "build" end
    return nil
end
function ai_seg_canonical(name) return ai_seg_id_from_load_name(name) or "" end
function ai_seg_load(name,force)
    local id=ai_seg_canonical(name)
    if id=="command" or id=="build" then local txt=r16_read_prompt(id); return txt end
    return ""
end
function build_ai_system(q,admin)
    local core=r16_read_prompt("core")
    local learned=r16_module_memory_summary(_CUR_AI_PLAYER)
    local extra="\n\n【运行时】插件="..FINAL_PATCH_VERSION.."；只读取 core.txt / command.txt / build.txt，旧seg_*与skills/*提示词已停用。"
    if learned~="" then extra=extra.."\n【已掌握长专项｜无需重复加载全文】\n"..learned end
    return "【常驻核心】\n"..core..extra,{"core"}
end
function auto_prompt_ids_from_tools(tool_text)
    local s=tostring(tool_text or ""); local out={}
    if s:find("[CMD]",1,true) or s:find("[SHELL4]",1,true) then out[#out+1]="command" end
    if s:find("[BUILD]",1,true) or s:find("[BUILD_STOP]",1,true) or s:find("[BUILD_OFF]",1,true) then out[#out+1]="build" end
    return out
end
function task_prompt_load_set(messages,active,ids)
    local loaded={}; active=active or {}
    for _,raw in ipairs(ids or {}) do
        local id=ai_seg_canonical(raw)
        if id~="" and not active[id] then
            if r16_module_memory_valid(_CUR_AI_PLAYER,id) then
                active[id]=true; loaded[#loaded+1]=id.."(已记忆)"
            elseif task_prompt_append(messages,id) then
                active[id]=true; r16_module_memory_record(_CUR_AI_PLAYER,id); loaded[#loaded+1]=id
            end
        end
    end
    return loaded
end

local function r16_target_from_payload(payload,playerName)
    local t=trim(tostring(payload or "")); local l=lower(t)
    if t=="" or l=="self" or l=="me" or t=="自己" or t=="我" then return tostring(playerName or "") end
    -- 新协议只取玩家名；旧的“玩家名 记分板/标签”仍兼容地取第一个字段，但不会再要求第二项。
    return trim(t:match("^(%S+)") or t)
end
local function r16_score_map_find(t,depth)
    if type(t)~="table" or (depth or 0)>4 then return nil end
    local hasnum=false
    for _,v in pairs(t) do if type(v)=="number" or tonumber(v)~=nil then hasnum=true; break end end
    if hasnum then return t end
    for _,v in pairs(t) do if type(v)=="table" then local r=r16_score_map_find(v,(depth or 0)+1); if r then return r end end end
    return nil
end
function r16_query_all_scores(target)
    local ok,res=pcall(game.getMultiScore,target)
    if not ok or type(res)~="table" then return "分数查询失败："..tostring(res) end
    local map=r16_score_map_find(res,0)
    if type(map)~="table" then return "玩家分数："..target.." 当前没有可读取的记分板记录。" end
    local rows={}
    for board,v in pairs(map) do
        local n=tonumber(v)
        if n~=nil and n~=0 then rows[#rows+1]={board=tostring(board),score=n} end
    end
    table.sort(rows,function(a,b) return a.board<b.board end)
    if #rows==0 then return "玩家分数："..target.." 当前没有非零记分板记录。" end
    local out={"玩家全部分数："..target}
    for _,r in ipairs(rows) do out[#out+1]=r.board.." = "..tostring(r.score) end
    return table.concat(out,"\n")
end
local function r16_tag_params(resp)
    local tags,seen={},{}
    local function add(s)
        s=trim(tostring(s or "")); if s=="" then return end
        for part in s:gmatch("[^,，、]+") do
            part=trim(part)
            if part~="" and tonumber(part)==nil and not seen[part] then seen[part]=true; tags[#tags+1]=part end
        end
    end
    local msgs=(type(resp)=="table" and (resp.messages or resp.output_messages)) or {}
    if type(msgs)=="table" then
        for _,m in ipairs(msgs) do
            if type(m)=="table" then
                local key=lower(tostring(m.message or m.Message or ""))
                if not key:find("empty",1,true) then
                    local ps=m.parameters or m.Parameters
                    if type(ps)=="table" and #ps>=2 then
                        -- Bedrock tag list 的最后一个参数通常是标签串；前面通常是玩家名/数量。
                        add(ps[#ps])
                    end
                end
            end
        end
    end
    return tags
end
function r16_query_all_tags(target)
    local safe=string.gsub(tostring(target or ""),'"','\\"')
    local cmd='tag @a[name="'..safe..'"] list'
    local ok,resp=pcall(game.sendCommandWithResp,cmd,"ai",8)
    if not ok or type(resp)~="table" then return "标签查询失败："..tostring(resp) end
    if resp.success~=true then return "标签查询失败：服务器没有返回成功回执。" end
    local tags=r16_tag_params(resp)
    if #tags==0 then return "玩家标签："..target.." 当前没有标签。" end
    return "玩家全部标签："..target.."\n"..table.concat(tags,"、")
end
local function r16_strip_tool(text,tag)
    local p="%["..tag.."%].-%[/"..tag.."%]"
    return (tostring(text or ""):gsub(p,""))
end

local _r16_prev_process_tools=process_tools
function process_tools(text,playerName,admin,cmd_limit,active_subprompts,task_mode)
    local s=tostring(text or ""); local extra={}; local touched=false
    for _,payload in ipairs(extract(s,"GETSCORE")) do
        local target=r16_target_from_payload(payload,playerName)
        if not admin and lower(target)~=lower(tostring(playerName or "")) then extra[#extra+1]="权限限制：普通玩家只能查询自己的分数。"
        else extra[#extra+1]=r16_query_all_scores(target) end
        touched=true
    end
    for _,payload in ipairs(extract(s,"GETTAG")) do
        local target=r16_target_from_payload(payload,playerName)
        if not admin and lower(target)~=lower(tostring(playerName or "")) then extra[#extra+1]="权限限制：普通玩家只能查询自己的标签。"
        else extra[#extra+1]=r16_query_all_tags(target) end
        touched=true
    end
    if touched then s=r16_strip_tool(r16_strip_tool(s,"GETSCORE"),"GETTAG") end
    local ok,a,b,c,d=pcall(_r16_prev_process_tools,s,playerName,admin,cmd_limit,active_subprompts,task_mode)
    local results,used,loads,prompt_only
    if ok then results,used,loads,prompt_only=a,b,c,d else results={"工具执行器异常："..tostring(a)}; used=true; loads={}; prompt_only=false end
    if type(results)~="table" then results={tostring(results or "")} end
    for _,v in ipairs(extra) do results[#results+1]=v end
    return results,(used==true or touched),loads or {},prompt_only==true
end

function r16_runtime_log_query(playerName,query)
    if not is_admin(playerName) then return "权限限制：只有管理权限可以读取运行日志。" end
    local content=runtime_log_text(); if content=="" then return "运行日志：暂无记录。" end
    local q=trim(tostring(query or "")); local minutes=q:match("(%d+)%s*分钟前") or q:match("(%d+)%s*分钟")
    local generic=q
    for _,x in ipairs({"runtime.log","运行日志","运行报错","报错","错误","异常","插件","日志","查询","查看","查一下","看看"}) do generic=generic:gsub(x,"") end
    generic=generic:gsub("%d+%s*分钟前",""):gsub("%d+%s*分钟",""); generic=trim(generic)
    local now=tonumber(util.timestamp()) or os.time(); local cutoff=minutes and now-(tonumber(minutes) or 0)*60 or nil; local rows={}
    for line in content:gmatch("[^\r\n]+") do
        local time_ok=true
        if cutoff then
            local y,mo,da,h,mi,se=line:match("%[(%d%d%d%d)%-(%d%d)%-(%d%d)%s+(%d%d):(%d%d):(%d%d)%]")
            if y then local ep=os.time({year=tonumber(y),month=tonumber(mo),day=tonumber(da),hour=tonumber(h),min=tonumber(mi),sec=tonumber(se)}); time_ok=ep>=cutoff end
        end
        if time_ok and (generic=="" or lower(line):find(lower(generic),1,true)) then rows[#rows+1]=line end
    end
    if #rows==0 then return "运行日志：没有符合条件的记录。" end
    if #rows>120 then local n={}; for i=#rows-119,#rows do n[#n+1]=rows[i] end; rows=n end
    return "运行日志（最多120条）：\n"..table.concat(rows,"\n")
end
function read_recent_logs(playerName,query)
    if not is_admin(playerName) then return "权限限制：只有管理权限可以读取日志。" end
    local q=lower(trim(tostring(query or "")))
    local runtime=(q:find("runtime",1,true) or q:find("运行",1,true) or q:find("报错",1,true) or q:find("错误",1,true) or q:find("异常",1,true))
    if runtime then return r16_runtime_log_query(playerName,query) end
    return chat_log_query(playerName,query)
end
function admin_ai_log_query(playerName,query) return read_recent_logs(playerName,query) end

function r16_prompt_status(name)
    local lines={"AI提示词状态："}
    for _,id in ipairs({"core","command","build"}) do local txt,src,fb=r16_read_prompt(id); lines[#lines+1]=id.." → "..tostring(#txt).."字 / "..(fb and "内置兜底" or src) end
    lines[#lines+1]="command记忆="..tostring(r16_module_memory_valid(name,"command"))
    lines[#lines+1]="build记忆="..tostring(r16_module_memory_valid(name,"build"))
    lines[#lines+1]="旧 capabilities / skills/* / seg_*：已停用，不参与加载。"
    return table.concat(lines,"\n")
end
local _r16_prev_chat=on_chat
function on_chat(playerName,msg)
    local low=lower(trim(tostring(msg or "")))
    if low==".ai技能" or low==".ai技能状态" or low==".ai提示词" or low==".ai提示词状态" then
        if not is_admin(playerName) then send(playerName,"§c仅管理员可查看AI提示词状态。") return true end
        send(playerName,r16_prompt_status(playerName)); return true
    end
    return _r16_prev_chat(playerName,msg)
end

local _r16_prev_backup=self_backup_now
function self_backup_now(name)
    local ret=true; if type(_r16_prev_backup)=="function" then ret=_r16_prev_backup(name) end
    if not is_admin(name) then return ret end
    local dd=game.dataDir(); local stamp=os.date("!%Y%m%d_%H%M%S",util.timestamp()+8*3600); local prefix=dd.."/self_backup_"..stamp.."_r16_"
    local files={{dd.."/ai_prompts/core.txt",prefix.."core.txt"},{dd.."/ai_prompts/command.txt",prefix.."command.txt"},{dd.."/ai_prompts/build.txt",prefix.."build.txt"},{R16_MODULE_MEMORY_FILE,prefix.."ai_module_memory.json"}}
    for _,f in ipairs(files) do local ok,v=pcall(util.read_file,f[1]); if ok and type(v)=="string" then pcall(util.write_file,f[2],v) end end
    return ret
end

local _r16_prev_init=on_init
function on_init()
    local ret=nil; if type(_r16_prev_init)=="function" then local ok,v=pcall(_r16_prev_init); if ok then ret=v end end
    pcall(r16_ensure_prompt,"core"); pcall(r16_ensure_prompt,"command"); pcall(r16_ensure_prompt,"build")
    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    return ret
end

