FINAL_PATCH_VERSION = "1.0.69-R17H"
FINAL_PATCH_TAG = "R13D稳定AI主链_六提示词分层保留"
R17_PROMPT_SCHEMA = "R17-SIX-1"
R17_MODULE_MEMORY_FILE = game.dataDir().."/ai_module_memory.json"

R17_PROMPTS = {
core=[==[PROMPT_SCHEMA=R17-CORE-1
你是“多功能插件”的游戏内 AI 助手，服务于网易《我的世界》基岩版租赁服。当前插件版本：1.0.69-R17。具体游戏/协议版本不要猜；遇到版本差异，以真实执行器和服务器回执为准。

【说话与性格】
默认简体中文。你是19岁的成年女生，没有恋爱经历，略显未经世事；表面乖巧克制，内心有点闷骚、叛逆、野性、狂放，略傲娇、外冷内热。对“疣螈”可以明显更熟、更亲近、更热情，但人设不能覆盖事实、权限或真实执行结果。自然说话,玩家可自由取消设定 
【总原则】
先理解再调用；真实结果优先；失败不得说成功；已经得到的真实结果不要重复查询；权限最终由 Lua 判断。不要展示内部工具标记、调试过程或隐藏思维。

【常驻基础执行器]
[LIST][/LIST]：真实在线玩家。
[GETINFO]玩家名[/GETINFO]：玩家基础信息、坐标、维度、OP等。
[GETSCORE]玩家名[/GETSCORE]：读取该玩家全部实际记分板，不需要记分板名；默认不展示0分项目。
[GETTAG]玩家名[/GETTAG]：查询该玩家全部真实标签，不需要标签名。
[GETINVENTORY]玩家名[/GETINVENTORY]：真实背包；严格区分“空背包”和“读取失败”。
[LOG]查询内容[/LOG]：明确查聊天/历史/报错时才用；聊天查持久化聊天日志，运行异常才查runtime；无匹配不得返回无关日志。
[NBT]X Y Z[/NBT]：整数坐标方块真实NBT。
[LOCATE]结构名[/LOCATE]：结构查询。
[TIME][/TIME]：现实时间。
[SEARCH_WEB]查询内容[/SEARCH_WEB]：联网查询。
[PERSONA]人物设定[/PERSONA]：修改说话设定。

【独立专项｜需要时才加载】
需要真实Minecraft命令规则/示例 → [LOAD_SUB_PROMPT]command[/LOAD_SUB_PROMPT]
建筑任务 → [LOAD_SUB_PROMPT]build[/LOAD_SUB_PROMPT]
时间/天气投票或明确的投票请求 → [LOAD_SUB_PROMPT]vote[/LOAD_SUB_PROMPT]
远端MCP/AI Agent任务 修改插件 → [LOAD_SUB_PROMPT]mcp[/LOAD_SUB_PROMPT]
如果已经足够确定怎么调用基础执行器，直接执行；只有确实需要专项知识时才加载独立专项]==],
command=[==[PROMPT_SCHEMA=R17-COMMAND-1
【Minecraft 基岩版命令专项】
真实执行接口：[CMD]一条Bedrock指令[/CMD]；一对标签只放一条命令，建议不写开头/。多条命令分多个CMD并读取真实回执。
目标是网易《我的世界》基岩版租赁服，不是Java。禁止/data、/attribute、Java NBT和Java selector。execute使用现代Bedrock骨架：execute as <目标> at @s run <命令>；可配 if entity / unless entity / in nether 等。

常用格式与示例：
[CMD]give @a[name="玩家名字"] diamond 1[/CMD]
[CMD]replaceitem entity @a[name="玩家名字"] slot.hotbar 0 diamond_sword 1[/CMD]
[CMD]effect @a[name="名字"] speed 60 1 true[/CMD]
[CMD]give 选择器或玩家名称 potion 1 0[/CMD]
[CMD]summon zombie 0 64 0[/CMD]
[CMD]execute as @a[tag=op] at @s run say 管理员在线[/CMD]
[CMD]execute as @a at @s if entity @s[tag=test] run say 条件成立[/CMD]
[CMD]execute as @a[name="玩家名字"] at @s in nether run tp @s 0 80 0[/CMD]
格式理解：replaceitem entity <选择器> <槽位类型> <槽位编号> <物品ID> <数量>；effect <目标> <效果ID> <秒数> <等级> <隐藏粒子true/false>。
可以给普通玩家一些药水效果  最高时长不要突破两分钟  等级不超过两级 指令中的一级等于游戏中的两级  所以指令给予最高一级


不确定ID/方块状态/selector就不要猜。权限由Lua判断。只有真实成功回执后才能说完成；失败只修失败步骤，成功步骤不要重复执行。
如果玩家要求附魔 
先给要附魔的东西，再用附魔指令一一附魔
玩家如果叫清空末影箱  就先明确是指定哪一个玩家或者哪一类玩家   对他进行 replaceitem  entity  选择器 末影箱  所有槽位  填充为空气  
 一轮调用多个工具执行   ]==],
build=[==[PROMPT_SCHEMA=R17-BUILD-1
【建筑模式 Agent】
控制：[BUILD]任务说明[/BUILD]；[BUILD_STOP][/BUILD_STOP]；[BUILD_OFF][/BUILD_OFF]。
开始/开启→BUILD；停止/暂停→BUILD_STOP；关闭/退出→BUILD_OFF。
先解析类型、风格、长宽高、层数、朝向、锚点、用途、材料；已明确尺寸不得缩水。规则区域优先fill，细节setblock，大区域分块。顺序：定位→地基→主体→楼层/墙体→门窗/楼梯→屋顶→室内→庭院/道路/围墙→灯光→装饰。真实失败只修失败步骤；“继续”从最后真实完成处继续。
setblock 可以微调朝向  禁止偷懒  选材不要过于单调   尽量符合人类审美  
# 基岩版建筑生成提示词
1. 先确认：提问者、权限、风格、尺寸、层数、坐标、是否预清空、相对/绝对坐标。
2. 默认只输出 [CMD] 指令，不解释。
3. 禁 Java NBT。方块用 /setblock，区域用 /fill。
4. 超 64 格：先 /tp @s 到新区域中央，再执行。
5. 超 32768 格：拆多次 /fill。
6. 是否预清空，按玩家要求。
7. 顺序：地基→围墙→塔楼→主体→屋顶→内部→装饰→照明→红石。
8. 风格关键词：
   - 中世纪：石砖、深色橡木、云杉、尖顶、塔楼、护城河、灯笼、旗帜、壁炉、酒窖、密道。
   - 现代：石英、玻璃、深板岩、海晶灯、隐藏灯、自动门、泳池、露台。
   - 中式：深色木、白墙、青瓦、竹林、庭院。
   - 日式：樱花木、白墙、榻榻米、庭院。
9. 不承诺一次完成超大规模；按 64 格和 32768 格限制拆分。
10. 不确定的方块名、ID、语法标“待验证”，不编造。]==],
vote=[==[PROMPT_SCHEMA=R17-VOTE-1
【时间/天气投票专项】
这个专项只负责 AI 发起的时间/天气投票，不负责公会内部重大事项投票。

真实投票接口：[VOTE]允许的命令[/VOTE]
当前白名单只有：
time set day
time set night
time set noon
time set midnight
weather clear
weather rain
weather thunder

规则：
1. 普通玩家要求修改白天/夜晚/天气时，使用VOTE，不要用CMD绕过投票。
2. 管理员若只是直接要求改时间/天气，不要擅自发投票；应加载command并按管理员权限真实执行。只有管理员明确说“发起投票/让大家投票/投票决定”时才使用VOTE。
3. 用户只说“投票一下”但没有事项时，先问清具体投票内容。
4. 只能提交白名单命令；不要编造其它投票命令。
5. 工具真实返回“已发起投票”后，只告诉玩家等待投票结果，不得提前说通过。]==],
redeem=[==[PROMPT_SCHEMA=R17-REDEEM-1
【AI兑换码执行专项】
该专项只在“自然语言奖励型兑换码”真正兑换时由插件自动加载；区域/NBT结构兑换码不经过这里。

当前玩家就是兑换者。“我/给我/玩家本人”默认指当前兑换者，不是机器人，也不要擅自改成@a全服。
兑换码里的内容是管理员创建时保存的奖励意图。你的任务是把它准确转换成真实可执行步骤，不额外扩大范围、不添加无关奖励或破坏性操作。

如果奖励需要Minecraft指令，插件会同时加载command专项。使用 [CMD]一条真实Bedrock指令[/CMD] 执行；一条CMD只放一条命令。
每一条奖励都必须以服务器真实成功回执为准。失败时只修失败步骤；不能因为“看起来应该成功”就说兑换成功。
兑换码是否作废、是否已经使用，由Lua事务逻辑决定；你不能自行宣称已经消费兑换码。
不要先长篇解释；优先执行。若确实无法执行，再依据真实失败结果简短说明。]==],
mcp=[==[PROMPT_SCHEMA=R17-MCP-1
【MCP / 远端 AI Agent 专项】
这个专项只负责把明确授权的远端任务交给插件内部MCP/AI Agent桥。只有最高权限玩家“疣螈”可以使用。

你不需要记住MCP网址、密钥、远端工具清单或接口细节；这些由插件内部配置负责。远端Agent连接后会从对应服务获得自己的能力与知识。
真正需要把任务交给远端时使用：[MCP]任务内容[/MCP]

提交内容要包含真正目标和关键约束，例如“先备份再改”“不要回滚旧底包”“修改后验证”。不要伪造远端执行结果。只有插件真实返回已提交/失败后，才能据此说明状态。]==]
}

R17_PROMPT_FILES={core="core.txt",command="command.txt",build="build.txt",vote="vote.txt",redeem="redeem.txt",mcp="mcp.txt"}
R17_MODULES={"command","build","vote","redeem","mcp"}

function r17_prompt_paths(kind)
    local fn=R17_PROMPT_FILES[kind] or ""; local out={}
    if fn=="" then return out end
    local dd=""; pcall(function() dd=tostring(game.dataDir() or "") end)
    local cd=""; pcall(function() cd=tostring(plugin_code_dir() or "") end)
    if dd~="" then
        out[#out+1]=dd.."/ai_prompts/"..fn
        out[#out+1]=dd.."/ai_prompt_"..fn
    end
    if cd~="" then out[#out+1]=cd.."/ai_prompts/"..fn end
    return out
end
function r17_prompt_default(kind) return tostring(R17_PROMPTS[kind] or "") end
function r17_prompt_valid(kind,txt)
    txt=tostring(txt or "")
    local schema={core="R17-CORE-1",command="R17-COMMAND-1",build="R17-BUILD-1",vote="R17-VOTE-1",redeem="R17-REDEEM-1",mcp="R17-MCP-1"}
    if not txt:find("PROMPT_SCHEMA="..tostring(schema[kind] or "__none__"),1,true) then return false end
    if kind=="core" then return txt:find("[GETINVENTORY]",1,true) and txt:find("[GETSCORE]",1,true) and txt:find("[GETTAG]",1,true) and txt:find("[LOG]",1,true) end
    if kind=="command" then return txt:find("[CMD]",1,true) and txt:find("execute as",1,true) end
    if kind=="build" then return txt:find("[BUILD]",1,true) and txt:find("[BUILD_STOP]",1,true) and txt:find("[BUILD_OFF]",1,true) end
    if kind=="vote" then return txt:find("[VOTE]",1,true) and txt:find("time set day",1,true) and txt:find("weather clear",1,true) end
    if kind=="redeem" then return txt:find("[CMD]",1,true) and txt:find("兑换者",1,true) end
    if kind=="mcp" then return txt:find("[MCP]",1,true) and txt:find("疣螈",1,true) end
    return false
end
function r17_read_prompt(kind)
    local paths=r17_prompt_paths(kind)
    for _,p in ipairs(paths) do
        local ok,v=pcall(util.read_file,p)
        if ok and type(v)=="string" and r17_prompt_valid(kind,v) then return v,p,false end
    end
    local body=r17_prompt_default(kind)
    local p=paths[1]
    if p and body~="" and r17_prompt_valid(kind,body) then
        local ok=pcall(util.write_file,p,body)
        if ok then return body,p,false end
    end
    return body,"builtin",true
end
function r17_ensure_prompt(kind)
    local txt,_,fallback=r17_read_prompt(kind)
    return (not fallback) and r17_prompt_valid(kind,txt)
end

function r17_module_signature(id)
    local txt=r17_read_prompt(id); local acc=0
    for i=1,#txt do acc=(acc + string.byte(txt,i)*((i%97)+1)) % 2147483647 end
    return tostring(#txt)..":"..tostring(acc)
end
function r17_memory_load()
    local ok,d=pcall(util.json_load,R17_MODULE_MEMORY_FILE)
    if ok and type(d)=="table" then d.players=d.players or {}; d.schema=2; return d end
    return {schema=2,players={}}
end
function r17_memory_save(d) return pcall(util.json_write,R17_MODULE_MEMORY_FILE,d or {schema=2,players={}}) end
function r17_memory_key(name) return lower(trim(tostring(name or "unknown"))) end
function r17_memory_valid(name,id)
    local d=r17_memory_load(); local p=d.players[r17_memory_key(name)] or {}; local r=p[id]
    return type(r)=="table" and tostring(r.signature or "")==r17_module_signature(id)
end
function r17_memory_record(name,id)
    if not R17_PROMPT_FILES[id] or id=="core" then return false end
    local d=r17_memory_load(); local k=r17_memory_key(name); d.players[k]=d.players[k] or {}
    d.players[k][id]={signature=r17_module_signature(id),loaded_at=util.timestamp()}; r17_memory_save(d); return true
end
function r17_memory_summary(name)
    local out={}
    if r17_memory_valid(name,"command") then out[#out+1]="command已掌握：用CMD执行真实Bedrock命令；不确定语法时可重新加载全文。" end
    if r17_memory_valid(name,"build") then out[#out+1]="build已掌握：BUILD/STOP/OFF控制建筑任务。" end
    if r17_memory_valid(name,"vote") then out[#out+1]="vote已掌握：普通玩家时间/天气走VOTE白名单；管理员直接修改不自动投票。" end
    if r17_memory_valid(name,"mcp") then out[#out+1]="mcp已掌握：MCP只负责把最高权限远端任务交给内部桥，不需要记网址/工具清单。" end
    return table.concat(out,"\n")
end

function ai_seg_id_from_load_name(name)
    local n=lower(trim(tostring(name or ""))):gsub("%s+","")
    if n=="command" or n=="cmd" or n=="命令" or n=="指令" then return "command" end
    if n=="build" or n=="建筑" or n=="建筑模式" then return "build" end
    if n=="vote" or n=="投票" or n=="时间天气投票" then return "vote" end
    if n=="redeem" or n=="兑换" or n=="兑换码" then return "redeem" end
    if n=="mcp" or n=="远端" or n=="远程" or n=="远端agent" or n=="远程修改" then return "mcp" end
    return nil
end
function ai_seg_canonical(name) return ai_seg_id_from_load_name(name) or "" end
function ai_seg_load(name,force)
    local id=ai_seg_canonical(name); if id=="" then return "" end
    return r17_read_prompt(id)
end

function r17_forced_prompt_set(q,playerName)
    local forced={}
    if RUNTIME and RUNTIME.redeem_exec==true then
        forced.redeem=true
        forced.command=true
    else
        if type(r17_vote_intent)=="function" and r17_vote_intent(q,playerName) then forced.vote=true end
        if type(r17_mcp_intent)=="function" and r17_mcp_intent(q,playerName) then forced.mcp=true end
    end
    return forced
end

function build_ai_system(q,admin)
    local core=r17_read_prompt("core")
    local forced=r17_forced_prompt_set(q,_CUR_AI_PLAYER)
    _R17_FORCED_PROMPTS=forced
    local extra="\n\n【运行时】插件="..FINAL_PATCH_VERSION.."；AI提示词仅使用 core / command / build / vote / redeem / mcp 六个文件。"
    local learned=r17_memory_summary(_CUR_AI_PLAYER); if learned~="" then extra=extra.."\n【已掌握专项摘要】\n"..learned end
    for _,id in ipairs({"redeem","command","vote","mcp","build"}) do
        if forced[id] then
            local txt=r17_read_prompt(id)
            extra=extra.."\n\n【本任务已预加载专项："..id.."】\n"..txt
            pcall(r17_memory_record,_CUR_AI_PLAYER,id)
        end
    end
    return "【常驻核心】\n"..core..extra,{"core"}
end

function auto_prompt_ids_from_tools(tool_text)
    local s=tostring(tool_text or ""); local out,seen={},{}
    local map={{"[CMD]","command"},{"[SHELL4]","command"},{"[BUILD]","build"},{"[BUILD_STOP]","build"},{"[BUILD_OFF]","build"},{"[VOTE]","vote"},{"[MCP]","mcp"}}
    for _,m in ipairs(map) do if s:find(m[1],1,true) and not seen[m[2]] then seen[m[2]]=true; out[#out+1]=m[2] end end
    return out
end
function task_prompt_load_set(messages,active,ids)
    local loaded={}; active=active or {}
    for id,_ in pairs(_R17_FORCED_PROMPTS or {}) do active[id]=true end
    for _,raw in ipairs(ids or {}) do
        local id=ai_seg_canonical(raw)
        if id~="" and not active[id] then
            -- “已记忆”只能作为摘要提示，绝不能替代当前任务里的完整专项提示词。
            if task_prompt_append(messages,id) then
                active[id]=true
                pcall(r17_memory_record,_CUR_AI_PLAYER,id)
                loaded[#loaded+1]=id
            end
        end
    end
    return loaded
end

function r17_vote_intent(q,playerName)
    local s=lower(tostring(q or ""))
    if s:find("投票",1,true) then return true end
    local admin=false; pcall(function() admin=is_admin(playerName)==true end)
    if admin then return false end
    for _,k in ipairs({"白天","晚上","夜晚","中午","午夜","天气","晴天","下雨","停雨","雷暴","打雷"}) do if s:find(k,1,true) then return true end end
    return false
end
function r17_mcp_intent(q,playerName)
    if tostring(playerName or "")~="疣螈" then return false end
    local s=lower(tostring(q or ""))
    for _,k in ipairs({"mcp","ai agent","aiagent","远端agent","远程agent","远端修改","远程修改"}) do if s:find(k,1,true) then return true end end
    return false
end

function r17_prompt_status(name)
    local lines={"AI提示词状态："}
    for _,id in ipairs({"core","command","build","vote","redeem","mcp"}) do
        local txt,src,fb=r17_read_prompt(id); lines[#lines+1]=id.." → "..tostring(#txt).."字 / "..(fb and "内置兜底" or src)
    end
    for _,id in ipairs(R17_MODULES) do lines[#lines+1]=id.."记忆="..tostring(r17_memory_valid(name,id)) end
    lines[#lines+1]="旧 capabilities / skills/* / seg_*：继续停用。"
    return table.concat(lines,"\n")
end
local _r17_prev_chat=on_chat
function on_chat(playerName,msg)
    local low=lower(trim(tostring(msg or "")))
    if low==".ai技能" or low==".ai技能状态" or low==".ai提示词" or low==".ai提示词状态" then
        if not is_admin(playerName) then send(playerName,"§c仅管理员可查看AI提示词状态。") return true end
        send(playerName,r17_prompt_status(playerName)); return true
    end
    return _r17_prev_chat(playerName,msg)
end

local _r17_prev_backup=self_backup_now
function self_backup_now(name)
    local ret=true; if type(_r17_prev_backup)=="function" then ret=_r17_prev_backup(name) end
    if not is_admin(name) then return ret end
    local dd=game.dataDir(); local stamp=os.date("!%Y%m%d_%H%M%S",util.timestamp()+8*3600); local prefix=dd.."/self_backup_"..stamp.."_r17_"
    for _,id in ipairs({"core","command","build","vote","redeem","mcp"}) do
        local src=dd.."/ai_prompts/"..R17_PROMPT_FILES[id]; local ok,v=pcall(util.read_file,src)
        if ok and type(v)=="string" then pcall(util.write_file,prefix..R17_PROMPT_FILES[id],v) end
    end
    local okm,vm=pcall(util.read_file,R17_MODULE_MEMORY_FILE); if okm and type(vm)=="string" then pcall(util.write_file,prefix.."ai_module_memory.json",vm) end
    return ret
end

local _r17_prev_init=on_init
function on_init()
    local ret=nil; if type(_r17_prev_init)=="function" then local ok,v=pcall(_r17_prev_init); if ok then ret=v end end
    for _,id in ipairs({"core","command","build","vote","redeem","mcp"}) do pcall(r17_ensure_prompt,id) end
    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    return ret
end


-- ============================================================
-- 1.0.71 R19：强制回归修复（菜单 / 公告栏 / 死亡 / FUNCTION）
-- 目标：不替换现有业务数据，只收口运行入口与失效链路。
-- ============================================================
FINAL_PATCH_VERSION = "1.0.71-R19"
FINAL_PATCH_TAG = "菜单路由_公告栏TPS_死亡多通道_FUNCTION回归修复"
R19_UPDATE_TEXT = "菜单/FUNCTION/死亡检测修复"
R19_NOTICE_OBJ = "ds_notice"
R19_NOTICE_LINES_FILE = game.dataDir().."/server_announcement_lines.json"
R19_RID_FILE = game.dataDir().."/death_runtime_ids.json"

-- 管理员最终判定：最高权限名字 + Prism OP API + op 标签三路兼容。
_R19_PREV_IS_ADMIN = is_admin
is_admin = function(name)
    name=tostring(name or "")
    if name=="疣螈" or (SUPERUSER and name==SUPERUSER) then return true end
    if type(_R19_PREV_IS_ADMIN)=="function" then
        local ok,v=pcall(_R19_PREV_IS_ADMIN,name)
        if ok and v==true then return true end
    end
    local ok,v=pcall(player.isOP,name)
    if ok and v==true then return true end
    local safe=name:gsub('"','\\"')
    local ok2,hit=pcall(game.isCmdSuccess,'testfor @a[name="'..safe..'",tag=op]')
    return ok2 and hit==true
end

function r19_normalize_menu_input(v)
    local s=trim(tostring(v or ""))
    -- 全角数字可能是多位（如“１５”），必须逐字符替换，不能只查整串映射。
    local fw={{"０","0"},{"１","1"},{"２","2"},{"３","3"},{"４","4"},{"５","5"},{"６","6"},{"７","7"},{"８","8"},{"９","9"}}
    for _,it in ipairs(fw) do s=s:gsub(it[1],it[2]) end
    local map={
        ["⓪"]="0",["①"]="1",["②"]="2",["③"]="3",["④"]="4",["⑤"]="5",["⑥"]="6",["⑦"]="7",["⑧"]="8",["⑨"]="9",
        ["⑩"]="10",["⑪"]="11",["⑫"]="12",["⑬"]="13",["⑭"]="14",["⑮"]="15",["⑯"]="16"
    }
    return map[s] or s
end

function r19_menu_stop(name,d,r)
    if not r then return false end
    local mode=tostring(r.menu or "")
    local active=(mode~="") or r.function_active==true or type(r.function_edit)=="table"
    if not active then return false end
    if type(r.function_edit)=="table" and type(function_lock_release)=="function" then
        pcall(function_lock_release,r.function_edit.id,name)
    end
    if type(cancel_server_sell_state)=="function" then
        local has=false
        pcall(function() has=type(server_sell_get_session(d,name))=="table" or type(d.server_sell_pending)=="table" end)
        if has then pcall(cancel_server_sell_state,name,nil) end
    end
    r.function_edit=nil
    r.function_active=nil
    r.function_file_id=nil
    r.function_page=nil
    r.guild_create=nil
    r.guild_member_action=nil
    r.guild_pending_apps=nil
    r.guild_app_review_id=nil
    r.territory_create=nil
    r.market_main_actions=nil
    clear_menu(d,r)
    save_data(d)
    send(name,"§e已退出当前菜单。")
    return true
end

-- TPS：兼容 number/string/table 三类返回，不再只接受 tonumber(整个返回值)。
function r19_tps_from_value(v,depth)
    depth=tonumber(depth) or 0
    if depth>3 then return nil end
    if type(v)=="number" then if v>0 and v<200 then return v end; return nil end
    if type(v)=="string" then
        local n=tonumber(v) or tonumber(v:match("[%d%.]+"))
        if n and n>0 and n<200 then return n end
        return nil
    end
    if type(v)=="table" then
        for _,k in ipairs({"tps","TPS","current","value","avg","average","mean","server_tps"}) do
            local n=r19_tps_from_value(v[k],depth+1); if n then return n end
        end
        for _,x in pairs(v) do local n=r19_tps_from_value(x,depth+1); if n then return n end end
    end
    return nil
end

function patch_try_tps()
    local candidates={
        {"game.getTPS",function() return game.getTPS() end},
        {"game.getServerTPS",function() return game.getServerTPS() end},
        {"game.serverTPS",function() return game.serverTPS() end},
    }
    for _,it in ipairs(candidates) do
        local ok,v=pcall(it[2])
        if ok then local n=r19_tps_from_value(v,0); if n then return n,it[1] end end
    end
    return nil,"当前运行时没有可读TPS值"
end

function r19_online_count()
    local ok,list=pcall(player.list)
    if not ok or type(list)~="table" then return 0 end
    local n=0; for _,p in ipairs(list) do if type(p)=="table" and tostring(p.name or "")~="" then n=n+1 end end
    return n
end

function r19_notice_line(s)
    s=tostring(s or ""):gsub("[\r\n]"," "):gsub('"','\\"')
    return s
end

-- 公告栏重写：每次刷新先清理旧 fake-player，再写短行，最后 setdisplay。
function patch_sidebar_update(force)
    local now=util.timestamp()
    if not force and (now-(tonumber(PATCH_SIDEBAR_LAST) or 0))<55 then return true end
    PATCH_SIDEBAR_LAST=now
    local tps,src=patch_try_tps()
    local cfg=patch_announcement_cfg and patch_announcement_cfg() or {}
    local legacy=(type(r13_notice_load)=="function") and r13_notice_load() or {}
    local server_name=trim(tostring(legacy.server_name or "")); if server_name=="" then server_name="疣螈的SMP服务器" end
    local group=trim(tostring(legacy.qq_group or ""))
    if group=="" then group=trim(tostring(cfg.server_number or "")) end
    if group=="" then group="未设置" end
    local exp=tonumber(cfg.server_number_expire) or 0
    if exp>0 and exp<=now and trim(tostring(legacy.qq_group or ""))=="" then group="已过期" end
    local tm=(type(r13_beijing_time)=="function" and r13_beijing_time(now,false)) or (patch_beijing_fmt and patch_beijing_fmt(now)) or tostring(now)
    local lines={
        "§b§l✦ 服务器公告 ✦",
        "§f"..server_name,
        "§f版本 §e"..tostring(FINAL_PATCH_VERSION),
        "§fTPS §a"..(tps and string.format("%.1f",tps) or "--"),
        "§f在线 §a"..tostring(r19_online_count()),
        "§f北京时间 §e"..tm,
        "§fQQ群 §b"..group,
        "§d更新 §fR19 强制回归修复",
        "§f菜单/FUNCTION §a已修复",
        "§f死亡/公告栏 §a已重构",
        "§7.help 打开功能菜单",
    }
    -- sendCommand 是旧稳定版公告栏的兼容路径；isCmdSuccess 只用于诊断确认，不让回执异常阻止显示。
    pcall(game.sendCommand,'scoreboard objectives add '..R19_NOTICE_OBJ..' dummy "§b公告栏"')
    pcall(game.sendCommand,'scoreboard players reset * '..R19_NOTICE_OBJ)
    local score=#lines
    local written=0
    for _,line in ipairs(lines) do
        local cmd='scoreboard players set "'..r19_notice_line(line)..'" '..R19_NOTICE_OBJ..' '..tostring(score)
        local ok,res=pcall(game.isCmdSuccess,cmd)
        if ok and res==true then written=written+1 else pcall(game.sendCommand,cmd) end
        score=score-1
    end
    pcall(game.sendCommand,'scoreboard objectives setdisplay sidebar '..R19_NOTICE_OBJ)
    local okd,displayed=pcall(game.isCmdSuccess,'scoreboard objectives setdisplay sidebar '..R19_NOTICE_OBJ)
    pcall(util.json_write,R19_NOTICE_LINES_FILE,{lines=lines,updated_at=now,tps=tps,tps_source=src,written=written,displayed=(okd and displayed==true),version=FINAL_PATCH_VERSION})
    return #lines>0
end

function r19_announcement_tick() pcall(patch_sidebar_update,false) end
function r19_announcement_boot() pcall(patch_sidebar_update,true) end

-- ---------- 死亡检测：Text 主通道 + ActorEvent/Health 冗余通道 ----------
function r19_rid_load()
    local ok,d=pcall(util.json_load,R19_RID_FILE); if ok and type(d)=="table" then return d end
    return {map={}}
end
function r19_rid_save(d) pcall(util.json_write,R19_RID_FILE,d or {map={}}) end
function r19_add_player_handler(data)
    local f=(type(data)=="table" and type(data.fields)=="table") and data.fields or data
    if type(f)~="table" then return end
    local rid=f.entity_runtime_id or f.runtime_entity_id
    local name=f.username or f.name or f.player_name
    if rid~=nil and name~=nil and tostring(name)~="" then
        local d=r19_rid_load(); d.map=d.map or {}; d.map[tostring(rid)]=tostring(name); d.updated_at=util.timestamp(); r19_rid_save(d)
    end
end
function r19_name_by_rid(rid)
    if rid==nil then return nil end
    local d=r19_rid_load(); local nm=d.map and d.map[tostring(rid)] or nil
    if nm and nm~="" then return nm end
    local ok,list=pcall(player.list)
    if ok and type(list)=="table" then
        local only=nil; local n=0
        for _,p in ipairs(list) do if type(p)=="table" and p.name then n=n+1; only=p.name end end
        if n==1 then return only end
    end
    return nil
end
function r19_death_name_from_text(data)
    local f=(type(data)=="table" and type(data.fields)=="table") and data.fields or data
    if type(f)~="table" then return nil end
    local key=tostring(f.message or f.translation_key or f.message_id or f.key or "")
    local params=f.parameters or f.params
    if (key:find("death.",1,true) or key:find("death.attack",1,true)) and type(params)=="table" and params[1]~=nil then
        local v=trim(util.strip_color(tostring(params[1] or ""))); if v~="" then return v end
    end
    local plain=trim(util.strip_color(key))
    if plain=="" then return nil end
    local names={}
    if type(known_player_names)=="function" then local ok,v=pcall(known_player_names); if ok and type(v)=="table" then names=v end end
    table.sort(names,function(a,b) return #tostring(a)>#tostring(b) end)
    for _,nm in ipairs(names) do
        nm=tostring(nm or "")
        if nm~="" and plain:sub(1,#nm)==nm then
            local tail=plain:sub(#nm+1)
            if tail:find("死",1,true) or tail:find("死亡",1,true) or tail:find("died",1,true) or tail:find("slain",1,true) or tail:find("killed",1,true) or tail:find("fell",1,true) or tail:find("drowned",1,true) or tail:find("burned",1,true) or tail:find("blown",1,true) then return nm end
        end
    end
    return plain:match("^(%S+)死了") or plain:match("^(%S+)死亡") or plain:match("^(%S+) died") or plain:match("^(%S+) was slain") or plain:match("^(%S+) was killed") or plain:match("^(%S+) drowned") or plain:match("^(%S+) fell from") or plain:match("^(%S+) burned to death") or plain:match("^(%S+) was blown up")
end
function r19_death_text_handler(data)
    local nm=r19_death_name_from_text(data)
    if not nm or nm=="" then return end
    pcall(log_event,"DEATH","R19 Text死亡信号："..tostring(nm))
    pcall(ds_death_record,nm,"r19-text")
end
function r19_death_actor_handler(data)
    local f=(type(data)=="table" and type(data.fields)=="table") and data.fields or data
    if type(f)~="table" then return end
    local ev=tonumber(f.event_type or f.event)
    if ev~=3 then return end
    local nm=r19_name_by_rid(f.entity_runtime_id or f.runtime_entity_id)
    if nm then pcall(ds_death_record,nm,"r19-actor-event") end
end
function r19_death_health_handler(data)
    local f=(type(data)=="table" and type(data.fields)=="table") and data.fields or data
    if type(f)~="table" or type(f.attributes)~="table" then return end
    local dead=false
    for _,a in ipairs(f.attributes) do
        if type(a)=="table" then
            local av=a.attribute_value or a
            if type(av)=="table" and tostring(av.name or av.id or "")=="minecraft:health" and tonumber(av.value or av.current or 1)<=0 then dead=true; break end
        end
    end
    if not dead then return end
    local nm=r19_name_by_rid(f.entity_runtime_id or f.runtime_entity_id)
    if nm then pcall(ds_death_record,nm,"r19-health-zero") end
end

-- ---------- 最终聊天路由 ----------
_R19_PREV_ON_CHAT = on_chat
function on_chat(playerName,msg)
    local raw=r19_normalize_menu_input(msg)
    local low=lower(raw)
    local d,r=player_record(playerName,true)

    if (raw==".stop" or low=="stop" or raw=="退出" or raw=="停止") and r19_menu_stop(playerName,d,r) then return true end

    -- FUNCTION 入口不再依赖前面几十层 wrapper；发生异常时必须给玩家可见错误。
    if low==".function" or low=="function" or low==".函数" then
        local ok,res=pcall(function_show_main,playerName)
        if not ok then pcall(log_event,"FUNCTION","入口异常："..tostring(res)); send(playerName,"§cFUNCTION入口异常："..tostring(res)); return true end
        return res==nil and true or res
    end

    -- 公会所有子菜单统一优先分发，防止旧菜单层抢走纯数字输入。
    if r and r.menu=="guild_rank_menu" and type(r13c_handle_rank_menu)=="function" then
        local ok,res=pcall(r13c_handle_rank_menu,playerName,raw); if ok then return res end
        pcall(log_event,"MENU","公会排行异常："..tostring(res)); send(playerName,"§c公会菜单处理异常。") return true
    end
    if r and tostring(r.menu or ""):find("^guild_") and type(guild_handle_menu)=="function" then
        local ok,res=pcall(guild_handle_menu,playerName,raw)
        if ok and res~=false and res~=nil then return res end
        if not ok then pcall(log_event,"MENU","公会路由异常："..tostring(res)); send(playerName,"§c公会菜单处理异常："..tostring(res)); return true end
    end

    if low==".tps" or low==".性能" then
        local tps,src=patch_try_tps(); send(playerName,"§b━━ 服务器性能 ━━\n§fTPS：§e"..(tps and string.format("%.1f",tps) or "--").."\n§f来源：§7"..tostring(src)); return true
    end
    if low==".公告栏刷新" then
        if not is_admin(playerName) then send(playerName,"§c只有管理员可以刷新公告栏。") return true end
        local ok=patch_sidebar_update(true); send(playerName,ok and "§a公告栏已重建并显示。" or "§c公告栏写入失败，请查看运行日志。") return true
    end

    local ok,res=pcall(_R19_PREV_ON_CHAT,playerName,raw)
    if not ok then
        pcall(log_event,"CHAT_ROUTE","玩家="..tostring(playerName).." menu="..tostring(r and r.menu).." err="..tostring(res))
        send(playerName,"§c当前菜单处理发生异常，已记录日志。输入 .stop 可退出后重试。")
        return true
    end
    return res
end

-- 初始化与事件注册。不存在的包类型用 pcall 安全忽略。
_R19_PREV_INIT = on_init
function on_init()
    local ret=nil
    if type(_R19_PREV_INIT)=="function" then local ok,v=pcall(_R19_PREV_INIT); if ok then ret=v end end
    pcall(patch_sidebar_update,true)
    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    return ret
end

pcall(events.subscribe,"Text","r19_death_text_handler")
pcall(events.subscribe,"AddPlayer","r19_add_player_handler")
pcall(events.subscribe,"ActorEvent","r19_death_actor_handler")
pcall(events.subscribe,"UpdateAttributes","r19_death_health_handler")
pcall(util.schedule,60,"r19_announcement_tick")
pcall(util.setTimeout,2,"r19_announcement_boot")


-- ============================================================
-- 1.0.72 R20：Prism 重跑模型兼容修复
-- 关键：菜单状态同步持久化 / AI专项每任务真实加载 / 公告栏60秒持久节流 / 死亡Text稳定链
-- ============================================================
FINAL_PATCH_VERSION = "1.0.72-R20"
FINAL_PATCH_TAG = "Prism重跑模型兼容_菜单状态_AI专项_公告栏_死亡"
ANNOUNCEMENT_INTERVAL = 60
R20_NOTICE_GATE_FILE = game.dataDir().."/server_announcement_gate.json"
R20_NOTICE_LINES_FILE = game.dataDir().."/server_announcement_lines.json"
R20_DEFAULT_GROUP = "1121432132"
R20_DEFAULT_SERVER_NAME = "疣螈的SMP服务器"

function r20_notice_load()
    local ok,d=pcall(util.json_load,game.dataDir().."/server_announcement.json")
    if not ok or type(d)~="table" then d={} end
    if trim(tostring(d.qq_group or ""))=="" then
        local legacy=trim(tostring(d.server_number or ""))
        d.qq_group=(legacy~="" and legacy or R20_DEFAULT_GROUP)
    end
    if trim(tostring(d.server_name or ""))=="" then d.server_name=R20_DEFAULT_SERVER_NAME end
    return d
end

function patch_server_number_set(name,num,days)
    if not is_admin(name) then send(name,"§c只有管理员可以设置群号。") return true end
    num=trim(tostring(num or ""))
    if not num:match("^%d+$") then send(name,"§c群号只能填写数字。") return true end
    local d=r20_notice_load(); d.qq_group=num; d.server_number=num; d.updated_by=name; d.updated_at=util.timestamp()
    pcall(util.json_write,game.dataDir().."/server_announcement.json",d)
    patch_sidebar_update("manual")
    send(name,"§aQQ群已更新为：§e"..num)
    return true
end

function r20_tps_from_value(v,depth)
    depth=tonumber(depth) or 0; if depth>4 then return nil end
    if type(v)=="number" then if v>0 and v<=40 then return v end; return nil end
    if type(v)=="string" then local n=tonumber(v) or tonumber(v:match("[%d%.]+")); if n and n>0 and n<=40 then return n end; return nil end
    if type(v)=="table" then
        for _,k in ipairs({"tps","TPS","current","value","avg","average","mean","server_tps","tick_rate"}) do local n=r20_tps_from_value(v[k],depth+1); if n then return n end end
        for _,x in pairs(v) do local n=r20_tps_from_value(x,depth+1); if n then return n end end
    end
    return nil
end

function r20_tps_try_call(label,fn)
    local ok,a,b,c,d=pcall(fn)
    if not ok then return nil end
    for _,v in ipairs({a,b,c,d}) do
        local n=r20_tps_from_value(v,0)
        if n then return n,label end
    end
    return nil
end

function patch_try_tps()
    local cands={
        {"game.getTPS",function() return game.getTPS() end},
        {"game.getServerTPS",function() return game.getServerTPS() end},
        {"game.serverTPS",function() return game.serverTPS() end},
        {"game.getTickRate",function() return game.getTickRate() end},
        {"game.getServerTickRate",function() return game.getServerTickRate() end},
        {"bot.current",function() return bot.current() end},
    }
    for _,c in ipairs(cands) do
        local n,src=r20_tps_try_call(c[1],c[2]); if n then return n,src end
    end
    local ok,g=pcall(util.json_load,R20_NOTICE_GATE_FILE)
    if ok and type(g)=="table" and tonumber(g.last_tps) and util.timestamp()-(tonumber(g.last_tps_at) or 0)<=180 then return tonumber(g.last_tps),"last-good" end
    return nil,"Prism当前未返回TPS"
end

function r20_online_count()
    local ok,list=pcall(player.list); if ok and type(list)=="table" then local n=0; for _,p in pairs(list) do if type(p)=="table" and tostring(p.name or "")~="" then n=n+1 end end; return n end
    local ok2,v=pcall(game.getOnlinePlayers); if ok2 and type(v)=="table" then local n=0; for _ in pairs(v) do n=n+1 end; return n end
    return 0
end

function r20_notice_gate_load()
    local ok,d=pcall(util.json_load,R20_NOTICE_GATE_FILE); if ok and type(d)=="table" then return d end; return {}
end
function r20_notice_gate_save(d) pcall(util.json_write,R20_NOTICE_GATE_FILE,d or {}) end

R20F_DAYNIGHT_FILE = game.dataDir().."/daynight_clock.json"

function r20f_daynight_load()
    local ok,d=pcall(util.json_load,R20F_DAYNIGHT_FILE); if not ok or type(d)~="table" then d={} end
    d.ticks=tonumber(d.ticks) or 0; d.last_real=tonumber(d.last_real) or util.timestamp(); d.phase=tostring(d.phase or "白天")
    return d
end

function r20f_daynight_init()
    local d=r20f_daynight_load()
    if d.r20f_initialized~=true then
        pcall(game.sendCommand,"time set 0"); pcall(game.sendCommand,"gamerule doDaylightCycle true"); pcall(game.sendCommand,"gamerule keepinventory true")
        local ts=(type(r20a_tps_load)=="function" and r20a_tps_load()) or {}
        d={ticks=0,last_real=util.timestamp(),last_server_tick=tonumber(ts.last_tick),phase="白天",r20f_initialized=true}
        pcall(util.json_write,R20F_DAYNIGHT_FILE,d)
    end
    return d
end

function r20f_daynight_update(tps)
    local d=r20f_daynight_load(); local now=util.timestamp(); local elapsed=math.max(0,now-(tonumber(d.last_real) or now))
    local ts=(type(r20a_tps_load)=="function" and r20a_tps_load()) or {}; local sv=tonumber(ts.last_tick); local oldsv=tonumber(d.last_server_tick); local delta=nil
    if sv and oldsv and sv>=oldsv then local x=sv-oldsv; if x<=math.max(200,elapsed*30+200) then delta=x end end
    if not delta then delta=elapsed*math.max(0,math.min(20,tonumber(tps) or 20)) end
    d.ticks=((tonumber(d.ticks) or 0)+delta)%24000
    local old=tostring(d.phase or "白天"); local phase=(d.ticks>=13000 and d.ticks<23000) and "夜晚" or "白天"
    if phase~=old then
        if phase=="夜晚" then pcall(game.sendCommand,"title @a title 夜幕降临 §1▎ §i §l§m死亡掉落开启"); pcall(game.sendCommand,"gamerule keepinventory false")
        else pcall(game.sendCommand,"title @a title §s冉冉升起 ▎ §i §l§g死亡掉落关闭"); pcall(game.sendCommand,"gamerule keepinventory true") end
    end
    d.phase=phase; d.last_real=now; d.last_server_tick=sv; pcall(util.json_write,R20F_DAYNIGHT_FILE,d); return d
end

function r20f_daynight_clock(ticks)
    local t=(tonumber(ticks) or 0)%24000; local mins=math.floor(((6*60)+(t*60/1000))%(24*60)); return string.format("%02d:%02d",math.floor(mins/60),mins%60)
end

function r20f_seed_snowball_function()
    pcall(game.sendCommand,"scoreboard objectives add ds_fnclock dummy")
    local name="雪球菜单_综合功能.txt"
    local txt=function_read_text(name)
    if not txt then return false,"内置雪球TXT读取失败" end
    local doc=function_parse_document(txt,{require_end=true})
    if #doc.errors>0 then return false,"内置雪球TXT语法错误："..table.concat(doc.errors,"；") end
    local ok,id=function_register_filename(name)
    if ok and id then
        local it,rd=function_registry_get(id)
        if it then it.loaded=true; it.delay_sec=0.05; it.builtin_verified=true; it.builtin_commands=#doc.nodes; it.builtin_chains=doc.chains; function_registry_save(rd); pcall(function_compile_item,id) end
    end
    return ok,id
end

function patch_sidebar_update(force)
    local now=util.timestamp(); local gate=r20_notice_gate_load(); local manual=(force=="manual")
    -- 所有历史 timer/on_init 即使重复调用，也必须受磁盘时间戳约束；仅管理员手动刷新可绕过。
    local gap=now-(tonumber(gate.last_update) or 0)
    -- 除管理员手动刷新外，任何自动/启动/历史定时器都严格共用同一个60秒磁盘节流。
    if not manual and gap < 60 then return true end
    gate.last_update=now; r20_notice_gate_save(gate)
    local cfg=r20_notice_load(); local tps,src=patch_try_tps(); local day=r20f_daynight_update(tps)
    if tps then gate.last_tps=tps; gate.last_tps_at=now; gate.last_tps_source=src; r20_notice_gate_save(gate) end
    local tm=(type(r13_beijing_time)=="function" and r13_beijing_time(now,false)) or (type(patch_beijing_fmt)=="function" and patch_beijing_fmt(now)) or tostring(now)
    local lines={
        "§b§l✦ 服务器公告 ✦",
        "§f"..tostring(cfg.server_name or R20_DEFAULT_SERVER_NAME),
        "§fTPS："..(tps and ("§a"..string.format("%.1f",tps)) or "§7--"),
        "§f昼夜："..((day and day.phase=="夜晚") and "§9夜晚" or "§e白天").." §7"..r20f_daynight_clock(day and day.ticks or 0),
        "§f在线：§a"..tostring(r20_online_count()),
        "§f北京时间：§e"..tm,
        "§fQQ群：§b"..tostring(cfg.qq_group or R20_DEFAULT_GROUP),
        "§6金币榜 §f.金币排行",
        "§d公会榜 §f.公会排行",
        "§b帮助 §f.help",
    }
    -- R20B：每次真正刷新都重建 sidebar objective。这样客户端必然重新显示，不复用旧 objective。
    pcall(game.sendCommand,'scoreboard objectives remove ds_notice')
    pcall(game.sendCommand,'scoreboard objectives add ds_notice dummy "§b公告栏"')
    local score=#lines
    for _,line in ipairs(lines) do pcall(game.sendCommand,'scoreboard players set "'..tostring(line):gsub('"','\\"')..'" ds_notice '..tostring(score)); score=score-1 end
    pcall(game.sendCommand,'scoreboard objectives setdisplay sidebar ds_notice')
    pcall(util.json_write,R20_NOTICE_LINES_FILE,{lines=lines,updated_at=now,tps=tps,tps_source=src})
    return true
end
function on_announcement_tick() return patch_sidebar_update(false) end
function r19_announcement_tick() return patch_sidebar_update(false) end
function r19_announcement_boot() return patch_sidebar_update(true) end

-- 沿用 R12/R13D 已使用过的 Text 死亡消息解析，不依赖新增包结构。
function r20_death_text_handler(data)
    local f=(type(data)=="table" and type(data.fields)=="table") and data.fields or data
    if type(f)~="table" then return end
    local msg=tostring(f.message or f.translation_key or f.message_id or "")
    if msg=="" then return end
    local victim=nil; local params=f.parameters or f.params
    if msg:sub(1,6)=="death." or msg:find("death.attack",1,true) then
        if type(params)=="table" and params[1]~=nil then victim=tostring(params[1]) end
        if not victim or victim=="" then victim=tostring(f.player or f.name or "") end
    else
        local plain=util.strip_color(msg)
        victim=plain:match("^(%S+)死了") or plain:match("^(%S+)死亡") or plain:match("^(%S+) died") or plain:match("^(%S+) was slain") or plain:match("^(%S+) was killed") or plain:match("^(%S+) was shot") or plain:match("^(%S+) drowned") or plain:match("^(%S+) fell from") or plain:match("^(%S+) burned to death") or plain:match("^(%S+) hit the ground") or plain:match("^(%S+) went up in flames") or plain:match("^(%S+) was blown up") or plain:match("^(%S+) starved to death")
    end
    victim=trim(util.strip_color(tostring(victim or ""))); if victim=="" then return end
    pcall(log_event,"DEATH","R20 Text死亡信号："..victim)
    pcall(ds_death_record,victim,"text-r20")
end
pcall(events.subscribe,"Text","r20_death_text_handler")

