-- ============================================================
-- R20B：R20回滚主体 + R12稳定AI思考提示 + 公告栏60秒重建
-- 真机验证：当前 Prism/网易基岩版 SetTime 包类型 SrxhUu8I4，
-- wug_mir_mdto 为服务器游戏 tick；用 tick 差 / 实际秒差估算 TPS。
-- ============================================================
FINAL_PATCH_VERSION = "1.0.72-R20B"
FINAL_PATCH_TAG = "R20回滚_旧版AI思考提示_公告栏60秒重建"
R20A_TPS_FILE = game.dataDir().."/r20a_tps_samples.json"
R20A_TPS_PACKET_TYPE = "SrxhUu8I4"

function r20a_tps_load()
    local ok,d=pcall(util.json_load,R20A_TPS_FILE)
    if ok and type(d)=="table" then d.samples=d.samples or {}; return d end
    return {samples={}}
end

function r20a_tps_packet(data)
    local f=(type(data)=="table" and type(data.fields)=="table") and data.fields or data
    if type(f)~="table" then return end
    local tick=tonumber(f.wug_mir_mdto)
    if not tick then return end
    local now=util.timestamp()
    local st=r20a_tps_load()
    local last_tick=tonumber(st.last_tick)
    local last_ts=tonumber(st.last_ts)
    if last_tick and last_ts and tick>last_tick then
        local dt=tick-last_tick
        local sec=now-last_ts
        if dt>0 and dt<=1024 and sec>=5 and sec<=60 then
            local tps=dt/sec
            if tps>0 and tps<=30 then
                if tps>20 then tps=20 end
                st.samples[#st.samples+1]=tps
                while #st.samples>8 do table.remove(st.samples,1) end
                local sum,n=0,0
                for _,v in ipairs(st.samples) do
                    local x=tonumber(v)
                    if x and x>0 and x<=20.5 then sum=sum+x; n=n+1 end
                end
                if n>0 then st.tps=sum/n; st.updated_at=now end
            end
        end
    end
    st.last_tick=tick
    st.last_ts=now
    pcall(util.json_write,R20A_TPS_FILE,st)
end

function patch_try_tps()
    local st=r20a_tps_load()
    local tps=tonumber(st.tps)
    local at=tonumber(st.updated_at) or 0
    if tps and tps>0 and util.timestamp()-at<=90 then
        return math.min(20,tps),"SetTime包采样"
    end
    local ok,g=pcall(util.json_load,R20_NOTICE_GATE_FILE)
    if ok and type(g)=="table" then
        local last=tonumber(g.last_tps)
        local last_at=tonumber(g.last_tps_at) or 0
        if last and last>0 and util.timestamp()-last_at<=180 then return last,"last-good" end
    end
    return nil,"SetTime采样中"
end

pcall(events.subscribe,R20A_TPS_PACKET_TYPE,"r20a_tps_packet")


-- ============================================================
-- 1.0.73 R20C：FUNCTION 同步顺序命令方块链执行核
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R20H"
FINAL_PATCH_TAG = "FUNCTION语法修复_真实TXT加载_链级频率_雪球昼夜"

-- R20H：修复尾部说明行误用单横线造成的 Lua Invalid token；动态回调机制继续保留。
-- 内置雪球 TXT 始终通过 function_read_text + function_parse_document 真实读取/解析；扫描权限不会导致误判缺失。

-- ============================================================
-- 1.0.73 R20J：内置TXT直读 / 昼夜TPS时钟 / 公告栏精简
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R20J"
FINAL_PATCH_TAG = "内置TXT直读_昼夜TPS校准_公告栏精简"

R20J_DAYNIGHT_SCHEMA = 2
R20J_DAYNIGHT_FILE = game.dataDir().."/daynight_clock_r20j.json"



function function_read_text(name)
    local path,n=function_file_path(name)
    if not path then return nil,n end

    local ok,v=pcall(util.read_file,path)
    if ok and type(v)=="string" and trim(v)~="" then
        return v,path
    end

    local embedded=FUNCTION_EMBEDDED_TXT and FUNCTION_EMBEDDED_TXT[tostring(n or "")]
    if type(embedded)=="string" and trim(embedded)~="" then
        pcall(util.write_file,path,embedded)
        return embedded,"<embedded:"..tostring(n)..">"
    end

    local bundled=FUNCTION_BUNDLED_TXT and FUNCTION_BUNDLED_TXT[tostring(n or "")]
    if bundled then
        local cd=""
        pcall(function() cd=tostring(plugin_code_dir() or "") end)
        if cd~="" then
            local rp=cd.."/command_txt/"..bundled
            local ok2,v2=pcall(util.read_file,rp)
            if ok2 and type(v2)=="string" and trim(v2)~="" then
                pcall(util.write_file,path,v2)
                return v2,rp
            end
        end
    end
    return nil,"读取不到TXT："..tostring(n)
end

function r20j_register_builtin_functions()
    for _,name in ipairs({"雪球菜单_综合功能.txt","FUNCTION_链级频率示例.txt"}) do
        local txt,src=function_read_text(name)
        if type(txt)=="string" and trim(txt)~="" then
            local doc=function_parse_document(txt,{require_end=true})
            if type(doc)=="table" and type(doc.errors)=="table" and #doc.errors==0 then
                local ok,id=function_register_filename(name)
                if ok and id then
                    local it,rd=function_registry_get(id)
                    if it then
                        it.loaded=true
                        it.missing=false
                        it.builtin_verified=true
                        it.builtin_source=src
                        it.builtin_commands=#(doc.nodes or {})
                        it.builtin_chains=tonumber(doc.chains) or 1
                        function_registry_save(rd)
                        pcall(function_compile_item,id)
                    end
                end
            end
        end
    end
    pcall(function_scan_files,true)
    return true
end

function r20j_daynight_load()
    local ok,d=pcall(util.json_load,R20J_DAYNIGHT_FILE)
    if not ok or type(d)~="table" then d={} end
    return d
end

function r20j_effective_tps()
    local tps,src=patch_try_tps()
    tps=tonumber(tps)
    if tps and tps>0 and tps<=20.5 then
        return math.min(20,tps),tostring(src or "TPS")
    end
    local st=(type(r20a_tps_load)=="function" and r20a_tps_load()) or {}
    tps=tonumber(st.tps)
    if tps and tps>0 and tps<=20.5 then
        return math.min(20,tps),"最近TPS样本"
    end
    return 20,"20TPS兜底"
end

function r20j_daynight_init()
    local d=r20j_daynight_load()
    if tonumber(d.schema)~=R20J_DAYNIGHT_SCHEMA then
        pcall(game.sendCommand,"time set 0")
        pcall(game.sendCommand,"gamerule doDaylightCycle true")
        pcall(game.sendCommand,"gamerule keepinventory true")
        d={
            schema=R20J_DAYNIGHT_SCHEMA,
            ticks=0,
            last_real=util.timestamp(),
            phase="白天",
            initialized_at=util.timestamp(),
            tps=20,
            tps_source="初始化",
        }
        pcall(util.json_write,R20J_DAYNIGHT_FILE,d)
    end
    return d
end

function r20j_daynight_update()
    local d=r20j_daynight_init()
    local now=util.timestamp()
    local last=tonumber(d.last_real) or now
    local elapsed=math.max(0,now-last)
    if elapsed>180 then elapsed=60 end

    local tps,src=r20j_effective_tps()
    d.ticks=((tonumber(d.ticks) or 0)+(elapsed*tps))%24000

    local old=tostring(d.phase or "白天")
    local phase=(d.ticks>=13000 and d.ticks<23000) and "夜晚" or "白天"
    if phase~=old then
        if phase=="夜晚" then
            pcall(game.sendCommand,"title @a title 夜幕降临")
            pcall(game.sendCommand,"gamerule keepinventory false")
        else
            pcall(game.sendCommand,"title @a title 冉冉升起")
            pcall(game.sendCommand,"gamerule keepinventory true")
        end
    end

    d.phase=phase
    d.last_real=now
    d.tps=tps
    d.tps_source=src
    d.updated_at=now
    pcall(util.json_write,R20J_DAYNIGHT_FILE,d)
    return d
end

function r20j_daynight_clock(ticks)
    local t=(tonumber(ticks) or 0)%24000
    local total_minutes=math.floor(((6*60)+(t*60/1000))%(24*60))
    return string.format("%02d:%02d",math.floor(total_minutes/60),total_minutes%60)
end

function patch_sidebar_update(force)
    local now=util.timestamp()
