-- ============================================================
-- 1.0.73 R20K：外部TXT资源加载 / 实体数量检测
-- 大段 FUNCTION 指令只存放在 command_txt/*.txt，不复制到 Lua。
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R20K"
FINAL_PATCH_TAG = "外部TXT加载_实体数量检测"

R20K_ENTITY_FILE = game.dataDir().."/entity_count_r20k.json"

-- 读取 ZIP 中“存储（method=0）”的原始文件。
-- command_txt 资源在 R20K 包内特意使用 ZIP_STORED，以便运行环境无法访问
-- 插件解压目录时，仍可以直接从安装 ZIP 读取 TXT 原文。
function r20k_zip_read_stored_entry(zip_path, entry_name)
    local ok,data=pcall(util.read_file,tostring(zip_path or ""))
    if not ok or type(data)~="string" or #data<30 then return nil end
    local pos=1
    while true do
        local s=data:find("PK\003\004",pos,true)
        if not s then break end
        local method=string.byte(data,s+8)+(string.byte(data,s+9)*256)
        local csize=0
        for i=0,3 do csize=csize+string.byte(data,s+18+i)*(256^i) end
        local nlen=string.byte(data,s+26)+(string.byte(data,s+27)*256)
        local elen=string.byte(data,s+28)+(string.byte(data,s+29)*256)
        local name=data:sub(s+30,s+30+nlen-1)
        local dstart=s+30+nlen+elen
        if name==entry_name and method==0 then
            return data:sub(dstart,dstart+csize-1),zip_path
        end
        pos=dstart+csize
    end
    return nil
end

function r20k_plugin_zip_candidates()
    local base=tostring(plugin_base_dir() or "")
    local id=tostring(plugin_id_now() or "ds_ai_agent")
    return {
        base.."/插件文件/"..id..".zip",
        base.."/插件文件/ds_ai_agent.zip",
        base.."/"..id..".zip",
    }
end

-- R20K：真正的外部 TXT 加载。
-- 1. dataDir/command_txt（用户自己的可编辑版本）
-- 2. 插件解压目录 command_txt
-- 3. 安装 ZIP 内 command_txt（不把命令嵌入 Lua）
function function_read_text(name)
    local path,n=function_file_path(name)
    if not path then return nil,n end

    local ok,v=pcall(util.read_file,path)
    if ok and type(v)=="string" and trim(v)~="" then
        return v,path
    end

    local bundled=FUNCTION_BUNDLED_TXT and FUNCTION_BUNDLED_TXT[tostring(n or "")]
    if not bundled then
        return nil,"读取不到TXT："..tostring(n)
    end

    local cd=""
    pcall(function() cd=tostring(plugin_code_dir() or "") end)
    if cd~="" then
        local rp=cd.."/command_txt/"..bundled
        local ok2,v2=pcall(util.read_file,rp)
        if ok2 and type(v2)=="string" and trim(v2)~="" then
            pcall(util.write_file,path,v2)
            return v2,rp
        end
    end

    local entry="command_txt/"..bundled
    for _,zp in ipairs(r20k_plugin_zip_candidates()) do
        local raw,src=r20k_zip_read_stored_entry(zp,entry)
        if type(raw)=="string" and trim(raw)~="" then
            pcall(util.write_file,path,raw)
            return raw,src.."::"..entry
        end
    end

    return nil,"读取不到外部TXT："..tostring(n)
end

function r20k_entity_save(d)
    pcall(util.json_write,R20K_ENTITY_FILE,d or {})
end

function r20k_entity_load()
    local ok,d=pcall(util.json_load,R20K_ENTITY_FILE)
    if ok and type(d)=="table" then return d end
    return {count=0,updated_at=0,ok=false}
end

function r20k_resp_number(resp)
    if type(resp)~="table" then return nil end
    local msgs=resp.messages or resp.output_messages
    if type(msgs)~="table" then return nil end
    for _,m in ipairs(msgs) do
        if type(m)=="table" then
            local p=m.parameters or m.Parameters
            if type(p)=="table" then
                for i=#p,1,-1 do
                    local n=tonumber(p[i])
                    if n then return n end
                end
            end
        end
    end
    return nil
end

-- 统计当前服务器三个维度中已加载的 @e 实体。
-- 每分钟刷新一次，不做 20Hz 实体扫描。
function r20k_refresh_entity_count(force)
    local cache=r20k_entity_load()
    local now=util.timestamp()
    if force~=true and now-(tonumber(cache.updated_at) or 0)<55 then
        return tonumber(cache.count) or 0,cache.ok==true,tostring(cache.source or "缓存")
    end

    -- 这几条只是计数器控制命令，不是业务 FUNCTION 指令。
    pcall(game.sendCommandWithResp,"scoreboard objectives add ds_entity_count dummy","ai",5)
    local ok0=pcall(game.sendCommandWithResp,"scoreboard players set __ds_entities__ ds_entity_count 0","ai",5)

    local dims={"overworld","nether","the_end"}
    local sent=0
    for _,dim in ipairs(dims) do
        local ok=pcall(game.sendCommandWithResp,
            "execute in "..dim.." as @e run scoreboard players add __ds_entities__ ds_entity_count 1",
            "ai",10)
        if ok then sent=sent+1 end
    end

    local okg,resp=pcall(game.sendCommandWithResp,
        "scoreboard players get __ds_entities__ ds_entity_count","ai",5)
    local n=okg and r20k_resp_number(resp) or nil

    if n==nil then
        local oks,scores=pcall(game.getMultiScore,"__ds_entities__")
        if oks and type(scores)=="table" and type(r16_score_map_find)=="function" then
            local map=r16_score_map_find(scores,0)
            if type(map)=="table" then
                n=tonumber(map.ds_entity_count)
                if n==nil then
                    for k,v in pairs(map) do
                        if tostring(k):find("ds_entity_count",1,true) then n=tonumber(v); break end
                    end
                end
            end
        end
    end

    local good=(tonumber(n)~=nil and sent>0)
    if not good then n=tonumber(cache.count) or 0 end
    cache={
        count=tonumber(n) or 0,
        ok=good,
        updated_at=now,
        source=good and ("@e三维度 / "..tostring(sent).."维成功") or "沿用上次缓存",
    }
    r20k_entity_save(cache)
    return cache.count,cache.ok,cache.source
end

-- 公告栏：增加实体数量；仍然每60秒刷新。
function patch_sidebar_update(force)
    local now=util.timestamp()
    local gate=r20_notice_gate_load()
    local manual=(force=="manual")
    local gap=now-(tonumber(gate.last_update) or 0)
    if not manual and gap<60 then return true end

    gate.last_update=now
    r20_notice_gate_save(gate)

    local cfg=r20_notice_load()
    local day=r20j_daynight_update()
    local tps=tonumber(day and day.tps) or 20
    local tps_src=tostring(day and day.tps_source or "20TPS兜底")
    local entities,entity_ok=r20k_refresh_entity_count(manual)

    gate.last_tps=tps
    gate.last_tps_at=now
    gate.last_tps_source=tps_src
    r20_notice_gate_save(gate)

    local tm=(type(r13_beijing_time)=="function" and r13_beijing_time(now,false))
        or (type(patch_beijing_fmt)=="function" and patch_beijing_fmt(now))
        or tostring(now)

    local entity_text=entity_ok and tostring(entities) or (tostring(entities).."*")
    local lines={
        "§b§l✦ 服务器公告 ✦",
        "§f"..tostring(cfg.server_name or R20_DEFAULT_SERVER_NAME),
        "§fTPS：§a"..string.format("%.1f",tps),
        "§f游戏时间："..((day and day.phase=="夜晚") and "§9夜晚 " or "§e白天 ").."§f"..r20j_daynight_clock(day and day.ticks or 0),
        "§f在线：§a"..tostring(r20_online_count()),
        "§f实体：§a"..entity_text,
        "§f北京时间：§e"..tm,
        "§fQQ群：§b"..tostring(cfg.qq_group or R20_DEFAULT_GROUP),
        "§b帮助：§f.help",
    }

    pcall(game.sendCommand,'scoreboard objectives remove ds_notice')
    pcall(game.sendCommand,'scoreboard objectives add ds_notice dummy "§b公告栏"')
    local score=#lines
    for _,line in ipairs(lines) do
        pcall(game.sendCommand,'scoreboard players set "'..tostring(line):gsub('"','\\"')..'" ds_notice '..tostring(score))
        score=score-1
    end
    pcall(game.sendCommand,'scoreboard objectives setdisplay sidebar ds_notice')
    pcall(util.json_write,R20_NOTICE_LINES_FILE,{
        lines=lines,
        updated_at=now,
        tps=tps,
        tps_source=tps_src,
        entity_count=entities,
        entity_ok=entity_ok,
        game_ticks=day and day.ticks or 0,
        phase=day and day.phase or "白天",
    })
    return true
end

_R20K_PREV_CHAT = on_chat
function on_chat(playerName,msg)
    local low=lower(trim(tostring(msg or "")))

    if low==".实体数量" or low==".实体数" then
        local n,ok,src=r20k_refresh_entity_count(true)
        send(playerName,
            "§b━━ 实体数量 ━━\n"..
            "§f已加载实体：§a"..tostring(n).."\n"..
            "§f状态："..(ok and "§a实时检测成功" or "§e检测失败，显示最近缓存").."\n"..
            "§f来源：§7"..tostring(src or "")
        )
        return true
    end

    if low==".function内置检查" or low==".function文件检查" then
        if not is_admin(playerName) then send(playerName,"§c仅管理员可用。") return true end
        local a,sa=function_read_text("雪球菜单_综合功能.txt")
        local b,sb=function_read_text("FUNCTION_链级频率示例.txt")
        send(playerName,
            "§b━━ FUNCTION外部TXT检查 ━━\n"..
            "§f雪球菜单："..((a and #a>0) and "§a可读" or "§c不可读").." §7"..tostring(sa or "").."\n"..
            "§f频率示例："..((b and #b>0) and "§a可读" or "§c不可读").." §7"..tostring(sb or "").."\n"..
            "§8业务指令仅保存在TXT中，不再复制进main.lua。"
        )
        return true
    end

    return _R20K_PREV_CHAT(playerName,msg)
end

_R20K_PREV_INIT = on_init
function on_init()
    local ret=nil
    if type(_R20K_PREV_INIT)=="function" then
        local ok,v=pcall(_R20K_PREV_INIT)
        if ok then ret=v end
