-- 1.0.73 R20L：真实TXT落地（docs.md 资源载体）
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R20L"
FINAL_PATCH_TAG = "真实TXT落地_实体检测"

function r20l_docs_candidates()
    local out={}
    local cd=""
    pcall(function() cd=tostring(plugin_code_dir() or "") end)
    if cd~="" then
        out[#out+1]=cd.."/ds_ai_agent.docs.md"
        out[#out+1]=cd.."/docs.md"
    end
    local base=""
    pcall(function() base=tostring(plugin_base_dir() or "") end)
    if base~="" then
        out[#out+1]=base.."/插件文件/ds_ai_agent/ds_ai_agent.docs.md"
        out[#out+1]=base.."/插件文件/ds_ai_agent/docs.md"
    end
    return out
end

function r20l_extract_docs_resource(name)
    local begin="<!--R20L_FUNCTION_BEGIN:"..tostring(name).."\n"
    local ending="\nR20L_FUNCTION_END:"..tostring(name).."-->"
    for _,p in ipairs(r20l_docs_candidates()) do
        local ok,raw=pcall(util.read_file,p)
        if ok and type(raw)=="string" and #raw>0 then
            local a=raw:find(begin,1,true)
            if a then
                local start=a+#begin
                local b=raw:find(ending,start,true)
                if b and b>start then
                    local txt=raw:sub(start,b-1)
                    if trim(txt)~="" then
                        return txt,p
                    end
                end
            end
        end
    end
    return nil
end

-- 只认两类真实来源：
-- 1) 数据目录里已经存在的 TXT；
-- 2) 第一次运行时从 docs.md 资源区提取并落地。
function function_read_text(name)
    local path,n=function_file_path(name)
    if not path then return nil,n end

    local ok,v=pcall(util.read_file,path)
    if ok and type(v)=="string" and trim(v)~="" then
        return v,path
    end

    local seed,src=r20l_extract_docs_resource(tostring(n or ""))
    if type(seed)=="string" and trim(seed)~="" then
        local wok=pcall(util.write_file,path,seed)
        if wok then
            local ok2,verify=pcall(util.read_file,path)
            if ok2 and type(verify)=="string" and trim(verify)~="" then
                return verify,path.." <= "..tostring(src)
            end
        end
        -- 即使本次写盘失败，也允许先解析；但会明确标明未落地。
        return seed,"<docs资源，写盘失败> "..tostring(src)
    end

    return nil,"读取不到真实TXT："..tostring(n)
end

function r20l_materialize_builtin_txt()
    local result={}
    for _,name in ipairs({"雪球菜单_综合功能.txt","FUNCTION_链级频率示例.txt"}) do
        local txt,src=function_read_text(name)
        result[name]={ok=type(txt)=="string" and trim(txt)~="",source=src or ""}
        if result[name].ok then
            local doc=function_parse_document(txt,{require_end=true})
            result[name].parse_ok=(type(doc)=="table" and type(doc.errors)=="table" and #doc.errors==0)
            result[name].commands=(type(doc)=="table" and tonumber(doc.commands)) or 0
            result[name].chains=(type(doc)=="table" and tonumber(doc.chains)) or 0
        else
            result[name].parse_ok=false
        end
    end
    return result
end

