-- 1.0.73 R20P：雪球默认TXT升级
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R20P"
FINAL_PATCH_TAG = "时间运转_互传低头取消_下探叠20次"

function r20p_count_plain(hay,needle)
    hay=tostring(hay or ""); needle=tostring(needle or "")
    if needle=="" then return 0 end
    local n,p=0,1
    while true do
        local a=hay:find(needle,p,true)
        if not a then break end
        n=n+1; p=a+#needle
    end
    return n
end

function r20p_upgrade_snowball_txt()
    local path,name=function_file_path("雪球菜单_综合功能.txt")
    if not path then return false,tostring(name or "路径失败") end
    local ok,old=pcall(util.read_file,path)
    old=(ok and type(old)=="string") and old or ""
    if old:find("# 雪球菜单综合FUNCTION R20P：",1,true) then
        return true,"已经是R20P"
    end

    local repeated='/execute as @a[tag=return_surface] at @s run execute as @n[type=armor_stand,tag=surface_tp,x=-2000000,dx=4000000,y=-114514,dy=320000000,z=-2000000,dz=4000000] at @s if block ~ ~-1 ~ air run tp @s ~ ~-1 ~'
    -- 只自动覆盖我们自己之前下发的默认版本：R20G标记 + 40条重复下探。
    -- 用户自行改过结构的TXT不强制覆盖。
    local stock=(old=="") or (old:find("# 雪球菜单综合FUNCTION R20G：",1,true) and r20p_count_plain(old,repeated)==40)
    if not stock then return false,"检测到自定义TXT，未自动覆盖" end

    local seed,src=r20l_extract_docs_resource("雪球菜单_综合功能.txt")
    if type(seed)~="string" or trim(seed)=="" then return false,"R20P资源读取失败" end
    local wok,werr=pcall(util.write_file,path,seed)
    if not wok then return false,tostring(werr) end
    return true,tostring(src or path)
end

