-- 1.0.73 R20O CORE：单插件轻量 FUNCTION / 静默初始化
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R20O"
FINAL_PATCH_TAG = "单插件轻量20Hz_FUNCTION_静默启动"
FUNCTION_ENGINE_VERSION = "BOOTSTRAP_20HZ_V1"

-- FUNCTION 的执行由 tiny main.lua 中的 function_runtime_tick 负责。
-- 主体只负责 TXT 管理、编译、编辑、开关状态。
function function_fallback_tick()
    return true
end

function function_register_timers()
    return 0
end

function function_schedule_one(id)
    local item,d=function_registry_get(tonumber(id))
    if not item then return false,"文件编号不存在" end
    item.timer_registered=(item.enabled==true)
    item.timer_id=nil
    item.needs_reload=false
    function_registry_save(d)
    return true,"由单插件轻量20Hz执行核接管"
end

function function_cancel_old_timers()
    local n=0
    local ok,d=pcall(util.json_load,FUNCTION_TIMER_FILE)
    if ok and type(d)=="table" then
        for _,h in ipairs(d.ids or {}) do
            if tonumber(h) then pcall(util.cancel,tonumber(h)); n=n+1 end
        end
    end
    local ok2,s=pcall(util.json_load,FUNCTION_TIMER_STATE_FILE)
    if ok2 and type(s)=="table" then
        for _,h in pairs(s.items or {}) do
            if tonumber(h) then pcall(util.cancel,tonumber(h)); n=n+1 end
        end
    end
    pcall(util.json_write,FUNCTION_TIMER_FILE,{
        ids={},count=0,at=util.timestamp(),version=FINAL_PATCH_VERSION,
        note="R20O：FUNCTION高频执行由 bootstrap 轻量20Hz执行核接管"
    })
    pcall(util.json_write,FUNCTION_TIMER_STATE_FILE,{items={}})
    return n
end

function function_toggle(name,id)
    if not is_admin(name) then
        send(name,"§cFUNCTION系统仅管理员可管理。")
        return true
    end
    id=tonumber(id)
    local item,d=function_registry_get(id)
    if not item then send(name,"§c文件编号不存在。") return true end

    if item.enabled==true then
        item.enabled=false
        item.timer_registered=false
        item.needs_reload=false
        function_registry_save(d)
        send(name,"§a#"..tostring(id).." "..tostring(item.name).." 已停止。")
        return true
    end

    local okc,ec=function_compile_item(id)
    if not okc then
        send(name,"§c无法开启，TXT语法/读取失败："..tostring(ec))
        return true
    end
    item,d=function_registry_get(id)
    item.enabled=true
    item.loaded=true
    item.missing=false
    item.timer_registered=true
    item.needs_reload=false
    item.activation_seq=(tonumber(item.activation_seq) or 0)+1
    item.runtime_pulse_done_seq=nil
    function_registry_save(d)

    local hzset={}
    for _,node in ipairs(item.compiled_nodes or {}) do
        local st=node.state or {}
        local kind=tonumber(st.kind) or 1
        if kind~=1 then
            local hz=tonumber(st.hz)
            if hz and hz>0 then hzset[string.format("%.8g",hz)]=true end
        end
    end
    local rates={}
    for hz in pairs(hzset) do rates[#rates+1]=hz.."Hz" end
    table.sort(rates)
    send(name,
        "§a#"..tostring(id).." "..tostring(item.name).." 已开启。\n"..
        "§f执行器：§a单插件轻量20Hz核心\n"..
        "§f链频率：§b"..(#rates>0 and table.concat(rates," / ") or "默认20Hz")
    )
    return true
end

-- 最终初始化不再调用历史上层层包裹的 on_init，避免一次启动重复执行几十段初始化。
function on_init()
    -- 先静默关闭命令回显，后续初始化指令不会刷屏。
    pcall(game.isCmdSuccess,"gamerule sendcommandfeedback false")
    pcall(game.isCmdSuccess,"gamerule commandblockoutput false")

    pcall(game.setConfigDefault,{
        ai_key="",
        ai_model=AI_MODEL,
        ai_thinking=false,
        deepseek_key="",
        deepseek_url=DEEPSEEK_URL,
        death_tp_cost=100,
        web_search_key="",
        web_search_url=WEB_SEARCH_URL,
        web_search_model=WEB_SEARCH_MODEL,
        seed_engine_url=SEED_FINDER_URL,
        seed_engine_account="",
        seed_engine_password="",
        seed_engine_token="",
    })

    -- 必要的数据迁移/初始化，各执行一次，不向玩家发送提示。
    pcall(reset_ai_session_on_plugin_start)
    pcall(migrate_player_keys)
    pcall(coord_soul_state_migrate)
    pcall(init_scoreboard)
    pcall(mute_exempt_load)
    pcall(mute_cfg)
    pcall(ensure_defaults_json)
    pcall(guild_init_files)
    pcall(ensure_patch_prompt_files)
    pcall(r20l_materialize_builtin_txt)
    pcall(r20j_register_builtin_functions)
    pcall(function_scan_files,true)
    pcall(function_cancel_old_timers)

    -- FUNCTION 轻量执行核使用的内部计分板。
    pcall(game.isCmdSuccess,"scoreboard objectives add ds_fnclock dummy")

    -- 昼夜初始化仍按 R20J：首次 schema 初始化时 /time set 0。
    pcall(r20j_daynight_init)
    -- R20P：启动时主动重建一次公告栏，避免沿用旧行后时间不刷新。
    pcall(patch_sidebar_update,"manual")

    -- 主体自身只保留原来 v29 的 1 秒主心跳。
    pcall(register_periodic_tasks)

    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",
        FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    pcall(log_event,"SYSTEM","R20O quiet init complete")
end


