-- R20Q：死亡检测恢复
-- 重新接回 Text + PlayerLocation + PyRpc 三路死亡信号。
-- 单插件 tiny bootstrap 已补齐 v17_event_tick / 死亡采样 handler 代理。
-- 继续使用 v29 唯一1秒主心跳；死亡采样/兜底在其内部每3秒执行。
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R20Q"
FINAL_PATCH_TAG = "死亡检测恢复_下探再叠50次"

R20O_TICK_SEC = 0.05
R20O_CLOCK_OBJ = "ds_fnclock"
R20O_THRESHOLD = 20000000

function r20o_trim(s)
    return (tostring(s or ""):gsub("^%s+",""):gsub("%s+$",""))
end

function r20o_cmd(s)
    s=r20o_trim(s)
    if s:sub(1,1)=="/" then s=s:sub(2) end
    return s
end

function r20o_registry_file()
    return game.dataDir().."/function_registry.json"
end

function r20o_registry()
    local ok,d=pcall(util.json_load,r20o_registry_file())
    if ok and type(d)=="table" then
        d.items=d.items or {}
        return d
    end
    return {items={}}
end

function r20o_save_registry(d)
    pcall(util.json_write,r20o_registry_file(),d or {items={}})
end

function r20o_chain_map(nodes)
    local order,map={},{}
    for _,node in ipairs(nodes or {}) do
        local cid=tostring(tonumber(node.chain_id) or 1)
        if not map[cid] then
            map[cid]={id=tonumber(node.chain_id) or 1,nodes={}}
            order[#order+1]=cid
        end
        map[cid].nodes[#map[cid].nodes+1]=node
    end
    return order,map
end

function r20o_chain_hz(chain,item)
    local hz=nil
    for _,node in ipairs(chain.nodes or {}) do
        local v=tonumber(node and node.state and node.state.hz)
        if v and v>0 then hz=v break end
    end
    if not hz then
        local delay=tonumber(item and item.delay_sec) or 0.05
        if delay<=0 then delay=0.05 end
        hz=1/delay
    end
    if hz>20 then hz=20 end
    if hz<0.00001 then hz=0.00001 end
    return hz
end

function r20o_send(cmd,need_result)
    cmd=r20o_cmd(cmd)
    if cmd=="" then return false,false end
    if need_result then
        local ok,res=pcall(game.isCmdSuccess,cmd)
        if ok then return true,res==true end
        local ok2=pcall(game.sendCommand,cmd)
        return ok2,false
    end
    local ok=pcall(game.sendCommand,cmd)
    return ok,nil
end

function r20o_execute_nodes(nodes,item,gate_prefix,gate_mode)
    local prev_success=nil
    local prev_activated=true
    for i,node in ipairs(nodes or {}) do
        local st=node.state or {}
        local kind=tonumber(st.kind) or 1
        local conditional=tonumber(st.conditional) or 0
        local needs_redstone=(tonumber(st.redstone) or 0)==1
        local execute=true
        if i>1 and kind==0 and prev_activated~=true then execute=false end
        if execute and needs_redstone and item.powered~=true then execute=false end
        if execute and conditional==1 and prev_success~=true then execute=false end

        if execute then
            local actual=r20o_cmd(node.command)
            if gate_mode=="periodic" then
                actual='execute if score "'..gate_prefix..'" '..R20O_CLOCK_OBJ..
                    ' matches '..tostring(R20O_THRESHOLD)..'.. run '..actual
            elseif gate_mode=="pulse" then
                local seq=tonumber(item.activation_seq) or 0
                actual='execute unless score "'..gate_prefix..'" '..R20O_CLOCK_OBJ..
                    ' matches '..tostring(seq)..' run '..actual
            end

            local nextnode=nodes[i+1]
            local next_cond=nextnode and tonumber((nextnode.state or {}).conditional)==1
            local dispatched,success=r20o_send(actual,next_cond==true)
            prev_activated=(dispatched==true)
            prev_success=(next_cond==true) and (success==true) or nil
        else
            prev_activated=false
            prev_success=false
        end
    end
end

function r20o_execute_chain(fid,item,chain,registry)
    local nodes=chain.nodes or {}
    if #nodes==0 then return end
    local fst=(nodes[1] and nodes[1].state) or {}
    local kind=tonumber(fst.kind) or 1
    local cid=tonumber(chain.id) or 1

    if kind==1 then
        local seq=tonumber(item.activation_seq) or 0
        local done=tonumber(item.runtime_pulse_done_seq)
        if done==seq then return end
        local mark="P"..tostring(fid).."C"..tostring(cid)
        r20o_execute_nodes(nodes,item,mark,"pulse")
        pcall(game.sendCommand,'scoreboard players set "'..mark..'" '..R20O_CLOCK_OBJ..' '..tostring(seq))
        item.runtime_pulse_done_seq=seq
        registry.__dirty=true
        return
    end

    local hz=r20o_chain_hz(chain,item)
    if hz>=19.9999 then
        r20o_execute_nodes(nodes,item,nil,nil)
        return
    end

    -- Fractional accumulator: add hz*1,000,000 per 20Hz host tick.
    -- Threshold is 20,000,000, so arbitrary frequencies keep the correct average.
    local step=math.max(1,math.floor(hz*1000000+0.5))
    local mark="F"..tostring(fid).."C"..tostring(cid)
    pcall(game.sendCommand,'scoreboard players add "'..mark..'" '..R20O_CLOCK_OBJ..' '..tostring(step))
    r20o_execute_nodes(nodes,item,mark,"periodic")
    pcall(game.sendCommand,
        'execute if score "'..mark..'" '..R20O_CLOCK_OBJ..' matches '..tostring(R20O_THRESHOLD)..
        '.. run scoreboard players remove "'..mark..'" '..R20O_CLOCK_OBJ..' '..tostring(R20O_THRESHOLD))
end

function function_runtime_tick()
    local reg=r20o_registry()
    reg.__dirty=false
    for id,item in pairs(reg.items or {}) do
        if type(item)=="table"
            and item.enabled==true
            and item.loaded~=false
            and item.missing~=true
            and type(item.compiled_nodes)=="table" then
            local order,map=r20o_chain_map(item.compiled_nodes)
            for _,cid in ipairs(order) do
                r20o_execute_chain(tonumber(id),item,map[cid],reg)
            end
        end
    end
    if reg.__dirty then
        reg.__dirty=nil
        r20o_save_registry(reg)
    end
end



-- ============================================================
-- R20P 轻量游戏时钟：不加载大主体
-- ============================================================
R20P_DAY_FILE = game.dataDir().."/daynight_clock_r20j.json"
R20P_NOTICE_FILE = game.dataDir().."/server_announcement_lines.json"
R20P_CLOCK_STATE = game.dataDir().."/r20p_clock_state.json"

function r20p_json(path,default)
    local ok,d=pcall(util.json_load,path)
    if ok and type(d)=="table" then return d end
    return default or {}
end

function r20p_game_clock(ticks)
    local t=(tonumber(ticks) or 0)%24000
    local mins=math.floor(((6*60)+(t*60/1000))%(24*60))
    return string.format("%02d:%02d",math.floor(mins/60),mins%60)
end

function r20p_clock_tick()
    local now=tonumber(util.timestamp()) or 0
    local d=r20p_json(R20P_DAY_FILE,{})
    if tonumber(d.schema)~=2 then return end

    local last=tonumber(d.last_real) or now
    local elapsed=math.max(0,now-last)
    if elapsed>180 then elapsed=60 end
    local tps=tonumber(d.tps) or 20
    if tps<=0 or tps>20.5 then tps=20 end
    if elapsed>0 then
        d.ticks=((tonumber(d.ticks) or 0)+(elapsed*tps))%24000
        d.last_real=now
    end

    local old=tostring(d.phase or "白天")
    local phase=(d.ticks>=13000 and d.ticks<23000) and "夜晚" or "白天"
    d.phase=phase
    d.updated_at=now
    pcall(util.json_write,R20P_DAY_FILE,d)

    if phase~=old then
        if phase=="夜晚" then
            pcall(game.sendCommand,"title @a title 夜幕降临")
            pcall(game.sendCommand,"gamerule keepinventory false")
        else
            pcall(game.sendCommand,"title @a title 冉冉升起")
            pcall(game.sendCommand,"gamerule keepinventory true")
        end
    end

    local st=r20p_json(R20P_CLOCK_STATE,{})
    if now-(tonumber(st.sidebar_at) or 0)<5 then return end
    st.sidebar_at=now
    pcall(util.json_write,R20P_CLOCK_STATE,st)

    local notice=r20p_json(R20P_NOTICE_FILE,{})
    local lines=notice.lines
    if type(lines)~="table" then return end
    for i,oldline in ipairs(lines) do
        if tostring(oldline):find("§f游戏时间：",1,true)==1 then
            local newline="§f游戏时间："..(phase=="夜晚" and "§9夜晚 " or "§e白天 ").."§f"..r20p_game_clock(d.ticks)
            if newline~=oldline then
                local score=#lines-i+1
                pcall(game.sendCommand,'scoreboard players reset "'..tostring(oldline):gsub('"','\\"')..'" ds_notice')
                pcall(game.sendCommand,'scoreboard players set "'..tostring(newline):gsub('"','\\"')..'" ds_notice '..tostring(score))
                lines[i]=newline
                notice.lines=lines
                notice.game_ticks=d.ticks
                notice.phase=phase
                notice.updated_at=now
                pcall(util.json_write,R20P_NOTICE_FILE,notice)
            end
            break
        end
    end
end

