function r20w_docs_paths()
    local out={}
    local cd=""
    pcall(function() cd=tostring(plugin_code_dir() or "") end)
    if cd~="" then
        out[#out+1]=cd.."/ds_ai_agent.docs.md"
        out[#out+1]=cd.."/docs.md"
    end
    local base=""
    pcall(function() base=tostring(plugin_base_dir() or "") end)
    if base~="" then
        out[#out+1]=base.."/插件文件/ds_ai_agent/ds_ai_agent.docs.md"
        out[#out+1]=base.."/插件文件/ds_ai_agent/docs.md"
    end
    return out
end

function r20w_resource_from_docs(name)
    local begin="R20W_RESOURCE_BEGIN:"..tostring(name).."\n"
    local ending="\nR20W_RESOURCE_END:"..tostring(name)
    for _,p in ipairs(r20w_docs_paths()) do
        local ok,raw=pcall(util.read_file,p)
        if ok and type(raw)=="string" and #raw>0 then
            local a=raw:find(begin,1,true)
            if a then
                a=a+#begin
                local b=raw:find(ending,a,true)
                if b and b>a then return raw:sub(a,b-1),p end
            end
        end
    end
    return nil
end

