-- ------------------------------------------------------------
FUNCTION_BUNDLED_TXT = {
    ["雪球菜单_综合功能.txt"]="雪球菜单_综合功能.txt",
    ["药水系统.txt"]="药水系统.txt",
}

function function_scan_shell_names()
    return {},false
end

function function_read_text(name)
    local path,n=function_file_path(name)
    if not path then return nil,n end

    local ok,v=pcall(util.read_file,path)
    if ok and type(v)=="string" and trim(v)~="" then
        return v,path
    end

    local bundled=FUNCTION_BUNDLED_TXT[tostring(n or "")]
    if bundled then
        local dd=tostring(game.dataDir() or "")
        local dp=dd.."/command_txt/"..bundled
        local ok2,v2=pcall(util.read_file,dp)
        if ok2 and type(v2)=="string" and trim(v2)~="" then
            return v2,dp
        end

        local cd=""
        pcall(function() cd=tostring(plugin_code_dir() or "") end)
        if cd~="" then
            local cp=cd.."/command_txt/"..bundled
            local ok3,v3=pcall(util.read_file,cp)
            if ok3 and type(v3)=="string" and trim(v3)~="" then
                pcall(util.write_file,dp,v3)
                return v3,cp
            end
        end

        local raw,src=r20w_resource_from_docs("command_txt/"..bundled)
        if type(raw)=="string" and trim(raw)~="" then
            pcall(util.write_file,dp,raw)
            return raw,"docs:"..tostring(src or "")
        end
    end
    return nil,"读取不到TXT："..tostring(n)
end

function function_scan_files(silent)
    pcall(r20w_seed_resources)
    local d=function_registry_load()
    local names={}
    local seen={}

    -- 已登记文件仍然保留，只要真实可读。
    for _,x in ipairs(function_registry_sorted(d,true)) do
        local n=tostring(x.item.name or "")
        if n~="" then
            local txt=function_read_text(n)
            if txt then names[#names+1]=n end
        end
    end

    -- 两个正式 FUNCTION 始终加入。
    for _,n in ipairs({"雪球菜单_综合功能.txt","药水系统.txt"}) do
        local txt=function_read_text(n)
        if txt then names[#names+1]=n end
    end

    table.sort(names)
    local byname={}
    for id,it in pairs(d.items or {}) do
        if type(it)=="table" and tostring(it.name or "")~="" then
            byname[tostring(it.name)]=tostring(id)
        end
    end

    for _,n in ipairs(names) do
        if not seen[n] then
            seen[n]=true
            local id=byname[n]
            if not id then
                local nextid=tonumber(d.next_id) or 1
                while d.items[tostring(nextid)] and nextid<=FUNCTION_MAX_FILES do
                    nextid=nextid+1
                end
                if nextid<=FUNCTION_MAX_FILES then
                    d.items[tostring(nextid)]={
                        id=nextid,name=n,enabled=false,loaded=true,
                        delay_sec=FUNCTION_DEFAULT_DELAY,powered=false,
                        missing=false,created_at=util.timestamp(),
                        timer_registered=false,needs_reload=false,
                    }
                    d.next_id=nextid+1
                end
            else
                d.items[id].missing=false
            end
        end
    end

    for id,it in pairs(d.items or {}) do
        if type(it)=="table" then
            it.missing=not seen[tostring(it.name or "")]
        end
    end
    function_registry_save(d)

    local count=0
    for _,_ in ipairs(function_registry_sorted(d,false)) do count=count+1 end
    if not silent then
        return true,"安全扫描完成，共找到 "..tostring(count).." 个 TXT。"
    end
    return true,d,false
end

function function_show_main(name)
    if not is_admin(name) then
        send(name,"§cFUNCTION命令链系统仅管理员可使用。")
        return true
    end
    local ok,msg=pcall(function_scan_files,false)
    if not ok then
        send(name,"§cFUNCTION扫描失败："..tostring(msg))
        return true
    end
    local d=function_registry_load()
    local arr=function_registry_sorted(d,false)
    local run=0
    for _,x in ipairs(arr) do if x.item.enabled then run=run+1 end end
    local lines={
        "§8━━━━━━━━━━━━━━━━━━━━━━━━",
        "§b§lFUNCTION 管理",
        "§8━━━━━━━━━━━━━━━━━━━━━━━━",
        "§fTXT文件：§e"..#arr.."  §f运行：§a"..run.."  §f停止：§c"..(#arr-run),
    }
    for _,x in ipairs(arr) do
        local hz=1/(tonumber(x.item.delay_sec) or FUNCTION_DEFAULT_DELAY)
        lines[#lines+1]=string.format(
            "§f%d. §e%s §8| %s §8| §7%.5gHz",
            x.id,tostring(x.item.name),function_file_status_label(x.item),hz
        )
    end
    if #arr==0 then
        lines[#lines+1]="§7未读取到 FUNCTION TXT。"
    end
    local d0,r=player_record(name,true)
    r.function_active=true
    set_menu(d0,r,"function_main")
    save_data(d0)
    function_send_chunked(name,table.concat(lines,"\n"),FUNCTION_CHAT_CHUNK)
    return true
end

