-- 北京时间 / 十二时辰 / 二十四节气 / 节日
-- ------------------------------------------------------------
function r20w_real_time(ts)
    local now=tonumber(ts) or tonumber(util.timestamp()) or 0
    local ok,t=pcall(os.date,"!*t",now+8*3600)
    if not ok or type(t)~="table" then
        return {year=1970,month=1,day=1,hour=0,min=0,yday=1,
                date="1970-01-01",md="01-01",hm="00:00"}
    end
    return {
        year=tonumber(t.year) or 1970,
        month=tonumber(t.month) or 1,
        day=tonumber(t.day) or 1,
        hour=tonumber(t.hour) or 0,
        min=tonumber(t.min) or 0,
        sec=tonumber(t.sec) or 0,
        yday=tonumber(t.yday) or 1,
        wday=tonumber(t.wday) or 1,
        date=string.format("%04d-%02d-%02d",t.year,t.month,t.day),
        md=string.format("%02d-%02d",t.month,t.day),
        hm=string.format("%02d:%02d",t.hour,t.min),
    }
end

function r20w_shichen(hour)
    local h=tonumber(hour) or 0
    local arr={"子时","丑时","寅时","卯时","辰时","巳时","午时","未时","申时","酉时","戌时","亥时"}
    local idx
    if h==23 or h==0 then idx=1 else idx=math.floor((h+1)/2)+1 end
    if idx<1 then idx=1 end
    if idx>12 then idx=12 end
    return arr[idx]
end

