function r20w_term_day(year,term)
    local y=(tonumber(year) or 2000)%100
    return math.floor(y*0.2422+(tonumber(term[3]) or 0))-math.floor((y-1)/4)
end

function r20w_solar_term(rt)
    local current=nil
    local today=(tonumber(rt.month) or 1)*100+(tonumber(rt.day) or 1)
    for _,term in ipairs(R20W_SOLAR_TERMS) do
        local day=r20w_term_day(rt.year,term)
        local idx=(tonumber(term[2]) or 1)*100+day
        if idx<=today then
            current={name=term[1],month=term[2],day=day,phrase=term[4],is_today=(idx==today)}
        end
    end
    if not current then
        local term=R20W_SOLAR_TERMS[#R20W_SOLAR_TERMS]
        current={name=term[1],month=term[2],day=r20w_term_day(rt.year-1,term),
                 phrase=term[4],is_today=false}
    end
    return current
end

R20W_LUNAR_HOLIDAYS={
    [2026]={spring="02-17",dragon="06-19",mid="09-25"},
    [2027]={spring="02-06",dragon="06-09",mid="09-15"},
    [2028]={spring="01-26",dragon="05-28",mid="10-03"},
    [2029]={spring="02-13",dragon="06-16",mid="09-22"},
    [2030]={spring="02-03",dragon="06-05",mid="09-12"},
    [2031]={spring="01-23",dragon="06-24",mid="10-01"},
    [2032]={spring="02-11",dragon="06-12",mid="09-19"},
    [2033]={spring="01-31",dragon="06-01",mid="09-08"},
    [2034]={spring="02-19",dragon="06-20",mid="09-27"},
    [2035]={spring="02-08",dragon="06-10",mid="09-16"},
}

function r20w_holiday(rt,term)
    local out={}
    if rt.md=="01-01" then out[#out+1]="元旦" end
    if term and term.name=="清明" and term.is_today then out[#out+1]="清明节" end
    if rt.md=="05-01" then out[#out+1]="劳动节" end
    if rt.md=="10-01" then out[#out+1]="国庆节" end
    local y=R20W_LUNAR_HOLIDAYS[tonumber(rt.year)]
    if type(y)=="table" then
        if rt.md==y.spring then out[#out+1]="春节" end
        if rt.md==y.dragon then out[#out+1]="端午节" end
        if rt.md==y.mid then out[#out+1]="中秋节" end
    end
    return table.concat(out,"、")
end

-- ------------------------------------------------------------
-- 游戏时间：丰富阶段词 + keepInventory
-- 13000~22999：死亡掉落；其余：死亡不掉落。
-- ------------------------------------------------------------
function r20w_game_phase(ticks)
    local t=(tonumber(ticks) or 0)%24000
    local p
    if t<1000 then
        p={id="dawn",name="破晓",keep=true,title="§6破晓",subtitle="§e晨光冉冉升起"}
    elseif t<2500 then p={id="morning_glow",name="晨曦",keep=true}
    elseif t<5000 then p={id="sunrise",name="旭日初升",keep=true}
    elseif t<7500 then p={id="day",name="白昼",keep=true}
    elseif t<9000 then p={id="noon",name="日正当空",keep=true,title="§e日正当空",subtitle="§f白昼正盛"}
    elseif t<11000 then p={id="afternoon",name="午后",keep=true}
    elseif t<12000 then p={id="sunset",name="夕照",keep=true}
    elseif t<12500 then p={id="evening",name="傍晚",keep=true,title="§6夕阳西沉",subtitle="§e晚霞渐染天际"}
    elseif t<13000 then p={id="dusk",name="黄昏",keep=true}
    elseif t<14500 then p={id="twilight",name="暮色",keep=false,title="§5暮色四合",subtitle="§d夜幕降临，死亡掉落已开启"}
    elseif t<17000 then p={id="nightfall",name="夜幕初临",keep=false}
    elseif t<19000 then p={id="night",name="夜晚",keep=false}
    elseif t<21000 then p={id="midnight",name="子夜",keep=false,title="§1子夜已至",subtitle="§9死亡掉落"}
    elseif t<23000 then p={id="late_night",name="深夜",keep=false}
    else p={id="predawn",name="黎明前",keep=true,title="§b长夜将尽",subtitle="§f黎明将至，死亡不掉落已开启"} end
    p.rule=p.keep and "死亡不掉落" or "死亡掉落"
    p.rule_color=p.keep and "§a" or "§c"
    return p
end

function r20w_game_clock(ticks)
    local t=(tonumber(ticks) or 0)%24000
    local total=math.floor(((6*60)+(t*60/1000))%(24*60))
    return string.format("%02d:%02d",math.floor(total/60),total%60)
end

function r20w_screen(title,subtitle,target)
    target=target or "@a"
    pcall(game.sendCommand,"title "..target.." times 10 60 15")
    if tostring(title or "")~="" then
        pcall(game.sendCommand,"title "..target.." title "..tostring(title))
    end
    if tostring(subtitle or "")~="" then
        pcall(game.sendCommand,"title "..target.." subtitle "..tostring(subtitle))
    end
end

function r20w_game_update()
    local d=r20j_daynight_init()
    local now=tonumber(util.timestamp()) or 0
    local last=tonumber(d.last_real) or now
    local elapsed=math.max(0,now-last)
    if elapsed>180 then elapsed=60 end
    local tps,src=r20j_effective_tps()
    if elapsed>0 then
        d.ticks=((tonumber(d.ticks) or 0)+(elapsed*tps))%24000
        d.last_real=now
    end

    local old_stage=tostring(d.stage_id or "")
    local old_keep=d.keepinventory
    local p=r20w_game_phase(d.ticks)

    d.stage_id=p.id
    d.stage_name=p.name
    d.phase=p.keep and "白天" or "夜晚"
    d.keepinventory=p.keep
    d.tps=tps
    d.tps_source=src
    d.updated_at=now
    pcall(util.json_write,R20J_DAYNIGHT_FILE,d)

    if old_stage~="" and old_stage~=p.id and p.title then
        r20w_screen(p.title,p.subtitle,"@a")
    end

    local st=r20w_json(R20W_STATE_FILE,{})
    if old_keep==nil or old_keep~=p.keep or now-(tonumber(st.rule_at) or 0)>=30 then
        pcall(game.sendCommand,p.keep and "gamerule keepinventory true" or "gamerule keepinventory false")
        st.rule_at=now
        pcall(util.json_write,R20W_STATE_FILE,st)
    end
    return d,p
end

function r20j_daynight_update()
    local d=r20w_game_update()
    return d
end

function r20j_daynight_clock(ticks)
    return r20w_game_clock(ticks)
end

