function r20w_pick(arr,seed)
    if type(arr)~="table" or #arr==0 then return "" end
    return tostring(arr[(math.floor(tonumber(seed) or 0)%#arr)+1] or "")
end

function r20w_greeting(rt,id)
    local arr=R20W_GREETINGS[id] or R20W_GREETINGS.morning
    local seed=(tonumber(rt.year) or 0)*1009+(tonumber(rt.yday) or 0)*97+#id*53
    return r20w_pick(arr,seed)
end

function r20w_real_events(now)
    local rt=r20w_real_time(now)
    local st=r20w_json(R20W_STATE_FILE,{})
    st.greet_done=st.greet_done or {}
    st.special_done=st.special_done or {}

    if st.real_date~=rt.date then
        st.real_date=rt.date
        st.greet_done={}
        st.special_done={}
    end

    for _,slot in ipairs(R20W_GREETING_SLOTS) do
        if rt.hour==slot.hour and rt.min==slot.min and not st.greet_done[slot.id] then
            r20w_screen(slot.title,"§f"..r20w_greeting(rt,slot.id),"@a")
            st.greet_done[slot.id]=true
        end
    end

    local term=r20w_solar_term(rt)
    local holiday=r20w_holiday(rt,term)

    if rt.hour>=8 and holiday~="" and not st.special_done.holiday then
        r20w_screen("§6"..holiday,"§f今天是"..holiday.."，愿今天轻松顺利","@a")
        st.special_done.holiday=true
    end
    if rt.hour>=8 and term and term.is_today and not st.special_done.term then
        r20w_screen("§e今日"..term.name,"§f"..tostring(term.phrase or ""),"@a")
        st.special_done.term=true
    end

    pcall(util.json_write,R20W_STATE_FILE,st)
end

