function patch_sidebar_update(force)
    local now=tonumber(util.timestamp()) or 0
    local gate=r20_notice_gate_load()
    local manual=(force=="manual" or force==true)
    if not manual and now-(tonumber(gate.last_update) or 0)<60 then return true end
    gate.last_update=now
    r20_notice_gate_save(gate)

    local cfg=r20_notice_load()
    local day,phase=r20w_game_update()
    local rt=r20w_real_time(now)
    local term=r20w_solar_term(rt)
    local holiday=r20w_holiday(rt,term)
    local entities,entity_ok=r20k_refresh_entity_count(manual)
    local entity_text=entity_ok and tostring(entities) or (tostring(entities).."*")
    local tps=tonumber(day and day.tps) or 20

    local lines={
        "§3§l疣螈服务器状态",
        "§f"..tostring(cfg.server_name or R20_DEFAULT_SERVER_NAME),
        "§7游戏 §f"..r20w_game_clock(day and day.ticks or 0).." §7"..phase.name,
        "§7规则 "..phase.rule_color..phase.rule,
        "§7现实 §f"..rt.md.." "..rt.hm.." §7"..r20w_shichen(rt.hour),
        "§7节气 §f"..tostring(term and term.name or ""),
    }
    if holiday~="" then lines[#lines+1]="§7节日 §6"..holiday end
    lines[#lines+1]="§7TPS §a"..string.format("%.1f",tps).." §7在线 §a"..tostring(r20_online_count())
    lines[#lines+1]="§7实体 §a"..entity_text
    lines[#lines+1]="§7QQ群 §b"..tostring(cfg.qq_group or R20_DEFAULT_GROUP)
    lines[#lines+1]="§b.help §7查看功能"

    yy_notice_diff(lines)
    pcall(util.json_write,R20W_NOTICE_FILE,{lines=lines,updated_at=now})
    return true
end

function r20w_time_status_text()
    local now=tonumber(util.timestamp()) or 0
    local day,phase=r20w_game_update()
    local rt=r20w_real_time(now)
    local term=r20w_solar_term(rt)
    local holiday=r20w_holiday(rt,term)
    local lines={
        "§8━━━━━━━━━━━━━━━━━━━━━━━━",
        "§b时间状态",
        "§7北京时间 §f"..rt.date.." "..rt.hm.." §7"..r20w_shichen(rt.hour),
        "§7节气 §f"..tostring(term and term.name or ""),
        "§7游戏时间 §f"..r20w_game_clock(day and day.ticks or 0).." §7"..phase.name,
        "§7掉落规则 "..phase.rule_color..phase.rule,
    }
    if holiday~="" then lines[#lines+1]="§7节日 §6"..holiday end
    lines[#lines+1]="§8━━━━━━━━━━━━━━━━━━━━━━━━"
    return table.concat(lines,"\n")
end

