-- ------------------------------------------------------------
-- 最终聊天入口：.help / .function / 时间查询直接走明确函数。
-- 其它全部交回原完整主体。
-- ------------------------------------------------------------
R20W_PREV_CHAT=on_chat
function on_chat(playerName,msg)
    local raw=trim(tostring(msg or ""))
    local low=lower(raw)

    if low==".help" or low=="help" then
        local ok,err=pcall(show_help,playerName)
        if not ok then
            pcall(log_event,"MENU","help异常："..tostring(err))
            send(playerName,"§c主菜单异常："..tostring(err))
        end
        return true
    end

    if low==".function" or low=="function" or low==".函数" then
        local ok,err=pcall(function_show_main,playerName)
        if not ok then
            pcall(log_event,"FUNCTION","R20W入口异常："..tostring(err))
            send(playerName,"§cFUNCTION入口异常："..tostring(err))
        end
        return true
    end

    if low==".时间" or low==".现实时间" or low==".游戏时间" or low==".昼夜" then
        send(playerName,r20w_time_status_text())
        return true
    end

    if type(R20W_PREV_CHAT)=="function" then
        return R20W_PREV_CHAT(playerName,msg)
    end
    return false
end

R20W_PREV_INIT=on_init
function on_init()
    local ret=nil
    if type(R20W_PREV_INIT)=="function" then
        local ok,v=pcall(R20W_PREV_INIT)
        if ok then ret=v end
    end

    pcall(r20w_seed_resources)
    pcall(function_scan_files,true)
    pcall(r20w_game_update)
    pcall(patch_sidebar_update,"manual")
    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",
        FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    return ret
end

