-- 1.0.73 R20X
-- 死亡检测三路兜底 + FUNCTION稳定性修复
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R20X"
FINAL_PATCH_TAG = "死亡检测三路兜底_FUNCTION稳定修复"

R20X_MASTER_TIMER_FILE = game.dataDir().."/function_master_timer_r20x.json"
R20X_MASTER_LOCK_FILE  = game.dataDir().."/function_master_lock_r20x.json"
R20X_DEATH_DIAG_FILE   = game.dataDir().."/death_diag_r20x.json"

-- ---------- FUNCTION：空闲时不提交110条返回地面下探 ----------
R20X_OLD_ROUND_DISPATCH = function_round_dispatch
function function_round_dispatch(cmd,need_result)
    local raw=tostring(cmd or "")
    if raw:find("tag=return_surface",1,true)
        and raw:find("tag=surface_tp",1,true)
        and raw:find("if block ~ ~-1 ~ air run tp @s ~ ~-1 ~",1,true) then

        if R20X_SURFACE_ACTIVE_CACHE==nil then
            local ok,hit=pcall(game.isCmdSuccess,'testfor @a[tag="return_surface"]')
            R20X_SURFACE_ACTIVE_CACHE=(ok and hit==true)
        end
        if not R20X_SURFACE_ACTIVE_CACHE then
            return true,nil,"idle-skip","返回地面未激活，跳过重下探"
        end
    end
    return R20X_OLD_ROUND_DISPATCH(cmd,need_result)
end

R20X_OLD_EXEC_FILE = function_execute_file_id
function function_execute_file_id(id,debug_mode)
    R20X_SURFACE_ACTIVE_CACHE=nil
    return R20X_OLD_EXEC_FILE(id,debug_mode)
end

function r20x_master_timer_load()
    local ok,d=pcall(util.json_load,R20X_MASTER_TIMER_FILE)
    if ok and type(d)=="table" then return d end
    return {}
end

function r20x_master_timer_save(d)
    pcall(util.json_write,R20X_MASTER_TIMER_FILE,d or {})
end

function r20x_cancel_master_timer()
    local d=r20x_master_timer_load()
    local h=tonumber(d.id)
    if h then pcall(util.cancel,h) end
    r20x_master_timer_save({id=nil,enabled=false,at=util.timestamp()})
end

function r20x_any_function_enabled()
    local d=function_registry_load()
    for _,it in pairs(d.items or {}) do
        if type(it)=="table" and it.enabled==true and it.loaded~=false and it.missing~=true then
            return true
        end
    end
    return false
end

-- 文件锁防止上一轮还没结束，下一轮又重入。
-- 崩溃留下的锁超过2秒自动视为陈旧。
function r20x_master_lock_acquire()
    local now=tonumber(util.timestamp()) or 0
    local ok,d=pcall(util.json_load,R20X_MASTER_LOCK_FILE)
    if ok and type(d)=="table" and d.running==true then
        local age=now-(tonumber(d.at) or 0)
        if age<=2 then return false end
    end
    pcall(util.json_write,R20X_MASTER_LOCK_FILE,{running=true,at=now})
    return true
end

function r20x_master_lock_release()
    pcall(util.json_write,R20X_MASTER_LOCK_FILE,{running=false,at=util.timestamp()})
end

function function_master_tick()
    if not r20x_master_lock_acquire() then return false end

    local ok,err=pcall(function()
        local d=function_registry_load()
        for _,x in ipairs(function_registry_sorted(d,false)) do
            local it=x.item
            if type(it)=="table" and it.enabled==true and it.loaded~=false and it.missing~=true then
                pcall(function_execute_file_id,x.id,false)
            end
        end
    end)

    r20x_master_lock_release()
    if not ok then
        pcall(log_event,"FUNCTION","R20X master tick异常："..tostring(err))
    end
    return ok
end

function r20x_ensure_master_timer(force)
    if force then r20x_cancel_master_timer() end
    if not r20x_any_function_enabled() then
        r20x_cancel_master_timer()
        return true,"没有运行中的FUNCTION"
    end

    local d=r20x_master_timer_load()
    if not force and tonumber(d.id) and d.enabled==true then
        return true,tonumber(d.id)
    end

    local ok,h=false,"R21A已禁用R20X主计时器"
    if ok and type(h)=="number" and h>0 then
        r20x_master_timer_save({id=h,enabled=true,at=util.timestamp(),hz=20})
        local rg=function_registry_load()
        for _,it in pairs(rg.items or {}) do
            if type(it)=="table" and it.enabled==true and it.loaded~=false and it.missing~=true then
                it.timer_registered=true
                it.timer_id=h
                it.registered_delay=0.05
                it.needs_reload=false
            end
        end
        function_registry_save(rg)
        return true,h
    end
    return false,"主计时器注册失败："..tostring(h)
end

-- 不再一个TXT注册一个0.05s timer。
function function_schedule_one(id)
    id=tonumber(id)
    local item,d=function_registry_get(id)
    if not item then return false,"文件编号不存在" end

    -- 清理这个文件旧时代的专属 timer
    local ts=function_timer_state_load()
    local old=tonumber(ts.items[tostring(id)])
    if old then pcall(util.cancel,old) end
    ts.items[tostring(id)]=nil
    function_timer_state_save(ts)

    item.timer_registered=false
    item.timer_id=nil
    function_registry_save(d)

    local ok,h=r20x_ensure_master_timer(false)
    if item.enabled==true and ok then
        local it,rd=function_registry_get(id)
        if it then
            it.timer_registered=true
            it.timer_id=tonumber(h)
            it.registered_delay=0.05
            it.needs_reload=false
            function_registry_save(rd)
        end
    end
    return ok,h
end

function function_register_timers()
    -- 清理全部旧“每文件一个timer”
    pcall(function_cancel_old_timers)
    pcall(function_scan_files,true)

    local d=function_registry_load()
    for _,x in ipairs(function_registry_sorted(d,false)) do
        if x.item and x.item.enabled==true and x.item.loaded~=false and not x.item.missing then
            pcall(function_compile_item,x.id)
        end
    end
    return r20x_ensure_master_timer(true)
end

-- ---------- 死亡检测：兼容(data)和(desc,data)两种回调 ----------
function r20x_event_payload(a,b)
    if type(b)=="table" then return b end
    if type(a)=="table" then
        if type(a.fields)=="table" then return a.fields end
        return a
    end
    return nil
end

function r20x_death_diag(kind,name)
    local d={}
    local ok,v=pcall(util.json_load,R20X_DEATH_DIAG_FILE)
    if ok and type(v)=="table" then d=v end
    d[kind]={
        at=util.timestamp(),
        name=tostring(name or ""),
    }
    d.last_kind=kind
    d.last_name=tostring(name or "")
    d.last_at=util.timestamp()
    pcall(util.json_write,R20X_DEATH_DIAG_FILE,d)
end

function final_death_text_handler(a,b)
    local data=r20x_event_payload(a,b)
    if type(data)~="table" then return end

    local msg=tostring(data.message or data.text or "")
    local victim=nil

    if msg:sub(1,6)=="death." then
        local p=data.parameters or data.params
        if type(p)=="table" and p[1]~=nil then
            victim=tostring(p[1])
        end
    end

    if not victim or victim=="" then
        local plain=msg
        pcall(function() plain=util.strip_color(msg) end)
        victim=plain:match("^(%S+)死了")
            or plain:match("^(%S+)死亡")
            or plain:match("^(%S+) died")
            or plain:match("^(%S+) was slain")
            or plain:match("^(%S+) was killed")
            or plain:match("^(%S+) was shot")
            or plain:match("^(%S+) drowned")
            or plain:match("^(%S+) fell from")
            or plain:match("^(%S+) burned to death")
            or plain:match("^(%S+) hit the ground")
            or plain:match("^(%S+) went up in flames")
            or plain:match("^(%S+) was blown up")
            or plain:match("^(%S+) starved to death")
    end

    if victim and victim~="" then
        victim=trim(tostring(victim))
        r20x_death_diag("Text",victim)
        pcall(ds_death_record,victim,"text-r20x")
    end
end

function final_death_location_handler(a,b)
    local data=r20x_event_payload(a,b)
    if type(data)~="table" then return end
    local tp=tonumber(data.type or data.location_type)
    if tp~=1 then return end
    local uid=data.entity_unique_id or data.entity_uniqueId or data.unique_id
    local nm=final_death_name_by_uid(uid)
    if nm and nm~="" then
        r20x_death_diag("PlayerLocation",nm)
        pcall(ds_death_record,nm,"location-r20x")
    end
end

function final_death_pyrpc_handler(a,b)
    local data=r20x_event_payload(a,b)
    if type(data)~="table" then return end
    local p=final_death_find_payload(data,0)
    if type(p)~="table" or p.die~=true then return end
    local pid=p.pid or p.id or p.uuid or p.entity_unique_id or p.entity_uniqueId
    local nm=final_death_name_by_uid(pid)
    if nm and nm~="" then
        r20x_death_diag("PyRpc",nm)
        pcall(ds_death_record,nm,"pyrpc-r20x")
    end
end

-- 独立于数据包的标签差集兜底：
-- @a 能看到连接玩家；@e[type=player] 只移除仍作为活实体存在的玩家。
function r20x_death_tag_probe()
    pcall(game.sendCommand,"tag @a add ds_death_probe")
    pcall(game.sendCommand,"tag @e[type=player] remove ds_death_probe")

    local now=tonumber(util.timestamp()) or 0
    local samples=ds_samples_load()
    for name,s in pairs(samples.samples or {}) do
        if type(s)=="table" and now-(tonumber(s.ts) or 0)<=30 then
            local safe=tostring(name):gsub('"','\\"')
            local ok,hit=pcall(game.isCmdSuccess,'testfor @a[name="'..safe..'",tag="ds_death_probe"]')
            if ok and hit==true then
                r20x_death_diag("TagDiff",name)
                pcall(ds_death_record,name,"tagdiff-r20x")
            end
        end
    end

    pcall(game.sendCommand,"tag @a remove ds_death_probe")
end

function r20x_register_death_events()
    pcall(events.subscribe,"Text","final_death_text_handler")
    pcall(events.subscribe,"PlayerLocation","final_death_location_handler")
    pcall(events.subscribe,"PyRpc","final_death_pyrpc_handler")
    return true
end

-- 在现有唯一1秒主心跳上补采样和标签差集，不新增死亡 timer。
R20X_PREV_V17=v17_event_tick
function v17_event_tick()
    local ret=true
    if type(R20X_PREV_V17)=="function" then
        local ok,v=pcall(R20X_PREV_V17)
        if ok then ret=v end
    end
    pcall(ds_death_sample_tick)
    pcall(r20x_death_tag_probe)
    return ret
end

R20X_PREV_CHAT=on_chat
function on_chat(playerName,msg)
    local low=lower(trim(tostring(msg or "")))
    if low==".死亡检测状态" or low==".死亡诊断" then
        local d={}
        local ok,v=pcall(util.json_load,R20X_DEATH_DIAG_FILE)
        if ok and type(v)=="table" then d=v end
        send(playerName,
            "§b死亡检测状态\n"..
            "§7最近信号：§f"..tostring(d.last_kind or "暂无")..
            "\n§7玩家：§f"..tostring(d.last_name or "暂无")..
            "\n§7时间戳：§f"..tostring(d.last_at or "暂无")..
            "\n§7检测：Text / PlayerLocation / PyRpc / TagDiff"
        )
        return true
    end
    if low==".function诊断" then
        local td=r20x_master_timer_load()
        local rg=function_registry_load()
        local enabled=0
        for _,it in pairs(rg.items or {}) do
            if type(it)=="table" and it.enabled==true and it.loaded~=false and it.missing~=true then
                enabled=enabled+1
            end
        end
        send(playerName,
            "§bFUNCTION诊断\n"..
            "§7运行TXT：§f"..tostring(enabled)..
            "\n§7主计时器：§f"..tostring(td.id or "未注册")..
            "\n§7频率：§f20Hz"..
            "\n§7模式：§f单主计时器 + 防重入 + 返回地面空闲跳过"
        )
        return true
    end
    return R20X_PREV_CHAT(playerName,msg)
end

R20X_PREV_INIT=on_init
function on_init()
    local ret=nil
    if type(R20X_PREV_INIT)=="function" then
        local ok,v=pcall(R20X_PREV_INIT)
        if ok then ret=v end
    end

    pcall(r20x_register_death_events)
    pcall(ds_death_sample_tick)

    -- 导入/重载后把旧专属FUNCTION timers合并成一个主timer。
    pcall(function_register_timers)

    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",
        FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    return ret
end

-- R21A: fresh-load FUNCTION timer disabled; death events are registered by normal init.

-- ============================================================
-- R20Y：雪球菜单 TXT 原文基准恢复
-- 只负责把本版本确认过的 TXT 一次性落到数据目录。
-- 不在 Lua 内复制命令正文。
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R20Y"
FINAL_PATCH_TAG = "雪球命令链原文恢复"
R20Y_SNOW_MIGRATION = game.dataDir().."/r20y_snow_chain_restored.ok"

function r20y_restore_snow_txt_once()
    local ok,mark=pcall(util.read_file,R20Y_SNOW_MIGRATION)
    if ok and tostring(mark or "")=="R20Y" then return true end

    local raw,src=r20w_resource_from_docs("command_txt/雪球菜单_综合功能.txt")
    if type(raw)~="string" or trim(raw)=="" then
        return false,"找不到R20Y雪球原文资源"
    end

    local dst=game.dataDir().."/command_txt/雪球菜单_综合功能.txt"
    local wok,werr=pcall(util.write_file,dst,raw)
    if not wok then return false,tostring(werr) end

    pcall(util.write_file,R20Y_SNOW_MIGRATION,"R20Y")
    return true,dst
end

R20Y_PREV_INIT=on_init
function on_init()
    local ret=nil
    if type(R20Y_PREV_INIT)=="function" then
        local ok,v=pcall(R20Y_PREV_INIT)
        if ok then ret=v end
    end
    pcall(r20y_restore_snow_txt_once)
    pcall(function_scan_files,true)
    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",
        FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    return ret
end

-- ============================================================
-- 1.0.73 R21A CORE
-- FUNCTION 高频调度完全移交 tiny main.lua。
-- ============================================================
FINAL_PATCH_VERSION = "1.0.73-R21A"
FINAL_PATCH_TAG = "轻量20Hz执行核_原文命令链"
FUNCTION_ENGINE_VERSION = "R21A_TINY_BOOTSTRAP_20HZ"

function r21a_cancel_legacy_function_timers()
    -- R14/R20M era per-file timers
    local ok,ts=pcall(function_timer_state_load)
    if ok and type(ts)=="table" then
        for _,h in pairs(ts.items or {}) do
            if tonumber(h) then pcall(util.cancel,tonumber(h)) end
        end
    end
    pcall(function_timer_state_save,{items={}})

    -- Legacy ids file
    local ok2,legacy=pcall(util.json_load,FUNCTION_TIMER_FILE)
    if ok2 and type(legacy)=="table" then
        for _,h in ipairs(legacy.ids or {}) do
            if tonumber(h) then pcall(util.cancel,tonumber(h)) end
        end
    end
    pcall(util.json_write,FUNCTION_TIMER_FILE,{
        ids={},count=0,at=util.timestamp(),version=FINAL_PATCH_VERSION,
        note="R21A: 20Hz由tiny main.lua统一调度"
    })

    -- R20X master timer
    if type(r20x_cancel_master_timer)=="function" then
        pcall(r20x_cancel_master_timer)
    end
end

function function_register_timers()
    pcall(r21a_cancel_legacy_function_timers)
    return 0
end

function function_schedule_one(id)
    id=tonumber(id)
    local item,d=function_registry_get(id)
    if not item then return false,"文件编号不存在" end

    if item.enabled==true and item.loaded~=false and item.missing~=true then
        local okc,ec=function_compile_item(id)
        if not okc then
            item,d=function_registry_get(id)
            if item then
                item.enabled=false
                item.timer_registered=false
                item.last_error=tostring(ec)
                function_registry_save(d)
            end
            return false,ec
        end
    end

    item,d=function_registry_get(id)
    if item then
        item.timer_registered=(item.enabled==true)
        item.timer_id=nil
        item.registered_delay=0.05
        item.needs_reload=false
        function_registry_save(d)
    end
    return true,"R21A轻量20Hz执行核"
end

function r21a_prepare_function_registry()
    pcall(r20y_restore_snow_txt_once)
    pcall(function_scan_files,true)

    local d=function_registry_load()
    local n=0
    for _,x in ipairs(function_registry_sorted(d,false)) do
        local it=x.item
        if type(it)=="table" and it.enabled==true and it.loaded~=false and it.missing~=true then
            -- 强制按当前真实TXT重编译，绝不沿用上个版本 compiled_nodes。
            it.compiled_nodes=nil
            it.compiled_at=nil
            function_registry_save(d)
            local okc=function_compile_item(x.id)
            if okc then n=n+1 end
            d=function_registry_load()
        end
    end
    pcall(r21a_cancel_legacy_function_timers)
    return n
end

R21A_PREV_INIT=on_init
function on_init()
    local ret=nil
    if type(R21A_PREV_INIT)=="function" then
        local ok,v=pcall(R21A_PREV_INIT)
        if ok then ret=v end
    end
    pcall(r21a_prepare_function_registry)
    pcall(r20x_register_death_events)
    pcall(util.write_file,game.dataDir().."/PATCH_VERSION.txt",
        FINAL_PATCH_VERSION.."\n"..FINAL_PATCH_TAG.."\n")
    return ret
end
